          DialogueId = 6100510,
          GUID = "0F45A0EC",
          RougeTalkActorType = 3
        },
        [6100601] = {
          ContentJP = "小さな影がどんどん近付いてくる。\n見えてきたのは、背の低い少女。",
          DialogueId = 6100601,
          GUID = "0F45AFDA",
          NextDialogue = 6100602,
          RougeTalkActorType = 3
        },
        [6100602] = {
          ContentJP = "「あの…私も…火に…あたらせて？」\nその声は震えている。裾から滴り落ちる水が、ぽたぽたと地面に染み込んでいく──ワンピースはずぶ濡れだった。",
          DialogueId = 6100602,
          GUID = "0F45B004",
          NextDialogue = 6100603,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100603] = {
          ContentJP = "「お母さんと…はぐれちゃって…もう…すこし…だけ…」",
          DialogueId = 6100603,
          GUID = "0F45B02E",
          NextOptions = {
            [1] = 6100604,
            [2] = 6100613
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100604] = {
          ContentJP = "受け入れる。",
          DialogueId = 6100604,
          GUID = "0F45B058",
          IsKeyOption = true,
          NextDialogue = 6100605,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100605] = {
          ContentJP = "「ありがとう。」\n彼女は震えながら、感謝の言葉を必死に歯の隙間から絞りだす。",
          DialogueId = 6100605,
          GUID = "0F45B082",
          NextDialogue = 6100606,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100606] = {
          ContentJP = "「彼女がここにいる理由を尋ねる」",
          DialogueId = 6100606,
          GUID = "0F45B0AC",
          NextDialogue = 6100607,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100607] = {
          ContentJP = "「ど…どうして…ここに？ …ああ…思い出した…」\n「お父さんと…お母さんは…ヒュペリア人…私たち…そこから逃げて…エリュシオンへ行くつもりだったけど…」\n「海で船が…黒い渦に…呑み込まれて…」",
          DialogueId = 6100607,
          GUID = "0F45B0D6",
          NextDialogue = 6100608,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100608] = {
          ContentJP = "黒い渦──心当たりがあった。黒潮のことだ。形あるものをすべて呑み込んだ、飢える深淵。",
          DialogueId = 6100608,
          GUID = "0F45B100",
          NextDialogue = 6100609,
          RougeTalkActorType = 3
        },
        [6100609] = {
          ContentJP = "危険を冒してもエリュシオンへ向かった理由を尋ねる。",
          DialogueId = 6100609,
          GUID = "0F45B12A",
          NextDialogue = 6100610,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100610] = {
          ContentJP = "「私たちは…『悪魔の子』だって…お母さんが。」\n「たとえ深淵に落ちるような災いが起こっても…ヒュペリアに残るよりはまし…」",
          DialogueId = 6100610,
          GUID = "0F45B154",
          NextDialogue = 6100611,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100611] = {
          ContentJP = "「ありがとう…火を貸してくれて、それから…私が生きていないことを教えてくれて。」",
          DialogueId = 6100611,
          GUID = "0F45B17E",
          NextDialogue = 6100612,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100612] = {
          ContentJP = "彼女は消えた。まるで最初から誰もいなかったかのように、隣でパチパチと焚火が音を立てていた。",
          DialogueId = 6100612,
          GUID = "0F45B1A8",
          RougeTalkActorType = 3
        },
        [6100613] = {
          ContentJP = "断る。",
          DialogueId = 6100613,
          GUID = "0F45B1D2",
          IsKeyOption = true,
          NextDialogue = 6100614,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100614] = {
          ContentJP = "「ご…こめんなさい…お邪魔よね。」",
          DialogueId = 6100614,
          GUID = "0F45B1FC",
          NextDialogue = 6100615,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room306_Char01"
        },
        [6100615] = {
          ContentJP = "少女は震えながら立ち去った。まるで最初から誰もいなかったかのように、隣でパチパチと焚火が音を立てていた。",
          DialogueId = 6100615,
          GUID = "0F45B226",
          RougeTalkActorType = 3
        },
        [6100701] = {
          ContentJP = "「こんにちは！」",
          DialogueId = 6100701,
          GUID = "0F45C042",
          NextDialogue = 6100702,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100702] = {
          ContentJP = "荷物を背負った爽やかな青年が、焚火に歩み寄り、元気に挨拶をした。",
          DialogueId = 6100702,
          GUID = "0F45C06C",
          NextDialogue = 6100703,
          RougeTalkActorType = 3
        },
        [6100703] = {
          ContentJP = "「ちょっと失礼だけど──君、まだ生きてるよね？」",
          DialogueId = 6100703,
          GUID = "0F45C096",
          NextOptions = {
            [1] = 6100704,
            [2] = 6100711
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100704] = {
          ContentJP = "うなずく。",
          DialogueId = 6100704,
          GUID = "0F45C0C0",
          IsKeyOption = true,
          NextDialogue = 6100705,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100705] = {
          ContentJP = "「まさかこんなところで生きてる人に会えるなんて。どうやら、君は僕と同じ、百人に1人の幸運の持ち主なんだね！」",
          DialogueId = 6100705,
          GUID = "0F45C0EA",
          NextDialogue = 6100706,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100706] = {
          ContentJP = "「十六歳の時、父親と一緒に作った歌が神への冒涜だと言われて、聖裁所に裁かれたんだ。」\n「僕も父親みたいに処刑されるはずだったけど、処刑の日に死刑執行人が雷に打たれたおかげで、赦免された。」",
          DialogueId = 6100706,
          GUID = "0F45C114",
          NextDialogue = 6100707,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100707] = {
          ContentJP = "「二十歳の時は商人の一団に加わってたんだけど、北の森で盗賊に襲われて、洞窟に縛りつけられた。」\n「仲間みたいに餓死するかと思ったけど、7日目の朝、豚が僕を起こしてくれた。近くにいた少女が食べ物をくれたんだ。天使に出会った気分だったね。」",
          DialogueId = 6100707,
          GUID = "0F45C13E",
          NextDialogue = 6100708,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100708] = {
          ContentJP = "「その後、商人として騎士団について深淵に来た。騎士たちの灯りは一つずつ消え、ある騎士は転んだ拍子に自分の剣に喉を刺し貫かれた。生き残ったのは僕だけだ。」\n「その時から、僕は運命の女神に愛されてるんだって信じてる。彼女から授かった幸運と幸福に恵まれてるってね。」",
          DialogueId = 6100708,
          GUID = "0F45C168",
          NextDialogue = 6100709,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100709] = {
          ContentJP = "「彼女が僕をここまで導いたってことは、きっとこの奥に唯一無二の至宝が待っているに違いない。こうしちゃいられない、探しに行かなくちゃ。」\n彼は重そうな荷物を背負い直し、立ち去ろうとしている。",
          DialogueId = 6100709,
          GUID = "0F45C192",
          NextDialogue = 6100710,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100710] = {
          ContentJP = "「そうだ、友よ！君も運命に生かされたってことは、君にもきっと、君だけの幸運が待ってるはずだよ！」\n彼は拳を握りしめ、高らかに笑った。\n「僕たちに幸運あれ！」",
          DialogueId = 6100710,
          GUID = "0F45C1BC",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100711] = {
          ContentJP = "倒れて死んだふりをする。",
          DialogueId = 6100711,
          GUID = "0F45C1E6",
          IsKeyOption = true,
          NextDialogue = 6100712,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100712] = {
          ContentJP = "「気絶してるのか？」\n彼はしゃがみ込み、あなたの息を確認しようとした。\n「まさか、君もやつらと同じ亡霊なのか？」",
          DialogueId = 6100712,
          GUID = "0F45C210",
          NextDialogue = 6100713,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100713] = {
          ContentJP = "あなたは無言のままだ。\n彼は荷物を下ろし、水と食べ物を取り出した。",
          DialogueId = 6100713,
          GUID = "0F45C23A",
          NextDialogue = 6100714,
          RougeTalkActorType = 3
        },
        [6100714] = {
          ContentJP = "「かわいそうな友よ、これを置いておくよ！聖塔に最初の日差しが差す頃になれば、きっと君も目を覚まして、元通り健康になれるだろう。」",
          DialogueId = 6100714,
          GUID = "0F45C264",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room307_Char01"
        },
        [6100801] = {
          ContentJP = "闇の中に、双生の赤い花が咲き、微かに光を放っていた。\nランタンを掲げると、灯りは白みがかった金髪の束と、白い脊椎の数節を照らし出した。これは人型の<Default note=\"text:エジュウ\">穢獣</>なのか、それとも<Default note=\"text:エジュウ\">穢獣</>へと変わりゆく人間なのか？\n警戒して武器を握り締めるが、それは襲いかかってくる様子もなく、漆黒の背景に埋もれた赤い瞳でただ静かにあなたを見つめている。",
          DialogueId = 6100801,
          GUID = "0F45D0AA",
          NextDialogue = 6100802,
          RougeTalkActorType = 3
        },
        [6100802] = {
          ContentJP = "突然、その喉から、何か壊れた音が漏れた。硬い岩同士が擦れ合うような噪音でありながら、どこかリズムを伴っている。なぜか分からないが、あなたはその意味を理解していた――",
          DialogueId = 6100802,
          GUID = "0F45D0D4",
          NextDialogue = 6100803,
          RougeTalkActorType = 3
        },
        [6100803] = {
          ContentJP = "「もうこれ以上近づかないで、ランタンの旅人さん。どうか私に教えください。この灯りに映る私の姿は、まだ美しいでしょうか？」",
          DialogueId = 6100803,
          GUID = "0F45D0FE",
          NextDialogue = 6100804,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100804] = {
          ContentJP = "「私は髪を柔らかく光るように梳かし、美しいお下げに編みました。」それは後頭部に開いた皮膚を撫でながら言った。\n「私はスカートの折り目にきちんとアイロンかけ、貴く輝く宝石で飾りました。」それは深く体に食い込んだ結晶を撫でながら言った。\n「私は愛する人が贈ったネックレスを身に付け、彼の熱い思いに耽りました。」それは首筋に伸びた骨節を撫でながら言った。",
          DialogueId = 6100804,
          GUID = "0F45D128",
          NextOptions = {
            [1] = 6100805,
            [2] = 6100808
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100805] = {
          ContentJP = "「ええ、あなたは美しい。」",
          DialogueId = 6100805,
          GUID = "0F45D152",
          IsKeyOption = true,
          NextDialogue = 6100806,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100806] = {
          ContentJP = "その赤い瞳は風に揺れる花弁のように微かに震えた。",
          DialogueId = 6100806,
          GUID = "0F45D17C",
          NextDialogue = 6100807,
          RougeTalkActorType = 3
        },
        [6100807] = {
          ContentJP = "「ありがとう、優しい旅人さん。これは私からの謝礼です。」\n「もし私の愛する人にお会いになったら、ずっと彼を愛していると伝えてください。」",
          DialogueId = 6100807,
          GUID = "0F45D1A6",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100808] = {
          ContentJP = "「お前は恐ろしい怪物だ。」",
          DialogueId = 6100808,
          GUID = "0F45D1D0",
          IsKeyOption = true,
          NextDialogue = 6100809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100809] = {
          ContentJP = "その赤い瞳は獰猛たる爪に覆われる。",
          DialogueId = 6100809,
          GUID = "0F45D1FA",
          NextDialogue = 6100810,
          RougeTalkActorType = 3
        },
        [6100810] = {
          ContentJP = "「あぁ――いや！ 愛する人にこんな醜い姿を見せたくない。」\n「慈悲深き旅人さんよ、どうか私を楽にさせて。」",
          DialogueId = 6100810,
          GUID = "0F45D224",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room308_Char01"
        },
        [6100901] = {
          ContentJP = "「ごきげんよう、見知らぬ旅人さん。」",
          DialogueId = 6100901,
          GUID = "0F45E112",
          NextDialogue = 6100902,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100902] = {
          ContentJP = "派手な服を身に纏った青年が、揺らめく焚火の明かりの前で足を止め、優雅にお辞儀をした。",
          DialogueId = 6100902,
          GUID = "0F45E13C",
          NextDialogue = 6100903,
          RougeTalkActorType = 3
        },
        [6100903] = {
          ContentJP = "「私は赤い瞳をした淑女を探しております。彼女の姿を見かけませんでしたか？」",
          DialogueId = 6100903,
          GUID = "0F45E166",
          NextDialogue = 6100904,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100904] = {
          ContentJP = "「彼女はこの世で最も美しい歌声の持ち主で、夜鶯さえも彼女には劣ります。」\n「柔らかな金色の髪は、春に咲くマリーゴールドのように輝いています。」\n「気品のあるワンピースを纏い、スカートには星のようにきらめく宝石が縫い込まれています。」\n「そして私が贈ったネックレスを身につけています。真紅の水晶は、彼女が私を見つめる時の瞳のように神秘的な輝きを放っています。」",
          DialogueId = 6100904,
          GUID = "0F45E190",
          NextDialogue = 6100905,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100905] = {
          ContentJP = "そんな女性は見たことがない。",
          DialogueId = 6100905,
          GUID = "0F45E1BA",
          NextDialogue = 6100906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100906] = {
          ContentJP = "「そうですか…」\n彼は一瞬項垂れたが、すぐに元の表情に戻った。\n「構いません、私はこれからも探し続けます。」",
          DialogueId = 6100906,
          GUID = "0F45E1E4",
          NextDialogue = 6100907,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100907] = {
          ContentJP = "青年は焚火の傍に腰を下ろした。明るい炎が彼の澄んだ瞳に映り込んだ。",
          DialogueId = 6100907,
          GUID = "0F45E20E",
          NextDialogue = 6100908,
          RougeTalkActorType = 3
        },
        [6100908] = {
          ContentJP = "「私たちはすでに婚約しており、彼女が成人したら結婚式を挙げる予定でした。しかし彼女は神の恩寵を受け、額の聖痕が次第に明らかになり、十四歳の前夜に使者に連れ去られたのです。」\n「彼女は別れの手紙を残し、私に他の女性を探すよう勧めました。ですが、私は既に誓いを立てています。この生涯は彼女と共に過ごしたい。」\n「彼女を見つけたら、絶対に連れ帰ります。満月の神は人々に愛の美しさを謳うよう教えられた方です。きっと私たちを祝福してくださるでしょう。」",
          DialogueId = 6100908,
          GUID = "0F45E238",
          NextOptions = {
            [1] = 6100909,
            [2] = 6100911
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100909] = {
          ContentJP = "恋人を見つけられるよう祈る。",
          DialogueId = 6100909,
          GUID = "0F45E262",
          IsKeyOption = true,
          NextDialogue = 6100910,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100910] = {
          ContentJP = "「感謝します、優しい旅人さん。」\n「このささやかな贈り物を受け取ってください。あなたも望みが叶いますように。」",
          DialogueId = 6100910,
          GUID = "0F45E28C",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6100911] = {
          ContentJP = "「もし神が許さなかったら？」",
          DialogueId = 6100911,
          GUID = "0F45E2B6",
          IsKeyOption = true,
          NextDialogue = 6100912,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6100912] = {
          ContentJP = "彼はあなたに小さく微笑んだ。\n「ならば、この身を聖なる湖に捧げましょう。そうすれば、私の魂は永遠に彼女と共にあることができます。」",
          DialogueId = 6100912,
          GUID = "0F45E2E0",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room309_Char01"
        },
        [6101001] = {
          ContentJP = "焚火の傍に女の姿が浮かび上がった。彼女は左手を燃え盛る焚火に差し入れ、煤を指に取り、地面にあなたが読めない文字を書きつけていく。",
          DialogueId = 6101001,
          GUID = "0F45F17A",
          NextDialogue = 6101002,
          RougeTalkActorType = 3
        },
        [6101002] = {
          ContentJP = "「ああ――時に抗う旅人よ、君は絶望と共にあり、死は影のごとく付き従う。」\n彼女はそう囁くように詠んだ。",
          DialogueId = 6101002,
          GUID = "0F45F1A4",
          NextOptions = {
            [1] = 6101003,
            [2] = 6101005
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101003] = {
          ContentJP = "何をしているのかと尋ねる",
          DialogueId = 6101003,
          GUID = "0F45F1CE",
          IsKeyOption = true,
          NextDialogue = 6101004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101004] = {
          ContentJP = "「おお、親愛なる友よ。ご覧の通り、私は詩人だ。」\n「今まさに、私の101首目の作品を創作中さ。そう、あなたに捧げる詩だ！」",
          DialogueId = 6101004,
          GUID = "0F45F1F8",
          NextDialogue = 6101008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101005] = {
          ContentJP = "「火が熱くないのか？」",
          DialogueId = 6101005,
          GUID = "0F45F222",
          IsKeyOption = true,
          NextDialogue = 6101006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101006] = {
          ContentJP = "女はくすくすと笑った。",
          DialogueId = 6101006,
          GUID = "0F45F24C",
          NextDialogue = 6101007,
          RougeTalkActorType = 3
        },
        [6101007] = {
          ContentJP = "「親愛なる友よ、これを見て。」\n彼女は掌をあなたの目の前に広げた。白い肌には傷1つない。\n「あなたのように賢明な旅人ならとっくにお気づきでしょう。これは本物の炎ではなく、私も本物の人間ではない。」",
          DialogueId = 6101007,
          GUID = "0F45F276",
          NextDialogue = 6101008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101008] = {
          ContentJP = "詩人は再び焚火に手を伸ばし、炎を優雅に指先でかき混ぜた。そのしなやかな指の動きは、まるで踊り子の足踏みのようだった。",
          DialogueId = 6101008,
          GUID = "0F45F2A0",
          NextDialogue = 6101009,
          RougeTalkActorType = 3
        },
        [6101009] = {
          ContentJP = "「ここは実に素敵な場所だよね？」\n「私はついに肉体の苦痛から解放され、つまらないことに創作を邪魔されることもなくなった。至上の自由と、永遠の時を手に入れた――！」\n「旅人よ、ここに足を止めてくれてありがとう。おかげで一片の閃きが得られた。ぜひ私の詩を受け取ってほしい。どうかあなたがこの無限の輪廻から解き放たれ、望みを叶えられますように。」",
          DialogueId = 6101009,
          GUID = "0F45F2CA",
          NextDialogue = 6101010,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room310_Char01"
        },
        [6101010] = {
          ContentJP = "詩人があなたに手を差し伸べると、舞い上がるすすが嵐のようにあなたの視界を覆い尽くした。\nすすが散った時、詩人の姿はどこにも見当たらなかった。",
          DialogueId = 6101010,
          GUID = "0F45F2F4",
          RougeTalkActorType = 3
        },
        [6101101] = {
          ContentJP = "「こんにちは。どうか、この火を分けてください。」",
          DialogueId = 6101101,
          GUID = "0F4601E2",
          NextDialogue = 6101102,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101102] = {
          ContentJP = "少年はわざとらしい格式ばった歩き方で、ゆっくりと焚火の傍に腰を下ろした。\n彼は大きすぎる礼服を纏い、痩せた小さな体が一層みすぼらしく見えた。火の光を借りて薄い本を捧げ持ち、本を読み始めるその仕草は、妙に気取っているように見えた。",
          DialogueId = 6101102,
          GUID = "0F46020C",
          NextDialogue = 6101103,
          RougeTalkActorType = 3
        },
        [6101103] = {
          ContentJP = "「炎の神よ、我らに知恵を授けたまえ…水の神よ、我らに豊穣を授けたまえ…」",
          DialogueId = 6101103,
          GUID = "0F460236",
          NextOptions = {
            [1] = 6101104
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101104] = {
          ContentJP = "何を読んでいる？",
          DialogueId = 6101104,
          GUID = "0F460260",
          NextDialogue = 6101105,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101105] = {
          ContentJP = "「ああ、これは兄さんたちがくれた本だ。」彼は照れくさそうに頭を掻いた。「神様にお会いする前にもっと賢くならなきゃいけないんだ。」\n「僕は小さい頃から家族で一番頭の悪い子だった。兄さんたちはみんな僕よりずっと優秀なのに、どういうわけか神様に選ばれたのは僕だった。みんなおかしいって言ってる。」\n「兄さんたちがこの聖歌集をくれて、九神に拝謁する前にちゃんと覚えて、家族の恥にならないようにしろって言ったんだ。」",
          DialogueId = 6101105,
          GUID = "0F46028A",
          NextDialogue = 6101106,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101106] = {
          ContentJP = "少年は体をずらし、あなたに近づくと、手に持った本を差し出しながら誘うような視線を投げかけた。",
          DialogueId = 6101106,
          GUID = "0F4602B4",
          NextDialogue = 6101107,
          RougeTalkActorType = 3
        },
        [6101107] = {
          ContentJP = "「一緒に見ない？」",
          DialogueId = 6101107,
          GUID = "0F4602DE",
          NextOptions = {
            [1] = 6101108,
            [2] = 6101112
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101108] = {
          ContentJP = "一緒に本を見る。",
          DialogueId = 6101108,
          GUID = "0F460308",
          IsKeyOption = true,
          NextDialogue = 6101109,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101109] = {
          ContentJP = "あなたは誘いに乗り、視線を本に向けた。驚いたことに、そこには真っ黒な筆跡で、想像もつかない悪意に満ちた卑俗な言葉がびっしりと書き込まれていた。\n次の瞬間、文字が黒い棘と化して紙面から飛び出し、獲物を狙う毒蛇のようにあなたの体に絡みついた。視界はどんどん暗く、ぼやけていく。\n本能的に、あなたは体を反らせて視線を本から引き剥がした。",
          DialogueId = 6101109,
          GUID = "0F460332",
          NextDialogue = 6101110,
          RougeTalkActorType = 3
        },
        [6101110] = {
          ContentJP = "「え？ どうしたの？ 本に何か怖いものでも書いてあった？」\n彼は純粋な眼差しで、困惑しながらあなたを見つめた。",
          DialogueId = 6101110,
          GUID = "0F46035C",
          NextDialogue = 6101111,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101111] = {
          ContentJP = "あなたは唇を開いたが、声が出ない。\n黒い棘が少年を包み、吞み込んでいく。少年も、本も、棘も、やがて全てが消え去った。",
          DialogueId = 6101111,
          GUID = "0F460386",
          RougeTalkActorType = 3
        },
        [6101112] = {
          ContentJP = "一緒に本を読むのを断る",
          DialogueId = 6101112,
          GUID = "0F4603B0",
          IsKeyOption = true,
          NextDialogue = 6101113,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101113] = {
          ContentJP = "ここで勉強するつもりはなかったが。",
          DialogueId = 6101113,
          GUID = "0F4603DA",
          NextDialogue = 6101114,
          RougeTalkActorType = 3
        },
        [6101114] = {
          ContentJP = "「そっか……それじゃ、僕一人で読む。」\n彼は本を膝の上に戻した。",
          DialogueId = 6101114,
          GUID = "0F460404",
          NextDialogue = 6101115,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room311_Char01"
        },
        [6101115] = {
          ContentJP = "突然、ページの間から無数の黒い棘が蠢き出た。\n驚く間もなく、黒い棘が少年を包み、吞み込んでいく。少年も、本も、棘も、やがて全てが消え去った。",
          DialogueId = 6101115,
          GUID = "0F46042E",
          RougeTalkActorType = 3
        },
        [6101201] = {
          ContentJP = "一人の中年女性が焚火の前に深刻な面持ちで腰を下ろした。炎の光は彼女の陰った瞳を照らさなかった。",
          DialogueId = 6101201,
          GUID = "0F46124A",
          NextDialogue = 6101202,
          RougeTalkActorType = 3
        },
        [6101202] = {
          ContentJP = "「こんにちは、見知らぬ方よ。失礼ながらお聞きしたいのですが、ここはどこなのでしょうか？」",
          DialogueId = 6101202,
          GUID = "0F461274",
          NextDialogue = 6101203,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101203] = {
          ContentJP = "答える。",
          DialogueId = 6101203,
          GUID = "0F46129E",
          NextDialogue = 6101204,
          RougeTalkActorType = 3
        },
        [6101204] = {
          ContentJP = "「聖湖…？深淵…？」彼女の声は混乱と困惑に満ちていた「でも、私はそういった言葉に全く覚えがなくて…」\n彼女は自分の皺だらけの手のひらを見つめた。「私は、どうしてここに来たのか忘れてしまったようです。」",
          DialogueId = 6101204,
          GUID = "0F4612C8",
          NextOptions = {
            [1] = 6101205,
            [2] = 6101207
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101205] = {
          ContentJP = "彼女に聖湖の歴史を教える。",
          DialogueId = 6101205,
          GUID = "0F4612F2",
          IsKeyOption = true,
          NextDialogue = 6101206,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101206] = {
          ContentJP = "「体に聖痕が現れた人は…ここに連れてこられる…？」\n「ああ…思い出しました。私の子供がここにいるはずです。彼女の目元に、まるで羽ばたこうとする蝶のような聖痕が現れたのです。」",
          DialogueId = 6101206,
          GUID = "0F46131C",
          NextDialogue = 6101210,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101207] = {
          ContentJP = "自分の持ち物を調べるよう勧める。",
          DialogueId = 6101207,
          GUID = "0F461346",
          IsKeyOption = true,
          NextDialogue = 6101208,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101208] = {
          ContentJP = "「あなたの言う通りですね。」\n彼女はポケットに手を入れ、銀のブローチを取り出した。",
          DialogueId = 6101208,
          GUID = "0F461370",
          NextDialogue = 6101209,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101209] = {
          ContentJP = "「ああ…思い出しました。」彼女は袖でブローチを丁寧に拭く。「これはあの子に贈るはずのプレゼントでした。」",
          DialogueId = 6101209,
          GUID = "0F46139A",
          NextDialogue = 6101210,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101210] = {
          ContentJP = "女は顔を上げた。今、炎の光がはっきりと彼女の瞳に映っている。",
          DialogueId = 6101210,
          GUID = "0F4613C4",
          NextDialogue = 6101211,
          RougeTalkActorType = 3
        },
        [6101211] = {
          ContentJP = "「私は子供を探しに来たのです。」\n「私が留守の間に、眠っている彼女を連れ去られました。あの子は小さい頃から人見知りが激しくて、目を覚ました時に知らない人ばかりだったらきっと怖がるはず。」\n「彼女のそばにいなければ…そう、私は彼女を探しに来たのです。」",
          DialogueId = 6101211,
          GUID = "0F4613EE",
          NextDialogue = 6101212,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101212] = {
          ContentJP = "「彼女がいなくなってからどれくらい経つか？」",
          DialogueId = 6101212,
          GUID = "0F461418",
          NextDialogue = 6101213,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101213] = {
          ContentJP = "「十日前…いや、十か月…いえ、十年…ああ…忘れてしまいました。」",
          DialogueId = 6101213,
          GUID = "0F461442",
          NextDialogue = 6101214,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room312_Char01"
        },
        [6101214] = {
          ContentJP = "女は黙り込んだ。彼女は異常な放心状態に陥り、全身が静止し、呼吸さえも止まったように見えた。\n何を言おうと、彼女はもう何の反応も示してくれなかった。",
          DialogueId = 6101214,
          GUID = "0F46146C",
          RougeTalkActorType = 3
        },
        [6101301] = {
          ContentJP = "「ボッ──」\n突然、目の前の焚火が勢いを増した。\n金髪の少女がスカートに金色の小石を抱え、一つ一つ火の中に投げ入れているのに気づく。",
          DialogueId = 6101301,
          GUID = "0F4622B2",
          NextDialogue = 6101302,
          RougeTalkActorType = 3
        },
        [6101302] = {
          ContentJP = "火の勢いは益々強くなり、まるで最初の春を迎えた植物のように勢い良く、無限に枝を伸ばし始めた。",
          DialogueId = 6101302,
          GUID = "0F4622DC",
          NextOptions = {
            [1] = 6101303,
            [2] = 6101305
          },
          RougeTalkActorType = 3
        },
        [6101303] = {
          ContentJP = "炎の美しさを褒める",
          DialogueId = 6101303,
          GUID = "0F462306",
          IsKeyOption = true,
          NextDialogue = 6101304,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101304] = {
          ContentJP = "「ええ！」彼女は炎のように熱烈な声で答えた。「同じ考えの人がいて嬉しいな。」",
          DialogueId = 6101304,
          GUID = "0F462330",
          NextDialogue = 6101307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101305] = {
          ContentJP = "石の由来を尋ねる",
          DialogueId = 6101305,
          GUID = "0F46235A",
          IsKeyOption = true,
          NextDialogue = 6101306,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101306] = {
          ContentJP = "「この辺で拾った石よ。」彼女は説明した。「多分、何かの炎魔法の結晶だと思う。」",
          DialogueId = 6101306,
          GUID = "0F462384",
          NextDialogue = 6101307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101307] = {
          ContentJP = "少女は石を投げ続ける。錯覚だろうか、炎は少女にますます近づき、金色の髪を優しく舐めるように揺らめいている。",
          DialogueId = 6101307,
          GUID = "0F4623AE",
          NextDialogue = 6101308,
          RougeTalkActorType = 3
        },
        [6101308] = {
          ContentJP = "「明日になれば、焚火は元通り。この小石もまた辺りに散らばる。」\n「だから毎日、石を拾っては投げ入れてるの。146個、多くも少なくもなく。」",
          DialogueId = 6101308,
          GUID = "0F4623D8",
          NextDialogue = 6101309,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101309] = {
          ContentJP = "「無意味じゃないか？」",
          DialogueId = 6101309,
          GUID = "0F462402",
          NextDialogue = 6101310,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101310] = {
          ContentJP = "少女は首を傾げ、瞬きながら無邪気な笑顔を見せる。",
          DialogueId = 6101310,
          GUID = "0F46242C",
          NextDialogue = 6101311,
          RougeTalkActorType = 3
        },
        [6101311] = {
          ContentJP = "「いいえ、私は火が好き。」彼女は言った。「燃える音も、踊る姿も好き。」\n「ここの空間は入り乱れている。目を閉じた時は焚火の傍にいても、次に目を開ければ湖の底にいたりする。」\n「でもこの小石は違う。環境がどう変わろうと、必ずまた現れる。明日も見つけられると思うと、安心して眠れるの。」",
          DialogueId = 6101311,
          GUID = "0F462456",
          NextDialogue = 6101312,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101312] = {
          ContentJP = "「私は確かなものが好き。」",
          DialogueId = 6101312,
          GUID = "0F462480",
          NextDialogue = 6101313,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room313_Char01"
        },
        [6101313] = {
          ContentJP = "少女は最後の石を投げた。\n炎の光に完全に包まれ、金髪と炎の境界はもはや見分けがつかない。",
          DialogueId = 6101313,
          GUID = "0F4624AA",
          RougeTalkActorType = 3
        },
        [6101401] = {
          ContentJP = "「う…ぐっ…」",
          DialogueId = 6101401,
          GUID = "0F46331A",
          NextDialogue = 6101402,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101402] = {
          ContentJP = "か細い呻き声が低い位置から聞こえる。焚火の傍に、飢えに苦しんでいるらしい痩せこけた男が倒れているのに気づいた。",
          DialogueId = 6101402,
          GUID = "0F463344",
          NextOptions = {
            [1] = 6101403,
            [2] = 6101409
          },
          RougeTalkActorType = 3
        },
        [6101403] = {
          ContentJP = "食べ物を分ける",
          DialogueId = 6101403,
          GUID = "0F46336E",
          IsKeyOption = true,
          NextDialogue = 6101404,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101404] = {
          ContentJP = "「…ありがとう、優しい子だね。だが、もう食べ物は必要ないんだ。」\n「黒潮に呑まれて、もう戻れない以上、どれだけ食べても無意味だ。」\n「君を見ていると、エリュシオンにいる女の子を思い出す…君と同じように優しい子だった。」",
          DialogueId = 6101404,
          GUID = "0F463398",
          NextDialogue = 6101405,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101405] = {
          ContentJP = "「金髪の女の子で、ピンクの巨大な豚に乗っていた。私が飢えで街を彷徨っていた時、パン一切れを差し出してくれた…」\n「だが当時の私は高慢で、礼賛会の施しなど受け入れられなかった。子供の善意と知りながら、大声で罵倒してしまった。」",
          DialogueId = 6101405,
          GUID = "0F4633C2",
          NextDialogue = 6101406,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101406] = {
          ContentJP = "「今となって、自分の人生を振り返って…彼女だけが真心から私に接してくれたのだと初めて気づいたよ。」\n「信仰や種族、出身…人はいつもそんなもので……自分を飾り立てる…だが、どんな肩書も、真の優しさが放つ輝きには勝てない…」",
          DialogueId = 6101406,
          GUID = "0F4633EC",
          NextDialogue = 6101407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101407] = {
          ContentJP = "「もし戻れたら…直接謝りたかった…ただ…もう…チャンスはないようだ…」",
          DialogueId = 6101407,
          GUID = "0F463416",
          NextDialogue = 6101408,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room314_Char01"
        },
        [6101408] = {
          ContentJP = "男の声は次第に小さくなり、瞬きをすると彼の姿は消えていた。\n空気中に、焼きたてのパンの香りが漂ってくる。",
          DialogueId = 6101408,
          GUID = "0F463440",
          RougeTalkActorType = 3
        },
        [6101409] = {
          ContentJP = "何もしない",
          DialogueId = 6101409,
          GUID = "0F46346A",
          IsKeyOption = true,
          NextDialogue = 6101410,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101410] = {
          ContentJP = "男は確かに可哀想に見えるが、自分の持ち物もほとんど残っていない。\nこの危険な深淵では、まず自分が生き延びることを最優先にすべきだ。",
          DialogueId = 6101410,
          GUID = "0F463494",
          RougeTalkActorType = 3
        },
        [6101501] = {
          ContentJP = "一筋の金色の光が空中に閃いた。一瞬、太陽が昇ったかと思ったが、よく見ればそれは全身が黄金色の小鳥だった。\n空から旋回しながら降りてきた鳥は、あなたの傍に優雅に着地し、羽を収めた。焚火に照らされた金色の羽はきらめき、貴族の令嬢たちが秘蔵する金細工よりも、精緻な輝きを放っている。",
          DialogueId = 6101501,
          GUID = "0F464382",
          NextOptions = {
            [1] = 6101502,
            [2] = 6101505,
            [3] = 6101509
          },
          RougeTalkActorType = 3
        },
        [6101502] = {
          ContentJP = "鳥に水をやる",
          DialogueId = 6101502,
          GUID = "0F4643AC",
          IsKeyOption = true,
          NextDialogue = 6101503,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101503] = {
          ContentJP = "手のひらに水を溜め、鳥に差し伸べる。",
          DialogueId = 6101503,
          GUID = "0F4643D6",
          NextDialogue = 6101504,
          RougeTalkActorType = 3
        },
        [6101504] = {
          ContentJP = "小鳥は首を傾げ、警戒しながらあなたを観察する。しばらくして、ためらいがちに金色の嘴を降ろし、手のひらの水を少しずつ飲み始めた。\n水を飲み終えると、羽を楽しげに振るわせて感謝の鳴き声をあげ、空へと舞い上がっていった。",
          DialogueId = 6101504,
          GUID = "0F464400",
          RougeTalkActorType = 3
        },
        [6101505] = {
          ContentJP = "鳥の尾羽を抜いてみる",
          DialogueId = 6101505,
          GUID = "0F46442A",
          IsKeyOption = true,
          NextDialogue = 6101506,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101506] = {
          ContentJP = "こっそり手を伸ばし、鳥が目を閉じて休んでいる隙に尾羽を一本抜き取る――羽の質感はまるで上質な黄金のようで、きっと高価に違いない。",
          DialogueId = 6101506,
          GUID = "0F464454",
          NextDialogue = 6101507,
          RougeTalkActorType = 3
        },
        [6101507] = {
          ContentJP = "鳥は怒りの鳴き声をあげ、羽ばたきながらあなたに襲いかかる。その嘴の一撃は、高熱を持つ溶けた金が手のひらに滴り落ちたかのような激痛で、鮮やかな赤い痕を残した。",
          DialogueId = 6101507,
          GUID = "0F46447E",
          NextDialogue = 6101508,
          RougeTalkActorType = 3
        },
        [6101508] = {
          ContentJP = "激痛が引いた頃には、鳥は遥か上空へ飛び去っていた。",
          DialogueId = 6101508,
          GUID = "0F4644A8",
          RougeTalkActorType = 3
        },
        [6101509] = {
          ContentJP = "鳥の頭の羽を抜いてみる",
          DialogueId = 6101509,
          GUID = "0F4644D2",
          IsKeyOption = true,
          NextDialogue = 6101510,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101510] = {
          ContentJP = "そっと手を伸ばし頭の羽を狙うが、力が入る前に鳥はあなたの動向に気づき、ぱっちりと目を見開いた。\n鳥は怒りの鳴き声をあげ、羽ばたきながらあなたに襲いかかる。その嘴の一撃は、高熱を持つ溶けた金が手のひらに滴り落ちたかのような激痛で、鮮やかな赤い痕を残した。",
          DialogueId = 6101510,
          GUID = "0F4644FC",
          NextDialogue = 6101511,
          RougeTalkActorType = 3
        },
        [6101511] = {
          ContentJP = "激痛が引いた頃には、鳥は遥か上空へ飛び去っていた。",
          DialogueId = 6101511,
          GUID = "0F464526",
          RougeTalkActorType = 3
        },
        [6101601] = {
          ContentJP = "腐敗した生臭い匂いが近くから漂ってきた。\n焚火の傍に小さな女の子が現れた。彼女の頬や腕には恐ろしい膿瘍が広がっており、焚火の明かりに照らされた瞳だけがかすかな生命の輝きを放っていなければ、目の前の存在が死体だと錯覚するところだった。",
          DialogueId = 6101601,
          GUID = "0F4653EA",
          NextOptions = {
            [1] = 6101602,
            [2] = 6101606,
            [3] = 6101612
          },
          RougeTalkActorType = 3
        },
        [6101602] = {
          ContentJP = "バッグから薬を取り出し、少女に手渡す。",
          DialogueId = 6101602,
          GUID = "0F465414",
          IsKeyOption = true,
          NextDialogue = 6101603,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101603] = {
          ContentJP = "「ありがとう…ございます…優しい旅人さん…」\nゆっくりと顔を上げる少女。その引きつった口元が、笑みなのか痛みによる痙攣なのか、判別できなかった。",
          DialogueId = 6101603,
          GUID = "0F46543E",
          NextDialogue = 6101604,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101604] = {
          ContentJP = "「でも…どうか…助けなくて結構です…」声をひそめて言った。「司祭様がおっしゃいました。私は呪われて、深淵病にかかっている。これは私の罪だと…」\n「心から懺悔すれば…きっと治る…それまでは、誰にも近づいてはいけないのです」",
          DialogueId = 6101604,
          GUID = "0F465468",
          NextDialogue = 6101605,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101605] = {
          ContentJP = "少女はよろめきながら立ち上がり、闇の中に消えていった。",
          DialogueId = 6101605,
          GUID = "0F465492",
          RougeTalkActorType = 3
        },
        [6101606] = {
          ContentJP = "少女の傷を治療しようとする",
          DialogueId = 6101606,
          GUID = "0F4654BC",
          IsKeyOption = true,
          NextDialogue = 6101607,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101607] = {
          ContentJP = "慎重に近づき、少女の傷の状態を調べようとする。",
          DialogueId = 6101607,
          GUID = "0F4654E6",
          NextDialogue = 6101608,
          RougeTalkActorType = 3
        },
        [6101608] = {
          ContentJP = "「げほっ…げほっ…！」\n激しい咳込みと共に、どす黒い血があなたの手にかかる。血は不気味な黒煙を立ち上らせた。",
          DialogueId = 6101608,
          GUID = "0F465510",
          NextDialogue = 6101609,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101609] = {
          ContentJP = "「ご…ごめんなさい…！」\nふらふらと立ち上がろうとして、またもや地面に倒れ込む。",
          DialogueId = 6101609,
          GUID = "0F46553A",
          NextDialogue = 6101610,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101610] = {
          ContentJP = "「司祭様がおっしゃいました。私は呪われて、深淵病にかかっている。これは私の罪だと…」\n「心から懺悔すれば…きっと治る…それまでは、誰にも近づいてはいけないのです」",
          DialogueId = 6101610,
          GUID = "0F465564",
          NextDialogue = 6101611,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101611] = {
          ContentJP = "少女は再び苦しそうに起き上がり、よろめきながら闇に消えた。",
          DialogueId = 6101611,
          GUID = "0F46558E",
          RougeTalkActorType = 3
        },
        [6101612] = {
          ContentJP = "距離を取る",
          DialogueId = 6101612,
          GUID = "0F4655B8",
          IsKeyOption = true,
          NextDialogue = 6101613,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101613] = {
          ContentJP = "直感が少女の病の危険性を告げていた。あなたは立ち上がり、距離を取った。",
          DialogueId = 6101613,
          GUID = "0F4655E2",
          NextDialogue = 6101614,
          RougeTalkActorType = 3
        },
        [6101614] = {
          ContentJP = "「すみません…驚かせてしまって…私…すぐに立ち去ります…」",
          DialogueId = 6101614,
          GUID = "0F46560C",
          NextDialogue = 6101615,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room316_Char01"
        },
        [6101615] = {
          ContentJP = "少女はよろめきながら立ち上がり、闇の中に消えていった。",
          DialogueId = 6101615,
          GUID = "0F465636",
          RougeTalkActorType = 3
        },
        [6101701] = {
          ContentJP = "あなたは焚火の傍に腰を下ろして休憩を取ることにし、手にしていたランタンを足元に置いた。\nその瞬間、地面が突然、水のような光を放ち始めた。反応する間もなく、ランタンは渦巻く水に吞み込まれてしまった。",
          DialogueId = 6101701,
          GUID = "0F466452",
          NextDialogue = 6101702,
          RougeTalkActorType = 3
        },
        [6101702] = {
          ContentJP = "滑稽な鳥頭の仮面をした人が水中から上半身を現し、頭を振ると、両手を広げた――水上に、形は同じだが材質の異なる三つのランタンが浮かび上がった。",
          DialogueId = 6101702,
          GUID = "0F46647C",
          NextDialogue = 6101703,
          RougeTalkActorType = 3
        }
      }
    end
  },
  {
    MinKey = 6101703,
    MaxKey = 6200220,
    Loader = function()
      return {
        [6101703] = {
          ContentJP = "「おお、親愛なる旅人よ！あなたが落としたのは、この黄金のランタンですか？この木製のランタンですか？それともこの普通のランタンですか？」",
          DialogueId = 6101703,
          GUID = "0F4664A6",
          NextOptions = {
            [1] = 6101704,
            [2] = 6101707,
            [3] = 6101710
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101704] = {
          ContentJP = "黄金のランタン。",
          DialogueId = 6101704,
          GUID = "0F4664D0",
          IsKeyOption = true,
          NextDialogue = 6101705,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101705] = {
          ContentJP = "「あははは！」彼は大げさに笑い、「素晴らしい、気に入ったぞ！良いものを見つけたら、手段を選ばず手に入れるべきだ！」\n「どうぞ持っていくといい！ピカピカ光る黄金が嫌いな奴なんていない――そうだろう？」",
          DialogueId = 6101705,
          GUID = "0F4664FA",
          NextDialogue = 6101706,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101706] = {
          ContentJP = "彼は水中に飛び込み、水面はすぐに消えた。\n足元にはランタンが元通りに置かれていたが、その周りには灰の残骸が散らばっていた。",
          DialogueId = 6101706,
          GUID = "0F466524",
          RougeTalkActorType = 3
        },
        [6101707] = {
          ContentJP = "木製のランタン。",
          DialogueId = 6101707,
          GUID = "0F46654E",
          IsKeyOption = true,
          NextDialogue = 6101708,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101708] = {
          ContentJP = "「ふむ？君…面白いね！」彼は首を傾げた。その黒い眼窩は底が見えない空洞のようだった。「木でランタンを作るなんて普通はあり得ない――だが、なぜできないと決めつける？ここは深淵だ、何だって不可能じゃない！」\n「親愛なる旅人に祝福を！君はきっと面白い旅を迎えるのだろう」",
          DialogueId = 6101708,
          GUID = "0F466578",
          NextDialogue = 6101709,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101709] = {
          ContentJP = "彼は水中に飛び込み、水面はすぐに消えた。\n足元にはランタンが元通りに置かれていたが、その横にレリックが一つ増えていた。",
          DialogueId = 6101709,
          GUID = "0F4665A2",
          RougeTalkActorType = 3
        },
        [6101710] = {
          ContentJP = "普通のランタン。",
          DialogueId = 6101710,
          GUID = "0F4665CC",
          IsKeyOption = true,
          NextDialogue = 6101711,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101711] = {
          ContentJP = "「あーあ、礼賛会の連中に洗脳されちゃったんだね」彼はしきりに嘆き、あなたの答えに不満そうだった、「正直すぎるってつまらないよ――他のタイプのランタンに変えてみたいとは思わないのかい？」",
          DialogueId = 6101711,
          GUID = "0F4665F6",
          NextDialogue = 6101712,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101712] = {
          ContentJP = "「まあいいさ」彼は首を振り、「正直は美德だ、そうだろ？物語通り、ちょっとしたご褒美をあげよう」",
          DialogueId = 6101712,
          GUID = "0F466620",
          NextDialogue = 6101713,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room317_Char01"
        },
        [6101713] = {
          ContentJP = "彼は水中に飛び込み、水面はすぐに消えた。\n足元にはランタンが元通りに置かれていたが、中の灯りは以前より明るく輝いていた。",
          DialogueId = 6101713,
          GUID = "0F46664A",
          RougeTalkActorType = 3
        },
        [6101801] = {
          ContentJP = "あなたは焚き火のそばに腰を下ろし、しばしの休息をとる。\nそのとき、不意に奇妙な音が耳に届いた。最初はすぐ耳元から聞こえたように思えたが、徐々に頭上へと移動していく。\nその音は次第に大きくなり――ざわ、ざわ……何か柔らかいもの同士が擦れ合うような、そんな不気味な気配が辺りを包みはじめた。",
          DialogueId = 6101801,
          GUID = "0F4674BA",
          NextDialogue = 6101802,
          RougeTalkActorType = 3
        },
        [6101802] = {
          ContentJP = "「やぁ！幸運な旅人さん！」",
          DialogueId = 6101802,
          GUID = "0F4674E4",
          NextDialogue = 6101803,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6101803] = {
          ContentJP = "色とりどりの羽根が、頭上からはらはらと舞い落ちてきた。深淵の中で、これほど多くの色彩を同時に目にしたのは、初めてのことだ。気づけば、あなたの足元には羽根が山のように積もっている。まるで街角のイタズラ好きな子どもたちに選ばれてしまった、運の悪い通行人のようだ――気まずさとともに、どこか言いようのない哀れさが、静かに漂っていた。",
          DialogueId = 6101803,
          GUID = "0F46750E",
          NextDialogue = 6101804,
          RougeTalkActorType = 3
        },
        [6101804] = {
          ContentJP = "「つまんないなぁ、ちょっとは反応してくれてもいいんじゃない？こんなに長く深淵にいて、退屈じゃないの？」そう言いながら、ひょろりと現れたのは、滑稽な鳥の仮面を被った人物。逆さまの姿勢のまま、ふわりと降りてきて、ちょうどあなたと視線が合う高さで止まった。どうやってその体勢を保っているのかは謎だが、そんなことは今はどうでもいい。何より気になるのは、その仮面の尖ったクチバシが、今にもあなたの顔に触れそうなほど、ぐいっと近づいていることだった。",
          DialogueId = 6101804,
          GUID = "0F467538",
          NextOptions = {
            [1] = 6101805
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6101805] = {
          ContentJP = "悪いけど、あなたに構ってる暇ないから。",
          DialogueId = 6101805,
          GUID = "0F467562",
          NextDialogue = 6101806,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101806] = {
          ContentJP = "「そんなに冷たくしないでよ～。礼賛会のじじいたちに教わらなかった？日々善行を積めば、いつか報われるってさ」\n「ね、<H>ひとつゲームしようよ</>。勝ったらごほうびをあげるし、負けても罰はなし。損することなんて、なーんにもない。どう？やる気出てきた？」",
          DialogueId = 6101806,
          GUID = "0F46758C",
          NextOptions = {
            [1] = 6101807,
            [2] = 6101808
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6101807] = {
          ContentJP = "いいよ。",
          DialogueId = 6101807,
          GUID = "0F4675B6",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101808] = {
          ContentJP = "本当に忙しい。",
          DialogueId = 6101808,
          GUID = "0F4675E0",
          IsKeyOption = true,
          NextDialogue = 6101809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101809] = {
          ContentJP = "「はいはい、わかったよ～。ワタシだって、無理強いするような悪いヤツじゃないしね」\n「じゃあ、また今度会おうね！」",
          DialogueId = 6101809,
          GUID = "0F46760A",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6101901] = {
          ContentJP = "焚き火が、しわが寄った老人の顔を照らし出していた。\n老人は手にハンマーを持っており、足元にはいくつもの武器が散らばっていた。\nあなたに気づくと、その瞳にはほのかな喜びが浮かんだ。",
          DialogueId = 6101901,
          GUID = "0F468522",
          NextDialogue = 6101902,
          RougeTalkActorType = 3
        },
        [6101902] = {
          ContentJP = "「若者よ、エリュシオンはどっちの方向じゃか知ってるかい」\n老人はかすれた声で話した。\n「この辺りを何度もぐるぐる回っとるのにのう、どうにも家への道が見つからんでな……」",
          DialogueId = 6101902,
          GUID = "0F46854C",
          NextOptions = {
            [1] = 6101903
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101903] = {
          ContentJP = "沈黙。",
          DialogueId = 6101903,
          GUID = "0F468576",
          NextDialogue = 6101904,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101904] = {
          ContentJP = "「そうか……おぬしも道に迷うとるか。ままならんのう……」\n老人は長いため息をつくと、頭を垂れた。",
          DialogueId = 6101904,
          GUID = "0F4685A0",
          NextOptions = {
            [1] = 6101905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101905] = {
          ContentJP = "武器をひとつもらえないかと老人に尋ねる。",
          DialogueId = 6101905,
          GUID = "0F4685CA",
          NextDialogue = 6101906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101906] = {
          ContentJP = "「武器とな？　この地面に転がっとる、この品々のことか？」\n「ああ……思い出した。わしは……鍛冶屋なんじゃ。」\n「何人かのために武器を打ってな、逃げる手助けをしとったんじゃ。そしてーー」",
          DialogueId = 6101906,
          GUID = "0F4685F4",
          NextDialogue = 6101907,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101907] = {
          ContentJP = "老人の視線は一瞬暗くなった。ようやくここに来た理由を思い出したようだ。そして彼は軽く首を振り、あなたに向けて奥深そうに微笑んだ。",
          DialogueId = 6101907,
          GUID = "0F46861E",
          NextDialogue = 6101908,
          RougeTalkActorType = 3
        },
        [6101908] = {
          ContentJP = "「もちろんじゃ。」\n「好きなのを選びなされ。きっとおぬしを守ってくれよう。」",
          DialogueId = 6101908,
          GUID = "0F468648",
          NextOptions = {
            [1] = 6101909,
            [2] = 6101910
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room319_Char01"
        },
        [6101909] = {
          ContentJP = "老人の左手側にある武器から選ぶ。",
          DialogueId = 6101909,
          GUID = "0F468672",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101910] = {
          ContentJP = "老人の右手側にある武器から選ぶ。",
          DialogueId = 6101910,
          GUID = "0F46869C",
          IsKeyOption = true,
          NextDialogue = 6101911,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6101911] = {
          ContentJP = "あなたは選んだ武器を収めた。\n老人はあなたの存在を忘れているようで、物も言わずに手元のハンマーを眺め、何かを深く考え込んでいるようだ。",
          DialogueId = 6101911,
          GUID = "0F4686C6",
          RougeTalkActorType = 3
        },
        [6102001] = {
          ContentJP = "ふと、金属のぶつかる音が聞こえた。火花が飛び散り、焚き火の明かりに溶けていった。振り向くと、簡素な鍛冶台のそばで、老人が力強くハンマーを振り下ろしている。",
          DialogueId = 6102001,
          GUID = "0F46958A",
          NextDialogue = 6102002,
          RougeTalkActorType = 3
        },
        [6102002] = {
          ContentJP = "「やあ、若いの。」\nあなたを見たら、老人は熱心に声をかけてきた。",
          DialogueId = 6102002,
          GUID = "0F4695B4",
          NextOptions = {
            [1] = 6102003
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102003] = {
          ContentJP = "こんにちは。",
          DialogueId = 6102003,
          GUID = "0F4695DE",
          NextDialogue = 6102004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102004] = {
          ContentJP = "「どうやら、おぬしもここに閉じ込められとるようじゃな？」老人は自分を指差して、「わしもじゃ。」",
          DialogueId = 6102004,
          GUID = "0F469608",
          NextOptions = {
            [1] = 6102005
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102005] = {
          ContentJP = "また会いました{性别:なぁ|ね}。",
          DialogueId = 6102005,
          GUID = "0F469632",
          NextDialogue = 6102006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102006] = {
          ContentJP = "「わしら、会うたことがあるかの？」老人は少し戸惑って、「よう覚えとらんが、わしも年を取ったもんじゃ……」",
          DialogueId = 6102006,
          GUID = "0F46965C",
          NextDialogue = 6102007,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102007] = {
          ContentJP = "「とにかく、ここは危ないところじゃ。武器をいくつか打ってみたでな、ひとつ持っていきなされ。」\n老人は気前よく自分の作品を見せてくれた。\n「まあ、どうせここからは出られんのなら、せっかくだし本職に戻るとしようかの。いつか、わしの打った武器がすごい騎士さまの役に立つことがあれば、こんな腐れた場所から連れ出してくれるやもしれんわい。」",
          DialogueId = 6102007,
          GUID = "0F469686",
          NextOptions = {
            [1] = 6102008,
            [2] = 6102009,
            [3] = 6102010
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room318_Char01"
        },
        [6102008] = {
          ContentJP = "新しく鍛え上げた武器から選ぶ。",
          DialogueId = 6102008,
          GUID = "0F4696B0",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102009] = {
          ContentJP = "整然と並べている完成品から選ぶ。",
          DialogueId = 6102009,
          GUID = "0F4696DA",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102010] = {
          ContentJP = "片隅で埃にまみれた武器から選ぶ。",
          DialogueId = 6102010,
          GUID = "0F469704",
          IsKeyOption = true,
          NextDialogue = 6102011,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102011] = {
          ContentJP = "選んだ武器を持って、老人の親切な別れの言葉を聞きながら、先へ進んでいく。",
          DialogueId = 6102011,
          GUID = "0F46972E",
          RougeTalkActorType = 3
        },
        [6102101] = {
          ContentJP = "焚き火の光が明るくなったり暗くなったりして、うつむいた詩人の横顔を照らし出した。彼女は焚き火のそばにひざまずき、指を伸ばし、灰の上にゆっくりと曲線を描いている。",
          DialogueId = 6102101,
          GUID = "0F46A5F2",
          NextDialogue = 6102102,
          RougeTalkActorType = 3
        },
        [6102102] = {
          ContentJP = "「逃げる場所がないなら、運命を受け入れよう。」\n「文字が噓を突き破る刃になれないのなら、それは美しい夢を築くレンガになろうーー」\n詩人は少し間を置いて、指先を少し上げた。\n「うん......」",
          DialogueId = 6102102,
          GUID = "0F46A61C",
          NextDialogue = 6102103,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102103] = {
          ContentJP = "脳裏の記憶がふっと蘇り、かつてこの詩を読んだことがあるとあなたは確信を持っている。\n一本の煙が頬をかすれた後、まるで無意識のように、あなたは詩の最後の一句をそっと読み出したーー",
          DialogueId = 6102103,
          GUID = "0F46A646",
          NextOptions = {
            [1] = 6102104
          },
          RougeTalkActorType = 3
        },
        [6102104] = {
          ContentJP = "「噓を紡ぎ、不滅の火光を灯す。」",
          DialogueId = 6102104,
          GUID = "0F46A670",
          NextDialogue = 6102105,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102105] = {
          ContentJP = "「うん......？」\n詩人は顔を上げ、嬉しそうに君を見る。\n「どれだけ美しい詩句よ、これこそが私が欲しがる結末！まさかここで知己を得たとはね。」",
          DialogueId = 6102105,
          GUID = "0F46A69A",
          NextOptions = {
            [1] = 6102106
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102106] = {
          ContentJP = "「実はこれが、もう一つのタイムラインのあなたが書いたものよ。」",
          DialogueId = 6102106,
          GUID = "0F46A6C4",
          NextDialogue = 6102107,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102107] = {
          ContentJP = "「もう一つのタイムラインって......？」\n詩人は最初に信じがたい表情を表したが、すると眼差しから光を放ち、まるで焚き火に燃やされたように。\n「なるほど......君が特別なのだ。この叙事詩の主役、私がほかのタイムラインで再び会えるかもしれない人、そうでしょう？」",
          DialogueId = 6102107,
          GUID = "0F46A6EE",
          NextOptions = {
            [1] = 6102108
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102108] = {
          ContentJP = "うなずく。",
          DialogueId = 6102108,
          GUID = "0F46A718",
          NextDialogue = 6102109,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102109] = {
          ContentJP = "「そしたらこの詩はあなたが書いたものなのか、それとも私なのか？ふふ......迷っちゃうね、聖樹学院の学者たちも君の物語に酔いしれると思うよ。\n詩人はくっくと笑い始めた。\n「今度会った時、あなたのために詩を作らせていただくわ。さぁ、手を出して、私の祝福を受け取りなさい。」",
          DialogueId = 6102109,
          GUID = "0F46A742",
          NextOptions = {
            [1] = 6102110,
            [2] = 6102111
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room320_Char01"
        },
        [6102110] = {
          ContentJP = "左手を出す。",
          DialogueId = 6102110,
          GUID = "0F46A76C",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102111] = {
          ContentJP = "右手を出す。",
          DialogueId = 6102111,
          GUID = "0F46A796",
          IsKeyOption = true,
          NextDialogue = 6102112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102112] = {
          ContentJP = "詩人は、指先についた灰で、あなたの手のひらに何かを書いた。\n文字の意味は相変わらず分からないが、人を傷つけるものではない情熱の、確かなぬくもりだけは感じ取れる。\nあなたがふたたび顔を上げると、詩人の姿はもうここになかった。",
          DialogueId = 6102112,
          GUID = "0F46A7C0",
          RougeTalkActorType = 3
        },
        [6102201] = {
          ContentJP = "「儚い運命の神よ、時には私たちを喜ばせ、時には私たちを苦しめる......」\n「常に敬虔な心を持って......その純白の糸はいずれ、天国へ行く道を示してくれるだろう......」\n少年は真剣で敬虔な口調で本を読み上げていて、あなたにまったく気づいていない。",
          DialogueId = 6102201,
          GUID = "0F46B65A",
          NextDialogue = 6102202,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102202] = {
          ContentJP = "あなたはそっと少年のそばに近づき、その本をちらりと見た。\n記憶どおり、ページに記された聖歌は、悪意に満ちた漆黒の文字で覆われている。\nその文字はうごめき、今にも本から逃げ出しそうだ。",
          DialogueId = 6102202,
          GUID = "0F46B684",
          NextDialogue = 6102203,
          RougeTalkActorType = 3
        },
        [6102203] = {
          ContentJP = "「こんにちは......あなたも本を読みたいでしょうか？」\n少年はついにあなたの存在に気づき、興味深そうに顔を上げた。",
          DialogueId = 6102203,
          GUID = "0F46B6AE",
          NextOptions = {
            [1] = 6102204,
            [2] = 6102208
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102204] = {
          ContentJP = "彼が読み続けるのを止める。",
          DialogueId = 6102204,
          GUID = "0F46B6D8",
          IsKeyOption = true,
          NextDialogue = 6102205,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102205] = {
          ContentJP = "あなたが少年の手の中から本を奪い、思いっきり閉じる。",
          DialogueId = 6102205,
          GUID = "0F46B702",
          NextDialogue = 6102206,
          RougeTalkActorType = 3
        },
        [6102206] = {
          ContentJP = "「あなた、大丈夫でしょうか？！」\n少年は心配そうに立ち上がり、空っぽになった両手に呆然と視線を落とした。\n「あれ？私......もう本を読まなくてもいいのですか？私......自由になりましたのか？」",
          DialogueId = 6102206,
          GUID = "0F46B72C",
          NextDialogue = 6102207,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room321_Char01"
        },
        [6102207] = {
          ContentJP = "あなたは指先の痛みに耐えながら、微笑んでうなずき、本を焚き火に投げ入れた。すると、炎が高く噴き上がり、黒い棘と一緒にあなたに襲いかかってきたーー",
          DialogueId = 6102207,
          GUID = "0F46B756",
          RougeTalkActorType = 3
        },
        [6102208] = {
          ContentJP = "沈黙。",
          DialogueId = 6102208,
          GUID = "0F46B780",
          IsKeyOption = true,
          NextDialogue = 6102209,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102209] = {
          ContentJP = "あなたは知っている。どんな行動を取っても、少年の運命を本当に変えることはできない。あなたにとってもっと大事なことがあるーー瑠璃を集め、この末永く続く悪夢を徹底的に終わらせること。",
          DialogueId = 6102209,
          GUID = "0F46B7AA",
          NextDialogue = 6102210,
          RougeTalkActorType = 3
        },
        [6102210] = {
          ContentJP = "瞬く間に、黒い棘が広がり、少年の姿を飲み込んでいった。\nあなたは軽くため息をつき、前に進み続ける。",
          DialogueId = 6102210,
          GUID = "0F46B7D4",
          RougeTalkActorType = 3
        },
        [6102301] = {
          ContentJP = "「そこの子......ほら見て、ここに焚き火があるのよ。」\n火の光の向こう側で、一人の女性が微笑みながら顔を上げた。火の光が彼女のやつれた頬を照らしていた。\n「本当に暖かいわ。ありがとう、親切な見知らぬ人よ」",
          DialogueId = 6102301,
          GUID = "0F46C6C2",
          NextOptions = {
            [1] = 6102302
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102302] = {
          ContentJP = "彼女の言う子供はどこにいるのかを尋ねる。",
          DialogueId = 6102302,
          GUID = "0F46C6EC",
          NextDialogue = 6102303,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102303] = {
          ContentJP = "「今ここにいるよ、見て。」",
          DialogueId = 6102303,
          GUID = "0F46C716",
          NextDialogue = 6102304,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102304] = {
          ContentJP = "彼女が示す方向に目を向けると、腰ほど高さの苔に覆われた岩があった。\n岩の真ん中から少し上の隙間には、きらきらと光る一枚のブローチがはめ込まれていて、周りに苔が這いまわっている。まるで、埋もれた心のようだ。\n彼女は手についた泥にはまったく気づかなく、優しく岩の表面をなでていた。",
          DialogueId = 6102304,
          GUID = "0F46C740",
          NextOptions = {
            [1] = 6102305,
            [2] = 6102308
          },
          RougeTalkActorType = 3
        },
        [6102305] = {
          ContentJP = "真実を教える。",
          DialogueId = 6102305,
          GUID = "0F46C76A",
          IsKeyOption = true,
          NextDialogue = 6102306,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102306] = {
          ContentJP = "「何を言っているの？！」\n彼女の目から敵意の光が一瞬放ち、あの岩を背後に強く庇いながら、声を振り絞って叫んだ。\n「これは私の子なの......彼女は今ここにいるんのよ、もう誰にも連れ去らせない......絶対に.....」",
          DialogueId = 6102306,
          GUID = "0F46C794",
          NextDialogue = 6102307,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102307] = {
          ContentJP = "あなたは一瞬言葉を失う。\n美しい夢から人を呼び覚ますなんて、残酷で意味のないことだ.――それはとっくにわかっているのに。\nそしてあなたは立ち上がり、焚き火を彼女と彼女の「子供」に残してこの場を離れようとした。\nその瞬間、暗闇に潜んでいた暗影があなたを狙って襲いかかってくるーー",
          DialogueId = 6102307,
          GUID = "0F46C7BE",
          RougeTalkActorType = 3
        },
        [6102308] = {
          ContentJP = "彼女を認める。",
          DialogueId = 6102308,
          GUID = "0F46C7E8",
          IsKeyOption = true,
          NextDialogue = 6102309,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102309] = {
          ContentJP = "「ありがとう。この子は小さい頃から人見知りなのに、どうやらあなたのことが好きみたいね。」\n彼女は優しい口調で言い、時おり岩をそっと撫でていた。\n「あなた、ひとりで旅をしているの？だめだよ、家族が心配なさるわ.....早く家にお帰りなさい。」",
          DialogueId = 6102309,
          GUID = "0F46C812",
          NextDialogue = 6102310,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room322_Char01"
        },
        [6102310] = {
          ContentJP = "あなたは丁寧に礼を言い、身を起こして先へ進んだ。\n彼女とその「子」の姿は、次第に火の陰に霞んでいった。",
          DialogueId = 6102310,
          GUID = "0F46C83C",
          RougeTalkActorType = 3
        },
        [6102401] = {
          ContentJP = "「なくなった…… なくなった……」\n少女は虚ろな目を開け、地面を這って、何かを探している。爪はほとんど土に食い込みそうだ。",
          DialogueId = 6102401,
          GUID = "0F46D72A",
          NextOptions = {
            [1] = 6102402
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102402] = {
          ContentJP = "彼女が何を探しているのかを尋ねる。",
          DialogueId = 6102402,
          GUID = "0F46D754",
          NextDialogue = 6102403,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102403] = {
          ContentJP = "「私の石.....石......さっきまでここにあったのに......」\n彼女は呟きながら、絶望したように、あなたの足元にある焚き火を見つめている。\n「私の火は......消えそう......どうしよう......どうしょう......」",
          DialogueId = 6102403,
          GUID = "0F46D77E",
          NextOptions = {
            [1] = 6102404,
            [2] = 6102408
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102404] = {
          ContentJP = "彼女を助ける。",
          DialogueId = 6102404,
          GUID = "0F46D7A8",
          IsKeyOption = true,
          NextDialogue = 6102405,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102405] = {
          ContentJP = "あなたは、彼女が好んでいた石の様子を思い出そうと試みた。その由来は確かめられないが、炎魔法で似たものを作れるだろうと、あなたは判断した。\nそれで、焚き火を利用して、力を集中させるとーー\n瞬く間に、きらめく金色の小石が流星のように降り注ぎ、ぶつかり合って清らかな音を立てた。",
          DialogueId = 6102405,
          GUID = "0F46D7D2",
          NextDialogue = 6102406,
          RougeTalkActorType = 3
        },
        [6102406] = {
          ContentJP = "「あっ......！私の石ーーこれは私の石だ！ありがとう、神の使者様！」\n少女は宝物を得たように一つ一つ拾い上げ、大事にスカートの裾で包んだ。",
          DialogueId = 6102406,
          GUID = "0F46D7FC",
          NextDialogue = 6102407,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102407] = {
          ContentJP = "その結晶は、以前少女の懐に見た石とそっくりだった。それが、あなたが旅の途中でうっかり残した痕跡なのかどうか、疑問が浮かんだ。\nどちらにせよ、少女は再び自分の「確定」を取り戻した。そして、あなたは旅を続けなければならない。",
          DialogueId = 6102407,
          GUID = "0F46D826",
          RougeTalkActorType = 3
        },
        [6102408] = {
          ContentJP = "世の中は、いつも私たちの思う通りにはならないと彼女に言う。",
          DialogueId = 6102408,
          GUID = "0F46D850",
          IsKeyOption = true,
          NextDialogue = 6102409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102409] = {
          ContentJP = "「分かってる......分かってるの。」\n「だからもう諦めたの......本も読まないし、魔法の起源なんて考えないし、あの塔の中に何があるかなんて問いかけないの......」\n「今はただ火がほしいだけなのに......それもだめなの？」",
          DialogueId = 6102409,
          GUID = "0F46D87A",
          NextDialogue = 6102410,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room323_Char01"
        },
        [6102410] = {
          ContentJP = "あなたは言葉に詰まった。\n少女は立ち上がり、あなたが応える間もなく、思い切って炎の中へ踏み入った。\nゆっくりと、少女の姿は火の光に溶け、やがて消えていった。\nあなたは踵を返し、旅を続けた。",
          DialogueId = 6102410,
          GUID = "0F46D8A4",
          RougeTalkActorType = 3
        },
        [6102501] = {
          ContentJP = "焚き火は静かに燃え続けていて、今度はどんなミラージュも見えなかった。\nあなたが立ち去ろうとした時に、地面にきらめくものが目に入ったーー黄金色の小石が一つ一つ散らばっていて、まるで空から落ちた星のようだ。",
          DialogueId = 6102501,
          GUID = "0F46E792",
          NextOptions = {
            [1] = 6102502,
            [2] = 6102506
          },
          RougeTalkActorType = 3
        },
        [6102502] = {
          ContentJP = "石ころを拾って炎の中に放り投げる。",
          DialogueId = 6102502,
          GUID = "0F46E7BC",
          IsKeyOption = true,
          NextDialogue = 6102503,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102503] = {
          ContentJP = "炎がますます勢いを増し、それから異常に横に伸び始めた。\nあなたは慎重に一歩後ずさりして、炎の中から一つの姿が突然現れた。あなたはようやくわかったのだ。横に伸びていた光は炎ではなく、少女の髪の毛だった。",
          DialogueId = 6102503,
          GUID = "0F46E7E6",
          NextDialogue = 6102504,
          RougeTalkActorType = 3
        },
        [6102504] = {
          ContentJP = "「こんにちは！私の石を見つけてくれたの？」\n少女は焚き火の中から飛び出し、頭を左右に振り、金色の石がバラバラと地面に落ちた。\n「もう外に探しにいかなくていいのーー見て、この火の中に入れば、自分で石ころを作れるから。」",
          DialogueId = 6102504,
          GUID = "0F46E810",
          NextDialogue = 6102505,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102505] = {
          ContentJP = "「ごめん、あなたとゆっくり話せる時間がなくてーーまだ１４６個集めていないの。」\n「でも、あなたに役に立つかもしれないものを見つけたよ。これを受け取って。そして、良い旅を！」\n少女が何かをあなたに渡すと、振り向いて炎の中に消えていった。",
          DialogueId = 6102505,
          GUID = "0F46E83A",
          NextDialogue = 6102510,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102506] = {
          ContentJP = "静かに観察する。",
          DialogueId = 6102506,
          GUID = "0F46E864",
          IsKeyOption = true,
          NextDialogue = 6102507,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102507] = {
          ContentJP = "炎はまだ静かに燃えていて、恍惚の中で、どこかから声を聞こえたようだ。",
          DialogueId = 6102507,
          GUID = "0F46E88E",
          NextDialogue = 6102508,
          RougeTalkActorType = 3
        },
        [6102508] = {
          ContentJP = "「うん......うん。覚えている。」\n少女の穏やかで幸せに溢れる声が炎を通して伝わってくる。\n「疑問を持つにもほどがある。火は神様の贈り物で、物質の反応じゃない。これらの石たちも、神様から頂いた宝物で、いつも安らかに眠れるようにしてくれてる.....」",
          DialogueId = 6102508,
          GUID = "0F46E8B8",
          NextDialogue = 6102509,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room324_Char01"
        },
        [6102509] = {
          ContentJP = "あなたは黙って背を向けて立ち去った。一つの石ころがたまたま道の先に転がっていて、あなたは無意識に踏みつけて粉々にしてしまった。\n神様からの贈り物は、こんなに脆いのだ。",
          DialogueId = 6102509,
          GUID = "0F46E8E2",
          NextDialogue = 6102510,
          RougeTalkActorType = 3
        },
        [6102510] = {
          ContentJP = "その炎が少女にもたらすのは、幸福を与える「確定」なのか、それとも永遠にここに閉じ込める「枷」なのか？\nあるいは、この両者は元々、それほどの違いがないのだろう。",
          DialogueId = 6102510,
          GUID = "0F46E90C",
          RougeTalkActorType = 3
        },
        [6102601] = {
          ContentJP = "「ごめんなさい、全部私のせい.....頭が悪いから、聖歌を全部覚えられない.....怠けていたから、宣教が終わるまで聞き続けられなかった.....」\n「神様、どうか許してください.....」",
          DialogueId = 6102601,
          GUID = "0F46F7FA",
          NextDialogue = 6102602,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102602] = {
          ContentJP = "少女は周りの人を無視して懺悔しているーーもしくは、もう他人が見えなくなっているのかもしれない。\n彼女の様子は前よりも明らかに悪くなっていて、目までもくすんで光を失った。",
          DialogueId = 6102602,
          GUID = "0F46F824",
          NextDialogue = 6102603,
          RougeTalkActorType = 3
        },
        [6102603] = {
          ContentJP = "「あなたは.....あの旅人……？もう……だいぶ時間が経ったのか？」\n少女はようやくあなたの存在に気づき、ゆっくりとこちらを振り向いた。\n「旅人よ......教えてください......なぜ、私は昼も夜も神様に祈っていたのに、神様は一度たりとも応えてくれなかったの？」",
          DialogueId = 6102603,
          GUID = "0F46F84E",
          NextOptions = {
            [1] = 6102604,
            [2] = 6102608
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102604] = {
          ContentJP = "彼女に祈り続けるよう励ます。",
          DialogueId = 6102604,
          GUID = "0F46F878",
          IsKeyOption = true,
          NextDialogue = 6102605,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102605] = {
          ContentJP = "結末を書き変える時がまだ来ていないのなら、噓を続けても構わなく.....少なくとも、これも一種の「希望」だから。\nあなたは彼女に、祈り続ければ、いつか二人とも必ず救われるだろうと伝えた。\nこれは完全な嘘ではないーー彼女の祈祷にも関わらず、深淵はいつか必ず破れられ、その答はあなたが今持っているランタンにあるのだとあなたはいつも信じている。",
          DialogueId = 6102605,
          GUID = "0F46F8A2",
          NextDialogue = 6102606,
          RougeTalkActorType = 3
        },
        [6102606] = {
          ContentJP = "「分かった.....信じる。」\n少女は手を合わせ、さらにしっかりとした調子で祈り続けた。",
          DialogueId = 6102606,
          GUID = "0F46F8CC",
          NextDialogue = 6102607,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102607] = {
          ContentJP = "あなたはそっとため息をつき、手元のランタンを握りしめて、進み続ける。",
          DialogueId = 6102607,
          GUID = "0F46F8F6",
          RougeTalkActorType = 3
        },
        [6102608] = {
          ContentJP = "神様は応えないと彼女に告げる。",
          DialogueId = 6102608,
          GUID = "0F46F920",
          IsKeyOption = true,
          NextDialogue = 6102609,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102609] = {
          ContentJP = "「神様は.....応えてくれないのか？」\n「私の罪は深すぎて、もう救われる価値もないのか？」\n彼女は絶望した表情であなたを見つめ、膿瘍の広がる頬から涙が滴り落ちた。",
          DialogueId = 6102609,
          GUID = "0F46F94A",
          NextOptions = {
            [1] = 6102610
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102610] = {
          ContentJP = "「あなたにはもともと罪などないからだ。」",
          DialogueId = 6102610,
          GUID = "0F46F974",
          NextDialogue = 6102611,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102611] = {
          ContentJP = "「えっ......？」\n彼女は呆れて、目の中に深い困惑が浮かんだ。",
          DialogueId = 6102611,
          GUID = "0F46F99E",
          NextDialogue = 6102612,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room325_Char01"
        },
        [6102612] = {
          ContentJP = "あなたはしっかりとした微笑みを浮かべ、必ず彼女の苦しみを終わらせる方法を見つけるんのだと言った。少女はあなたを見つめ、なんとなく頷いた。その時、あなたは気付いた。彼女の傷口はもう血を流さなくなっていた。あなたは手を振って別れを告げ、ランタンを握りしめ、進み続けた。",
          DialogueId = 6102612,
          GUID = "0F46F9C8",
          RougeTalkActorType = 3
        },
        [6102701] = {
          ContentJP = "「満月の神・フサよーー」\n「煌めく足跡の主宰、運命の糸の紡ぎ手よ......」\n「空と月の輝きを証とし、敬虔な讃歌を捧げよ......」",
          DialogueId = 6102701,
          GUID = "0F470862",
          NextDialogue = 6102702,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102702] = {
          ContentJP = "人々の姿が火の中から浮かび上がり、彼らは一斉に神様への祝詞を歌っていた。",
          DialogueId = 6102702,
          GUID = "0F47088C",
          NextDialogue = 6102703,
          RougeTalkActorType = 3
        },
        [6102703] = {
          ContentJP = "「あなたは誰ですか？道に迷った旅人？」\n一人の祈祷者があなたを気付き、笑顔で手を伸ばしてきた。\n「私たちと一緒に満月の神に祈りましょう。きっとあなたの前路に祝福を与えてくださるでしょう。」",
          DialogueId = 6102703,
          GUID = "0F4708B6",
          NextDialogue = 6102704,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102704] = {
          ContentJP = "彼らの讃歌は<H>第九位の神</>、運命の神である<H>フサ</>に捧げられていた。\nフサは満月を司り、月の輝きを練り合わせ、運命の糸をおる存在だ。",
          DialogueId = 6102704,
          GUID = "0F4708E0",
          NextOptions = {
            [1] = 6102705,
            [2] = 6102709
          },
          RougeTalkActorType = 3
        },
        [6102705] = {
          ContentJP = "彼らの祈りに加わる。",
          DialogueId = 6102705,
          GUID = "0F47090A",
          IsKeyOption = true,
          NextDialogue = 6102706,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102706] = {
          ContentJP = "これは幼い頃のあなたがいちばん嫌いだった場面だった。空虚な賛美の言葉など、覚えてもすぐに忘れてしまった。だが今では、いくらか懐かしさすら覚える。\nあなたは彼らの祈りに加わった。",
          DialogueId = 6102706,
          GUID = "0F470934",
          NextDialogue = 6102707,
          RougeTalkActorType = 3
        },
        [6102707] = {
          ContentJP = "「フサ様、無秩序な運命の流れの中で常に大空を横切る満月の神よ。\n「あなたに敬意を捧げよう、あなたの信者をかばってください。\n最高の幸運と幸せを与えてください。」",
          DialogueId = 6102707,
          GUID = "0F47095E",
          NextDialogue = 6102708,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102708] = {
          ContentJP = "あなたは目を閉じ、敬虔な信者と一緒に祈った。\n最後の一節を唱い終えると、あなたは目を開け、彼らの姿はもう消えていた。",
          DialogueId = 6102708,
          GUID = "0F470988",
          RougeTalkActorType = 3
        },
        [6102709] = {
          ContentJP = "彼らの祈りに加わるのを拒む。",
          DialogueId = 6102709,
          GUID = "0F4709B2",
          IsKeyOption = true,
          NextDialogue = 6102710,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102710] = {
          ContentJP = "「断る？貴様――なぜだ？」\n祈祷師は甲高い声で叫んだ。\n「異端者――まさか、貴様は闇月派の信徒か？ネーファの信徒か？」",
          DialogueId = 6102710,
          GUID = "0F4709DC",
          NextDialogue = 6102711,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room326_Char01"
        },
        [6102711] = {
          ContentJP = "その禁忌の名を耳にすると、祈祷師たちは一斉に顔を歪めた。\nあなたはため息をついた――どうやらここから抜け出す方法を考えなければならない。",
          DialogueId = 6102711,
          GUID = "0F470A06",
          RougeTalkActorType = 3
        },
        [6102801] = {
          ContentJP = "「運命の糸を断ち切る鋏、永遠と静寂の主宰よ......」\n「深淵と長夜の証の下で、私のへりくだった祝詞を聞いてくれませんか......」",
          DialogueId = 6102801,
          GUID = "0F4718CA",
          NextDialogue = 6102802,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01"
        },
        [6102802] = {
          ContentJP = "人々の姿が火の中から浮かび上がり、彼らは一斉に神様への祝詞を読み上げている。あなたは静かに聞いていた。それらはあなたの知らない祝詞だった。",
          DialogueId = 6102802,
          GUID = "0F4718F4",
          NextDialogue = 6102803,
          RougeTalkActorType = 3
        },
        [6102803] = {
          ContentJP = "「あなたは誰ですか？道に迷った旅人ですか？」\n一人の祈祷者があなたに気付き、笑顔で手を伸ばしてきた。\n「それとも、あなたも同じように天の秘密を看破し、真の救世主であるネーファのもとに入りたいのですか？」",
          DialogueId = 6102803,
          GUID = "0F47191E",
          NextDialogue = 6102804,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char01"
        },
        [6102804] = {
          ContentJP = "<H>ネーファ</>ーーこの名前はあなたが覚えている。\nこの名前はエリュシオン正教の信者の筆の下であまり登場せず、あなたは埃を被った古い書簡の中でだけこの名前を見たことがある。これは禁忌の名前で、すでに忘れ去られた<H>第十位の神だ</>。",
          DialogueId = 6102804,
          GUID = "0F471948",
          NextDialogue = 6102805,
          RougeTalkActorType = 3
        },
        [6102805] = {
          ContentJP = "ネーファは、満月と運命の神であるフサの姉妹で、闇月と死の神だ。\n同胞の姉は運命の糸をの織るに対し、ネーファは運命を断つのだ。\n二人の神はきりのない争いで月の満ち欠けをもたらし、潮汐を巻き起こしていた。\nそしたら、ネーファの信者は......",
          DialogueId = 6102805,
          GUID = "0F471972",
          NextOptions = {
            [1] = 6102806
          },
          RougeTalkActorType = 3
        },
        [6102806] = {
          ContentJP = "彼らの信仰について尋ねる。",
          DialogueId = 6102806,
          GUID = "0F47199C",
          NextDialogue = 6102807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102807] = {
          ContentJP = "「ここに現れたのだから、あなたも知っているはずだが、この深淵は死んだものではない。それは生きていて、どんどん成長し、広がっている。」\n「騎士団の黄金の聖剣も暗闇の波を退けることができず、満月の輝きも底が見えない静寂を貫くことができない。」\n「すべての光が消えるべく駆け、すべての生き物が必ず死ぬようにーー消滅こそが唯一確かなものだ。我らの深淵こそ、世界の本来の姿なのだ。」\n「<H>闇月教派</>へようこそ、愛しい旅人よ。」",
          DialogueId = 6102807,
          GUID = "0F4719C6",
          NextOptions = {
            [1] = 6102808,
            [2] = 6102811
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02"
        },
        [6102808] = {
          ContentJP = "彼らの誘いに応じる。",
          DialogueId = 6102808,
          GUID = "0F4719F0",
          IsKeyOption = true,
          NextDialogue = 6102809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102809] = {
          ContentJP = "たとえただの幻にすぎなくても、彼らを怒らせて無意味な争いを増やしたくはない。\nそこで、あなたはいかにも本気らしく、闇月教派について耳にした噂を繰り返し語った。『死の本能』『ネーファの救済』『深淵こそ永遠』……\nあなたの話を聞くと、彼らは顔に笑みを広げ、しきりにうなずき、あなたの大げさな言葉にも同意した。",
          DialogueId = 6102809,
          GUID = "0F471A1A",
          NextDialogue = 6102810,
          RougeTalkActorType = 3
        },
        [6102810] = {
          ContentJP = "「あなたの博学と知恵に心から感服しました。これを受け取ってくれ。見知らぬ友よ！」\nあなたはなんとかごまかした。幸い、幼いころの宣教と論弁の記憶は、全部がぼんやりしていたわけではなかった、とあなたは考えた。",
          DialogueId = 6102810,
          GUID = "0F471A44",
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room327_Char02"
        },
        [6102811] = {
          ContentJP = "彼らの誘いを断る。",
          DialogueId = 6102811,
          GUID = "0F471A6E",
          IsKeyOption = true,
          NextDialogue = 6102812,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102812] = {
          ContentJP = "この長い苦しみの旅の中で、あなたは何度も生と死の意味を考えていた。死こそが唯一の答えだと信じた時期もあった。\nしかし、<H>あの思いがけない出会いで</>、あなたが迷わずに暗闇の中で進み続けられる意を固めてくれたーー\nたとえ自らの身を薪にしてでも、この闇を追い払う。たとえ一本の微光しか届かなくても、この不滅を燃や尽くしてやる。",
          DialogueId = 6102812,
          GUID = "0F471A98",
          NextDialogue = 6102813,
          RougeTalkActorType = 3
        },
        [6102813] = {
          ContentJP = "「深淵は永遠ではない。お前たちはただ、生きていた生者たちの幻に過ぎない。」\nあなたは武器を構えた。\n「さあ、亡霊たちよ。行くべき場所に戻れーー」",
          DialogueId = 6102813,
          GUID = "0F471AC2",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102901] = {
          ContentJP = "あなたは焚き火のそばに腰を下ろし、しばしの休息をとる。\nそのとき、不意に奇妙な音が耳に届いた。最初はすぐ耳元から聞こえたように思えたが、徐々に頭上へと移動していく。\nその音は次第に大きくなり――ざわ、ざわ……何か柔らかいもの同士が擦れ合うような、そんな不気味な気配が辺りを包みはじめた。",
          DialogueId = 6102901,
          GUID = "0F472932",
          NextDialogue = 6102902,
          RougeTalkActorType = 3
        },
        [6102902] = {
          ContentJP = "「やぁ！幸運な旅人さん！」",
          DialogueId = 6102902,
          GUID = "0F47295C",
          NextDialogue = 6102903,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102903] = {
          ContentJP = "色とりどりの羽根が、頭上からはらはらと舞い落ちてきた。深淵の中で、これほど多くの色彩を同時に目にしたのは、初めてのことだ。気づけば、あなたの足元には羽根が山のように積もっている。まるで街角のイタズラ好きな子どもたちに選ばれてしまった、運の悪い通行人のようだ――気まずさとともに、どこか言いようのない哀れさが、静かに漂っていた。",
          DialogueId = 6102903,
          GUID = "0F472986",
          NextDialogue = 6102904,
          RougeTalkActorType = 3
        },
        [6102904] = {
          ContentJP = "「つまんないなぁ、ちょっとは反応してくれてもいいんじゃない？こんなに長く深淵にいて、退屈じゃないの？」そう言いながら、ひょろりと現れたのは、滑稽な鳥の仮面を被った人物。逆さまの姿勢のまま、ふわりと降りてきて、ちょうどあなたと視線が合う高さで止まった。どうやってその体勢を保っているのかは謎だが、そんなことは今はどうでもいい。何より気になるのは、その仮面の尖ったクチバシが、今にもあなたの顔に触れそうなほど、ぐいっと近づいていることだった。",
          DialogueId = 6102904,
          GUID = "0F4729B0",
          NextOptions = {
            [1] = 6102905
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102905] = {
          ContentJP = "悪いけど、あなたに構ってる暇ないから。",
          DialogueId = 6102905,
          GUID = "0F4729DA",
          NextDialogue = 6102906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6102906] = {
          ContentJP = "「そんなに冷たくしないでよ～。礼賛会のじじいたちに教わらなかった？日々善行を積めば、いつか報われるってさ」\n「ね、<H>ひとつゲームしようよ</>。勝ったらごほうびをあげるし、負けても罰はなし。損することなんて、なーんにもない。どう？やる気出てきた？」",
          DialogueId = 6102906,
          GUID = "0F472A04",
          NextOptions = {
            [1] = 6102907
          },
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room381_Char01"
        },
        [6102907] = {
          ContentJP = "いいよ。",
          DialogueId = 6102907,
          GUID = "0F472A2E",
          IsKeyOption = true,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103001] = {
          ContentJP = "「さあ、<H>サリエル</>のために、一緒に歌を歌いましょう！」\n「彼はエリュシオンの聖者、\n　フサの啓示を聞き、人々に慈悲と寛恕と愛を教えて。\n　朱色のエリュシオンの大地に、再び平和を芽生えさせた。」",
          DialogueId = 6103001,
          GUID = "0F47399A",
          NextDialogue = 6103002,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103002] = {
          ContentJP = "吟遊詩人のような老者が、崩れ落ちた壁の一部を撫でている。\nこの壁は比較的まともな状態で、かかすかな明かりに照らされ、大きな壁画が姿を現す。かれているのは、まさに詩人が歌っていた<H>「サリエル」</>だ。\n二千年前の聖者で、最初の<H>セブンヴァーチェス</>の一つである「節制」の座にあった存在である。\n詩人は一人で歌い続けていて、あなたが来たことにはまったく気づいていない。",
          DialogueId = 6103002,
          GUID = "0F4739C4",
          NextOptions = {
            [1] = 6103003
          },
          RougeTalkActorType = 3
        },
        [6103003] = {
          ContentJP = "聞き続ける。",
          DialogueId = 6103003,
          GUID = "0F4739EE",
          NextDialogue = 6103004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103004] = {
          ContentJP = "「だが、聖者の心は、ずっと一つの事で痛んでいた。」\n「それはフサが人々に約束した、あの天国のことだ。」\n「ついにある日、彼は碧波の畔で七十七日間座り続けた後、\n　満月の下で真理を悟ったーー湖の中で「永遠」にたどり着けた。」",
          DialogueId = 6103004,
          GUID = "0F473A18",
          NextDialogue = 6103005,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103005] = {
          ContentJP = "あなたは彼が何を歌っているかを知っている。\nサリエルは、碧波の畔で満月と運命の神であるフサの啓示を受け、魂が天国へ赴き、「永遠」を手に入れた。彼は神に選ばれた最初の人となった。\nその後、次々と人々の身に聖痕が現れた —— それは神に選ばれたしるしだ。彼らは聖湖を経て、約束された地へと到達した。\nこれらの礼賛会初期の歴史は、あなたには馴染み深いものだ。",
          DialogueId = 6103005,
          GUID = "0F473A42",
          NextOptions = {
            [1] = 6103006
          },
          RougeTalkActorType = 3
        },
        [6103006] = {
          ContentJP = "聞き続ける。",
          DialogueId = 6103006,
          GUID = "0F473A6C",
          NextDialogue = 6103007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103007] = {
          ContentJP = "「だが、二千年後、起伏のある山々の上に立って、聖湖を眺めると。\n　なぜそこに漆黒の渦波しか残っていないのか？」\n　サリエルよ、我々の知恵の聖者よーー\n　教えてくれ、女神が約束した楽園は、いったいどこにあるのか？」",
          DialogueId = 6103007,
          GUID = "0F473A96",
          NextDialogue = 6103008,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103008] = {
          ContentJP = "詩人は歌いながら，涙を流した。彼はようやく遠い昔の物語から、目の前にあるこの幽暗な深淵のことまで、歌ってきた。\n二千年以来、礼賛会にとって最も神聖で清らかな聖湖が、一夜にしてこの汚れた混沌に替えられた。\nまるで千年前に、信仰を捨てた墜落者が言っていたようにーー「神はすでに死んだ！」\n聞き続けるか？",
          DialogueId = 6103008,
          GUID = "0F473AC0",
          NextOptions = {
            [1] = 6103009,
            [2] = 6103013
          },
          RougeTalkActorType = 3
        },
        [6103009] = {
          ContentJP = "聞き続ける。",
          DialogueId = 6103009,
          GUID = "0F473AEA",
          IsKeyOption = true,
          NextDialogue = 6103010,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103010] = {
          ContentJP = "「なぜその穢れた深淵は言葉を発しないのか？\n「満月の銀の輝きが我が身に満ちても、なぜ女神は答えてくれないのか？」\n「サリエルよ、まさか暗月派の信徒たちが言うように──\n　あなたは天国に赴かず、月に背を向けて悪魔となったのか？」",
          DialogueId = 6103010,
          GUID = "0F473B14",
          NextDialogue = 6103011,
          RougeTalkActorType = 1,
          SpeakNpcId = 910005,
          SpeakNpcName = "RougeLike_Room328_Char01"
        },
        [6103011] = {
          ContentJP = "「ちょっと待ってーー何と言ったか？」\n詩人は思いがけない詩句を歌いあげた。それは異端者の中で流れる最も秘められた流言だーー聖湖はかつて神聖だったことはなく、サリエルから始まった神選びは、最初から盛大な生贄だけだった。\n<H>誰か</>の口から、同じような推測を聞いたことがある。",
          DialogueId = 6103011,
          GUID = "0F473B3E",
          NextDialogue = 6103012,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103012] = {
          ContentJP = "詩人は、まるであなたと別の時空にいるかのように、傍若無人に彼の七弦琴を弾き続け、次の歌へと移っていった。\n彼の歌声が次第に遠ざかり、姿が消えると共に聞こえなくなった。",
          DialogueId = 6103012,
          GUID = "0F473B68",
          RougeTalkActorType = 3
        },
        [6103013] = {
          ContentJP = "ここを離れる。",
          DialogueId = 6103013,
          GUID = "0F473B92",
          IsKeyOption = true,
          NextDialogue = 6103014,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6103014] = {
          ContentJP = "あなたは、詩人の注意をひこうと、何度か声をかけた。彼と話をしてみたかったが、彼はその古い歌謡を歌い続けるばかりだった。\n彼からほかに価値のある情報は得られないだろうと判断し、あなたは背を向けて立ち去ろうとした。",
          DialogueId = 6103014,
          GUID = "0F473BBC",
          RougeTalkActorType = 3
        },
        [6200101] = {
          ContentJP = "若者たちの話す声が、ほど遠くない場所から聞こえてくる。こんな声を深淵で聞くのは久しぶりだ──熱烈で、元気あふれる、まだ深淵の闇に侵されていない声。\nあなたはこれは亡霊でも幻影でもなく、紛れもない生身の人間の声だということを確信した。そして、会話の様子から、彼らがここに来たばかりだということも察した。",
          DialogueId = 6200101,
          GUID = "0F857412",
          NextDialogue = 6200102,
          RougeTalkActorType = 3
        },
        [6200102] = {
          ContentJP = "思わず声のする方へ足を向ける。周囲を覆っていた霧が薄れ、四人の若き騎士たちの姿が見えた。\n装備や服装はそれぞれ異なるが、皆、エリュシオンを象徴した、聖アイリスの紋章を身に着けている。",
          DialogueId = 6200102,
          GUID = "0F85743C",
          NextDialogue = 6200103,
          RougeTalkActorType = 3
        },
        [6200103] = {
          ContentJP = "「この方向で合ってるの？隊長」\n金髪の女騎士は古びた階段を駆け上がり、軽やかに飛び降りた。\n「どうやら、ただの廃墟みたい」",
          DialogueId = 6200103,
          GUID = "0F857466",
          NextDialogue = 6200104,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200104] = {
          ContentJP = "「少なくとも、来たことがない場所だ」\n隊長と呼ばれた青年騎士は落ち着いた足取りで彼女の横を通り過ぎる。\n「聖湖では方向を見失いやすい。今は一歩ずつ進むしかない」",
          DialogueId = 6200104,
          GUID = "0F857490",
          NextDialogue = 6200105,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200105] = {
          ContentJP = "「それから──そんなに跳ね回って疲れないのか、ケイシー？」\n元気すぎる仲間を見て、青年はため息をついた。\n「危険な場所なんだから、気を引き締めろ。それと、体力を無駄扱いするんじゃない」",
          DialogueId = 6200105,
          GUID = "0F8574BA",
          NextDialogue = 6200106,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200106] = {
          ContentJP = "「全然平気よ！隊長みたいに重い剣と盾持ってないから」\n少女は軽やかに拳銃を指でくるりと回した。\n「そういえば、なんでここが『聖湖』なの？<Default note=\"text:エジュウ\">穢獣</>とか気味の悪い幻影ばっかで、あまり神聖な感じとかしないんだけど」",
          DialogueId = 6200106,
          GUID = "0F8574E4",
          NextDialogue = 6200107,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200107] = {
          ContentJP = "「ケイシー、言葉を慎め」\n杖を握った男性のカロン司祭が厳しく言い放つ。\n「聖湖は神に選ばれし者が恩寵を受ける聖地だ。今は闇に穢されているが、我々がエリュシオンの一翼である以上、畏敬の念を忘れるな」",
          DialogueId = 6200107,
          GUID = "0F85750E",
          NextDialogue = 6200108,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200108] = {
          ContentJP = "四人の最後の一人──マントを羽織り、長弓を背負った女術師は彼の言葉に苦笑した。黒いフードに顔を隠され、表情は見えない。",
          DialogueId = 6200108,
          GUID = "0F857538",
          NextDialogue = 6200109,
          RougeTalkActorType = 3
        },
        [6200109] = {
          ContentJP = "気まずさを解消しようとしたのか、隊長の青年は口を開いたが、何も言えずにいた。そんな時、彼はあなたに気づいた。",
          DialogueId = 6200109,
          GUID = "0F857562",
          NextDialogue = 6200110,
          RougeTalkActorType = 3
        },
        [6200110] = {
          ContentJP = "「…あなたは騎士団の方ではなさそうですね。もしかして、迷い込まれた平民でしょうか？」",
          DialogueId = 6200110,
          GUID = "0F85758C",
          NextOptions = {
            [1] = 6200111
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200111] = {
          ContentJP = "私は旅人だ",
          DialogueId = 6200111,
          GUID = "0F8575B6",
          NextDialogue = 6200112,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200112] = {
          ContentJP = "「旅人…？」青年は一瞬困惑したような表情を見せたが、すぐに穏やかな忠告口調に戻った。「…お気づきかもしれませんが、ここはエリュシオンの聖地であり、ある事情で非常に危険な場所になってしまったんです。旅行に適した場所ではないと思いますが」",
          DialogueId = 6200112,
          GUID = "0F8575E0",
          NextDialogue = 6200113,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200113] = {
          ContentJP = "「私はフーリン。エリュシオン礼賛会所属、天翼騎士団の騎士です。こちらは私の仲間たち。よろしければ、この場から護衛いたしましょうか？」",
          DialogueId = 6200113,
          GUID = "0F85760A",
          NextOptions = {
            [1] = 6200114
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200114] = {
          ContentJP = "結構だ。まだ果たすべき目的がある。",
          DialogueId = 6200114,
          GUID = "0F857634",
          NextDialogue = 6200115,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200115] = {
          ContentJP = "「重ねて申し上げます。ここは聖地であると同時に立ち入り禁止の場所です。騎士として、外部の者を排除する義務があります」",
          DialogueId = 6200115,
          GUID = "0F85765E",
          NextDialogue = 6200116,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200116] = {
          ContentJP = "「…どうやって？」冷ややかな笑いと共に、マントの女術師がようやく口を開いた。「私たちだって、出口はもう分からないでしょう？」\n彼女の声は冷たく、頬を擦れた冬の雪のようだった。",
          DialogueId = 6200116,
          GUID = "0F857688",
          NextDialogue = 6200117,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char04"
        },
        [6200117] = {
          ContentJP = "「まあまあ、いいんじゃない？」金髪の女騎士がさりげなく話題を転じた。「この『お客さん』はそこそこ強そうだし、冒涜者にも見えないし。任務に差し支えなきゃ、見逃しちゃえば？」",
          DialogueId = 6200117,
          GUID = "0F8576B2",
          NextDialogue = 6200118,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200118] = {
          ContentJP = "「あ、そうだ！旅人さん。」彼女はフーリンを軽く押しのけ、あなたのすぐ前に身を寄せた。「ピンク色の長い髪で、大きな剣を持った、十三、十四歳くらいの女の子を見かけませんでしたか？」",
          DialogueId = 6200118,
          GUID = "0F8576DC",
          NextOptions = {
            [1] = 6200119
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200119] = {
          ContentJP = "…いや、見ていないけど",
          DialogueId = 6200119,
          GUID = "0F857706",
          NextDialogue = 6200120,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200120] = {
          ContentJP = "「そうですか…では、もし彼女に会ったら、<H>静寂の黄昏</>小隊が探していると伝えていただけませんか？お願いします！」",
          DialogueId = 6200120,
          GUID = "0F857730",
          NextOptions = {
            [1] = 6200121
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200121] = {
          ContentJP = "なぜ彼女を探してる？",
          DialogueId = 6200121,
          GUID = "0F85775A",
          NextDialogue = 6200122,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200122] = {
          ContentJP = "「えっと…ちょっと説明しづらいですが、彼女は一応、私たちの…指揮官みたいな人で。あんまり詳しく喋ると、ミルトンにまた怒られてしまいます」",
          DialogueId = 6200122,
          GUID = "0F857784",
          NextDialogue = 6200123,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char01"
        },
        [6200123] = {
          ContentJP = "「分かっているなら余計なことを言うな。」司祭は眉をひそめた。「これ以上無用な混乱を招くな。任務に集中しろ。さあ、出発しよう」",
          DialogueId = 6200123,
          GUID = "0F8577AE",
          NextDialogue = 6200124,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char03"
        },
        [6200124] = {
          ContentJP = "「本当に助けは要らないんですか？」青年は心配そうにあなたを見た。「ここは本当に危ない場所です。もしよければ、私たちと一緒に」",
          DialogueId = 6200124,
          GUID = "0F8577D8",
          NextOptions = {
            [1] = 6200125
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200125] = {
          ContentJP = "本当に大丈夫だ。",
          DialogueId = 6200125,
          GUID = "0F857802",
          NextDialogue = 6200126,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200126] = {
          ContentJP = "「…わかりました。そこまでおっしゃるのであれば」",
          DialogueId = 6200126,
          GUID = "0F85782C",
          NextOptions = {
            [1] = 6200127
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200127] = {
          ContentJP = "そんなに危険なら、あなたたちは怖くないのか？",
          DialogueId = 6200127,
          GUID = "0F857856",
          IsKeyOption = true,
          NextDialogue = 6200128,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200128] = {
          ContentJP = "「信仰があれば、恐れるものなどありません。」青年は確信に満ちた微笑みを浮かべた。「では、縁があればまたどこかで。満月の神があなたの旅路を護られますように」",
          DialogueId = 6200128,
          GUID = "0F857880",
          NextDialogue = 6200129,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent11_Char02"
        },
        [6200129] = {
          ContentJP = "騎士たちは去り、あなたの目の前には再び果てしない霧だけが広がっていた。",
          DialogueId = 6200129,
          GUID = "0F8578AA",
          RougeTalkActorType = 3
        },
        [6200201] = {
          ContentJP = "若き女騎士が闇の中から現れた。金色の髪は、まるで流れてきた灯りのように混沌を照らした。\n彼女は前回会った時とは少し違っていた――裾には幾筋もの傷が増え、赤黒い染みがついている。",
          DialogueId = 6200201,
          GUID = "0F85847A",
          NextDialogue = 6200202,
          RougeTalkActorType = 3
        },
        [6200202] = {
          ContentJP = "「あら、旅人さん！また会えましたね！」彼女は少し疲れているようだったが、それでも元気に手を振ってくれた。",
          DialogueId = 6200202,
          GUID = "0F8584A4",
          NextOptions = {
            [1] = 6200203
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200203] = {
          ContentJP = "あなたの仲間たちは？",
          DialogueId = 6200203,
          GUID = "0F8584CE",
          NextDialogue = 6200204,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200204] = {
          ContentJP = "「それは…さっき、たくさんの<Default note=\"text:エジュウ\">穢獣</>や、幽霊――あの闇の影みたいなのに遭遇して…」",
          DialogueId = 6200204,
          GUID = "0F8584F8",
          NextDialogue = 6200205,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200205] = {
          ContentJP = "「必死で追い払ったんですけど、気がついたら1人になっていて…どこかで見かけませんでしたか？」",
          DialogueId = 6200205,
          GUID = "0F858522",
          NextOptions = {
            [1] = 6200206
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200206] = {
          ContentJP = "いや、会ってない",
          DialogueId = 6200206,
          GUID = "0F85854C",
          NextDialogue = 6200207,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200207] = {
          ContentJP = "ケイシーの瞳に瞬く光が消えた。まるで雲が流れ、太陽を遮ってしまったように見える。",
          DialogueId = 6200207,
          GUID = "0F858576",
          NextDialogue = 6200208,
          RougeTalkActorType = 3
        },
        [6200208] = {
          ContentJP = "「フーリンはいつも、戦う時は隊列を保ち、互いの後ろを守れ、とかうるさく言ってたのに…私、もっとちゃんと聞いておけばよかった」",
          DialogueId = 6200208,
          GUID = "0F8585A0",
          NextDialogue = 6200209,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200209] = {
          ContentJP = "「聖湖がこんな場所だなんて知りませんでした。普段なら迷子になってもすぐ見つかるのに……さっき通ったばかりの道も、振り返ると全然違う景色になっていることもあって。まるで…」\n彼女は拳を握りしめた。\n「まるで、あの影がみんなを連れ去ってしまったみたいです。跡形さえも残さずに」",
          DialogueId = 6200209,
          GUID = "0F8585CA",
          NextOptions = {
            [1] = 6200210
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200210] = {
          ContentJP = "心配しないで、きっとまた会える。私に会えたように",
          DialogueId = 6200210,
          GUID = "0F8585F4",
          NextDialogue = 6200211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200211] = {
          ContentJP = "ケイシーは驚いたように瞬き、しばらくあなたを見つめた。",
          DialogueId = 6200211,
          GUID = "0F85861E",
          NextDialogue = 6200212,
          RougeTalkActorType = 3
        },
        [6200212] = {
          ContentJP = "「私たち…前にも会ったことあります？」\n彼女の明るい瞳には、あなたの姿が映っていた。しかしその顔は、どこか見覚えのないものに思えた。",
          DialogueId = 6200212,
          GUID = "0F858648",
          NextDialogue = 6200213,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200213] = {
          ContentJP = "「なんだか、すごく懐かしい感じがします――前回会った時ではなくて、もっと前、聖湖に来る前から…」",
          DialogueId = 6200213,
          GUID = "0F858672",
          NextOptions = {
            [1] = 6200214
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200214] = {
          ContentJP = "それは錯覚だろう",
          DialogueId = 6200214,
          GUID = "0F85869C",
          NextDialogue = 6200215,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200215] = {
          ContentJP = "「…そうですね」\n彼女は口元を緩めて笑った。雲の隙間から零れる太陽の光のように、かすかに輝きを見せた。",
          DialogueId = 6200215,
          GUID = "0F8586C6",
          NextDialogue = 6200216,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200216] = {
          ContentJP = "「みんなとはぐれてから、ずっと一人で歩いてきましたから。あなたに会わなかったら、神罰で地獄に落ちたのかと思ってしまうぐらいでした」",
          DialogueId = 6200216,
          GUID = "0F8586F0",
          NextDialogue = 6200217,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200217] = {
          ContentJP = "「多分<H>命あるもの</>の気配が、ただ懐かしかったのかもしれません」",
          DialogueId = 6200217,
          GUID = "0F85871A",
          NextOptions = {
            [1] = 6200218
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200218] = {
          ContentJP = "早く仲間と再会できるといいね",
          DialogueId = 6200218,
          GUID = "0F858744",
          IsKeyOption = true,
          NextDialogue = 6200219,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200219] = {
          ContentJP = "「うん、ありがとう！大丈夫、みんな強い騎士ばかりですから。私がいなくても平気です。早くみんなを探さないと…」",
          DialogueId = 6200219,
          GUID = "0F85876E",
          NextDialogue = 6200220,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        },
        [6200220] = {
          ContentJP = "「ではまた、旅人さん。あなたの目的も果たされますように」",
          DialogueId = 6200220,
          GUID = "0F858798",
          NextDialogue = 6200221,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent12_Char01"
        }
      }
    end
  },
  {
    MinKey = 6200221,
    MaxKey = 6201602,
    Loader = function()
      return {
        [6200221] = {
          ContentJP = "ケイシーは手を振り、去っていった。\n周りは再び暗闇に包まれ、永遠の夜のような空間に戻った。",
          DialogueId = 6200221,
          GUID = "0F8587C2",
          RougeTalkActorType = 3
        },
        [6200301] = {
          ContentJP = "瓦礫の山、またしても廃墟と化した光景。\n深淵で幾度も目にした、ありふれた情景に過ぎない――。",
          DialogueId = 6200301,
          GUID = "0F8594E2",
          NextDialogue = 6200302,
          RougeTalkActorType = 3
        },
        [6200302] = {
          ContentJP = "崩れ落ちた建築の残骸だけでなく、二度と握られることのない武器、瓦礫の下にかすかに横たわる、息の絶えた躯。血の匂い、塵の気配。\n見慣れすぎた光景だ。自らの意志かどうかは関係なく、ただ聖湖に捧げられた魂の数、それだけだ。",
          DialogueId = 6200302,
          GUID = "0F85950C",
          NextDialogue = 6200303,
          RougeTalkActorType = 3
        },
        [6200303] = {
          ContentJP = "ふと、血に染まった徽章が目に留まった――あのアイリスの紋様は、つい最近見たことのあるものだ。",
          DialogueId = 6200303,
          GUID = "0F859536",
          NextDialogue = 6200304,
          RougeTalkActorType = 3
        },
        [6200304] = {
          ContentJP = "瓦礫を払いのけると、血まみれの長剣が現れた。まっすぐ地面に突き立てられたその剣は、おそらく最後まで倒れることを拒み、無駄な抵抗を続けていた者の意志の表れだろう。",
          DialogueId = 6200304,
          GUID = "0F859560",
          NextDialogue = 6200305,
          RougeTalkActorType = 3
        },
        [6200305] = {
          ContentJP = "そして、砕けた杖、散り乱れた矢、壊れた拳銃。\n今、あなたはこれらの魂の名を知った。",
          DialogueId = 6200305,
          GUID = "0F85958A",
          NextDialogue = 6200306,
          RougeTalkActorType = 3
        },
        [6200306] = {
          ContentJP = "「信仰があれば、恐れるものなどありません。」――最期の瞬間、彼らの信じたものは、少しでも死の苦しみを和らげてくれたのだろうか？\nあなたにはわからない。知る必要もない。",
          DialogueId = 6200306,
          GUID = "0F8595B4",
          NextDialogue = 6200307,
          RougeTalkActorType = 3
        },
        [6200307] = {
          ContentJP = "時計の針が次に進めば、これらすべては消え去るのだから。\n弔いも祈りも無意味であり、あなたは時間を費やすつもりもない。亡き者の目を閉じると、そのまま踵を返そうとした。",
          DialogueId = 6200307,
          GUID = "0F8595DE",
          NextDialogue = 6200308,
          RougeTalkActorType = 3
        },
        [6200308] = {
          ContentJP = "「早くみんなを探さないと…」\n少女の声が突然、脳裏に響いた。何かを呼び覚ますように、何かを促すように。",
          DialogueId = 6200308,
          GUID = "0F859608",
          NextDialogue = 6200309,
          RougeTalkActorType = 3
        },
        [6200309] = {
          ContentJP = "再び廃墟へ視線を向かせた途端、今度はささやかな違和感を感じた――\n四人の若き騎士たちの体はすでに冷たくなっているが、ケイシーだけは服に黒い煤が付いていない。\n彼女の体には、乾ききった血とまだ乾き切っていない<Default note=\"text:エジュウ\">穢獣</>の血が、幾重にも重なっていた。",
          DialogueId = 6200309,
          GUID = "0F859632",
          NextOptions = {
            [1] = 6200310
          },
          RougeTalkActorType = 3
        },
        [6200310] = {
          ContentJP = "あなたは悟った。彼女も、あなたと同じように間に合わなかったのだ。",
          DialogueId = 6200310,
          GUID = "0F85965C",
          IsKeyOption = true,
          NextDialogue = 6200311,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200311] = {
          ContentJP = "仲間を見つけた時、すでに彼らは廃墟の中で、原型もわからない残骸と化していた。",
          DialogueId = 6200311,
          GUID = "0F859686",
          NextDialogue = 6200312,
          RougeTalkActorType = 3
        },
        [6200312] = {
          ContentJP = "だから彼女はここに留まり、進むことをやめ、一度は離れ離れになった仲間たちを守り、最期の瞬間まで戦い続けたのだ。\n仲間の死骸を守るためだったのか？「見捨てた」仲間への贖罪だったのか？騎士としての信条を貫くためだったのか？\nそれとも、長き闇がついに彼女の最後の希望を奪い、死の慈悲を乞うことしかできなくなったのか？",
          DialogueId = 6200312,
          GUID = "0F8596B0",
          NextDialogue = 6200313,
          RougeTalkActorType = 3
        },
        [6200313] = {
          ContentJP = "彼女はもう、その問いには答えてくれない。",
          DialogueId = 6200313,
          GUID = "0F8596DA",
          RougeTalkActorType = 3
        },
        [6200401] = {
          ContentJP = "若者たちの話す声が、ほど遠くない場所から聞こえてくる。こんな声を深淵で聞くのは久しぶりだ──熱烈で、元気あふれる、まだ深淵の闇に侵されていない声。",
          DialogueId = 6200401,
          GUID = "0F85A54A",
          NextDialogue = 6200402,
          RougeTalkActorType = 3
        },
        [6200402] = {
          ContentJP = "あなたはその正体を知っている。",
          DialogueId = 6200402,
          GUID = "0F85A574",
          NextDialogue = 6200403,
          RougeTalkActorType = 3
        },
        [6200403] = {
          ContentJP = "思わず声のする方へ足を向ける。周囲を覆っていた霧が薄れ、四人の若き騎士たちの姿が見えた。\n装備や服装にはまだ塵一つ付いておらず、身に着けた聖アイリスの紋章も輝くばかりに磨かれ、どこからか差し込む金色の光を反射していた。",
          DialogueId = 6200403,
          GUID = "0F85A59E",
          NextDialogue = 6200404,
          RougeTalkActorType = 3
        },
        [6200404] = {
          ContentJP = "「この方向で合ってるの？隊長」\n金髪の女騎士は古びた階段を駆け上がり、軽やかに飛び降りた。\n「どうやら、ただの廃墟みたい」",
          DialogueId = 6200404,
          GUID = "0F85A5C8",
          NextDialogue = 6200405,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200405] = {
          ContentJP = "「少なくとも、来たことがない場所だ」\n隊長と呼ばれた青年騎士は落ち着いた足取りで彼女の横を通り過ぎる。\n「聖湖では方向を見失いやすい。今は一歩ずつ進むしかない」",
          DialogueId = 6200405,
          GUID = "0F85A5F2",
          NextDialogue = 6200406,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200406] = {
          ContentJP = "「それから──そんなに跳ね回って疲れないのか、ケイシー？」\n元気すぎる仲間を見て、青年はため息をついた。\n「危険な場所なんだから、気を引き締めろ。それと、体力を無駄扱いするんじゃない」",
          DialogueId = 6200406,
          GUID = "0F85A61C",
          NextDialogue = 6200407,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200407] = {
          ContentJP = "「全然平気よ！隊長みたいに──」",
          DialogueId = 6200407,
          GUID = "0F85A646",
          NextOptions = {
            [1] = 6200408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200408] = {
          ContentJP = "彼の言う通りだ。",
          DialogueId = 6200408,
          GUID = "0F85A670",
          NextDialogue = 6200409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200409] = {
          ContentJP = "少女は言葉を遮られ、ぽかんとこちらの方を向いた。",
          DialogueId = 6200409,
          GUID = "0F85A69A",
          NextDialogue = 6200410,
          RougeTalkActorType = 3
        },
        [6200410] = {
          ContentJP = "「あの、あなたは…？」",
          DialogueId = 6200410,
          GUID = "0F85A6C4",
          NextOptions = {
            [1] = 6200411
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200411] = {
          ContentJP = "旅人だ。あなたたちより長くここにいるから、信じてほしい。ここは想像以上に危険なところだ",
          DialogueId = 6200411,
          GUID = "0F85A6EE",
          NextDialogue = 6200412,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200412] = {
          ContentJP = "「旅人……？」青年の顔に一瞬困惑が浮かぶ、前回会った時と同じように。「しかし、ここはエリュシオンの聖地…どうやって？",
          DialogueId = 6200412,
