        [6200416] = {
          ContentJP = "「どうやらあなたは、私たちの知らない真実を知っているようですね。この深淵についての」",
          DialogueId = 6200416,
          GUID = "0F85A7C0",
          NextDialogue = 6200417,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char03"
        },
        [6200417] = {
          ContentJP = "「カリスタ…！それは異端者の言葉だ！ここは聖湖──聖湖なのだ！」",
          DialogueId = 6200417,
          GUID = "0F85A7EA",
          NextDialogue = 6200418,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char04"
        },
        [6200418] = {
          ContentJP = "カリスタは司祭の叱責を無視し、じっとあなたを見つめ、あなたの回答を待っていた。",
          DialogueId = 6200418,
          GUID = "0F85A814",
          NextDialogue = 6200419,
          RougeTalkActorType = 3
        },
        [6200419] = {
          ContentJP = "あなたは何と答えるべきか──何と答えられるのか？",
          DialogueId = 6200419,
          GUID = "0F85A83E",
          NextDialogue = 6200420,
          RougeTalkActorType = 3
        },
        [6200420] = {
          ContentJP = "引き返せと告げるのか？だが彼らの信仰がそれを許さないことは承知の上だ。\n信仰とは、なんと重い言葉だろう。見知らぬ旅人や、変わり果てた旧知の忠告などより、はるかに重い。",
          DialogueId = 6200420,
          GUID = "0F85A868",
          NextDialogue = 6200421,
          RougeTalkActorType = 3
        },
        [6200421] = {
          ContentJP = "信仰の光の中で育った者にとって、余計な真実は光による火傷のようなもの。白昼の入れ墨のように──心に永遠の苦痛を刻みつける。",
          DialogueId = 6200421,
          GUID = "0F85A892",
          NextDialogue = 6200422,
          RougeTalkActorType = 3
        },
        [6200422] = {
          ContentJP = "あなたは首を振り、彼女の視線を避けた。",
          DialogueId = 6200422,
          GUID = "0F85A8BC",
          NextOptions = {
            [1] = 6200423
          },
          RougeTalkActorType = 3
        },
        [6200423] = {
          ContentJP = "深淵では迷いやすい。はぐれないよう気をつけて、ケイシー",
          DialogueId = 6200423,
          GUID = "0F85A8E6",
          NextDialogue = 6200424,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200424] = {
          ContentJP = "「え？なんで私だけ名指し？」",
          DialogueId = 6200424,
          GUID = "0F85A910",
          NextDialogue = 6200425,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200425] = {
          ContentJP = "「少し反省しろ。他人から見ても、お前が一番落ち着きがないのが分かる」",
          DialogueId = 6200425,
          GUID = "0F85A93A",
          NextDialogue = 6200426,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200426] = {
          ContentJP = "「そんな──だってはぐれてもすぐ見つけるもん」",
          DialogueId = 6200426,
          GUID = "0F85A964",
          NextOptions = {
            [1] = 6200427
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char01"
        },
        [6200427] = {
          ContentJP = "いつもそううまくいくとは限らない",
          DialogueId = 6200427,
          GUID = "0F85A98E",
          IsKeyOption = true,
          NextDialogue = 6200428,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200428] = {
          ContentJP = "ケイシーは凍りついた。あなたの真剣な口調に驚いたのだろう。",
          DialogueId = 6200428,
          GUID = "0F85A9B8",
          NextDialogue = 6200429,
          RougeTalkActorType = 3
        },
        [6200429] = {
          ContentJP = "そこへフーリンが前に出た。明らかに、彼は有能なエリュシオン騎士だった。優秀な騎士にとって、純粋な信仰と同様に慎重さも美徳となる──好奇心を、情報を得られるぎりぎりの線で抑える術を知っている。例えば聖堂で、常に閉ざされていた扉が隙間を見せた時、彼は足を止め、背を向け、何も見なかったふりをするのが最善だと知っている。",
          DialogueId = 6200429,
          GUID = "0F85A9E2",
          NextDialogue = 6200430,
          RougeTalkActorType = 3
        },
        [6200430] = {
          ContentJP = "「あなたが何者かは知りませんが、どうやらそれぞれに進むべき道があるようです。私たちにはまだ任務がありますので、これで」彼は丁寧に礼をすると、「満月の神があなたの旅路を護られますように」",
          DialogueId = 6200430,
          GUID = "0F85AA0C",
          NextDialogue = 6200431,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent21_Char02"
        },
        [6200431] = {
          ContentJP = "騎士たちは去り、あなたの目の前には再び果てしない霧だけが広がっていた。",
          DialogueId = 6200431,
          GUID = "0F85AA36",
          RougeTalkActorType = 3
        },
        [6200501] = {
          ContentJP = "絶え間ない戦いが、あなたの力を搾り尽くした。\n最後の一片の燼すらも、指の隙間から零れ落ち、あなたは完全に方向を見失った。",
          DialogueId = 6200501,
          GUID = "0F85B5B2",
          NextDialogue = 6200502,
          RougeTalkActorType = 3
        },
        [6200502] = {
          ContentJP = "ランタンが地面に転がり、瑠璃が砕ける音が静寂の闇を切り裂く。\n粉々に砕けた闇が四方八方から押し寄せ、あなたの体を侵食し、神経を蝕み始める。",
          DialogueId = 6200502,
          GUID = "0F85B5DC",
          NextDialogue = 6200503,
          RougeTalkActorType = 3
        },
        [6200503] = {
          ContentJP = "全ての感覚が闇と一体化した時、あなたは突然抵抗をやめた。闇が優しくあなたを包み、傷口を撫でて、疲れを癒してくれるのを感じた。",
          DialogueId = 6200503,
          GUID = "0F85B606",
          NextDialogue = 6200504,
          RougeTalkActorType = 3
        },
        [6200504] = {
          ContentJP = "これが正しい結末なのかもしれない。闇が囁く声が聞こえるようだった──\n「ここまでよく頑張った、もう十分だ」",
          DialogueId = 6200504,
          GUID = "0F85B630",
          NextDialogue = 6200505,
          RougeTalkActorType = 3
        },
        [6200505] = {
          ContentJP = "そうだ…あなたは十分に戦った。孤独な輪廻の中で、必死に戦い、もがき、果てしない苦痛を味わい、絶望を美酒として飲み干した。それでも希望の光には届かなかった。",
          DialogueId = 6200505,
          GUID = "0F85B65A",
          NextDialogue = 6200506,
          RougeTalkActorType = 3
        },
        [6200506] = {
          ContentJP = "あなたは疲れた。もう終わりにしよう。",
          DialogueId = 6200506,
          GUID = "0F85B684",
          NextDialogue = 6200507,
          RougeTalkActorType = 3
        },
        [6200507] = {
          ContentJP = "暗闇の揺り籠で眠りに落ちそうになったその時、意識の奥に遠い人影が浮かんだ──実際にはもうその姿を正確に覚えていなかったが、このかすかな思いが、鈍りかけた血肉を切り裂くようにあなたを目覚めさせた。それは思考の海をかき乱し、高波を起こす。",
          DialogueId = 6200507,
          GUID = "0F85B6AE",
          NextDialogue = 6200508,
          RougeTalkActorType = 3
        },
        [6200508] = {
          ContentJP = "闇に打ち勝ち、深淵を共に脱すると約束した者。そして、あなたの全ての苦痛の元凶となった者。",
          DialogueId = 6200508,
          GUID = "0F85B6D8",
          NextDialogue = 6200509,
          RougeTalkActorType = 3
        },
        [6200509] = {
          ContentJP = "あなたはまだその者を見つけていない──そうだ、思い出した。\nここで眠ってはいけない。闇の誘いがどれほど魅力的でも、それはあなたの望む結末ではない。\nあなたは戦い続けなければならない。終着点に辿り着くため、約束を果たすため──この不合理な輪廻を断ち切るために。",
          DialogueId = 6200509,
          GUID = "0F85B702",
          NextOptions = {
            [1] = 6200510
          },
          RougeTalkActorType = 3
        },
        [6200510] = {
          ContentJP = "文字盤を回す",
          DialogueId = 6200510,
          GUID = "0F85B72C",
          IsKeyOption = true,
          NextDialogue = 6200511,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200511] = {
          ContentJP = "そうしてあなたは再び、ランタンの文字盤に手を伸ばした。物語の始まりへ。",
          DialogueId = 6200511,
          GUID = "0F85B756",
          RougeTalkActorType = 3
        },
        [6200601] = {
          ContentJP = "深淵の中では方向が常に変化し続け、前進しているのか後退しているのかさえ判別できないことが多い。\n時には、終わりなき螺旋に囚われ、空しく回り続けているだけのようにさえ感じる。果てなど決して訪れはしないのだと。",
          DialogueId = 6200601,
          GUID = "0F85C61A",
          NextDialogue = 6200602,
          RougeTalkActorType = 3
        },
        [6200602] = {
          ContentJP = "しかし、目の前に現れたこの巨大な物を視界に捉えた瞬間、これが深淵の「中心」だと本能的に理解した。",
          DialogueId = 6200602,
          GUID = "0F85C644",
          NextDialogue = 6200603,
          RougeTalkActorType = 3
        },
        [6200603] = {
          ContentJP = "ランタンを掲げ、その全貌を照らそうとするが、かすかな光は境界に触れた途端、容赦なく吞み込まれる。\n周りの混沌とした闇は濁流のように渦巻き、一つの終着点へ向かって流れ込んでいく。",
          DialogueId = 6200603,
          GUID = "0F85C66E",
          NextDialogue = 6200604,
          RougeTalkActorType = 3
        },
        [6200604] = {
          ContentJP = "地面が轟音と共に揺れ、足場を失ったあなたは闇の中へ転がり落ちる。\n朦朧とした意識の中で、自分の体もまたその濁流の一部となり、崩れ、溶け、全てを吞み込む存在へと流れていくように感じた。",
          DialogueId = 6200604,
          GUID = "0F85C698",
          NextDialogue = 6200605,
          RougeTalkActorType = 3
        },
        [6200605] = {
          ContentJP = "耳の奥に押し寄せる静寂が、鼓膜を圧迫する。生存本能が今すぐ引き返せと告げている。",
          DialogueId = 6200605,
          GUID = "0F85C6C2",
          NextOptions = {
            [1] = 6200606,
            [2] = 6200615
          },
          RougeTalkActorType = 3
        },
        [6200606] = {
          ContentJP = "混沌を見つめ続ける",
          DialogueId = 6200606,
          GUID = "0F85C6EC",
          IsKeyOption = true,
          NextDialogue = 6200607,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200607] = {
          ContentJP = "あなたは退かなかった。\n闇の中から体を起こし、顔を上げ、ランタンを握りしめて、得体も知れない存在に宣言する。恐れてはいないと。",
          DialogueId = 6200607,
          GUID = "0F85C716",
          NextDialogue = 6200608,
          RougeTalkActorType = 3
        },
        [6200608] = {
          ContentJP = "徐々に、何かが周りの混沌を打ち破り、深淵の底から幾つかの何かがあなたの心臓へ逆流してくるのを感じた――不思議なことに、あなたはそれを理解できた。",
          DialogueId = 6200608,
          GUID = "0F85C740",
          NextDialogue = 6200609,
          RougeTalkActorType = 3
        },
        [6200609] = {
          ContentJP = "それは人間の感情だった。疑念、怒り、苦痛、絶望、そして…悲しみ。圧倒的な悲しみ。\nまるで深淵そのものが、終焉を求めているかのようだ。",
          DialogueId = 6200609,
          GUID = "0F85C76A",
          NextDialogue = 6200610,
          RougeTalkActorType = 3
        },
        [6200610] = {
          ContentJP = "「どうすれば助けられる？」心の中で問いかける。",
          DialogueId = 6200610,
          GUID = "0F85C794",
          NextDialogue = 6200611,
          RougeTalkActorType = 3
        },
        [6200611] = {
          ContentJP = "そのランタンではまだ足りない。旅を続けなさいとそれは言った。輪廻の果てで、答えは見つかる。",
          DialogueId = 6200611,
          GUID = "0F85C7BE",
          NextDialogue = 6200612,
          RougeTalkActorType = 3
        },
        [6200612] = {
          ContentJP = "「果てはどこだ？」",
          DialogueId = 6200612,
          GUID = "0F85C7E8",
          NextDialogue = 6200613,
          RougeTalkActorType = 3
        },
        [6200613] = {
          ContentJP = "問いには答えず、闇が優しくあなたを包み込む。視界に残るのはランタンの光だけだった。",
          DialogueId = 6200613,
          GUID = "0F85C812",
          NextDialogue = 6200614,
          RougeTalkActorType = 3
        },
        [6200614] = {
          ContentJP = "そうしてあなたは、再びランタンの文字盤を回した。",
          DialogueId = 6200614,
          GUID = "0F85C83C",
          RougeTalkActorType = 3
        },
        [6200615] = {
          ContentJP = "引き返す",
          DialogueId = 6200615,
          GUID = "0F85C866",
          IsKeyOption = true,
          NextDialogue = 6200616,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200616] = {
          ContentJP = "賢明な選択だ。\n振り向き、方向を変え、歩み出す。本能が逃げるよう促す――たとえ来た道がもうないと知っていても。",
          DialogueId = 6200616,
          GUID = "0F85C890",
          NextDialogue = 6200617,
          RougeTalkActorType = 3
        },
        [6200617] = {
          ContentJP = "ふと、背後から視線を感じた。その目は無言であなたを見届けている。去りゆくあなたに悲しみを覚えているようだ。",
          DialogueId = 6200617,
          GUID = "0F85C8BA",
          NextDialogue = 6200618,
          RougeTalkActorType = 3
        },
        [6200618] = {
          ContentJP = "「戻ってほしいのか？」心の中で問う。",
          DialogueId = 6200618,
          GUID = "0F85C8E4",
          NextDialogue = 6200619,
          RougeTalkActorType = 3
        },
        [6200619] = {
          ContentJP = "いや、あなたは自分の道を進めとそれは言った。輪廻の果てで、また会おうと。",
          DialogueId = 6200619,
          GUID = "0F85C90E",
          NextDialogue = 6200620,
          RougeTalkActorType = 3
        },
        [6200620] = {
          ContentJP = "「果てはどこだ？」また問う。",
          DialogueId = 6200620,
          GUID = "0F85C938",
          NextDialogue = 6200621,
          RougeTalkActorType = 3
        },
        [6200621] = {
          ContentJP = "答えはなく、闇が肩越しに優しく空間を満たす。視界に残るのはランタンの光だけだった。",
          DialogueId = 6200621,
          GUID = "0F85C962",
          NextDialogue = 6200622,
          RougeTalkActorType = 3
        },
        [6200622] = {
          ContentJP = "そうしてあなたは、再び提灯の文字盤を回し、再び時間を巻き戻す。",
          DialogueId = 6200622,
          GUID = "0F85C98C",
          RougeTalkActorType = 3
        },
        [6200701] = {
          ContentJP = "謎の青年が焚き火の隣に立っている。実際のところ、あなたは彼の年齢をはっきりと知らない。ただ声から判断しているだけだ。\n彼に会うのは、これが初めてではない。",
          DialogueId = 6200701,
          GUID = "0F85D682",
          NextDialogue = 6200702,
          RougeTalkActorType = 3
        },
        [6200702] = {
          ContentJP = "「また会ったね、勇敢な旅人さん。」",
          DialogueId = 6200702,
          GUID = "0F85D6AC",
          NextDialogue = 6200703,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200703] = {
          ContentJP = "青年は丁寧にあなたに挨拶をした。\nあなたは彼の目が見えないことに気づいたーーその顔の上半分を、鋭い輪郭の金属製の仮面が完全に覆っていたからだ。",
          DialogueId = 6200703,
          GUID = "0F85D6D6",
          NextDialogue = 6200704,
          RougeTalkActorType = 3
        },
        [6200704] = {
          ContentJP = "「深淵で長く歩いていた人のほとんどは、道を見失って最後には暗影の一部になってしまんのだ。」「ここから放たれる<H>光</>は、あなたの道しるべとなって前へと導いてくれるだろう。」「あなたはそれらをランタンの中に入れて、キャンドルの芯として使ってもいいよ。」と青年は言った。\n金属製の仮面に反射した焚き火の明かりが、まるで彼の目に宿った光のように跳ね返っていた。",
          DialogueId = 6200704,
          GUID = "0F85D700",
          NextDialogue = 6200705,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200705] = {
          ContentJP = "「まあ、これらはまだ覚えているでしょう？だって、あなたは<H>いつも</>ここにたどり着けられるものだから。」\n「前のように補給を用意しておいた。焚き火の傍に置いてあるから、好きなだけ取っていいよ。」",
          DialogueId = 6200705,
          GUID = "0F85D72A",
          NextOptions = {
            [1] = 6200706
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200706] = {
          ContentJP = "君は誰ですか？",
          DialogueId = 6200706,
          GUID = "0F85D754",
          NextDialogue = 6200707,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200707] = {
          ContentJP = "「またこの質問か？何回聞かれたかももう覚えていない。悪いけど、今の私なら、この質問には答えられない。」青年は軽く笑った。\n「隠そうしているわけじゃない。ただ......自分自身もわからないんだ。今の私は、いったい何者になるべきなのかってね。」",
          DialogueId = 6200707,
          GUID = "0F85D77E",
          NextDialogue = 6200708,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200708] = {
          ContentJP = "「だから、お互いも気楽にしてほしいんだーー今のあなたにとっては、私はただ、どこにでもいる<H>行商人</>にすぎないからな。」\n「あなたがいつも言う『私はただの旅人だ』ってのと、同じようなもんだよ。」",
          DialogueId = 6200708,
          GUID = "0F85D7A8",
          NextOptions = {
            [1] = 6200709
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200709] = {
          ContentJP = "そろそろ出発しないと。",
          DialogueId = 6200709,
          GUID = "0F85D7D2",
          IsKeyOption = true,
          NextDialogue = 6200710,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200710] = {
          ContentJP = "「さよなら、勇敢な旅人さんよ。」「あなたの旅路に、いつも灯りがそいますように」\n仮面ではその表情は見えないが、その下の瞳には、揺らめく灯りが映っているに違いない。",
          DialogueId = 6200710,
          GUID = "0F85D7FC",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200801] = {
          ContentJP = "謎の行商人は、前のように焚き火の傍に佇んでいる。\nここにあったのは、暗影の咆哮ではなく、静寂のみだった。",
          DialogueId = 6200801,
          GUID = "0F85E6EA",
          NextDialogue = 6200802,
          RougeTalkActorType = 3
        },
        [6200802] = {
          ContentJP = "「また会ったね、彷徨う旅人さん。」\n「微かな<H>光</>があなたを招いたのかい。」\n行商人はいつものように、波一つもない湖面のような穏やかな声で話した。\n「このランタンの芯を交換するために、ずっとここで待ってたんだ。」",
          DialogueId = 6200802,
          GUID = "0F85E714",
          NextOptions = {
            [1] = 6200803
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200803] = {
          ContentJP = "直接私に渡してくれればいいじゃないか。",
          DialogueId = 6200803,
          GUID = "0F85E73E",
          NextDialogue = 6200804,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200804] = {
          ContentJP = "「あなたの見た通り、今の私はそのような力を持っていない。」\n行商人は首を振りながら、言った。\n「今の私にできるのは、わずかな魔法を使って、灰の残骸を微かに光るキャンドルの芯へと変えることだけだ。」",
          DialogueId = 6200804,
          GUID = "0F85E768",
          NextDialogue = 6200805,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200805] = {
          ContentJP = "謎の行商人にランタンを渡した。\n灰となった残骸は、その手の中で、飛び交う蛍のように次第に明るくなり、ついに明るく光るキャンドルの芯へと変わった。",
          DialogueId = 6200805,
          GUID = "0F85E792",
          NextOptions = {
            [1] = 6200806
          },
          RougeTalkActorType = 3
        },
        [6200806] = {
          ContentJP = "ありがとう。",
          DialogueId = 6200806,
          GUID = "0F85E7BC",
          NextDialogue = 6200807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200807] = {
          ContentJP = "あなたは手元のランタンを揺さぶったーー芯を替えたキャンドルから放たれる光が、前よりも明るくなったようだ。このランタンは、あなたのたったひとつの仲間として、この暗くて底も見えない深淵の中で、あなたが迷子にならないように守ってくれている。",
          DialogueId = 6200807,
          GUID = "0F85E7E6",
          NextOptions = {
            [1] = 6200808
          },
          RougeTalkActorType = 3
        },
        [6200808] = {
          ContentJP = "そろそろ出発するのだ。",
          DialogueId = 6200808,
          GUID = "0F85E810",
          IsKeyOption = true,
          NextDialogue = 6200809,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200809] = {
          ContentJP = "「さよなら、勇敢な旅人さんよ、あなたの旅路に、いつも灯りがそいますように」と彼は言った。",
          DialogueId = 6200809,
          GUID = "0F85E83A",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200901] = {
          ContentJP = "もう一度、あなたはここに戻ってきた。\nこの暗闇の中で、どこかにすこし安堵を感じられるとしたら、それはまさにここだ......",
          DialogueId = 6200901,
          GUID = "0F85F752",
          NextOptions = {
            [1] = 6200902
          },
          RougeTalkActorType = 3
        },
        [6200902] = {
          ContentJP = "君はまだここにいる。",
          DialogueId = 6200902,
          GUID = "0F85F77C",
          NextDialogue = 6200903,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200903] = {
          ContentJP = "「そうだ。」\n行商人はいつものような静かで優しい声で答えた。\n「あなたがこの暗闇を終わらせるまで、いつもここにいて協力するから。」",
          DialogueId = 6200903,
          GUID = "0F85F7A6",
          NextOptions = {
            [1] = 6200904
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200904] = {
          ContentJP = "しかし、私を覚えてくれるのは君だけだ。",
          DialogueId = 6200904,
          GUID = "0F85F7D0",
          NextDialogue = 6200905,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200905] = {
          ContentJP = "「深淵の......あの幽霊たち、あと数人ーー文字盤を巻き戻して過去に戻ると、彼らは私のことを忘れてしまって、まるで話したこともなくて、会ったこともないようだった。」\n「たくさんの人を救ったとしても、彼らのほとんどはまた次の輪廻の中で死んでしまう。」\n「たくさんの人と出会ったとしても、結局独りぼっちだった。」",
          DialogueId = 6200905,
          GUID = "0F85F7FA",
          NextDialogue = 6200906,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200906] = {
          ContentJP = "「そうだ。深淵のすべては打ち寄せる波のように、何度も何度も昔の歳月へと押し戻されている。」\n「だが、あなたは特別だーーあの文字盤の今の持ち主として、あなたはもう時間の外に立っている。」\n言い終えると、彼はため息をついた。",
          DialogueId = 6200906,
          GUID = "0F85F824",
          NextDialogue = 6200907,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200907] = {
          ContentJP = "「この深淵の中で、あなたは時間を司っている。<H>永遠</>にいられるのはあなただけ。これこそが神権だ。」\n「しかし、この力であなたは神の座にも囚われている。つまり、あなたは自分の目であらゆるものが消えていく過程を最後まで見なければならないのだ。」\n行商人のいつも穏やかな声には、ほとんど感じ取れないほどの揺らぎが混じっていた。\n「これもまた、あなたが深淵と立ち向かえる唯一の武器だ。」",
          DialogueId = 6200907,
          GUID = "0F85F84E",
          NextOptions = {
            [1] = 6200908
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6200908] = {
          ContentJP = "そろそろ旅に出るのだ。",
          DialogueId = 6200908,
          GUID = "0F85F878",
          IsKeyOption = true,
          NextDialogue = 6200909,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6200909] = {
          ContentJP = "「さよなら、勇敢な旅人さんよ、あなたの旅路に、いつも灯りがそいますように」と彼は言った。",
          DialogueId = 6200909,
          GUID = "0F85F8A2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201001] = {
          ContentJP = "あなたはようやくしばらく息をつけるようになった。\nまとわりつく暗影も見えなく、魂の悲鳴も聞こえない。ここは確かに安全だった。\nあなたは崩れ落ちた一面の壁によりかかり、ゆっくりと腰を下ろした。",
          DialogueId = 6201001,
          GUID = "0F8607BA",
          NextOptions = {
            [1] = 6201002
          },
          RougeTalkActorType = 3
        },
        [6201002] = {
          ContentJP = "もう疲れた。",
          DialogueId = 6201002,
          GUID = "0F8607E4",
          NextDialogue = 6201003,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201003] = {
          ContentJP = "「何度も何度も繰り返して......」\n「これは自分の戦いだとわかっているけど、後どれぐらい続くのだろう。」",
          DialogueId = 6201003,
          GUID = "0F86080E",
          NextDialogue = 6201004,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201004] = {
          ContentJP = "「神の祝福ーー<H>純潔の瑠璃</>が再び集まり、ランタンが修復される時、奇跡は訪れる。」\n「あなたも、またこの闇を切り裂く光を手にするのだ。」",
          DialogueId = 6201004,
          GUID = "0F860838",
          NextOptions = {
            [1] = 6201005
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201005] = {
          ContentJP = "知りたいのはこっちじゃないんだ。",
          DialogueId = 6201005,
          GUID = "0F860862",
          NextDialogue = 6201006,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201006] = {
          ContentJP = "「ここで何年過ごしてきたんだろうーー十年？二十年？それとももっと長い間？分かっているのは、この文字盤を巻き戻した回数だけだ。」\n「でも、このランタンの光がまだあまりに微かで、今までやってきたすべてが無意味だったみたいだ。」\n「死ぬまでこのランタンを直せないならーー今まで経験してきたのは何？」\n「馬鹿馬鹿しくて意味もない悲劇だけなのか？」",
          DialogueId = 6201006,
          GUID = "0F86088C",
          NextDialogue = 6201007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201007] = {
          ContentJP = "「そうだ。」\nあなたは彼が否定しなかったのに驚いた。",
          DialogueId = 6201007,
          GUID = "0F8608B6",
          NextDialogue = 6201008,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201008] = {
          ContentJP = "「私は見ていた。何度も何度も刃を振り下ろし、暗影を追い払うあなたの後ろ姿をーーそれは、万人の職人が日ごとに巨石を磨き、神殿の礎を築く姿とそっくりだった。」\n「私は見ていた。繰り返し炎に石を投げる一人の少女の姿をーーそれは、万人の農人が毎年畑に種をまく姿と同じだった。」\n「すべての苦労は、次の同じ苦労を繰り返すために存在している。あなたと私だけでなく、深淵の魂も、地上の生者たちも、誰もがこの悲劇の輪廻から逃れられないのだ。」\n「もしこれに苦しんでいるのなら、あなたはいつでも止めることができる。そうすれば、全てを終わらせることもできるのだ。」",
          DialogueId = 6201008,
          GUID = "0F8608E0",
          NextOptions = {
            [1] = 6201009
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201009] = {
          ContentJP = "断る。",
          DialogueId = 6201009,
          GUID = "0F86090A",
          NextDialogue = 6201010,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201010] = {
          ContentJP = "すべてを終わらせるとはーー彼らのように深淵で迷い続ける幽霊になると同じ意味だ。\nあなたは、柔らかく敏感な心を持つこともなくなり、孤独に怯えたり、繰り返される不条理に苦しんだりすることもなくなるのだ。\nしかしーーそれを幸せだと言えるのだろうか？",
          DialogueId = 6201010,
          GUID = "0F860934",
          NextDialogue = 6201011,
          RougeTalkActorType = 3
        },
        [6201011] = {
          ContentJP = "「違う。」あなたは刃を再び拾い上げた。\n「私は戦い続ける。クソっタレ瑠璃も探し続けるのだ。」",
          DialogueId = 6201011,
          GUID = "0F86095E",
          NextOptions = {
            [1] = 6201012
          },
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201012] = {
          ContentJP = "そろそろ時間だ。",
          DialogueId = 6201012,
          GUID = "0F860988",
          IsKeyOption = true,
          NextDialogue = 6201013,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201013] = {
          ContentJP = "「さよなら、勇敢な旅人さんよ、あなたの旅路に、いつも灯りがそいますように」と彼は言った。",
          DialogueId = 6201013,
          GUID = "0F8609B2",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201101] = {
          ContentJP = "あなたは行商人にランタンを渡した。言葉を交わす必要もなく、二人は慣れた手つきでキャンドルの芯を交換した。\n今回は、ここに留まるつもりはない。",
          DialogueId = 6201101,
          GUID = "0F861822",
          NextOptions = {
            [1] = 6201102
          },
          RougeTalkActorType = 3
        },
        [6201102] = {
          ContentJP = "そろそろ時間だ。",
          DialogueId = 6201102,
          GUID = "0F86184C",
          IsKeyOption = true,
          NextDialogue = 6201103,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201103] = {
          ContentJP = "「待って、これを受け取ってください。」\n青年の声は背後から響いた。彼は何かをあなたに渡した。\n「これは光らないから、エンバーと交換する必要はない。」\nそれは一粒の透き通ったキャンディだ。血と灰にまみれたあなたの手の掌に静かに横たわっている。",
          DialogueId = 6201103,
          GUID = "0F861876",
          NextDialogue = 6201104,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201104] = {
          ContentJP = "あなたはキャンディーを丸ごと口に放り込んで、薄荷の味だった。薄荷のおかげで、あなたはすっきりし、人間としての感覚もようやく取り戻した。\n今のあなたが思い出したのは暗影だけではなく、空までつくタワー、いつも登りたがった柏木、皿にのせた冷やしクリーム、庭で揺れていたブランコは、一つずつ脳裏に浮かび上がってきている。\nこれは、あなたが生きてきた証だ。",
          DialogueId = 6201104,
          GUID = "0F8618A0",
          NextDialogue = 6201105,
          RougeTalkActorType = 3
        },
        [6201105] = {
          ContentJP = "では、あの謎の行商人は？彼は人間なのか？それとも幽霊？－－彼も甘い物を好むのだろうか？深淵の牢獄に囚われて苦しんでいるのだろうか？彼もかつて深淵の上ーー日差しが届く世界で真実に生きていたことがあるのだろうか？\nしかし、そんなことを考える暇はない。\nあなたは、止まることなく、戦い続けねばならないのだ。",
          DialogueId = 6201105,
          GUID = "0F8618CA",
          NextDialogue = 6201106,
          RougeTalkActorType = 3
        },
        [6201106] = {
          ContentJP = "「さよなら、勇敢な旅人さんよ、あなたの旅路に、いつも灯りがそいますように」と彼は言った。",
          DialogueId = 6201106,
          GUID = "0F8618F4",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201201] = {
          ContentJP = "最近、あなたの疲労感が段々薄くなっていた。暗影に軽く話し掛けることさえできるようになった。\nそれが、心が本当に鉄石の如く揺るぎなくなったせいなのか、それともただ崩壊寸前の兆しなのか、あなたには分からない。\nだが、少なくとも今この瞬間だけは、心地が悪くない。",
          DialogueId = 6201201,
          GUID = "0F86288A",
          NextDialogue = 6201202,
          RougeTalkActorType = 3
        },
        [6201202] = {
          ContentJP = "「私は、満月の信徒と闇月の信徒を同じ日に出くわした。」\n「一人はは光を信仰するといい、もう一人は闇に仕えていると言う。だが、笑えることに、彼らの神に興味がないと言ったら、両者とも同じ暴言を吐いたことだ。」\n「では、君はどう？信じている神はいるのか？」",
          DialogueId = 6201202,
          GUID = "0F8628B4",
          NextDialogue = 6201203,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201203] = {
          ContentJP = "「私はフサの侍者だ。」\n行商人が彼自身に関する質問に答えたのは初めてだ。\n「その名に尊重し、その慈愛に讃え、満月の輝きに賛美する。」",
          DialogueId = 6201203,
          GUID = "0F8628DE",
          NextDialogue = 6201204,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201204] = {
          ContentJP = "「私はフサの侍者だ。」\n行商人が彼自身に関する質問に答えたのは初めてだ。\n「その名に尊重し、その慈愛に讃え、満月の輝きに賛美する。」",
          DialogueId = 6201204,
          GUID = "0F862908",
          NextDialogue = 6201205,
          RougeTalkActorType = 3
        },
        [6201205] = {
          ContentJP = "「じゃあ、君もエリュシオンの教義を、すべて信じているんだね？」\n「満月の神にひたすら祈りを捧げれば、神は幸せな糸を紡いで、私たちを救ってくれるって。」",
          DialogueId = 6201205,
          GUID = "0F862932",
          NextDialogue = 6201206,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201206] = {
          ContentJP = "「いえ。私はフサを<H>追っている</>だけで、フサを<H>信じている</>わけではない。」\n「私に必要なのは、ただ一つ明確な理由ーー私が正しいと思う道に進むための理由だけだ。」",
          DialogueId = 6201206,
          GUID = "0F86295C",
          NextOptions = {
            [1] = 6201207
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201207] = {
          ContentJP = "話の意味は分からない。",
          DialogueId = 6201207,
          GUID = "0F862986",
          NextDialogue = 6201208,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201208] = {
          ContentJP = "「我らは与えるべきであり、奪うべきではない」\n「我らは愛し合うべきであり、憎み合うべきではない」\n「我らは抱き合うべきであり、傷つけ合うべきではない」\n「これが私の信じる『正しさ』だ――だが、人が自由であると信じるならば、それらが正しいと証明する根拠など、どこにも見つからない。」",
          DialogueId = 6201208,
          GUID = "0F8629B0",
          NextDialogue = 6201209,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201209] = {
          ContentJP = "「だから、私は『自由』を捨て、すべてを乗り越えるフサを選んだ。こうして、私の信じる正しさは、証明すら要らない確たる真理となった。」\n「おそらく、ある意味では、私こそがフサに対して、最も不敬な者なのかもしれない。」",
          DialogueId = 6201209,
          GUID = "0F8629DA",
          NextDialogue = 6201210,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201210] = {
          ContentJP = "「つまり、あなたが言いたいのは......」\nあなたは言葉を探している。\n「この深淵で進み続けたいなら......歩みの神を信じろ、と、自分に言い聞かせればいい？」",
          DialogueId = 6201210,
          GUID = "0F862A04",
          NextDialogue = 6201211,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201211] = {
          ContentJP = "「うん......このように理解しても構わない。」\n彼は軽く笑った。",
          DialogueId = 6201211,
          GUID = "0F862A2E",
          NextOptions = {
            [1] = 6201212
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201212] = {
          ContentJP = "本当に変な奴だ。そろそろ行かないと、ここに留まりすぎた。",
          DialogueId = 6201212,
          GUID = "0F862A58",
          IsKeyOption = true,
          NextDialogue = 6201213,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201213] = {
          ContentJP = "「さよなら、勇敢な旅人さんよ、あなたの旅路に、いつも灯りがそいますように」と彼は言った。",
          DialogueId = 6201213,
          GUID = "0F862A82",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201301] = {
          ContentJP = "「ずっと休んでいない。」\nここに来る前から、あなたは今回の取引を考えていた。\n「ひとつ買いたいものがあるーー夢。」\n「できるならね。」",
          DialogueId = 6201301,
          GUID = "0F8638F2",
          NextDialogue = 6201302,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201302] = {
          ContentJP = "「私は夢紡ぎ師でもないから、あなたが望むものを提供できると約束できない。」\n彼はゆっくりと首を振った。\n「でも......試してもいいけど。」\n「遠い昔、妹に物語を読み聞かせていた時、彼女はいつもぐっすりと眠っていた。」",
          DialogueId = 6201302,
          GUID = "0F86391C",
          NextDialogue = 6201303,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201303] = {
          ContentJP = "あなたは一束の藁を見つけ、それをできるだけふわふわに敷き詰めた。\n再び疲労感が襲ってきた。今のあなたが欲しいのは夢と、束の間の休息だけだ。",
          DialogueId = 6201303,
          GUID = "0F863946",
          NextDialogue = 6201304,
          RougeTalkActorType = 3
        },
        [6201304] = {
          ContentJP = "「昔々、彫金師をやっていた少年がいた。彼は月に恋をした。」\n「彼はこっそり月の大きさを測り、この世で最も煌びやかな宝石を使い、月への贈り物として、この世で最も美しいネックレスを作ろうとしたんだ。」\n「しかし、ついにネックレスを完成した時、彼は気づいた。月が少しふっくらと太ってしまい、もうこのネックレスがサイズに合わなくなっていることに。」\n「そこで、彼は作り直すことにした。今度は彼は自分が集めたすべての宝石をネックレスにちりばめた。しかし、再び月に会った時、月はさらに丸くなり、丸々としたお皿のようだった。」",
          DialogueId = 6201304,
          GUID = "0F863970",
          NextDialogue = 6201305,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201305] = {
          ContentJP = "これは古いおとぎ話だ。母からこの物語を聞いたことがあるをあなたはぼんやりと思い出した。ふと、微かな眠気が襲ってきた。",
          DialogueId = 6201305,
          GUID = "0F86399A",
          NextDialogue = 6201306,
          RougeTalkActorType = 3
        },
        [6201306] = {
          ContentJP = "「『.....それなら、大きさが違うネックレスを三本作ろうか。必ずぴったりするのがあるんだ』と、若い彫金師はそう考えた。」\n「しかし、愛しい月に三本のネックレスを捧げようとした時、月は消えていたーー漆黒の天幕にぽつりと輝くのは星のみ、まるで、月が最初から存在しなかったのようだった。」",
          DialogueId = 6201306,
          GUID = "0F8639C4",
          NextDialogue = 6201307,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201307] = {
          ContentJP = "銀色の月光に包まれ、あなたはゆっくりと夢の世界に沈んでいった。",
          DialogueId = 6201307,
          GUID = "0F8639EE",
          NextDialogue = 6201308,
          RougeTalkActorType = 3
        },
        [6201308] = {
          ContentJP = "「.....こうして、月を無くした彫金師は、日々ハンマーを振り続け、虚しくネックレスを作り続けていた。」\n「彼の涙が大地に落ちると、透き通った木が生えてきて、水晶のような実を結んだーー彼が一生を掛けて愛した月のような実だった。」\n「後の人々はこれを『天上樹』と『月ノ石』と呼んでいる.....」\n「疲れた旅人よ、もう寝てしまったのか？それでは、良い夢を見られますように。」",
          DialogueId = 6201308,
          GUID = "0F863A18",
          NextDialogue = 6201309,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201309] = {
          ContentJP = "最初の夢では、あなたは庭園の中で揺れているブランコを見た。\nあなたはとても小さくなっていた。年老いた執事がブランコの傍に立ち、両手を広げ、あなたが飛び込んでくるのを待っていた。\n「お帰りなさい、▇▇様。」",
          DialogueId = 6201309,
          GUID = "0F863A42",
          NextDialogue = 6201310,
          RougeTalkActorType = 3
        },
        [6201310] = {
          ContentJP = "二つ目の夢で、あなたは、タイムの花が咲き誇った丘の上に立つ若き騎士たちを見た。\n彼らは、金色の聖アイリスが施された旗を高く掲げ、髪が風になびいている。そして、彼らは笑いながら、あなたの名前を呼んだ。\n「出発しましょう、▇▇様。」\n……",
          DialogueId = 6201310,
          GUID = "0F863A6C",
          NextDialogue = 6201311,
          RougeTalkActorType = 3
        },
        [6201311] = {
          ContentJP = "三つ目の夢で、あなたと同じようにランタンを提げる旅人を見た。あなた{性别:彼|彼女}を三回も見た。\nその人の姿は遠ざかりつつ、暗闇に吞み込まれそうになった。\nあなたは大股で歩幅を速め、{性别:彼|彼女}傍に駆け寄った。",
          DialogueId = 6201311,
          GUID = "0F863A96",
          NextDialogue = 6201312,
          RougeTalkActorType = 3
        },
        [6201312] = {
          ContentJP = "「行かないで。」\nあなたはかすれた声で叫んだ。これまでのどんな戦いよりも無様の姿だった。",
          DialogueId = 6201312,
          GUID = "0F863AC0",
          NextDialogue = 6201313,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201313] = {
          ContentJP = "「ごめん、▇▇。」\n{性别:彼|彼女}は首を回す。揺らめく灯りが、{性别:彼|彼女}の顔を照らしたが、それは微かにしか見えない。\n「私たちは逆方向の道を歩んでいる。だから、もう行かないと。」",
          DialogueId = 6201313,
          GUID = "0F863AEA",
          NextDialogue = 6201314,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02"
        },
        [6201314] = {
          ContentJP = "「でもーーもう一人は嫌だ。」\nあなたはその人の裾を掴もうとしたがーーわがままな子供が最後の一粒の飴をねだるようにーーしかし、何も掴めなかった。\n涙がこぼれたーー前に泣いたのはいつだっただろう？",
          DialogueId = 6201314,
          GUID = "0F863B14",
          NextDialogue = 6201315,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201315] = {
          ContentJP = "「泣かないで、▇▇。」\n{性别:彼|彼女}は、あなたの頬を優しく撫でながら、涙を拭拭いた。{性别:彼|彼女}の息遣いとその温もりを感じた。\n「私たちの道は<H>繋がってるの</>だ。たとえ方向が違っていても、いつか必ず巡り合える。」",
          DialogueId = 6201315,
          GUID = "0F863B3E",
          NextDialogue = 6201316,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char02"
        },
        [6201316] = {
          ContentJP = "{性别:彼|彼女}の持っているランタンが徐々に明るくなり、銀色の光を放ち、やがて銀の糸を降り注ぐ満月のように輝いたーー\n{性别:彼|彼女}はその眩しい銀色の中に歩き出した。\n.....\n.....\n薄荷の香りに包まれる中、あなたは目を覚める。",
          DialogueId = 6201316,
          GUID = "0F863B68",
          NextDialogue = 6201317,
          RougeTalkActorType = 3
        },
        [6201317] = {
          ContentJP = "「いい夢だったか？」",
          DialogueId = 6201317,
          GUID = "0F863B92",
          NextDialogue = 6201318,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201318] = {
          ContentJP = "「うん......とても長い、長い夢だった。何年も経ったように。」",
          DialogueId = 6201318,
          GUID = "0F863BBC",
          NextDialogue = 6201319,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201319] = {
          ContentJP = "「それはよかった。まだ夢を見られるとは、幸運のことだ。」",
          DialogueId = 6201319,
          GUID = "0F863BE6",
          NextDialogue = 6201320,
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201320] = {
          ContentJP = "あなたは身を起こし、ランタンを握りしめ、あなたの戦いへと赴き続けるーー\n果てのない孤独な旅へ。",
          DialogueId = 6201320,
          GUID = "0F863C10",
          NextOptions = {
            [1] = 6201321
          },
          RougeTalkActorType = 3
        },
        [6201321] = {
          ContentJP = "ありがとう、そろそろ行かないと。",
          DialogueId = 6201321,
          GUID = "0F863C3A",
          IsKeyOption = true,
          NextDialogue = 6201322,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201322] = {
          ContentJP = "「さよなら、芯の強い旅人よ。」彼が言った。\n「いつかあなたの旅が独りぼっちでなくなりますように。」",
          DialogueId = 6201322,
          GUID = "0F863C64",
          RougeTalkActorType = 1,
          SpeakNpcName = "RougeLike_StoryShop_Char01"
        },
        [6201401] = {
          ContentJP = "闇、闇、そしてもっと深い闇ーー\nあんたは今、静寂な水底を漂流しているような感覚を覚えていた。\n底知れないこの川に沿って、どんどん下流へと流れていった。",
          DialogueId = 6201401,
          GUID = "0F86495A",
          NextDialogue = 6201402,
          RougeTalkActorType = 3
        },
        [6201402] = {
          ContentJP = "ーーそして、一本の光が遠くから、あなたへと近づいてきた。\nあれは一つの灯りだ。",
          DialogueId = 6201402,
          GUID = "0F864984",
          NextDialogue = 6201403,
          RougeTalkActorType = 3
        },
        [6201403] = {
          ContentJP = "「帰ってきたのね。私はずっと信じていたの、あなたが必ず帰ってくるって。」\n風にゆらめく灯りがその人の顔を照らすと、それは老いた婦人の顔だ。",
          DialogueId = 6201403,
          GUID = "0F8649AE",
          NextOptions = {
            [1] = 6201404
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201404] = {
          ContentJP = "私のことを知っているのですか？",
          DialogueId = 6201404,
          GUID = "0F8649D8",
          NextDialogue = 6201405,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201405] = {
          ContentJP = "「はい。」\n一瞬、彼女の老いた瞳から光が閃いた。まるで朽ち果てた朽木に、花が咲き始めたようだ。\n「私はここで、とてもとても長い間待っていたの。」",
          DialogueId = 6201405,
          GUID = "0F864A02",
          NextOptions = {
            [1] = 6201406
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201406] = {
          ContentJP = "私は一体誰ですか？",
          DialogueId = 6201406,
          GUID = "0F864A2C",
          NextDialogue = 6201407,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201407] = {
          ContentJP = "「私たちが歩んできた道は、<H>ひとつの輪</>になって繋がっているのよ。」\n彼女は笑い始めた。\n「またここに戻って来れば、きっとすべてを思い出せるはずだわ。」",
          DialogueId = 6201407,
          GUID = "0F864A56",
          NextOptions = {
            [1] = 6201408
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201408] = {
          ContentJP = "これからどうすればいい？",
          DialogueId = 6201408,
          GUID = "0F864A80",
          NextDialogue = 6201409,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201409] = {
          ContentJP = "「ここを、この<H>深淵</>から逃れなさい。これは<H>あなた</>の宿願だ。」\n老婦人はランタンをあなたに渡した。彼女の指は幽霊のように冷たかったが、あのランタンから放たれる金色の光は暖かかった。\nあなたは気付いたーー灯りに<H>目盛り</>のついた文字盤がはめ込まれているのだ。",
          DialogueId = 6201409,
          GUID = "0F864AAA",
          NextOptions = {
            [1] = 6201410
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201410] = {
          ContentJP = "どうすればここを離れますか？",
          DialogueId = 6201410,
          GUID = "0F864AD4",
          IsKeyOption = true,
          NextDialogue = 6201411,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201411] = {
          ContentJP = "「これは神の祝福を受けた灯りだ。」\n「十分な量の<H>純潔の瑠璃</>を集めて、この灯りを修復すれば、この深淵の海に道を開いてくれるだろう。」\n「致命的な危険に陥る時は、文字盤の針を<H>巻き戻せば</>いい。」",
          DialogueId = 6201411,
          GUID = "0F864AFE",
          NextDialogue = 6201412,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201412] = {
          ContentJP = "「旅に出る前に、この深淵の物語を聞きてみたいかもしれないね。」\n彼女は相変わらず静かに微笑んでいる。\n「これらの物語は、時の流れに漂う木の切れ端のようなものだ。『私たちの道は輪になって繋がっている』と言ったでしょう？あなたにとって、それらは過去の物語にも、将来の物語にもなり得るのだ。」\nだが間違いなく、すべてはあなたの物語だった。",
          DialogueId = 6201412,
          GUID = "0F864B28",
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryEvent_SeasonFirst01_Char01"
        },
        [6201501] = {
          ContentJP = "暗闇のほうから足音が聞こえてくる。重く引きずるような、ざわざわとした余韻を帯びている。\n足音のする方へ進むと、四人の若者が目の前に現れたーー静寂の黄昏小隊の騎士たちだった。彼らは無事だったが、その表情は前に会ったときとは隔世の感があった。",
          DialogueId = 6201501,
          GUID = "0F8659C2",
          NextDialogue = 6201502,
          RougeTalkActorType = 3
        },
        [6201502] = {
          ContentJP = "「まだ......歩き続けるの？もうどれぐらい歩いただろう？」\n女魔術師の声は疲労でかすれている。まるで、彼女が羽織っているのはマントではなく、分厚い石板でも背負っているかのようだ。",
          DialogueId = 6201502,
          GUID = "0F8659EC",
          NextDialogue = 6201503,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201503] = {
          ContentJP = "「たぶん......四日？五日......？あるいはもっとか。私の懐中時計はもう効かない。」\n司祭の声は、刃物が紙をこするようにかすれているーー敬虔な彼ですら、もはや平時のような恭しい口調を保てなかった。",
          DialogueId = 6201503,
          GUID = "0F865A16",
          NextDialogue = 6201504,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201504] = {
          ContentJP = "みんなも疲れてるし、ここで一旦休憩しよう。しばらく眠ってもいい、私が見張ってやるから。」\n青年はそう言ったが、彼自身も相当疲れているのが、声から分かる。",
          DialogueId = 6201504,
          GUID = "0F865A40",
          NextDialogue = 6201505,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201505] = {
          ContentJP = "「私も付き合うよ！万が一どちらかがうっかり眠っちゃっても、互いに起こせるから！」\n彼女はできるだけ軽い口調で提案し、フーリンが自責の念に駆られて「ごめん」と言い出そうとした時、目配せで彼を止めた。",
          DialogueId = 6201505,
          GUID = "0F865A6A",
          NextDialogue = 6201506,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201506] = {
          ContentJP = "そして、四人は比較的に平らな地面を見つけ、荷物を下ろし、簡素な仮設の営地を作った。\nカリスタとミルトンが休み始めた後、フーリンとケイシーは少し離れた場所へ歩いていった。沈黙が彼らを包み、空気が凍り付いたかのように思える。\nふと、フーリンはうつむき、自分とケイシーだけが聞こえる声で、ぽつりとため息をついた。",
          DialogueId = 6201506,
          GUID = "0F865A94",
          NextDialogue = 6201507,
          RougeTalkActorType = 3
        },
        [6201507] = {
          ContentJP = "「あら、ため息なんて珍しいね。」少女は笑みを浮かべながら、ポケットから小さな紙包みを取り出した。「飴、食べない？こっそり持ち込んできたんだよ。この二粒が最後、半分こしようね。」",
          DialogueId = 6201507,
          GUID = "0F865ABE",
          NextDialogue = 6201508,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201508] = {
          ContentJP = "「……ありがとう、結構だ。好きなものなら、自分で持ってて。」",
          DialogueId = 6201508,
          GUID = "0F865AE8",
          NextDialogue = 6201509,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201509] = {
          ContentJP = "「飴は友達と分け合うからこそもっと甘くなるんだから。」",
          DialogueId = 6201509,
          GUID = "0F865B12",
          NextDialogue = 6201510,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201510] = {
          ContentJP = "ケイシーは一粒を口に放り込むと、残った最後の一粒を包み紙ごとフーリンに押し付けた。しかし、フーリンはただ黙ってうつむき、反応はなかった。\nケイシーはそれ以上何も言わず、飴を舐めながら静かに待っていた——友が思考を整理してから、再び対話を始める時を。",
          DialogueId = 6201510,
          GUID = "0F865B3C",
          NextDialogue = 6201511,
          RougeTalkActorType = 3
        },
        [6201511] = {
          ContentJP = "「さっきの……剣を持っていた暗影……見たか？」\nようやく、青年は低い声で口を開いた。",
          DialogueId = 6201511,
          GUID = "0F865B66",
          NextDialogue = 6201512,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201512] = {
          ContentJP = "「あの味方見境なく、暗影まで斬りつける奴のこと？もちろん見たよ。あの銀色の剣の白い光はまぶしすぎて、あんたが憧れているあの伝説の英雄が使っている武器みたいだね......」\nここまで言いかけて、少女は何かに気付いたようにフーリンを見た。\n「まさか……彼が<H>月昇り</>の騎士なのか？」",
          DialogueId = 6201512,
          GUID = "0F865B90",
          NextDialogue = 6201513,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201513] = {
          ContentJP = "「……ああ。あれは彼だった。彼の映像や画集を数え切れないほど見てたから、間違いない。」\n青年はため息をつくと、両手で顔を覆った。\n「……本当に、彼だと気付いた時、怖かった。もし彼だって深淵に敗れたというのなら、私たちはどうやって勝てるんだ？私も最後はあんなようになってしまうのか？……同胞に刃を向ける者になってしまうのか。」",
          DialogueId = 6201513,
          GUID = "0F865BBA",
          NextDialogue = 6201514,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201514] = {
          ContentJP = "「確かに、深淵ってこんな恐ろしいところだとは全然思わなかった.....それでも、私は信じている。最後まで勝つのが、必ず人類の意志だってね。」\n少女は友人の背を軽く叩いた。\n「ほら、暗影を攻撃したってのは、彼はまだ負けを認めていない証でしょう？たとえこんな姿になっても、最初の目標を見失っていないって。そうでしょう？」",
          DialogueId = 6201514,
          GUID = "0F865BE4",
          NextDialogue = 6201515,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201515] = {
          ContentJP = "「うん......」",
          DialogueId = 6201515,
          GUID = "0F865C0E",
          NextDialogue = 6201516,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201516] = {
          ContentJP = "会話に加わるいいタイミングじゃなさそうだ。あなたは若者たちの休憩を邪魔するつもりはないが、ここから立ち去ろうとした時、ケイシーに気付かれた。",
          DialogueId = 6201516,
          GUID = "0F865C38",
          NextDialogue = 6201517,
          RougeTalkActorType = 3
        },
        [6201517] = {
          ContentJP = "「あれ？」少女は嬉しそうにあなたに歩いてきた。「あの時の旅人さんじゃん！無事でよかった！」",
          DialogueId = 6201517,
          GUID = "0F865C62",
          NextDialogue = 6201518,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201518] = {
          ContentJP = "青年は驚いた様子で少女の後ろをついてきた。\n「あなたはさすが普通の方ではありませんね。私たちよりも早く深淵に入りましたのに、一体どうやってずっとこんな固い意志でおられるんですか。」",
          DialogueId = 6201518,
          GUID = "0F865C8C",
          NextOptions = {
            [1] = 6201519
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201519] = {
          ContentJP = "私は......ただ慣れただけだ。私だって迷ったり、後悔したり、絶望したりする時がある。だが今はもう、そのすべてを受け入れただけだ。",
          DialogueId = 6201519,
          GUID = "0F865CB6",
          NextDialogue = 6201520,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201520] = {
          ContentJP = "青年の驚いた顔に、感服した表情が浮かんだ。\n「では......あなたはどう思いますか？人類は深淵に勝てると思いますか？」",
          DialogueId = 6201520,
          GUID = "0F865CE0",
          NextOptions = {
            [1] = 6201521,
            [2] = 6201524
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201521] = {
          ContentJP = "必ずね。",
          DialogueId = 6201521,
          GUID = "0F865D0A",
          IsKeyOption = true,
          NextDialogue = 6201522,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201522] = {
          ContentJP = "「ほらね、旅人さんもそう言っているし、必ず無事で任務を達成できるの。もっと元気出して！",
          DialogueId = 6201522,
          GUID = "0F865D34",
          NextDialogue = 6201523,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201523] = {
          ContentJP = "彼女はあなたを誤解しているようだ。あなたが信じている「勝利」は、礼賛会がこれらの騎士に下した命令とはまったく違うものだ。\nあなたはよく知っているーー前方で彼らを待っているのが苦痛と絶望だけ。彼らは繰り返し死を経験していても、自分が地獄にいることにちっとも自覚していない。\nしかし、あなたはそれ以上何も話さなかった。未来を変えられないのなら、無知もまた一つの幸福であるからだ。\n",
          DialogueId = 6201523,
          GUID = "0F865D5E",
          RougeTalkActorType = 3
        },
        [6201524] = {
          ContentJP = "分からない。",
          DialogueId = 6201524,
          GUID = "0F865D88",
          IsKeyOption = true,
          NextDialogue = 6201525,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201525] = {
          ContentJP = "「あなたも、実は自信がないのですか......」\n青年はうつむいた。だが、彼はすぐに顔を上げ、不自然なほどしっかりとした声で口を開いたーーそれが自分に勇気を与えているのか、それとも自分んをだましているのか、あなたも分からない。\n「なんにせよ、エリュシオンの騎士として、我々に後退の道はない。たとえ本当に希望が消え去っても、最後の瞬間まで戦い続けるつもりだ。」",
          DialogueId = 6201525,
          GUID = "0F865DB2",
          NextDialogue = 6201526,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201526] = {
          ContentJP = "あなたはよく知っているーー前方で彼らを待っているのは苦痛と絶望だけ。彼らは繰り返し死を経験していても、自分が地獄にいることにちっとも自覚していない。\nしかし、騎士のしっかりとした視線を見ると、あなたはそれ以上話せなかった。",
          DialogueId = 6201526,
          GUID = "0F865DDC",
          RougeTalkActorType = 3
        },
        [6201601] = {
          ContentJP = "鋼鉄の激突の音が闇から響いてくる。前方で激戦が繰り広げられているに違いない。\n若き騎士が必死に剣を振り下ろし、目の前の暗影にとどめを刺した。",
          DialogueId = 6201601,
          GUID = "0F866A2A",
          NextDialogue = 6201602,
          RougeTalkActorType = 3
        },
        [6201602] = {
          ContentJP = "突然、細い黒影が飛び込んできた。騎士は迅速に盾を構え、この奇襲を防いだ。だが、盾の裂け目に刺さっていた細い矢を見た瞬間、彼は凍り付いた。\n矢の羽根には、エリュシオンを象徴する金色の聖アイリスの紋章が飾られていた。だがその地の色は、真っ黒に塗りつぶされていた。こんなことをする者はただ一人しか――",
          DialogueId = 6201602,
          GUID = "0F866A54",
          NextDialogue = 6201603,
          RougeTalkActorType = 3
        }
      }
    end
  },
  {
    MinKey = 6201603,
    MaxKey = 10011708,
    Loader = function()
      return {
        [6201603] = {
          ContentJP = "「カリスタ......？」",
          DialogueId = 6201603,
          GUID = "0F866A7E",
          NextDialogue = 6201604,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201604] = {
          ContentJP = "暗影は近づいてくる。暗闇に蝕まれた肢体が、まるで黒いマントと一体となっているようだ。「彼女」はフーリンの呼びかけにまったく反応せず、ただ黙って弓を構えた。",
          DialogueId = 6201604,
          GUID = "0F866AA8",
          NextDialogue = 6201605,
          RougeTalkActorType = 3
        },
        [6201605] = {
          ContentJP = "深淵に足を踏み入れたばかりの頃、四人は衝撃的な事実を知ったーー攻撃的な人型の暗影の多くが、見覚えのある顔をしていたのだ。彼らはみんなエリュシオンの騎士で、かつて深淵を討伐するためにここに来て、戦死した後に深淵に同化され、今では昔の仲間に刃を向けるようになっていた。",
          DialogueId = 6201605,
          GUID = "0F866AD2",
          NextDialogue = 6201606,
          RougeTalkActorType = 3
        },
        [6201606] = {
          ContentJP = "これこそが深淵で最も恐ろしい呪いだーー「生き続けること」そのものだ。もし誰かが深淵に踏み入れてすぐ死ねば、せめて生前の姿のまま、ありふれた亡霊になれるだろう。",
          DialogueId = 6201606,
          GUID = "0F866AFC",
          NextDialogue = 6201607,
          RougeTalkActorType = 3
        },
        [6201607] = {
          ContentJP = "もし彼は安易に死ぬことを選ばず、進み続けるなら、深淵で過ごした一分一秒は、意志が混沌の暗闇に蝕まれる苦痛に耐える戦いになる。そして最後に、すべての戦いが賭けになり、たとえ一瞬でも動揺したら、彼はすぐに暗闇に吞み込まれ、理性を失い、戦うことしか知らない化け物に墜ちてしまうのだ。",
          DialogueId = 6201607,
          GUID = "0F866B26",
          NextDialogue = 6201608,
          RougeTalkActorType = 3
        },
        [6201608] = {
          ContentJP = "今、フーリンの前に立っている「彼女」のように。",
          DialogueId = 6201608,
          GUID = "0F866B50",
          NextDialogue = 6201609,
          RougeTalkActorType = 3
        },
        [6201609] = {
          ContentJP = "「いや......やめて......もう傷つけたくないんだ......お願いだ......」青年の剣を握っている手が震えている。「ミルトンも犠牲になったし、あんたまで......」",
          DialogueId = 6201609,
          GUID = "0F866B7A",
          NextDialogue = 6201610,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201610] = {
          ContentJP = "それでも、矢は真っ直ぐに彼の心臓を目指して飛んできた。彼は盾を構えてこの一撃を防いだが、すぐに次の矢が飛んできて、彼の顔を掠めて血痕を残した。",
          DialogueId = 6201610,
          GUID = "0F866BA4",
          NextDialogue = 6201611,
          RougeTalkActorType = 3
        },
        [6201611] = {
          ContentJP = "「あああ......！」",
          DialogueId = 6201611,
          GUID = "0F866BCE",
          NextDialogue = 6201612,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201612] = {
          ContentJP = "苦痛に満ちた叫び声と共に、青年は再び剣を手に取った。一撃、また一撃、暗影が完全に消えるまで、彼は剣を振り続けていた。\nすでに灰になった昔の仲間の遺骸を前に、彼は倒れそうな体を剣にもたれかけ、声を上げて泣き崩れていた。",
          DialogueId = 6201612,
          GUID = "0F866BF8",
          NextDialogue = 6201613,
          RougeTalkActorType = 3
        },
        [6201613] = {
          ContentJP = "泣き声が止んだ後、周りは異常に静まり返っている。戦闘はすでに終わっているのに、いつも彼と一緒にふざけていたあの少女は、笑いながら彼のそばに戻ってくることはなかった。",
          DialogueId = 6201613,
          GUID = "0F866C22",
          NextDialogue = 6201614,
          RougeTalkActorType = 3
        },
        [6201614] = {
          ContentJP = "「ケイシー......ケイシー？大丈夫か？」\n彼は友人の方向に向かい、傷だらけの体を引きずって難しく移動している。",
          DialogueId = 6201614,
          GUID = "0F866C4C",
          NextDialogue = 6201615,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201615] = {
          ContentJP = "少女は彼の呼びかけに気付いていないようだった。両手は力なく垂れ下がったまま、その場に佇んでいた。彼女の息遣いが荒くなり、まるで窒息しそうな様子で、必死に空気を吸い込でいたようだ。\n禍々しい暗影が彼女の傷口から湧き出し、手足に絡みつき、美しい金髪を黒に染めあげ、ついに彼女をまるごと吞み込んだ。",
          DialogueId = 6201615,
          GUID = "0F866C76",
          NextDialogue = 6201616,
          RougeTalkActorType = 3
        },
        [6201616] = {
          ContentJP = "剣は血と涙が混じる泥濘に落ちていった。青年は力を失って倒れた。",
          DialogueId = 6201616,
          GUID = "0F866CA0",
          NextDialogue = 6201617,
          RougeTalkActorType = 3
        },
        [6201617] = {
          ContentJP = "「私の......負けだった。聞こえているのか？」\n彼は目を閉じ、顔を空に向けたーーもしあの深い暗闇を空と呼べるのならばーー彼の声は死水のように静かだった。\n「お前は何者であれ......なぜ私たちをそこまで苦しめるんだ？本当にうんざりだ。もう疲れた。ここまでだ。私も一緒に連れていけ......」",
          DialogueId = 6201617,
          GUID = "0F866CCA",
          NextDialogue = 6201618,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201618] = {
          ContentJP = "前方からざわめきが聞こえてきた。何かがゆっくりと彼に近づいている。彼は目も閉けず、毅然とした顔で死を待っている。\n一対の手が剣を拾い上げ、再び彼の手の中に戻した。",
          DialogueId = 6201618,
          GUID = "0F866CF4",
          NextDialogue = 6201619,
          RougeTalkActorType = 3
        },
        [6201619] = {
          ContentJP = "「私のことにそんなに自信がなかったの？」\n少女の声は闇を通して伝わってきた。彼女は優しく青年の涙を拭き、うつむている彼の頭を抱き寄せ、全身にこびりついた血痕を遮った。\n「大丈夫だよ。どんなことがあっても......少なくとも私だけは、絶対に変わらないから。約束するよ。」",
          DialogueId = 6201619,
          GUID = "0F866D1E",
          NextDialogue = 6201620,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201620] = {
          ContentJP = "「......うん。ずっと信じている。」\n青年は両腕を伸ばし、その闇を受け入れた。",
          DialogueId = 6201620,
          GUID = "0F866D48",
          NextDialogue = 6201621,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201621] = {
          ContentJP = "これは彼らにさらなる苦痛をもたらすだけの、無意味な希望だと知りながら、あなたはついに我慢できなかった。\nあなたはランタンを掲げ、二人の傍に駆け寄った。瑠璃の光のおかけで、彼らを包む闇が消え去り、少女の長髪は再び金色の輝きを帯び始めた。\n救われた二人は状況が分からないような表情で首をあげ、あなたを見つめた。",
          DialogueId = 6201621,
          GUID = "0F866D72",
          NextDialogue = 6201622,
          RougeTalkActorType = 3
        },
        [6201622] = {
          ContentJP = "「旅人さん......？あなたが私たちを救ってくれたのですか？」\n少女は正常に戻った両手を確かめたら、信じられないような表情を浮かべた。\n「ありがとうございます......！あなたが普通の方ではないとは分っていますが、こんな強い力まで.....」",
          DialogueId = 6201622,
          GUID = "0F866D9C",
          NextDialogue = 6201623,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201623] = {
          ContentJP = "「はぁ......」\n青年はぼうっと息を吐いて、まだ完全に反応できていないようだった。",
          DialogueId = 6201623,
          GUID = "0F866DC6",
          NextOptions = {
            [1] = 6201624
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201624] = {
          ContentJP = "どういたしまして、あなたたち......これからどうするつもり？",
          DialogueId = 6201624,
          GUID = "0F866DF0",
          IsKeyOption = true,
          NextDialogue = 6201625,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201625] = {
          ContentJP = "「救われた以上、もちろん前進するつまりですよ。あ、でもまずはフーリンの傷の手当をしなくちゃ。」",
          DialogueId = 6201625,
          GUID = "0F866E1A",
          NextDialogue = 6201626,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201626] = {
          ContentJP = "あなたの心配に気付いたかのように、少女は明るい笑顔を見せた。",
          DialogueId = 6201626,
          GUID = "0F866E44",
          NextDialogue = 6201627,
          RougeTalkActorType = 3
        },
        [6201627] = {
          ContentJP = "「旅人さん、前にフーリンが聞いたことをまだ覚えていますか？今、やっと分かった気がします。」彼女は落ち着いたしっかりとした口調で話した。「だってね、本当に深淵に勝てるのは、たった一つの戦いでも、一人の人間でもない。最後まで勝てるのが私たち全員が積み重ねてきた努力だと思います。それを続けていけば、いつか......いつかきっと何かを変えられます。だから、自分の結末ばかりに気にしなくていい。進み続けること自体が、最後の勝利へ導く小さな貢献になれるのです。」",
          DialogueId = 6201627,
          GUID = "0F866E6E",
          NextDialogue = 6201628,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201628] = {
          ContentJP = "「はぁ......ケイシー、まさか......あなたの口からこんなもっともな話を聞く日がくるとはな。隊長としては情けない。」\n青年はついに意識を取り戻し、友人の支えで立ち上がり、背筋を伸ばした。\n「深淵は広がり続けている。このまま放っておくと、エリュシオン全域までが吞み込まれるぞ。時間稼ぎのためでもいい。最後まで戦うのだ。それに、リズベル様もまだ行方不明だった。」",
          DialogueId = 6201628,
          GUID = "0F866E98",
          NextDialogue = 6201629,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201629] = {
          ContentJP = "「そうですよ。私たちは彼女と一緒に帰らなくちゃ！だから、旅人さん、あなたも自分の道を進んでください。私たちを気遣わず、私たちの代わりに何かを背負わず、ただ祝福だけを受け取ってください。」\n少女は真剣な眼差しであなたを見つめ、掌を胸元に当てた。\n「<H>運命の神があなたに千本の月光を降り注ぎ、その翼が満月のように純白でありますように。</>」",
          DialogueId = 6201629,
          GUID = "0F866EC2",
          NextDialogue = 6201630,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201630] = {
          ContentJP = "これは非常に荘厳な祝福の言葉だ。エリュシオンでは、おそらく二度と会うことのない人にのみ、この言葉は贈られる。\nしかし、これは決して消極的な別れの言葉ではなく、運命を受け入れる覚悟の表明だーー\n「あなたの旅路が平穏であることを心から願います。たとえこれが永遠の別れであっても、それもまた受け入れます。」",
          DialogueId = 6201630,
          GUID = "0F866EEC",
          NextDialogue = 6201631,
          RougeTalkActorType = 3
        },
        [6201631] = {
          ContentJP = "あなたはケイシーに頷くと、ランタンを手にして再び旅に出た。",
          DialogueId = 6201631,
          GUID = "0F866F16",
          RougeTalkActorType = 3
        },
        [6201701] = {
          ContentJP = "若者たちの声が、遠くない場所から聞こえてくる。こんな声を深淵で聞いたのは久しぶり──熱烈で、元気あふれる、まだ深淵の闇に侵されていない声。\nあなたはこれは亡霊でも幻影でもなく、紛れもない生身の人間の声だということに確信を持っている。",
          DialogueId = 6201701,
          GUID = "0F867A92",
          NextDialogue = 6201702,
          RougeTalkActorType = 3
        },
        [6201702] = {
          ContentJP = "また彼らと出会った。",
          DialogueId = 6201702,
          GUID = "0F867ABC",
          NextDialogue = 6201703,
          RougeTalkActorType = 3
        },
        [6201703] = {
          ContentJP = "これまでと同じように、四人の若き騎士が霧の中から現れた。\n彼らの血に染まった姿がまだ目に焼き付いている。こんな再開が果たして誰にとってより残酷なものであろうーー繰り返し絶望の中で死んでいく彼らか、それとも同じ光景を繰り返し見せられるあなたか。",
          DialogueId = 6201703,
          GUID = "0F867AE6",
          NextDialogue = 6201704,
          RougeTalkActorType = 3
        },
        [6201704] = {
          ContentJP = "「この方向は合ってるの？隊長。」\n金髪の女騎士は古びた階段を大股で駆け上がり、また軽やかに飛び降りた。\n「どうやら、ただの廃墟だけみたいだ。」",
          DialogueId = 6201704,
          GUID = "0F867B10",
          NextDialogue = 6201705,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201705] = {
          ContentJP = "「少なくとも、来たことがない場所だ。」\n隊長と呼ばれた青年の騎士は落ち着いた足取りで彼女の横を通り過ぎた。\n「聖湖では方向を失いやすい。今は一歩ずつ進むしかない。」",
          DialogueId = 6201705,
          GUID = "0F867B3A",
          NextOptions = {
            [1] = 6201706,
            [2] = 6201716
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201706] = {
          ContentJP = "戻ろう.....今ならまだ間に合える。",
          DialogueId = 6201706,
          GUID = "0F867B64",
          IsKeyOption = true,
          NextDialogue = 6201707,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201707] = {
          ContentJP = "「うん？あなたは......？」",
          DialogueId = 6201707,
          GUID = "0F867B8E",
          NextDialogue = 6201708,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201708] = {
          ContentJP = "「あなたたち、リズベルの友達だね？彼女からの伝言がある――深淵は私たちの想像より危険だ。ただの騎士団の小隊で対応できるものじゃない。戻ってください。無駄な犠牲を増やすな。」\nあなたはもう他のことを考えられない。たとえ嘘をついても、少なくとも<W>今回</>は、彼らに生きて欲しい。",
          DialogueId = 6201708,
          GUID = "0F867BB8",
          NextDialogue = 6201709,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201709] = {
          ContentJP = "「えっ！？リズベル様の行方を知っていますか？彼女は元気ですか？どこにいるのですか？」",
          DialogueId = 6201709,
          GUID = "0F867BE2",
          NextDialogue = 6201710,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201710] = {
          ContentJP = "「待て、ケイシー。」\n司祭は仲間を制し、怪しげにあなたを見た。\n「リズベル様は決してこんな臆病者であるはずがない。どうか彼女の名を騙らないでください。それに、深淵討伐は教皇陛下が下されたご命令です。たとえ前方が地獄であろうと、我々は退かない。」",
          DialogueId = 6201710,
          GUID = "0F867C0C",
          NextDialogue = 6201711,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201711] = {
          ContentJP = "あなたは心の中でため息をついた。\n時々に人々は「地獄」という言葉を口にするが、彼らはその真の意味を知らない。",
          DialogueId = 6201711,
          GUID = "0F867C36",
          NextDialogue = 6201712,
          RougeTalkActorType = 3
        },
        [6201712] = {
          ContentJP = "「私たちに戻れって......」\nマントを羽織った女魔術師は、底も見えない瞳であなたを見つめ、冷たい口調で言った。\n「仮に戻ったとしても......実は無意味じゃない？」",
          DialogueId = 6201712,
          GUID = "0F867C60",
          NextDialogue = 6201713,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201713] = {
          ContentJP = "あなたは言い返す言葉がない。\nそうだ。彼女の言う通りだ。たとえ今すぐ戻ったとしても、彼らは来た道を見つけ出せない。この深淵において、「進む」と「戻る」を区別するとは、ただの自己欺瞞に過ぎないのだ。\n彼らを救う方法はただ一つ。この絶望的な輪廻を完全に終わらせることだ。",
          DialogueId = 6201713,
          GUID = "0F867C8A",
          NextDialogue = 6201714,
          RougeTalkActorType = 3
        },
        [6201714] = {
          ContentJP = "「皆さん......」\nあなたは若き騎士たちを見つめ、厳かに胸に手を当てた。\n「<H>運命の神があなたに千本の月光を降り注ぎ、その翼が満月のように純白でありますように。</>」",
          DialogueId = 6201714,
          GUID = "0F867CB4",
          NextDialogue = 6201715,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201715] = {
          ContentJP = "あなたの祝福を聞き、カリスタの顔には悲しみを帯びた微笑みが浮かんだ。\nあなたはふと気付いたーーもしかして彼女は、あなたに反論してほしがっていたのではないかと、たとえ嘘でも。",
          DialogueId = 6201715,
          GUID = "0F867CDE",
          RougeTalkActorType = 3
        },
        [6201716] = {
          ContentJP = "勇敢な騎士たちよ、満月の神があなたたちの旅路を護られますように。",
          DialogueId = 6201716,
          GUID = "0F867D08",
          IsKeyOption = true,
          NextDialogue = 6201717,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201717] = {
          ContentJP = "「うん？」\nあなたの突然の祝福を聞いて、青年は言葉を失った。\n「あなたは......？」",
          DialogueId = 6201717,
          GUID = "0F867D32",
          NextDialogue = 6201718,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Flynn"
        },
        [6201718] = {
          ContentJP = "「あなたたちは、リズベルの友達だね？彼女から伝言がある――深淵は私たちの想像より遥かに危険だ。あなたたちはこれから未曾有の困難と挑戦に直面することになる。覚悟しなさい。」",
          DialogueId = 6201718,
          GUID = "0F867D5C",
          NextDialogue = 6201719,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201719] = {
          ContentJP = "「あれ？！リズベル様の行方を知っていますか？今どこにいらっしゃいますか？元気ですか？」",
          DialogueId = 6201719,
          GUID = "0F867D86",
          NextDialogue = 6201720,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Kathy"
        },
        [6201720] = {
          ContentJP = "「待って、ケイシー、素性知れぬ者の言葉を簡単に信じるな。」\n司祭は興奮した仲間を制し、怪しげにあなたを見た。\n「リズベル様は未熟なご性格です。こんな重々しい言葉を口にされるとは、想像もつかぬ。それに、深淵討伐は教皇陛下が下されたご命令です。あなた方が言わなくても、我々は全力を尽くす覚悟を持っています。」",
          DialogueId = 6201720,
          GUID = "0F867DB0",
          NextDialogue = 6201721,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201721] = {
          ContentJP = "「この旅人さんが話していたのは真実だと思う。こんなところで長くいればいるほど、性格が変わるどころか、狂ってしまっても可笑しくないのだ。」\n女魔術師は顔をあげ、謎解きしているように、底も見えない瞳で視線もそらずにあなたを見つめている。\n「あなたは一体、何者ですか？どこかで会ったことは......ありますか？」",
          DialogueId = 6201721,
          GUID = "0F867DDA",
          NextDialogue = 6201722,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201722] = {
          ContentJP = "「......私の正体はどうでもいい。」\nあなたは若い騎士たちを見つめ、自然な微笑みを浮かべた。\n「あなたたちが知るべきなのは、私は祝福が本音だということだけ。たとえ物語の結末がすでに決められたとしても......あなたたちに旅の意味を見つけてもらいたい。」",
          DialogueId = 6201722,
          GUID = "0F867E04",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201801] = {
          ContentJP = "無数の暗影に囲まれている二つの若い姿を、あなたは見たーーそれはミルトンとカリスタだった。\n彼らは協力して何度も何度も敵を撃退したが、暗影は依然として襲い続けていた。\nそして、あなたはランタンを掲げ、彼らのそばへと近づいた。瑠璃の光の下で、ついに暗影たちは一時的に退散した。",
          DialogueId = 6201801,
          GUID = "0F868AFA",
          NextDialogue = 6201802,
          RougeTalkActorType = 3
        },
        [6201802] = {
          ContentJP = "「あなたはこの前の......」\nあなたを見て、司祭はまず驚き、続いて少し恥ずかしがるような顔を浮かべた。\n「そこまで疑われていたのに、手を差し伸べてくださったなんて......ありがとうございます。どうか許してください、謎の旅人さん。」",
          DialogueId = 6201802,
          GUID = "0F868B24",
          NextDialogue = 6201803,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201803] = {
          ContentJP = "「さすが普通の方ではありませんね。助かりました。」\n女魔術師はマントを下ろして感謝の言葉を述べ、マントと同じく漆黒の髪を見せた。\n「あなたが持っているあのランタン......もしかして、何かの神器でもないですか？なぜ暗影を払えるのですか。」",
          DialogueId = 6201803,
          GUID = "0F868B4E",
          NextOptions = {
            [1] = 6201804
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201804] = {
          ContentJP = "これは他の人からもらったものです。",
          DialogueId = 6201804,
          GUID = "0F868B78",
          NextDialogue = 6201805,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201805] = {
          ContentJP = "「そしたら、余計な口は聞きません。ただ、このランタンがあれば、深淵での行動もよりやすくなるはずです。もしよければ、私たちも同行させていただけますでしょうか？」",
          DialogueId = 6201805,
          GUID = "0F868BA2",
          NextDialogue = 6201806,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201806] = {
          ContentJP = "「構わないけど。ただし、私たちの目標が違う。私はこのランタンを修復できる瑠璃を集めているだけだ。」",
          DialogueId = 6201806,
          GUID = "0F868BCC",
          NextDialogue = 6201807,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201807] = {
          ContentJP = "「いまさら、目標なんてもうどうでもいい......あなたと同行できれば、この深淵真相にもっと触れるのだと、私の直感がそう言っています。」",
          DialogueId = 6201807,
          GUID = "0F868BF6",
          NextDialogue = 6201808,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201808] = {
          ContentJP = "「カリスタ、馬鹿なことを言うな。」\nあなたが答える前に、司祭は急き込んで仲間をしかった。\n「ほかの隊員とはぐれてしまったが......我々はエリュシオンの騎士だってことは変わらない。たとえ一人になっても、使命を忘れるな。」",
          DialogueId = 6201808,
          GUID = "0F868C20",
          NextDialogue = 6201809,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201809] = {
          ContentJP = "「ふっ......何が使命だと？君の頭にはこんなガラクタしか入ってないのか？」\n女魔術師も落ち着きを失い始めた。矢立てに収めた数本の細い矢が、彼女の動きに合わせて、カサカサと音を立てた。\n「ちょっと考えてくれよ、ここで会ったのは何？穢獣、ミラージュ、幽霊。本当に上の人たちが言ったように、聖湖に入れる人が神に選ばれた人だとしたら、私たちが見たあの暗影は何だ？聖湖より、ここは闇月教派が言っている魔王の巣のほうが近いのだーー」",
          DialogueId = 6201809,
          GUID = "0F868C4A",
          NextDialogue = 6201810,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201810] = {
          ContentJP = "「お前はーー完全に狂ってる！その口の利き方、まるで異端者のようだ。」\n彼は自分の最後の体面を保とうとしているが、その声には少しの戸惑いが混じっている。\n「あの暗影たちは......信仰が薄すぎて、最後の試練を乗り越えられなかっただけだ。彼らを始末すれば、聖湖は元通りになるかもしれない。これは神様が私たちに与えた試練だ。敬虔に祈り続けていれば、きっと神様は加護してくださるはず......」",
          DialogueId = 6201810,
          GUID = "0F868C74",
          NextDialogue = 6201811,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201811] = {
          ContentJP = "「あんたが言っていたあの神様は、本当に加護してくれるなら、自らこの地獄を終わらせるべきなんだ。」\n彼女は軽く笑ってから、長いため息をついた。\n「わざわざここに来て求めているのは、ただの死だけか。討伐なんてどうでもいい。生贄をここに送り続け、深淵の欲望を満たすのが、最初から彼らの真の狙いだった。私は見たんだよ。暗影の中には、この前深淵を討伐しに来た騎士たちの顔を見たんだよ......」",
          DialogueId = 6201811,
          GUID = "0F868C9E",
          NextDialogue = 6201812,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201812] = {
          ContentJP = "「彼らは私たちより年上だし、もっと多くの戦争も経験してきたし、身体能力も精神能力もはるかに優れていたはず。最後もまたこんな姿になってしまったんじゃないか？もうここから出られるわけがない。狂うか死ぬか、これが私たちの宿命だ。遅かれ早かれ。」",
          DialogueId = 6201812,
          GUID = "0F868CC8",
          NextDialogue = 6201813,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201813] = {
          ContentJP = "司祭は渋い顔で唇を嚙んでいる。彼は杖を強く握り、震えている体を抑えようとした。\nしばらく経ってから、彼はまた冷静な口調で話した。\n「......特殊な状況に鑑みて、さっきの話を聞かなかったふりをする。今はフーリンもいないし、階級から見ると、あなたは私の決断に従うべきだ。いますぐ教義と聖者への軽蔑な言葉を撤回して、騎士としての役目を果たし続けろ。」",
          DialogueId = 6201813,
          GUID = "0F868CF2",
          NextDialogue = 6201814,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201814] = {
          ContentJP = "「......まあいい。早く解脱できるのも悪くない。」\n彼女は諦めたように頭を下げ、もう一度マントを被った。\n「しかし友達として、ひとつ聞いてほしい......あなたが信じているすべてが嘘だとしたら、その嘘のために死ぬなんて、惜しすぎるじゃないの？」",
          DialogueId = 6201814,
          GUID = "0F868D1C",
          NextDialogue = 6201815,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201815] = {
          ContentJP = "「......」\n司祭は軽くかぶりを振り、一歩前へ進み、あなたに向けてお辞儀をした。\n「お恥ずかしいところをお見せまして申し訳ございません。私たちはもう大丈夫です。すこし整えてからまた出発します。善良な旅人さんよ、ここで別れましょう。満月の神があなたの旅路を護られますように。」",
          DialogueId = 6201815,
          GUID = "0F868D46",
          NextOptions = {
            [1] = 6201816,
            [2] = 6201818,
            [3] = 6201820
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201816] = {
          ContentJP = "満月の神もあなたたちの旅路を護られますように",
          DialogueId = 6201816,
          GUID = "0F868D70",
          IsKeyOption = true,
          NextDialogue = 6201817,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201817] = {
          ContentJP = "あなたの話を聞くと、ミルトンの顔には満足した微笑みを浮かべた。カリスタも言い返さずに背を向けた。彼女の表情は見えない。\nあなたは彼らに頷いてから、振り向いて立ち去った。",
          DialogueId = 6201817,
          GUID = "0F868D9A",
          RougeTalkActorType = 3
        },
        [6201818] = {
          ContentJP = "満月の神は私を助けられないかもしれない。",
          DialogueId = 6201818,
          GUID = "0F868DC4",
          IsKeyOption = true,
          NextDialogue = 6201819,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201819] = {
          ContentJP = "あなたの話を聞くと、ミルトンはあわてて視線をそらし、それ以上言わなかった。カリスタはあなたに悲しげな微笑みを投げ、また疲れそうに頭を下げた。\nあなたは彼らに頷いてから、振り向いて立ち去った",
          DialogueId = 6201819,
          GUID = "0F868DEE",
          RougeTalkActorType = 3
        },
        [6201820] = {
          ContentJP = "......本当に大事なのは信仰ではなく、我々自身の勇気かもしれない。",
          DialogueId = 6201820,
          GUID = "0F868E18",
          IsKeyOption = true,
          NextDialogue = 6201821,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201821] = {
          ContentJP = "あなたの話を聞くと、ミルトンとカリスタは最初に驚き、次に考え込んだ。\nあなたはこれ以上言わなかった。この言葉は他の人から教えてもらったもので、その真の意味はあなたにも分からない。\nあなたは彼らに頷いてから、振り向いて立ち去った。",
          DialogueId = 6201821,
          GUID = "0F868E42",
          RougeTalkActorType = 3
        },
        [6201901] = {
          ContentJP = "前方から禍々しく強い血の匂いが漂っている。\nその深い暗闇と重苦しい静寂には、あなたが求めているものがないのだと確信を持っているが、誰かがあなたをこの暗闇に引き寄せようとするのを感じているーーあなたは足を踏み出してみた。",
          DialogueId = 6201901,
          GUID = "0F869B62",
          NextDialogue = 6201902,
          RougeTalkActorType = 3
        },
        [6201902] = {
          ContentJP = "突然、周りに白色の光が閃いたーー違う。光ではない。よく見ると、それは穢獣の白い殻だけだった。繋げている殻が重なり、まるである異端者の芸術家が酔ってから創作したもののようにも見える。\nあなたは本能的に一歩後ずさった後、懐かしい二人の姿が現れた。",
          DialogueId = 6201902,
          GUID = "0F869B8C",
          NextDialogue = 6201903,
          RougeTalkActorType = 3
        },
        [6201903] = {
          ContentJP = "「げほっ、げほっ......きりがないな......」\n女魔術師は口元の血を拭き、持っている弓を地に捨てた。\n「矢も使い切ったし......これから魔法にしか頼らない。ふふ、これもあんたが言った神様のために使命を果たしたと言えるでしょうか？せめて野垂れ死にたくないな。」",
          DialogueId = 6201903,
          GUID = "0F869BB6",
          NextDialogue = 6201904,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201904] = {
          ContentJP = "「でたらめを言うなーー後ろに気を付けろ！」\n司祭が杖を振り回し、魔法の光が放った。\n「ちぇ......また暗影か。」",
          DialogueId = 6201904,
          GUID = "0F869BE0",
          NextDialogue = 6201905,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201905] = {
          ContentJP = "あなたはカリスタと同時に振り返り、無数の暗影が襲い掛かってくる。地上に倒れた穢獣の死体は、あの芸術家が創作中にこぼした黒い染料のようだった。\nあなたは慌ててランタンを掲げたが、暗影は止まるふりをまったく示さなかった。ランタンがミルトンの杖を貫いたことにあなたはふと気付いた。",
          DialogueId = 6201905,
          GUID = "0F869C0A",
          NextDialogue = 6201906,
          RougeTalkActorType = 3
        },
        [6201906] = {
          ContentJP = "あなたは分かったーー目の前にあるすべてが記憶の残像だけだ。彼らのそばにいたのに、戦闘で消耗されつつ、負傷し、疲れ果てて地に倒れるのを見捨てる以外、あなたは何もできない。",
          DialogueId = 6201906,
          GUID = "0F869C34",
          NextDialogue = 6201907,
          RougeTalkActorType = 3
        },
        [6201907] = {
          ContentJP = "暗影のほとんどはすでに退散し、最後の四匹......三匹......二匹......一匹しか残らない。二人の若い騎士に反撃する力を持つ者は一人さえいれば、彼らの仲間が少しでも早くこの場に現れることができれば、一欠けらの瑠璃でもここに落ちれば、彼らはこの戦闘で勝ち、生きていけるのに。\nだが……誰も来なかった。遅れてきた傍観者であるあなた以外に。",
          DialogueId = 6201907,
          GUID = "0F869C5E",
          NextDialogue = 6201908,
          RougeTalkActorType = 3
        },
        [6201908] = {
          ContentJP = "彼らの先輩だっただろうか、仲間や友達だっただろうか。あの人間型の暗影がカリスタに近づき、漆黒の槍で彼女の心臓を突き刺した。\nあなたはこの残酷な場面を目にしたくなく、目を閉じた。",
          DialogueId = 6201908,
          GUID = "0F869C88",
          NextDialogue = 6201909,
          RougeTalkActorType = 3
        },
        [6201909] = {
          ContentJP = "「ミルトン......？あんた......どうして......？」",
          DialogueId = 6201909,
          GUID = "0F869CB2",
          NextDialogue = 6201910,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201910] = {
          ContentJP = "あなたは驚いて目を見開くと、その槍がミルトンの胸を貫いていたことに気付いた。暗影が消え去り、彼は力尽きて倒れ、いつもきちんと整えられる襟元がこぼれた鮮血に染まった。",
          DialogueId = 6201910,
          GUID = "0F869CDC",
          NextDialogue = 6201911,
          RougeTalkActorType = 3
        },
        [6201911] = {
          ContentJP = "「何てことをしてしまったんだよ......？あなた......」\n女魔術師は慌ててミルトンのそばに跪き、手を出して治療魔法を使おうとしたが、それは無駄だった。\n「私は異端者だって......いつもそう言ってるでしょう？なぜ......こんな異端者の私のために、命までかけてくれたんだよ？！あなたはまだ......自分の信仰を証明してもいないのに。」",
          DialogueId = 6201911,
          GUID = "0F869D06",
          NextDialogue = 6201912,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201912] = {
          ContentJP = "「私の信仰はこう教えたんだ......仲間を守れってな......どう疑っても.....少なくともこれだけが正しいってことに自信がある。」\nいつも重々しい顔をしていた司祭は、最期を迎える際に、ようやく生きている人しか見せない生き生きとした笑顔を浮かべた。\n「神に捧げたものはもう十分だと思う......最後に、私の本音を聞いてほしいんだ。カリスタ......使命も責任も忘れて、ここから離れて生きていきなさい。」",
          DialogueId = 6201912,
          GUID = "0F869D30",
          NextDialogue = 6201913,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201913] = {
          ContentJP = "「な.....？」",
          DialogueId = 6201913,
          GUID = "0F869D5A",
          NextDialogue = 6201914,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201914] = {
          ContentJP = "「私がいなくなったら、あんたは自分の指揮官になれ。自分の意志で行動すればいい。あんたの言っていたように、逃げて......この深淵から、あの旅人さんを探しに行ってもいい......生きていけるなら、どうしたっていい。」",
          DialogueId = 6201914,
          GUID = "0F869D84",
          NextDialogue = 6201915,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201915] = {
          ContentJP = "涙がぽつりと彼女の白い頬に沿って零れ落ち、ミルトンの襟に止まった。それはすでに固まり始めていた血の塊を、再び解かせた。\n「しかし、たった一人で......どこまで行けるのでしょう......」",
          DialogueId = 6201915,
          GUID = "0F869DAE",
          NextDialogue = 6201916,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6201916] = {
          ContentJP = "「また......馬鹿なことを言ってる。」\n司祭は、かつて杖を握りしめる手で、胸元の勲章をカリスタに渡した。\n「私たちの中で成績が一番優れていたのは君だ。ここに来てからも、最初に事実を見破り、現状を疑う勇気が持つのも君だ......君なら......きっと......生きていける......」",
          DialogueId = 6201916,
          GUID = "0F869DD8",
          NextDialogue = 6201917,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Milton"
        },
        [6201917] = {
          ContentJP = "ミラージュは消えていった。あなたはカリスタの答えを聞こえなかった。\n静まり返った闇の中で、あなたは司祭の冷たい体を見つけた。黒い影が彼の傷口から湧き出し、彼ももうすぐ、あなたが見てきたあの人たちのように、永遠に安息できない暗影になるのだ。",
          DialogueId = 6201917,
          GUID = "0F869E02",
          NextOptions = {
            [1] = 6201918,
            [2] = 6201920
          },
          RougeTalkActorType = 3
        },
        [6201918] = {
          ContentJP = "（彼の苦痛を終わらせる。）",
          DialogueId = 6201918,
          GUID = "0F869E2C",
          IsKeyOption = true,
          NextDialogue = 6201919,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201919] = {
          ContentJP = "彼が完全に暗影になる前に、あなたはランタンの力を使い、彼の命を断った。\n「ありがとう......」\nあなたはまたこんな声を聞いた。あるいは、それはただ自分を慰めるための幻に過ぎなかったのだ。",
          DialogueId = 6201919,
          GUID = "0F869E56",
          RougeTalkActorType = 3
        },
        [6201920] = {
          ContentJP = "（手を出すのに忍びない。）",
          DialogueId = 6201920,
          GUID = "0F869E80",
          IsKeyOption = true,
          NextDialogue = 6201921,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6201921] = {
          ContentJP = "あなたは一歩後ずさり、このまま立ち去ろうとした。\nしかし、暗影は立ち上がった。かつて力尽きて友人の手から滑り落ちたあの蒼白の手が、再び杖を握りしめ、攻めてくる。\nあなたはため息をつき、武器を取り直し、いつものように暗影を倒した。",
          DialogueId = 6201921,
          GUID = "0F869EAA",
          RougeTalkActorType = 3
        },
        [6202001] = {
          ContentJP = "あなたはもう一度、輪廻の果てにたどり着いた。\n集めてきた深淵と対抗する瑠璃の数が足りないため、もう一度時間を巻き戻す必要がある。",
          DialogueId = 6202001,
          GUID = "0F86ABCA",
          NextDialogue = 6202002,
          RougeTalkActorType = 3
        },
        [6202002] = {
          ContentJP = "あなたは混沌の流れの中で、当てもなく彷徨っているーーその視線をもう何度も受けた。あなたは恐怖すら感じられなくて、ただこの輪廻の最後の数分を平静に感じているだけ。\nふと、あなたは慣れ親しんだ姿を見た。",
          DialogueId = 6202002,
          GUID = "0F86ABF4",
          NextDialogue = 6202003,
          RougeTalkActorType = 3
        },
        [6202003] = {
          ContentJP = "「はぁ......あなた......あなたはまだ生きているの？」\n彼女は崩れ落ちた壁に寄りかかり、ぼろぼろになったマントは彼女の傷だらけの体を遮り切れなかった。\n「あなたは一体何者なの......？どうして、あんな恐ろしいものを目にしても、あなたの目には怯える気配がまったく見つからないの？」",
          DialogueId = 6202003,
          GUID = "0F86AC1E",
          NextOptions = {
            [1] = 6202004,
            [2] = 6202006
          },
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202004] = {
          ContentJP = "もう何度も見たから、輪廻の中で。",
          DialogueId = 6202004,
          GUID = "0F86AC48",
          IsKeyOption = true,
          NextDialogue = 6202005,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6202005] = {
          ContentJP = "「輪廻？」\n彼女の目には一瞬光が閃いた。難題を解いた学者のようだ。\n「あぁ……なるほど。ようやく分かった。道理で私たちをそんな目で見ていたんだね......ご慈悲を......あなたはもう何度も私たちを結末を見ていたんでしょう？輪廻......ふふ......つまり、もうすぐ、彼らに会えることだね......こう考えてみれば、死もそんな恐ろしいものでもなくなったのだ。」",
          DialogueId = 6202005,
          GUID = "0F86AC72",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202006] = {
          ContentJP = "真実を知らない方がいい。",
          DialogueId = 6202006,
          GUID = "0F86AC9C",
          IsKeyOption = true,
          NextDialogue = 6202007,
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [6202007] = {
          ContentJP = "「ふふ......あなたの言う通りね。一体どんなことを経験してから、こんなに強く、怖いとも言える......平静になれるのだろう。私には想像もつかない。」\n彼女の黒い瞳は、何年ぶりの親友のように優しくあなたを見つめていた。\n「なんとなく、まだ教えていないことはたくさんあるんだと思うよ。でもね、あなたにも自分自身の理由があるのでしょう。彼らが堅持してきた信仰のようなもの。」",
          DialogueId = 6202007,
          GUID = "0F86ACC6",
          NextDialogue = 6202008,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202008] = {
          ContentJP = "「これを受け取ってください......できれば、これをいつも傍においてほしい。これは、私の最後のお願いだ......」\n彼女は手を出して、あるノートをあなたに渡した。\n「ミルトンは私に逃げてって言っていたけど、分かってる。もう帰る場所がないんだと。少なくとも......命の最後に、少しでもお役に立てたのであれば。」",
          DialogueId = 6202008,
          GUID = "0F86ACF0",
          NextDialogue = 6202009,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202009] = {
          ContentJP = "「この深淵の中でね.....大分時間がかかっちゃったんだよ。満月の神と闇月の神は、どっちが正しいのかって。ずっと正解を見つけられなかったから、仲間と揉め事さえ起きてしまって。」\n自分を自嘲するように、彼女は感慨深くため息をついた。\n「いまさらよく分かったんだよ.....信仰そのものの真偽は取るに足らないものだ。大事なのは、それを選んだ人が何をしたかってことだ。私の仲間たちは、実際の行動で自分の信仰を最後まで貫いてきたんだ。彼らの行いは正しいと思う。だから、話の最後に、私も彼らの信仰でーー真偽とは関係ないーーあなたに私の祝福を送りたい。」",
          DialogueId = 6202009,
          GUID = "0F86AD1A",
          NextDialogue = 6202010,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202010] = {
          ContentJP = "「では.....旅人よ.....」\n彼女は震えている蒼白の右手を胸元にあて、虚ろな目であなたがいる方向を捕まえようとした。\n「<H>運命の神があなたに千本の月光を降り注ぎ、その翼が満月のように純白でありますように。</>」",
          DialogueId = 6202010,
          GUID = "0F86AD44",
          NextDialogue = 6202011,
          RougeTalkActorType = 1,
          SpeakNpcName = "StoryNPC_Calista"
        },
        [6202011] = {
          ContentJP = "彼女の息は止まった。\nあなたは彼女の目を閉じた。彼女の口元にはまだ穏やかな笑顔が残っており、まるで寝ているだけのようだ。",
          DialogueId = 6202011,
          GUID = "0F86AD6E",
          NextDialogue = 6202012,
          RougeTalkActorType = 3
        },
        [6202012] = {
          ContentJP = "あなたは彼女が残したあのノートを開いた。ノートのページには厚い塵と血の跡がついているが、文字はまだはっきりと見える。\n「私はカリスタ。リュシオン礼賛会所属、天翼騎士団、静寂の黄昏小隊の騎士です。このノートには、聖湖について、私が観測したすべてのことが記録されています。このノートを手に入れた人は、この記録をここから持ち出していただけるようお願いします。」",
          DialogueId = 6202012,
          GUID = "0F86AD98",
          NextDialogue = 6202013,
          RougeTalkActorType = 3
        },
        [6202013] = {
          ContentJP = "ランタンの光の下で、あなたはノートのページをめくっている。乱れた文字は、彼女が暗闇の中で慌ただしく書き上げた様子を物語っている。その中には、すべての暗影の弱点からミラージュの退散策まで、詳しく記録されている。\nあなたはノートの最後の一ページを開いた。\n「確かなのは、<H>闇月教派</>の聖典に記されたすべてのものが嘘だというわけでもないことだ.....すくなくとも、聖湖は神話の中の天国とはまったく関係がなく、いわゆる『神に選ばれる』とは、生贄に近いものだ。ここは、死者が残した悪意と邪念に満ちた場所だけのものだ。」\n「私の家族は闇月教派の敬虔な信者だった。彼らは深淵と闇月の神を信仰し、初代セブンヴァーチェスの一人ーー<H>サリエル</>が二千年前に天国へ行ったのではなく、この聖湖の底で<H>魔王</>になったと固く信じていた。魔王というのは、深淵の核でもある。彼はネーファへ貢を納めるために、魂を吞み込み続けているのだ。」",
          DialogueId = 6202013,
          GUID = "0F86ADC2",
          NextDialogue = 6202014,
          RougeTalkActorType = 3
        },
        [6202014] = {
          ContentJP = "「私は生きてきた人生の中で、ずっと正教で身を慎んできたーーそれらの怖い伝説を信じたくないからだ。しかし、この深淵は常に私に問いかけている：闇月派の教義が真実だとしたら......我々の世界の果ては、本当に暗闇と虚無なのだろうーー」\n「そして、深淵は本当に勝てないのだろう？」\n「ただ、こんなぼろぼろになった体では、答えを見つけられるはずもないだろう。」",
          DialogueId = 6202014,
          GUID = "0F86ADEC",
          NextDialogue = 6202015,
          RougeTalkActorType = 3
        },
        [6202015] = {
          ContentJP = "「ミルトンが教えてくれたんだ。かつて、特殊な力が宿っている<H>コローネ</>という<H>聖剣</>が聖湖で思わぬことにより壊れてしまったって......そして、深淵の中で偶然出会った旅人が持つランタンにも、暗影を退治できそうな力がある。」\n「もし深淵に勝てるものが本当に存在するならば、この二つのものは何かのカギにもなれるのではないかと思う。」",
          DialogueId = 6202015,
          GUID = "0F86AE16",
          NextDialogue = 6202016,
          RougeTalkActorType = 3
        },
        [6202016] = {
          ContentJP = "ノートはまだ何ページも残っており、あなたは残りの部分を読みたくてたまらなくなるーー彼女はどれだけ真相に近づいていたのだろうか？\nしかしもうすぐ、あなたはノートの後半の内容は深淵とは全く関係のないものだと気付いた。",
          DialogueId = 6202016,
          GUID = "0F86AE40",
          NextDialogue = 6202017,
          RougeTalkActorType = 3
        },
        [6202017] = {
          ContentJP = "「このノートを読んでいる方よ。ここまで読んでくれてありがとう。彼らの名前も覚えてもらえるか？」",
          DialogueId = 6202017,
          GUID = "0F86AE6A",
          NextDialogue = 6202018,
          RougeTalkActorType = 3
        },
        [6202018] = {
          ContentJP = "あなたの思いは、しばらくの間、深淵から離れ、別の世界へと連れられていった。エリュシオン騎士団の営地の小さな寮で、柔らかい黄色の明りの下で、あなたは若い騎士の日記を見つけ、彼女と三人の友達の物語を読み始めた",
          DialogueId = 6202018,
          GUID = "0F86AE94",
          NextDialogue = 6202019,
          RougeTalkActorType = 3
        },
        [6202019] = {
          ContentJP = "彼らは一緒に軍事訓練に参加していたーー\n『君たち、まるでひとつのチームみたいじゃん。』－－何回もこのように教官に言われると、フーリンは本気で燃えてきて、この『チーム』に名を付けようと考え始めた。ケイシーもすぐに相槌を打ったーーまあ、これは何とも言えないね。あの二人はいつも一緒にふざけているから。だけど、ミルトンも賛成するとは思わなかった。まさかこいつ、英雄になりたい夢でもあんのかな？」\n「『静寂の黄昏』と『勇敢のじゃが芋』はそれぞれフーリンとケイシーが出したチーム名の候補だった。私とミルトンは迷わずに前者に投票した。あの日の昼ご飯は肉じゃがだったということから見ると、『勇敢のじゃが芋』はケイシーが昼食中にふと思いついた名前の可能性は十分高い。」\n「フーリンがつけたこの名前、『黄昏』…… ふふ、他人は気づかなかったかもしれないが、私たちはすぐに分かったよ。これは、彼が最も敬愛する『月昇り』の騎士に、密かに敬意を表しているんだ。」",
          DialogueId = 6202019,
          GUID = "0F86AEBE",
          NextDialogue = 6202020,
          RougeTalkActorType = 3
        },
        [6202020] = {
          ContentJP = "みんなで一緒に戦場に踏み込んだ時 ——\n「行軍中、ケイシーはいつも気づかないうちにどこかへ消えちゃうんだった。最初はみんな心配してたけど、いつも思いがけないタイミングで突然現れてびっくりさせるから、後ではもう慣れちゃったよ。でもさ、どうしてそんなことができるんだろう？ あの子の頭では、瞬間移動みたいな難しい魔法なんか絶対に習得できないのに……」\n「ミルトンの本の虫って、なんと戦場まで本を持って来て、暇な時に読もうって言うの？！ なんて言ったらいいのか分からない……」\n「後で、ミルトンの本は帝国軍のロケット弾一発でまるっと燃え尽きちゃった。あの日は一日中クマ顔してたけど…… むしろあの帝国兵に感謝すべきだと思うんだ。少なくともリュックの重さが三分の二は減ったからな。」",
          DialogueId = 6202020,
          GUID = "0F86AEE8",
          NextDialogue = 6202021,
          RougeTalkActorType = 3
        },
        [6202021] = {
          ContentJP = "彼らは一緒に使命を受けたーー\n「面倒くさいのを避けるため、深淵討伐に申し込んだことは親には言わなかったんだ。ただ兄にだけ話したのに…… まさか彼も親たちと同じように、くどくど言い続けるとは思わなかった。「深淵は礼賛会の陰謀だ」「魔王はみんなを生贄にするぞ」なんて…… 本当にうるさくてウンザリだ。」\n「実はね、私は深淵を討伐するなんて全然興味ないんだ。でもフーリンがすごく積極的だから、反対するのも悪いなって思った。前まで参加した戦闘では、俺たちは主役になったことなんかなく、いつも負けることの方が多かった。彼はきっと自分を証明する機会が欲しかったんだろう…… だから、彼の騎士の夢を叶えてあげるつもりだ。いずれにしても、みんなが一緒なら、どこへ行ってもあまり変わらないよ。」",
          DialogueId = 6202021,
          GUID = "0F86AF12",
          NextDialogue = 6202022,
          RougeTalkActorType = 3
        },
        [6202022] = {
          ContentJP = "……",
          DialogueId = 6202022,
          GUID = "0F86AF3C",
          NextDialogue = 6202023,
          RougeTalkActorType = 3
        },
        [6202023] = {
          ContentJP = "日記の最後の一ページをめくる。",
          DialogueId = 6202023,
          GUID = "0F86AF66",
          NextDialogue = 6202024,
          RougeTalkActorType = 3
        },
        [6202024] = {
          ContentJP = "「沈黙の神よ、本当にミルトンが言っていたように、あなたは常に私たちを見つめているのならば......最後のお願いを聞いてくれ。」\n「私の魂に彼らと再会させよう。」\n「叶えてくれるなら、あなたの冷酷、残酷、あなたがもたらした苦難、ついた嘘、何もかも許してあげる。」",
          DialogueId = 6202024,
          GUID = "0F86AF90",
          NextDialogue = 6202025,
          RougeTalkActorType = 3
        },
        [6202025] = {
          ContentJP = "<H>「我の翼はもう満月の光もいらなく、そよ風に乗せて、仲間がいる世界へと飛んでいくことしか望んでいない。」</>",
          DialogueId = 6202025,
          GUID = "0F86AFBA",
          NextDialogue = 6202026,
          RougeDialogueMainIcon = "Texture2D'/Game/UI/Texture/Dynamic/Image/RougeLike/T_Rouge_Story13.T_Rouge_Story13'",
          RougeTalkActorType = 3
        },
        [6202026] = {
          ContentJP = "日記を閉じて、あなたの指先はまだページに残されている書き手の温度を感じられる。",
          DialogueId = 6202026,
          GUID = "0F86AFE4",
          NextDialogue = 6202027,
          RougeTalkActorType = 3
        },
        [6202027] = {
          ContentJP = "「私は......絶対に輪廻を終わらせて、輝かしい満月の下で、あなたたちが再び会えるようにしてあげる。」",
          DialogueId = 6202027,
          GUID = "0F86B00E",
          RougeTalkActorType = 2,
          SpeakNpcId = 910004
        },
        [7002001] = {
          ContentJP = "お見舞い品が所狭しと積まれている。ここ数日、見舞いの者が大勢来ていたようだ。\n名も知らぬ花や冷めてしまっても香ばしい肉スープ、傷だらけだが精巧なオルゴール、小鳥の絵が描かれた綿菓子の缶……\n中には、名の記されていない少し歪んだリボンが結ばれた質素な贈り物が混ざっていた。開けてみると、帝国で最高級の鎮痛剤が一本入っている。気持ちはありがたいが、気絶状態の者に鎮痛剤を贈るのは、どう考えても意味がない。",
          DialogueId = 7002001,
          GUID = "11875DCA"
        },
        [7003001] = {
          ContentJP = "近日、アイスレイク城の外城区で残忍な傷害事件が多発し、現場は混乱状態に陥っております。深夜の外出を控え、戸締まりを徹底してください。\n武器免許を所持する市民は、犯人と遭遇した際、決して反撃せず（非常にキケン！！！）、 身の安全を確保することを優先してください。\n犯人の手がかりがある方は、警備部隊のリズム・フィッシャーまでご連絡ください。\n忠実なる民は皇帝のご加護を得られるでしょう。皇帝に栄光あれ。",
          DialogueId = 7003001,
          GUID = "118801DA"
        },
        [10010101] = {
          Camera = "67.539062,-1123.730225,550.733276,0.000081,-22.799314,91.999741,35.0,1000.0,false,Manual,2.8",
          ContentJP = "{性别:ベレ、僕は……|ベレ、私は……}",
          DefaultLookAt = "KeepState",
          DialogueId = 10010101,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "190F2A32",
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 408001,
            [4] = 201001
          },
          SpeakNpcId = 100001,
          Subtitle = "Berry, I...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A32"
        },
        [10010102] = {
          ContentJP = "しーっ……",
          DialogueId = 10010102,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2A5C",
          SpeakNpcId = 100003,
          Subtitle = "Ssh...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A5C"
        },
        [10010103] = {
          ContentJP = "大丈夫？",
          DialogueId = 10010103,
          DisableMouth = 1,
          Duration = 2,
          GUID = "190F2A86",
          SpeakNpcId = 100003,
          Subtitle = "Are you all right?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2A86"
        },
        [10010104] = {
          ContentJP = "うん。",
          DialogueId = 10010104,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "190F2AB0",
          SpeakNpcId = 100001,
          Subtitle = "Yeah.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2AB0"
        },
        [10010105] = {
          ContentJP = "まだ休んでていいよ。ずっと傍にいる。おいていったりしないから。",
          DialogueId = 10010105,
          DisableMouth = 1,
          Duration = 5,
          GUID = "190F2ADA",
          SpeakNpcId = 100003,
          Subtitle = "Get some more sleep. I won't leave — I'll be right here when you wake up.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2ADA"
        },
        [10010106] = {
          ContentJP = "もう平気。山を下りて帰らないと。",
          DialogueId = 10010106,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F2B04",
          SpeakNpcId = 100001,
          Subtitle = "It's okay. We should get down the mountain and head to the village.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B04"
        },
        [10010107] = {
          ContentJP = "今から戻る？村から咆哮が聞こえるけど…",
          DialogueId = 10010107,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F2B2E",
          SpeakNpcId = 100003,
          Subtitle = "You wanna go back? There've been roars coming from there for days...",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B2E"
        },
        [10010108] = {
          ContentJP = "家にはたしか武器があったと思うよ。あれがあれば――",
          DialogueId = 10010108,
          DisableMouth = 1,
          Duration = 4.5,
          ExStoryInfo = "Player",
          GUID = "190F2B58",
          SpeakNpcId = 100001,
          Subtitle = "I was thinking, if we could make it home and grab our weapons—",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B58"
        },
        [10010109] = {
          ContentJP = "ずっとここにいても仕方ないし、",
          DialogueId = 10010109,
          DisableMouth = 1,
          Duration = 2.5,
          ExStoryInfo = "Player",
          GUID = "190F2B82",
          SpeakNpcId = 100001,
          Subtitle = "And with your strength, you'll find a way out. ",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B82"
        },
        [10010110] = {
          ContentJP = "ベレの力があればきっと大丈夫。",
          DialogueId = 10010110,
          DisableMouth = 1,
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "190F2B83",
          SpeakNpcId = 100001,
          Subtitle = "No one's gonna save us no matter how long we stay here anyway.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2B83"
        },
        [10010111] = {
          ContentJP = "……行こうか。",
          DialogueId = 10010111,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F2BAC",
          SpeakNpcId = 100003,
          Subtitle = "...Let's go then.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAC"
        },
        [10010112] = {
          ContentJP = "焦らず、ゆっくりね。",
          DialogueId = 10010112,
          GUID = "190F2BAD",
          SpeakNpcId = 100003,
          Subtitle = "Take it easy.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAD"
        },
        [10010113] = {
          ContentJP = "足元に気をつけて、踏み外さないように。",
          DialogueId = 10010113,
          GUID = "190F2BAE",
          SpeakNpcId = 100003,
          Subtitle = "Watch your step.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAE"
        },
        [10010114] = {
          ContentJP = "怪我、まだ治っていないよね？本当に平気？",
          DialogueId = 10010114,
          GUID = "190F2BAF",
          NextDialogue = 10010115,
          SpeakNpcId = 100003,
          Subtitle = "You're not fully recovered. Are you sure you can do this?",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BAF"
        },
        [10010115] = {
          ContentJP = "大丈夫。この程度の裂け目を越えるくらいなら。",
          DialogueId = 10010115,
          ExStoryInfo = "Player",
          GUID = "190F2BB1",
          NextDialogue = 10010116,
          SpeakNpcId = 100001,
          Subtitle = "I'm okay. It's just a few scratches.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB1"
        },
        [10010116] = {
          ContentJP = "無理はしないで。<Default note=\"text:エジュウ\">穢獣</>に出くわす前に体力を使い果たさないようにね。",
          DialogueId = 10010116,
          GUID = "190F2BB2",
          SpeakNpcId = 100003,
          Subtitle = "Don't push yourself too hard. We still have to save some strength for those Filthoids.",
          VoiceName = "voice/$Locale$/story/1001/100101/190F2BB2"
        },
        [10010201] = {
          ContentJP = "生き延びたくば、真実を話しなさい。",
          DialogueId = 10010201,
          Duration = 4,
          GUID = "190F3A9A",
          SpeakNpcId = 100005,
          Subtitle = "Tell me the truth if you want to live.",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3A9A"
        },
        [10010202] = {
          ContentJP = "ここへ来た理由と、お前の仲間の正体……",
          DialogueId = 10010202,
          Duration = 5,
          GUID = "190F3AC4",
          SpeakNpcId = 100005,
          Subtitle = "Why are you here, who's with you,",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AC4"
        },
        [10010203] = {
          ContentJP = "お前自身のこともね。",
          DialogueId = 10010203,
          Duration = 3.5,
          GUID = "190F3AEE",
          SpeakNpcId = 100005,
          Subtitle = "and who on earth are you?",
          VoiceName = "voice/$Locale$/story/1001/100102/190F3AEE"
        },
        [10010204] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010204,
          Duration = 2,
          GUID = "190F3AEF",
          NextDialogue = 10010205
        },
        [10010205] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010205,
          Duration = 2,
          GUID = "190F3AF0",
          NextDialogue = 10010206
        },
        [10010206] = {
          Camera = "10000,11000,2000,0.000046,-4.799929,73.987312,35.0,150.0,false,Manual,2.8",
          Content = "……",
          DialogueId = 10010206,
          Duration = 2,
          GUID = "190F3AF1"
        },
        [10010301] = {
          Content = "我们现在赤手空拳，尽可能避开它们吧。",
          DialogueId = 10010301,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "190F4B02",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100103/190F4B02"
        },
        [10010401] = {
          ContentJP = "剣はしっかり持っておいてね。きっと役に立つはずだから。",
          DialogueId = 10010401,
          DisableMouth = 1,
          Duration = 3,
          GUID = "190F5B6A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001
          },
          SpeakNpcId = 100003,
          Subtitle = "Take that sword with you. It might be helpful one day.",
          TalkActionId = {
            [1] = "100001:FuXiong_Start"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B6A"
        },
        [10010402] = {
          ContentJP = "<Default note=\"text:エジュウ\">穢獣</>は私が。自分の身は自分で守って。",
          DialogueId = 10010402,
          DisableMouth = 1,
          Duration = 4,
          GUID = "190F5B94",
          SpeakNpcId = 100003,
          Subtitle = "Keep yourself safe. I'll take care of these Filthoids.",
          TalkActionId = {
            [1] = "100001:FuXiong_End"
          },
          VoiceName = "voice/$Locale$/story/1001/100104/190F5B94"
        },
        [10010501] = {
          Content = "拿起剑的时候，熟悉而陌生的记忆涌上来……",
          DialogueId = 10010501,
          Duration = 3,
          GUID = "190F6BD2",
          NextDialogue = 10010502,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100105/190F6BD2"
        },
        [10010502] = {
          Content = "……已经很久没有像这样战斗过了。",
          DialogueId = 10010502,
          Duration = 2.5,
          GUID = "190F6BFC",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100105/190F6BFC"
        },
        [10010601] = {
          ContentJP = "行こう、桟橋へ。",
          DialogueId = 10010601,
          Duration = 2,
          GUID = "190F7D0C",
          SpeakNpcId = 100003,
          Subtitle = "Let's head to the wharf.",
          VoiceName = "voice/$Locale$/story/1001/100106/190F7D0C"
        },
        [10010701] = {
          ContentJP = "チッ……船を一艘も残してくれないなんて……",
          DialogueId = 10010701,
          GUID = "190F8CA2",
          NextDialogue = 10010702,
          SpeakNpcId = 100003,
          Subtitle = "Ugh, they didn't leave even one single boat.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CA2"
        },
        [10010702] = {
          ContentJP = "{性别:<Default note=\"text:エジュウ\">穢獣</>が現れた時、ベレは村にいたんだよね？僕を探しに戻らなければ、ベレひとりで逃げられたはず……|<Default note=\"text:エジュウ\">穢獣</>が現れた時、ベレはまだ村にいたんだよね？私を探しに戻らなければ、ベレひとりで逃げられたはず……}",
          DialogueId = 10010702,
          ExStoryInfo = "Player",
          GUID = "190F8CCC",
          NextDialogue = 10010703,
          SpeakNpcId = 100001,
          Subtitle = "You were at the village when the Filthoids came, weren't you? If it wasn't for coming back for me, you could have escaped with them.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CCC"
        },
        [10010703] = {
          ContentJP = "バカなことを言わないで。海岸沿いに使える船がないか探してみよう。",
          DialogueId = 10010703,
          GUID = "190F8CF6",
          SpeakNpcId = 100003,
          Subtitle = "Don't be silly. You'd have done the same for me. Let's search along the shore and see if there's any old boats or something.",
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CF6"
        },
        [10010704] = {
          Content = "别说傻话。我们先沿着海岸找找有没有废旧的船。",
          DialogueId = 10010704,
          GUID = "190F8CF7",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100107/190F8CF7"
        },
        [10010801] = {
          Camera = "233.692749,98.025391,337.437744,0.000525,-38.008308,-170.090546,35.000008,500.0,false,Disable,22.0",
          ContentJP = "これは……村の誰かが逃げる時に落としたのかな？",
          DefaultLookAt = "KeepState",
          DialogueId = 10010801,
          ExStoryInfo = "Player",
          FinalCamera = "233.692749,98.025391,306.806396,0.000525,-38.008308,-170.090546,35.000008,500.0,false,Disable,22.0",
          GUID = "190F9D0A",
          LookAt = {
            [1] = "100001:p(QuestPoint102)",
            [2] = "100003:p(QuestPoint102)"
          },
          NextDialogue = 10010802,
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001
          },
          SpeakNpcId = 100001,
          Subtitle = "Look... Someone must have lost them when they ran away.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D0A"
        },
        [10010802] = {
          Camera = "45.787476,-42.09668,191.500977,0.000512,-35.408981,145.509857,30.0,500.0,false,Disable,22.0",
          ContentJP = "そうね、もらっておこうか。準備はしておくに越したことはないから。",
          DefaultLookAt = "KeepState",
          DialogueId = 10010802,
          FinalCamera = "25.377319,-28.079102,173.898438,0.000512,-35.408981,145.509857,30.0,500.0,false,Disable,22.0",
          GUID = "190F9D34",
          SpeakNpcId = 100003,
          Subtitle = "Hmm, let's grab one. It's always good to be well-armed.",
          TalkActionId = {
            [1] = "100003:Agree"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1001/100108/190F9D34"
        },
        [10010901] = {
          Content = "这边。",
          DialogueId = 10010901,
          Duration = 2,
          GUID = "190FAD9D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100109/190FAD9D"
        },
        [10011001] = {
          ContentJP = "また<Default note=\"text:エジュウ\">穢獣</>が……",
          DialogueId = 10011001,
          GUID = "190FBDDA",
          NextDialogue = 10011002,
          SpeakNpcId = 100003,
          Subtitle = "More Filthoids are coming...",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBDDA"
        },
        [10011002] = {
          ContentJP = "{nickname}、私からあまり離れないように。何かあったら合図を出して知らせて。",
          DialogueId = 10011002,
          GUID = "190FBE04",
          NextDialogue = 10011003,
          SpeakNpcId = 100003,
          Subtitle = "Stay close, Phoxhunter. If necessary, give out the secret signals.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE04"
        },
        [10011003] = {
          ContentJP = "覚えているかな？前に、山の中で動物に気づかれないよう身振りの合図を決めたよね。",
          DialogueId = 10011003,
          GUID = "190FBE05",
          NextDialogue = 10011004,
          SpeakNpcId = 100003,
          Subtitle = "We made them up earlier so as not to alert the beasts up the mountain, remember?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE05"
        },
        [10011004] = {
          ContentJP = "うん。",
          DialogueId = 10011004,
          ExStoryInfo = "Player",
          GUID = "190FBE06",
          NextDialogue = 10011005,
          SpeakNpcId = 100001,
          Subtitle = "Yeah.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE06"
        },
        [10011005] = {
          ContentJP = "じゃあ、確認しよう。右肩を2回叩く、この合図の意味は？",
          DialogueId = 10011005,
          GUID = "190FBE07",
          NextDialogue = 10011006,
          SpeakNpcId = 100003,
          Subtitle = "Alright, a quick check — Two pats on the right shoulder means...?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE07"
        },
        [10011006] = {
          ContentJP = "「後ろに気をつけて」",
          DialogueId = 10011006,
          ExStoryInfo = "Player",
          GUID = "190FBE08",
          NextDialogue = 10011007,
          SpeakNpcId = 100001,
          Subtitle = "\"Watch your back.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE08"
        },
        [10011007] = {
          ContentJP = "心臓のところを2回叩く、この合図は？",
          DialogueId = 10011007,
          GUID = "190FBE09",
          NextDialogue = 10011008,
          SpeakNpcId = 100003,
          Subtitle = "And two taps on the chest?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBE09"
        },
        [10011008] = {
          ContentJP = "「近くに来て」",
          DialogueId = 10011008,
          ExStoryInfo = "Player",
          GUID = "190FBEA0",
          NextDialogue = 10011009,
          SpeakNpcId = 100001,
          Subtitle = "\"Come closer.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA0"
        },
        [10011009] = {
          ContentJP = "鼻を触る。",
          DialogueId = 10011009,
          GUID = "190FBEA1",
          NextDialogue = 10011010,
          SpeakNpcId = 100003,
          Subtitle = "And scraping on the nose?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA1"
        },
        [10011010] = {
          ContentJP = "「もう大丈夫」",
          DialogueId = 10011010,
          ExStoryInfo = "Player",
          GUID = "190FBEA2",
          NextDialogue = 10011011,
          SpeakNpcId = 100001,
          Subtitle = "\"Everything's okay now.\"",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA2"
        },
        [10011011] = {
          ContentJP = "正解よ。最後のひとつ――連続で3回まばたき、この合図は？",
          DialogueId = 10011011,
          GUID = "190FBEA3",
          NextDialogue = 10011012,
          SpeakNpcId = 100003,
          Subtitle = "Good. And the last one — three quick blinks?",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA3"
        },
        [10011012] = {
          ContentJP = "……ごめん、忘れた。",
          DialogueId = 10011012,
          ExStoryInfo = "Player",
          GUID = "190FBEA4",
          NextDialogue = 10011013,
          SpeakNpcId = 100001,
          Subtitle = "...I forgot that.",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA4"
        },
        [10011013] = {
          ContentJP = "覚えておいて、まばたき3回の意味は――",
          DialogueId = 10011013,
          GUID = "190FBEA5",
          NextDialogue = 10011014,
          SpeakNpcId = 100003,
          Subtitle = "Remember, three quick blinks means—",
          VoiceName = "voice/$Locale$/story/1001/100110/190FBEA5"
        },
        [10011014] = {
