          VoiceName = "voice/$Locale$/story/1001/100120/19106218"
        },
        [10012005] = {
          ContentJP = "さもないと、そいつの命は――",
          DialogueId = 10012005,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "19106219",
          SpeakNpcId = 100005,
          Subtitle = "Otherwise, Phoxhunter will—",
          VoiceName = "voice/$Locale$/story/1001/100120/19106219"
        },
        [10012006] = {
          ContentJP = "……約束して。",
          DefaultLookAt = "KeepState",
          DialogueId = 10012006,
          DisableMouth = 1,
          Duration = 1.7,
          GUID = "1910623E",
          SpeakNpcId = 100003,
          Subtitle = "...Give me your word.",
          VoiceName = "voice/$Locale$/story/1001/100120/1910623E"
        },
        [10012007] = {
          ContentJP = "何を？",
          DialogueId = 10012007,
          DisableMouth = 1,
          Duration = 1,
          GUID = "1910623F",
          SpeakNpcId = 100005,
          Subtitle = "Hmm?",
          VoiceName = "voice/$Locale$/story/1001/100120/1910623F"
        },
        [10012008] = {
          ContentJP = "私が行く代わりにこの子は見逃して。",
          DefaultLookAt = "KeepState",
          DialogueId = 10012008,
          DisableMouth = 1,
          Duration = 4,
          GUID = "19106268",
          LookAt = {
            [1] = "100007:n(100005)"
          },
          SpeakNpcId = 100003,
          Subtitle = "I'll go back with you, but you have to promise to let Phoxhunter go.",
          VoiceName = "voice/$Locale$/story/1001/100120/19106268"
        },
        [10012009] = {
          ContentJP = "約束しないなら私たちの死体を持ち帰るのね！",
          DefaultLookAt = "KeepState",
          DialogueId = 10012009,
          DisableMouth = 1,
          Duration = 3.5,
          GUID = "19106292",
          SpeakNpcId = 100003,
          Subtitle = "Give me your word! Or, you can take two corpses back!",
          VoiceName = "voice/$Locale$/story/1001/100120/19106292"
        },
        [10012010] = {
          ContentJP = "誤解しているみたいだけど、これは「交渉」じゃなくて、「命令」なのよ。",
          DefaultLookAt = "Self",
          DialogueId = 10012010,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "190F7C64",
          LookAt = {
            [1] = "100005:n(100005)"
          },
          SpeakNpcId = 100005,
          Subtitle = "Perhaps I wasn't clear — This is not a negotiation, it's an order.",
          VoiceName = "voice/$Locale$/story/1001/100106/190F7C64"
        },
        [10012011] = {
          ContentJP = "……ベレ。",
          DefaultLookAt = "KeepState",
          DialogueId = 10012011,
          DisableMouth = 1,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "191062E6",
          LookAt = {
            [1] = "100005:n(100003)"
          },
          SpeakNpcId = 100001,
          Subtitle = "...Berry.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E6"
        },
        [10012012] = {
          ContentJP = "……？！ダメ……！",
          DialogueId = 10012012,
          DisableMouth = 1,
          Duration = 1,
          GUID = "191062E7",
          SpeakNpcId = 100003,
          Subtitle = "...?! No...!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E7"
        },
        [10012013] = {
          ContentJP = "逃げて。",
          DialogueId = 10012013,
          DisableMouth = 1,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "191062E8",
          SpeakNpcId = 100001,
          Subtitle = "Get out of here, and live.",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E8"
        },
        [10012014] = {
          ContentJP = "いやあぁぁ――――！！",
          DialogueId = 10012014,
          DisableMouth = 1,
          Duration = 1.5,
          GUID = "191062E9",
          SpeakNpcId = 100003,
          Subtitle = "No—!!",
          VoiceName = "voice/$Locale$/story/1001/100120/191062E9"
        },
        [10012015] = {
          ContentJP = "{nickname}、テストするよ。「まばたき3回」の合図は――",
          DialogueId = 10012015,
          Duration = 5,
          GUID = "191062F0",
          SpeakNpcId = 100003,
          Subtitle = "Quick question, Phoxhunter. The \"three quick blinks\" means—",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F0"
        },
        [10012016] = {
          ContentJP = "心配性だねベレは。もう覚えたよ！まばたき3回の意味は……",
          DialogueId = 10012016,
          Duration = 6,
          ExStoryInfo = "Player",
          GUID = "191062F1",
          SpeakNpcId = 100001,
          Subtitle = "I've got this, Berry. Three quick blinks means...",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F1"
        },
        [10012017] = {
          ContentJP = "「たとえひとりになっても、強く生きる」",
          DialogueId = 10012017,
          DialoguePanelType = "None",
          Duration = 5,
          ExStoryInfo = "Player",
          GUID = "191062F2",
          SpeakNpcId = 100001,
          Subtitle = "\"Even if left all alone, you should be brave and live on.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F2"
        },
        [10012018] = {
          ContentJP = "{性别:「僕たちが、また会う日まで」|「私たちが、また会う日まで」}",
          DialogueId = 10012018,
          DialoguePanelType = "None",
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "191062F3",
          SpeakNpcId = 100001,
          Subtitle = "\"Until the day we meet again.\"",
          VoiceName = "voice/$Locale$/story/1001/100120/191062F3"
        },
        [10012101] = {
          ContentJP = "その力は……？",
          DialogueId = 10012101,
          Duration = 1.5,
          GUID = "19107252",
          NextDialogue = 10012102,
          SpeakNpcId = 100005,
          Subtitle = "What the...",
          VoiceName = "voice/$Locale$/story/1001/100121/19107252"
        },
        [10012102] = {
          ContentJP = "No.0の力はまだ解放されていないのに、どうして……",
          DialogueId = 10012102,
          Duration = 2.5,
          GUID = "1910727C",
          NextDialogue = 10012103,
          SpeakNpcId = 100005,
          Subtitle = "No. 0 isn't supposed to release all her powers yet. Why is she...?",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727C"
        },
        [10012103] = {
          ContentJP = "いえ……これはNo.0自身の力ではないわ。他者から与えられた「レゾナンス」ね。",
          DialogueId = 10012103,
          Duration = 3,
          GUID = "1910727D",
          NextDialogue = 10012104,
          SpeakNpcId = 100005,
          Subtitle = "No, that's not her power, it's Resonance.",
          VoiceName = "voice/$Locale$/story/1001/100121/1910727D"
        },
        [10012104] = {
          ContentJP = "……No.0が庇っている……あのチビが「レゾナンス」の新しい宿主であると？",
          DialogueId = 10012104,
          Duration = 2.5,
          GUID = "191072A6",
          NextDialogue = 10012110,
          SpeakNpcId = 100005,
          Subtitle = "...That brat she's protecting... that's the new receptacle for Resonance?",
          VoiceName = "voice/$Locale$/story/1001/100121/191072A6"
        },
        [10012105] = {
          ContentJP = "「レゾナンス」と「No.0」が同時に現れるなんて、一体何を意味しているのか……",
          DialogueId = 10012105,
          Duration = 3,
          GUID = "191072D0",
          SpeakNpcId = 100005,
          Subtitle = "It made its appearance again here... What does this truly implies...",
          VoiceName = "voice/$Locale$/story/1001/100121/191072D0"
        },
        [10012110] = {
          ContentJP = "そういうば、あのチビの顔も......",
          DialogueId = 10012110,
          GUID = "191072D1",
          NextDialogue = 10012105,
          SpeakNpcId = 100005,
          VoiceName = "voice/$Locale$/story/1001/100121/191072D1"
        },
        [10012201] = {
          ContentJP = "逃げて！",
          DialogueId = 10012201,
          Duration = 2,
          GUID = "191082BA",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 201003
          },
          SpeakNpcId = 100003,
          Subtitle = "Run!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BA"
        },
        [10012202] = {
          ContentJP = "させるか！",
          DialogueId = 10012202,
          Duration = 2,
          GUID = "191082BB",
          SpeakNpcId = 100006,
          Subtitle = "You can't get away!",
          VoiceName = "voice/$Locale$/story/1001/100122/191082BB"
        },
        [10012301] = {
          Content = "你的伤……好些没有？",
          DialogueId = 10012301,
          Duration = 2,
          GUID = "19109322",
          NextDialogue = 10012302,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/19109322"
        },
        [10012302] = {
          Content = "好多了，只是还有些头晕……",
          DialogueId = 10012302,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910934C",
          NextDialogue = 10012303,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934C"
        },
        [10012303] = {
          Content = "那就好，不要勉强自己。",
          DialogueId = 10012303,
          Duration = 2,
          GUID = "1910934D",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100123/1910934D"
        },
        [10012401] = {
          ContentJP = "ここには誰かが住んでいた形跡があるね。",
          DialogueId = 10012401,
          ExStoryInfo = "Player",
          GUID = "1910A38A",
          NextDialogue = 10012402,
          SpeakNpcId = 100001,
          Subtitle = "It seems someone used to live here.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A38A"
        },
        [10012402] = {
          ContentJP = "当ててみようか？ベレが住んでいたんでしょ？",
          DialogueId = 10012402,
          ExStoryInfo = "Player",
          GUID = "1910A3B4",
          NextDialogue = 10012403,
          SpeakNpcId = 100001,
          Subtitle = "This was your home, am I right, Berry?",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3B4"
        },
        [10012403] = {
          ContentJP = "……私。",
          DialogueId = 10012403,
          GUID = "1910A3DE",
          NextDialogue = 10012404,
          SpeakNpcId = 100003,
          Subtitle = "...I...",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A3DE"
        },
        [10012404] = {
          ContentJP = "……そうね。だけど私だけじゃなくて、「私たち」の家だった。",
          DialogueId = 10012404,
          GUID = "1910A408",
          NextDialogue = 10012405,
          SpeakNpcId = 100003,
          Subtitle = "...Yes, and no. It was OUR home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A408"
        },
        [10012405] = {
          ContentJP = "{性别:僕たちが？そんな、何も思い出せない……|私たちが？そんな、何も思い出せない……}",
          DialogueId = 10012405,
          ExStoryInfo = "Player",
          GUID = "1910A432",
          NextDialogue = 10012406,
          SpeakNpcId = 100001,
          Subtitle = "Our home? But I don't remember a thing.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A432"
        },
        [10012406] = {
          ContentJP = "……いいの、むしろ思い出さないで欲しい。ここから脱出したら、私たちで新しい家を作ろうね。",
          DialogueId = 10012406,
          GUID = "1910A433",
          SpeakNpcId = 100003,
          Subtitle = "...It's okay. Maybe it's all for the best. After we make it out, we'll build a new home.",
          VoiceName = "voice/$Locale$/story/1001/100124/1910A433"
        },
        [10012501] = {
          ContentJP = "クエスト失敗。もう一度やり直してください。",
          DialogueId = 10012501,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1910B3F2",
          SpeakNpcId = 100001,
          Subtitle = "Quest failed. Try again",
          VoiceName = "voice/$Locale$/story/1001/100125/1910B3F2"
        },
        [10012502] = {
          ContentJP = "クエスト失敗。もう一度やり直してください。",
          DialogueId = 10012502,
          Duration = 10,
          ExStoryInfo = "Player",
          GUID = "1910B3F3",
          SpeakNpcId = 100001,
          Subtitle = "Quest failed. Try again"
        },
        [10012601] = {
          Content = "净界岛上的小村，我和贝蕾妮卡一起长大的地方。",
          DialogueId = 10012601,
          Duration = 2.5,
          GUID = "1910C45A",
          NextDialogue = 10012602,
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C45A"
        },
        [10012602] = {
          Content = "这些叫做秽兽的怪物究竟从何而来，我们也无从得知；",
          DefaultLookAt = "KeepState",
          DialogueId = 10012602,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1910C484",
          LookAt = {
            [1] = "100001:n(100003)"
          },
          NextDialogue = 10012603,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C484"
        },
        [10012603] = {
          Content = "只知道，昔日宁和的村庄，一夜之间变成了这副模样。",
          DialogueId = 10012603,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1910C4AE",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100126/1910C4AE"
        },
        [10012701] = {
          Camera = "524.417969,-273.097656,72.024963,0.000254,10.998483,156.973907,35.0,100000.0,false,Manual,22.0",
          ContentJP = "帰って来たか。{nickname}……私の半身、私の影、私の木霊。",
          DialogueId = 10012701,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "511.515625,-301.914062,72.024963,0.000255,10.998483,151.374451,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D4EC",
          NextDialogue = 10012702,
          RelatedWikiId = {
            [1] = 304001,
            [2] = 204001,
            [3] = 201001,
            [4] = 304002
          },
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "You're back, Phoxhunter... My other half, my reflection, and my echo.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100127/1910D4EC"
        },
        [10012702] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentJP = "お前は私の声を聞いた。己自身の力を取り戻したのだ。「レゾナンス」を。",
          DialogueId = 10012702,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D516",
          NextDialogue = 10012703,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "You heard my voice. You've retrieved the power that belonged to you. The \"Resonance\".",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1001/100127/1910D516"
        },
        [10012703] = {
          Camera = "136.882812,-238.855469,168.495239,0.000319,-18.601807,42.176678,35.0,100000.0,false,Manual,22.0",
          ContentJP = "{性别:その力がなんだっていうんだ？僕は海に落ちて、もう二度と目覚めない。僕の物語はこれで全部おしまいなのに。|その力がなんだっていうの？私は海に落ちて、もう二度と目覚めない。私の物語はこれで全部おしまいなのに。}",
          DefaultLookAt = "KeepState",
          DialogueId = 10012703,
          Duration = 5,
          ExStoryInfo = "Player",
          FinalCamera = "116.4375,-210.523438,168.495239,0.000323,-19.201778,29.174892,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D540",
          LookAt = {
            [1] = "100001:n(100014)"
          },
          NextDialogue = 10012704,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D540"
        },
        [10012704] = {
          Camera = "699.554688,-957.21875,341.90564,0.000407,-14.001368,121.374519,35.0,100000.0,false,Manual,22.0",
          ContentJP = "否、私には見える。お前の未来、我々の未来は……ここで終わりはしない。",
          DialogueId = 10012704,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          FinalCamera = "249.050781,-1061.171875,341.90564,0.00044,-16.201441,91.573235,35.0,100000.0,false,Manual,22.0",
          GUID = "1910D56A",
          NextDialogue = 10012705,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56A"
        },
        [10012705] = {
          ContentJP = "何者かが、お前を苦しみの海からすくいあげ、苦寒の荒野へと導くだろう。その地で、運命がもたらす真の試練の幕が上がるのだ。",
          DialogueId = 10012705,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D56B",
          NextDialogue = 10012706,
          SnapShot = "MEMORY",
