        },
        [10012713] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentJP = "……{nickname}よ。命は果てしなき夜を航行する孤独な船だ。川は涙で溢れ、岸には茨が生い茂る。",
          DialogueId = 10012713,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D597",
          NextDialogue = 10012714,
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "...Phoxhunter. Life is like a lonely cruise through the boundless darkness of the night. The river weeps, overflowing its banks, while the thorny thickets on either side stand as a testament to its sorrow.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D597"
        },
        [10012714] = {
          Camera = "317.9375,-203.148438,165.504761,0.000249,2.998658,152.974579,35.0,100000.0,false,Manual,22.0",
          ContentJP = "私はこれからも見守っていく……彼岸より来たる人が、どこへ向かって漕いでいくのか。",
          DialogueId = 10012714,
          Duration = 5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910D598",
          SnapShot = "MEMORY",
          SpeakNpcId = 100012,
          Subtitle = "I'll keep watching over you, The One Across the Shore... to see where you're going.",
          VoiceName = "voice/$Locale$/story/1002/100127/1910D598"
        },
        [10012801] = {
          ContentJP = "コキュートスに来るのは初めてだが、当地のもてなしはかなり独特なのだな。",
          DialogueId = 10012801,
          Duration = 8.1,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E52A",
          RelatedWikiId = {
            [1] = 408002
          },
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "This is my first time in Cocytus Province. Is this how the people here show their hospitality?",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E52A"
        },
        [10012802] = {
          ContentJP = "ああ、悪気はないんだ。ただ……少し取引をしたいだけだ。",
          DialogueId = 10012802,
          Duration = 6.1,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E57E",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "I don't want to bother you, I just want to... strike a small \"bargain\".",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E57E"
        },
        [10012803] = {
          ContentJP = "聞けば断れないぐらいの報酬は用意するつもりだ。非常にシンプルな頼みごとなのだが……引き受けてはくれないかね。",
          DialogueId = 10012803,
          Duration = 6.5,
          ExStoryInfo = "EXPlayer",
          GUID = "1910E5A8",
          SnapShot = "MYSTERIOUS",
          SpeakNpcId = 100012,
          Subtitle = "I'll pay you whatever you want, and all you have to do, well, it will be a piece of cake.",
          VoiceName = "voice/$Locale$/story/1002/100128/1910E5A8"
        },
        [10017801] = {
          Content = "......",
          DialogueId = 10017801,
          Duration = 1,
          GUID = "1914197A",
          RelatedWikiId = {
            [1] = 408001,
            [2] = 201001,
            [3] = 303001,
            [4] = 401001,
            [5] = 403001
          },
          VoiceName = "voice/$Locale$/story/1002/100178/1914197A"
        },
        [10017901] = {
          ContentJP = "飛行船は山頂にあるはず。少し休んだら、また登ろうか。",
          DialogueId = 10017901,
          DisableMouth = 1,
          Duration = 5,
          GUID = "191429E2",
          SpeakNpcId = 100003,
          Subtitle = "The ship is at the mountaintop. After a short break, we'll push on.",
          VoiceName = "voice/$Locale$/story/1001/100179/191429E2"
        },
        [10017902] = {
          ContentJP = "……こんなに早く、この島を出ることになるなんて。",
          DialogueId = 10017902,
          DisableMouth = 1,
          Duration = 3.5,
          ExStoryInfo = "Player",
          GUID = "19142A0C",
          SpeakNpcId = 100001,
          Subtitle = "...Can't believe we'll be saying goodbye to Purgatorio Island soon.",
          VoiceName = "voice/$Locale$/story/1001/100179/19142A0C"
        },
        [10017903] = {
          ContentJP = "……チッ、少しぐらい、休ませてよ。",
          DialogueId = 10017903,
          DisableMouth = 1,
          Duration = 5.5,
          GUID = "19142A0D",
          SpeakNpcId = 100003,
          Subtitle = "...You creatures just can't give us a break, can you?",
          VoiceName = "voice/$Locale$/story/1001/100179/19142A0D"
        },
        [10018001] = {
          Content = "走。",
          DialogueId = 10018001,
          Duration = 2,
          GUID = "19143A4A",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100180/19143A4A"
        },
        [10018101] = {
          DialogueId = 10018101,
          Duration = 1,
          GUID = "19144AB2",
          SpeakNpcId = 100003,
          VoiceName = "voice/$Locale$/story/1001/100181/19144AB2"
        },
        [10018201] = {
          Content = "那天，在毁灭之前，我睁开双眼。瞳孔所见之景，是“无限”。",
          DialogueId = 10018201,
          DialoguePanelType = "None",
          Duration = 13,
          ExStoryInfo = "Player",
          GUID = "19145B1A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100182/19145B1A"
        },
        [10018202] = {
          Content = "第一次，我感受到了，我是如此真实地活着。",
          DialogueId = 10018202,
          DialoguePanelType = "None",
          Duration = 7,
          ExStoryInfo = "Player",
          GUID = "19145B44",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1001/100182/19145B44"
        },
        [10018301] = {
          Content = "下坠。我本应朝着漆黑的深渊下坠。",
          DialogueId = 10018301,
          Duration = 2.5,
          GUID = "19146B82",
          NextDialogue = 10018302,
          VoiceName = "voice/$Locale$/story/1001/100183/19146B82"
        },
        [10018302] = {
          Content = "但，我却感觉自己在晨雾的怀抱里飘浮。",
          DialogueId = 10018302,
          Duration = 2.5,
          GUID = "19146BAC",
          NextDialogue = 10018303,
          VoiceName = "voice/$Locale$/story/1001/100183/19146BAC"
        },
        [10018303] = {
          Content = "周身被冰冷的触感包围，但意外的是，那种冰冷并不令人恐惧。",
          DialogueId = 10018303,
          Duration = 4,
          GUID = "19146BD6",
          NextDialogue = 10018304,
          VoiceName = "voice/$Locale$/story/1001/100183/19146BD6"
        },
        [10018304] = {
          Content = "而是一种，奇特的触感……亲切，甚至令人怀念。",
          DialogueId = 10018304,
          Duration = 3,
          GUID = "19146C00",
          VoiceName = "voice/$Locale$/story/1001/100183/19146C00"
        },
        [10018401] = {
          ContentJP = "答えてくれたのは、無限に流れる白い砂と……そして……",
          DialogueId = 10018401,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "19147BEA",
          NextDialogue = 10018402,
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "But up until now, there has been no answer. Only endless flowing quicksand covering my vision, and...",
          VoiceName = "voice/$Locale$/story/1001/100184/19147BEA"
        },
        [10018402] = {
          ContentJP = "{性别:彼女|彼}。",
          DialogueId = 10018402,
          Duration = 1.5,
          ExStoryInfo = "Player",
          GUID = "19147C14",
          SnapShot = "HEART",
          SpeakNpcId = 100001,
          Subtitle = "Phoxhunter.",
          VoiceName = "voice/$Locale$/story/1001/100184/19147C14"
        },
        [10018501] = {
          Content = "占位文本",
          DialogueId = 10018501,
          GUID = "19148C52",
          VoiceName = "voice/$Locale$/story/1001/100185/19148C52"
        },
        [10018601] = {
          ContentJP = "だめ……",
          DialogueId = 10018601,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "19149CBA",
          SpeakNpcId = 100001,
          Subtitle = "No...",
          VoiceName = "voice/$Locale$/story/1001/100186/19149CBA"
        },
        [10018602] = {
