        },
        [10019001] = {
          ContentJP = "村には誰もいないみたい。多分、みんなもう……",
          DialogueId = 10019001,
          Duration = 1.8,
          GUID = "1914DE5A",
          NextDialogue = 10019002,
          SpeakNpcId = 100003,
          Subtitle = "The village is in dead silence. I'm afraid they've probably...",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DE5A"
        },
        [10019002] = {
          ContentJP = "……！！",
          DialogueId = 10019002,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "1914DE84",
          NextDialogue = 10019003,
          SpeakNpcId = 100001,
          Subtitle = "...!!",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DE84"
        },
        [10019003] = {
          ContentJP = "……そんな顔しないで。みんなは船で逃げ出したんでしょうね、って意味。",
          DialogueId = 10019003,
          Duration = 2.5,
          GUID = "1914DEAE",
          NextDialogue = 10019004,
          SpeakNpcId = 100003,
          Subtitle = "...I mean, they've probably scarpered off by boat.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEAE"
        },
        [10019004] = {
          ContentJP = "ここは危険だから、急いで家に戻って武器を回収しないとね。そしたら桟橋まで行ってみよう。",
          DialogueId = 10019004,
          Duration = 2.5,
          GUID = "1914DEAF",
          NextDialogue = 10019005,
          SpeakNpcId = 100003,
          Subtitle = "We should hurry home and get the weapons, and then get to the wharf. It's still dangerous here.",
          VoiceName = "voice/$Locale$/story/1001/100190/1914DEAF"
        },
        [10019005] = {
          ContentJP = "（{性别:今の僕たちは武器を持っていないし……<Default note=\"text:エジュウ\">穢獣</>に見つからないようにしないと|今の私たちは武器を持っていないし……<Default note=\"text:エジュウ\">穢獣</>に見つからないようにしないと}）",
