        },
        [10030421] = {
          ContentJP = "お見舞い品が所狭しと積まれている。ここ数日、見舞いの者が大勢来ていたようだ。\n名も知らぬ花や冷めてしまっても香ばしい肉スープ、傷だらけだが精巧なオルゴール、小鳥の絵が描かれた綿菓子の缶……\n中には、名の記されていない少し歪んだリボンが結ばれた質素な贈り物が混ざっていた。開けてみると、帝国で最高級の鎮痛剤が一本入っている。気持ちはありがたいが、気絶状態の者に鎮痛剤を贈るのは、どう考えても意味がない。",
          DialogueId = 10030421,
          GUID = "191C2FF2",
          VoiceName = "voice/$Locale$/story/1003/100304/191C2FF2"
        },
        [10030422] = {
          Camera = "80.631256,-105.42334,178.525864,0.000194,-7.403289,115.154785,35.000011,142.834564,false,Manual,22.0",
          ContentJP = "他の質問は、アスフォデロスにいる友人たちに聞きなさい。この数日間、あなたのことを随分心配していたわ。",
          DialogueId = 10030422,
          GUID = "191C2FC8",
          NextDialogue = 10030420,
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1003/100304/191C2FC8"
        },
