        },
        [10031211] = {
          ContentJP = "（ベレ、こうゆうふわふわなのが好きだったっけ……）",
          DetectiveQuestionId = 1003,
          DialogueId = 10031211,
          DisableMouth = 1,
          GUID = "191CB18E",
          NextDialogue = 10031212,
          SnapShot = "HEART",
