          Duration = 17,
          GUID = "191D4536",
          SpeakNpcId = 100329,
          VoiceName = "voice/$Locale$/story/1003/100321/191D4536"
        },
        [10032112] = {
          ContentJP = "あれ、釘は？よりによって舞台の補強中に見当たらなくなるなんて……",
          DialogueId = 10032112,
          Duration = 9,
          GUID = "191D450D",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450D"
        },
        [10032113] = {
          ContentJP = "ダニスは？本番まであと数日しかないのに、まだメイクも衣装写真も済んでないの、あいつだけだよ。",
          DialogueId = 10032113,
          Duration = 10,
          GUID = "191D450E",
          VoiceName = "voice/$Locale$/story/1003/100321/191D450E"
        },
        [10032114] = {
          ContentJP = "「燭を掲げて舞い、声の限りに歌え――この雪の夜に」",
          DialogueId = 10032114,
          Duration = 6,
          GUID = "191D450F",
          SpeakNpcId = 100370,
          VoiceName = "voice/$Locale$/story/1003/100321/191D450F"
        },
        [10032115] = {
          ContentJP = "……第三幕の照明、修正だ。俺たちが再現したいのは、一本ずつ蝋燭に火が灯っていくあの感じだ。わかるか？逐・一・点・灯・だ！",
          DialogueId = 10032115,
          Duration = 15,
          GUID = "191D4510",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4510"
        },
        [10032116] = {
          ContentJP = "……また走った。それで数日後の本番に出るつもり？やり直し。",
          DialogueId = 10032116,
          Duration = 9,
          GUID = "191D4511",
          VoiceName = "voice/$Locale$/story/1003/100321/191D4511"
        },
        [10032117] = {
