        [10032901] = {
          ContentJP = "こちらです。",
          DialogueId = 10032901,
          GUID = "191DC6D2",
          NextDialogue = 10032902,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC6D2"
        },
        [10032902] = {
          ContentJP = "リズム長官、ここの地形にやけに詳しいね？",
          DialogueId = 10032902,
          GUID = "191DC6FC",
          NextDialogue = 10032903,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC6FC"
        },
        [10032903] = {
          ContentJP = "ここ数年、帝国は各都市の地下施設の建設に力を入れており、警備部隊もその維持に貢献していたので。",
          DialogueId = 10032903,
          GUID = "191DC726",
          NextDialogue = 10032904,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC726"
        },
        [10032904] = {
          ContentJP = "警備部隊に入隊したばかりの頃は、毎日ここの掃除をさせられてました。",
          DialogueId = 10032904,
          GUID = "191DC750",
          NextDialogue = 10032905,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC750"
        },
        [10032905] = {
          ContentJP = "毎日下水道の掃除を……カロン族って軍に入っても、やっぱりいじめられるの？",
          DialogueId = 10032905,
          GUID = "191DC77A",
          NextDialogue = 10032906,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC77A"
        },
        [10032906] = {
          ContentJP = "偏見は根深いものです。しかし、帝国軍においては功績を上げることで尊敬を勝ち取ることができます。",
          DialogueId = 10032906,
          GUID = "191DC7A4",
          NextDialogue = 10032907,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7A4"
        },
        [10032907] = {
          ContentJP = "これは「悪魔の子」としての罪を償う方法のひとつでもあるんです。",
          DialogueId = 10032907,
          GUID = "191DC7CE",
          NextDialogue = 10032908,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7CE"
        },
        [10032908] = {
          ContentJP = "おい、ちょっと待て……なんか音が聞こえないか？",
          DialogueId = 10032908,
          GUID = "191DC7F8",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC7F8"
        },
        [10032909] = {
          ContentJP = "た、助けてくれ……死にたく、ない……！",
          DialogueId = 10032909,
          GUID = "191DC822",
          NextDialogue = 10032910,
          SpeakNpcId = 100321,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC822"
        },
        [10032910] = {
          ContentJP = "……誰かが助けを求めてる！今行くわ！",
          DialogueId = 10032910,
          GUID = "191DC84C",
          NextDialogue = 10032911,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100329/191DC84C"
        },
        [10032911] = {
