        [10033101] = {
          ContentJP = "扉の制御装置が使えない……",
          DialogueId = 10033101,
          GUID = "191DE7A2",
          NextDialogue = 10033102,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE7A2"
        },
        [10033102] = {
          ContentJP = "恐らく周辺の排水管が詰まっているせいで制御装置がロックされてしまったのでしょう。緊急排水バルブを開けて、詰まりを解消できないか試してみましょう。",
          DialogueId = 10033102,
          GUID = "191DE7CC",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE7CC"
        },
        [10033103] = {
          ContentJP = "<W>警告：排水プロセスに異常発生！排水口が限界まで稼働中。速やかに排水管を通水せよ。</>",
          DialogueId = 10033103,
          GUID = "191DE7F6",
          SnapShot = "BROADCAST",
          VoiceName = "voice/$Locale$/story/1003/100331/191DE7F6"
        },
        [10033104] = {
          ContentJP = "ひぃいいい！ち、近づいてきたぞ！うっ……あ、足が動かな……",
          DialogueId = 10033104,
          GUID = "191DE820",
          NextDialogue = 10033105,
          SpeakNpcId = 100321,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE820"
        },
        [10033105] = {
          ContentJP = "チッ、こんな細いパイプにどんだけ物が詰め込まれてんだか……",
          DialogueId = 10033105,
          GUID = "191DE84A",
          NextDialogue = 10033106,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE84A"
        },
        [10033106] = {
          ContentJP = "<Default note=\"text:エジュウ\">穢獣</>を全て排除しないと。",
          DialogueId = 10033106,
          GUID = "191DE874",
          NextDialogue = 10038102,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE874"
        },
        [10033107] = {
          ContentJP = "防衛システムが終了しました。これで制御装置も使えそうですね。",
          DialogueId = 10033107,
          GUID = "191DE89E",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE89E"
        },
        [10033108] = {
          ContentJP = "それ、大丈夫？",
          DialogueId = 10033108,
          GUID = "191DE8C8",
          NextDialogue = 10033109,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE8C8"
        },
        [10033109] = {
          ContentJP = "ほんのかすり傷です。気にしないでください。そんなことより、もう一人の遭難者を探しましょう。",
          DialogueId = 10033109,
          GUID = "191DE8F2",
          NextDialogue = 10033110,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE8F2"
        },
        [10033110] = {
          ContentJP = "あの化け物が姿を消したのもちょうどこの辺りだった。俺の仲間はこの前にいるはずだ……",
          DialogueId = 10033110,
          GUID = "191DE91C",
          SpeakNpcId = 100321,
          VoiceName = "voice/$Locale$/story/1003/100331/191DE91C"
