        },
        [10034002] = {
          ContentJP = "鍵に書かれていた場所によりゃ、おそらく公道の中継ステーション付近ってとこかな。",
          DialogueId = 10034002,
          GUID = "191E7B74",
          NextDialogue = 10034003,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B74"
        },
        [10034003] = {
          ContentJP = "こんな場所に秘密基地を……",
          DialogueId = 10034003,
          GUID = "191E7B9E",
          NextDialogue = 10034004,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7B9E"
        },
        [10034004] = {
          ContentJP = "まあ、一般人には理解できねぇような場所に自分だけの隠れ家を作りたがるのも、人の性だからな……",
          DialogueId = 10034004,
          GUID = "191E7BC8",
          NextDialogue = 10034005,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BC8"
        },
        [10034005] = {
          ContentJP = "車や配管の中を好む輩が多いのもそれだ。ここを選んだのも納得はできるな。",
          DialogueId = 10034005,
          GUID = "191E7BF2",
          NextDialogue = 10034006,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7BF2"
        },
        [10034006] = {
          ContentJP = "ええと……納得できる、よな？あれ、ガキの頃にあちこち潜り込んだこととかなかったのか、お前ら？",
          DialogueId = 10034006,
          GUID = "191E7C1C",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100340/191E7C1C"
        },
        [10034007] = {
          ContentJP = "地図によればここだけど……？",
