        [10034601] = {
          ContentJP = "ふふ……",
          DialogueId = 10034601,
          GUID = "191EDDBA",
          NextDialogue = 10034602,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDBA"
        },
        [10034602] = {
          ContentJP = "何笑ってんだ？",
          DialogueId = 10034602,
          GUID = "191EDDE4",
          NextDialogue = 10034603,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDDE4"
        },
        [10034603] = {
          ContentJP = "三年前、こうして湖で釣りをした時のことを思い出しました。あの時はブルースと一緒で……",
          DialogueId = 10034603,
          GUID = "191EDE0E",
          NextDialogue = 10034604,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE0E"
        },
        [10034604] = {
          ContentJP = "あの子は賢いけど、とにかく落ち着きがなくて。一日中いてもバケツは空っぽでした。",
          DialogueId = 10034604,
          GUID = "191EDE38",
          NextDialogue = 10034605,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE38"
        },
        [10034605] = {
          ContentJP = "……内城区でどんな暮らしをしているんだろう。釣りのコツくらいは覚えたかもしれませんね……",
          DialogueId = 10034605,
          GUID = "191EDE62",
          NextDialogue = 10034606,
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE62"
        },
        [10034606] = {
          ContentJP = "ふふん、ほんと凡人はすぐくだらない感情に振り回されるよねぇ。この魔王様を見習いなさい。",
          DialogueId = 10034606,
          GUID = "191EDE8C",
          NextDialogue = 10034607,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDE8C"
        },
        [10034607] = {
          ContentJP = "俺たちもお前の家族のようなもんだ、チビ助。お前さえ望めば、喜んでおばあちゃんって呼んでやろう。",
          DialogueId = 10034607,
          GUID = "191EDEB6",
          NextDialogue = 10034608,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEB6"
        },
        [10034608] = {
          ContentJP = "な、なによ急に、柄にもないことを……",
          DialogueId = 10034608,
          GUID = "191EDEE0",
          NextDialogue = 10034609,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDEE0"
        },
        [10034609] = {
          ContentJP = "あーおばあちゃん、お腹すいたー小遣いくれ。",
          DialogueId = 10034609,
          GUID = "191EDF0A",
          NextDialogue = 10034610,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF0A"
        },
        [10034610] = {
          ContentJP = "へ……ムキ―！",
          DialogueId = 10034610,
          GUID = "191EDF34",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF34"
        },
        [10034611] = {
          ContentJP = "これで揃いましたね。では霧の街に届けましょう。",
          DialogueId = 10034611,
          GUID = "191EDF5E",
          SpeakNpcId = 100304,
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF5E"
        },
        [10034612] = {
          ContentJP = "夜間外出禁止令が出てる間は、通行禁止だ。ご協力を！",
          DialogueId = 10034612,
          GUID = "191EDF60",
          VoiceName = "voice/$Locale$/story/1003/100346/191EDF60"
        },
        [10034613] = {
          Content = "（<H>地面都被士兵封锁了</>……或许可以试试别的路——比如<H>楼顶</>？）",
