        [10034814] = {
          ContentJP = "劇場の幕とよく似た材質の布。古びているが、とても清潔に保たれている。誰かが丁寧に手入れをしたのだろう。\n注意深く観察し、触れてみると、襲撃現場で見つかった幕と同じ布であることが分かる。",
          DialogueId = 10034814,
          GUID = "191F00AC",
          VoiceName = "voice/$Locale$/story/1003/100348/191F00AC"
        },
        [10034815] = {
          ContentJP = "古びたマネキン。その着こなしやポーズには明らかに細やかな意図が込められており、まるで舞台上で情熱的に演じる優雅な俳優のように見える。",
          DialogueId = 10034815,
          GUID = "191F00D6",
          VoiceName = "voice/$Locale$/story/1003/100348/191F00D6"
        },
        [10034816] = {
          ContentJP = "周囲には巨大な爪痕がびっしりと刻まれており、その密度と乱れ具合から、極限の苦痛と狂気の中で刻まれたものだとわかる。",
          DialogueId = 10034816,
          GUID = "191F0100",
          VoiceName = "voice/$Locale$/story/1003/100348/191F0100"
        },
