        },
        [10035313] = {
          ContentJP = "これはブルースに教わった歌で、『儚き子へのレクイエム』って言うの。確か、オペラ『雪国の幼子』のアリアだったかな。でも、今のは少しアレンジしたもので、本当の歌詞はもっと悲しいものよ。",
          DialogueId = 10035313,
          FacialId = {
            [1] = "100304:None"
          },
          GUID = "191F528A",
          NextDialogue = 10035314,
          SpeakNpcId = 100304,
