          Scripts = [[

PARA{
PlayAnimation{_delay{0},ActorId{100327},AnimationId{"Tuosi02_Story_Find02_Start"},Duration{5}}
}]]
        },
        [10035501] = {
          ContentJP = "「桂冠カロン族」――かつて私はそれを、最も輝くダイヤモンドのように思っていた。\nそれは夢の果てで煌めき、まるでアイスレイクシティの頂にある、不滅の明かりのようだった。",
          DialogueId = 10035501,
          Duration = 4,
          GUID = "191F7162",
          NextDialogue = 10035502,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7162"
        },
        [10035502] = {
          ContentJP = "だが後になって知ったんだ。それは堅固なダイヤモンドなんかじゃなかった。\nそれはただのガラス――幻想の光を反射し、美しく、眩しいだけのもの。\nそして、卵石一つ、泥の塊一つで、簡単に砕け散る脆いものだった。",
          DialogueId = 10035502,
          Duration = 4,
          GUID = "191F718C",
          NextDialogue = 10035503,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F718C"
        },
        [10035503] = {
          ContentJP = "第六軍団の試験を通過したカロン族は、結局のところ、好き放題に扱われる囚われの獣と何ら変わりはしない。\nむしろ、無知で鈍感な獣でいられた方がよかったかもしれない。\nそうすれば、壊れた夢に苦しむことも、果たせない約束に涙することもなかっただろうに……",
          DialogueId = 10035503,
          Duration = 4,
          GUID = "191F71B6",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71B6"
        },
        [10035504] = {
          ContentJP = "（ここは？たしか第六軍団のに入って、錬金院に派遣されて、それから……）",
          DialogueId = 10035504,
          GUID = "191F71E0",
          RelatedWikiId = {
            [1] = 407003,
            [2] = 201024
          },
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F71E0"
        },
        [10035505] = {
          ContentJP = "先生、被検体が意識を取り戻しました。\nすごく苦しそう……すぐに追加の麻酔を――",
          DialogueId = 10035505,
          GUID = "191F720A",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F720A"
        },
        [10035506] = {
          ContentJP = "構わん。どちらにしろ同じことだ。準備を進めろ、2分後にそれの耐性データを採取する。",
          DialogueId = 10035506,
          GUID = "191F7234",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7234"
        },
        [10035507] = {
          DialogueId = 10035507,
          GUID = "191F725E",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F725E"
        },
        [10035508] = {
          ContentJP = "先生、データが出ました。彼は今回の被検体の中でも耐性が非常に優れています。\n電流を流しても移植された第二の心臓を破壊することはできませんでした。\nただし、炎による損傷で人工皮膚が焼け、体温が通常値を大幅に上回っています。",
          DialogueId = 10035508,
          GUID = "191F7288",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7288"
        },
        [10035509] = {
          ContentJP = "記録は以上です。体力もそろそろ限界でしょうし、少し休ませてはどうでしょう。",
          DialogueId = 10035509,
          GUID = "191F72B2",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F72B2"
        },
        [10035510] = {
          ContentJP = "こんな悪魔どもに情けは不要だ。\n鎮静剤を打って手足を固定しろ。このまま強化実験に移る。",
          DialogueId = 10035510,
          GUID = "191F72DC",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F72DC"
        },
        [10035511] = {
          ContentJP = "（痛い……痛い……僕に何をした……体中が悲鳴をあげてる……聞こえないのか……！）",
          DialogueId = 10035511,
          GUID = "191F7306",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7306"
        },
        [10035512] = {
          ContentJP = "ほぅ、実に表情が豊かだ。何か言いたいのか？もとより、そんな機会は与えんがな。",
          DialogueId = 10035512,
          GUID = "191F7330",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7330"
        },
        [10035513] = {
          ContentJP = "鎮静剤、注射しました。先生、その、やっぱり――",
          DialogueId = 10035513,
          GUID = "191F735A",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F735A"
        },
        [10035514] = {
          ContentJP = "言う通りにやれ。まずは最も敏感な角の先端からサンプルを採取しろ。そうすれば、より正確なデータが得られるだろう。",
          DialogueId = 10035514,
          GUID = "191F7384",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7384"
        },
        [10035515] = {
          ContentJP = "……わかりました……",
          DialogueId = 10035515,
          GUID = "191F73AE",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73AE"
        },
        [10035516] = {
          ContentJP = "（痛い……痛いよ……これが「悪魔の子」として受けるべき罰なのか……）",
          DialogueId = 10035516,
          GUID = "191F73D8",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F73D8"
        },
        [10035517] = {
          ContentJP = "（でも、どんな罪があろうと、こんな痛み……いい加減償いきれたはずだ……！）",
          DialogueId = 10035517,
          GUID = "191F7402",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7402"
        },
        [10035518] = {
          ContentJP = "こんな日々がどれだけ続いたのか、もうわからない。\nただ一つわかるのは、自分の身体が少しずつ恐ろしい怪物へと変わり果てていくことだけだ。\n心は次第に冷えきり、涙の湖に吹く冷たい風の中で粉々に砕け散っていく。",
          DialogueId = 10035518,
          GUID = "191F742C",
          NextDialogue = 10035519,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F742C"
        },
        [10035519] = {
          ContentJP = "「人」だった頃の記憶はどんどん薄れていき、ついには名前すら忘れていった。",
          DialogueId = 10035519,
          GUID = "191F7456",
          NextDialogue = 10035520,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7456"
        },
        [10035520] = {
          ContentJP = "「ブルース・フィッシャー」は死んだ。代わりに<W>No.47</>――という新しい「名」が与えられた。",
          DialogueId = 10035520,
          GUID = "191F7480",
          NextDialogue = 10035521,
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          VoiceName = "voice/$Locale$/story/1003/100355/191F7480"
        },
        [10035521] = {
          ContentJP = "それでもなお、この肉体はみじめにもがき続けていた。",
          DialogueId = 10035521,
          GUID = "191F74AA",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName02",
          VoiceName = "voice/$Locale$/story/1003/100355/191F74AA"
        },
        [10035522] = {
          Camera = "-4.90918,-156.237305,105.101868,-0.000091,10.758511,116.110672,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "先生、拒絶反応が収まり、各数値も安定しました。ただ、β型抑制剤を使いすぎたようで、精神状態が不安定です。",
          DialogueId = 10035522,
          FinalCamera = "-9.579102,-158.523438,105.101868,-0.000092,10.758511,114.710289,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "191F74D4",
          NextDialogue = 10035523,
          Scripts = "SEQ{CameraMoveTo{_delay{3},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000069,7.559721,84.699837,35.0,100000.0,false,DoNotOverride,2.8\"},duration{0}},CameraMoveTo{_delay{0},TargetPosition{\"-53.197266,-469.569336,49.268738,0.000061,11.159675,84.499451,35.0,100000.0,false,DoNotOverride,2.8\"},duration{5}}}",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          TalkActionId = {
            [1] = "100337:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74D4"
        },
        [10035523] = {
          Camera = "-179.390625,29.248047,164.763611,0.000084,-5.841492,-25.696522,35.0,251.812622,false,Manual,2.797869",
          ContentJP = "精神など生命活動の副産物にすぎん。返事さえできれば十分だ。実験場に連れていけ。",
          DialogueId = 10035523,
          FinalCamera = "-182.842773,22.280273,164.763611,0.000086,-5.841492,-21.695681,35.0,251.812622,false,Manual,2.797869",
          GUID = "191F74FE",
          NextDialogue = 10035524,
          SpeakNpcId = 100337,
          SpeakNpcName = "Cp2CharacterName04",
          TalkActionId = {
            [1] = "100337:Explain01_End",
            [2] = "100336:Confident_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F74FE"
        },
        [10035524] = {
          Camera = "20.333008,-203.238281,111.764038,0.00009,4.758661,116.695335,35.0,251.812622,false,Manual,2.797869",
          ContentJP = "はい、先生。",
          DialogueId = 10035524,
          FinalCamera = "20.333008,-203.238281,111.764038,0.000089,7.758616,116.69487,35.0,251.812622,false,Manual,2.797869",
          GUID = "191F7528",
          SpeakNpcId = 100336,
          SpeakNpcName = "Cp2CharacterName05",
          TalkActionId = {
            [1] = "100337:Agree",
            [2] = "100336:Confident_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1003/100355/191F7528"
        },
        [10035601] = {
          ContentJP = "抑制剤が効いてる限り、<H>命令に背くことすらできない</>。まるで家畜だな。",
          DialogueId = 10035601,
          GUID = "191F81CA",
          NextDialogue = 10035602,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F81CA"
        },
        [10035602] = {
          ContentJP = "なんて凶暴で野蛮な姿――理性も美しさもまるでない。これがカロン族の本来の姿なのね。",
          DialogueId = 10035602,
          GUID = "191F81F4",
          NextDialogue = 10035603,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F81F4"
        },
        [10035603] = {
          ContentJP = "おいおい、あまり近づくな。変な病気でもうつされたらどうするんだ。",
          DialogueId = 10035603,
          GUID = "191F821E",
          NextDialogue = 10035604,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F821E"
        },
        [10035604] = {
          ContentJP = "ちゃんと戦闘データを記録するのよ。基準を満たさない、もしくは怪しい動きがあれば即刻処分しなさい。",
          DialogueId = 10035604,
          GUID = "191F8248",
          NextDialogue = 10035605,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8248"
        },
        [10035605] = {
          ContentJP = "でも、こんなの……いくらなんでも残酷すぎるんじゃ……",
          DialogueId = 10035605,
          GUID = "191F8272",
          NextDialogue = 10035606,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8272"
        },
        [10035606] = {
          ContentJP = "残酷？陛下の慈悲深いお心と錬金術の偉大なる力があってこそ、こんなクズにも錬金院に貢献する権利が与えられたのよ。感謝してほしいくらいだわ。",
          DialogueId = 10035606,
          GUID = "191F829C",
          NextDialogue = 10035607,
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F829C"
        },
        [10035607] = {
          ContentJP = "逃げようなど考えないことだ。電気ネットと機関銃は俺らみたいに手加減なんてしないぜ。自殺も諦めることだ。その無意味な命を延ばす薬は山ほどあるからな。",
          DialogueId = 10035607,
          GUID = "191F82C6",
          SpeakNpcName = "Cp2CharacterName32",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C6"
        },
        [10035608] = {
          ContentJP = "テストを開始する。被検体を入れろ。",
          DialogueId = 10035608,
          GUID = "191F82F0",
          NextDialogue = 10035609,
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82F0"
        },
        [10035609] = {
          ContentJP = "No.47、全ての敵を排除しろ。",
          DialogueId = 10035609,
          GUID = "191F831A",
          NextDialogue = 10035610,
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100356/191F831A"
        },
        [10035610] = {
          ContentJP = "はい。",
          DialogueId = 10035610,
          GUID = "191F8344",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName02",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8344"
        },
        [10035611] = {
          ContentJP = "あっちにも敵がいるよ。ほら、止まってる場合じゃないよー！",
          DialogueId = 10035611,
          GUID = "191F836E",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100356/191F836E"
        },
        [10035612] = {
          ContentJP = "数値が思ったより低いな。そっちの敵も始末しろ、もたもたするな。",
          DialogueId = 10035612,
          GUID = "191F8398",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8398"
        },
        [10035613] = {
          ContentJP = "がんばれ！がんばれ！",
          DialogueId = 10035613,
          GUID = "191F83C2",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83C2"
        },
        [10035614] = {
          ContentJP = "もう怪我を？まったく脆いな。",
          DialogueId = 10035614,
          GUID = "191F83EC",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F83EC"
        },
        [10035615] = {
          ContentJP = "あっちだよあっち！",
          DialogueId = 10035615,
          GUID = "191F8416",
          SpeakNpcName = "Cp2CharacterName05",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8416"
        },
        [10035616] = {
          ContentJP = "そっちの、まだ息があるではないか。そんな雑魚も仕留められんのか？",
          DialogueId = 10035616,
          GUID = "191F8440",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F8440"
        },
        [10035617] = {
          ContentJP = "テストは以上だ。収容所に戻せ。次の被検体に移るぞ。",
          DialogueId = 10035617,
          GUID = "191F846A",
          SpeakNpcName = "Cp2CharacterName04",
          VoiceName = "voice/$Locale$/story/1003/100356/191F846A"
        },
        [10035618] = {
          ContentJP = "データ、まだか？待ちきれないよ。",
          DialogueId = 10035618,
          GUID = "191F82C7",
          SpeakNpcName = "Cp2CharacterName22",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C7"
        },
        [10035619] = {
          ContentJP = "今度こそ成功してくれよな……",
          DialogueId = 10035619,
          GUID = "191F82C8",
          SpeakNpcName = "Cp2CharacterName22",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C8"
        },
        [10035620] = {
          ContentJP = "三日後に第五回目の強化を始める。",
          DialogueId = 10035620,
          GUID = "191F82C9",
          SpeakNpcName = "Cp2CharacterName22",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82C9"
        },
        [10035621] = {
          ContentJP = "惜しいな……廃棄率がちょっと高すぎる。",
          DialogueId = 10035621,
          GUID = "191F82CA",
          SpeakNpcName = "Cp2CharacterName22",
          VoiceName = "voice/$Locale$/story/1003/100356/191F82CA"
        },
        [10035701] = {
          Camera = "220.367188,-259.076172,237.702698,0.000082,-11.603056,-49.20525,20.000011,335.406189,false,Manual,1.2",
          ContentJP = "おい、聞こえるか？",
          DialogueId = 10035701,
          FinalCamera = "215.316406,-263.4375,237.702698,0.000082,-11.603056,-49.20525,20.000011,335.406189,false,Manual,1.2",
