        [10036214] = {
          Camera = "86.808594,-88.199707,320.100586,0.000018,-29.605869,33.985477,25.0,100000.0,false,Manual,22.0",
          ContentJP = "僕は……",
          DialogueId = 10036214,
          FinalCamera = "4.820312,-143.472656,376.284668,0.000023,-32.005917,34.185921,25.0,100000.0,false,Manual,22.0",
