          ContentJP = "兵士の手首に細い傷跡がある。よく見ると、それは剣によってつけられたものだとわかる。だが、<H>この舞台に残されるべきは、本来「化け物」と軍団の戦闘の痕跡のみのはず……</>",
          DialogueId = 10036604,
          GUID = "1920226A",
          NextOptions = {
            [1] = 10036605
          },
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036605] = {
          ContentJP = "剣の傷跡を消す",
          DialogueId = 10036605,
          GUID = "1920226B",
          NextDialogue = 10036606
        },
        [10036606] = {
          ContentJP = "その傷は細く、跡形なく壊すのは容易だった。朱に染まった露が滴り落ちる――<H>まるで、剣を振るった月狩り人など初めから存在しなかったかのように。</>",
          DialogueId = 10036606,
          GUID = "1920226C",
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036607] = {
          ContentJP = "兵士の身体には広範囲にわたる火傷があり、よく見ると電撃によるものだとわかる。だが、<H>この舞台に残されるべきは、本来「化け物」と軍団の戦闘の痕跡のみのはず……</>",
          DialogueId = 10036607,
          GUID = "1920226D",
          NextOptions = {
            [1] = 10036608
          },
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036608] = {
          ContentJP = "ケーブルを引きちぎる",
          DialogueId = 10036608,
          GUID = "1920226E",
          NextDialogue = 10036609
        },
        [10036609] = {
          ContentJP = "フロアランプが砕け、垂れ下がったケーブルは真っ二つに引き裂かれた。火花がパチパチと軽やかに踊り、<H>まるで電流を操る軍官などここにいなかったかのようだ。</>……ああ、あのフロアランプ、いいデザインだったのにな。",
          DialogueId = 10036609,
          GUID = "1920226F",
          NextDialogue = 10036610,
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036610] = {
          ContentJP = "こうして、舞台は整った。第十三軍団はガレア劇場まで追撃し、<H>先頭部隊は市民の避難に成功するも、「化け物」の手により全滅。</>その後到着した本隊が「化け物」を討ち取り、カロン狩り事件は終幕を迎えた――それこそが、カロン狩りにふさわしい終わり方なのだ。",
          DialogueId = 10036610,
          GUID = "19202270",
          SpeakNpcName = "UI_Npc_Name_Pangbai"
        },
        [10036701] = {
          ContentJP = "フォーセイクン同盟のやつ、もう行ったぞ！……ブルース、大丈夫か？ブルース、ブルース！",
          DialogueId = 10036701,
          GUID = "19203642",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036702,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203642"
        },
        [10036702] = {
          ContentJP = "見た目の割りに……も、脆すぎる……錬金院の技術も……大したことないね。",
          DialogueId = 10036702,
          GUID = "1920366C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036703,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/1920366C"
        },
        [10036703] = {
          ContentJP = "姉さん……銃の腕が、また上がった……前よりずっと上手だ……あれなら、ちゃんと……自分を守れる……ゴホッ！",
          DialogueId = 10036703,
          GUID = "19203696",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036704,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/19203696"
        },
        [10036704] = {
          ContentJP = "そんなこと言ってる場合か！",
          DialogueId = 10036704,
          GUID = "192036C0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036705,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/192036C0"
        },
        [10036705] = {
          ContentJP = "ハ、ハ……",
          DialogueId = 10036705,
          GUID = "192036EA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036706,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/192036EA"
        },
        [10036706] = {
          ContentJP = "待ってろ。医者を捕まえてきてやる！脅してでも手当させるから――",
          DialogueId = 10036706,
          GUID = "19203714",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036707,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203714"
        },
        [10036707] = {
          ContentJP = "……もう……いいんだ……",
          DialogueId = 10036707,
          GUID = "1920373E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036708,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/1920373E"
        },
        [10036708] = {
          ContentJP = "君は……何も言わないけど……僕にはわかるんだ……身体にこびりついた血が……何を意味するのかをね……",
          DialogueId = 10036708,
          GUID = "19203768",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036709,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/19203768"
        },
        [10036709] = {
          ContentJP = "こうして……死ねば……みんなも……助かる。",
          DialogueId = 10036709,
          GUID = "19203792",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036710,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/19203792"
        },
        [10036710] = {
          ContentJP = "ふざけるな！他人のことばかり言って、自分はどうなんだ！？約束したことを忘れたのか？外へ出たら舞台を作るんだろ！僕が演技を教えてやる！みんなを招待して公演を開くって言ってたじゃないか！",
          DialogueId = 10036710,
          GUID = "192037BC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030103.T_Story_Recall_10030103'",
          NextDialogue = 10036711,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/192037BC"
        },
        [10036711] = {
          ContentJP = "……ごめんね……守れそうにないや……",
          DialogueId = 10036711,
          GUID = "192037E6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036712,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/192037E6"
        },
        [10036712] = {
          ContentJP = "なっ……そうだ、お前の姉さん！お前、姉さんに会いたがってたじゃないか！こんなところでくたばっちゃダメだ！",
          DialogueId = 10036712,
          GUID = "19203810",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036713,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203810"
        },
        [10036713] = {
          ContentJP = "……僕は……臆病者なんだ……口では……家族に会うんだとか……偉そうに言っても……いざ目の前にすると……逃げることしか……できなかった……",
          DialogueId = 10036713,
          GUID = "1920383A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036714,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/1920383A"
        },
        [10036714] = {
          ContentJP = "お、お願いが……あるんだ。",
          DialogueId = 10036714,
          GUID = "19203864",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036715,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/19203864"
        },
        [10036715] = {
          ContentJP = "この編み紐は……僕の宝物だ。姉さんに……だ、第六軍団の……真相を……伝えてくれ……彼女を……同じ目に……合わせたくないんだ……",
          DialogueId = 10036715,
          GUID = "1920388E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036716,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/1920388E"
        },
        [10036716] = {
          ContentJP = "それから……<H>僕を殺したのが……姉さんだってこと……絶対に……知られちゃダメだ……</>そんなの知ったら……姉さんは……",
          DialogueId = 10036716,
          GUID = "192038B8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036717,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/192038B8"
        },
        [10036717] = {
          ContentJP = "たの……む……",
          DialogueId = 10036717,
          GUID = "192038E2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030104.T_Story_Recall_10030104'",
          NextDialogue = 10036718,
          SnapShot = "MEMORY",
          SpeakNpcId = 100327,
          SpeakNpcName = "Cp2CharacterName06",
          VoiceName = "voice/$Locale$/story/1003/100367/192038E2"
        },
        [10036718] = {
          ContentJP = "ブルース……！！",
          DialogueId = 10036718,
          GUID = "1920390C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036719,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/1920390C"
        },
        [10036719] = {
          ContentJP = "……わかったよ。",
          DialogueId = 10036719,
          GUID = "19203936",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036720,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203936"
        },
        [10036720] = {
          ContentJP = "だが、彼女にお前の死を隠した上で、第六軍団の真相を伝えるとなると……",
          DialogueId = 10036720,
          GUID = "19203960",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036721,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/19203960"
        },
        [10036721] = {
          ContentJP = "……そうか。",
          DialogueId = 10036721,
          GUID = "1920398A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
          NextDialogue = 10036722,
          SnapShot = "MEMORY",
          SpeakNpcId = 100328,
          SpeakNpcName = "Cp2CharacterName07",
          VoiceName = "voice/$Locale$/story/1003/100367/1920398A"
        },
        [10036722] = {
          ContentJP = "<H>「ブルース」が自ら姉さんに事実を伝えればいい</>……そうすれば……",
          DialogueId = 10036722,
          GUID = "192039B4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10030105.T_Story_Recall_10030105'",
