          VoiceName = "voice/$Locale$/story/1003/100370/192068CA"
        },
        [10037101] = {
          ContentJP = "昔々 とある雪国の城で 氷の妖精が二人の子どもに呼び覚まされた",
          DialogueId = 10037101,
          GUID = "192077E2",
          VoiceName = "voice/$Locale$/story/1003/100371/192077E2"
        },
        [10037102] = {
          ContentJP = "子どもたちは灯火を灯したが その凍った心を溶かすことはできなかった",
          DialogueId = 10037102,
          GUID = "1920780C",
          VoiceName = "voice/$Locale$/story/1003/100371/1920780C"
        },
        [10037103] = {
          ContentJP = "それでも彼らは雪の中 日々妖精のもとへ通い続けた",
          DialogueId = 10037103,
          GUID = "19207836",
          VoiceName = "voice/$Locale$/story/1003/100371/19207836"
        },
        [10037104] = {
          ContentJP = "やがて 妖精は彼らの笑い声や歌が響く生活に慣れ親しんでいった",
          DialogueId = 10037104,
          GUID = "19207860",
          VoiceName = "voice/$Locale$/story/1003/100371/19207860"
        },
        [10037105] = {
          ContentJP = "「もしも あの子たちのように笑えたら……」",
          DialogueId = 10037105,
          GUID = "1920788A",
          VoiceName = "voice/$Locale$/story/1003/100371/1920788A"
        },
        [10037106] = {
          ContentJP = "「もしも この凍えた心が少しでも溶けたなら……」",
          DialogueId = 10037106,
          GUID = "192078B4",
          VoiceName = "voice/$Locale$/story/1003/100371/192078B4"
        },
        [10037201] = {
          ContentJP = "ある日、雪国を野獣が襲い――",
          DialogueId = 10037201,
          GUID = "1920884A",
          NextDialogue = 10037202,
          VoiceName = "voice/$Locale$/story/1003/100372/1920884A"
        },
        [10037202] = {
          ContentJP = "空も大地も朱色に染まった",
          DialogueId = 10037202,
          GUID = "19208874",
          NextDialogue = 10037203,
          VoiceName = "voice/$Locale$/story/1003/100372/19208874"
        },
        [10037203] = {
          ContentJP = "少年との約束を果たすため 妖精は冷たい風を切り 山を下った",
          DialogueId = 10037203,
          GUID = "1920889E",
          NextDialogue = 10037204,
          VoiceName = "voice/$Locale$/story/1003/100372/1920889E"
        },
        [10037204] = {
          ContentJP = "「君の家族を見つけ、守ると約束するよ」",
          DialogueId = 10037204,
          GUID = "192088C8",
          VoiceName = "voice/$Locale$/story/1003/100372/192088C8"
        },
        [10037205] = {
          ContentJP = "廃墟の中 少女は野獣に囲まれていた",
          DialogueId = 10037205,
          GUID = "192088F2",
          VoiceName = "voice/$Locale$/story/1003/100372/192088F2"
        },
        [10037206] = {
          ContentJP = "「どうすれば この地を救えるだろう？どうすれば 彼女を守れるだろう？」",
          DialogueId = 10037206,
          Duration = 10,
          GUID = "1920891C",
