        },
        [10037207] = {
          ContentJP = "「どうすれば、獣を払えるだろう？凍った心を引き換えにしても――」",
          DialogueId = 10037207,
          Duration = 10,
          GUID = "19208946",
          VoiceName = "voice/$Locale$/story/1003/100372/19208946"
        },
        [10037208] = {
          ContentJP = "妖精は獣に飛びかかった しかし その手足は容易く砕かれる",
          DialogueId = 10037208,
          GUID = "19208970",
          NextDialogue = 10037209,
          VoiceName = "voice/$Locale$/story/1003/100372/19208970"
        },
        [10037209] = {
          ContentJP = "その瞬間 初めて鼓動を聞いた それは運命の音のように――",
          DialogueId = 10037209,
          GUID = "1920899A",
          VoiceName = "voice/$Locale$/story/1003/100372/1920899A"
        },
        [10037210] = {
          ContentJP = "「妖精に獣は倒せない。ならば、私自身が獣になればいい」",
          DialogueId = 10037210,
          GUID = "192089C4",
          VoiceName = "voice/$Locale$/story/1003/100372/192089C4"
        },
        [10037211] = {
          ContentJP = "「この身を捨て、爪を裂く刃になりましょう……」",
          DialogueId = 10037211,
          Duration = 10,
          GUID = "192089EE",
          NextDialogue = 10037212,
          VoiceName = "voice/$Locale$/story/1003/100372/192089EE"
        },
        [10037212] = {
          ContentJP = "「この顔を捨て、恐怖の鬼になりましょう……」",
          DialogueId = 10037212,
          Duration = 10,
          GUID = "19208A18",
          NextDialogue = 10037213,
          VoiceName = "voice/$Locale$/story/1003/100372/19208A18"
        },
        [10037213] = {
          ContentJP = "「この声を捨て、轟く咆哮に変えましょう……」",
          DialogueId = 10037213,
          Duration = 10,
          GUID = "19208A42",
          NextDialogue = 10037214,
          VoiceName = "voice/$Locale$/story/1003/100372/19208A42"
        },
        [10037214] = {
          ContentJP = "「この心を捨て、巨獣を貫く氷の刃になりましょう……」",
          DialogueId = 10037214,
          Duration = 10,
          GUID = "19208A6C",
          VoiceName = "voice/$Locale$/story/1003/100372/19208A6C"
        },
        [10037215] = {
          ContentJP = "「それでようやく、約束を果たせるのなら」",
          DialogueId = 10037215,
          Duration = 24,
          GUID = "19208A96",
          VoiceName = "voice/$Locale$/story/1003/100372/19208A96"
        },
        [10037301] = {
