        [10100612] = {
          Camera = "318.783203,25.541016,175.118164,0.001212,-9.69867,-171.999939,35.0,431.538452,false,Manual,4.0",
          ContentJP = "通行許可証はすぐにでも再発行を申請するわ。だけどかわいそうに……よほど怖かったみたいですっかり怯えちゃって。温かい物でも食べさせてあげたいから、できれば先に街へ入れて欲しいのだけど。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100612,
          ExStoryInfo = "Player",
