            [2] = 101006122
          },
          Scripts = "PlayAnimation{ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "I'll reapply for the travel permit soon, but the child is quite shaken. Please, have mercy on this poor thing, let {性别:him|her} in for a warm meal.",
