}]],
          SpeakNpcId = 200003,
          Subtitle = "...It's the Forsakens. I tell you what — I, Camilla Scarlet, on my honour, assure you that {性别:he|she} has nothing to do with the Forsakens.",
          VoiceName = "voice/$Locale$/story/1002/101006/19492C26"
        },
        [10100616] = {
          Camera = "-365.87207,335.160156,119.696777,0.001258,-1.199463,-44.99984,35.000008,615.484863,false,Manual,10.0",
          ContentJP = "……わかった。あんたがそこまで言う関係者ならば仕方ない。ただし絶対にそいつから目を離すなよ。街で騒ぎを起こすのなんざ厳禁だ。もし上官にバレでもしたら、俺もあんたも一大事になるからな。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10100616,
          ExStoryInfo = "Player",
          GUID = "19492C50",
          NextDialogue = 10100617,
          Scripts = [[
