PlayAnimation{ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "How curious. Some enigmatic benefactor from nowhere is willing to spend a fortune to save a stranger but doesn't want to reveal his identity or intention.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101008/19494CA2"
        },
        [10100814] = {
          ContentJP = "何者かが、お前を苦しみの海からすくいあげ、苦寒の荒野へと導くだろう。その地で、運命がもたらす真の試練の幕が上がるのだ。",
          DialogueId = 10100814,
          ExStoryInfo = "EXPlayer",
          GUID = "19494CA3",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10100814.T_Story_Recall_10100814'",
          NextDialogue = 10100815,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Fate has arranged for a pair of hands to pluck you from the brinish water and guide you to the next desolate land. There, you shall awaken anew.",
          TalkActionId = {
            [1] = "200002:Explain01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/100127/1910D56B"
        },
