PlayAnimation{ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "The 13th Legion is directly under the Emperor's command, with bases in every province, so Sibylle could be in any part of Hyperborea.",
          VoiceName = "voice/$Locale$/story/1002/101008/19494DC8"
        },
        [10100821] = {
          Camera = "-389.902344,-245.504395,22.587891,0.001195,10.30069,31.257433,35.000015,178.504257,false,DoNotOverride,4.0",
          ContentJP = "なかでも可能性が高いのは帝都ディズマニアの巨大な鋼鉄砦かしら。 国全体でももっとも訓練の行き届いた兵士たちに、想像もできないような兵器なんかが、あそこには集結しているわ。",
          DialogueId = 10100821,
          FinalCamera = "-373.101562,-274.45459,22.588379,0.001195,10.30069,35.05777,35.000015,178.504257,false,DoNotOverride,4.0",
          GUID = "19494DF2",
          NextDialogue = 10100822,
          RelatedWikiId = {
            [1] = 408004
          },
          Scripts = "PlayAnimation{_delay{2.2},ActorId{200003},AnimationId{\"Think_Start\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "The most likely place, though, is the colossal steel bastion in the imperial capital, aka Dismania, where you can find the Empire's finest soldiers and an arsenal of every type of conceivable and inconceivable armaments.",
          TalkActionId = {
            [1] = "100001:Sigh_End",
            [2] = "200003:Talk03_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/101008/19494DF2"
        },
        [10100822] = {
          Camera = "-2070.686523,-3294.441406,2337.578125,0.001209,26.398127,22.05953,11.0,10000.0,false,Manual,1.2",
          CameraBlendCurve = "easeInQuad",
          ContentJP = "轟音をうならせる戦車をヒュペリア帝国にたとえるならば、あの砦はいわばエンジン。国の核となる部分だと思いなさい。で、あなたはそんな場所を目指そうとしてるってわけ。今のご時世じゃあなたみたいな狂人は珍しくないし、行きたきゃ止めはしないけど。",
          DialogueId = 10100822,
          FinalCamera = "-1849.558594,-2787.050781,2533.88208,0.001209,26.398127,22.05953,12.0,10000.0,false,Manual,1.2",
          GUID = "19494E1C",
          NextDialogue = 10100823,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/talk_engine_roaring\"},EventKey{\"talk_engine_roaring\"},PlayAs2D{false}}",
          SpeakNpcId = 200003,
