          VoiceName = "voice/$Locale$/story/1002/101011/19497BE2"
        },
        [10101102] = {
          ContentJP = "うぉっほん！私は純白の救い手☆光の魔王様である！いいかね、{性别:彼|彼女}は……",
          DialogueId = 10101102,
          Duration = 2,
          ExStoryInfo = "Player",
          GUID = "19497C0C",
          SpeakNpcId = 200002,
          Subtitle = "Um, ahem! I am the Pure-white Redeemer ☆ Demon King of Light. Listen well, this person...",
