          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = [[
...And then, out of nowhere, he ambushed me and pinched the cash I'd just gotten. That rotter, doesn't even spare us scavengers!
That money was for several families' upkeep in the slums!]],
          TalkActionId = {
            [1] = "200011:Explain02_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101025/194A6192"
        },
        [10102502] = {
          Camera = "78.0,-7.4375,131.521484,0.000191,-2.398646,-161.013702,35.000008,175.980392,false,Manual,4.0",
          ContentJP = "おカネがないとスラムのお年寄りも小さい子も来月には飢え死んじゃうよ。でもコソ泥がどこに行ったかわからずじまいで…助けが必要なの。切実に。",
          DialogueId = 10102502,
          FacialId = {
            [1] = "200011:Sad01"
          },
          GUID = "194A61BC",
          LookAt = {
            [1] = "200003:n(200011)"
          },
          NextDialogue = 10102503,
          Scripts = "PlayAnimation{_delay{3},ActorId{200011},AnimationId{\"Sigh_Start\"},Duration{2}}",
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Without that bag of coins, all the young and old will have to tighten their belts even more next month. Ugh... I've no idea where the thief has run off to, I need someone to help me nab him.",
          TalkActionId = {
            [1] = "200011:Angry01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A61BC"
        },
        [10102503] = {
          Camera = "-197.983643,-228.263672,131.707031,0.000195,0.20134,50.188034,50.0,454.857483,false,Manual,5.0",
          ContentJP = "それは保安署の仕事じゃないかしら？",
          DialogueId = 10102503,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "194A61E6",
          LookAt = {
            [1] = "200003:n(200003)"
          },
          NextDialogue = 10102504,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"SpecialUnInterested_Start"},Duration{2}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Shouldn't this be something for the Security Bureau to handle?",
          VoiceName = "voice/$Locale$/story/1002/101025/194A61E6"
        },
        [10102504] = {
          Camera = "281.375,129.460938,170.882812,0.000218,-5.998777,-154.617096,62.0,422.431763,false,Manual,5.0",
          ContentJP = "そんないじわる言わないでって！保安署が私たちカロンのために働くわけないじゃん！待ってたら日が暮れるどころか、ダクリ湖の氷すら溶けちゃうもん！",
          DialogueId = 10102504,
          FacialId = {
            [1] = "200011:Unacceptable01"
          },
          GUID = "194A6210",
          LookAt = {
            [1] = "200011:n(200003)"
          },
          NextDialogue = 10102505,
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = "Well, by the time the Security Bureau bothers with us Charons, the ice in Lamenting Lake would've all melted away!",
          TalkActionId = {
            [1] = "200011:Sigh_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A6210"
        },
        [10102505] = {
          Camera = "-298.685974,-953.163086,100.919922,0.000218,0.201115,68.990013,50.0,1215.570923,false,Manual,6.0",
          ContentJP = "ねえねえ、お頼み申します、麗しきカミラお姉さま。ちょっと月狩り人に手伝ってもらえたらなぁーって……あの、本当にちょっとだけ！深い慈愛の心を持つお姉さまなら、悲しくて死んじゃいそうな私を見捨てたりなんてしないよね？",
          DialogueId = 10102505,
          FacialId = {
            [1] = "200011:Unacceptable01"
          },
          FinalCamera = "-302.263062,-951.791992,100.919922,0.000218,0.201115,68.990013,50.0,1215.570923,false,Manual,6.0",
          GUID = "194A623A",
          NextDialogue = 10102506,
          SpeakNpcId = 200011,
          SpeakNpcName = "UI_Npc_Name_NervouseMaer",
          Subtitle = [[
Please, Ms Camilla, the kindest and most beautiful lady in Icelake, could you maybe ask some of the Phoxhunters here to
lend a hand... Just one tiny favour! Pretty please!]],
          TalkActionId = {
            [1] = "200011:Explain02_Start",
            [2] = "200003:SpecialUnInterested_End"
          },
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/101025/194A623A"
        },
        [10102506] = {
          Camera = "10.047852,-140.40625,117.429688,0.000236,8.800841,67.194237,56.354355,240.957672,false,Manual,6.0",
          ContentJP = "猫なで声なんて出しても無駄よ。知っているとは思うけど、ここでの頼み事には相応の対価が必要になるわ。",
          DialogueId = 10102506,
          GUID = "194A6264",
          NextDialogue = 10102507,
          SpeakNpcId = 200003,
          Subtitle = "Save it. You should know that nothing asked for here comes without a price.",
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101025/194A6264"
        },
        [10102507] = {
          Camera = "81.471924,-18.664062,159.626953,0.000213,-10.598773,-163.809616,48.734837,175.980392,false,Manual,4.0",
          ContentJP = "じゃあせめて、ほら……少しでいいの、少し安くしてくんないかな？ほかの何かで支払いを埋め合わせるって話でも大丈夫！あれ、あの言葉、なんだったっけか――",
          DialogueId = 10102507,
          GUID = "194A628E",
          NextDialogue = 10102508,
