        },
        [10103501] = {
          Camera = "-165.324219,313.250977,140.767822,0.000018,-4.657957,-60.556728,41.027447,1.5,false,Disable,1.2",
          ContentJP = "なんか変なの。カミラお姉さまは海千山千の人たちと渡り合ってきたはずなのに、さっきはちょっと動揺してた気がする……",
          DialogueId = 10103501,
          FacialId = {
            [1] = "200011:Think01"
          },
          GUID = "194AF569",
          LookAt = {
            [1] = "200002:n(200011)",
            [2] = "100001:n(200011)"
          },
          NextDialogue = 10103502,
          RelatedWikiId = {
            [1] = 408003,
            [2] = 405004,
            [3] = 201008,
            [4] = 201005
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/mute\"}}",
          SpeakNpcId = 200011,
          Subtitle = "No, please... I'm begging you! Don't send me there—",
          TalkActionId = {
            [1] = "200011:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF569"
        },
        [10103502] = {
          Camera = "-135.308594,-179.244141,147.530365,0.000016,-7.258025,49.643944,35.000008,1.5,false,Disable,1.2",
          ContentJP = "あのコソ泥も急にブルブル怯えちゃってさ。保安署ってそんなにおっかない場所なのかな？",
          DialogueId = 10103502,
          FacialId = {
            [1] = "200002:Shock01"
          },
          GUID = "194AF570",
          NextDialogue = 10103503,
          SpeakNpcId = 200002,
          Subtitle = "He seemed terrified. I wonder what's in store for him at the Security Bureau.",
          TalkActionId = {
            [1] = "200002:Shock_Start",
            [2] = "200011:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF570"
        },
        [10103503] = {
          Camera = "-37.669922,74.164062,136.618378,0.000016,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
          ContentJP = "きっと保安署送りになったら、きっつーいお仕置きをされちゃうんだね。あーあ、本当はお財布を取り戻して、ちょっとだけボコって終わりにしようと思ってたんだけど。なんか大騒ぎになっちゃった……",
          DialogueId = 10103503,
          FacialId = {
            [1] = "200011:Unhappy01"
          },
          GUID = "194AF571",
          NextDialogue = 10103504,
          SpeakNpcId = 200011,
          Subtitle = "Mmm, they'll probably give him a really harsh telling-off. But more importantly, I must commend you.",
          TalkActionId = {
            [1] = "200002:Shock_End",
            [2] = "200011:SpecialHoldHelmet_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF571"
        },
        [10103504] = {
          Camera = "-165.324219,313.250977,140.767822,0.000018,-4.657957,-60.556728,41.027447,1.5,false,Disable,1.2",
          ContentJP = "あ、忘れるところだった。報酬報酬！これあげる！",
          DialogueId = 10103504,
          FacialId = {
            [1] = "200011:Smile01"
          },
          GUID = "194AF572",
          NextDialogue = 10103505,
          Scripts = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Give\"},Duration{1}}",
          SpeakNpcId = 200011,
          Subtitle = "Heehee, you were on fire, my little minion! That brash thing, and yet we put him in his place!",
          TalkActionId = {
            [1] = "200011:SpecialHoldHelmet_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF572"
        },
        [10103505] = {
          ContentJP = "えへへ。ほんっとーにありがとうね！{nickname}ちゃんは私の大恩人……ううん。私たちはもう父違いで母違いの実の{性别:兄弟|姉妹}だよ！",
          DialogueId = 10103505,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200011:Smile02"
          },
          GUID = "194AF573",
          NextDialogue = 10103506,
          SpeakNpcId = 200011,
          Subtitle = "A little correction — it wasn't \"we\", you were hiding behind me the whole time.",
          TalkActionId = {
            [1] = "200011:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF573"
        },
        [10103506] = {
          Camera = "-33.322266,90.494141,136.335449,0.000018,-4.258083,-78.357025,35.000011,1.5,false,Disable,1.2",
          ContentJP = "早く戻ってみんなにおカネを分けてあげなくちゃ。私はいつもアイスレイク城のあちこちで「仕入れ」をしているんだけどさ。何か用があったらスラムの人たちに私の名前を伝えてね、マギーはどこだって。そしたらきっとまた会えるから。",
          DialogueId = 10103506,
          GUID = "194AF574",
          Scripts = "PlayAnimation{_delay{2},ActorId{200011},AnimationId{\"Explain02_Start\"},Duration{1}}",
          SpeakNpcId = 200011,
          TalkActionId = {
            [1] = "200011:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101034/194AF574"
        },
        [10103507] = {
          ContentJP = "我が下僕よ、早くカミラのもとに戻ろうではないか！",
          DialogueId = 10103507,
          GUID = "194AF575",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101034/194AF575"
        },
        [10103601] = {
          ContentJP = "「アスフォデロス」は南の方にあるの。",
          DialogueId = 10103601,
          Duration = 3,
          GUID = "194B160A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10103602,
          SpeakNpcId = 200006,
          Subtitle = "The Asphodel is just to the south.",
          VoiceName = "voice/$Locale$/story/1002/101036/194B160A"
        },
        [10103602] = {
          ContentJP = "おいおーーい急げーー！スノウが広場で待ってるぞーー！",
          DialogueId = 10103602,
          Duration = 4,
          GUID = "194B1634",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Come on! Snow will be waiting for you in the square!",
          VoiceName = "voice/$Locale$/story/1002/101036/194B1634"
        },
        [10103701] = {
          ContentJP = "こっちにご注目！月狩り人への依頼はこの掲示板に貼り出されるんだよ！",
          DialogueId = 10103701,
          Duration = 3,
          GUID = "194B2672",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "Over here, all the commissions for Phoxhunters are listed on this board!",
          VoiceName = "voice/$Locale$/story/1002/101037/194B2672"
        },
        [10103801] = {
          Camera = "172.692993,-479.681641,69.009766,0.001296,4.999999,95.0,25.000006,357.352783,false,DoNotOverride,1.2",
          ContentJP = "よぉ、スノウじゃないか。例のごとく月狩り人の手伝いか？今回は泥棒を何百人も捕まえたり、驚愕の陰謀をいくつも暴き出したってとこだろう？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10103801,
          FinalCamera = "158.725586,-480.897461,69.009766,0.001297,4.999999,97.500046,25.000006,357.352783,false,DoNotOverride,1.2",
          GUID = "194B36DA",
          LookAt = {
