        },
        [10104017] = {
          ContentJP = "危険なことはわかっています。心配してくれてありがとう……でも、カミラさんの言った通り……",
          DialogueId = 10104017,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          GUID = "194B5A4A",
          LookAt = {
            [1] = "100001:n(200065)"
          },
          NextDialogue = 10104018,
          Scripts = [[
PARA{
LookAt{_delay{3},LookAtDescription{"100001:n(200003)"}},
CameraMoveTo{_delay{3.2},TargetPosition{"21.058167,-60.678711,137.054688,0.001258,0.301785,41.650921,60.000004,500.770081,false,DoNotOverride,19.947756"},duration{0}},
SetRotation{_delay{3.2},SetRotationDescription{"200003:n(200006)"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Thank you, I get it. But Ms Camilla...",
          TalkActionId = {
