        },
        [10104018] = {
          Camera = "586.407837,263.538086,166.693359,0.001254,-5.098381,-163.341629,60.0,424.533936,false,Manual,3.8",
          ContentJP = "ひとりで稼ぐことさえできないのに、なくした大事なモノを探し出すなんて、夢のまた夢だから。",
          DialogueId = 10104018,
          ExStoryInfo = "Player",
          GUID = "194B5A74",
          LookAt = {
            [1] = "100001:n(200003)",
            [2] = "200006:n(100001)"
          },
          NextDialogue = 10104019,
          Scripts = [[
PARA{
PlayAnimation{_delay{2.5},ActorId{100001},AnimationId{"Explain02_Start"},Duration{2}},
PlayFacial{_delay{5},ActorId{200006},FacialId{"Smile01"}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "You once told me — if I can't handle this, how am I supposed to find my family?",
          TurnTo = {
            [1] = "100001:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A74"
        },
        [10104019] = {
          Camera = "-127.626587,-169.432617,135.080078,0.001295,0.699917,38.798576,70.000015,100000.0,false,DoNotOverride,2.8",
          ContentJP = "アスフォデロスは依頼内容に干渉しないわ。月狩り人として働き始めた以上、あなたの決意が確かならば私に引きとめる権利もない。",
          DialogueId = 10104019,
          FacialId = {
            [1] = "200003:Uninterested01"
          },
          GUID = "194B5A9E",
          LookAt = {
            [1] = "200065:n(200003)"
          },
          NextDialogue = 10104022,
          Scripts = [[
SEQ{
PlayAnimation{_delay{5.3},ActorId{200003},AnimationId{"Talk03_End"},Duration{1.8}},
PlayAnimation{ActorId{200003},AnimationId{"Disagree"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "The Asphodel doesn't interfere with the choices of clients or Phoxhunters. If you're set on it, I won't stand in your way.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          TurnTo = {
            [1] = "200065:n(200003)"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A9E"
        },
        [10104020] = {
          Camera = "259.278076,116.387695,137.603516,0.001216,-0.898272,38.841999,25.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "さっき財布を取り戻した報酬を渡しておくわ。そしてこれも、おまけに持っていきなさい。",
          DialogueId = 10104020,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194B5AC8",
          NextDialogue = 10104021,
          Scripts = "PlayAnimation{_delay{5},ActorId{200003},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 200003,
          Subtitle = "Here's your due for getting Margie's money back. And take this with you as well.",
          TalkActionId = {
            [1] = "200003:Give"
          },
          VoiceName = "voice/$Locale$/story/1002/101040/194B5AC8"
        },
        [10104021] = {
          Camera = "-501.142578,-406.078125,344.859375,0.001474,-14.701865,36.043182,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "無事に戻ってくるように。願っておくわ。",
          DialogueId = 10104021,
          FinalCamera = "-751.681763,-588.393555,426.658203,0.001474,-14.701865,36.043182,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "194B5AF2",
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200003},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{ActorId{200003},AnimationId{"Talk03_Start"},Duration{1}}
}]],
          SpeakNpcId = 200003,
          Subtitle = "Make it back in one piece.",
          ToFinalCameraBlendTime = 12,
          VoiceName = "voice/$Locale$/story/1002/101040/194B5AF2"
        },
        [10104022] = {
          ContentJP = "群星のジェムは青紫色の結晶で、その内部にまるで星雲が宿っているよう。暗い鉱坑では非常に目立つから、きっと見逃さないわ。",
          DialogueId = 10104022,
          GUID = "194B5A9F",
          NextDialogue = 10104020,
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/story/1002/101040/194B5A9F"
        },
        [10104101] = {
          ContentJP = "……群星のジェム……ヘンリックおじさん……",
          DialogueId = 10104101,
          GUID = "194B6812",
          SpeakNpcId = 200006,
          Subtitle = "...Crystallo of Stella... Mr Henrik...",
          VoiceName = "voice/$Locale$/story/1002/101041/194B6812"
        },
        [10104201] = {
          ContentJP = "無理はするなよ、{性别:坊主|嬢ちゃん}。少しでもまずいと感じたら、機を見て逃げるのも悪かないからな？",
          DialogueId = 10104201,
          ExStoryInfo = "Player",
          GUID = "194B787A",
          SpeakNpcId = 200015,
          Subtitle = "Don't be a hero, kid. Run for your life if things get dicey.",
          VoiceName = "voice/$Locale$/story/1002/101042/194B787A"
        },
        [10104301] = {
          ContentJP = "アスフォデロスにはお酒以外に、\n買えるものはいくらでもある…\nまぁ、前提としてはそれなりの代償を支払うことわよ。",
          DialogueId = 10104301,
          GUID = "194B88E2",
          NextOptions = {
            [1] = 101043011,
            [2] = 101043051,
            [3] = 101043091,
            [4] = 101043112
          },
          SpeakNpcId = 200003,
          Subtitle = "Back for a drink already?",
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_02"
        },
        [10104302] = {
          ContentJP = "何から話しましょうか……まあ、歴史はかなり長いわよ。800年前の「大移住」の後、初代皇帝によって築かれたの。帝国の歴史のなかでも一番古い都市のひとつね。",
          DialogueId = 10104302,
          GUID = "194B890C",
          NextDialogue = 10104303,
          SpeakNpcId = 200003,
          Subtitle = "Where to begin... well, it's got a long history. Built by the Empire's first ruler after the Great Migration 800 years ago, it's among the first few cities of the empire.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B890C"
        },
        [10104303] = {
          ContentJP = "ここは帝国の最北に位置する都市で、北へ100km以上進めばヴィドフニル山脈。それを越えた先にはアースガルドの地があるわ。",
          DialogueId = 10104303,
          GUID = "194B8936",
          NextDialogue = 10104304,
          SpeakNpcId = 200003,
          Subtitle = "It's also the northernmost major city of the Empire. Just over a hundred kilometres further north, past the Vidofnir Mountains, and you're on Askard's turf.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8936"
        },
        [10104304] = {
          ContentJP = "昔のアイスレイク城は月ノ石の産出地として有名だったの。数十年前までグルビューム鉱山がヒュペリア最大の採掘場だったのだけどね。鉱脈が枯れちゃって、今となっては当時から残っている工場がなんとか稼働しているだけ。",
          DialogueId = 10104304,
          GUID = "194B8960",
          NextDialogue = 10104305,
          SpeakNpcId = 200003,
          Subtitle = "Icelake used to be known for its Phoxene veins. Take Glevum Pit for example — one of Hyperborea's largest Phoxene mines back in the day. But now, the veins are spent, only the old factories are barely chugging along.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8960"
        },
        [10104305] = {
          ContentJP = "……なんて話は本を読めば書いてある、周知の常識だし。いっそ自分の目で直接確かめたほうが早いかも。この街の氷の下に、何が埋もれているのかを。",
          DialogueId = 10104305,
          GUID = "194B898A",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "But then, this is all stuff you can read about in books, things anyone could tell you. I'd suggest you look with your own eyes and listen with your heart, to find out what truly lurks beneath this city's snow and ice.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B898A"
        },
        [10104306] = {
          ContentJP = "口だけは達者で、頭のなかは損得勘定ばかりが詰まっている生意気な連中よ。生計のためにやっているヤツもいれば、刺激を求める冒険好きなヤツもいるわ。共通してるのは、ケガしてばかりな危険屋って感じね。",
          DialogueId = 10104306,
          GUID = "194B89B4",
          NextDialogue = 10104307,
          SpeakNpcId = 200003,
          Subtitle = "A bunch of cheap, noisy blighters keen on spinning yarns. Some of them became Phoxhunters to eke a living, some just fancy a bit of ruckus and adventure. One thing they have in common is they often end up more battered and bruised than not.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B89B4"
        },
        [10104307] = {
          ContentJP = "本音を言えば、店から叩きだしてやりたいわ。あんな連中、道端でからっ風にさらされればいいのよ。",
          DialogueId = 10104307,
          GUID = "194B89DE",
          NextDialogue = 10104308,
          SpeakNpcId = 200003,
          Subtitle = "Truth be told, I've often wanted to give them the boot, let them munch on dirty snow and gulp the north wind outside.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B89DE"
        },
        [10104308] = {
          ContentJP = "だけど保安署が放置してる仕事は誰が片付けてくれるのか……って考えるとね。あの連中の働きがあってこそ、ここアスフォデロスで一杯やろうって客が現れるのよ。",
          DialogueId = 10104308,
          GUID = "194B8A08",
          NextDialogue = 10104309,
          SpeakNpcId = 200003,
          Subtitle = "But then, they do manage a fair bit that ought to be the Security Bureau's job. Without them, likely not many in this city would have the luxury to kick back in my tavern.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A08"
        },
        [10104309] = {
          ContentJP = "あいつらのバカ騒ぎを大目に見ているのはそのためよ。お互いに利益の関係でしかないの。だとしても、連中はもう少し声を抑えるべきだし、取っ組み合いの喧嘩は控えてほしいわね。",
          DialogueId = 10104309,
          GUID = "194B8A32",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "So I let them gather and natter here, a bit of quid pro quo. Still, I do wish they'd keep it down a little and get into fewer brawls.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A32"
        },
        [10104310] = {
          ContentJP = "あら、誰も教えてくれなかったの？女性のプライバシーには無闇に踏み込まないこと。無粋な人だなって思われちゃうわよ？",
          DialogueId = 10104310,
          GUID = "194B8A5C",
          NextDialogue = 10104311,
          SpeakNpcId = 200003,
          Subtitle = "Hasn't anyone told you it's rather rude to pry into a lady's secrets for no reason?",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A5C"
        },
        [10104311] = {
          ContentJP = "もし聞きたいなら――報酬を支払ってちょうだいな。私が満足できるほどの……ふふ。",
          DialogueId = 10104311,
          GUID = "194B8A86",
          NextDialogue = 10104301,
          SpeakNpcId = 200003,
          Subtitle = "Of course, I can share my stories with you — provided you can pay the right price... hehe.",
          VoiceName = "voice/$Locale$/story/1002/101043/194B8A86"
        },
        [10104401] = {
          Camera = "937.774414,-120.576172,119.04834,0.000012,-1.999695,166.391983,35.0,762.45813,false,Manual,1.6",
          ContentJP = "ちょっと待って！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 10104401,
          FinalCamera = "936.792969,-122.973145,119.04834,0.000012,-1.999695,163.999969,35.0,762.45813,false,Manual,5.0",
          GUID = "194B994A",
