          SpeakNpcId = 200006,
          Subtitle = "The entrance to Glevum Pit is up ahead. Please be extra careful.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA1A"
