          },
          VoiceName = "voice/$Locale$/story/1002/101046/194BBA44"
        },
        [10104603] = {
          ContentJP = "先にふたりは帰っておいて。ここから先は{性别:僕|私}ひとりで行くから。",
          DialogueId = 10104603,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "194BBA6E",
          NextDialogue = 10104604,
