          SpeakNpcId = 200021,
          Subtitle = "And come alone — don't bring anyone unrelated.",
          ToFinalCameraBlendTime = 4,
          VoiceName = "voice/$Locale$/story/1002/101054/194C4414"
        },
        [10105501] = {
          ContentJP = "あっちに道があるよ。早く行こう。こんな場所にずっといたら心が暗くなっちゃう……",
          DialogueId = 10105501,
          GUID = "194C4DC1",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105502,
          SpeakNpcId = 200002,
          Subtitle = "\"Anyone unrelated\"... Wait, he wasn't talking about me, was he?",
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC1"
        },
        [10105502] = {
          ContentJP = "……ん？ちょっと待って。アウトサイダーが言ってた「無関係なヤツ」って？私のことじゃないよね？",
          DialogueId = 10105502,
          GUID = "194C4DC2",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          Subtitle = "...Wait, when he said \"anyone unrelated,\" he wasn't talking about me, was he?",
          VoiceName = "voice/$Locale$/story/1002/101055/194C4DC2"
        },
        [10105601] = {
          ContentJP = "この道、さっき通ってきた坑道と違う……誰かが掘ったのかな？",
          DialogueId = 10105601,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5E2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105602,
          SpeakNpcId = 100001,
          Subtitle = "This trail feels different from the one we passed through earlier, almost as if it's been hand-dug by someone.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E2A"
        },
        [10105602] = {
          ContentJP = "ほんとだね。スコップが転がってるし......かなり昔にもここに来た冒険家がいたみたいだね。",
          DialogueId = 10105602,
          Duration = 3,
          GUID = "194C5E54",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10105603,
          SpeakNpcId = 200002,
          Subtitle = "Yeah, there are even shovels lying around here... Looks like other adventurers have been here before us!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E54"
        },
        [10105603] = {
          ContentJP = "というかサイキ、調子悪いの？さっきから何も話してないし、顔色もよくないみたいだけど。",
          DialogueId = 10105603,
          Duration = 3,
          GUID = "194C5E7E",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105604,
          SpeakNpcId = 200002,
          Subtitle = "Are you alright, Psyche? You look pale, and you've been so quiet since a while ago.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5E7E"
        },
        [10105604] = {
          ContentJP = "えっ、そ、そうかな？",
          DialogueId = 10105604,
          Duration = 3,
          GUID = "194C5EA8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10105605,
          SpeakNpcId = 200006,
          Subtitle = "Ah, have I?",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EA8"
        },
        [10105605] = {
          ContentJP = "多分……さっきの<Default note=\"text:エジュウ\">穢獣</>のせいだと思う。まだちょっと足が震えちゃっているから。",
          DialogueId = 10105605,
          Duration = 3,
          GUID = "194C5ED2",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10105606,
          SpeakNpcId = 200006,
          Subtitle = "I'm probably still a bit shaken from that monster we met back there.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5ED2"
        },
        [10105606] = {
          ContentJP = "恐るるに足らず！この魔王様と下僕がいるのだぞ！",
          DialogueId = 10105606,
          Duration = 3,
          GUID = "194C5EFC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105607,
          SpeakNpcId = 200002,
          Subtitle = "Relax! We're right here with you!",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5EFC"
        },
        [10105607] = {
          ContentJP = "さっきのアホチンサイダーも我が下僕は特別な「骸」だと語ってたじゃんか？たとえ10匹ぐらい<Default note=\"text:エジュウ\">穢獣</>が来たって、{nickname}の相手にはならないのさ！",
          DialogueId = 10105607,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F26",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105608,
          SpeakNpcId = 200002,
          Subtitle = "That Outsider said that my little minion is a strong \"Daimon,\" right? So even if ten more Filthoids came at us, they'd be no match for {性别:him|her}.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F26"
        },
        [10105608] = {
          ContentJP = "適当なこと{性别:言うなって|言わないでよ}。こっちはもうヘトヘトだし、サイキだってさっきは無理に強がってたんだから。",
          DialogueId = 10105608,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F50",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10105609,
          SpeakNpcId = 100001,
          Subtitle = "Rubbish. I'm nearly spent, and Psyche was just bluffing.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F50"
        },
        [10105609] = {
          ContentJP = "みんな無事で本当によかった……やっぱりふたりを巻き込むべきじゃなかったかもしれない。",
          DialogueId = 10105609,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "194C5F7A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10105610,
          SpeakNpcId = 100001,
          Subtitle = "I'm just relieved you're both safe... Maybe I shouldn't have involved you two in such a dangerous event.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5F7A"
        },
        [10105610] = {
          ContentJP = "そんなことないよ！今日一緒に「冒険」できて、私はすっごく満足だったんだから！",
          DialogueId = 10105610,
          Duration = 3,
          GUID = "194C5FA4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10105611,
          SpeakNpcId = 200006,
          Subtitle = "No, not at all! I'm really happy that I took part in such an adventure.",
          VoiceName = "voice/$Locale$/story/1002/101056/194C5FA4"
        },
        [10105611] = {
          ContentJP = "仲間と一緒に、慣れ親しんだ街から一歩を踏み出して、行ったことのない場所に向かう。みんなでおしゃべりしたり、危険な敵に立ち向かったり……私にこんなことができるなんて、夢にも思わなかったの。",
          DialogueId = 10105611,
          Duration = 3,
          GUID = "194C5FCE",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
