        [10108502] = {
          Camera = "-115.567871,-338.226562,281.567627,0.000205,-25.200125,66.302895,40.000011,546.789001,false,Manual,2.0",
          ContentJP = "アウトサイダーってば本当にアウトなヤツなんだよ！スノウはここで見張っておけってさ。魔王様の偉大なる能力は下僕たちを率いるためにこそあり、勇敢な狩りへ赴くべきものなんだよ？陰気臭いおじさんを監視するためにあるものじゃないの！",
          DialogueId = 10108502,
          FacialId = {
            [1] = "200064:Doubt01"
          },
          FinalCamera = "-99.011719,-300.50293,244.98291,0.000237,-21.799927,66.303619,40.000011,483.54599,false,Manual,2.0",
          GUID = "194E3A1C",
          LookAt = {
