          VoiceName = "voice/$Locale$/story/1002/101097/194EFF50"
        },
        [10109706] = {
          Camera = "-513.90625,86.755859,248.274414,-3.000002,-22.199732,4.520242,50.0,589.274902,false,Manual,12.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentJP = "4歳の時にお父さんからもらったの。きれいなスズランをお父さんが栽培して、内城区の大富豪さんがとても喜んでくれてね。お礼としてお父さんに贈られたのがこのカメラだったの。それを私の誕生日にプレゼントしてくれて…",
          DialogueId = 10109706,
          FacialId = {
            [1] = "200006:Happy02"
          },
          FinalCamera = "-513.90625,86.755859,228.629883,-3.000002,-19.999599,4.520289,50.0,589.274902,false,Manual,12.0",
          GUID = "194EFF7A",
          NextDialogue = 10109707,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200006},AnimationId{"Talk02_End"},Duration{2}},
PlayAnimation{ActorId{200006},AnimationId{"Explain01_Start"},Duration{2}},

}]],
          SpeakNpcId = 200006,
          Subtitle = "Dad gave it to me when I was four. That year, he had managed to grow beautiful Lamenting Lake Bellflowers. A wealthy man from the inner city loved the flowers and gave this camera to Dad, which he then gave to me as a birthday gift.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101097/194EFF7A"
        },
        [10109707] = {
          Camera = "97.855469,26.320312,46.532227,-1.0,10.398955,146.71611,50.0,242.458954,false,Manual,8.0",
          ContentJP = "使うのがもったいなくて、その時に思っちゃったの。土に埋めて収穫の季節を待てば、カメラがたくさん生えてくるかもって。そしたら、お父さんとお母さんを楽させられるぐらいの、お金持ちになれるかも、とか。",
          DialogueId = 10109707,
          FacialId = {
            [1] = "200006:None"
          },
          FinalCamera = "95.832031,23.208984,46.592773,-1.0,10.398955,145.715927,50.0,242.458954,false,Manual,8.0",
          GUID = "194EFFA4",
          NextDialogue = 10109708,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200006},AnimationId{"Explain01_End"},Duration{2}},
PlayAnimation{ActorId{200006},AnimationId{"DisagreeHead"},Duration{2}},
PlayAnimation{ActorId{200006},AnimationId{"Explain02_Start"},Duration{2}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "But I cherished it too much to actually play with it. I thought, if I buried this precious treasure in the ground, it would sprout many more cameras by harvest time. Then our family would become rich, and my parents wouldn't have to work so hard.",
          ToFinalCameraBlendTime = 13,
          VoiceName = "voice/$Locale$/story/1002/101097/194EFFA4"
        },
        [10109708] = {
          Camera = "17.835938,30.003906,75.855469,0.000003,5.999706,139.000046,50.0,172.869095,false,Manual,5.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentJP = "だからこっそり箱ごと「植えて」みたの……あの頃の私、本当におバカさんだったよね。",
          DialogueId = 10109708,
          FinalCamera = "17.835938,30.003906,75.855469,0.000003,6.399723,139.000046,53.0,172.869095,false,Manual,5.0",
          GUID = "194EFFCE",
          NextDialogue = 10109709,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{200006},AnimationId{"Explain02_End"},Duration{1.5}},
LookAt{LookAtDescription{"200006:p(Point101097)"}}
}]],
          SpeakNpcId = 200006,
          Subtitle = "So I came here alone and \"sowed\" it. I was quite silly back then.",
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1002/101097/194EFFCE"
        },
        [10109709] = {
          Camera = "-167.960938,132.5625,94.099609,0.000283,-8.400545,-7.686968,50.0,217.697235,false,Manual,8.0",
          ContentJP = "でもお父さんとお母さんは私を責めたりしなかった。「じゃあサイキが大人になったら掘り出そう。未来の自分への贈り物にしよう」って言ってくれたっけ。",
          DialogueId = 10109709,
          FacialId = {
            [1] = "200006:Smile01"
          },
          FinalCamera = "-167.53125,135.693359,94.099609,0.000283,-8.400545,-8.887018,50.0,217.697235,false,Manual,8.0",
          GUID = "194EFFF8",
          LookAt = {
            [1] = "200006:n(100001)"
          },
          NextOptions = {
            [1] = 10109710,
            [2] = 10109711
          },
          SpeakNpcId = 200006,
          Subtitle = "When Mum and Dad found out about this later, they didn't get mad at me. Instead, they said, \"Let's dig it up on your coming of age, as a gift to your future self.\"",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101097/194EFFF8"
        },
        [10109710] = {
          ContentJP = "かわいらしいアイディアだね。",
          DialogueId = 10109710,
          GUID = "10109710.0",
          NextDialogue = 10109712
        },
        [10109711] = {
