          GUID = "194F409C",
          SpeakNpcName = "UI_Npc_Name_SuspiciousMan",
          Subtitle = "Stay back... or I'll shoot!",
          TalkActionId = {
            [1] = "200004:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101101/194F409C"
        },
        [10110201] = {
