        },
        [10110202] = {
          Camera = "63.138672,-228.014648,186.216797,0.000054,-12.399627,106.79998,35.0,399.040039,false,Manual,3.749117",
          ContentJP = "お前は……？",
          DialogueId = 10110202,
          ExStoryInfo = "Player",
          FacialId = {
