          GUID = "194F5104",
          NextDialogue = 10110203,
          SpeakNpcId = 100001,
          Subtitle = "It's you?",
          TalkActionId = {
            [1] = "100001:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/101102/194F5104"
        },
        [10110203] = {
          ContentJP = "……わかった。あんたがそこまで言う関係者ならば仕方ない。ただし絶対にそいつから目を離すなよ。街で騒ぎを起こすのなんざ厳禁だ。もし長官にバレでもしたら、俺もあんたも一大事になるからな。",
          DialogueId = 10110203,
          ExStoryInfo = "Player",
          GUID = "194F512E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110203.T_Story_Recall_10110203'",
          NextDialogue = 10110204,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 200004,
          SpeakNpcName = "UI_Npc_Name_Man_4",
          Subtitle = "Alright, I trust you, Ms Camilla. But remember, keep a close eye on this kid and don't let {性别:him|her} stir up any trouble in town. If the Chief finds out about this, we'll both be in for it.",
          VoiceName = "voice/$Locale$/story/1002/101006/19492C50"
        },
        [10110204] = {
          Camera = "47.769531,188.458008,134.702148,0.000103,0.398248,-107.229118,35.0,362.075562,false,Manual,3.0",
          ContentJP = "マジか、よりにもよってお前に捕まるとは……なあ頼むよ、{性别:坊ちゃん|嬢ちゃん}。このことは他言無用でお願いできないか？",
          DialogueId = 10110204,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "200004:Sad01"
          },
          GUID = "194F5158",
          NextDialogue = 10110205,
          Scripts = [[
PARA{
PlayAnimation{_delay{1},ActorId{200004},AnimationId{"Disagree"},Duration{1}},
