        [10110233] = {
          ContentJP = "ちょっとめまいがして、段差があるの見落としていて……ありがとう！",
          DialogueId = 10110233,
          GUID = "194F559C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_10110233.T_Story_Recall_10110233'",
          NextDialogue = 10110234,
