        [10110902] = {
          Camera = "-231.873047,-73.172028,160.285156,0.000103,-6.596924,20.794041,40.000011,446.663574,false,Manual,5.5",
          ContentJP = "これを持っていって。",
          DialogueId = 10110902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter01_Flower_1.T_Guide_Chapter01_Flower_1'}",
          GUID = "194FC3DC",
          NextDialogue = 10110903,
          SpeakNpcId = 200045,
          Subtitle = "Please take this with you.",
          TalkActionId = {
            [1] = "200045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC3DC"
        },
        [10110903] = {
          Camera = "64.572266,91.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          ContentJP = "サイキはよく花をくれたの。私たちのなかには、花の香りがもうわからない人がいるし、花の輪郭すら見えない人だっていた。でもサイキは「お花は幸運を運んでくれるから」ってずっと言ってた。",
          DialogueId = 10110903,
          FinalCamera = "64.572266,141.821472,278.037109,0.0,0.0,89.999992,30.0,100000.0,false,DoNotOverride,22",
          GUID = "194FC406",
          LookAt = {
            [1] = "200045:p(P10106801)"
          },
          NextDialogue = 10110904,
          SpeakNpcId = 200045,
          Subtitle = "Psyche often gave us flowers. Even though some of us can barely smell or see them clearly anymore, she kept doing it, saying flowers bring good luck.",
          TalkActionId = {
            [1] = "200045:Talk02_End"
          },
          ToFinalCameraBlendTime = 7.5,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC406"
        },
        [10110904] = {
          Camera = "-64.513672,-54.797607,154.447266,0.000147,-5.19662,21.383118,35.000008,170.88736,false,Manual,3.0",
          ContentJP = "……私は「ありがとう」って言おうと思ってた……でも間に合わなかった。",
          DialogueId = 10110904,
          GUID = "194FC430",
          NextDialogue = 10110905,
          SpeakNpcId = 200045,
          Subtitle = "...But by the time I wanted to return her kindness, it was already too late.",
          TalkActionId = {
            [1] = "200045:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC430"
        },
        [10110905] = {
          Camera = "-230.103516,-78.412262,153.914062,0.000093,-5.797054,21.191561,35.000008,351.556366,false,Manual,4.0",
          ContentJP = "この花をサイキに渡してあげて。サイキが大好きな花なの。",
          DialogueId = 10110905,
          GUID = "194FC45A",
          LookAt = {
            [1] = "200045:n(100001)"
          },
          NextDialogue = 10110906,
          SpeakNpcId = 200045,
          Subtitle = "Please bring this flower to her. It's her favourite.",
          TalkActionId = {
            [1] = "200045:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC45A"
        },
        [10110906] = {
          Camera = "-7.181641,-249.865479,233.710938,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
          CameraBlendCurve = "easeInOutQuad",
          ContentJP = "そして彼女に伝えて。「ヒュプノスの家のみんながサイキの帰りを待ってるよ」って。",
          DialogueId = 10110906,
          FinalCamera = "-4.027344,-306.261597,265.148438,0.000057,-29.099882,93.194183,15.000005,100000.0,false,DoNotOverride,22.0",
          GUID = "194FC484",
          NextDialogue = 10110907,
          SpeakNpcId = 200045,
          Subtitle = "And let her know that everyone at the Hypnos' House is waiting for her...",
          TalkActionId = {
            [1] = "200045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC484"
        },
        [10110907] = {
          Camera = "262.748047,-120.47818,147.644531,0.000102,-4.196898,153.589691,35.000008,434.590698,false,Manual,3.0",
          ContentJP = "わかった。きっと彼女を助けてみせる。",
          DialogueId = 10110907,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "194FC4AE",
          NextDialogue = 10110908,
          SpeakNpcId = 100001,
          Subtitle = "I will. I'm gonna do everything I can to save her.",
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101109/194FC4AE"
        },
        [10110908] = {
          Camera = "51.148438,0.197876,149.753906,0.000102,-4.600037,179.58815,35.000011,140.0,false,Manual,1.2",
          ContentJP = "もしそれが叶わなくても……彼女が想いに背かないようにだけは……必ず……",
          DialogueId = 10110908,
          ExStoryInfo = "Player",
          FacialId = {
            [1] = "100001:Confident01"
          },
          FinalCamera = "38.595703,0.288055,150.865234,0.000102,-4.600037,179.58815,35.000011,140.0,false,Manual,1.2",
          GUID = "194FC4D8",
          Scripts = [[
PARA{
CameraMoveTo{_delay{2.1},TargetPosition{"-22.845703,1.761353,150.835938,0.000102,-4.600037,179.58815,35.000011,65.552429,false,Manual,4.0"},duration{0}},
CameraMoveTo{_delay{2.2},TargetPosition{"-27.648438,1.795654,150.466797,0.000102,-4.600037,179.58815,35.000011,65.552429,false,Manual,4.0"},duration{2}}
}]],
          SpeakNpcId = 100001,
          Subtitle = "Or at the very least... stop her from doing something she'd regret.",
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/1002/101109/194FC4D8"
        },
        [10111001] = {
          ContentJP = "はぁ……はぁ……はぁ……",
          DialogueId = 10111001,
          Duration = 3,
          GUID = "194FD41A",
          SpeakNpcId = 200006,
          Subtitle = "*panting* Hah... hah... hah...",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD41A"
        },
        [10111002] = {
          ContentJP = "はぁっ……ああ……",
          DialogueId = 10111002,
          Duration = 1,
          GUID = "194FD444",
          SpeakNpcId = 200006,
          Subtitle = "Ah...",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD444"
        },
        [10111003] = {
          ContentJP = "ご……めん……",
          DialogueId = 10111003,
          Duration = 0.5,
          GUID = "194FD46E",
          SpeakNpcId = 200006,
          Subtitle = "I'm... sorr...",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD46E"
        },
        [10111004] = {
          ContentJP = "うぁぁっ——！！",
          DialogueId = 10111004,
          Duration = 0.5,
          ExStoryInfo = "Player",
          GUID = "194FD498",
          SpeakNpcId = 100001,
          Subtitle = "Argh—!! (gasp)",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD498"
        },
        [10111005] = {
          ContentJP = "っ！風が強すぎて……近づけない！",
          DialogueId = 10111005,
          ExStoryInfo = "Player",
          GUID = "194FD499",
          SpeakNpcId = 100001,
          Subtitle = "Resonance isn't working... What should I do?",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD499"
        },
        [10111006] = {
          ContentJP = "くそっ、こいつがまじやべぇ！",
          DialogueId = 10111006,
          Duration = 4.5,
          GUID = "194FD500",
          SpeakNpcId = 200021,
          Subtitle = "Don't waste your energy; Resonance can't stop Deterioration!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD500"
        },
        [10111007] = {
          ContentJP = "サイキは理性を失ってる！",
          DialogueId = 10111007,
          Duration = 2.5,
          GUID = "194FD516",
          SpeakNpcId = 200021,
          Subtitle = "She's lost her mind, get ready to fight!",
          VoiceName = "voice/$Locale$/story/1002/101110/194FD516"
        },
        [10111101] = {
          ContentJP = "サイキ、{性别:僕|私}の声が聞こえる？",
          DialogueId = 10111101,
          ExStoryInfo = "Player",
          GUID = "194FE482",
          NextDialogue = 10111102,
          SpeakNpcId = 100001,
          Subtitle = "Psyche, can you hear me?",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE482"
        },
        [10111102] = {
          ContentJP = "答えて……",
          DialogueId = 10111102,
          ExStoryInfo = "Player",
          GUID = "194FE4AC",
          NextDialogue = 10111103,
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4AC"
        },
        [10111103] = {
          ContentJP = "言っていたじゃない{性别:か|の}……まだやりたいこと、たくさんある{性别:って|んでしょ}……？",
          DialogueId = 10111103,
          ExStoryInfo = "Player",
          GUID = "194FE4D6",
          NextDialogue = 10111104,
          SpeakNpcId = 100001,
          Subtitle = "You said it yourself, there's so much you want to do...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE4D6"
        },
        [10111104] = {
          ContentJP = "ここを離れて、まだ見たことのない場所に行こうよ――",
          DialogueId = 10111104,
          ExStoryInfo = "Player",
          GUID = "194FE500",
          NextDialogue = 10111105,
          SpeakNpcId = 100001,
          Subtitle = "You'll leave Icelake for those unseen places—",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE500"
        },
        [10111105] = {
          ContentJP = "小さな島で……小さな家を建てて……",
          DialogueId = 10111105,
          ExStoryInfo = "Player",
          GUID = "194FE52A",
          NextDialogue = 10111106,
          SpeakNpcId = 100001,
          Subtitle = "...You'll go to a small island, where you can build a few houses by the sea...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE52A"
        },
        [10111106] = {
          ContentJP = "家の周りにたくさんの白い花を植えて……",
          DialogueId = 10111106,
          ExStoryInfo = "Player",
          GUID = "194FE554",
          NextDialogue = 10111107,
          SpeakNpcId = 100001,
          Subtitle = "...and grow white flowers around them...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE554"
        },
        [10111107] = {
          ContentJP = "太陽の下で日よけの帽子をかぶって……アイスレイク城の雪が恋しいなって、友達とおしゃべりする{性别:んだ|の}……",
          DialogueId = 10111107,
          ExStoryInfo = "Player",
          GUID = "194FE57E",
          NextDialogue = 10111108,
          SpeakNpcId = 100001,
          Subtitle = "...Talk about the snow in Icelake with your friends, while shading yourself with a wide-brimmed sunhat...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE57E"
        },
        [10111108] = {
          ContentJP = "ねえ……答えて{性别:くれ|}よ……",
          DialogueId = 10111108,
          ExStoryInfo = "Player",
          GUID = "194FE5A8",
          SpeakNpcId = 100001,
          Subtitle = "Talk to me, Psyche...",
          VoiceName = "voice/$Locale$/story/1002/101111/194FE5A8"
        },
        [10111201] = {
          ContentJP = "サイキ、一緒に帰ろう。",
          DialogueId = 10111201,
          Duration = 4,
          ExStoryInfo = "Player",
          GUID = "194FF4EA",
          SpeakNpcId = 100001,
          Subtitle = "Psyche, I'm here to take you home.",
          VoiceName = "voice/$Locale$/story/1002/101127/1950EB02"
        },
        [10111301] = {
          ContentJP = "ここは……私の家？",
          DialogueId = 10111301,
          GUID = "191B889A",
          SpeakNpcId = 200006,
          Subtitle = "Is this... my home?",
          VoiceName = "voice/$Locale$/story/1002/101113/191B889A"
        },
        [10111401] = {
          ContentJP = "あなた、見て。サイキが笑っているわ。",
          DialogueId = 10111401,
          GUID = "191B88C4",
          NextDialogue = 10111402,
          SpeakNpcId = 200039,
          Subtitle = "Honey, look, Psyche is smiling at us.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B88C4"
        },
        [10111402] = {
          ContentJP = "この子はこの世に生まれてきて……幸せなのか不幸なのか……",
          DialogueId = 10111402,
          GUID = "191B88EE",
          NextDialogue = 10111403,
          SpeakNpcId = 200038,
          Subtitle = "...I wonder whether this child's birth in this world was a blessing or a curse.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B88EE"
        },
        [10111403] = {
          ContentJP = "……そうだね。私たちは祝福されて、生まれてきたわけじゃないから。",
          DialogueId = 10111403,
          GUID = "191B8918",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...Yes, we weren't born with blessings.",
          VoiceName = "voice/$Locale$/story/1002/101114/191B8918"
        },
        [10111501] = {
          ContentJP = "お母さん！今日うちで積み木で遊ぼうって、サイキと約束したんだけど……",
          DialogueId = 10111501,
          GUID = "191BB9D2",
          NextDialogue = 10111502,
          SpeakNpcId = 200040,
          Subtitle = "Mum! I promised Psyche I'd bring her home today to play with blocks...",
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9D2"
        },
        [10111502] = {
          ContentJP = "誰があの子と遊んでいいって言ったの？お母さん何度も言ったでしょうに。あの汚い連中に近づいちゃダメって。邪悪な魔法で殺されたいの？",
          DialogueId = 10111502,
          GUID = "191BB9FC",
          NextDialogue = 10111503,
          SpeakNpcId = 200041,
          Subtitle = "Who says you can play with her? How many times have I told you to stay away from these unclean people? Do you want to be killed by dark magic?",
          VoiceName = "voice/$Locale$/story/1002/101115/191BB9FC"
        },
        [10111503] = {
          ContentJP = "ちっ、上等な積み木だったのに穢れちゃったじゃないの！……もうそれ捨てておきなさいよ！",
          DialogueId = 10111503,
          GUID = "191BBA26",
          SpeakNpcId = 200041,
          Subtitle = "Ugh, now these blocks are all dirty. Throw them away now!",
          VoiceName = "voice/$Locale$/story/1002/101115/191BBA26"
        },
        [10111601] = {
          ContentJP = "あの日、とまどって、悔しくて、一晩中お風呂で血が出るまで体を洗ったんだっけ。",
          DialogueId = 10111601,
          GUID = "191BBA50",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "That day, feeling wronged and confused, I bathed all night until my skin bled.",
          VoiceName = "voice/$Locale$/story/1002/101116/191BBA50"
        },
        [10111701] = {
          ContentJP = "長官様、滅相もございません。うちの娘は本当にいい子で、人様のネックレスを盗むなんて絶対にありえません。まして植木鉢の中に隠すだなんて！",
          DialogueId = 10111701,
          GUID = "191BCA3A",
          NextDialogue = 10111702,
          SpeakNpcId = 200039,
          Subtitle = "So what if he hit your daughter? It was all because your daughter's stuff was an eyesore, wasn't it?",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA3A"
        },
        [10111702] = {
          ContentJP = "言い逃れはやめろ、手癖が悪くないカロンのガキがいるか？",
          DialogueId = 10111702,
          GUID = "191BCA64",
          NextDialogue = 10111703,
          SpeakNpcId = 200043,
          Subtitle = "Exactly. And it was just a pot of flowers, so cut the whimper, you little twerp. Don't get your filthy tears on my uniform.",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA64"
        },
        [10111703] = {
          ContentJP = "こうしよう。盗んでも隠してもいないと言い張るなら、あのガキが自分で、この店の植木鉢をひとつずつ壊して、身の潔白を証明するんだ。",
          DialogueId = 10111703,
          GUID = "191BCA8E",
          NextDialogue = 10111704,
          SpeakNpcId = 200044,
          Subtitle = "What are you still doing here? The Security Bureau isn't a place for your nonsense.",
          VoiceName = "voice/$Locale$/story/1002/101117/191BCA8E"
        },
        [10111704] = {
          ContentJP = "……そう、私たちは生まれながらにして「悪魔の子」だから。こんな扱いを受けるの。",
          DialogueId = 10111704,
          GUID = "191BDAA2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          Subtitle = "...It's all because, we are \"demon's children.\"",
