          CameraBlendCurve = "easeInQuad",
          ContentJP = "この子は<Default note=\"text:エジュウ\">穢獣</>なんかじゃないし、兵士さんが処分するゴミでもない。",
          DialogueId = 10113029,
          ExStoryInfo = "Player",
          FacialId = {
