        [10113030] = {
          Camera = "-313.24707,-289.5,102.341797,0.000199,0.897494,42.804501,30.0,516.200134,false,Manual,3.5",
          ContentJP = "彼女の名前はサイキ、アイスレイク城の住民だった、今夜、彼女は「穢蝕」から街の人たち全員を守った{性别:んだ|の}。",
          DialogueId = 10113030,
          ExStoryInfo = "Player",
          GUID = "1951202D",
          NextDialogue = 10113031,
          SpeakNpcId = 100001,
          Subtitle = "Her name was Psyche. She was a citizen of Icelake. Tonight, she protected everyone in the city from Deterioration.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/101130/1951202D"
        },
        [10113031] = {
          Camera = "-71.211914,-137.410156,141.410156,5.00005,-0.600189,43.438988,35.0,54.652218,false,Manual,8.0",
          ContentJP = "誰も近寄らないで。{性别:僕|私}がサイキをきちんと弔ってあげる{性别:んだ|の}。",
