          },
          FinalCamera = "-73.801758,-139.859375,141.443359,5.000083,-0.600189,43.438965,35.0,58.003056,false,Manual,8.0",
          GUID = "1951202E",
          NextDialogue = 10113032,
          Scripts = [[
