        [10118203] = {
          Camera = "-845.377014,-25.232204,629.145264,0.000027,-33.600269,4.611965,28.874323,1077.120361,false,Manual,4.2",
          ContentJP = "君が本当に困ってるなら助けてあげるけどさ。勝手に持っていっちゃう子にはお仕置きだよ！",
          DialogueId = 10118203,
          FacialId = {
            [1] = "200011:Angry01"
          },
          GUID = "195471AE",
          SpeakNpcId = 200011,
          Subtitle = "If you're hard up, I can help you. But you can't just grab money of people — that'll earn you a whack on the head with my shovel!",
          TalkActionId = {
            [1] = "200011:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/101182/195471AE"
        },
        [10118204] = {
          ContentJP = "（青年は言い返す言葉がみつからないようだ。苛ついた様子で屋根から飛び降りた）",
          DialogueId = 10118204,
          DisableMouth = 1,
          GUID = "195471D8",
          VoiceName = "voice/$Locale$/story/1002/101182/195471D8"
        },
        [10118301] = {
          ContentJP = "またまた見失っちゃった？あいつはゴーストか？！",
          DialogueId = 10118301,
          Duration = 3,
          GUID = "195481C2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10118303,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101183/195481C2"
        },
        [10118302] = {
          ContentJP = "ううん……ほら見て。このマンホール、動かした跡がある。",
          DialogueId = 10118302,
          Duration = 3,
          GUID = "195481EC",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10118303,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101183/195481EC"
        },
        [10118303] = {
          ContentJP = "よって私の推理は……あいつは下水道に逃げ込んだんだ！",
          DialogueId = 10118303,
          Duration = 3,
          GUID = "19548216",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101183/19548216"
        },
        [10118401] = {
          ContentJP = "うわ……水が深すぎて渡れないよ。あいつはどうやって渡ったのかな？",
          DialogueId = 10118401,
          Duration = 3,
          GUID = "1954922A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10118402,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101184/1954922A"
        },
        [10118402] = {
          ContentJP = "慌てない慌てない。こういう時は「物言わぬ探偵」の情報網の出番だよ。",
          DialogueId = 10118402,
          Duration = 3,
          GUID = "19549254",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10118403,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101184/19549254"
        },
        [10118403] = {
          ContentJP = "小型ゴミ箱8号で見つけた『下水道メンテナンスマニュアル』に書いてあったんだけど、ここの水位は調節できるんだって。水門がたしかこの辺にあったはず。",
          DialogueId = 10118403,
          Duration = 3,
          GUID = "1954927E",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101184/1954927E"
        },
        [10118501] = {
          ContentJP = "わお！本当に排水の仕掛けがあったよ。ゴミ拾いの姫様☆物言わぬ探偵、やるじゃん！",
          DialogueId = 10118501,
          Duration = 3,
          GUID = "1954A292",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10118502,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A292"
        },
        [10118502] = {
          ContentJP = "ぷえ……お願いだから、前半のあだ名は省略して……",
          DialogueId = 10118502,
          Duration = 3,
          GUID = "1954A2BC",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10118503,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A2BC"
        },
        [10118503] = {
          ContentJP = "水位が少し下がったね。他にも似たような仕掛けがないか探してみよう。",
          DialogueId = 10118503,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1954A2E6",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101185/1954A2E6"
        },
        [10118601] = {
          ContentJP = "見て、下の方に道があるよ！",
          DialogueId = 10118601,
          Duration = 3,
          GUID = "1954B2FA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B2FA"
        },
        [10118602] = {
          ContentJP = "あっそうだ。これも『下水道メンテナンスマニュアル』に書いてあったんだけど、下水道にはあったくて湿った環境を好む穢獣が住みつくことがあるって。",
          DialogueId = 10118602,
          Duration = 3,
          GUID = "1954B324",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B324"
        },
        [10118603] = {
          ContentJP = "犬とか猫くらいの大きさしかない小型の<Default note=\"text:エジュウ\">穢獣</>だけど、群れで行動するとちょっと厄介なんだって。",
          DialogueId = 10118603,
          Duration = 3,
          GUID = "1954B34E",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10118604,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B34E"
        },
        [10118604] = {
          ContentJP = "この先に進むならしっかり準備を整えないとね！",
          DialogueId = 10118604,
          Duration = 3,
          GUID = "1954B378",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101186/1954B378"
        },
        [10118701] = {
          ContentJP = "そこの君！いい子だから止まりやがれーー！",
          DialogueId = 10118701,
          Duration = 3,
          GUID = "1954C362",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          NextDialogue = 10118702,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101187/1954C362"
        },
        [10118702] = {
          ContentJP = "はあ……はあ……足の長いみなさーん……ちょっと待って……",
          DialogueId = 10118702,
          Duration = 3,
          GUID = "1954C38C",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101187/1954C38C"
        },
        [10118801] = {
          ContentJP = "ゴホゴホ……く、苦しい……卑怯者めーｰ",
