          Duration = 3,
          GUID = "1954D3CA",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101188/1954D3CA"
        },
        [10118901] = {
