        },
        [10119001] = {
          ContentJP = "ん？なんか飛んできたかも……",
          DialogueId = 10119001,
          Duration = 3,
          GUID = "1954F49A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10119002,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101190/1954F49A"
        },
        [10119002] = {
          ContentJP = "ほぎゃ……いだだだだ！石だ！",
          DialogueId = 10119002,
          Duration = 3,
          GUID = "1954F4C4",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101190/1954F4C4"
        },
        [10119101] = {
          ContentJP = "あいつ、高いところにいるぞ。今度はこの魔王様が華麗に石を避けて――ほぎゃっ！",
          DialogueId = 10119101,
          Duration = 3,
          GUID = "19550502",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10119102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101191/19550502"
        },
        [10119102] = {
          ContentJP = "まーったく……石ばかりなげてさぁ、お猿さんみたいだね！",
