          Duration = 3,
          GUID = "1955052C",
          GuideFacialId = "Angry",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101191/1955052C"
        },
        [10119201] = {
          ContentJP = "この足跡……まだ新しいね。濡れた足跡をたどっていこう。",
          DialogueId = 10119201,
          Duration = 3,
          GUID = "1955156A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101192/1955156A"
        },
        [10119301] = {
          ContentJP = "これって……血の跡？まだ新しいみたい……あいつケガしたのかな？",
          DialogueId = 10119301,
          Duration = 3,
          GUID = "195525D2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10122001,
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101193/195525D2"
        },
        [10119302] = {
          ContentJP = "何かに襲われたのかも……慎重に進もう。",
