          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195525FC",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101193/195525FC"
        },
        [10119401] = {
          ContentJP = "やっぱり……あいつは<Default note=\"text:エジュウ\">穢獣</>の群れを刺激して、{性别:襲われたんだ。|襲われたのね。}",
