          VoiceName = "voice/$Locale$/story/1002/101195/195546A2"
        },
        [10119503] = {
          ContentJP = "{nickname}ちゃん、手伝って！捕まえちゃおう！",
          DialogueId = 10119503,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195546CC",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200011,
          VoiceName = "voice/$Locale$/story/1002/101195/195546CC"
        },
        [10119601] = {
          ContentJP = "この扉は壊れてないけど、鍵がかかってるみたい……",
          DialogueId = 10119601,
          Duration = 3,
          GUID = "1955570A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10119602,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101196/1955570A"
        },
        [10119602] = {
          ContentJP = "ぐぬぬ……もう廃坑になってるのに、どうして防犯対策が必要なのさ！",
          DialogueId = 10119602,
          Duration = 3,
          GUID = "19555734",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10119603,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101196/19555734"
        },
        [10119603] = {
          ContentJP = "……誰かが迷い込んで、<Default note=\"text:エジュウ\">穢獣</>に襲われないようにするため、とか？",
          DialogueId = 10119603,
          Duration = 3,
          GUID = "1955575E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10119604,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101196/1955575E"
        },
        [10119604] = {
          ContentJP = "この近くを探してみようか。運がよければ鍵とか何か見つかるかも。",
