          Duration = 3,
          GUID = "19555788",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101196/19555788"
        },
        [10119701] = {
          ContentJP = "わぁお……坑道にこんな素敵なものがあるなんて。マギーが知ったら飛びあがって喜ぶね！",
          DialogueId = 10119701,
          Duration = 3,
          GUID = "19556772",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10119702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101197/19556772"
        },
        [10119702] = {
          ContentJP = "でもこの鉱石はとっても硬そう。マギーさんのスコップが折れちゃうかも。",
          DialogueId = 10119702,
          Duration = 3,
          GUID = "1955679C",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101197/1955679C"
        },
        [10119801] = {
          ContentJP = "{nickname}、私にも手伝わせて！",
          DialogueId = 10119801,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "195577DA",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10119802,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/195577DA"
        },
        [10119802] = {
          ContentJP = "大丈夫。それよりサイキ、「魔王様」が見てない隙に、ふたりで山分けするのはどう？",
          DialogueId = 10119802,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19557804",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10119803,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101198/19557804"
        },
        [10119803] = {
          ContentJP = "いいの。{nickname}が持ってて。きれいな服とか買えるでしょ。私は……おカネがあっても使い道がないから。",
          DialogueId = 10119803,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955782E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101198/1955782E"
        },
        [10119901] = {
          ContentJP = "これ、なんだろう？",
          DialogueId = 10119901,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "19558842",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101199/19558842"
        },
        [10120001] = {
          ContentJP = "おおお……扉を開く仕掛けがこんなところに！うまく隠してあったね。",
          DialogueId = 10120001,
          Duration = 3,
          GUID = "195598AA",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101200/195598AA"
        },
        [10120101] = {
          ContentJP = "え、え、えじゅ……<Default note=\"text:エジュウ\">穢獣</>がうようよだああ……",
          DialogueId = 10120101,
          Duration = 3,
          GUID = "1955A912",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A912"
        },
        [10120102] = {
          ContentJP = "{性别:僕|私}の脚から降りてよ、スノウ。これじゃ身動きできない。先にアイスレイク城に引き返してもいいよ、からかったりしないから。",
          DialogueId = 10120102,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A93C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 10120103,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A93C"
        },
        [10120103] = {
          ContentJP = "だだだだ誰が、ひひひ引き返すって。ぼぼぼぼ冒険しないと……みみみみ満たされない人生になっちゃうんだぞ！",
          DialogueId = 10120103,
          Duration = 3,
          GUID = "1955A966",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10120104,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A966"
        },
        [10120104] = {
          ContentJP = "そうだね。じゃあ私も、{nickname}と魔王様と一緒に、人生をもっと満たしちゃおうかな。",
          DialogueId = 10120104,
          Duration = 3,
          ExStoryInfo = "Player",
          GUID = "1955A990",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 10120105,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101201/1955A990"
        },
        [10120105] = {
          ContentJP = "ここまで私、足手まといになってないよね？……だからこの先もきっと大丈夫！",
