          GUID = "1955DA74",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101204/1955DA74"
        },
        [10120501] = {
          ContentJP = "ちょっと、そっちは違うよ。街へ行くんじゃなかったの？",
