          VoiceName = "voice/$Locale$/story/1002/101225/195732D2"
        },
        [10122601] = {
          ContentJP = "どうやら{nickname}のことが気に入ったみたいだね。",
          DialogueId = 10122601,
          GUID = "1957433A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10122602,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101226/1957433A"
        },
        [10122602] = {
          ContentJP = "可愛い！スノウにも撫でさせて！",
          DialogueId = 10122602,
          GUID = "19574364",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101226/19574364"
        },
        [10122701] = {
          ContentJP = "「この先、大量の財宝を奪った<Default note=\"text:エジュウ\">穢獣</>がいる。くれぐれも近づくな！」っと――これでよし！",
          DialogueId = 10122701,
          GUID = "195753A2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10122702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101227/195753A2"
        },
        [10122702] = {
          ContentJP = "なんだろう、すごく見に行ってみたくなる……",
          DialogueId = 10122702,
          GUID = "195753CC",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101227/195753CC"
        },
        [10122801] = {
          ContentJP = "ん？あの黄色いキラキラしてる「棘」って、もしかして……",
          DialogueId = 10122801,
          GUID = "1957640A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10122802,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101228/1957640A"
        },
        [10122802] = {
          ContentJP = "違うよ。群星のジェムは、星の形をした<H>紫色</>のクリスタルだって、ヘンリックおじさんが言ってたから。",
          DialogueId = 10122802,
          GUID = "19576434",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101228/19576434"
        },
        [10122901] = {
          ContentJP = "危ない！",
          DialogueId = 10122901,
          GUID = "19577472",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          NextDialogue = 10122902,
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101229/19577472"
        },
        [10122902] = {
          ContentJP = "ふぅ、怪我しなくてよかった……あ！道があるよ！",
          DialogueId = 10122902,
          GUID = "1957749C",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 200006,
          VoiceName = "voice/$Locale$/story/1002/101229/1957749C"
        },
        [10123001] = {
          ContentJP = "そうだ、道中の街灯はお前が灯したんだろ？後から来る月狩り人の代わりに礼を言うぜ。",
          DialogueId = 10123001,
          GUID = "195784DA",
          NextDialogue = 10123002,
          VoiceName = "voice/$Locale$/story/1002/101230/195784DA"
        },
        [10123002] = {
          ContentJP = "これらは、ほんのお礼だ。",
          DialogueId = 10123002,
          GUID = "19578504",
          VoiceName = "voice/$Locale$/story/1002/101230/19578504"
        },
        [10123101] = {
          ContentJP = "下僕、はやくはやく！",
          DialogueId = 10123101,
          GUID = "19579542",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 10123102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101231/19579542"
        },
        [10123102] = {
          ContentJP = "しー、静かに。気づかれたらどうするの……",
          DialogueId = 10123102,
          GUID = "1957956C",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101231/1957956C"
        },
        [10123201] = {
          ContentJP = "ったく、受取人はまだか？何時だと思ってるんだ……",
          DialogueId = 10123201,
          GUID = "1957A5AA",
          VoiceName = "voice/$Locale$/story/1002/101232/1957A5AA"
        },
        [10123301] = {
          ContentJP = "待って、近すぎる！",
          DialogueId = 10123301,
          GUID = "1957B612",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101233/1957B612"
        },
        [10123401] = {
          ContentJP = "お前たちか？こそこそ俺の後をつけて、なんのつもりだ？",
          DialogueId = 10123401,
          GUID = "1957C67A",
          IsBlack = 1,
          NextDialogue = 10123402,
          SpeakNpcId = 200005,
          VoiceName = "voice/$Locale$/story/1002/101234/1957C67A"
        },
        [10123402] = {
          ContentJP = "ち、違うよ！ちょうど酒場に帰ろうと思って、通りかかっただけ！",
          DialogueId = 10123402,
          GUID = "1957C6A4",
          IsBlack = 1,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101234/1957C6A4"
        },
        [10123403] = {
          ContentJP = "まずい、ヘンリックに見つかった！",
          DialogueId = 10123403,
          GUID = "10123403.0",
          IsBlack = 1
        },
        [10123404] = {
          Content = "恩里克消失在了视线外……似乎是跟丢了。",
          DialogueId = 10123404,
          GUID = "1957C6A5"
        },
        [10123405] = {
          Content = "恩里克走进了一间花店，你们决定在一旁的咖啡厅稍作等待。",
          DialogueId = 10123405,
          GUID = "1957C6A6"
        },
        [10123501] = {
          ContentJP = "並んでゆっくり歩くのよ――",
          DialogueId = 10123501,
          GUID = "1957D6E2",
          NextDialogue = 10123502,
          VoiceName = "voice/$Locale$/story/1002/101235/1957D6E2"
        },
        [10123502] = {
          ContentJP = "手をつないでゆっくり歩くのよ――",
          DialogueId = 10123502,
          GUID = "1957D70C",
          VoiceName = "voice/$Locale$/story/1002/101235/1957D70C"
        },
        [10123601] = {
          ContentJP = "（ヘンリックさんの動きが止まった。隠れる場所を探さないと……）",
          DialogueId = 10123601,
          DisableMouth = 1,
          GUID = "1957E74A",
          GuideFacialId = "Afraid",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101236/1957E74A"
        },
        [10123602] = {
          ContentJP = "また壊れたのか！？",
          DialogueId = 10123602,
          GUID = "1957E774",
          VoiceName = "voice/$Locale$/story/1002/101236/1957E774"
        },
        [10123701] = {
          ContentJP = "そうだ！このデカブツの中に隠れれば、気づかれずに尾行できるぞ！",
          DialogueId = 10123701,
          GUID = "1957F7B2",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          NextDialogue = 10123702,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101237/1957F7B2"
        },
        [10123702] = {
          ContentJP = "じゃあ聞くけど、見張りが見てる前でどうやって中に入るの？",
          DialogueId = 10123702,
          GUID = "1957F7DC",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 10123703,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101237/1957F7DC"
        },
        [10123703] = {
          ContentJP = "う、それは……あ！ヘンリックが歩き出した！はやくはやく！",
          DialogueId = 10123703,
          GUID = "1957F806",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10123501,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101237/1957F806"
        },
        [10123801] = {
          ContentJP = "「フローリスト・リメンブランス」……花屋の名前かな。",
