          GUID = "1958081A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 10123802,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101238/1958081A"
        },
        [10123802] = {
