        [10123905] = {
          Camera = "-161.023438,20.044434,118.390259,0.000759,-2.805302,-37.617157,35.0,267.49585,false,Manual,3.0",
          ContentJP = "行こう。",
          DialogueId = 10123905,
          GUID = "1958192A",
          LookAt = {
            [1] = "100001:n(200002)"
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101239/1958192A"
        },
        [10123906] = {
          ContentJP = "うっ、ヘンリックを見失ってしまった……",
          DialogueId = 10123906,
          GUID = "19581954",
          NextDialogue = 10123907,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101239/19581954"
        },
        [10123907] = {
          ContentJP = "花屋の店主に聞いてみよう。",
          DialogueId = 10123907,
          GUID = "19581955",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101239/19581955"
        },
        [10124000] = {
          ContentJP = "十分後。",
          DialogueId = 10124000,
          GUID = "10124000.0",
          IsBlack = 1
        },
        [10124001] = {
          ContentJP = "あのー！さっき、そこで銀貨を拾ったんだけど、これを落としたおじさんに届けたくて。その人がどこに――",
          DialogueId = 10124001,
          GUID = "195828EA",
          NextDialogue = 10124002,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101240/195828EA"
        },
        [10124002] = {
          ContentJP = "って！おばさん、何で泣いてるんだ！？あいつに何か嫌なことでも言われたのか？",
          DialogueId = 10124002,
          GUID = "19582914",
          NextDialogue = 10124003,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101240/19582914"
        },
        [10124003] = {
          ContentJP = "え？いいえ、違うの。目にムラサキツユクサの花粉が入ったのよ。心配してくれてありがとうね。",
          DialogueId = 10124003,
          GUID = "1958293E",
          NextDialogue = 10124004,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101240/1958293E"
        },
        [10124004] = {
          ContentJP = "さっきの白い服を着た男性なら、たぶん……北東にある湖に行ったと思うわ。",
          DialogueId = 10124004,
          GUID = "19582968",
          NextDialogue = 10124005,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101240/19582968"
        },
        [10124005] = {
          ContentJP = "分かった。ありがとう。",
          DialogueId = 10124005,
          GUID = "19582992",
          NextDialogue = 10124006,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101240/19582992"
        },
        [10124006] = {
          ContentJP = "ちょっと待って。あなたは……",
          DialogueId = 10124006,
          GUID = "195829BC",
          NextDialogue = 10124007,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101240/195829BC"
        },
        [10124007] = {
          ContentJP = "{性别:僕|私}？",
          DialogueId = 10124007,
          GUID = "195829E6",
          NextDialogue = 10124008,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101240/195829E6"
        },
        [10124008] = {
          ContentJP = "……いいえ、人違いだったみたい。ごめんなさいね、よかったらこれを受け取って。",
          DialogueId = 10124008,
          GUID = "19582A10",
          NextDialogue = 10124101,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101240/19582A10"
        },
        [10124101] = {
          ContentJP = "これ……くれるの？",
          DialogueId = 10124101,
          GUID = "19583952",
          NextDialogue = 10124102,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101241/19583952"
        },
        [10124102] = {
          ContentJP = "ええ。あなたもルビーのような綺麗な目をしているから。きっとこの花が似合うわ。よい一日を。",
          DialogueId = 10124102,
          GUID = "1958397C",
          NextDialogue = 10124103,
          SpeakNpcName = "UI_Npc_Name_FlowerShoper",
          VoiceName = "voice/$Locale$/story/1002/101241/1958397C"
        },
        [10124103] = {
          ContentJP = "ありがとう。",
          DialogueId = 10124103,
          GUID = "195839A6",
          NextDialogue = 10124104,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1002/101241/195839A6"
        },
        [10124104] = {
          ContentJP = "何もしてないのにプレゼントをもらうとは、我が下僕の魅力は底が知れないな！",
          DialogueId = 10124104,
          GUID = "195839D0",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101241/195839D0"
        },
        [10124201] = {
          ContentJP = "この湖だな……あ、いた！",
          DialogueId = 10124201,
          GUID = "195849BA",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1002/101242/195849BA"
        },
        [10124301] = {
          ContentJP = "きっとあれがあいつの秘密なんだよ！でも、こんなに冷たい水、カロン族でも潜るのはキツい……",
          DialogueId = 10124301,
          GUID = "19585A22",
          NextDialogue = 10124302,
          VoiceName = "voice/$Locale$/story/1002/101243/19585A22"
        },
        [10124302] = {
          ContentJP = "しかたない、ここは万能なるルーナ族のスノウが一肌脱いで――って、下僕よ、何をしてるんだ……？",
          DialogueId = 10124302,
          GUID = "19585A4C",
          NextDialogue = 10124303,
          VoiceName = "voice/$Locale$/story/1002/101243/19585A4C"
        },
        [10124303] = {
          ContentJP = "こうやって釣り竿を改造すれば……よし、できた。",
          DialogueId = 10124303,
          GUID = "19585A76",
          NextDialogue = 10124304,
          VoiceName = "voice/$Locale$/story/1002/101243/19585A76"
        },
        [10124304] = {
          ContentJP = "まかせて。たとえサメだろうと、{性别:僕|私}に釣り上げられないものはないから。",
          DialogueId = 10124304,
          GUID = "19585AA0",
          VoiceName = "voice/$Locale$/story/1002/101243/19585AA0"
        },
        [10124401] = {
          ContentJP = "下僕よ！もしやお前は。エリュシオンの海産物を統べる神なのか！？",
          DialogueId = 10124401,
          GUID = "19586A8A",
          NextDialogue = 10124402,
          VoiceName = "voice/$Locale$/story/1002/101244/19586A8A"
        },
        [10124402] = {
          ContentJP = "積み上げられた石のそばに白い花束が置かれている……何か特別な意味があるようだ。",
          DialogueId = 10124402,
          GUID = "19586AB4",
          NextDialogue = 10124403,
          VoiceName = "voice/$Locale$/story/1002/101244/19586AB4"
        },
        [10124403] = {
          ContentJP = "見て見て。この花、ヘンリックが買ったのと同じじゃない？",
          DialogueId = 10124403,
          GUID = "19586ADE",
          VoiceName = "voice/$Locale$/story/1002/101244/19586ADE"
        },
