        [11010221] = {
          ContentJP = "っ……ダフネ先生、これで任務完了……でいいんですよね？",
          DialogueId = 11010221,
          Duration = 3,
          GUID = "1B901C62",
          SpeakNpcId = 110019,
          Subtitle = "Hssss... Dr Daphne, we've completed our mission, right?",
