          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EE8C"
        },
        [11011503] = {
          ContentJP = "これで要塞内に備わっていた防衛兵器の大半が止まったはずだ。他の小隊も少しは楽になるだろうさ。",
          DialogueId = 11011503,
          Duration = 3,
          GUID = "1B90EEB6",
          NextDialogue = 11011504,
          Scripts = [[
PARA{
PlayAnimation{_delay{1},ActorId{110022},AnimationId{"Talk02_End"},Duration{1}},
PlayAnimation{_delay{3},ActorId{110010},AnimationId{"Think_Start"},Duration{1}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "Okay, most of the defensive weapons within the fortress have been disabled. The rest of our squads should have an easier time.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EEB6"
        },
        [11011504] = {
          Camera = "25.622559,-213.152344,121.84137,0.000183,-0.799159,111.990997,28.000006,100000.0,false,DoNotOverride,2.8",
          ContentJP = "支障はないか？動けるなら即座に出発して、他の救援に——待て、通信だ。",
          DialogueId = 11011504,
          Duration = 3,
          GUID = "1B90EEE0",
          NextDialogue = 11011505,
          Scripts = [[
PARA{
LookAt{_delay{5},LookAtDescription{"110010:n(110010)"}},
PlayAnimation{_delay{6},ActorId{110010},AnimationId{"Call_Start"},Duration{0}},
TurnTo{_delay{8},TurnToDescription{"110010:p(-100)"},AnimationId{"Call_Rotation"}},
PlayAnimation{_delay{3},ActorId{110022},AnimationId{"AgreeHead"},Duration{0}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "So can you continue? Let's go if you can, we've got other comrades to rescue— Hold on, new communication coming in.",
          TalkActionId = {
