        },
        [11011506] = {
          ContentJP = "アヴァールよ、今どこにいる？",
          DialogueId = 11011506,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B90EF34",
          NextDialogue = 11011507,
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "Avar, where are you?",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EF34"
        },
        [11011507] = {
          Camera = "-206.013672,0.410156,134.678345,0.000218,-0.399088,4.196889,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "…………",
          DialogueId = 11011507,
          Duration = 3,
          FinalCamera = "-214.72998,-0.222656,134.739075,0.000218,-0.399088,4.196893,35.000011,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90EF5E",
          NextDialogue = 11011508,
          SpeakNpcId = 110010,
          Subtitle = "...",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EF5E"
        },
        [11011508] = {
          ContentJP = "本日のヒュペリアの空模様は。",
          DialogueId = 11011508,
          Duration = 3,
          GUID = "1B90EF88",
          NextDialogue = 11011509,
          SpeakNpcId = 110010,
          Subtitle = "The weather in Hyperborea today.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EF88"
        },
        [11011509] = {
          ContentJP = "何を？総司令官の声も忘れたのかね？",
          DialogueId = 11011509,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          GUID = "1B90EFB2",
          NextDialogue = 11011510,
          SnapShot = "TELEPHONE",
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          Subtitle = "What's your problem? Can't even recognise the chief commander's voice?",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EFB2"
        },
        [11011510] = {
          ContentJP = "空模様は。",
          DialogueId = 11011510,
          Duration = 3,
          GUID = "1B90EFDC",
          NextDialogue = 11011511,
          SpeakNpcId = 110010,
          Subtitle = "Weather.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90EFDC"
        },
        [11011511] = {
          Camera = "-2040.53125,-6.380859,581.50824,0.000221,-14.198993,-1.000641,28.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "今夜は雨だ雨。まったく君の頭の硬さは大理石の彫像以上で扱いに困る。ほら、さっさと報告したまえ。君たち小隊の状況は？",
          DialogueId = 11011511,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "-2039.224609,68.435547,581.508057,0.000221,-14.198993,-1.000641,28.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F006",
          NextDialogue = 11011512,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "It's raining tonight. Tsk, I've seen marble sculptures in the gallery with more flexibility than your mind. Now, report on your squad.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F006"
        },
        [11011512] = {
          ContentJP = "ありがたいことに「<Default note=\"text:スノーウルフ\">雪狼</>」「<Default note=\"text:グリフィン\">鷲獅子</>」2部隊ともども先遣隊は全滅に至ってません。聡明なご決断のお陰ですな。それで何用で？また何か新しいご助言でも？",
          DialogueId = 11011512,
          Duration = 3,
          GUID = "1B90F030",
          NextDialogue = 11011513,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"-192.069824,-58.894531,124.695801,0.0,5.00006,44.395386,28.000006,100000.0,false,DoNotOverride,2.8"},duration{0}},
CameraMoveTo{TargetPosition{"-189.639648,-61.367188,124.695801,0.0,5.00006,44.395386,28.000006,100000.0,false,DoNotOverride,2.8"},duration{15}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "Thanks to your \"brilliant\" decision-making, the Snow Wolves and the Griffins haven't been completely annihilated yet. What, got any new insight?",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F030"
        },
        [11011513] = {
          Camera = "-488.78418,56.402344,85.289307,0.000219,2.801054,-12.005161,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "舐めた態度はやめてもらおうか。現状の結果を恥じていないのかね君は？",
          DialogueId = 11011513,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FacialId = {
            [1] = "110022:Angry01"
          },
          FinalCamera = "-486.660645,66.390625,85.289307,0.000219,2.801054,-12.005161,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F05A",
          NextDialogue = 11011514,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Enough with your snide attitude. You should be ashamed of how this battle has turned out.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F05A"
        },
        [11011514] = {
          Camera = "-208.61084,-34.998047,124.695801,0.0,3.399972,25.594477,28.000006,100000.0,false,DoNotOverride,2.8",
          ContentJP = "こちらとしても敬意を払って話しているつもりですがね。秘密保持と作戦計画においてそっちが頼りない現状なんとも。兵士たちも冷たい鋼板の上で横たわるのでなく、さっさと中央制御室で祝賀会を開きたいでしょうに。",
          DialogueId = 11011514,
          Duration = 3,
          FinalCamera = "-200.800781,-31.255859,125.210022,0.000001,3.399972,25.59412,28.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F084",
          NextDialogue = 11011515,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{9},TargetPosition{"-185.694336,-6.542969,120.360779,0.000021,-4.200409,-22.200655,28.000006,100000.0,false,Manual,5.0"},duration{0}},
CameraMoveTo{TargetPosition{"-187.672852,-11.392578,120.360779,0.000021,-4.200409,-22.200655,28.000006,100000.0,false,Manual,5.0"},duration{8}}
}]],
          SpeakNpcId = 110010,
          Subtitle = "I would like to achieve glory, sir. If you exercised proper secrecy and came up with a more credible plan, our soldiers would be popping champagne bottles in the central control room at this very moment instead of waiting for body bags.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F084"
        },
        [11011515] = {
          Camera = "29.431152,-206.160156,126.804016,0.000153,-2.399432,116.400375,30.000002,100000.0,false,DoNotOverride,7.0",
          ContentJP = "アヴァール・ハードランド、今一度だけ警告してやる——貴様、口の利き方には気をつけろよ。",
          DialogueId = 11011515,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "32.746094,-204.517578,126.804016,0.000153,-2.399432,116.400375,30.000002,100000.0,false,DoNotOverride,7.0",
          GUID = "1B90F0AE",
          NextDialogue = 11011516,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Avar Hrodland, I'm warning you — Watch your tone when speaking to your superior!",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F0AE"
        },
        [11011516] = {
          Camera = "-208.043457,19.533203,102.896729,0.0,19.597855,-8.78466,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "アンソニー・フルヴィス、こちらからも警告してやる。我々兵士たちの命を玩具と思うなよ。",
          DialogueId = 11011516,
          Duration = 3,
          FinalCamera = "-199.971191,18.289062,105.804749,0.0,19.597855,-8.78466,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F0D8",
          NextDialogue = 11011517,
          SpeakNpcId = 110010,
          Subtitle = "Antonius Fulvis, I'm also warning you — Stop wasting the lives of my comrades.",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F0D8"
        },
        [11011517] = {
          Camera = "-563.553223,-958.021484,11.975342,0.000025,6.998976,54.007206,23.560806,1033.296143,false,Manual,1.2",
          ContentJP = "戯言に付き合ってる暇はないのだが。さっさと強襲任務の現状を報告しろ。",
          DialogueId = 11011517,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          Duration = 3,
          FinalCamera = "-581.693359,-944.851562,11.975342,0.000025,6.998976,54.007206,23.560806,1046.946777,false,Manual,1.2",
          GUID = "1B90F102",
          NextDialogue = 11011518,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "I have no time for this right now. I am here to demand a progress update on the mission.",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F102"
        },
        [11011518] = {
          ContentJP = "先遣隊は2部隊とも伏兵に遭遇して多大な損失を被った。我々は先んじて連絡を絶った兵士の捜索に当たり、製造エリアで一時的な治療を行いながら支援を待っている。",
          DialogueId = 11011518,
          Duration = 3,
          GUID = "1B90F12C",
          NextDialogue = 11011519,
          SpeakNpcId = 110010,
          Subtitle = "The two squads have been ambushed and suffered heavy losses. I'm preparing to search and rescue the missing soldiers first, then regroup in the processing area, waiting for your support.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F12C"
        },
        [11011519] = {
          Camera = "-270.909668,32.457031,122.689575,0.000147,-2.000118,-13.794167,19.449591,100000.0,false,DoNotOverride,2.8",
          ContentJP = "君たちの任務は迅速な突撃であろう？何を勝手に作戦を中止している？",
          DialogueId = 11011519,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "-269.342773,38.851562,122.689575,0.000147,-2.000118,-13.794167,19.449591,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F156",
          NextDialogue = 11011520,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Your mission is a rapid infiltration assault. No field officer of mine is permitted to make their own bloody choices.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F156"
        },
        [11011520] = {
          Camera = "29.431152,-206.160156,126.804016,0.000153,-2.399432,116.400436,30.000002,100000.0,false,Manual,7.0",
          ContentJP = "既存の作戦計画から逸脱すれば要塞内の警戒が厳重になる一方だ。命令を改めようではないか。中央制御室に計画通り攻撃を実行せよ。",
          DialogueId = 11011520,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "29.431152,-206.160156,126.804016,0.000153,-2.399432,116.400436,30.000002,100000.0,false,Manual,7.0",
          GUID = "1B90F180",
          NextDialogue = 11011521,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{6},TargetPosition{"-210.144531,17.427734,117.606079,0.000155,-1.599268,-27.397827,35.0,100000.0,false,Manual,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"-179.064941,1.080078,116.625427,0.000155,-1.599268,-29.197777,35.0,100000.0,false,Manual,10.0"},duration{8}}
}]],
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Straying off the planned course of action will only alert the entire fortress. I order you to stick to the plan and launch a direct assault on the central control room.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F180"
        },
        [11011521] = {
          Camera = "-283.299316,-15.771484,105.371338,0.000157,8.200632,8.003107,35.0,100000.0,false,DoNotOverride,10.0",
          ContentJP = "敵に気づかれるだ？そっちこそ戯言はやめろ！とっくの昔に警戒などされている！伏兵に遭遇したと言ったろう！8割だ！8割以上の損失でまだ足りないとほざくか！？",
          DialogueId = 11011521,
          FinalCamera = "-274.317871,-14.511719,106.678589,0.000157,8.200632,8.003121,35.0,100000.0,false,DoNotOverride,10.0",
          GUID = "1B90F1AA",
          NextDialogue = 11011522,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{2},TargetPosition{"-186.463867,18.255859,110.615173,0.000163,22.600508,-5.198188,35.000008,62.163586,false,Manual,10.0"},duration{0}},
SEQ{
CameraMoveTo{_delay{6.5},TargetPosition{"-2030.179199,-717.564453,858.498047,0.000213,-19.7997,18.80571,30.0,62.163586,false,DoNotOverride,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"-2227.331543,-784.722656,933.480164,0.000214,-19.7997,18.805719,30.0,62.163586,false,DoNotOverride,10.0"},duration{0.1}}
}
}]],
          SpeakNpcId = 110010,
          Subtitle = "Are you even listening to yourself? Alert the fortress? They're already in ambush positions, waiting to wipe us all out! We've sustained eighty percent casualties — eight zero! Isn't that enough for you!?",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F1AA"
        },
        [11011522] = {
          Camera = "-2227.331543,-784.722656,933.480164,0.000214,-19.7997,18.805719,30.0,62.163586,false,DoNotOverride,10.0",
          ContentJP = "損失！損失！損失！口を開けば不愉快な台詞を吐くばかりだな貴様は！貴様らの行動で遅れが発生していることを自覚したまえよ！",
          DialogueId = 11011522,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          GUID = "1B90F1D4",
          NextDialogue = 11011523,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{5},TargetPosition{"-127.570801,-135.820312,123.863464,0.000167,-1.599453,2.200026,35.0,62.163586,false,DoNotOverride,10.0"},duration{0}},
CameraMoveTo{TargetPosition{"-127.746582,-131.263672,123.863464,0.000167,-1.599453,2.200026,35.0,62.163586,false,DoNotOverride,10.0"},duration{8}}
}]],
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "Casualties? Forget about your bloody casualties. All I know is that you're significantly behind schedule!",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F1D4"
        },
        [11011523] = {
          Camera = "12.281738,-219.625,91.564148,0.000186,6.800532,103.001862,15.0,62.163586,false,DoNotOverride,10.0",
          ContentJP = "貴様らは帝国の軍旗に泥を塗るつもりだな——ヒュペリア軍人たるもの、僅かな損失で立ち止まる臆病者であっていいものか！",
          DialogueId = 11011523,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "2.466797,-221.894531,91.564148,0.000186,6.800532,103.001961,15.0,62.163586,false,DoNotOverride,10.0",
          GUID = "1B90F1FE",
          NextDialogue = 11011524,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "You've brought shame to the legion's banner — the soldiers of Hyperborea are not cowards who would stop because of trivial losses like this!",
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F1FE"
        },
        [11011524] = {
          Camera = "-3204.455566,-1025.527344,215.10437,0.000155,-0.199339,5.802845,30.0,62.163586,false,DoNotOverride,10.0",
          ContentJP = "偉大なディズ1世陛下から「神の挽歌」の攻勢のクィントゥス軍団長まで！我々ヒュペリアが誇る偉大な統帥は損失など恐れていたかね？",
          DialogueId = 11011524,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "-3217.544434,-896.724609,215.104126,0.000155,-0.199339,5.802853,30.0,62.163586,false,DoNotOverride,10.0",
          GUID = "1B90F228",
          NextDialogue = 11011525,
          RelatedWikiId = {
            [1] = 201021
          },
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "From Emperor Dis I to Legion Chief Quintus, the mastermind of the Divine Elegy offensive, no Hyperborean commander ever baulked at taking losses.",
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F228"
        },
        [11011525] = {
          Camera = "-199.996582,27.865234,134.139771,-2.0,-2.199765,-22.991972,28.0,62.163586,false,DoNotOverride,10.0",
          ContentJP = "君の率いているのは第十三軍団の精鋭であろう？小さな要塞ひとつを攻め落とすには十分すぎるほどの戦力だと思うのだがな。",
          DialogueId = 11011525,
          DialoguePanelType = "{type:Guide;style:Communicator}",
          FinalCamera = "-201.352539,24.6875,134.018982,-2.0,-2.199765,-22.991972,28.0,62.163586,false,DoNotOverride,10.0",
          GUID = "1B90F252",
          NextDialogue = 11011526,
          SnapShot = "TELEPHONE",
          SpeakNpcId = 110011,
          Subtitle = "I gave you the elites of the 13th Legion. You should have more than enough resources to take this puny fort.",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F252"
        },
        [11011526] = {
          Camera = "-201.352539,24.6875,134.018982,-2.0,-2.199765,-22.991972,28.0,62.163586,false,DoNotOverride,10.0",
