        },
        [11011547] = {
          ContentJP = "まずは兵士たちの救援へ向かいましょう。現況の私たちだけでは、勝ち目などゼロに等しいですから。",
          DialogueId = 11011547,
          GUID = "1B90F5EE",
          ImprPlusId = 1009,
          NextDialogue = 11011548,
          Subtitle = "I intend to get to the soldiers first. We don't stand a chance on our own."
        },
        [11011548] = {
          Camera = "170.827637,-188.957031,121.458923,0.000164,-2.399261,154.39566,28.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "だな……やはり見込んだ通りだお前は。",
          DialogueId = 11011548,
          Duration = 3,
          GUID = "1B90F618",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11011550,
          SpeakNpcId = 110010,
          Subtitle = "You kiddo... I knew I was right about you.",
          TalkActionId = {
            [1] = "110010:Think_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F618"
        },
        [11011549] = {
          ContentJP = "勝算が低くとも総司令官の命令ですので実行を優先するべきかと。",
          DialogueId = 11011549,
          GUID = "1B90F642",
          ImprPlusId = 1007,
          NextDialogue = 11011550,
          Subtitle = "Even though our chances are slim, we must adhere to the Chief Commander's orders."
        },
        [11011550] = {
          Camera = "276.480469,1274.542969,240.643982,0.000117,-3.999116,-107.394035,28.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "フルヴィスの野郎は功名心に囚われた傲慢な男だぞ。偉そうに指揮を執っているが、ヤツは元老院におけるフルヴィス家の爵位を世襲したにすぎん。",
          DialogueId = 11011550,
          Duration = 3,
          FinalCamera = "236.748047,1279.9375,274.560486,0.000103,-3.999116,-107.394089,28.000006,100000.0,false,DoNotOverride,2.8",
          GUID = "1B90F66C",
          LookAt = {
            [1] = "110010:n(110022)"
          },
          NextDialogue = 11011551,
          SpeakNpcId = 110010,
          Subtitle = "Fulvis is nothing but an arrogant and greedy bastard. His senatorial lineage is the only reason he's up there, barking orders at you.",
          TalkActionId = {
            [1] = "110010:Talk03_Start"
          },
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F66C"
        },
        [11011551] = {
          ContentJP = "見ているのは報告書の数字だけ。兵士は生き物だと知らんようでな、勲章を作る材料とでも思っているんだろう。",
          DialogueId = 11011551,
          Duration = 3,
          GUID = "1B90F696",
          NextDialogue = 11011552,
          SpeakNpcId = 110010,
          Subtitle = "He sees soldiers as mere numbers in his reports, treating them as fodder for medals to pin on his uniform, not as living, breathing humans.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F696"
        },
        [11011552] = {
          Camera = "-23.271973,-38.910156,134.332947,0.000116,-1.398891,154.005493,28.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "まして戦場は刻一刻と変化し続ける。地図上だけの状況を俯瞰してヨチヨチ進んでいるあいつに何が分かる？",
          DialogueId = 11011552,
          Duration = 3,
          GUID = "1B90F6C0",
          NextDialogue = 11011553,
          SpeakNpcId = 110010,
          Subtitle = "Besides, battlefields are ever-changing. What true insight can he gain from just staring at a map?",
          TalkActionId = {
            [1] = "110010:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F6C0"
        },
        [11011553] = {
          Camera = "-116.939453,59.931641,129.807434,0.000084,-6.599089,-65.392105,28.000008,100000.0,false,Manual,8.0",
          ContentJP = "{nickname2}、命令だ。お前の戦友を救助せよ。フルヴィスに責任を問われたら俺が命令したと答えてやれ。",
          DialogueId = 11011553,
          Duration = 3,
          GUID = "1B90F6EA",
          NextDialogue = 11011554,
          SpeakNpcId = 110010,
          Subtitle = "Go rescue your comrades, . In case Fulvis seeks someone to blame later, consider this a direct order from me.",
          VoiceName = "voice/$Locale$/story/1002/110115/1B90F6EA"
        },
        [11011554] = {
