          SpeakNpcId = 110005,
          Subtitle = "Please be careful... I'll see you in Dismania.",
          VoiceName = "voice/$Locale$/story/1002/110117/1B911100"
        },
        [11011801] = {
          ContentJP = "隊長！あ、あああ——こっち！こっちです！",
          DialogueId = 11011801,
          Duration = 3,
          GUID = "1B911F9A",
          SpeakNpcId = 110015,
          Subtitle = "Captain! Captain, over here!",
          VoiceName = "voice/$Locale$/story/1002/110118/1B911F9A"
        },
        [11011802] = {
          Camera = "-485.80957,430.660156,148.512939,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "やった、やったぞ、隊長、我が親愛なる隊長様ぁ！来てくださいましたかぁ！通信の周波数帯に異常が起きて誰とも連絡が取れなくなってたのです。なのでシモンが救援の要請に。",
          DialogueId = 11011802,
          FinalCamera = "-485.80957,430.660156,123.858765,0.000044,-2.39937,-69.002335,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "1B911FC4",
          LookAt = {
            [1] = "110043:n(110022)",
            [2] = "110022:n(110043)"
          },
          NextDialogue = 11011803,
          RelatedWikiId = {
            [1] = 204001,
            [2] = 201012,
            [3] = 201013,
            [4] = 408007,
            [5] = 101004
          },
          Scripts = [[
SEQ{
PARA{
MoveTo{ActorId{110022},TargetPoint{"fix11nanzhu"},MoveSpeed{150},Visibility{true}},
MoveTo{ActorId{110016},TargetPoint{"fix1102"},MoveSpeed{150},Visibility{true}},
MoveTo{ActorId{110043},TargetPoint{"fix1101"},MoveSpeed{150},Visibility{true}}
},
PlayAnimation{_click{False},ActorId{110043},AnimationId{"Talk01_Start"},Duration{2}}
}]],
          SpeakNpcId = 110043,
          Subtitle = "Oh, Captain! My dear Captain!! You finally came for us!! Something's gone wrong with our comm channels and we couldn't get in touch with nobody. Simon went out looking for help.",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/story/1002/110118/1B911FC4"
        },
        [11011803] = {
          ContentJP = "僕はずっとみんなを激励してました。強く、勇ましく、心優しい隊長でありますし、きっと「ササッ、ズバババッ！！」と風のように颯爽と駆けつけてくれるからって。",
          DialogueId = 11011803,
          GUID = "1B911FEE",
          NextDialogue = 11011804,
          Scripts = [[
SEQ{
LookAt{LookAtDescription{"110043:n(110016)"}},
LookAt{_delay{0.7},LookAtDescription{"110043:n(110022)"}},
PlayAnimation{_delay{1},_click{False},ActorId{110043},AnimationId{"Talk02_Start"},Duration{2}}
}]],
          SpeakNpcId = 110043,
          Subtitle = "I was just trying to get everyone to keep it together — told them how good you are and how you're gonna come flying in and get everyone out of this mess.",
          TalkActionId = {
            [1] = "110043:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B911FEE"
        },
        [11011804] = {
          Camera = "-176.421875,-207.507812,133.143555,0.000077,-4.60016,119.190758,40.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "隊長はおひとりで？シモンを見かけませんでしたか？",
          DialogueId = 11011804,
          GUID = "1B912018",
          LookAt = {
            [1] = "110016:n(110022)",
            [2] = "110022:n(110016)"
          },
          NextDialogue = 11011805,
          SpeakNpcId = 110016,
          Subtitle = "Captain, did you come alone? Did you see Simon?",
          TalkActionId = {
            [1] = "110043:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912018"
        },
        [11011805] = {
          ContentJP = "彼は、死んでしまった。",
          DialogueId = 11011805,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:Sad03"
          },
          GUID = "1B912042",
          NextDialogue = 11011806,
          SpeakNpcId = 110022,
          Subtitle = "He's dead.",
          TalkActionId = {
            [1] = "110022:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/story/1002/110118/1B912042"
        },
        [11011806] = {
          Camera = "-576.783203,132.173828,121.140991,0.000077,-0.800129,-17.610191,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "……！な、なんだって……！！嘘だろ！？仲間内でも一番機転の利くやつだったのに……あいつが……？",
          DialogueId = 11011806,
          FinalCamera = "-493.21582,105.644531,117.778931,0.000077,-0.800129,-17.610191,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "1B91206C",
          NextDialogue = 11011807,
          SpeakNpcId = 110016,
          Subtitle = "...!! He... He's the smartest among us. How come...?",
          TalkActionId = {
            [1] = "110016:Shock_Start"
          },
          ToFinalCameraBlendTime = 0.3,
          VoiceName = "voice/$Locale$/story/1002/110118/1B91206C"
        },
        [11011807] = {
          Camera = "-358.588867,96.607422,130.114014,0.000073,-5.400268,106.396278,35.000008,111.478104,false,Manual,2.8",
          ContentJP = "彼に関して考えるのは後回しだ。まずは戦って生き残る{性别2:ぞ|よ}。",
          DialogueId = 11011807,
          ExStoryInfo = "EXPlayer",
          FacialId = {
            [1] = "110022:None"
          },
          FinalCamera = "-358.588867,96.607422,135.594849,0.00008,-5.400268,106.396278,35.000015,111.478104,false,Manual,2.8",
          GUID = "1B912096",
          NextDialogue = 11011808,
          SpeakNpcId = 110022,
          Subtitle = "Now is not the time to dwell on Simon. We need to focus on this battle and surviving.",
