          VoiceName = "voice/$Locale$/story/1002/110124/1B918C8A"
        },
        [11012467] = {
          ContentJP = "親愛なる隊長様ったら帰ってきたのぉ？もしかして内緒話を聞かなかったの後悔しちゃった感じぃ？",
          DialogueId = 11012467,
          Duration = 3,
          GUID = "1B918CB4",
          NextDialogue = 11012468,
          SpeakNpcId = 110009,
          Subtitle = "You're back, honey. Changed your mind already? Desperate to hear out the secret?",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918CB4"
        },
        [11012468] = {
          ContentJP = "でも残念、今ご機嫌ナナメだから。もう話さねぇよターコ。",
          DialogueId = 11012468,
          Duration = 3,
          GUID = "1B918CDE",
          SpeakNpcId = 110009,
          Subtitle = "Sorry to disappoint, but I'm no longer in the mood for sharing.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918CDE"
        },
        [11012469] = {
          ContentJP = "分かっているわよ親愛なる隊長様ぁ。あなたが何を聞きたいのかなんてぇ。",
          DialogueId = 11012469,
          Duration = 3,
          GUID = "1B918D08",
          NextDialogue = 11012470,
          SpeakNpcId = 110009,
          Subtitle = "I know what you want, honey.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D08"
        },
        [11012470] = {
          ContentJP = "でもざーんねん、これ以上はなし。哀れな虜囚は話す気分じゃなくなってまぁ～っす。",
          DialogueId = 11012470,
          Duration = 3,
          GUID = "1B918D32",
          SpeakNpcId = 110009,
          Subtitle = "But I'm just a poor little captive now, not in the mood to talk.",
          VoiceName = "voice/$Locale$/story/1002/110124/1B918D32"
        },
        [11012501] = {
          ContentJP = "<W>そうだ、いいぞ……剣の柄をしかと握れ。上出来だ、あとは喉元へと狙いを定めるだけ——</>",
          DialogueId = 11012501,
          DisableMouth = 1,
          Duration = 3,
          ExStoryInfo = "EXPlayer",
          GUID = "1B919272",
          Scripts = [[
