        [11013402] = {
          Camera = "-1082.142456,-3445.185547,922.085327,0.000455,-17.59454,47.611614,40.250172,215.162598,false,DoNotOverride,2.8",
          ContentJP = "……現在の権限の所有者：アヴァール・ハードランド……",
