          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "...Current authority: Avar Hrodland...",
          TalkActionId = {
            [1] = "110010:Awa_Story_Operate01_Loop"
