          VoiceName = "voice/$Locale$/story/1002/110134/1B922644"
        },
        [11013403] = {
          Camera = "-1366.088501,-4102.904297,1084.964233,0.000416,-10.394857,69.806015,30.172316,215.162598,false,DoNotOverride,2.8",
          ContentJP = "こんにちは！敬愛なるアヴァール・ハードランド中佐！ヒュペリア帝国軍教訓第16条：敵が自分の射程内にいるならば、自分もまた敵の射程内にいることを忘れるべからず。",
          DialogueId = 11013403,
          Duration = 1,
          FinalCamera = "-1366.088501,-4102.904297,1026.309692,0.000416,-10.394857,69.806015,30.172316,215.162598,false,DoNotOverride,2.8",
          GUID = "1B92266E",
          NextDialogue = 11013404,
          SnapShot = "ELECTRIC",
          SpeakNpcName = "UI_Npc_MechVoice",
          Subtitle = "Good afternoon, Lieutenant Colonel Avar Hrodland! Motto 16 of the Hyperborean Legion: When you have the enemy within range, beware that you are also within theirs...",
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110134/1B92266E"
        },
        [11013404] = {
          Camera = "-991.410645,-3133.832031,853.562988,0.000037,12.600312,-63.598225,37.326954,84.929626,false,Manual,22.0",
          ContentJP = "……やったぞ。",
          DialogueId = 11013404,
          Duration = 1,
          FacialId = {
            [1] = "110010:Confident01"
          },
          FinalCamera = "-978.536255,-3159.746094,858.094727,0.000037,12.600312,-63.598225,37.326958,84.929626,false,Manual,22.0",
          GUID = "1B922698",
          NextDialogue = 11013405,
          SpeakNpcId = 110010,
          Subtitle = "...Finally.",
          TalkActionId = {
            [1] = "110010:AgreeHead"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/story/1002/110134/1B922698"
        },
        [11013405] = {
          ContentJP = "ああ、まったく、人生の半分以上は戦場にいるが、ここまで冷や汗に塗れたのは初めてだぞ！ガッハッハ！ダフネとクラウディアには二度と会えんかもなって何度心に浮かんだことか！",
          DialogueId = 11013405,
          Duration = 1,
          GUID = "1B9226C2",
          NextDialogue = 11013406,
          Scripts = "PlayAnimation{_delay{4},ActorId{110010},AnimationId{\"Talk03_Start\"},Duration{3}}",
          SpeakNpcId = 110010,
          Subtitle = "Whew, of all the battles I've fought, none has been as nerve-wracking as this! Ha, I thought I might never see Daphne and Claudia again.",
          TalkActionId = {
            [1] = "110010:Confident_Start"
          },
          VoiceName = "voice/$Locale$/story/1002/110134/1B9226C2"
        },
        [11013406] = {
          Camera = "-1957.93042,-2481.015625,1137.403687,0.000278,-9.793418,-47.193382,26.362551,84.929626,false,Manual,22.0",
          ContentJP = "おかしい……操作権限は取ったはずなのに、この扉、開かねえ……",
          DialogueId = 11013406,
          Duration = 1,
          FinalCamera = "-1957.93042,-2481.015625,1137.403687,0.000278,-7.393372,-55.193539,26.362551,84.929626,false,Manual,22.0",
          GUID = "1B9226EC",
          NextDialogue = 11013424,
          Scripts = "TurnTo{_delay{1},TurnToDescription{\"110010:p(-150)\"},Visibility{\"Show\"}}",
          SpeakNpcId = 110010,
          Subtitle = "Strange. I've got the operational clearance… How come it's not working? What about you? Found anything unusual?",
          TalkActionId = {
            [1] = "110010:Talk03_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/story/1002/110134/1B9226EC"
        },
        [11013407] = {
          Camera = "1207.821289,-24.046875,792.712402,0.000088,-26.998186,-160.388702,23.655027,683.847168,false,Manual,22.0",
          ContentJP = "うん？どうした、酷い顔色だが。",
          DialogueId = 11013407,
          Duration = 2,
          FacialId = {
            [1] = "110010:Doubt01"
          },
          FinalCamera = "934.254883,-119.332031,634.576416,0.000083,-29.598288,-161.188431,23.655027,683.847168,false,Manual,22.0",
          GUID = "1B922716",
          NextDialogue = 11013408,
          Scripts = "MoveTo{ActorId{110010},TargetPoint{\"fix18awa2\"},MoveSpeed{100},Visibility{\"Show\"}}",
          SpeakNpcId = 110010,
          Subtitle = "Hmm? You look like you've seen a ghost. What's wrong?",
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1002/110134/1B922716"
        },
        [11013408] = {
          Camera = "-172.0177,-358.59375,38.439209,0.000213,-15.202054,69.195915,43.030418,100000.0,false,Manual,22.0",
