        },
        [11013409] = {
          Camera = "578.011597,-377.267578,237.151978,0.000106,-20.799086,178.209442,20.072239,84.929688,false,Manual,22.0",
          ContentJP = "（録音に出てくる名前、資料にある名前……目の前にいるのはアヴァール・ハードランド。体術や戦闘技術は彼から教わった。ここまで歩みをともにしてきた私の教官だ）",
          DialogueId = 11013409,
          DisableMouth = 1,
