        [11016619] = {
          ContentJP = "……俺の自慢の教え子よ……なあ、{nickname2}。悪いな、こんなことに巻き込んじまって。",
          DialogueId = 11016619,
          ExStoryInfo = "EXPlayer",
          GUID = "1B94360E",
