          NextDialogue = 11016620,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "I'm proud to have been your instructor, ... And I'm sorry for dragging you into this mess.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B94360E"
        },
        [11016620] = {
          ContentJP = "お前には生き延びてもらうぞ。起きた顛末を軍団長に、ひいては陛下に伝えるんだ。この作戦を全うした兵士たちは信条と使命のために最後の瞬間まで戦い抜いたと帝国の人々に知らしめる。その役目をお前が担うんだ。",
          DialogueId = 11016620,
          GUID = "1B943638",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016620.T_Story_Recall_11016620'",
          NextDialogue = 11016621,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "You must survive. Bring the truth to Chief Sibylle and His Majesty. Let the entire Empire know that every soldier here held true to their creed and duty, and everyone fought till their very last breath.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943638"
        },
        [11016621] = {
          ContentJP = "……我らが皇帝に栄光あれ。",
          DialogueId = 11016621,
          GUID = "1B943662",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016621.T_Story_Recall_11016621'",
          NextDialogue = 11016701,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/01/flashing\"},PlayAs2D{true}}",
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          Subtitle = "...All glory to our Emperor.",
          VoiceName = "voice/$Locale$/story/1002/110166/1B943662"
        },
        [11016622] = {
          ContentJP = "……じゃあ聞くが、ここまでの消耗と、閉じ込められてる状況を踏まえて……お前の見立てじゃ、今の俺たちでフルヴィスの親衛を正面から叩ける可能性は、どれくらいある？",
          DialogueId = 11016622,
          GUID = "1B943495",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016623,
