          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943495"
        },
        [11016623] = {
          ContentJP = "敵が包囲してきたら……勝率は、ほぼゼロ。でも、死ぬ覚悟なら――",
          DialogueId = 11016623,
          ExStoryInfo = "EXPlayer",
          GUID = "1B943496",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016624,
          SnapShot = "MEMORY",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943496"
        },
        [11016624] = {
          ContentJP = "死ぬ覚悟は簡単だ。だが、使命を背負って生き延びるってのは、その何倍も難しい。{nickname2}、これは命令だ。これを成し遂げられるのは――お前だけだ。",
          DialogueId = 11016624,
          GUID = "1B943497",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
          NextDialogue = 11016625,
          SnapShot = "MEMORY",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110166/1B943497"
        },
        [11016625] = {
          ContentJP = "それに……俺の命ってのはな、お前が思ってるより、ずっと高くつくんだよ。まだ使い道があるんでな。",
          DialogueId = 11016625,
          GUID = "1B943498",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_11016611.T_Story_Recall_11016611'",
