        },
        [11016903] = {
          Camera = "-342.746094,140.6875,121.378906,0.000104,2.002775,27.177742,35.000011,530.09375,false,Manual,22.0",
          ContentJP = "上層部が急ぎ全ての審査手順を進めた。私の手に届いたのは、お前たちを処刑しろという紙切れだけだ。",
          DialogueId = 11016903,
          FacialId = {
            [1] = "110032:Angry01"
          },
          GUID = "1B9464A6",
          LookAt = {
            [1] = "110041:n(110032)",
            [2] = "110040:n(110032)"
          },
          NextDialogue = 11016904,
          Scripts = [[
SEQ{
SetLocation{ActorId{110032},TargetPoint{"28Point2"},Visibility{"Show"}}
}]],
          SpeakNpcId = 110032,
          Subtitle = "A directive to expedite all procedural reviews has been issued from above. The only document I received is a writ demanding your immediate execution.",
          TalkActionId = {
            [1] = "110032:Explain01_Start",
            [2] = "110041:Sit_Talk03_End"
