          GUID = "1B957C0C",
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110186/1B957C0C"
        },
        [11018701] = {
          ContentJP = "この娘はフォーセイクン同盟の一味だ。しっかり見張ってろ！",
