          GUID = "1B958BA2",
          IsBlack = 1,
          SpeakNpcId = 110010,
          VoiceName = "voice/$Locale$/story/1002/110187/1B958BA2"
        },
        [11018702] = {
          ContentJP = "防御モード起動中。セーフモードにリセットしてください。",
          DialogueId = 11018702,
