        },
        [11018801] = {
          ContentJP = "セーフモードに切り替える",
          DialogueId = 11018801,
          GUID = "1B959C0A"
        },
        [11018802] = {
          ContentJP = "防御モードに切り替える",
          DialogueId = 11018802,
          GUID = "1B959C34",
          NextDialogue = 11018803
        },
        [11018803] = {
          ContentJP = "（頭上の赤いライトが点滅してる……今は防御モード中だ。）",
