          NextDialogue = 11018702,
          VoiceName = "voice/$Locale$/story/1002/110188/1B959C5E"
        },
        [11018804] = {
          ContentJP = "自爆モードに切り替える",
          DialogueId = 11018804,
          GUID = "1B959C88",
