          GUID = "1E0AC0B2",
          NextDialogue = 12000507
        },
        [12000507] = {
          Content = "开个车，提示去聊一下+1",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000507,
          GUID = "1E0AC0B3"
        },
        [12000601] = {
          ContentJP = "ヴィオレッタさんのあの美しい歌声、澄んで豊かな高音に、芸術的なコロラトゥーラ！絶対に妖精の役を完璧に演じてくれるに違いないよ！この不朽のオペラが、新たな高みへと昇るのを見るのが楽しみだな！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000601,
          GUID = "1E0AD09A",
          NextDialogue = 12000602,
          SpeakNpcId = 220003,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD09A"
        },
        [12000602] = {
          ContentJP = "そうかね……俺から見れば、このオペラ団のレベルは年々落ちてきてる気がするな。まあ、かろうじて聴けるってところだな。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000602,
          GUID = "1E0AD0C4",
          NextDialogue = 12000603,
          SpeakNpcId = 220004,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD0C4"
        },
        [12000603] = {
          ContentJP = "それでも毎回欠かさずチケット買ってるじゃないか？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000603,
          GUID = "1E0AD0EE",
          NextDialogue = 12000604,
          SpeakNpcId = 220003,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD0EE"
        },
        [12000604] = {
          ContentJP = "聴けるかどうかは、やっぱり実際に来てみないとわからないだろう？結局のところ、こういう楽しみで生きてるようなもんだからさ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000604,
          GUID = "1E0AD118",
          SpeakNpcId = 220004,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD118"
        },
        [12000605] = {
          ContentJP = "パパ、リリィもうすぐお姉さんたちの声の魔法が聴けるんだよね！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000605,
          GUID = "1E0AD142",
          NextDialogue = 12000606,
          SpeakNpcId = 220005,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD142"
        },
        [12000606] = {
          ContentJP = "パパと一緒にオペラを観れて、そのあとごちそうも食べに行けるなんて、今日はリリィにとって一番幸せな日だよ！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000606,
          GUID = "1E0AD16C",
          SpeakNpcId = 220005,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD16C"
        },
        [12000607] = {
          ContentJP = "おい、聞いたか？数日前の銀燭祭りで、劇場で誰かが騒動を起こしたらしい！帝国軍のお偉いさんまで出てきたんだってよ！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000607,
          GUID = "1E0AD196",
          NextDialogue = 12000608,
          SpeakNpcId = 220006,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD196"
        },
        [12000608] = {
          ContentJP = "幽霊の仕業か、神に見捨てられた者の仕業か、それとも「カロン狩り」の犯人が蘇ったのか……真相を探ろうとした奴らはみんな口止めされちまったんだってよ！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12000608,
          GUID = "1E0AD1C0",
          SpeakNpcId = 220006,
          VoiceName = "voice/$Locale$/story/1200/120006/1E0AD1C0"
        },
