          ContentJP = "兵士の叱責が突然止んだ。シリュウが重そうな小袋を彼に渡しているのが目に入った。兵士は袋の重さを量り、無表情でそれを袖口にしまい込んだ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001766,
          Duration = 5,
          GUID = "1E0B8FBC",
          NextDialogue = 12001767,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"100001:p(Nvzhu_Look_309)\"}}",
          TalkActionId = {
            [1] = "220014:Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8FBC"
        },
        [12001767] = {
          Camera = "355.125,200.536621,154.582031,0.000034,-5.1997,-148.204956,35.000011,100000.0,false,DoNotOverride,10.0",
          ContentJP = "まあいいでしょう。今夜、重要な逃亡犯を捕まえるために、街の全ての兵力が動員されたんです。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001767,
          GUID = "1E0B8FE6",
          LookAt = {
            [1] = "100001:n(220025)"
          },
          NextDialogue = 12001768,
          SpeakNpcId = 220025,
          TalkActionId = {
            [1] = "220014:Talk02R_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B8FE6"
        },
        [12001768] = {
          ContentJP = "でも、この逃亡犯がどこにいて、どんな姿をしているのか、まだ手がかりは掴んでおりません。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001768,
          GUID = "1E0B9010",
          NextDialogue = 12001769,
          SpeakNpcId = 220025,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9010"
        },
        [12001769] = {
          Camera = "-270.78418,255.63623,167.03418,0.000086,-8.000794,-55.608383,35.000011,100000.0,false,DoNotOverride,10.0",
          ContentJP = "うーん、困ったわね……私は<Default note=\"text:カショ\">華胥</>から来た商人よ。プライベート飛行船を郊外に停めててね。六時間後には、重要な商談に出席しなければならないの。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001769,
          GUID = "1E0B903A",
          LookAt = {
            [1] = "100001:n(220025)",
            [2] = "200002:n(220025)"
          },
          NextDialogue = 12001770,
          SpeakNpcId = 220014,
          TalkActionId = {
            [1] = "220014:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B903A"
        },
        [12001770] = {
          ContentJP = "私と車に乗っている方は全員、身分が清白なで、正式な出国手続きも済ませているの。どうか、少しだけご融通いただけないかしら？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001770,
          GUID = "1E0B9064",
          NextDialogue = 12001771,
          SpeakNpcId = 220014,
          TalkActionId = {
            [1] = "220014:Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9064"
        },
        [12001771] = {
          Camera = "-90.224609,27.822266,129.658691,0.000123,-0.199885,-48.183372,51.572987,182.084885,false,Manual,10.0",
          ContentJP = "シリュウが提示した書類の中に、あなたは自分の写真がきちんと貼り付けられているのをはっきりと見た。ただその写真の表情はやや厳しく、見慣れないものだった。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001771,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_Chapter_Passport.T_Guide_Chapter_Passport'}",
          Duration = 5,
          FinalCamera = "-83.21582,19.981934,129.623047,0.000123,-0.199885,-48.18306,51.572987,171.736893,false,Manual,10.0",
          GUID = "1E0B908E",
          NextDialogue = 12001772,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B908E"
        },
        [12001772] = {
          ContentJP = "シリュウ……いつの間に書類を準備したんだろう？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001772,
          DisableMouth = 1,
          Duration = 5,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "1E0B90B8",
          LookAt = {
            [1] = "220014:n(220025)"
          },
          NextDialogue = 12001773,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "220014:Talk03ToTalkL_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B90B8"
        },
        [12001773] = {
          Camera = "100.349609,-20.827148,139.20459,0.000054,-0.000246,-172.803757,35.000011,264.540283,false,Manual,6.124233",
          ContentJP = "奥様……決してご迷惑をおかけするつもりはありませんが、長官から通行を厳しく禁じられております。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001773,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "1E0B90E2",
          LookAt = {
            [1] = "220025:n(220014)"
          },
          NextDialogue = 12001774,
          SpeakNpcId = 220025,
          TalkActionId = {
            [1] = "220025:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B90E2"
        },
        [12001774] = {
          Camera = "-410.826172,260.788574,156.883301,0.000045,-3.800918,-40.007858,60.419567,100000.0,false,DoNotOverride,10.0",
          ContentJP = "ではこうしましょう。あなたたちの軍隊番号と長官の名前を教え、私が何とかするわ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001774,
          GUID = "1E0B910C",
          NextDialogue = 12001775,
          SpeakNpcId = 220014,
          TalkActionId = {
            [1] = "220014:Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B910C"
        },
        [12001775] = {
          Camera = "-60.169922,20.828613,119.424805,0.000075,12.599663,-45.606236,46.428596,118.094795,false,Manual,10.0",
          ContentJP = "ふふ、もしルシアナ・ロレートが私が小さな兵士に引き留められて、大事な商談を逃したことを知ったら、アフタヌーンティーの話題になるでしょうね。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001775,
          GUID = "1E0B9136",
          NextDialogue = 12001776,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9136"
        },
        [12001776] = {
          Camera = "24.524414,3.004395,148.750488,0.000044,-2.599973,-158.404205,35.000008,100000.0,false,DoNotOverride,10.0",
          ContentJP = "ルシアナ・ロレート……聞いたことがあるような……確か帝国財務大臣のお名前！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001776,
          GUID = "1E0B9160",
          LookAt = {
            [1] = "220026:n(220025)",
            [2] = "220025:n(220026)"
          },
          NextDialogue = 12001777,
          SpeakNpcId = 220026,
          TalkActionId = {
            [1] = "220025:Talk01_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9160"
        },
        [12001777] = {
          ContentJP = "待て、もう一度見てみろ。書類に彼女の直筆署名が載っているぞ！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001777,
          GUID = "1E0B918A",
          NextDialogue = 12001778,
          SpeakNpcId = 220026,
          TalkActionId = {
            [1] = "220014:Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B918A"
        },
        [12001778] = {
          ContentJP = "困りましたな……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001778,
          GUID = "1E0B91B4",
          LookAt = {
            [1] = "220025:n(220014)"
          },
          NextDialogue = 12001779,
          SpeakNpcId = 220025,
          TalkActionId = {
            [1] = "220025:Shock_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B91B4"
        },
        [12001779] = {
          Camera = "-491.920898,478.322754,448.695801,0.000088,-10.999807,-47.399258,9.196175,100000.0,false,DoNotOverride,10.0",
          ContentJP = "全体注意！目標が劇場付近に出現した疑いがあり、武器を所持して逃走を試みている。近隣小隊、速やかに現場へ増援に向かえ。繰り返す——近隣小隊、速やかに現場へ増援に向かえ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001779,
          FinalCamera = "-491.920898,478.322754,448.695801,0.000088,-1.599603,-42.39946,9.196175,100000.0,false,DoNotOverride,10.0",
          GUID = "1E0B91DE",
          NextDialogue = 12001780,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/east/intro_crowdcombat\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "220025:Shock_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B91DE"
        },
        [12001780] = {
          Camera = "-245.133789,192.716309,132.871094,0.00009,-3.199267,-51.80265,30.0,100000.0,false,DoNotOverride,10.0",
          ContentJP = "うーん……どうやら容疑者が現れたみたいね。さて、まだ私たちを引き止めるつもりかしら？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001780,
          FacialId = {
            [1] = "220014:Smile01"
          },
          GUID = "1E0B9208",
          LookAt = {
            [1] = "220014:n(220025)",
            [2] = "100001:n(220025)",
            [3] = "200002:n(220025)"
          },
          NextDialogue = 12001781,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9208"
        },
        [12001781] = {
          Camera = "259.166016,139.326172,124.026855,0.0001,-2.599324,-148.204941,30.000002,100000.0,false,DoNotOverride,10.0",
          ContentJP = "……ではこうしましょう、奥様。今回は通行を許可しますが、確かに出国したことを確認できるように担当者を派遣いたします。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001781,
          GUID = "1E0B9232",
          NextDialogue = 12001782,
          SpeakNpcId = 220025,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9232"
        },
        [12001782] = {
          ContentJP = "飛行船が離陸するまで、あなたやあなたの部下の皆様には、私たちの視界内にお留まりいただく必要がございます。万が一、怪しい動きがございましたら、それは帝国への挑発と見なされます。このご提案はいかがでしょうか？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001782,
          GUID = "1E0B925C",
          NextDialogue = 12001783,
          SpeakNpcId = 220025,
          TalkActionId = {
            [1] = "220014:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B925C"
        },
        [12001783] = {
          Camera = "-247.888672,60.718262,171.297363,0.000116,-9.999724,-29.603325,35.000011,298.698639,false,Manual,10.0",
          ContentJP = "ふふ……問題ないわ。お互い納得がいくことに越したことはないからね。その提案を受け入れるわ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001783,
          GUID = "1E0B9286",
          LookAt = {
            [1] = "100001:n(220025)"
          },
          NextDialogue = 12001784,
          SpeakNpcId = 220014,
          TalkActionId = {
            [1] = "220014:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B9286"
        },
        [12001784] = {
          Camera = "-459.007812,408.505859,307.084473,0.000125,-16.999718,-52.801178,21.614788,100000.0,false,DoNotOverride,10.0",
          ContentJP = "ご協力ありがとうございます——通せ！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001784,
          FinalCamera = "-534.192383,507.5625,345.104492,0.000125,-16.999718,-52.801178,21.614788,100000.0,false,DoNotOverride,10.0",
          GUID = "1E0B92B0",
          SpeakNpcId = 220025,
          TalkActionId = {
            [1] = "220014:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/1200/120017/1E0B92B0"
        },
        [12001785] = {
          Content = "皎皎气呼呼地跑走了。",
          DialogueId = 12001785,
          GUID = "1E0B8AD1"
        },
        [12001801] = {
          Camera = "26.581055,-95.871094,153.29248,0.000088,-8.170654,-51.38456,12.0,60.0,false,Manual,10.0",
          ContentJP = "さて、もう自由に話話しても大丈夫よ。でも、表情には気をつけて。あの兵士たちが後ろからついているから。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001801,
          FinalCamera = "1.03418,-98.566895,152.582031,0.000092,-8.970668,-40.585316,12.0,100.0,false,Manual,10.0",
          GUID = "1E0B957A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 220014,
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B957A",
          bNotRecall = 1
        },
        [12001802] = {
          ContentJP = "ふふ、あれは私が雇った月狩り人よ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001802,
          GUID = "1E0B95A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001803,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95A4"
        },
        [12001803] = {
          ContentJP = "報酬がそれほど多くなくても、それを目当てにリスクを冒す人はいるわよね。でも、このお金じゃ、財務大臣の郊外の邸宅にいる猟犬すら買えないわ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001803,
          GUID = "1E0B95CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001804,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95CE"
        },
        [12001804] = {
          ContentJP = "でもおかげで、今夜の危機を解決できたわ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001804,
          GUID = "1E0B95F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B95F8"
        },
        [12001805] = {
          ContentJP = "面白いことを聞きたい？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001805,
          GUID = "1E0B9622",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001806,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9622"
        },
        [12001806] = {
          ContentJP = "『ヒュペリア新聞』は帝国全土で発行されている新聞よ。そして、ヒュペリアのすべての主要都市の中心広場には……ちょうど赤い電話ボックスが一つずつ設置されている。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001806,
          GUID = "1E0B964C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001807,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B964C"
        },
        [12001807] = {
          ContentJP = "今朝、カミラからこの新聞について説明してもらったの。これを知ってから、念のため、いくつか電報を余分に送ったわ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001807,
          GUID = "1E0B9676",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001808,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9676"
        },
        [12001808] = {
          ContentJP = "いいニュースを教えてあげる。今夜、すべての都市の電話ボックスには白髪の女性が立っていて、訪れることのない『故人』を待っているのよ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001808,
          GUID = "1E0B96A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001809,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96A0"
        },
        [12001809] = {
          ContentJP = "なぜこれがいいニュースなの？スノウ、わかんない……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001809,
          GUID = "1E0B96CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001810,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96CA"
        },
        [12001810] = {
          ContentJP = "シリュウ店主が言いたいのは、彼らには{性别:僕|私}の居場所も生死もわかっていないから、大規模に餌を撒き、この方法で{性别:僕|私}を誘い出そうとしているのだと思う……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001810,
          GUID = "1E0B96F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001811,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B96F4"
        },
        [12001811] = {
          ContentJP = "大当たり、賢いわね。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001811,
          GUID = "1E0B971E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001812,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B971E"
        },
        [12001812] = {
          ContentJP = "自分の存在を知っていて、この局を仕掛けている帝国軍の人物は、一体誰なんだろう……？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001812,
          GUID = "1E0B9748",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001830,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9748"
        },
        [12001813] = {
          ContentJP = "今の状況だと、飛行船が離陸するまであなたは車を降りられないみたいね。ごめんなさい、どうやらあなたも一緒に<Default note=\"text:カショ\">華胥</>へ連れて行くことになりそうね。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001813,
          GUID = "1E0B9772",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001814,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9772"
        },
        [12001814] = {
          ContentJP = "シリュウ店主、何回も助けていただいて本当に感謝しきれません。どうすればこのご恩を返せますでしょうか？",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001814,
          GUID = "1E0B979C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001815,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B979C"
        },
        [12001815] = {
          ContentJP = "ふむ……恩を返すか。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001815,
          GUID = "1E0B97C6",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001816,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97C6"
        },
        [12001816] = {
          ContentJP = "実はちょうど手伝ってくれる人が必要だったの。<Default note=\"text:カショ\">華胥</>からヒュペリアへ戻る飛行船は七日後に出発するから、その間、もしよかったら力を貸してくれると助かるわ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001816,
          GUID = "1E0B97F0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001817,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B97F0"
        },
        [12001817] = {
          ContentJP = "どうかしら？ちょっと考えてみて、賢い子供たち。報酬ももちろんはずむわ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001817,
          GUID = "1E0B981A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001818,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B981A"
        },
        [12001818] = {
          ContentJP = "（やっぱり……偶然じゃなかったか。）",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001818,
          GUID = "1E0B9844",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextOptions = {
            [1] = 12001819,
            [2] = 12001820
          },
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9844"
        },
        [12001819] = {
          ContentJP = "この車に乗った時から、拒否権はもうないんじゃないかな。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001819,
          GUID = "1E0B986E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          ImprPlusId = 1006,
          NextDialogue = 12001821,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B986E"
        },
        [12001820] = {
          ContentJP = "何度も助けてくれた身です、喜んでお手伝いします。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001820,
          GUID = "1E0B9898",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          ImprPlusId = 1007,
          NextDialogue = 12001821,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9898"
        },
        [12001821] = {
          ContentJP = "とっても遠い国に行って、見たこともない美味しい食べ物を味わって、しかも大金を稼げるだなんて……我が下僕よ、これはかなり素敵な大冒険になりそうだな！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001821,
          GUID = "1E0B98C2",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001822,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98C2"
        },
        [12001822] = {
          ContentJP = "すみません、出発する前に……もう一つお願いしてもいいですか。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001822,
          GUID = "1E0B98EC",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001823,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B98EC"
        },
        [12001823] = {
          ContentJP = "心配いらないわ。他の街でも何人か雇ったからね。こうしてあちこちで釣られる魚たちがいるおかげで、ヒュペリアの兵士たちの今夜の行動は、多分無駄足に終わるでしょうね――彼らは、あなたがアイスレイク城にいることを知ることはないわ。",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001823,
          GUID = "1E0B9916",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001824,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9916"
        },
        [12001824] = {
          ContentJP = "（ここまで読むなんて……この<H><Default note=\"text:カショ\">華胥</></>から来た女性、一体何を依頼するつもりなんだろう……）",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001824,
          GUID = "1E0B9940",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001825,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9940"
        },
        [12001825] = {
          ContentJP = "とはいえ、ここまで来てしまった以上、他に選択肢はない。7日間だけなら、時間的にはまだ余裕がある……",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001825,
          GUID = "1E0B996A",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          NextDialogue = 12001826,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B996A"
        },
        [12001826] = {
          ContentJP = "わかった！この依頼、引き受けるよ！",
          DefaultLookAt = "TalkNpc",
          DialogueId = 12001826,
          GUID = "1E0B9994",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_12001801.T_Story_Recall_12001801'",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/1200/120018/1E0B9994"
        },
