        },
        [12004101] = {
          ContentJP = "……わぁ、すごい人だ！みんなオペラを観に来たのかな？",
          DialogueId = 12004101,
          GUID = "1E0AE102",
          NextDialogue = 12004102,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120007/1E0AE102"
        },
        [12004102] = {
          ContentJP = "なんか面白いこと話してるみたい。我が下僕よ、早く行こう！",
          DialogueId = 12004102,
          GUID = "1E0D0EFC",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120041/1E0D0EFC"
        },
        [12004201] = {
          ContentJP = "シリュウ、アスフォデロスに行くって言ってたけど、知り合いにでも会いに行くのか？",
          DialogueId = 12004201,
          GUID = "1E0D1F3A",
          NextDialogue = 12004202,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F3A"
        },
        [12004202] = {
          ContentJP = "まーさーか……金髪のくるくるパーマをした、おっかない女店長とかじゃないよね！？",
          DialogueId = 12004202,
          GUID = "1E0D1F64",
          NextDialogue = 12004203,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F64"
        },
        [12004203] = {
          ContentJP = "ふふ、よく分かったわね。",
          DialogueId = 12004203,
          GUID = "1E0D1F8E",
          NextDialogue = 12004204,
          SpeakNpcId = 220014,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1F8E"
        },
        [12004204] = {
          ContentJP = "へへん！この魔王様に分からないことなんてないよ！",
          DialogueId = 12004204,
          GUID = "1E0D1FB8",
          NextDialogue = 12004205,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FB8"
        },
        [12004205] = {
          ContentJP = "あ、さっきのはカミラに言っちゃダメだぞ……今日のお小遣いがなくなっちゃうから。",
          DialogueId = 12004205,
          GUID = "1E0D1FE2",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D1FE2"
        },
        [12004206] = {
          ContentJP = "着いたぞ——",
          DialogueId = 12004206,
          GUID = "1E0D200C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120042/1E0D200C"
        },
        [12004301] = {
          ContentJP = "スノウはプンプンしながら走り去った。",
          DialogueId = 12004301,
          Duration = 2,
          GUID = "1E0D2FA2",
          VoiceName = "voice/$Locale$/story/1200/120043/1E0D2FA2"
        },
        [12004401] = {
          ContentJP = "あの機械、なんか変……避けた方がいい気がする！",
          DialogueId = 12004401,
          GUID = "1E0D400A",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D400A"
        },
        [12004402] = {
          ContentJP = "あっち行ったぞ！今のうちに——",
          DialogueId = 12004402,
          GUID = "1E0D4034",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120044/1E0D4034"
        },
        [12004501] = {
          ContentJP = "<W>ターゲット発見！ターゲット発見！</>",
          DialogueId = 12004501,
          GUID = "1E0D5072",
          NextDialogue = 12004502,
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D5072"
        },
        [12004502] = {
          ContentJP = "あわわ……見つかっちゃったぞ！",
          DialogueId = 12004502,
          GUID = "1E0D509C",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/1200/120045/1E0D509C"
        },
        [12004503] = {
          Content = "任务失败，请重新开始。",
          DialogueId = 12004503,
          GUID = "1E0D509D",
          SpeakNpcId = 200002
        },
        [12004504] = {
          Content = "被动失败",
          DialogueId = 12004504,
          GUID = "1E0D509E",
          SpeakNpcId = 200002
        },
        [12030001] = {
          ContentJP = "つい最近のこと、アイスレイク城で語り継がれた物語――",
          DialogueId = 12030001,
          Duration = 4,
          GUID = "1E1DA80A",
          NextDialogue = 12030002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA80A"
        },
        [12030002] = {
          ContentJP = "一羽の小さなナイチンゲールが、あたたかな巣を飛び出す決心をしました。",
          DialogueId = 12030002,
          Duration = 4,
          GUID = "1E1DA834",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA834"
        },
        [12030003] = {
          Content = "菲娜坐在家里，看着故事书",
          DialogueId = 12030003,
          GUID = "1E1DA85E",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DA85E"
        },
        [12030101] = {
          Content = "菲娜，晚上光线太暗，看书伤眼睛，还是早点睡吧。",
          DialogueId = 12030101,
          GUID = "1E1DB872",
          NextDialogue = 12030102,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB872"
        },
        [12030102] = {
          Content = "唔……",
          DialogueId = 12030102,
          GUID = "1E1DB89C",
          NextDialogue = 12030103,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB89C"
        },
        [12030103] = {
          Content = "怎么了？",
          DialogueId = 12030103,
          GUID = "1E1DB8C6",
          NextDialogue = 12030104,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8C6"
        },
        [12030104] = {
          Content = "奥特赛德，菲娜……菲娜有一个愿望！",
          DialogueId = 12030104,
          GUID = "1E1DB8F0",
          NextDialogue = 12030105,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB8F0"
        },
        [12030105] = {
          Content = "是吗？你说，是什么愿望？",
          DialogueId = 12030105,
          GUID = "1E1DB91A",
          NextDialogue = 12030106,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB91A"
        },
        [12030106] = {
          Content = "菲娜想出去看看。",
          DialogueId = 12030106,
          GUID = "1E1DB944",
          NextDialogue = 12030107,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB944"
        },
        [12030107] = {
          Content = "出去……？现在吗？",
          DialogueId = 12030107,
          GUID = "1E1DB96E",
          NextDialogue = 12030108,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB96E"
        },
        [12030108] = {
          Content = "不是的，菲娜的意思是，菲娜也想像你和独角兽{性别：先生|小姐}一样，去外面的世界，认识很多的新朋友……",
          DialogueId = 12030108,
          GUID = "1E1DB998",
          NextDialogue = 12030109,
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB998"
        },
        [12030109] = {
          Content = "这可不行，外面很危险的。我和{nickname}大多数时候遇到的都不是朋友，而是秽——怪兽，和很多坏——坏巫师，对，那些坏巫师可吓人了。",
          DialogueId = 12030109,
          GUID = "1E1DB9C2",
          NextDialogue = 12030110,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9C2"
        },
        [12030110] = {
          Content = "所以，你还是待在家里最安全。",
          DialogueId = 12030110,
          GUID = "1E1DB9EC",
          NextDialogue = 12030111,
          SpeakNpcId = 211002,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DB9EC"
        },
        [12030111] = {
          Content = "呜……",
          DialogueId = 12030111,
          GUID = "1E1DBA16",
          SpeakNpcId = 211001,
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA16"
        },
        [12030112] = {
          ContentJP = "フィーナは眠っている。アウトサイダーが、机の上に置かれたフィーナの本を見ている",
          DialogueId = 12030112,
          GUID = "1E1DBA40",
          VoiceName = "voice/$Locale$/story/1201/120111/1E1DBA40"
        },
        [12030201] = {
          Camera = "-345.501678,523.378906,124.574219,0.000322,-4.833527,90.822472,35.000008,77.550713,false,Manual,4.0",
          ContentJP = "「大魔法使いはいつも言っていました。外の世界は危険で、巣の中が一番安全だと……でも、小さな巣から見えるのは、四角く切り取られた空だけ」",
          DialogueId = 12030201,
          FinalCamera = "-351.068237,428.320312,123.277344,0.000143,-3.242031,91.01268,35.000008,212.663025,false,Manual,2.8",
          GUID = "1E1DC8DA",
