          ContentJP = "ほう……あんたのその顔、疑っとるね？",
          DialogueId = 20000528,
          Duration = 3,
          FacialId = {
            [1] = "200024:Shock01"
          },
          FinalCamera = "114.166748,-161.282227,36.354004,0.000129,8.798526,128.416595,50.000008,421.26944,false,Manual,6.435696",
          GUID = "3211B8CA",
          LookAt = {
            [1] = "200024:n(100001)"
          },
          NextDialogue = 20000529,
          Scripts = "CameraMoveTo{_delay{3.5},TargetPosition{\"-257.094238,105.374512,89.299316,0.000146,-7.001647,-20.17968,50.000008,421.26944,false,Manual,6.435696\"},duration{0}}",
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "Look, I can see scepticism written on your face.",
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 3,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B8CA"
        },
        [20000529] = {
          Camera = "-69.666748,-17.761719,56.248047,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "案ずるには及ばんさ。「自ら進んで他人を傷つけるルーナ族はいない」これはアトラシア大陸の誰もが知っておる。",
          DialogueId = 20000529,
          Duration = 2,
          FacialId = {
            [1] = "200024:Ahaha02"
          },
          FinalCamera = "-69.666748,-17.761719,57.486084,0.000116,1.798375,-8.383431,50.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "3211B8F4",
          NextDialogue = 20000530,
          SpeakNpcId = 200024,
          SpeakNpcName = "UI_Npc_Name_Duanzao",
          Subtitle = "You can trust me. You must know the saying, \"Lunos never harm.\" Everyone in Atlasia knows that.",
          ToFinalCameraBlendTime = 5,
          VoiceName = "voice/$Locale$/story/2001/200005/3211B8F4"
        },
        [20000530] = {
