          IsBlack = 1,
          NextDialogue = 20001802,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200018/3212897A"
        },
        [20001802] = {
          ContentJP = "スノウは{性别:僕|私}たちの後ろに。風が少しおさまるタイミングをみて進もう。",
          DialogueId = 20001802,
          ExStoryInfo = "Player",
          GUID = "321289A4",
          NextDialogue = 20001803,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200018/321289A4"
        },
        [20001803] = {
          ContentJP = "風が強いときは岩の後ろにかくれよう。焦らず、ゆっくりな。",
          DialogueId = 20001803,
          GUID = "321289CE",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200018/321289CE"
        },
        [20001901] = {
          Camera = "-362.765625,-80.016602,-24.530273,0.000006,17.167358,25.771385,15.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "遠くの湖の上空に嵐が渦巻いている。サイキはあの嵐の方向にいるはずだ……",
          DialogueId = 20001901,
          GUID = "321299E2"
        },
        [20002001] = {
          ContentJP = "……蝶？どうして冬に蝶が？",
          DialogueId = 20002001,
          ExStoryInfo = "Player",
          GUID = "3212AA4A",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200020/3212AA4A"
        },
        [20002002] = {
          ContentJP = "なんだか……道案内をしてくれているみたい……",
          DialogueId = 20002002,
          ExStoryInfo = "Player",
          GUID = "3212AA74",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200020/3212AA74"
        },
        [20002101] = {
          ContentJP = "<Default note=\"text:エジュウ\">穢獣</>どもが半殺しに……恐らくだがサイキと戦ったんだろう。",
          DialogueId = 20002101,
          GUID = "3212BAB2",
          NextDialogue = 20002102,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200021/3212BAB2"
        },
        [20002102] = {
          ContentJP = "<Default note=\"text:エジュウ\">穢獣</>が逃げてきたのと反対方向に進めば、サイキが見つかるはずだ……",
          DialogueId = 20002102,
          GUID = "3212BADC",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200021/3212BADC"
        },
        [20002201] = {
          Content = "兄弟，你还好吗。",
          DialogueId = 20002201,
          ExStoryInfo = "Player",
          GUID = "3212CB1A",
          NextDialogue = 20002202,
          SpeakNpcId = 100001
        },
        [20002202] = {
          Content = "不太好。",
          DialogueId = 20002202,
          GUID = "3212CB44",
          NextDialogue = 20002203
        },
        [20002203] = {
          Content = "外面情况怎么样？",
          DialogueId = 20002203,
          GUID = "3212CB6E",
          NextDialogue = 20002204
        },
        [20002204] = {
          Content = "刮了好大的风，秽兽的行为也很反常。",
          DialogueId = 20002204,
          GUID = "3212CB98"
        },
        [20002301] = {
          ContentJP = "（理性を失ったサイキが、いままさに穢蝕と戦っている……何か彼女のためにできることは……）",
          DialogueId = 20002301,
          DisableMouth = 1,
          GUID = "3212DB82"
        },
        [20002401] = {
          ContentJP = "……サイキは街の外に向かったみたいね。",
          DialogueId = 20002401,
          GUID = "3212EBEA",
          NextDialogue = 20002402,
          SpeakNpcId = 700049
        },
        [20002402] = {
          ContentJP = "郊外ならあまり人がいないから。できるだけ人気のない場所に向かったんだと思う。まだ理性が残っているうちに……",
          DialogueId = 20002402,
          GUID = "3212EC14",
          SpeakNpcId = 700049
        },
        [20002501] = {
          ContentJP = "……サイキを探しに行くの？",
          DialogueId = 20002501,
          GUID = "3212FC52",
          NextDialogue = 20002502,
          SpeakNpcId = 200045
        },
        [20002502] = {
          ContentJP = "あの子を見つけたら、どうかためらわないで。苦しみを終わらせてあげて。あの子もきっとそう望んでいるはずだから……",
          DialogueId = 20002502,
          GUID = "3212FC7C",
          SpeakNpcId = 200045
        },
        [20002601] = {
          ContentJP = "さっきのお姉ちゃん、どうしてあんなに走るの速いの？",
          DialogueId = 20002601,
          GUID = "32130CBA",
          NextDialogue = 20002602,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc1",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CBA"
        },
        [20002602] = {
          ContentJP = "いいから急ぐぞ、早く街に入るんだ。あ、あれは穢蝕者だ！",
          DialogueId = 20002602,
          GUID = "32130CE4",
          NextDialogue = 20002603,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc2",
          VoiceName = "voice/$Locale$/story/2001/200026/32130CE4"
        },
        [20002603] = {
          ContentJP = "だ、だだ……大丈夫だ。警備部隊にはもう通報してある。",
          DialogueId = 20002603,
          GUID = "32130D0E",
          NextDialogue = 20002604,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc3",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D0E"
        },
        [20002604] = {
          ContentJP = "どさくさに紛れてアイスレイク城に入ろうったってそうはいかないぞ。通行許可証を出せ！",
          DialogueId = 20002604,
          GUID = "32130D38",
          NextDialogue = 20002605,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc4",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D38"
        },
        [20002605] = {
          ContentJP = "お願いします、街に入れてください。通行許可証をうっかりなくしてしまって……本当なんです。",
          DialogueId = 20002605,
          GUID = "32130D62",
          NextDialogue = 20002606,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc5",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D62"
        },
        [20002606] = {
          ContentJP = "こんな時まで通行許可証って……。このまま外にいても死ぬだけなんだから、無理やりにでもなかに入ってやるわ！",
          DialogueId = 20002606,
          GUID = "32130D8C",
          NextDialogue = 20002607,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc6",
          VoiceName = "voice/$Locale$/story/2001/200026/32130D8C"
        },
        [20002607] = {
          ContentJP = "と、止まれ！これ以上近づくと撃つぞ！",
          DialogueId = 20002607,
          GUID = "32130DB6",
          NextDialogue = 20002608,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc7",
          VoiceName = "voice/$Locale$/story/2001/200026/32130DB6"
        },
        [20002608] = {
          ContentJP = "撃ちたきゃ撃ちなよ！銃声が穢蝕者を引き寄せてみんな一緒にみなごろしさ！",
          DialogueId = 20002608,
          GUID = "32130DE0",
          NextDialogue = 20002609,
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc8",
          VoiceName = "voice/$Locale$/story/2001/200026/32130DE0"
        },
        [20002609] = {
          ContentJP = "そ、それは……。まあいいだろう。警備部隊が穢蝕者を排除するまで、とりあえずは街に入れ。",
          DialogueId = 20002609,
          GUID = "32130E0A",
          SpeakNpcName = "UI_Npc_Name_FindSaiqiNpc9",
          VoiceName = "voice/$Locale$/story/2001/200026/32130E0A"
        },
        [20002701] = {
          ContentJP = "すげえ風だ……飛びおりても風に戻されちまう。",
          DialogueId = 20002701,
          GUID = "32131D22",
          NextDialogue = 20002702,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200027/32131D22"
        },
        [20002702] = {
          ContentJP = "あっちだ。エレベーターを使おう。",
          DialogueId = 20002702,
          GUID = "32131D4C",
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200027/32131D4C"
        },
        [20002801] = {
          ContentJP = "そう心配すんなよ。サイキのいる場所は見当ついてるし、追いつけばなんとかなるさ。",
          DialogueId = 20002801,
          Duration = 3,
          GUID = "32132D8A",
          NextDialogue = 20002802,
          SpeakNpcId = 200021,
          VoiceName = "voice/$Locale$/story/2001/200028/32132D8A"
        },
        [20002802] = {
          ContentJP = "そうそう。サイキに会えれば必ず方法はあるはずだよ！",
          DialogueId = 20002802,
          Duration = 3,
          GUID = "32132DB4",
          NextDialogue = 20002803,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200028/32132DB4"
        },
        [20002803] = {
