          VoiceName = "voice/$Locale$/story/2001/200055/3214E8AC"
        },
        [20005503] = {
          ContentJP = "いますぐここでキノコ探しを披露したいところですが、こんなに寒いんじゃキノコは生えてないでしょうね……",
          DialogueId = 20005503,
          GUID = "3214E8D6",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200055/3214E8D6"
        },
        [20005504] = {
          ContentJP = "家族はいません。物心がつく前に離ればなれになってしまったので、彼らの記憶はほとんどないんです。だから、ヘーゼルナッツが私の唯一の家族です！",
          DialogueId = 20005504,
