        [20006102] = {
          Camera = "-765.013428,-719.638672,299.876953,0.000206,6.008906,158.560791,35.000008,174.116943,false,Manual,2.8",
          ContentJP = "しーっ、静かに。相手に気づかれたらどうする{性别:んだ|の}。あのジェネモンが口を利けたら、きっと今頃君をバカだって罵ってるよ。",
          DialogueId = 20006102,
