          TalkActionId = {
            [1] = "200074:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200061/32154B70"
        },
        [20006105] = {
          ContentJP = "動物やジェネモンにも、感情があることをみんなが分かってくれたら、彼らを狩る人たちもいなくなるのに……",
          DialogueId = 20006105,
          GUID = "32154B9A",
          NextDialogue = 20006106,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Talk02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200061/32154B9A"
        },
        [20006106] = {
          Camera = "-748.335205,-586.757812,281.619141,0.000205,0.81006,175.165253,35.000008,174.116943,false,Manual,2.8",
          ContentJP = "いきましょう。今度こそ彼らに反省してもらわなくちゃ！",
