          VoiceName = "voice/$Locale$/story/2001/200061/32154BC4"
        },
        [20006201] = {
          Camera = "-287.4375,38.861328,166.546265,0.000031,-8.400183,-1.804748,18.000004,100000.0,false,Manual,2.8",
          ContentJP = "すごく入り組んだ下水道ですね……ヘーゼルナッツ、ジェネモンの場所は分かる？",
          DialogueId = 20006201,
          GUID = "32155B5A",
          NextDialogue = 20006202,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200062/32155B5A"
        },
        [20006202] = {
          ContentJP = "ブヒッ……",
          DialogueId = 20006202,
          GUID = "32155B84",
          NextDialogue = 20006203,
          SpeakNpcId = 200086,
          VoiceName = "voice/$Locale$/story/2001/200062/32155B84"
        },
        [20006203] = {
          ContentJP = "匂いが多すぎて方角が分からない？うーん、このまま進むしかないようですね。",
          DialogueId = 20006203,
          GUID = "32155BAE",
          NextDialogue = 20006204,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200062/32155BAE"
        },
        [20006204] = {
          ContentJP = "ここには詳しいんだ、スノウに任せて！",
          DialogueId = 20006204,
          GUID = "32155BD8",
          NextDialogue = 20006205,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200062/32155BD8"
        },
        [20006205] = {
          ContentJP = "詳しい？なるほど、スノウちゃんはこういう場所に住んでいるんですね？",
          DialogueId = 20006205,
          GUID = "32155C02",
          NextDialogue = 20006206,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200062/32155C02"
        },
        [20006206] = {
          ContentJP = "ち、ちがう！何度か視察に来ただけだ。さあジェネモンハンターハンターよ、この魔王様についてくるがいい！",
          DialogueId = 20006206,
          GUID = "32155C2C",
          NextDialogue = 20006207,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200062/32155C2C"
        },
        [20006207] = {
          ContentJP = "了解！",
          DialogueId = 20006207,
          GUID = "32155C56",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200062/32155C56"
        },
        [20006301] = {
          ContentJP = "ん？この痕は……？視察の時にはなかったものだな。",
          DialogueId = 20006301,
          GUID = "32156BC2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 20006302,
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200063/32156BC2"
        },
        [20006302] = {
          ContentJP = "捕まったジェネモンが残したもののようですね。これを辿ってみましょう！",
          DialogueId = 20006302,
          GUID = "32156BEC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200063/32156BEC"
        },
        [20006401] = {
          ContentJP = "痕跡が新しい――かなり近くまで来ているかと……",
          DialogueId = 20006401,
          GUID = "32157C2A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 20006402,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200064/32157C2A"
        },
        [20006402] = {
          ContentJP = "むむ？何やら話し声が――",
          DialogueId = 20006402,
          GUID = "32157C54",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 200002,
          VoiceName = "voice/$Locale$/story/2001/200064/32157C54"
        },
        [20006501] = {
          Camera = "802.462891,37.094727,399.100616,0.000002,-18.600189,1.600099,35.000011,403.34671,false,Manual,12.0",
          ContentJP = "こいつはジェネモンの中でも一番賢くて、珍しい、すべてのジェネモンのオリジナル――パーンだ。",
          DialogueId = 20006501,
          FinalCamera = "559.453125,30.306641,481.861816,0.000002,-18.800184,1.600099,35.000011,403.34671,false,Manual,12.0",
          GUID = "32158C92",
          NextDialogue = 20006502,
          SpeakNpcId = 200075,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158C92"
        },
        [20006502] = {
          ContentJP = "賢い？僕たちに捕まったのに、ですか？",
          DialogueId = 20006502,
          GUID = "32158CBC",
          NextDialogue = 20006503,
          SpeakNpcId = 200087,
          TalkActionId = {
            [1] = "200087:Talk02_Start"
