          NextDialogue = 20006504,
          SpeakNpcId = 200075,
          TalkActionId = {
            [1] = "200075:Talk03_Start",
            [2] = "200087:Talk02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200065/32158CE6"
        },
        [20006504] = {
          Camera = "485.179688,62.989258,489.663513,0.000012,-12.999386,-2.199652,35.000008,450.0,false,Manual,6.0",
          ContentJP = "まさか！アニキの完璧な罠があったから、これだけたくさんのジェネモンを捕まえられたんじゃないですか。",
          DialogueId = 20006504,
          FinalCamera = "610.728516,58.283203,460.538757,0.000012,-13.199401,-1.999653,35.000008,450.0,false,Manual,6.0",
          GUID = "32158D10",
          LookAt = {
            [1] = "200087:n(200075)"
          },
          NextDialogue = 20006505,
          SpeakNpcId = 200087,
          TalkActionId = {
            [1] = "200087:Shock_Start"
          },
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/story/2001/200065/32158D10"
        },
        [20006505] = {
          ContentJP = "ふん、当然だ。さて、これだけのジェネモンがいれば、月ノ石を錬成する方法も見つかるだろう。そして、その過程を論文に残すんだ。",
          DialogueId = 20006505,
          GUID = "32158D3A",
          LookAt = {
            [1] = "200075:n(200075)"
          },
          NextDialogue = 20006506,
          SpeakNpcId = 200075,
          TalkActionId = {
            [1] = "200087:Shock_End",
            [2] = "200075:Talk03_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158D3A"
        },
        [20006506] = {
          ContentJP = "もう誰にも錬金院の落ちこぼれとは言わせねえぞ！",
          DialogueId = 20006506,
          GUID = "32158D64",
          NextDialogue = 20006507,
          SpeakNpcId = 200075,
          TalkActionId = {
            [1] = "200075:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200065/32158D64"
        },
        [20006507] = {
          ContentJP = "僕は論文には興味ないので、報酬の分け前さえもらえれば……",
          DialogueId = 20006507,
          GUID = "32158D8E",
          NextDialogue = 20006508,
          SpeakNpcId = 200087,
