          ContentJP = "そっか、じゃあ気を付けて。",
          DialogueId = 20006727,
          FinalCamera = "-42.253906,-50.19043,126.079941,0.000077,5.591746,-137.192566,35.000011,450.0,false,Manual,6.0",
