          SpeakNpcId = 700248,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEC4"
        },
        [20007003] = {
          Camera = "855.156494,437.582031,235.363281,-0.000335,-12.202781,-167.746658,35.000008,369.08606,false,Manual,12.0",
          ContentJP = "トリュフとヘーゼルナッツを見て思いついた{性别:んだ|の}。ヘーゼルナッツが人間と仲良くなれるのなら、他のジェネモンだってきっと同じだってね。",
          DialogueId = 20007003,
          GUID = "3215DEEE",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007004,
          Scripts = [[
SEQ{
PlayAnimation{_delay{1},ActorId{700248},AnimationId{"Talk02_End"},Duration{1}}
}]],
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DEEE"
        },
        [20007004] = {
          Camera = "385.531738,327.31543,122.824219,-0.000336,8.596824,174.251282,35.0,369.08606,false,Manual,12.0",
          ContentJP = "それに、ジェネモンと人間が仲良くなれれば、カロン族とソラの民も、いつかはわかり合えるんじゃないかと思って。",
          DialogueId = 20007004,
          GUID = "3215DF18",
          NextDialogue = 20007005,
          Scripts = "PlayFacial{_delay{0.5},ActorId{700248},FacialId{\"Smile01\"}}",
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF18"
        },
        [20007005] = {
          Camera = "271.747681,244.423828,145.421875,0.000091,0.396629,32.112232,35.0,369.08606,false,Manual,12.0",
          ContentJP = "ふふ、ほんと、あなたってほんと、天然なのか計算高いのか分からないわ。まあ、その前に、まずはあの子にお別れを言わなきゃね。",
          DialogueId = 20007005,
          FinalCamera = "134.401306,153.286133,129.798828,-0.000336,-0.203833,31.850718,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DF42",
          NextDialogue = 20007006,
          Scripts = [[
SEQ{
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_Start"},Duration{2}},
PlayAnimation{_delay{0.5},ActorId{700248},AnimationId{"Sigh_End"},Duration{1}}}]],
          SpeakNpcId = 700248,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF42"
        },
        [20007006] = {
          Camera = "721.993774,408.491211,205.130859,0.00002,-14.403127,-165.088608,35.0,369.08606,false,Manual,12.0",
          ContentJP = "ううう……トリュフ、本当に出ていくのか？せっかくこの光の魔王にノってくれる仲間を見つけたというのに！",
          DialogueId = 20007006,
          FacialId = {
            [1] = "200002:Sad01"
          },
          GUID = "3215DF6C",
          NextDialogue = 20007007,
          SpeakNpcId = 200002,
          TurnTo = {
            [1] = "200074:p(30)"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF6C"
        },
        [20007007] = {
          ContentJP = "泣かないで、スノウちゃん。私は帰らないといけませんが、ここにはジェネモン博士になった元ジェネモンハンターたちがいるでしょう。",
          DialogueId = 20007007,
          GUID = "3215DF96",
          NextDialogue = 20007008,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DF96"
        },
        [20007008] = {
          Camera = "428.352539,486.96582,156.205078,0.000078,-8.003704,-124.08696,35.0,369.08606,false,Manual,12.0",
          ContentJP = "お前とは比べ物にもならないぞ。それに、ヘーゼルナッツに乗って散歩できなくなるし……{nickname}、お前も突っ立ってないで、一緒に引き留めてよ！",
          DialogueId = 20007008,
          FacialId = {
            [1] = "200002:Unhappy01"
          },
          GUID = "3215DFC0",
          NextOptions = {
            [1] = 200070081
          },
          SpeakNpcId = 200002,
          TalkActionId = {
            [1] = "700248:Think_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFC0"
        },
        [20007009] = {
          Camera = "322.5,503.43457,157.886719,0.000066,-8.003506,-99.487526,35.000008,369.08606,false,Manual,12.0",
          ContentJP = "ふふ、また遊びに来ますから。{性别:お兄さん|お姉さん}にだけこっそり教えますね……実は私、エリュシオン礼賛会から来たんです。",
          DialogueId = 20007009,
          FacialId = {
            [1] = "200002:CM_Idle"
          },
          FinalCamera = "316.476074,471.517578,153.757812,0.000067,-8.603483,-101.087669,35.000008,369.08606,false,Manual,12.0",
          GUID = "3215DFEA",
          LookAt = {
            [1] = "200074:n(100001)"
          },
          NextDialogue = 20007010,
          SpeakNpcId = 200074,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/story/2001/200070/3215DFEA"
        },
        [20007010] = {
          Camera = "-189.593018,180.383789,233.115234,0.000085,-10.602577,9.713165,35.0,369.08606,false,Manual,12.0",
          ContentJP = "ヘーゼルナッツと一緒に食べ物を探していると、たまに見張りのいない山を越えて、ヒュペリアまで来ることがあるんです。最初はちょっぴり怖かったんですよ。礼賛会と帝国はまだ戦争中だから……",
          DialogueId = 20007010,
          GUID = "3215E014",
          NextDialogue = 20007011,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E014"
        },
        [20007011] = {
          ContentJP = "でも{性别:お兄さん|お姉さん}と会ってからは、全然怖くなくなりました。",
          DialogueId = 20007011,
          GUID = "3215E03E",
          NextDialogue = 20007012,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E03E"
        },
        [20007012] = {
          ContentJP = "ジェネモンと人間が共存できる方法を見つけてくれた{性别:お兄さん|お姉さん}なら、きっとカロン族とソラの対立や、帝国と礼賛会の戦争を終わらせることができると信じてます。",
          DialogueId = 20007012,
          GUID = "3215E068",
          NextDialogue = 20007013,
          SpeakNpcId = 200074,
          TalkActionId = {
            [1] = "200074:Explain02_End"
          },
          VoiceName = "voice/$Locale$/story/2001/200070/3215E068"
        },
        [20007013] = {
          ContentJP = "そうなれば、お腹を空かせる人もいなくなりますから！",
          DialogueId = 20007013,
          GUID = "3215E092",
          NextDialogue = 20007014,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E092"
        },
        [20007014] = {
          ContentJP = "その時は是非、スノウちゃんやカミラさんと一緒に南に遊びに来て下さい。可愛いピンクのキノコを食べたり、暖かい海風を浴びたり、ここでは見られない星を眺めましょう！待ってますからね！",
          DialogueId = 20007014,
          GUID = "3215E0BC",
          NextDialogue = 20007015,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0BC"
        },
        [20007015] = {
          ContentJP = "うん、頑張るよ。",
          DialogueId = 20007015,
          GUID = "3215E0E6",
          NextDialogue = 20007016,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E0E6"
        },
        [20007016] = {
          ContentJP = "指切りげんまん！",
          DialogueId = 20007016,
          GUID = "3215E110",
          NextOptions = {
            [1] = 200070161
          },
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E110"
        },
        [20007017] = {
          ContentJP = "ヘーゼルナッツとも指切りしてください。",
          DialogueId = 20007017,
          GUID = "3215E13A",
          NextDialogue = 20007018,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E13A"
        },
        [20007018] = {
          ContentJP = "さすがに無理かな。",
          DialogueId = 20007018,
          GUID = "3215E164",
          NextDialogue = 20007019,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E164"
        },
        [20007019] = {
          ContentJP = "なら、足を握るだけでいいですよ。ほら、一緒に、指切りげんまん～嘘ついたら針千本の～ます。指切った！",
          DialogueId = 20007019,
          GUID = "3215E18E",
          NextDialogue = 20007020,
          SpeakNpcId = 200074,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E18E"
        },
        [20007020] = {
          ContentJP = "ブヒッ！",
          DialogueId = 20007020,
          GUID = "3215E1B8",
          SpeakNpcId = 200086,
          VoiceName = "voice/$Locale$/story/2001/200070/3215E1B8"
        },
        [20007101] = {
          ContentJP = "我は、アイスレイク城いちのジェネモン博士！ジェネモンに関することは、なんでも俺に――あ、お前……な、何か用か？",
          DialogueId = 20007101,
          GUID = "3215EF02",
          NextOptions = {
            [1] = 200071011,
            [2] = 200071012,
            [3] = 200071013
          },
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF02"
        },
        [20007102] = {
          ContentJP = "あの賢いジェネモンのことか？",
          DialogueId = 20007102,
          GUID = "3215EF2C",
          NextDialogue = 20007103,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF2C"
        },
        [20007103] = {
          ContentJP = "俺もあの時初めて見たんだが、あれに関する記録はほとんどないんだ。彼らは認めた相手の前にしか姿を現さないとか。",
          DialogueId = 20007103,
          GUID = "3215EF56",
          NextDialogue = 20007104,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF56"
        },
        [20007104] = {
          ContentJP = "でも、お前ならあいつらが残した痕跡を辿って隠れ家を見つけられるんじゃないか？",
          DialogueId = 20007104,
          GUID = "3215EF80",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EF80"
        },
        [20007105] = {
          ContentJP = "ジェネモンハンターなんかより百倍マシだ。毎日色んな人からジェネモンのことを聞かれるんだ。本物の博士になった気分だよ。",
          DialogueId = 20007105,
          GUID = "3215EFAA",
          NextDialogue = 20007106,
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFAA"
        },
        [20007106] = {
          ContentJP = "お前とトリュフちゃんが手加減してくれたおかげだな。ありがとよ。",
          DialogueId = 20007106,
          GUID = "3215EFD4",
          SpeakNpcId = 200075,
          SpeakNpcName = "UI_CMNpc_Name_MolingXZ",
          VoiceName = "voice/$Locale$/story/2001/200071/3215EFD4"
        },
        [20007107] = {
          Content = "若干道深深的刻痕，似是某周尖锐物体留下的痕迹。",
          DialogueId = 20007107,
          GUID = "3215EFD5"
        },
        [20007108] = {
          Content = "写着“禁区危险，严禁通行”的告示。贴了厚厚一叠，似乎是当老告示变旧了就会贴一张新告示上去。最新的一张告示落款是新历1004年，也就是二十年前——格雷姆矿场应当就是在那时彻底废弃的。",
          DialogueId = 20007108,
          GUID = "3215EFD6"
        },
        [21000101] = {
          Content = "背白白进场台词（测试用）",
          DialogueId = 21000101,
          GUID = "34925112",
          TalkActionId = {
            [1] = "900005:Beibao_Start"
          }
        },
        [21000102] = {
          Content = "背白白退场台词（测试用）",
          DialogueId = 21000102,
          GUID = "3492513C",
          TalkActionId = {
            [1] = "900005:Beibao_Finish"
          }
        },
        [50000101] = {
          ContentJP = "通行許可証を――おい、お前だよお前。通行許可証は持っているんだろうな？",
          DialogueId = 50000101,
          Duration = 3,
          GUID = "7D2B8592",
          SpeakNpcId = 700111,
          Subtitle = "Travel permit check — oi, I'm talking to you! Got your travel permit on you?",
          VoiceName = "voice/$Locale$/env/700002/7D2B8592"
        },
        [50000201] = {
          ContentJP = "月狩り人がよくここを見つけたな。お前さん、英雄になれる素質があるぞ。\nあいつらみたいな。",
          DialogueId = 50000201,
          Duration = 4,
          GUID = "7D2B95FA",
          SpeakNpcId = 700003,
          Subtitle = "A Phoxhunter? Can't believe anyone would still make it here. You've got what it takes to be a hero like them, I guess.",
          VoiceName = "voice/$Locale$/env/700003/7D2B95FA"
        },
        [50000301] = {
          ContentJP = "**なグランドのせいだ！いったいどうすれば……\nん？なんだね？今日は依頼はないぞ。",
          DialogueId = 50000301,
          Duration = 3,
          GUID = "7D2BA662",
          SpeakNpcId = 700004,
          Subtitle = "D*mn it, it's all Grandet's fault! What am I supposed to do now... Hm? What are you looking at? I've got no work for you today!",
          VoiceName = "voice/$Locale$/env/700004/7D2BA662"
        },
        [50000401] = {
          ContentJP = "私の名前は……アニー、なの？",
          DialogueId = 50000401,
          Duration = 3,
          GUID = "7D2BB6CA",
          SpeakNpcId = 700032,
          Subtitle = "My name is... Annie?",
          TalkActionId = {
            [1] = "700032:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700032/7D2BB6CA"
        },
        [50000501] = {
          ContentJP = "体調が回復したら、旅を再開するつもりです。",
          DialogueId = 50000501,
          Duration = 3,
          GUID = "7D2BC732",
          SpeakNpcId = 700005,
          Subtitle = "As soon as I'm back in form, I'm off on another adventure.",
          TalkActionId = {
            [1] = "700032:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BC732"
        },
        [50000601] = {
          ContentJP = "お母さんに会ったら何から話そうかな……きっと、すごく心配しているはず。",
          DialogueId = 50000601,
          Duration = 3,
          GUID = "7D2BD79A",
          SpeakNpcId = 700005,
          Subtitle = "What gift should I get for Elsa... She must've missed me terribly.",
          TalkActionId = {
            [1] = "700005:Think_Start"
          },
          VoiceName = "voice/$Locale$/env/700005/7D2BD79A"
        },
        [50000701] = {
          ContentJP = "アニー……アニー！",
          DialogueId = 50000701,
          Duration = 3,
          GUID = "7D2BE802",
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          VoiceName = "voice/$Locale$/env/700006/7D2BE802"
        },
        [50000801] = {
          ContentJP = "今日のお花はとてもきれいね。あの子のために何本か残しておこうかしら。",
          DialogueId = 50000801,
          Duration = 3,
          GUID = "7D2BF86A",
          SpeakNpcId = 700007,
          Subtitle = "The flowers today are quite lovely. I should save a few for that kid.",
          TalkActionId = {
            [1] = "700007:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700007/7D2BF86A"
        },
        [50000901] = {
          ContentJP = "いらっしゃいませ。あなたの服装に合わせるなら、今日はこちらのお花がピッタリですよ……あの子がいたら、きっとこう言うはずです。",
          DialogueId = 50000901,
          Duration = 5,
          GUID = "7D2C08D2",
          SpeakNpcId = 700203,
          Subtitle = "Good day, you look great with this flower... That kid would have said so, if she were still here.",
          VoiceName = "voice/$Locale$/env/700007/7D2C08D2"
        },
        [50001001] = {
          ContentJP = "その恵まれたルックスとスタイル！私の店の服を着ないなんて、もったいないですよ！",
          DialogueId = 50001001,
          Duration = 3,
          GUID = "7D2C193A",
          SpeakNpcId = 700008,
          Subtitle = "Hello, gorgeous! I bet you'd be a vision in our apparel.",
          VoiceName = "voice/$Locale$/env/700008/7D2C193A"
        },
        [50001101] = {
          ContentJP = "自家農園の最高フルーツ！よそにはまねできない栽培技術で育てた一級品だ！",
          DialogueId = 50001101,
          Duration = 3,
          GUID = "7D2C29A2",
          SpeakNpcId = 700009,
          Subtitle = "Try these fine fruits from our orchard — grown with unmatched cultivation techniques!",
          TalkActionId = {
            [1] = "700009:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700009/7D2C29A2"
        },
        [50001201] = {
          ContentJP = "あ……わ、わ、私……",
          DialogueId = 50001201,
          Duration = 2,
          GUID = "7D2C3A0A",
          SpeakNpcId = 700010,
          Subtitle = "Ah... whoa, I... um...",
          VoiceName = "voice/$Locale$/env/700010/7D2C3A0A"
        },
        [50001301] = {
          ContentJP = "よし……栄えある実験体第1号は君に決まりだ！",
          DialogueId = 50001301,
          Duration = 3,
          GUID = "7D2C4A72",
          SpeakNpcId = 700011,
          Subtitle = "Hmm... I've made up my mind — hello, Test subject No. 1!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C4A72"
        },
        [50001401] = {
          ContentJP = "{NickName}、また会ったね！僕は新しい知識を学んでいるところさ！お互い頑張ろう！",
          DialogueId = 50001401,
          Duration = 4,
          GUID = "7D2C5ADA",
          SpeakNpcId = 700011,
          Subtitle = "lovely to see you again! I'm trying my best to learn new things every day, let's keep at it!",
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700011/7D2C5ADA"
        },
        [50001501] = {
          ContentJP = "あなたは……カロン……私と同族……",
          DialogueId = 50001501,
          Duration = 6,
          GUID = "7D2C6B42",
          SpeakNpcId = 700012,
          Subtitle = "Are we... the same kind?",
          VoiceName = "voice/$Locale$/env/700012/7D2C6B42"
        },
        [50001601] = {
          ContentJP = "表沙汰にできない物事は嫌というほど見てきたけど。関わっていたのは「悪魔」だけじゃない……時々わからなくなるの。ヒトとカロン、どちらが悪魔なのかしら。",
          DialogueId = 50001601,
          Duration = 4,
          GUID = "7D2C7BAA",
          SpeakNpcId = 700013,
          Subtitle = [[
I've witnessed deeds that daylight never sees, and not all are the work of "demons".
...Sometimes, between humans and Charons, I can't tell which is the true demon.]],
          VoiceName = "voice/$Locale$/env/700013/7D2C7BAA"
        },
        [50001701] = {
          ContentJP = "チッ！モノの価値がわからない年増女め！いつまでもいきがれると思うなよ！",
          DialogueId = 50001701,
          Duration = 4,
          GUID = "7D2C8C12",
          SpeakNpcId = 700014,
          Subtitle = "Pah! Stupid hag! Let's see how long you can keep this charade up!",
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/env/700014/7D2C8C12"
        },
        [50001801] = {
          ContentJP = "神よ、なぜだ！善なる者の私になぜ、無限のインスピレーションを盗み取る悪しき魂を遣わしたのだ\n！これは万物を司る大いなる神が見ても、悲嘆の涙を流すほどの冤罪ではなかろうか！",
          DialogueId = 50001801,
          Duration = 4,
          GUID = "7D2C9C7A",
          SpeakNpcId = 700015,
          Subtitle = "Good grief! Who'd have thought a gentle soul like myself would be beset by an inspiration-stealing spectre?! Such wretchedness would surely draw heaven's own tears!",
          VoiceName = "voice/$Locale$/env/700015/7D2C9C7A"
        },
        [50001901] = {
          ContentJP = "つまんないの！こんな上っ面だけの儀式を繰りかえしてさ！こんなことより半日休みにして欲しいよ。",
          DialogueId = 50001901,
          Duration = 3,
          GUID = "7D2CACE2",
          SpeakNpcId = 700016,
          Subtitle = "What a drag! Who arranged these pointless events? I'd rather have half a day off!",
          VoiceName = "voice/$Locale$/env/700016/7D2CACE2"
        },
        [50002001] = {
          ContentJP = "「雨がふりました。お母さんのお花は、ぬれてしょんぼりしています。おわびに、空は、水たまりにたくさんのお花を咲かせて、お母さんにあやまったのでした」",
          DialogueId = 50002001,
          Duration = 3,
          GUID = "7D2CBD4A",
          NextDialogue = 50002002,
          SpeakNpcId = 700017,
          Subtitle = "\"The rain hurt Mum's flowers, so the sky said sorry by leaving her lots of tiny flowers in the puddles.\"",
          VoiceName = "voice/$Locale$/env/700017/7D2CBD4A"
        },
        [50002002] = {
          ContentJP = "ねえ知ってる？この詩の題名は『ごめんね』。6歳の生徒が書いた作品なの。",
          DialogueId = 50002002,
          Duration = 3,
          GUID = "7D2CBD74",
          SpeakNpcId = 700017,
          Subtitle = "You know what, this little verse is called \"Apology\", and it's written by a six-year-old student of mine.",
          TalkActionId = {
            [1] = "700017:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700017/7D2CBD74"
        },
        [50002101] = {
          ContentJP = "自然の摂理に逆らい天へ石を投げようとも、最終的には必ず返ってきて、自分の頭に当たるものなのです。",
          DialogueId = 50002101,
          Duration = 3,
          GUID = "7D2CCDB2",
          SpeakNpcId = 700018,
          Subtitle = "The rocks cast against the laws of nature will inevitably fall back on one's own head.",
          TalkActionId = {
            [1] = "700018:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/env/700018/7D2CCDB2"
        },
        [50002201] = {
          ContentJP = "どこに行ってしまったの……",
          DialogueId = 50002201,
          Duration = 3,
          GUID = "7D2CDE1A",
          SpeakNpcId = 700019,
          Subtitle = "Where could he have gone off to...",
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700019/7D2CDE1A"
        },
        [50002301] = {
          ContentJP = "今夜はマッシュルームのクリームスープよ。おいしいスープで奥様の心が少しでも安らぎますように……",
          DialogueId = 50002301,
          Duration = 4,
          GUID = "7D2CEE82",
          SpeakNpcId = 700020,
          Subtitle = "I hope tonight's creamy mushroom soup will bring some comfort to her ladyship.",
          TalkActionId = {
            [1] = "700020:Agree"
          },
          VoiceName = "voice/$Locale$/env/700020/7D2CEE82"
        },
        [50002401] = {
          ContentJP = "かわいそうに……毎日、気も狂わんばかりのご様子で......",
          DialogueId = 50002401,
          Duration = 3,
          GUID = "7D2CFEEA",
          NextDialogue = 50002402,
          SpeakNpcId = 700023,
          Subtitle = "Poor thing, having lost her mind like that.",
          VoiceName = "voice/$Locale$/env/700023/7D2CFEEA"
        },
        [50002402] = {
          ContentJP = "正直言って過保護過ぎるような……娘さんが耐えられなかったのもわかる気がしますね……",
          DialogueId = 50002402,
          Duration = 3,
          GUID = "7D2CFF14",
          SpeakNpcId = 700024,
          Subtitle = "No wonder her daughter had left.",
          VoiceName = "voice/$Locale$/env/700024/7D2CFF14"
        },
        [50002501] = {
          ContentJP = "街全体のゴミ箱は、その中のお宝も含めて、このマーティンが丸っと管理しておりますよ！\n数回しか履いてないシカ皮のブーツ、まだ生き生きと咲くユリの花、さらには誰かの砕けた夢の欠片まで……",
          DialogueId = 50002501,
          Duration = 3,
          GUID = "7D2D0F52",
          SpeakNpcId = 700115,
          Subtitle = "I oversee all the rubbish bins around the city, and oh, the treasures to be found in each of them! Nearly new deerskin boots, still-fresh lilies, and the fragments of someone's shattered dreams...",
          TalkActionId = {
            [1] = "700115:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700022/7D2D0F52"
        },
        [50002601] = {
          ContentJP = "まもなく、次の駅に向かう列車が出発いたします。切符はこちらで――なんですって？おカネがない？だったら早く白昼夢から目覚めてくださいませ！お帰りはあちらになります！",
          DialogueId = 50002601,
          Duration = 5,
          GUID = "7D2D0F53",
          SpeakNpcId = 700021,
          Subtitle = "The train to the next station is about to depart. Please process your ticket purchase here — What's that? You've got no money? Then less dreaming, more moving, if you please!",
          TalkActionId = {
            [1] = "700021:Confident_Start"
          }
        },
        [50002701] = {
          ContentJP = "13号パイプの修理中だ。やれやれ、なかはネズミがうじゃうじゃいるぞ。",
          DialogueId = 50002701,
          Duration = 4,
          GUID = "7D2D3022",
          SpeakNpcId = 700069,
          Subtitle = "Pipe No. 13 is under repair — blimey, it's swarming with rats in there.",
          TalkActionId = {
            [1] = "700069:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700069/7D2D3022"
        },
        [50002801] = {
          ContentJP = "失せろ！卑しいカロンめ！",
          DialogueId = 50002801,
          DialoguePanelType = "{type:Bubble;style:ExcitedBubble}",
          Duration = 3,
          GUID = "7D2D408A",
          SpeakNpcId = 700068,
          Subtitle = "Beat it, dirty Charon!",
          VoiceName = "voice/$Locale$/env/700068/7D2D408A"
        },
        [50002901] = {
          ContentJP = "あぁ……血の跡がどうしても落ちないんだよ。",
          DialogueId = 50002901,
          Duration = 3,
          GUID = "7D2D50F2",
          SpeakNpcId = 700067,
          Subtitle = "Ugh... why won't this bloodstain come off?",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700067/7D2D50F2"
        },
        [50003001] = {
          Content = "凶猛的狼咆哮着 撕咬着狡猾的狗",
          DialogueId = 50003001,
          Duration = 3,
          GUID = "7D2D615A",
          NextDialogue = 50003002,
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D615A"
        },
        [50003002] = {
          Content = "狡猾的狗呜咽着 啃食着腐朽的肉",
          DialogueId = 50003002,
          Duration = 3,
          GUID = "7D2D6184",
          SpeakNpcId = 700071,
          TalkActionId = {
            [1] = "700071:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700071/7D2D6184"
        },
        [50003101] = {
          Content = "您也喜欢这些百合吗？",
          DialogueId = 50003101,
          Duration = 3,
          GUID = "7D2D71C2",
          SpeakNpcId = 700072,
          TalkActionId = {
            [1] = "700072:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700072/7D2D71C2"
        },
        [50003201] = {
          ContentJP = "お城の外の怪物は、僕らの肉を食べちゃう～お城のなかの怪物は、僕らの毛をむしっちゃう～\n猟犬はふかふかパンを食ってるけど～哀れな羊の僕たちは、地面の草を食むだけさ～",
          DialogueId = 50003201,
          Duration = 3,
          GUID = "7D2D822A",
          NextDialogue = 50003202,
          SpeakNpcId = 700073,
          Subtitle = "♪ \"Monsters beyond the walls feast on our flesh; the ones within shear our fleece. While the hounds dine on fine white loaves; we lowly sheep are content with chewing grass...\"",
          TalkActionId = {
            [1] = "700073:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700073/7D2D822A"
        },
        [50003202] = {
          ContentJP = "ちょっ…黙りなさい！誰からそんな歌を教わったのやら……そのうちあんたのせいで私たちふたりとも酷い目にあうだろうよ。",
          DialogueId = 50003202,
          Duration = 3,
          GUID = "7D2D8254",
          NextDialogue = 50003203,
          SpeakNpcId = 700074,
          Subtitle = "Whoa, whoa! Where did you learn that ditty... you're going to get us both killed one of these days!",
          TalkActionId = {
            [1] = "700074:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D8254"
        },
        [50003203] = {
          ContentJP = "あぁ、何かご入り用ですかいお客さん？すべて私の手作り、最高品質ですよ！",
          DialogueId = 50003203,
          Duration = 3,
          GUID = "7D2D827E",
          SpeakNpcId = 700074,
          Subtitle = "Ah, welcome! What can I get you, dear customer? Each piece here is crafted by my own hands, top-notch quality guaranteed!",
          TalkActionId = {
            [1] = "700074:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700074/7D2D827E"
        },
        [50003301] = {
          Content = "真好呀！真好！生活这么美好，怎么大家都愁眉苦脸的呢？我们生活在一个幸福的世界里，多么幸运！",
          DialogueId = 50003301,
          Duration = 3,
          GUID = "7D2D9292",
          SpeakNpcId = 700075,
          TalkActionId = {
            [1] = "700075:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/env/700075/7D2D9292"
        },
        [50003401] = {
          Content = "呜呜……爸爸妈妈，你们在哪里……我好想你们……",
          DialogueId = 50003401,
          Duration = 3,
          GUID = "7D2DA2FA",
          SpeakNpcId = 700076,
          TalkActionId = {
            [1] = "700076:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700076/7D2DA2FA"
        },
        [50003501] = {
          Content = "这是我在广场那边买的纪念品！他们说来冰湖城绝不能错过……",
          DialogueId = 50003501,
          Duration = 3,
          GUID = "7D2DB362",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2DB362"
        },
        [50003601] = {
          Content = "求您了……再多给两个子儿吧，只给这个数，我连过冬的炭火都买不起啊……",
          DialogueId = 50003601,
          Duration = 3,
          GUID = "7D2DC3CA",
          NextDialogue = 50003602,
          SpeakNpcId = 700078,
          TalkActionId = {
            [1] = "700078:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700078/7D2DC3CA"
        },
        [50003602] = {
          Content = "子爵大人要最好的皮料！要从最健壮的头狼身上剥下的顶级货！懂了吗蠢蛋！你的这些残次品只配给乞丐穿！",
          DialogueId = 50003602,
          Duration = 3,
          GUID = "7D2DC3F4",
          SpeakNpcId = 700079,
          TalkActionId = {
            [1] = "700079:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700079/7D2DC3F4"
        },
        [50003701] = {
          ContentJP = "ポップコーンにタバコだよ！お酒も一緒にどう――え？なくし物？知りませんよ。本当に知りませってば！",
          DialogueId = 50003701,
          Duration = 4,
          GUID = "7D2DD432",
          SpeakNpcId = 700080,
          Subtitle = "Popcorn! Cigs! Booze! Lost something, you say? Didn't see it! I swear!",
          VoiceName = "voice/$Locale$/env/700080/7D2DD432"
        },
        [50003801] = {
          ContentJP = "カロン族がみんな、あたしと同じくらい長生きできたらねぇ。そしたら、あたしだってこんなに孤独にならずにすむのに……",
          DialogueId = 50003801,
          Duration = 7,
          GUID = "7D2DE49A",
          SpeakNpcId = 700081,
          Subtitle = "If every Charon could live as long as I have, I wouldn't feel so alone.",
          VoiceName = "voice/$Locale$/env/700081/7D2DE49A"
        },
        [50003901] = {
          ContentJP = "腕が折れたことがあっても雑貨なんては運べるんだ。 ご注文は？",
          DialogueId = 50003901,
          Duration = 3,
          GUID = "7D2DF502",
          SpeakNpcId = 700082,
          TalkActionId = {
            [1] = "700082:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/env/700082/7D2DF502"
        },
        [50004001] = {
          ContentJP = "………………（ルーナエッグはボードに「こんにちは」という文字を素早く書いた）",
          DialogueId = 50004001,
          Duration = 3,
          GUID = "7D2E056A",
          SpeakNpcId = 900008,
          VoiceName = "voice/$Locale$/env/900008/7D2E056A"
        },
        [50004101] = {
          ContentJP = "新しい依頼をまた受けたんだが、一緒にどうだ？取り分はお前らが8割、俺が2割のいつも通りでさ。こいつを一杯飲んだら出発するつもりだ。",
          DialogueId = 50004101,
          Duration = 3,
          GUID = "7D2E15D2",
          SpeakNpcId = 200015,
          TalkActionId = {
            [1] = "200015:Agree"
          },
          VoiceName = "voice/$Locale$/env/200015/7D2E15D2"
        },
        [50004201] = {
          ContentJP = "一杯どうかしら？",
          DialogueId = 50004201,
          Duration = 3,
          GUID = "7D2E263A",
          SpeakNpcId = 200003,
          VoiceName = "voice/$Locale$/char/Kami/vo_npc_01"
        },
        [50004301] = {
          ContentJP = "♪翼折れたナイチンゲール……",
          DialogueId = 50004301,
          Duration = 3,
          GUID = "7D2E36A2",
          NextDialogue = 50004302,
          SpeakNpcId = 700142,
          TalkActionId = {
            [1] = "700142:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36A2"
        },
        [50004302] = {
          ContentJP = "♪ナイチンゲールよ、もう泣かないで……",
          DialogueId = 50004302,
          Duration = 3,
          GUID = "7D2E36CC",
          SpeakNpcId = 700142,
          TalkActionId = {
            [1] = "700142:Explain02_End"
          },
          VoiceName = "voice/$Locale$/env/200020/7D2E36CC"
        },
        [50004401] = {
          ContentJP = "じゃ、邪魔だ……月ノ石を買わないなら、どっかに行けってんだ……頼む、兵士たちの目を引かないでくれ……",
          DialogueId = 50004401,
          Duration = 4,
          GUID = "7D2E470A",
          SpeakNpcId = 700113,
          TalkActionId = {
            [1] = "700113:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700113/7D2E470A"
        },
        [50004501] = {
          ContentJP = "さあ踊ろう！生きる意味？そんなのどうでもいいじゃないか。面倒なことはゴミ箱にポイして、みんなで踊ろう、明日まで！",
          DialogueId = 50004501,
          Duration = 3,
          GUID = "7D2E5772",
          SpeakNpcId = 700129,
          VoiceName = "voice/$Locale$/env/700129/7D2E5772"
        },
        [50004601] = {
          ContentJP = "旦那様、今月分の帝国からの手当は……ああ、まだ承認されていないのですね……、ゲホッ、ゲホ、ゴホッ……いいのです、自分の蓄えでしのいでおきますゆえ……お手数をおかけして申し訳ない……",
          DialogueId = 50004601,
          Duration = 4,
          GUID = "7D2E67DA",
          SpeakNpcId = 700070,
          TalkActionId = {
            [1] = "700070:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/env/700070/7D2E67DA"
        },
        [50004701] = {
          ContentJP = "さあさあ、お宝の情報を聞き逃しちゃもったいないぞ……",
          DialogueId = 50004701,
          Duration = 3,
          GUID = "7D2E7842",
          SpeakNpcId = 700048,
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E7842"
        },
        [50004801] = {
          ContentJP = "漁師互助会に興味はないかね？",
          DialogueId = 50004801,
          Duration = 3,
          GUID = "7D2E88AA",
          SpeakNpcId = 700048,
          TalkActionId = {
            [1] = "700048:Agree"
          },
          VoiceName = "voice/$Locale$/env/700048/7D2E88AA"
        },
        [50004901] = {
          ContentJP = "キチンと消毒さえすれば、ハラショーな料理に仕上がることでしょう！",
          DialogueId = 50004901,
          Duration = 3,
          GUID = "7D2E9912",
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700116/7D2E9912"
        },
        [50005001] = {
          ContentJP = "チッ、知らねぇ顔だな。",
          DialogueId = 50005001,
          Duration = 3,
          GUID = "7D2EA97A",
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EA97A"
        },
        [50005101] = {
          ContentJP = "またブツが欲しいのか？",
          DialogueId = 50005101,
          Duration = 3,
          GUID = "7D2EB9E2",
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Agree"
          },
          VoiceName = "voice/$Locale$/env/700096/7D2EB9E2"
        },
        [50005201] = {
          ContentJP = "欲望のままに、欲望のままに、欲望のままに……ああ、欲望に忠実とは、一体何をすればいいのでしょうか……",
          DialogueId = 50005201,
          Duration = 4,
          GUID = "7D2ECA4A",
          SpeakNpcId = 700077,
          TalkActionId = {
            [1] = "700077:Disagree"
          },
          VoiceName = "voice/$Locale$/env/700077/7D2ECA4A"
        },
        [50005301] = {
          ContentJP = "まもなく、次の駅に向かう列車が出発いたします。切符の購入はこちらで――\n\nなんですって？お金がない？だったら早く白昼夢から目覚めてくださいませ！お帰りはあちらになります！",
          DialogueId = 50005301,
          Duration = 4,
          GUID = "7D2D1FBA",
          SpeakNpcId = 700147,
          TalkActionId = {
            [1] = "700147:Confident_Start"
          },
          VoiceName = "voice/$Locale$/env/700021/7D2D1FBA"
        },
        [50005401] = {
          ContentJP = "アッハハハ、見たかよ、あいつの逃げ足。ドブネズミかっつうの！",
          DialogueId = 50005401,
          Duration = 3,
          GUID = "7D2EEB1A",
          SpeakNpcId = 700089
        },
        [50005501] = {
          ContentJP = "なにボケっとしてんだよ。臭っせえカロンはさっさと仲間を追っかけろよ！",
          DialogueId = 50005501,
          Duration = 3,
          GUID = "7D2EFB82",
          SpeakNpcId = 700088,
          TalkActionId = {
            [1] = "700088:Confident_Start"
          }
        },
        [50005601] = {
          ContentJP = "もっと大きな看板に交換しようかな……",
          DialogueId = 50005601,
          Duration = 3,
          GUID = "7D2F0BEA",
          SpeakNpcId = 700143
        },
        [51000001] = {
          ContentJP = "（受け入れる）",
          DialogueId = 51000001,
          GUID = "7FAC53AA",
          NextDialogue = 51005311
        },
        [51000002] = {
          ContentJP = "（断る）",
          DialogueId = 51000002,
          GUID = "7FAC53D4",
          Scripts = "SetOutport{FinishType{\"Fail\"}}"
        },
        [51000101] = {
          ContentJP = "今夜はマッシュルームのクリームスープで……あら？どちらのおチビさんかしら？",
          DialogueId = 51000101,
          GUID = "7FAC6412",
          NextDialogue = 51000102,
          SpeakNpcId = 700020
        },
        [51000102] = {
          ContentJP = "（老婦人は大きな手であなたの頭を何度もポンポンとなでたり、頬をつまんだ。過剰な反応があなたを困惑させる）",
          DialogueId = 51000102,
          GUID = "7FAC643C",
          NextDialogue = 51000103
        },
        [51000103] = {
          ContentJP = "おいで！スープをお飲みなさいな！おばさんはレッドバリー城で腕を振るっていたからね、経験したことないおいしさでホッペがとろけちゃうかもしれないわよ～？",
          DialogueId = 51000103,
          GUID = "7FAC6466",
          NextDialogue = 51000104,
          SpeakNpcId = 700020
        },
        [51000104] = {
          ContentJP = "（老婦人は有無を言わさず熱々のスープをあなたの前に差し出す。次の瞬間には顔をガッチリとつかまれて、無理やりにでも飲まされそうだ――）",
          DialogueId = 51000104,
          GUID = "7FAC6490",
          NextOptions = {
            [1] = 510001041,
            [2] = 510001042
          },
          bForbidSkipOptions = true
        },
        [51000105] = {
          ContentJP = "（コクのあるキノコの出汁とクリームの甘みで喉が優しく温まる。とてもおいしい）",
          DialogueId = 51000105,
          GUID = "7FAC64BA",
          NextDialogue = 51000106
        },
        [51000106] = {
          ContentJP = "ね、サリーおばさんはあんたを騙したりしないわよ、ふふふ。",
          DialogueId = 51000106,
          GUID = "7FAC64E4",
          NextDialogue = 51000108,
          SpeakNpcId = 700020
        },
        [51000107] = {
          ContentJP = "何もそんなに嫌がらなくたって！わかってくれない子だね本当！",
          DialogueId = 51000107,
          GUID = "7FAC650E",
          NextDialogue = 51000108,
          SpeakNpcId = 700020
        },
        [51000108] = {
          ContentJP = "私がお世話をする奥様なんてお嬢さんって年頃からずっとスープを飲んでくれていたわ。もう40年近くずっとよ？",
          DialogueId = 51000108,
          GUID = "7FAC6538",
          NextDialogue = 51000109,
          SpeakNpcId = 700020
        },
        [51000109] = {
          ContentJP = "だけども……あぁ、奥様！奥様のご病気は治るのかしらねぇ……",
          DialogueId = 51000109,
          GUID = "7FAC6562",
          NextDialogue = 51000110,
          SpeakNpcId = 700020
        },
        [51000110] = {
          ContentJP = "（老婦人の顔からほほ笑みが薄れ、代わりに一筋の涙が頬を伝う）",
          DialogueId = 51000110,
          GUID = "7FAC658C",
          NextOptions = {
            [1] = 510001101
          }
        },
        [51000111] = {
          ContentJP = "そうなの。日に日に弱っていて……はぁ、なのに奥様は、レッドバリー城を離れて、この寒い街に引っ越したいって。私が何を言ったってお聞きにならないのよ。",
          DialogueId = 51000111,
          GUID = "7FAC65B6",
          NextDialogue = 51000112,
          SpeakNpcId = 700020
        },
        [51000112] = {
          ContentJP = "奥様は40年も前のことを気にかけて、毎日大通りで尋ね回っているわ。私を巻き込まないようおひとりだけで……",
          DialogueId = 51000112,
          GUID = "7FAC65E0",
          NextDialogue = 51000190,
          SpeakNpcId = 700020
        },
        [51000113] = {
          ContentJP = "さて、おばさんは仕事の続きをやらないと！",
          DialogueId = 51000113,
          GUID = "7FAC660A",
          NextDialogue = 51000114,
          SpeakNpcId = 700020
        },
        [51000114] = {
          ContentJP = "（道行く人々に何かを尋ね回っている奥様か……もし見かけたら様子をうかがってみよう）",
          DialogueId = 51000114,
          GUID = "7FAC6634"
        },
        [51000190] = {
          ContentJP = "奥様の心の傷は私では癒やせないの。今の私にできるのは、日替わりでおいしいスープを作ることだけ。奥様のお身体だけでも少しは癒やせるようにね",
          DialogueId = 51000190,
          GUID = "7FAC72AC",
          NextDialogue = 51000113,
          SpeakNpcId = 700020
        },
        [51000201] = {
          ContentJP = "今夜はマッシュルームのクリームスープで、どうか奥様の心が少しでも安らぎますように……あら？お帰りなさい、おチビさん。",
          DialogueId = 51000201,
          GUID = "7FAC747A",
          NextDialogue = 51000202,
          SpeakNpcId = 700020
        },
        [51000202] = {
          ContentJP = "（老婦人は大きな手であなたの頭を何度もポンポンとなでたり、頬をつまんだ。過剰な反応があなたを困惑させる）",
          DialogueId = 51000202,
          GUID = "7FAC74A4",
          NextDialogue = 51000203
        },
