        },
        [51000209] = {
          ContentJP = "だけども……あぁ、奥様！奥様のご病気は治るのかしらねぇ……",
          DialogueId = 51000209,
          GUID = "7FAC75CA",
          NextDialogue = 51000210,
          SpeakNpcId = 700020,
          TalkActionId = {
            [1] = "700020:Sigh_Start"
          }
        },
        [51000210] = {
          ContentJP = "（老婦人の顔からほほ笑みが薄れ、代わりに一筋の涙が頬を伝う）",
          DialogueId = 51000210,
          GUID = "7FAC75F4",
          TalkActionId = {
            [1] = "700020:Sigh_End"
          }
        },
        [51000301] = {
          ContentJP = "どこに行ってしまわれたの……",
          DialogueId = 51000301,
          GUID = "7FAC84E2",
          NextDialogue = 51000302,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Sigh_Start"
          }
        },
        [51000302] = {
          ContentJP = "（老婦人が悲しい目で遠くを見つめている。話しかけても反応がない）",
          DialogueId = 51000302,
          GUID = "7FAC850C",
          NextOptions = {
            [1] = 510003021,
            [2] = 510003022,
            [3] = 510003023
          },
          bForbidSkipOptions = true
        },
        [51000303] = {
          ContentJP = "（彼女の服は少し古いものだが、生地が上質でとても丁寧に仕立てられている。恐らく裕福な家庭で育ったのだろう）",
          DialogueId = 51000303,
          GUID = "7FAC8536",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000304] = {
          ContentJP = "（彼女はじっと城外を見つめている。誰かの帰りを待っているのだろう）",
          DialogueId = 51000304,
          GUID = "7FAC8560",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000305] = {
          ContentJP = "（老いた目は悲しみに満ちあふれている。何か望みを叶えられないまま、長い時を過ごしたのだろう）",
          DialogueId = 51000305,
          GUID = "7FAC858A",
          NextOptions = {
            [1] = 510003051,
            [2] = 510003053
          },
          bForbidSkipOptions = true
        },
        [51000306] = {
          ContentJP = "（老婦人は振り返ってあなたをチラッと見たが、すぐさま顔を背けてしまった。あなたが話しかけても上の空だ）",
          DialogueId = 51000306,
          GUID = "7FAC85B4"
        },
        [51000307] = {
          ContentJP = "あなた……は……",
          DialogueId = 51000307,
          GUID = "7FAC85DE",
          NextDialogue = 51000308,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Sigh_End"
          }
        },
        [51000308] = {
          ContentJP = "初めまして、でよろしくて？近くの街からいらっしゃったのかしら？",
          DialogueId = 51000308,
          GUID = "7FAC8608",
          NextDialogue = 51000309,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_Start"
          }
        },
        [51000309] = {
          ContentJP = "ハーメル・ディキンソンという名のカロン族の男性をご存じありませんか？アイスレイク城の生まれで、髪は薄茶色で、18、9歳ぐらいで、いつも着ていた服は……いえ、今はもう、年齢は私と同じぐらいです。",
          DialogueId = 51000309,
          GUID = "7FAC8632",
          NextDialogue = 51000310,
          SpeakNpcId = 700019
        },
        [51000310] = {
          ContentJP = "アイスレイク城を離れて彼と連絡が取れなくなって、もう40年が過ぎました。最近やっとこの街に戻ったのですが、誰一人として彼を知る者はおらず……",
          DialogueId = 51000310,
          GUID = "7FAC865C",
          NextDialogue = 51000311,
          SpeakNpcId = 700019
        },
        [51000311] = {
          ContentJP = "彼はアイスレイク城で生まれ育ったのですから、街を離れたとしてもそう遠くには行かないと思うのです。お若い方、どこかで彼にお会いになったりは？",
          DialogueId = 51000311,
          GUID = "7FAC8686",
          NextOptions = {
            [1] = 510003111
          },
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51000312] = {
          ContentJP = "さようですか……",
          DialogueId = 51000312,
          GUID = "7FAC86B0",
          NextDialogue = 51000313,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Agree"
          }
        },
        [51000313] = {
          ContentJP = "もし彼に会われる機会があれば、伝えてくださらない？",
          DialogueId = 51000313,
          GUID = "7FAC86DA",
          NextDialogue = 51000314,
          SpeakNpcId = 700019
        },
        [51000314] = {
          ContentJP = "「セリーヌがアイスレイク城に戻ってきた。彼女はあなたをずっと待っている。40年も遅れている理由を教えてほしいと」",
          DialogueId = 51000314,
          GUID = "7FAC8704",
          NextDialogue = 51000315,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain01_Start"
          }
        },
        [51000315] = {
          ContentJP = "もし来年彼にお会いになったら41年も遅れている理由を、再来年ならば42年……私はずっと指折り数えて待ち続けます。",
          DialogueId = 51000315,
          GUID = "7FAC872E",
          NextDialogue = 51000316,
          SpeakNpcId = 700019,
          TalkActionId = {
            [1] = "700019:Explain01_End"
          }
        },
        [51000316] = {
          ContentJP = "（本当に途方に暮れた様子のセリーヌ夫人……彼女がサリーおばさんの言っていた「奥様」なのだろう。何か手伝えることがあるはず）",
          DialogueId = 51000316,
          GUID = "7FAC8758"
        },
        [51000401] = {
          ContentJP = "アニー……アニー！",
          DialogueId = 51000401,
          GUID = "7FAC954A",
          NextDialogue = 51000402,
          SpeakNpcId = 700006,
          Subtitle = "Annie... Annie!",
          TalkActionId = {
            [1] = "700006:Shock_Start"
          }
        },
        [51000402] = {
          ContentJP = "ああ、やっと帰ってきてくれたのね！私の愛しい娘！",
          DialogueId = 51000402,
          GUID = "7FAC9574",
          NextDialogue = 51000403,
          SpeakNpcId = 700006,
          Subtitle = "Ah, you're back, my dear daughter!"
        },
        [51000403] = {
          ContentJP = "（女性が行く手を遮った。虚ろに乾いた目であなたの身体をくまなく眺め、何かを懸命に見つけようとしている）",
          DialogueId = 51000403,
          GUID = "7FAC959E",
          NextOptions = {
            [1] = 510004031,
            [2] = 510004032,
            [3] = 510004033
          },
          Subtitle = "(A woman stops you. Her dry, vacant eyes roam over you, as if desperately searching for something inside of you.)",
          bForbidSkipOptions = true
        },
        [51000404] = {
          ContentJP = "信じてたわ、あなたはきっと帰ってくるって！お母さんを置き去りにしたりなんかしないって！",
