        [51001315] = {
          Camera = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
          ContentJP = "お、お前、何をするつもりだ！他人の商売を邪魔しやがって。",
          DialogueId = 51001315,
          GUID = "7FAD2B3E",
          LookAt = {
            [1] = "200003:n(700014)"
          },
          NextDialogue = 51001316,
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Angry01_Start"
          }
        },
        [51001316] = {
          Camera = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
          ContentJP = "あら、誤解しないでちょうだいね。あなたの商売には興味ないわ。ただ少しだけお話がしたくて。",
          DialogueId = 51001316,
          GUID = "7FAD2B68",
          NextDialogue = 51001317,
          Scripts = "PlayAnimation{_delay{0.5},ActorId{200003},AnimationId{\"Disagree\"},Duration{1}}",
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_End",
            [2] = "700014:Angry01_End"
          },
          TurnTo = {
            [1] = "100001:p(-30)"
          }
        },
        [51001317] = {
          ContentJP = "最近、私の名前を使って偽物を売り歩く人がいるみたいなの。「アスフォデロスの新商品だ」とか、「アスフォデロスで一瞬で売り切れて、もう手に入らない」とか言っちゃってね。",
          DialogueId = 51001317,
          GUID = "7FAD2B92",
          NextDialogue = 51001318,
          Scripts = "PlayAnimation{_delay{3},ActorId{200003},AnimationId{\"Explain01_End\"},Duration{1}}",
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Explain01_Start"
          }
        },
        [51001318] = {
          ContentJP = "知っているでしょ？商売って信用が大切なの。お酒の品質はアスフォデロスの信用に関わることだからね、誰かさんに汚されちゃ困るのよ。",
          DialogueId = 51001318,
          GUID = "7FAD2BBC",
          NextDialogue = 51001319,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_Start"
          }
        },
        [51001319] = {
          Camera = "32.993408,156.229492,158.578613,0.000122,-1.500244,-80.195831,35.0,250.869797,false,Manual,5.0",
          ContentJP = "そ、それが…俺に何の関係があるんだ？お前の面倒を見る暇なんてないぞ！",
          DialogueId = 51001319,
          GUID = "7FAD2BE6",
          NextDialogue = 51001320,
          Scripts = "PlayAnimation{_delay{3},ActorId{700014},AnimationId{\"Sigh_End\"},Duration{1}}",
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Sigh_Start"
          }
        },
        [51001320] = {
          ContentJP = "どけどけ、俺は行くぞ。お前が商売しなくても、俺には商売があるんだ。",
          DialogueId = 51001320,
          GUID = "7FAD2C10",
          NextDialogue = 51001321,
          SpeakNpcId = 700014,
          TalkActionId = {
            [1] = "700014:Confident_Start"
          }
        },
        [51001321] = {
          Camera = "108.244629,-193.245605,185.203125,0.000066,-10.700194,101.210106,35.000008,250.869797,false,Manual,5.0",
          ContentJP = "あら、逃げるの？少し前に取引を断ったとき、あなた、試飲用のお酒を置いていったでしょ？成分を調べてみたんだけど……どうなったと思う？",
          DialogueId = 51001321,
          GUID = "7FAD2C3A",
          NextDialogue = 51001322,
          SpeakNpcId = 200003
        },
        [51001322] = {
          ContentJP = "あなたの商品と、世間に出回っているアスフォデロスの偽酒の成分がまったく一緒だったの。偶然ってすごいわね？",
          DialogueId = 51001322,
          GUID = "7FAD2C64",
          NextDialogue = 51001323,
          SpeakNpcId = 200003
        },
        [51001323] = {
          Camera = "-209.837891,-298.262207,123.758301,0.000147,1.099674,42.806149,35.000008,408.143951,false,Manual,5.0",
          ContentJP = "何だって？デタラメ言うな！俺が偽物を売るなんてあり得ない！顧客を奪われるのを恐れているから、そんなでたらめを言っているんだろう！",
          DialogueId = 51001323,
          GUID = "7FAD2C8E",
