          },
          ToFinalCameraBlendTime = 5
        },
        [51001326] = {
          Camera = "-126.292969,-236.144531,121.561768,0.000212,4.098496,38.002239,35.0,288.862579,false,Manual,5.0",
          ContentJP = "の…飲んでやる、怖がるもんか！",
          DialogueId = 51001326,
          GUID = "7FAD2D0C",
          LookAt = {
            [1] = "700014:n(100001)"
          },
          NextDialogue = 51001327,
          SpeakNpcId = 700014
        },
        [51001327] = {
          ContentJP = "（ディーンは両手で酒桶を抱え、仰向けにして飲み始める）",
          DialogueId = 51001327,
          GUID = "7FAD2D36",
          IsBlack = 1,
          LookAt = {
