        [51001504] = {
          ContentJP = "ま、どのみちお前さんの話になぞ興味はない。掃除が先だ。",
          DialogueId = 51001504,
          GUID = "7FAD4A40",
          NextDialogue = 51001505,
          SpeakNpcId = 700067,
          Subtitle = "Oof, I'm swamped right now. Maybe talk to me after I'm done cleaning."
        },
        [51001505] = {
          ContentJP = "（男性は大きなぞうきんで地面をゴシゴシと擦っている。何度も繰り返し拭いて、疲れ果てたころにようやく血痕が消えた）",
