          DialogueId = 51001506,
          GUID = "7FAD4A94",
          NextDialogue = 51001507,
          SpeakNpcId = 700067,
          Subtitle = "*sigh* That fight earlier was brutal, blood splattered everywhere. Such a nightmare to clean up.",
          TalkActionId = {
            [1] = "700067:Talk01_Start"
          }
        },
        [51001507] = {
          ContentJP = "やっぱり一撃で決着をつけてくれたほうが助かるな。それか毒殺とか。血が流れない方法がいい。",
          DialogueId = 51001507,
          GUID = "7FAD4ABE",
          SpeakNpcId = 700067,
          Subtitle = "Much easier when it's a quick kill, or with poison — hardly any mess.",
          TalkActionId = {
            [1] = "700067:Talk01_End"
          },
          TalkOptions = {
            [1] = 510015071
          }
        },
        [51001508] = {
          ContentJP = "お前さん野次馬かい？そこに突っ立ってペラペラ話すだけならおいらみたいに腰も痛まないし、いい気なもんだね。",
          DialogueId = 51001508,
          GUID = "7FAD4AE8",
          SpeakNpcId = 700067,
          Subtitle = "Who asked you? Easy to judge when you're not in my shoes. Mind your own business!"
        },
        [51001509] = {
          ContentJP = "おいらに何ができるってんだ。\n汚れたら掃除せにゃならんし、きれいにできなきゃ殴られる。",
          DialogueId = 51001509,
          GUID = "7FAD4B12",
          NextDialogue = 51001510,
          SpeakNpcId = 700067,
          Subtitle = "What choice do I have? When the floor's dirty, I gotta clean it, or it's beatings and scoldings for me.",
          TalkActionId = {
            [1] = "700067:Sigh_Start"
          }
        },
        [51001510] = {
          ContentJP = "最初は死んだ連中に同情してたがね。そのうちどうでもよくなった。おいらだって下手したら殺されるってのに、知ったこっちゃない。",
          DialogueId = 51001510,
          GUID = "7FAD4B3C",
          NextDialogue = 51001511,
          SpeakNpcId = 700067,
          Subtitle = "I used to feel sorry for them, but there's only so much sympathy to go around.\nI'm struggling to keep myself alive — can't afford to worry about others!",
          TalkActionId = {
            [1] = "700067:Sigh_End"
          }
        },
        [51001511] = {
          ContentJP = "時間が経つにつれて、血がただの赤い液体にしか見えなくなった。おかげで気が楽だよ。感覚がマヒしないとやってられん……",
          DialogueId = 51001511,
          GUID = "7FAD4B66",
          NextDialogue = 51001512,
          SpeakNpcId = 700067,
          Subtitle = "Over time, blood's just another red spill to me. Being numb helps me make it through the day...",
          TalkActionId = {
