    Loader = function()
      return {
        [51002501] = {
          ContentJP = "じゃ、邪魔だ……月ノ石を買わないなら、どっかに行けってんだ……頼む、兵士たちの目を引かないでくれ……",
          DialogueId = 51002501,
          GUID = "7FADEDD2",
