            [4] = 510025024
          }
        },
        [51002503] = {
          ContentJP = "こ、今回だけは大目に見てくれないか。この月ノ石を売っぱらったらアイスレイク城から速攻で離れる。二度と帰ってこないから……",
          DialogueId = 51002503,
          GUID = "7FADEE26",
          SpeakNpcId = 700113
        },
        [51002504] = {
          ContentJP = "（男はそれを聞くや否や瞬間で袋を持ち上げて逃げようとした。慌てて自分の身分と冗談であることを説明すると、彼は小声で話し始める。何やら困った状況なようだ）",
          DialogueId = 51002504,
          GUID = "7FADEE50"
        },
        [51002505] = {
          ContentJP = "……買い手を探してくれたら報酬の70％、いや、80％を渡す！どうか頼む、後生の頼みだ！",
          DialogueId = 51002505,
          GUID = "7FADEE7A",
          SpeakNpcId = 700113,
          TalkActionId = {
            [1] = "700113:Sigh_Start"
          }
        },
        [51002506] = {
          ContentJP = "男の依頼には応じたものの──あの表情と、袋に滲んだ暗赤色の染みが、この月ノ石たちがただの品物じゃないことを物語っている。",
          DialogueId = 51002506,
          GUID = "7FADEEA4",
          TalkActionId = {
            [1] = "700113:Sigh_End"
          }
        },
        [51002601] = {
          ContentJP = "本日は吉日なり……なんせ{nickname}の顔を拝まずに済んでるからな……",
          DialogueId = 51002601,
          GUID = "7FADFE3A",
          NextDialogue = 51002602,
          SpeakNpcId = 700111,
          TalkActionId = {
            [1] = "700111:Think_Start"
          }
        },
        [51002602] = {
          ContentJP = "{性别:僕をお探しかな？|私をお探しかい？}",
          DialogueId = 51002602,
          GUID = "7FADFE64",
          NextDialogue = 51002603,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700111:Think_End"
          }
        },
        [51002603] = {
          ContentJP = "……おわぁ厄日が来やがったぁ！な、なんの用だよ！",
          DialogueId = 51002603,
          GUID = "7FADFE8E",
          NextOptions = {
            [1] = 510026031
          },
          SpeakNpcId = 700111,
          TurnTo = {
            [1] = "700111:n(0)"
          },
          bForbidSkipOptions = true
        },
        [51002604] = {
          ContentJP = "ふん……その手には乗らんぞ。何を騙して俺にやらせるつもりだ？",
          DialogueId = 51002604,
          GUID = "7FADFEB8",
          SpeakNpcId = 700111,
