        },
        [51002703] = {
          Camera = "221.641602,5.540039,120.836426,0.000002,0.200002,-178.397919,25.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "まあ、なんだっていいさ、重要なのはそこじゃないし……お前さ、無断で月ノ石を採掘したり販売するのは法に触れるって知ってるよな？上層部から通知を受けちまって……ツッ、テメェおい、その袋の血はなんだってんだ？",
          DialogueId = 51002703,
          GUID = "7FAE0EF6",
          NextDialogue = 51002704,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700114:Shock_End",
            [2] = "700112:Talk01_Start"
          }
        },
        [51002704] = {
          Camera = "-24.264648,5.625977,122.256836,0.0,0.0,8.403694,25.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "お、俺は……",
          DialogueId = 51002704,
          GUID = "7FAE0F20",
          NextDialogue = 51002705,
          Scripts = "SEQ{LookAt{LookAtDescription{\"700114:n(100001)\"}},LookAt{LookAtDescription{\"700114:n(700114)\"}}}",
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700112:Talk01_End"
          }
        },
        [51002705] = {
          Camera = "121.136719,-1.510742,123.537598,0.000002,0.399996,-168.191696,25.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "逃げんじゃねえよ！{nickname}、手伝え！",
          DialogueId = 51002705,
          GUID = "7FAE0F4A",
          Scripts = "SEQ{PlayAnimation{ActorId{700112},AnimationId{\"Angry01_Start\"},Duration{2}},LookAt{LookAtDescription{\"700112:n(100001)\"}},PlayAnimation{ActorId{100001},AnimationId{\"Talk03_Start\"},Duration{1}}}",
          SpeakNpcId = 700112
        },
        [51002801] = {
          Camera = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "お、お前！俺を騙したなぁ！兵士なんざ引き連れてきやがってぇ！！",
          DialogueId = 51002801,
          GUID = "7FAE1F0A",
          NextDialogue = 51002802,
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700114:Sigh_Start"
          }
        },
        [51002802] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "黙れっての、俺の見えるところに手を出せ……両手を広げて、麻袋を下ろせ！",
          DialogueId = 51002802,
          GUID = "7FAE1F34",
          NextDialogue = 51002803,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700112:Angry01_Start"
          }
        },
        [51002803] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（真っ黒な銃口がラリーの頭に突きつけられる。ラリーは一瞬ためらう様子を見せたが、ついに両手を広げた。麻袋が地面に落ちる。血のついた月ノ石が足元辺りに次々と転がった）",
          DialogueId = 51002803,
          GUID = "7FAE1F5E",
          NextDialogue = 51002804,
          TalkActionId = {
            [1] = "700114:Sigh_End",
            [2] = "700112:Angry01_End"
          }
        },
        [51002804] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "手をかけやがったな？そいつで兄弟たちをぶん殴って……",
          DialogueId = 51002804,
          GUID = "7FAE1F88",
          NextDialogue = 51002805,
          SpeakNpcId = 700112
        },
        [51002805] = {
          Camera = "-297.869141,-392.973633,116.237793,0.000001,0.0,37.400127,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "先に手を出したのはあいつらだッ！！お、俺は、自分の身を守っただけさ……正当防衛なんだよぉッ！！",
          DialogueId = 51002805,
          GUID = "7FAE1FB2",
          NextDialogue = 51002806,
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700114:Sigh_Start"
          }
        },
        [51002806] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "正当かなんて俺に言ったってしょうがないだろ！さっさと歩け！",
          DialogueId = 51002806,
          GUID = "7FAE1FDC",
          NextDialogue = 51002807,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700114:Sigh_End",
            [2] = "700112:Talk01_Start"
          }
        },
        [51002807] = {
          Camera = "435.016602,-46.152344,110.63623,0.000004,0.0,-169.994827,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "違う、俺のせいじゃ……！ああ全部、月ノ石めッ！こんなクソッタレな袋さえなけりゃ、俺たちみんな、なんにも……平和に暮らせたはずなんだよぉ……！！",
          DialogueId = 51002807,
          GUID = "7FAE2006",
          NextDialogue = 51002808,
          SpeakNpcId = 700114,
          TalkActionId = {
            [1] = "700114:Disagree",
            [2] = "700112:Talk01_End"
          }
        },
        [51002808] = {
          Camera = "121.290039,-83.856445,144.21875,0.000003,-0.999905,-165.995453,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "はぁ……",
          DialogueId = 51002808,
          GUID = "7FAE2030",
          NextDialogue = 51002809,
          SpeakNpcId = 700112,
          TalkActionId = {
            [1] = "700112:Disagree"
          }
        },
        [51002809] = {
          Camera = "-3.327148,-490.567383,115.4375,0.000011,0.0,94.803833,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "そうだ、規定通りに渡さないとだ。{nickname}、警備部隊への協力に感謝する。これは協力した報酬だ。",
          DialogueId = 51002809,
          GUID = "7FAE205A",
          Scripts = "SEQ{PARA{TurnTo{TurnToDescription{\"700112:n(100001)\"}},TurnTo{TurnToDescription{\"100001:n(700112)\"}}},PlayAnimation{ActorId{700112},AnimationId{\"Agree\"},Duration{1}},PlayAnimation{ActorId{700112},AnimationId{\"Talk01_Start\"},Duration{1}}}",
          SpeakNpcId = 700112
        },
        [51002810] = {
          ContentJP = "ケビンに連行されたラリーが徐々に遠ざかっていく。",
          DialogueId = 51002810,
          Duration = 2,
          GUID = "7FAE2084",
          NextDialogue = 51002811
        },
        [51002811] = {
          ContentJP = "「血の石」の裏に隠された血生臭い過去は、ラリーが去っていくにつれて、アイスレイク城に降り積もる雪の一粒として埋もれていくのだった。",
          DialogueId = 51002811,
          Duration = 4,
          GUID = "7FAE20AE"
        },
        [51002901] = {
          ContentJP = "（大声で何かを朗読している男の声が聞こえる。酒客たちは気まぐれに聞いており、時折楽しげに笑っている。）",
          DialogueId = 51002901,
          GUID = "7FAE2F72",
          NextDialogue = 51002902
        },
        [51002902] = {
          ContentJP = "深々たる山の奥底より具現化した！霊魂が！アイスレイクからの悪鬼が！",
          DialogueId = 51002902,
          GUID = "7FAE2F9C",
          NextDialogue = 51002903,
          SpeakNpcId = 700015
        },
        [51002903] = {
          ContentJP = "彼奴らが迫りくる！彼奴らが肉薄してくるのだ！！！",
          DialogueId = 51002903,
          GUID = "7FAE2FC6",
          NextDialogue = 51002904,
          SpeakNpcId = 700015
        },
        [51002904] = {
          ContentJP = "あら、来たのね？",
          DialogueId = 51002904,
          GUID = "7FAE2FF0",
          NextOptions = {
            [1] = 510029041
          },
          SpeakNpcId = 200003
        },
        [51002905] = {
          ContentJP = "今、手元に頼める仕事はないわね。でも……",
          DialogueId = 51002905,
          GUID = "7FAE301A",
          NextDialogue = 51002906,
          SpeakNpcId = 200003
        },
        [51002906] = {
          ContentJP = "……貴様たちは想像し得るか！？",
          DialogueId = 51002906,
          GUID = "7FAE3044",
          NextDialogue = 51002907,
          SpeakNpcId = 700015
        },
        [51002907] = {
          ContentJP = "亡霊だぞ！！！我が安息地である居館の静寂を鉤裂く者！！！門を通り抜けて邪魔立てる者！！！",
          DialogueId = 51002907,
          GUID = "7FAE306E",
          NextDialogue = 51002908,
          SpeakNpcId = 700015
        },
        [51002908] = {
          ContentJP = "お聞きの通り、トラブルの塊みたいなヤツならあそこにいるわ。",
          DialogueId = 51002908,
          GUID = "7FAE3098",
          NextOptions = {
            [1] = 510029081
          },
          SpeakNpcId = 200003
        },
        [51002909] = {
          ContentJP = "バック氏、少しでも酒が入ると倒れちゃうから、果汁や牛乳しか頼まない人よ。職業は…三流の劇作家、一流の難解な語り手。ほら、あそこでずっとぶつぶつ言ってるよ。",
          DialogueId = 51002909,
          GUID = "7FAE30C2",
          NextDialogue = 51002910,
          SpeakNpcId = 200003
        },
        [51002910] = {
          ContentJP = "まあ自分の言いたいことを単純明快に表現できない人でね。あなたは分かるかしら？",
          DialogueId = 51002910,
          GUID = "7FAE30EC",
          NextOptions = {
            [1] = 510029101
          },
          RestartTag = 51002910,
          SpeakNpcId = 200003,
          bForbidSkipOptions = true
        },
        [51002911] = {
          ContentJP = "ガッカリしなくてもいいわよ。アレの言語を解読できる人間なんて、アイスレイク中を探しても片手で数えるほどでしょうし。",
          DialogueId = 51002911,
          GUID = "7FAE3116",
          SpeakNpcId = 200003
        },
        [51002912] = {
          ContentJP = "あなたほどの才智を持つ人間であれば、理解もなんとかできそうかしら。",
          DialogueId = 51002912,
          GUID = "7FAE3140",
          SpeakNpcId = 200003
        },
        [51003001] = {
          ContentJP = "（劇作家の妄言に耳を傾ける）",
          DialogueId = 51003001,
          GUID = "7FAE3FDA",
          NextDialogue = 51003002
        },
        [51003002] = {
          ContentJP = "終焉なき詩人の夜は毎晩と永らえるもの……それは劇作家も多分に漏れず！私のペンは人の拍動を描写し、私の心は自然や潮汐にあり、月の下にある！",
          DialogueId = 51003002,
          GUID = "7FAE4004",
          NextDialogue = 51003003,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          }
        },
        [51003003] = {
          ContentJP = "燦爛たる陽光を見放し、喧々たる残響に耳を貸さず、思為す軽薄さなど遺棄する！その瞬間こそが、私と世界が邂逅し、対話する瞬間なのだ！",
          DialogueId = 51003003,
          GUID = "7FAE402E",
          NextOptions = {
            [1] = 510030031,
            [2] = 510030032
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_End"
          },
          bForbidSkipOptions = true
        },
        [51003004] = {
          ContentJP = "ああ！私の無自覚な怠慢がインスピレーションの女神を怒らせてしまったのか！否、それだけに非ず、眠りへと誘う神が我が身を戯れに弄んでいるのか！さもなければ何故！何故この私が時の歯車の回り動く様を拝むことなく、露いささかも気づかないのであろうか！",
          DialogueId = 51003004,
          GUID = "7FAE4058",
          NextDialogue = 51003005,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Sigh_Start"
          }
        },
        [51003005] = {
          ContentJP = "私の朝は揚々に語り明かされた物語を記する原稿を残して迎えるべきであったのだ！無意義にも健やかなりし身と虚無の純白を映写する原稿用紙を残すのではなく！",
          DialogueId = 51003005,
          GUID = "7FAE4082",
          NextOptions = {
            [1] = 510030051,
            [2] = 510030052
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Sigh_End"
          },
          bForbidSkipOptions = true
        },
        [51003006] = {
          ContentJP = "ある時、蠱惑の夢中で足音のざわめきが耳を撫でた。妖精かのように軽やかな舞いを感じた。その刹那には豊潤な果実に甘美なる白蜜を垂らしたような香りが私の鼻を突いた！",
          DialogueId = 51003006,
          GUID = "7FAE40AC",
          NextDialogue = 51003007,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Explain01_Start"
          }
        },
        [51003007] = {
          ContentJP = "夢中を彷徨ったのやも知れぬが、その音と香りが私を現実に繋ぎ止めたのだ。彼奴らは朧であろうと、私の周囲に纏わりつくように、確かに存在している……",
          DialogueId = 51003007,
          GUID = "7FAE40D6",
          NextOptions = {
            [1] = 510030071,
            [2] = 510030072
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51003008] = {
          ContentJP = "彼奴らが私の虹彩にのみ射映される夢幻でないのは必定！然し私には痕跡の尻尾を把持することすら叶わず、この不可解の靄が晴れない実態は慙愧に堪えぬ。靄の真相とは亡霊か？いや悪鬼か？或いは幻影の結句なのか？",
          DialogueId = 51003008,
          GUID = "7FAE4100",
          NextDialogue = 51003009,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Disagree"
          }
        },
        [51003009] = {
          ContentJP = "我が清貧なる破れ屋の家財が膨れることもなければ、萎むこともない。だがやつらは我が命とも言えるインスピレーションだけを確かに盗んでいったのだ！我が夢を挫き、砕こうとしているのだ……",
          DialogueId = 51003009,
          GUID = "7FAE412A",
          NextOptions = {
            [1] = 510030091,
            [2] = 510030092
          },
          SpeakNpcId = 700015,
          bForbidSkipOptions = true
        },
        [51003010] = {
          ContentJP = "劇作家の夜間とは枕に伏せる刻限に決して非ず！今般の場に集いし宿命を負う者たちにて、我が咆哮に傾聴し、私のため、否、まもなく地上に産まれ出づる傑作のため、インスピレーションを掠め取る怪盗を討ち払う者はおらぬか！",
          DialogueId = 51003010,
          GUID = "7FAE4154",
          NextDialogue = 51003011,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk03_Start"
          }
        },
        [51003011] = {
          ContentJP = "名乗り上げる者あらば、私の紡ぎし妖精の尾の中心人物となる可能性を、それに伴う名誉を捧ぐことを誓う！私に腕前の見得を切らば、月狩り人の名を後世に残すための伝記を私が紡ぎ上げようではないか！",
          DialogueId = 51003011,
          GUID = "7FAE417E",
          NextOptions = {
            [1] = 510030111,
            [2] = 510030112
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51003012] = {
          ContentJP = "儲けにはならなそうだけど、興味あるかしら？受けてみる？",
          DialogueId = 51003012,
          GUID = "7FAE41A8",
          NextOptions = {
            [1] = 510030121,
            [2] = 510030122
          },
          SpeakNpcId = 200003,
          bForbidSkipOptions = true
        },
        [51003013] = {
          ContentJP = "おお！我が問いかけに呼応する勇士が顕現した！新生の冒険譚が幕を開けるのであろうか！",
          DialogueId = 51003013,
          GUID = "7FAE41D2",
          NextDialogue = 51003014,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_Start"
          },
          TurnTo = {
            [1] = "700015:n(0)"
          }
        },
        [51003014] = {
          ContentJP = "此度より君たちに訪れるであろう壮絶な未来に私は興味を禁じ得ない。無事に生還した暁には、どのような物語が紡がれたのか教えてくれまいか！",
          DialogueId = 51003014,
          GUID = "7FAE41FC",
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700015:Talk01_End"
          }
        },
        [51003101] = {
          ContentJP = "カミラさんの話だと、バックさんは酒がまったくダメで、一滴も飲まないって聞いたけど……この酒、誰かがこっそり混ぜたの？",
          DialogueId = 51003101,
          GUID = "7FAE5042",
          NextDialogue = 51003102,
          SpeakNpcId = 100001
        },
        [51003102] = {
          ContentJP = "よく見ると……ミルク壺に小さな、べたべたした手形が残ってる。──ずいぶん小さな手だ。",
          DialogueId = 51003102,
          GUID = "7FAE506C",
          SpeakNpcId = 100001
        },
        [51003103] = {
          ContentJP = "小さな足跡が外から窓辺まで続いている。屋内には雪解け水も。荒らした様子はない……単に、小さな子どもが入り込んだだけのようだ。",
          DialogueId = 51003103,
          GUID = "7FAE5096",
          SpeakNpcId = 100001
        },
        [51003104] = {
          ContentJP = "どうやら子どもが牛乳に酒を混ぜて、バックさんを酔わせたみたいだね。他にも手がかりを探してみよう。",
          DialogueId = 51003104,
          Duration = 4,
          GUID = "7FAE50C0",
          SpeakNpcId = 100001
        },
        [51003105] = {
          ContentJP = "こんにちは。普段、バックさんのところに遊びに来る子どもっていますか？",
          DialogueId = 51003105,
          GUID = "7FAE50EA",
          NextDialogue = 51003106,
          SpeakNpcId = 100001
        },
        [51003106] = {
          ContentJP = "子ども？まさか、あんな家と酒場と劇場の往復しかしない変人に興味を持つ子なんかいないよ。",
          DialogueId = 51003106,
          GUID = "7FAE5114",
          NextDialogue = 51003107,
          SpeakNpcId = 700213
        },
        [51003107] = {
          ContentJP = "あんたも見たでしょう？子どもどころか、あいつ、誰ともろくに喋れないし、まともな働き口もない。昔からご近所の厄介者だよ。",
          DialogueId = 51003107,
          GUID = "7FAE513E",
          NextDialogue = 51003108,
          SpeakNpcId = 700213
        },
        [51003108] = {
          ContentJP = "隣人の老婆は延々とバックの悪口をまくしたてた。やっと話が一段落したところで、あなたはそっとその場を離れた。",
          DialogueId = 51003108,
          GUID = "7FAE5168",
          NextDialogue = 51003109
        },
        [51003109] = {
          ContentJP = "バックさんは引きこもりがちで、外部との接点もほとんどない。彼に酒を飲ませようとした子どもは、きっと何か特別な情報を知っていたはず……",
          DialogueId = 51003109,
          GUID = "7FAE5192",
          NextDialogue = 51003110,
          SpeakNpcId = 100001
        },
        [51003110] = {
          ContentJP = "アスフォデロスにも子どもはいないし、家の近くにもそれらしい目撃情報はない。残るは劇場だ、行ってみよう。",
          DialogueId = 51003110,
          GUID = "7FAE51BC",
          SpeakNpcId = 100001
        },
        [51003111] = {
          ContentJP = "チケット売り場近くで、寒さに震えながら小さな子どもがチラシやポップコーンを売っている。",
          DialogueId = 51003111,
          GUID = "7FAE51E6",
          NextDialogue = 51003112
        },
        [51003112] = {
          ContentJP = "待ちゆく人に商品を勧めている子ども。彼がバックさんを酔わせた犯人なのかな？",
          DialogueId = 51003112,
          GUID = "7FAE5210",
          SpeakNpcId = 100001
        },
        [51003113] = {
          ContentJP = "バックさんは劇場によく出入りしていた。この子に何度も飲み物を売りつけられていたに違いない。",
          DialogueId = 51003113,
          Duration = 3,
          GUID = "7FAE523A",
          NextDialogue = 51003114,
          SpeakNpcId = 100001
        },
        [51003114] = {
          ContentJP = "窓下で拾ったポップコーンの欠片と、あの子の持っているポップコーン……同じだ。間違いない、話を聞いてみよう。",
          DialogueId = 51003114,
          Duration = 4,
          GUID = "7FAE5264",
          SpeakNpcId = 100001
        },
        [51003115] = {
          ContentJP = "飲むぞ～！俺はまだ飲める！あと二十本は余裕だ！もっとビール持ってこい！",
          DialogueId = 51003115,
          GUID = "7FAE528E",
          NextDialogue = 51003116,
          SpeakNpcId = 700214
        },
        [51003116] = {
          ContentJP = "ベロベロに酔ったオジサン。彼がバックさんを酔わせた犯人なのかな？",
          DialogueId = 51003116,
          GUID = "7FAE52B8",
          SpeakNpcId = 100001
        },
        [51003117] = {
          ContentJP = "パパ、あのポップコーン食べてみたい～！",
          DialogueId = 51003117,
          GUID = "7FAE52E2",
          LookAt = {
            [1] = "700215:n(700219)",
            [2] = "700219:n(700215)"
          },
          NextDialogue = 51003118,
          SpeakNpcId = 700215
        },
        [51003118] = {
          ContentJP = "ダメだ。あんなジャンクフードは身体に悪い。劇が終わったらレストランに連れて行ってやろう。",
          DialogueId = 51003118,
          GUID = "7FAE530C",
          NextDialogue = 51003119,
          SpeakNpcId = 700219,
          TalkActionId = {
            [1] = "700219:Talk03_Start"
          }
        },
        [51003119] = {
          ContentJP = "……はぁい。",
          DialogueId = 51003119,
          GUID = "7FAE5336",
          NextDialogue = 51003120,
          SpeakNpcId = 700215,
          TalkActionId = {
            [1] = "700219:Talk03_End"
          }
        },
        [51003120] = {
          ContentJP = "劇場前にいる子ども。ポップコーンに興味津々だ。彼女がバックさんを酔わせた犯人なのかな？",
          DialogueId = 51003120,
          GUID = "7FAE5360",
          SpeakNpcId = 100001
        },
        [51003301] = {
          ContentJP = "ハックチュン！なんだかいつもより寒いや……",
          DialogueId = 51003301,
          GUID = "7FAE7112",
          NextDialogue = 51003302,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Sigh_Start"
          }
        },
        [51003302] = {
          ContentJP = "カロンといえど無理なものは無理だよ……夜は一気に冷えるのが普通だし……20℃差だっけ。また凍死するヤツも出そうかな、はは……",
          DialogueId = 51003302,
          GUID = "7FAE713C",
          NextDialogue = 51003303,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Sigh_End"
          }
        },
        [51003303] = {
          ContentJP = "こんにちは。",
          DialogueId = 51003303,
          GUID = "7FAE7166",
          NextDialogue = 51003304,
          SpeakNpcId = 100001
        },
        [51003304] = {
          ContentJP = "これはどうも親愛なるお客様！ご観劇お疲れさまでございました！3時間もお座りになられたのなら、きっとお腹がお空きでしょう？お菓子やお飲み物はいかがでしょうか？",
          DialogueId = 51003304,
          GUID = "7FAE7190",
          NextDialogue = 51003305,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003305] = {
          ContentJP = "それか素晴らしいショーに心動かされたのですか？ならば俳優のサイン入りポスターなどご覧になられませんか？",
          DialogueId = 51003305,
          GUID = "7FAE71BA",
          NextOptions = {
            [1] = 510033051,
            [2] = 510033052
          },
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003306] = {
          ContentJP = "{性别:何を売っているのか見せてよ。|何を売っているのか見せてくれ。}",
          DialogueId = 51003306,
          GUID = "7FAE71E4",
          NextDialogue = 51003307,
          SpeakNpcId = 100001
        },
        [51003307] = {
          ContentJP = "ヴィティの特別サイン入りポスター、『アイスフォルクテイル』記念ハンドブック、氷山の湧き水、劇場コラボのポップコーン、そしてさっぱりビールです！",
          DialogueId = 51003307,
          GUID = "7FAE720E",
          NextDialogue = 51003308,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain01_Start"
          }
        },
        [51003308] = {
          ContentJP = "ご安心を、度数はないのと同じぐらいですから、酔っ払うことはありゃしません！",
          DialogueId = 51003308,
          GUID = "7FAE7238",
          NextDialogue = 51003309,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain01_End"
          }
        },
        [51003309] = {
          ContentJP = "{性别:必ずそうだとは言い切れないと思うけど……ところで劇作家のバックさんって知っているかな？|必ずそうだとは言い切れないと思うけど……ところで劇作家のバックさんって知っているか？}",
          DialogueId = 51003309,
          GUID = "7FAE7262",
          NextDialogue = 51003310,
          SpeakNpcId = 100001
        },
        [51003310] = {
          ContentJP = "もちろん存じておりますとも！劇場の常連様で私のところにもよく足を運んでくださります！高貴なお方でありながら僕のようなカロンにもお目をかけてくださる大変素晴らしいお人でございますね！",
          DialogueId = 51003310,
          GUID = "7FAE728C",
          NextDialogue = 51003311,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Agree"
          }
        },
        [51003311] = {
          ContentJP = "あの方を冷やかす連中もいますが、そんな人たちよりもバック先生の方が何倍も尊敬に値しますよ。",
          DialogueId = 51003311,
          GUID = "7FAE72B6",
          NextDialogue = 51003312,
          SpeakNpcId = 700080
        },
        [51003312] = {
          ContentJP = "だからといって、夜中に彼の家に忍び込んで、ミルクに酒を仕込む理由にはならないよ。",
          DialogueId = 51003312,
          GUID = "7FAE72E0",
          NextDialogue = 51003313,
          SpeakNpcId = 100001
        },
        [51003313] = {
          ContentJP = "あ、ど、どうして、知って……",
          DialogueId = 51003313,
          GUID = "7FAE730A",
          NextDialogue = 51003321,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Shock_Start"
          }
        },
        [51003314] = {
          ContentJP = "{性别:バックさんはいつも夜中に創作活動する人みたいなの。あなたがやったことのせいで1ヶ月も脚本の筆が進まなかったみたいでね、謎の「インスピレーション泥棒」を見つけて欲しいって私を雇ったのよ。|バックさんはいつも夜中に創作活動する人みたいなんだ。あなたがやったことのせいで1ヶ月も脚本の筆が進まなかったみたいでさ、謎の「インスピレーション泥棒」を見つけて欲しいって僕を雇ったんだ。}",
          DialogueId = 51003314,
          GUID = "7FAE7334",
          NextOptions = {
            [1] = 510033141
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700080:Shock_End"
          },
          bForbidSkipOptions = true
        },
        [51003315] = {
          ContentJP = "（言いたいことが口から出る前に引っかかった。頭の中でもう一度整理してみよう）",
          DialogueId = 51003315,
          GUID = "7FAE735E"
        },
        [51003316] = {
          ContentJP = "{性别:冬を生き延びるための物資を買うには売った物の利益だけじゃ足りないはず。バックさんはお金がないといっても曲がりなりに貴族だから家が十分に暖かい。というわけで暖を取るためにバックさんの家に忍び込んだって感じかな？|冬を生き延びるための物資を買うには売った物の利益だけじゃ足りないはず。バックさんはお金がないといっても曲がりなりに貴族だから家が十分に暖かい。というわけで暖を取るためにバックさんの家に忍び込んだって感じだな？}",
          DialogueId = 51003316,
          GUID = "7FAE7388",
          NextDialogue = 51003317,
          SpeakNpcId = 100001
        },
        [51003317] = {
          ContentJP = "{性别:バックさんを選んだ理由は、度数の低いお酒を少し口にするだけでも彼は眠り落ちてしまうから。寝てしまえば気づかれることなく安心して一夜を乗り越えられる……でしょ？|バックさんを選んだ理由は、度数の低いお酒を少し口にするだけでも彼は眠り落ちてしまうから。寝てしまえば気づかれることなく安心して一夜を乗り越えられる……だよな？}",
          DialogueId = 51003317,
          GUID = "7FAE73B2",
          NextDialogue = 51003318,
          SpeakNpcId = 100001
        },
        [51003318] = {
          ContentJP = "ええ……お客様は名探偵の生まれ変わりだ。事情はまさに仰った通りです。",
          DialogueId = 51003318,
          GUID = "7FAE73DC",
          NextDialogue = 51003319,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_Start"
          }
        },
        [51003319] = {
          ContentJP = "どうぞ僕をお捕まえください。捕まって当然のことをしでかしたのですから、これは自業自得です……申し訳ない……",
          DialogueId = 51003319,
          GUID = "7FAE7406",
          NextDialogue = 51003320,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700080:Explain02_End"
          }
        },
        [51003320] = {
          ContentJP = "{性别:私にどうするかを決める権利はないから、とりあえずバックさんのところまで連行するよ。|僕にどうするかを決める権利はないから、とりあえずバックさんのところまで連行するよ。}",
          DialogueId = 51003320,
          GUID = "7FAE7430",
          SpeakNpcId = 100001
        },
        [51003321] = {
          ContentJP = "（やっぱり。）",
          DialogueId = 51003321,
          GUID = "7FAE730B",
          NextDialogue = 51003314,
          SpeakNpcId = 100001
        },
        [51003401] = {
          Camera = "98.558472,-67.410156,133.285156,0.0,-1.600033,173.800858,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "見つけました。",
          DialogueId = 51003401,
          GUID = "7FAE817A",
          LookAt = {
            [1] = "700102:n(100001)",
            [2] = "100001:n(700102)"
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51003402] = {
          ContentJP = "（あなたはバックさんに経緯を伝えた）",
          DialogueId = 51003402,
          Duration = 3,
          GUID = "7FAE81A4"
        },
        [51003403] = {
          Camera = "-262.830322,120.149414,121.775391,0.000007,-0.200008,-45.795547,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "おお、我が勇士よ！勇士に1万回の拍手喝采を！今宵からインスピレーションの女神の寵愛が、再び我が身に戻るであろう！",
          DialogueId = 51003403,
          GUID = "7FAE81CE",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003404,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Agree"
          },
          TurnTo = {
            [1] = "700103:n(700102)"
          }
        },
        [51003404] = {
          Camera = "-73.412354,63.213867,126.775391,0.000008,0.200002,-62.796665,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "続けて……私の夢中にいた小さき泥棒よ。君は真に莫大なサプライズを私に与えてくれたな！",
          DialogueId = 51003404,
          GUID = "7FAE81F8",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003405,
          SpeakNpcId = 700015,
          TurnTo = {
            [1] = "700102:n(700103)"
          }
        },
        [51003405] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "本当に申し訳ありません、バック先生……でもどうか信じてもらいたい。あなたを傷つける気はこれっぽっちもなかったんです……",
          DialogueId = 51003405,
          GUID = "7FAE8222",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003406,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700103:Explain02_Start"
          }
        },
        [51003406] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ああ、小さき泥棒。私は把握しているのだよ。売れない作品ばかりの三流劇作家だと皆が陰口を吹かせているのは。",
          DialogueId = 51003406,
          GUID = "7FAE824C",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003407,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700103:Explain02_End"
          }
        },
        [51003407] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "どれほど美しいレトリックで言葉を飾っても、彼らから称賛を受けるなど早々ないだろう。彼らは理解できぬモノを拒む、耳を傾ける努力さえ億劫だ……飾らず話せる人など世界に存在し得ぬというのにな。",
          DialogueId = 51003407,
          GUID = "7FAE8276",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003408,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Talk03_Start"
          }
        },
        [51003408] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "先生、できれば噛み砕いてご説明いただけると……",
          DialogueId = 51003408,
          GUID = "7FAE82A0",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003409,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700102:Talk03_End",
            [2] = "700103:Disagree"
          }
        },
        [51003409] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "私としては尊重したいわけだな。私を支離滅裂な語り口調の愚者だと扱わなかった君を。なぜ速やかに冬を乗り越えるのが難しいと教えてくれなかったのだ？",
          DialogueId = 51003409,
          GUID = "7FAE82CA",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003410,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Agree"
          }
        },
        [51003410] = {
          Camera = "-92.579468,176.0,104.482422,0.000083,1.000179,-63.000008,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "君の部屋を用意するとしよう。もし君が望むのであれば就寝時、私の原稿を枕元に携えてもよい。ただ私の物語で睡眠の質が上がるのかは別の話だが。",
          DialogueId = 51003410,
          GUID = "7FAE82F4",
          LookAt = {
            [1] = "700102:n(700103)"
          },
          NextDialogue = 51003411,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Explain01_Start"
          }
        },
        [51003411] = {
          Camera = "-49.103394,-198.604492,136.482422,0.000076,-6.999994,74.199654,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "受け入れて……くださるのですか？本当に……僕にそんな価値は。ですがこの1ヶ月の創作を遅らせた償いはします！身の回りのお世話ぐらいは、やらせてください……！",
          DialogueId = 51003411,
          GUID = "7FAE831E",
          LookAt = {
            [1] = "700103:n(700102)"
          },
          NextDialogue = 51003412,
          SpeakNpcId = 700080,
          TalkActionId = {
            [1] = "700102:Explain01_End",
            [2] = "700103:Explain02_Start"
          }
        },
        [51003412] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "謳われるべき月狩り人どの。君が巡らせた万物に心からの感謝を。優れた洞察力を有するアイスレイク城の探偵として、君は唯一無二であろう。私は一節の温かな物語を、そしてふたりの誠実な友を得ることができた。",
          DialogueId = 51003412,
          GUID = "7FAE8348",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          NextDialogue = 51003413,
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700103:Explain02_End"
          },
          TurnTo = {
            [1] = "700102:n(100001)"
          }
        },
        [51003413] = {
          Camera = "-143.197754,12.932617,126.775391,0.000008,0.0,-32.595322,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ああ！インスピレーションが間断なく溢れて止まぬ！早急に帰らねば！一切を書き留めなければ！もし後世に私の詩が言い伝えられたならば、何千何百年であろうと人々は君の名を賛美し続けるであろう！",
          DialogueId = 51003413,
          GUID = "7FAE8372",
          LookAt = {
            [1] = "700102:n(100001)"
          },
          SpeakNpcId = 700015,
          TalkActionId = {
            [1] = "700102:Talk01_Start"
          }
        },
        [51003414] = {
          ContentJP = "（ふたりは一緒に立ち去り、誰もが自分の願い事を叶えた。次の大作がバックさんの言うように素晴らしいものとなるかどうかは未知数だが）",
          DialogueId = 51003414,
          Duration = 4,
          GUID = "7FAE839C"
        },
        [51003501] = {
          Camera = "-813.361816,168.229736,207.784668,0.000003,-6.799986,-16.405685,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "我らを疫病や蒙昧、異族の脅威から遠ざけて下さった英霊たちに言葉をお贈りいたします。犠牲に感謝を。慈悲に感謝を。銀色の平和に感謝を。",
          DialogueId = 51003501,
          GUID = "7FAE91E2",
          NextDialogue = 51003520,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Explain02_Start"
          }
        },
        [51003502] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "エマさん？エマ？何を惚けていらっしゃるのですか？",
          DialogueId = 51003502,
          GUID = "7FAE920C",
          LookAt = {
            [1] = "700016:n(700086)"
          },
          NextDialogue = 51003503,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Explain02_End",
            [2] = "700086:Confident_Start"
          }
        },
        [51003503] = {
          Camera = "-344.113281,-49.567139,176.708252,0.000003,-0.399996,158.596222,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "あ、ご、ごめんなさい、先生！今すぐに！",
          DialogueId = 51003503,
          GUID = "7FAE9236",
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700086:Confident_End",
            [2] = "700016:Shock_Start"
          }
        },
        [51003504] = {
          Camera = "-336.324951,48.679199,108.230957,0.0,0.0,-9.40437,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "最近は何事にも集中できていないご様子ですが？次回は許しませんからね。",
          DialogueId = 51003504,
          GUID = "7FAE9260",
          NextDialogue = 510035041,
          SpeakNpcId = 700086,
          TalkActionId = {
            [1] = "700086:Sigh_Start"
          }
        },
        [51003505] = {
          ContentJP = "はぁ……本当つまんない……今頃おばあちゃん、何してるのかしら？",
          DialogueId = 51003505,
          GUID = "7FAE928A",
          NextOptions = {
            [1] = 510035051,
            [2] = 510035052,
            [3] = 510035053
          },
          SpeakNpcId = 700016,
          bForbidSkipOptions = true
        },
        [51003506] = {
          ContentJP = "色々とこっちも訳があるの。別に教えてあげてもいいけど、誰にも教えないって約束が守れない人には無理よ。",
          DialogueId = 51003506,
          GUID = "7FAE92B4",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035061
          },
          RestartTag = 51003506,
          SpeakNpcId = 700016,
          bForbidSkipOptions = true
        },
        [51003507] = {
          ContentJP = "ええ、そう見えるわ！",
          DialogueId = 51003507,
          GUID = "7FAE92DE",
          SpeakNpcId = 700016
        },
        [51003508] = {
          ContentJP = "じゃあ、あなたには教えてあげる！",
          DialogueId = 51003508,
          GUID = "7FAE9308",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextDialogue = 51003509,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Confident_Start"
          }
        },
        [51003509] = {
          ContentJP = "先月こっそりスラム街に遊びに行ったらね、路地裏で謎のおばあちゃんと出会ったのよ！",
          DialogueId = 51003509,
          GUID = "7FAE9332",
          NextDialogue = 51003510,
          SpeakNpcId = 700016
        },
        [51003510] = {
          ContentJP = "おばあちゃんはとても手先が器用なのよ！色々な結び方で髪の毛を編んでくれたり、花で爪を染めてくれたりもしたわ。全然知らないお話とかもいっぱい知ってるの！",
          DialogueId = 51003510,
          GUID = "7FAE935C",
          NextDialogue = 51003511,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Confident_End"
          }
        },
        [51003511] = {
          ContentJP = "おばあちゃんは私にお説教したりしないし、私を子ども扱いして適当にあしらったりしないわ。初めて会った時も私を抱き寄せてくれたの。まるで本当のおばあちゃんみたいに暖かかった……",
          DialogueId = 51003511,
          GUID = "7FAE9386",
          NextDialogue = 51003512,
          SpeakNpcId = 700016
        },
        [51003512] = {
          ContentJP = "素敵なことなのに、普通に新しい友達ができたって周りの人には教えないの{性别:か|}？",
          DialogueId = 51003512,
          GUID = "7FAE93B0",
          NextDialogue = 51003513,
          SpeakNpcId = 100001
        },
        [51003513] = {
          ContentJP = "おばあちゃんには角が生えてるから……お父様やお母様も、同級生に先生だってイジめるに決まってるもの。そのことを知ったらおばあちゃんを……",
          DialogueId = 51003513,
          GUID = "7FAE93DA",
          NextDialogue = 51003514,
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Explain02_Start"
          }
        },
        [51003514] = {
          ContentJP = "今日はおばあちゃんと会うって約束してたんだけど、学校が臨時で記念行事を始めるとか言い出しちゃってさ、約束が守れなくなっちゃって。もし暇なら、このぬいぐるみをおばあちゃんに渡してくれたりしないかしら？",
          DialogueId = 51003514,
          GUID = "7FAE9404",
          LookAt = {
            [1] = "700016:n(0)"
          },
          NextOptions = {
            [1] = 510035141,
            [2] = 51000002
          },
          SpeakNpcId = 700016,
          TalkActionId = {
            [1] = "700016:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003515] = {
          ContentJP = "あ、もう集合時間が！ありがとね！絶対届けてよ！",
          DialogueId = 51003515,
          GUID = "7FAE942E",
          SpeakNpcId = 700016
        },
        [51003520] = {
          ContentJP = "続けて学生代表のエマによる献花が……",
          DialogueId = 51003520,
          GUID = "7FAE9500",
          NextDialogue = 51003502,
          SpeakNpcId = 700086
        },
        [51003601] = {
          Camera = "-59.474121,-281.53418,130.205078,0.000004,0.0,71.19751,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "おばあさん、ありがとう。だいぶ気分も晴れたよ。それがロブの望みだったら、俺もあいつのために努力して生き続けないとね。",
          DialogueId = 51003601,
          GUID = "7FAEA24A",
          NextDialogue = 51003602,
          SpeakNpcId = 700087,
          TalkActionId = {
            [1] = "700087:Explain02_Start"
          }
        },
        [51003602] = {
          Camera = "-83.495605,207.759766,134.179199,0.000004,-0.199981,-68.802429,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "早く悲しみから抜け出すんだよ。愛しい子や、あたしたちはあんたとともにあるからさ。もし必要ならベリンダの小屋はいつでも開けておくよ。あんたのためにいつまでも。",
          DialogueId = 51003602,
          GUID = "7FAEA274",
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700087:Explain02_End",
            [2] = "700081:Explain01_Start"
          }
        },
        [51003604] = {
          ContentJP = "おやまあこんにちは！あんたとは初めましてかねぇ。アイスレイク城には着いたばかりかい？このベリンダに何かご用でも？",
          DialogueId = 51003604,
          GUID = "7FAEA2C8",
          NextOptions = {
            [1] = 510036041
          },
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain01_Start"
          }
        },
        [51003605] = {
          ContentJP = "（つたない技術で作られているぬいぐるみだが、ベリンダに少し似ているのは分かった。カロンのおばあさんはとても嬉しそうに、何度も何度もぬいぐるみに触れる）",
          DialogueId = 51003605,
          GUID = "7FAEA2F2",
          NextDialogue = 51003606,
          TalkActionId = {
            [1] = "700081:Explain01_End"
          }
        },
        [51003606] = {
          ContentJP = "ぬいぐるみから広場の気配を感じる……ああ、すっかりと忘れていたよ！記念週間の時期はひっきりなしに行事があるもんさ……",
          DialogueId = 51003606,
          GUID = "7FAEA31C",
          NextDialogue = 51003607,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003607] = {
          ContentJP = "わざわざありがとうねぇ、優しい子や。",
          DialogueId = 51003607,
          GUID = "7FAEA346",
          NextDialogue = 51003608,
          SpeakNpcId = 700081
        },
        [51003608] = {
          ContentJP = "（そう言った途端に彼女はあなたのことをじっと見つめ始める。何分間もしゃべらずに）",
          DialogueId = 51003608,
          GUID = "7FAEA370",
          NextDialogue = 51003609
        },
        [51003609] = {
          ContentJP = "あんた……大きな災いに巻き込まれたのかい……鼻を抜ける海風の香り……あたしも体が潮水で覆われた気分になるよ。そして手のひらに残っているのは……誰かの温もり。その温もりが次第に遠ざかっていく……",
          DialogueId = 51003609,
          GUID = "7FAEA39A",
          NextDialogue = 51003610,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003610] = {
          ContentJP = "アイスレイクに来てからも、あんたは困惑と悲壮の連鎖に巻き込まれているようだねぇ……なのに表に出さないよう努力をして……心底の想いを懸命に抑え込んで……",
          DialogueId = 51003610,
          GUID = "7FAEA3C4",
          NextDialogue = 51003611,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003611] = {
          ContentJP = "無礼を承知でお尋ねするけど。あんた、大切な人との繋がりが途絶えてしまったのかい？",
          DialogueId = 51003611,
          GUID = "7FAEA3EE",
          NextOptions = {
            [1] = 510036111,
            [2] = 510036112,
            [3] = 510036113
          },
          SpeakNpcId = 700081,
          bForbidSkipOptions = true
        },
        [51003612] = {
          ContentJP = "ほほ、珍しいだろう？こんな歳まで生きている、あたしみたいなカロンなんてのは。",
          DialogueId = 51003612,
          GUID = "7FAEA418",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003613] = {
          ContentJP = "分かるさ、その悲しみ。",
          DialogueId = 51003613,
          GUID = "7FAEA442",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003614] = {
          ContentJP = "無理をするんでないよ。あたしには分かるのさ。",
          DialogueId = 51003614,
          GUID = "7FAEA46C",
          NextDialogue = 51003615,
          SpeakNpcId = 700081
        },
        [51003615] = {
          ContentJP = "優しい子や。残念ながらあたしは、あんたを助ける手立てを持ち合わせていない。だけど言葉を贈ることはできる。今のあんたにぴったりだと思う言葉さ……",
          DialogueId = 51003615,
          GUID = "7FAEA496",
          NextDialogue = 51003616,
          SpeakNpcId = 700081
        },
        [51003616] = {
          ContentJP = "「旅人が一筋の道を歩み、運命の女神の紡錘が巻かれた。千差万別の糸が再び集い、目の前に失物が浮かび上がる」",
          DialogueId = 51003616,
          GUID = "7FAEA4C0",
          NextOptions = {
            [1] = 510036161
          },
          RestartTag = 51003616,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          },
          bForbidSkipOptions = true
        },
        [51003617] = {
          ContentJP = "優しい子や、欠けた全ては旅の道中で拾えるはずさ。いってらっしゃい。",
          DialogueId = 51003617,
          GUID = "7FAEA4EA",
          SpeakNpcId = 700081
        },
        [51003618] = {
          ContentJP = "『運命の女神の紡錘』終幕から……全てを奪われた者が、対極の境で奪われた全てを見る……失ったとしても、いつかは必ず再会できるって言いたいのですか？",
          DialogueId = 51003618,
          GUID = "7FAEA514",
          NextDialogue = 51003619,
          SpeakNpcId = 100001
        },
        [51003619] = {
          ContentJP = "その一節をぬいぐるみのお礼とさせておくれ。あんたはあたしの見立て通り……とても賢い。手取り足取り教える必要もなさそうだねぇ。きっと自力で疑問を解き明かせるはずさ。",
          DialogueId = 51003619,
          GUID = "7FAEA53E",
          NextDialogue = 51003620,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Agree"
          }
        },
        [51003620] = {
          ContentJP = "それと、初めて私を訪ねてくれた人には、ちょっとした贈り物を渡してるの。あなた自身の気配が染みついたワイヤーを一本持ってきて。今じゃなくてもいいわ、ここでずっと待ってるから。",
          DialogueId = 51003620,
          GUID = "7FAEA568",
          NextDialogue = 51003621,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Explain02_Start"
          }
        },
        [51003621] = {
          ContentJP = "気配……よくわからないけど、触ったものとか、身に着けたものなら大丈夫ってことだよね。",
          DialogueId = 51003621,
          GUID = "7FAEA592",
          NextDialogue = 51003622,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700081:Explain02_End"
          }
        },
        [51003622] = {
          ContentJP = "グルビューム廃坑のあたりなら、ワイヤーがたくさん落ちてそう。行ってみよう。",
          DialogueId = 51003622,
          Duration = 3,
          GUID = "7FAEA5BC",
          SpeakNpcId = 100001
        },
        [51003630] = {
          ContentJP = "見知らぬカロンの顔には涙の跡が。瞳の奥には生き抜こうと燃え盛る勇気が見て取れた。",
          DialogueId = 51003630,
          Duration = 4,
          GUID = "7FAEA70C",
          NextDialogue = 51003631
        },
        [51003631] = {
          ContentJP = "彼はベリンダを抱きしめた後、名残惜しそうに立ち去っていく",
          DialogueId = 51003631,
          Duration = 2,
          GUID = "7FAEA736"
        },
        [51003701] = {
          ContentJP = "（ベリンダはあなたの手から針金を受け取った。すると針金を横顔の肖像画みたいな形に曲げ始めた。やがて完成した小さな工芸品にはベレニカの面影が窺える）",
          DialogueId = 51003701,
          GUID = "7FAEB2B2",
          NextDialogue = 51003702
        },
        [51003702] = {
          ContentJP = "あたしの力はそう強くないから、ぼんやりとした影しか見えなかった。あんたの想い人に似ているかは見当もついていないけど、少しでも楽になれる代物が作れたのなら幸いさ。",
          DialogueId = 51003702,
          GUID = "7FAEB2DC",
          NextDialogue = 51003703,
          SpeakNpcId = 700081,
          TalkActionId = {
            [1] = "700081:Disagree"
          }
        },
        [51003703] = {
          ContentJP = "あんたともうひとりが再会を果たせるよう、心からお祈りしておくよ。",
          DialogueId = 51003703,
          GUID = "7FAEB306",
          NextDialogue = 51003704,
          SpeakNpcId = 700081
        },
        [51003704] = {
          ContentJP = "（ベリンダの小さなテントから離れた。なぜエマがあんなにも彼女に会いたがっていたのか、分かった気がした。強い力を持っていなくとも、常に心を癒して痛みを和らげてくれるからだろう）",
          DialogueId = 51003704,
          GUID = "7FAEB330"
        },
        [51003705] = {
          Camera = "-279.652405,-157.0,151.0,0.000004,-6.0,21.800476,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "うん……これだけあれば十分なはず！",
          DialogueId = 51003705,
          FinalCamera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAEA5BD",
          NextDialogue = 51003706,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          },
          ToFinalCameraBlendTime = 5
        },
        [51003706] = {
          Camera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ててて手を上げろ！その懐の物をよこせ！",
          DialogueId = 51003706,
          GUID = "7FAEA5BE",
          NextDialogue = 51003707,
          Scripts = "SEQ{PlayAnimation{ActorId{100001},AnimationId{\"Think_End\"},Duration{1}},TurnTo{_delay{1},TurnToDescription{\"100001:p(180)\"}}}",
          SpeakNpcId = 700206
        },
        [51003707] = {
          Camera = "128.007935,301.234375,103.0,0.000009,0.0,-108.798302,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ルーナ族の影が突如飛び出してきて、あなたが抱えていたワイヤーをひったくった。そして、にやにや笑いながら逃げていった。",
          DialogueId = 51003707,
          GUID = "7FAEA5BF",
          NextDialogue = 51003708,
          Scripts = "MoveTo{ActorId{700206},TargetPoint{\"QuestPoint_DJMove\"},MoveSpeed{200},Visibility{\"Show\"}}"
        },
        [51003708] = {
          Camera = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ついにチャンスをモノにしたぞ！ややややっと成功した、わはははは！",
          DialogueId = 51003708,
          GUID = "7FAEA5C0",
          NextDialogue = 51003709,
          SpeakNpcId = 700206
        },
        [51003709] = {
          Camera = "21.397217,106.074219,131.0,0.00001,0.0,-116.797485,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ワイヤーが何に使われるかは知らないが、ただで盗られてたまるか。追いかけて取り返そう！",
          DialogueId = 51003709,
          GUID = "7FAEA5C1",
          TalkActionId = {
            [1] = "100001:Confident_Start"
          }
        },
        [51003710] = {
          ContentJP = "ルーナ族の略奪者に勝つ",
          DialogueId = 51003710,
          GUID = "7FAEA5C2"
        },
        [51003711] = {
          Camera = "-279.652405,-135.0,151.0,0.000004,-6.0,21.80052,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "たかがガラクタのために、なんでここまで……ぐすっ……",
          DialogueId = 51003711,
          GUID = "7FAEA5C3",
          SpeakNpcId = 700206
        },
        [51003712] = {
          ContentJP = "色々と手こずったが、無事に自分のワイヤーを取り戻すことができた。ふと顔を上げると、ルーナの姿はもう見当たらない。",
          DialogueId = 51003712,
          Duration = 5,
          GUID = "7FAEA5C4",
          NextDialogue = 51003713
        },
        [51003713] = {
          ContentJP = "ため息をつきつつ、ベリンダのテントへ向かうことにした。",
          DialogueId = 51003713,
          GUID = "7FAEA5C5"
        },
        [51003721] = {
          Content = "打打打打打劫皎皎已逃走，任务失败，请重新开始。",
          DialogueId = 51003721,
          Duration = 3,
          GUID = "7FAEA5C6"
        },
        [51003801] = {
          ContentJP = "あなたは……カロン……私と同族……",
          DialogueId = 51003801,
          GUID = "7FAEC31A",
          NextDialogue = 51003802,
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Explain02_Start"
          }
        },
        [51003802] = {
          ContentJP = "（目の前の少女が何か呟いている。彼女の瞳はあなたを見ているようにも、未知の遠方を見ているようにも見える）",
          DialogueId = 51003802,
          GUID = "7FAEC344",
          NextOptions = {
            [1] = 510038021,
            [2] = 510038022
          },
          TalkActionId = {
            [1] = "700012:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51003803] = {
          ContentJP = "助けてくれるのですか……？",
          DialogueId = 51003803,
          GUID = "7FAEC36E",
          NextDialogue = 51003805,
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Agree"
          }
        },
        [51003804] = {
          ContentJP = "ううん……私はソラの民じゃないのです……",
          DialogueId = 51003804,
          GUID = "7FAEC398",
          NextDialogue = 51003805,
          SpeakNpcId = 700012,
          TalkActionId = {
            [1] = "700012:Disagree"
          }
        },
        [51003805] = {
          ContentJP = "ほら見て、私の……悪魔の角を。",
          DialogueId = 51003805,
          GUID = "7FAEC3C2",
          NextDialogue = 51003806,
          SpeakNpcId = 700012
        },
        [51003806] = {
          ContentJP = "（少女は自分の乱れた毛先をつかんで見せてくる。しかしそれは半分ほどけているだけのおさげ髪であって角の要素などない。彼女は正真正銘のソラの民である）",
