          SpeakNpcId = 700088,
          TalkActionId = {
            [1] = "700088:Sigh_Start",
            [2] = "700089:Shock_Start"
          }
        },
        [51004102] = {
          Camera = "-342.361328,156.479492,90.07373,0.0,0.0,-33.384811,20.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "うぐ……たしかにヤバそうだ！早く逃げよう！",
          DialogueId = 51004102,
          GUID = "7FAEF47C",
          LookAt = {
            [1] = "700089:n(700088)"
          },
          NextDialogue = 51004103,
          SpeakNpcId = 700089
        },
        [51004103] = {
          Camera = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "{性别:待ちなよ。|待てよ。}",
          DialogueId = 51004103,
          GUID = "7FAEF4A6",
          NextDialogue = 51004104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51004104] = {
          Camera = "-97.533691,-5.197266,119.393066,0.000077,-0.399996,173.011871,20.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "{性别:フェイはもう私という悪魔と契約を結んだ。あんたたちが危害を加えたりしたら、私は1分も経たず目の前に現れるから。忘れないでね。|フェイはもう僕という悪魔と契約を結んだ。あんたたちが危害を加えたりしたら、僕は1分も経たず目の前に現れるから。忘れるなよ。}",
          DialogueId = 51004104,
          GUID = "7FAEF4D0",
          NextDialogue = 51004105,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700088:Sigh_End"
          }
        },
        [51004105] = {
          Camera = "-199.681152,34.707031,99.213867,0.000074,-2.198085,-15.786639,20.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "お……お前……くっ！",
          DialogueId = 51004105,
          GUID = "7FAEF4FA",
          SpeakNpcId = 700088,
          TalkActionId = {
            [1] = "700088:Angry01_Start"
          }
        },
        [51004106] = {
          ContentJP = "（学生たちは一目散に逃げていった）",
          DialogueId = 51004106,
          GUID = "7FAEF524"
        },
        [51004107] = {
          ContentJP = "{性别:ほら、あいつらなんてこの程度だよ。|ほら、あいつらなんてこの程度さ。}",
          DialogueId = 51004107,
          GUID = "7FAEF54E",
          NextDialogue = 51004108,
          SpeakNpcId = 100001
        },
        [51004108] = {
          ContentJP = "……はい！",
          DialogueId = 51004108,
          GUID = "7FAEF578",
          NextDialogue = 51004109,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004109] = {
          ContentJP = "あなたのお陰です……あいつらを倒す姿、本当に格好よかった！",
          DialogueId = 51004109,
          GUID = "7FAEF5A2",
          NextOptions = {
            [1] = 510041091,
            [2] = 510041092
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004110] = {
          ContentJP = "え、そ、そうですかね？私はただ……密かに心の中で思ってたことを吐き出しただけで。",
          DialogueId = 51004110,
          GUID = "7FAEF5CC",
          NextDialogue = 51004111,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Shock_Start"
          }
        },
        [51004111] = {
          ContentJP = "ありがとうございます！こんなに爽快感を感じたのは、私、初めてです！",
          DialogueId = 51004111,
          GUID = "7FAEF5F6",
          NextDialogue = 51004112,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Shock_End"
          }
        },
        [51004112] = {
          ContentJP = "{性别:どういたしまして。これでしばらくは手を出してこないはず。私の住所を教えておくから——あいつらがまた来た時には私を探してね。それじゃ、家まで送るよ。|どういたしまして。これでしばらくは手を出してこないはず。僕の住所を教えておくから——あいつらがまた来た時には僕を探してくれ。それじゃ、家まで送るよ。}",
          DialogueId = 51004112,
          GUID = "7FAEF620",
          NextDialogue = 51004113,
          SpeakNpcId = 100001
        },
        [51004113] = {
          ContentJP = "いや！家になんて帰りたくない……！",
          DialogueId = 51004113,
          GUID = "7FAEF64A",
          NextDialogue = 51004114,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Disagree"
          }
        },
        [51004114] = {
          ContentJP = "私はカロンなのです。だからカロン族と一緒にいるの……",
          DialogueId = 51004114,
          GUID = "7FAEF674",
          NextOptions = {
            [1] = 510041141
          },
          RestartTag = 51004114,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          },
          bForbidSkipOptions = true
        },
        [51004115] = {
          ContentJP = "（少女は口を堅くつぐむ。あなたの説得に耳を貸さなかった）",
          DialogueId = 51004115,
          GUID = "7FAEF69E"
        },
        [51004116] = {
          ContentJP = "{性别:もうあいつらの程度は見たでしょ？威張り散らしていようが、いざ自分より強いヤツが来たら逃げるしかできない。|もうあいつらの程度は見ただろ？威張り散らしていようが、いざ自分より強いヤツが来たら逃げるしかできない。}",
          DialogueId = 51004116,
          GUID = "7FAEF6C8",
          NextDialogue = 51004117,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700105:Think_Start"
          }
        },
        [51004117] = {
          ContentJP = "{性别:見掛け倒しの嘘つきなんだから、あいつらがペラペラ話していたことも嘘だらけ。フェイ、あなたは正真正銘のソラの民なの。下手な嘘に騙されちゃダメよ。|見掛け倒しの嘘つきなんだから、あいつらがペラペラ話していたことも嘘だらけ。フェイ、あなたは正真正銘のソラの民だよ。下手な嘘に騙されちゃダメだ。}",
          DialogueId = 51004117,
          GUID = "7FAEF6F2",
          NextDialogue = 51004118,
          SpeakNpcId = 100001
        },
        [51004118] = {
          ContentJP = "{性别:他人の悪意で自分を疑ったり、自分を責めたりしてはいけない……私の家族が聞かせてくれた教訓。覚えておいてね。|他人の悪意で自分を疑ったり、自分を責めたりしてはいけない……僕の家族が聞かせてくれた教訓。覚えておいて。}",
          DialogueId = 51004118,
          GUID = "7FAEF71C",
          NextDialogue = 51004119,
          SpeakNpcId = 100001
        },
        [51004119] = {
          ContentJP = "（少女は少し困惑しながら目をパチクリさせた。あなたの言葉の意味を完全には理解できていないようだが、表情は和らいだように見える）",
          DialogueId = 51004119,
          GUID = "7FAEF746",
          NextDialogue = 51004120
        },
        [51004120] = {
          ContentJP = "分かりました……あなたの言うことですし、頑張って試してみます！でも最後にちょっとだけお願いが……",
          DialogueId = 51004120,
          GUID = "7FAEF770",
          NextDialogue = 51004121,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004121] = {
          ContentJP = "あなたの角、触ってもいいですか？",
          DialogueId = 51004121,
          GUID = "7FAEF79A",
          NextOptions = {
            [1] = 510041211,
            [2] = 510041212
          },
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51004122] = {
          ContentJP = "ありがとうございます！",
          DialogueId = 51004122,
          GUID = "7FAEF7C4",
          NextDialogue = 51004123,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_End"
          }
        },
        [51004123] = {
          ContentJP = "（少女はか細い手を慎重に伸ばして、あなたの頭上の角を触る）",
          DialogueId = 51004123,
          GUID = "7FAEF7EE",
          NextDialogue = 51004126
        },
        [51004124] = {
          ContentJP = "わかりました。でも触ったりしないので、見るだけでも……",
          DialogueId = 51004124,
          GUID = "7FAEF818",
          NextDialogue = 51004125,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_End"
          }
        },
        [51004125] = {
          ContentJP = "（少女は慎重に近づき、あなたの頭上の角をじっくりと見る）",
          DialogueId = 51004125,
          GUID = "7FAEF842",
          NextDialogue = 51004126
        },
        [51004126] = {
          ContentJP = "本物のカロン族の角って、こんな感じなのですね……",
          DialogueId = 51004126,
          GUID = "7FAEF86C",
          NextDialogue = 51004127,
          SpeakNpcId = 700105
        },
        [51004127] = {
          ContentJP = "赤色でキラキラと細かくて……太陽でピカピカと光ってて……私のお下げよりもずっと可愛いです。",
          DialogueId = 51004127,
          GUID = "7FAEF896",
          NextOptions = {
            [1] = 510041271
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004128] = {
          ContentJP = "そんな風に言ってくれた人はあなたが初めてなのです。今はグチャグチャになっちゃってるから……もう一度結び直さないと。",
          DialogueId = 51004128,
          GUID = "7FAEF8C0",
          NextDialogue = 51004129,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004129] = {
          ContentJP = "（少女はかばんの中から櫛を取り出した。頭の2本のお下げを丁寧に梳き直すと、持ち上げて角のようにする）",
          DialogueId = 51004129,
          GUID = "7FAEF8EA",
          NextDialogue = 51004130,
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004130] = {
          ContentJP = "これで悪魔の角のように見えますか？",
          DialogueId = 51004130,
          GUID = "7FAEF914",
          NextOptions = {
            [1] = 510041301,
            [2] = 510041302
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004131] = {
          ContentJP = "えへへ。",
          DialogueId = 51004131,
          GUID = "7FAEF93E",
          NextDialogue = 51004133,
          SpeakNpcId = 700105
        },
        [51004132] = {
          ContentJP = "あはは、それでも悪くありません。",
          DialogueId = 51004132,
          GUID = "7FAEF968",
          NextDialogue = 51004133,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004133] = {
          ContentJP = "あ、またポケットに髪留めはたくさんあるので、あなたの髪もお下げにしてみませんか？",
          DialogueId = 51004133,
          GUID = "7FAEF992",
          NextOptions = {
            [1] = 510041331,
            [2] = 510041332
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004134] = {
          ContentJP = "ちょっとだけ！ちょっとだけですから！",
          DialogueId = 51004134,
          GUID = "7FAEF9BC",
          NextDialogue = 51004135,
          SpeakNpcId = 700105
        },
        [51004135] = {
          ContentJP = "（少女はあなたに近づいてきて、つま先立ちで手を伸ばす。彼女はもう元気になった様子だ）",
          DialogueId = 51004135,
          GUID = "7FAEF9E6",
          NextDialogue = 51004136
        },
        [51004136] = {
          ContentJP = "はい、ちょっとしゃがんでくださいね……",
          DialogueId = 51004136,
          GUID = "7FAEFA10",
          NextDialogue = 51004137,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004137] = {
          ContentJP = "（後ろ髪を軽く引っ張られる感触がした。少女の髪を結ぶ動きは生え際が傷つく心配もなさそうなぐらい、とても優しい）",
          DialogueId = 51004137,
          GUID = "7FAEFA3A",
          NextDialogue = 51004138,
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004138] = {
          ContentJP = "よし！わあ、お下げ姿も可愛いです！",
          DialogueId = 51004138,
          GUID = "7FAEFA64",
          NextDialogue = 51004139,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004139] = {
          ContentJP = "残念ですが今は鏡を持ってなくて……",
          DialogueId = 51004139,
          GUID = "7FAEFA8E",
          NextDialogue = 51004140,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Think_Start"
          }
        },
        [51004140] = {
          ContentJP = "あ……わかった！描いてみせたらいいのです！",
          DialogueId = 51004140,
          GUID = "7FAEFAB8",
          NextDialogue = 51004141,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Think_End"
          }
        },
        [51004141] = {
          ContentJP = "（少女はカバンを開けてノートを取り出し、あなたの姿を真剣に描き始める）",
          DialogueId = 51004141,
          GUID = "7FAEFAE2",
          NextDialogue = 51004142
        },
        [51004142] = {
          ContentJP = "ところで、あなたのお名前は？",
          DialogueId = 51004142,
          GUID = "7FAEFB0C",
          NextOptions = {
            [1] = 510041421
          },
          SpeakNpcId = 700105,
          bForbidSkipOptions = true
        },
        [51004143] = {
          ContentJP = "はい！{nickname}さん、これでさよならになりますが、これから先もずっとあなたのことは忘れません。どうぞ、あなたを描いた絵です！！",
          DialogueId = 51004143,
          GUID = "7FAEFB36",
          NextDialogue = 51004144,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Agree"
          }
        },
        [51004144] = {
          ContentJP = "謎すぎる……これが都会人の芸術……？",
          DialogueId = 51004144,
          GUID = "7FAEFB60",
          NextDialogue = 51004145,
          SpeakNpcId = 100001
        },
        [51004145] = {
          ContentJP = "（そのままさよならして離れようとした少女だが、急に振り返ってあなたを真剣に見つめる）",
          DialogueId = 51004145,
          GUID = "7FAEFB8A",
          NextDialogue = 51004146
        },
        [51004146] = {
          ContentJP = "あの……さっき髪を結んでた時に、ふと思ったのですが……",
          DialogueId = 51004146,
          GUID = "7FAEFBB4",
          NextDialogue = 51004147,
          SpeakNpcId = 700105
        },
        [51004147] = {
          ContentJP = "いじめっ子たちはずっと「カロンは悪魔の子、野蛮で邪の塊で、常に悪いことばかり考えているんだ」って言ってましたけど……",
          DialogueId = 51004147,
          GUID = "7FAEFBDE",
          NextDialogue = 51004148,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_Start"
          }
        },
        [51004148] = {
          ContentJP = "そんな話……本当なんかじゃないのですよね？",
          DialogueId = 51004148,
          GUID = "7FAEFC08",
          NextDialogue = 51004149,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain01_End"
          }
        },
        [51004149] = {
          ContentJP = "あなたたちを虐めるための口実なだけ。そうですよね？",
          DialogueId = 51004149,
          GUID = "7FAEFC32",
          NextOptions = {
            [1] = 510041491,
            [2] = 510041492
          },
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Confident_Start"
          },
          bForbidSkipOptions = true
        },
        [51004150] = {
          ContentJP = "あなたたちは……私よりもずっと、つらい苦しみを背負っているはず。",
          DialogueId = 51004150,
          GUID = "7FAEFC5C",
          NextDialogue = 51004151,
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Confident_End"
          }
        },
        [51004151] = {
          ContentJP = "何かお手伝いできることがあれば遠慮なく私に相談してくださいね……同類だからじゃなくて、友達だから。",
          DialogueId = 51004151,
          GUID = "7FAEFC86",
          SpeakNpcId = 700105,
          TalkActionId = {
            [1] = "700105:Explain02_Start"
          }
        },
        [51004152] = {
          ContentJP = "同級生たちはまだ私のことを悪く見てきますが、もう怖くなんてありません！全部あなたのおかげです！",
          DialogueId = 51004152,
          GUID = "7FAEFCB0",
          SpeakNpcId = 700105
        },
        [51004201] = {
          ContentJP = "チッ、知らねぇ顔だな。",
          DialogueId = 51004201,
          GUID = "7FAF04BA",
          NextDialogue = 51004202,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Talk03_Start"
          }
        },
        [51004202] = {
          ContentJP = "（眼前の男は目を細めて、唇のひび割れを舐めながら乾いた言葉を吐き出した）",
          DialogueId = 51004202,
          GUID = "7FAF04E4",
          NextDialogue = 51004203
        },
        [51004203] = {
          ContentJP = "言ってみろ、誰ん紹介だ？",
          DialogueId = 51004203,
          GUID = "7FAF050E",
          NextOptions = {
            [1] = 510042031,
            [2] = 510042032,
            [3] = 510042033
          },
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Talk03_End"
          },
          bForbidSkipOptions = true
        },
        [51004204] = {
          ContentJP = "（新しい質問こそ、最高の答えとなるだろう）",
          DialogueId = 51004204,
          GUID = "7FAF0538",
          NextDialogue = 51004207
        },
        [51004205] = {
          ContentJP = "（「紹介」？恐らく彼は誰かを待っているのだろう）",
          DialogueId = 51004205,
          GUID = "7FAF0562",
          NextDialogue = 51004207
        },
        [51004206] = {
          ContentJP = "（問いかけてきた理由は分からないが、この回答を拒否する者はいないだろう）",
          DialogueId = 51004206,
          GUID = "7FAF058C",
          NextDialogue = 51004207
        },
        [51004207] = {
          ContentJP = "（男はしばらく黙り込むと、目線を上げてあなたを見つめた。彼が頭を上げたとき、脊椎から軋む音が聞こえてきそうな……そんな気がした。）",
          DialogueId = 51004207,
          GUID = "7FAF05B6",
          NextDialogue = 51004208
        },
        [51004208] = {
          ContentJP = "調子のいいガキめ。",
          DialogueId = 51004208,
          GUID = "7FAF05E0",
          NextDialogue = 51004209,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004209] = {
          ContentJP = "(彼は軽く鼻を鳴らしたが、君の答えに満足したようだ。）",
          DialogueId = 51004209,
          GUID = "7FAF060A",
          NextDialogue = 51004210
        },
        [51004210] = {
          ContentJP = "まあ誰ん紹介だろうと構わねぇさ。俺ん懐のブツが目当てなんだろ？",
          DialogueId = 51004210,
          GUID = "7FAF0634",
          NextDialogue = 51004211,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Confident_Start"
          }
        },
        [51004211] = {
          ContentJP = "（男が襟を開くと、鈍く光る金属が一瞬見える。）",
          DialogueId = 51004211,
          GUID = "7FAF065E",
          NextDialogue = 51004212,
          TalkActionId = {
            [1] = "700096:Confident_End"
          }
        },
        [51004212] = {
          ContentJP = "（彼はすぐに襟を閉じ、警戒しながら辺りを見回した）",
          DialogueId = 51004212,
          GUID = "7FAF0688",
          NextDialogue = 51004213
        },
        [51004213] = {
          ContentJP = "23mm口径、ダブルバレルの中折式だ。カロンだろうが<Default note=\"text:エジュウ\">穢獣</>だろうが、こいつにゃ敵わん。",
          DialogueId = 51004213,
          GUID = "7FAF06B2",
          NextDialogue = 51004214,
          SpeakNpcId = 700096
        },
        [51004214] = {
          ContentJP = "（男は農作業で使う殺虫剤の効果でも話すかのように、実利的な言葉をツラツラと並べた）",
          DialogueId = 51004214,
          GUID = "7FAF06DC",
          NextDialogue = 51004215
        },
        [51004215] = {
          ContentJP = "今回のブツに金は要らねぇ。ちょいとひとつ使い走ってくれりゃぁな。",
          DialogueId = 51004215,
          GUID = "7FAF0706",
          NextOptions = {
            [1] = 510042151,
            [2] = 510042152
          },
          SpeakNpcId = 700096,
          bForbidSkipOptions = true
        },
        [51004216] = {
          ContentJP = "ブルってんじゃねぇぞ？こいつを欲しがった癖によぉ？",
          DialogueId = 51004216,
          GUID = "7FAF0730",
          NextDialogue = 51004217,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Explain01_Start"
          }
        },
        [51004217] = {
          ContentJP = "要領よく済ませりゃブツ以外に報酬も上乗せてやっからよ。",
          DialogueId = 51004217,
          GUID = "7FAF075A",
          NextOptions = {
            [1] = 510042171,
            [2] = 510042172
          },
          RestartTag = 51004216,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Explain01_End"
          },
          bForbidSkipOptions = true
        },
        [51004218] = {
          ContentJP = "ほら急げ、腹くくるの悠長に待ちゃしねぇぞ俺は。",
          DialogueId = 51004218,
          GUID = "7FAF0784",
          SpeakNpcId = 700096
        },
        [51004219] = {
          ContentJP = "わかった。{性别:僕|私}に何をして欲しい{性别:んだ|の}？",
          DialogueId = 51004219,
          GUID = "7FAF07AE",
          NextDialogue = 51004220,
          SpeakNpcId = 100001
        },
        [51004220] = {
          ContentJP = "話が早ぇじゃねぇか。ターゲットは指定の場所の女以外を全部だ。場所は後で教えっからよ、根こそぎ殺ってくれや。",
          DialogueId = 51004220,
          GUID = "7FAF07D8",
          NextDialogue = 51004221,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Agree"
          }
        },
        [51004221] = {
          ContentJP = "えーっと……痴情のもつれ……？",
          DialogueId = 51004221,
          GUID = "7FAF0802",
          NextDialogue = 51004222,
          SpeakNpcId = 100001
        },
        [51004222] = {
          ContentJP = "余計な詮索はすんじゃねえ。",
          DialogueId = 51004222,
          GUID = "7FAF082C",
          NextDialogue = 51004223,
          SpeakNpcId = 700096,
          TalkActionId = {
            [1] = "700096:Disagree"
          }
        },
        [51004223] = {
          ContentJP = "（男は襟を締め、ガサついた唇を真一文字に引き結び、それ以上は何ひとつ語らなくなった）",
          DialogueId = 51004223,
          GUID = "7FAF0856"
        },
        [51004301] = {
          ContentJP = "上出来だ、金を受け取ってさっさと行け。この辺りで、もう二度とその面を見せるんじゃないよ。",
          DialogueId = 51004301,
          GUID = "7FAF1522",
          NextDialogue = 51004302,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004302] = {
          ContentJP = "この周辺の<Default note=\"text:エジュウ\">穢獣</>とかをどうにかしたかっただけなの{性别:か|}？だったら私に頼まなくとも、誰かが対処してくれたと思うけど。",
          DialogueId = 51004302,
          GUID = "7FAF154C",
          NextDialogue = 51004303,
          SpeakNpcId = 100001
        },
        [51004303] = {
          ContentJP = "んだと？対処するってそりゃぁ誰だがだよ？カロン族と犬畜生を混同してるあの脳腐れどもがか?",
          DialogueId = 51004303,
          GUID = "7FAF1576",
          NextDialogue = 51004304,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Angry01_Start"
          }
        },
        [51004304] = {
          ContentJP = "ここに住んでんのがカロンの虚弱な女と知った時、あいつらが何をやらかすか分かんねぇのかお前は？",
          DialogueId = 51004304,
          GUID = "7FAF15A0",
          NextDialogue = 51004305,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Angry01_End"
          }
        },
        [51004305] = {
          ContentJP = "（唐突に男は胸を押さえた。抉られた傷口の痛みを耐えるかのように全身を震わせている。しばらくしてから震えを止めると、地面にツバを吐き捨てた）",
          DialogueId = 51004305,
          GUID = "7FAF15CA",
          NextDialogue = 51004306
        },
        [51004306] = {
          ContentJP = "傷だらけでスっ転んでた他人を救うために、善良なカロンの女は内城区から猛り出てきた犬畜生を追っぱらった。",
          DialogueId = 51004306,
          GUID = "7FAF15F4",
          NextDialogue = 51004307,
          SpeakNpcId = 700101
        },
        [51004307] = {
          ContentJP = "それだけなのに彼女はこっ酷くぶん殴られてよ、アイスレイクの街から放り出されちまったんだ。この荒地にポイっとゴミみてぇにな。",
          DialogueId = 51004307,
          GUID = "7FAF161E",
          NextDialogue = 51004308,
          SpeakNpcId = 700101
        },
        [51004308] = {
          ContentJP = "{性别:そんな……私も彼女が別の場所で生活できるよう、手助けできるかも。|そんな……僕も彼女が別の場所で生活できるよう、手助けできるかも。}",
          DialogueId = 51004308,
          GUID = "7FAF1648",
          NextDialogue = 51004309,
          SpeakNpcId = 100001
        },
        [51004309] = {
          ContentJP = "……目前なんだ。もう少しで目標まで貯まる。",
          DialogueId = 51004309,
          GUID = "7FAF1672",
          NextDialogue = 51004310,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Agree"
          }
        },
        [51004310] = {
          ContentJP = "（男は振り向いてテントの方に目を向けた。強張った口元を珍しく一瞬だけ解き、微笑んだかのような表情を見せた）",
          DialogueId = 51004310,
          GUID = "7FAF169C",
          LookAt = {
            [1] = "700101:n(700100)"
          },
          NextDialogue = 51004311,
          TurnTo = {
            [1] = "700101:n(700100)"
          }
        },
        [51004311] = {
          ContentJP = "（朽ち木が生命を帯びてメキメキと伸びるような、そんな時に響くような音が聞こえた気がした）",
          DialogueId = 51004311,
          GUID = "7FAF16C6"
        },
        [51004401] = {
          ContentJP = "下水道で消えることのないものは？",
          DialogueId = 51004401,
          GUID = "7FAF258A",
          NextOptions = {
            [1] = 510044011,
            [2] = 510044012,
            [3] = 510044013
          },
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          bForbidSkipOptions = true
        },
        [51004402] = {
          ContentJP = "よし、来いよ",
          DialogueId = 51004402,
          GUID = "7FAF25B4",
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51004403] = {
          ContentJP = "ここは何も知らない馬鹿が来る場所じゃないんだ。",
          DialogueId = 51004403,
          GUID = "7FAF25DE",
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51004501] = {
          Camera = "-234.128906,122.0,168.883789,0.0,-11.799739,-20.999071,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "女性の姿はなかったよ。いたのは<Default note=\"text:エジュウ\">穢獣</>だけ。全部片付けたけど……まさか、何もない地面まできれいにしろってこと？",
          DialogueId = 51004501,
          FinalCamera = "-234.128906,132.925781,168.883789,0.0,-11.799766,-20.999094,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF35F2",
          LookAt = {
            [1] = "700101:n(100001)",
            [2] = "100001:n(700101)"
          },
          NextDialogue = 51004502,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Confident_Start"
          },
          ToFinalCameraBlendTime = 7
        },
        [51004502] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "へえ、口だけは達者だね。私が言ってた女がいなかったこと、不審に思わなかったかい？",
          DialogueId = 51004502,
          GUID = "7FAF361C",
          NextDialogue = 51004503,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "100001:Confident_End",
            [2] = "700101:Talk03_Start"
          }
        },
        [51004503] = {
          Camera = "-234.128906,132.925781,168.883789,0.0,-11.799766,-20.999094,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "指示された場所は掃除した。依頼内容はそれだけでしょ？",
          DialogueId = 51004503,
          GUID = "7FAF3646",
          NextDialogue = 51004504,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700101:Talk03_End",
            [2] = "100001:Explain01_Start"
          }
        },
        [51004504] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "……ふむ、それでいい。これが月狩り人ってやつだ。疑って悪かったね。こういう仕事をしてると、どうしても警戒心が抜けないものだよ。",
          DialogueId = 51004504,
          GUID = "7FAF3670",
          NextDialogue = 51004505,
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700101:Agree"
          }
        },
        [51004505] = {
          Camera = "265.636719,135.800781,103.029297,0.00002,1.999995,-157.798172,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "次はこの紙に書いてある場所だ。今度も同じように、女以外はすべて片付けな。",
          DialogueId = 51004505,
          GUID = "7FAF369A",
          SpeakNpcId = 700101,
          TalkActionId = {
            [1] = "700101:Give"
          }
        },
        [51004901] = {
          Content = "（街边一位拿着一叠纸的女人吸引了你的注意：你留意到纸上罗列着一些药剂。也许这个女人与<H>玛尔洁给的某个线索</>有关。）",
          DialogueId = 51004901,
          GUID = "7FAF7792",
          LookAt = {
            [1] = "700010:n(0)"
          }
        },
        [51004902] = {
          ContentJP = "マギーからもらった手がかりを彼女に見せることにした。",
          DialogueId = 51004902,
          FinalDialogueId = 51004905,
          GUID = "7FAF77BC",
          NextOptions = {
            [1] = 510049021,
            [2] = 510049022,
            [3] = 510049023
          },
          bForbidSkipOptions = true
        },
        [51004903] = {
          ContentJP = "（女性は何も言わず警戒の眼差しをあなたに向ける。そして首を横に振った。どうやらこれは彼女の落とし物じゃないようだ）",
          DialogueId = 51004903,
          GUID = "7FAF77E6",
          NextOptions = {
            [1] = 510049031,
            [2] = 510049032
          },
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004905] = {
          ContentJP = "ルナ……先生？この処方箋ってあなたが書いたモノですよね？",
          DialogueId = 51004905,
          GUID = "7FAF783A",
          NextDialogue = 51004906,
          SpeakNpcId = 100001
        },
        [51004906] = {
          ContentJP = "（手に持っている処方箋をルナの前に差し出す。処方箋に書かれている過激な文字を彼女に見せつけた）",
          DialogueId = 51004906,
          GUID = "7FAF7864",
          NextDialogue = 51004907
        },
        [51004907] = {
          ContentJP = "「お城の外の怪物は、僕らの肉を食べちゃう。お城のなかの怪物は、僕らの毛をむしっちゃう。猟犬はふかふかパンを食ってるけど、哀れな羊の僕たちは、地面の草を食むだけさ。腹出し尾を振り慈悲を乞い、主人の機嫌を取るだけさ」",
          DialogueId = 51004907,
          GUID = "7FAF788E",
          NextDialogue = 51004908,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004908] = {
          ContentJP = "あ……わ、わ、私……",
          DialogueId = 51004908,
          GUID = "7FAF78B8",
          NextDialogue = 51004909,
          SpeakNpcId = 700010,
          TalkActionId = {
            [1] = "700010:Shock_Start"
          }
        },
        [51004909] = {
          ContentJP = "（それを見た途端、ルナは言葉を濁した。両手を宙でヒラヒラさせて慌てふためく。筆跡から反応まで見るに、どうやら正しい持ち主を発見できたようだ）",
          DialogueId = 51004909,
          GUID = "7FAF78E2",
          NextOptions = {
            [1] = 510049091,
            [2] = 510049092
          },
          TalkActionId = {
            [1] = "700010:Shock_Loop"
          }
        },
        [51004910] = {
          ContentJP = "（ルナは少し落ち着いたようだ）",
          DialogueId = 51004910,
          GUID = "7FAF790C",
          NextDialogue = 51004912,
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004911] = {
          ContentJP = "（彼女の焦りが加速したように見える）",
          DialogueId = 51004911,
          GUID = "7FAF7936",
          NextDialogue = 51004912,
          TalkActionId = {
            [1] = "700010:Shock_End"
          }
        },
        [51004912] = {
          ContentJP = "この紙が他の人の手に渡ったら、大変な事態になり兼ねませんよ？",
          DialogueId = 51004912,
          GUID = "7FAF7960",
          NextDialogue = 51004913,
          SpeakNpcId = 100001
        },
        [51004913] = {
          ContentJP = "ルナは自分の喉元を指さすと、真っ白な紙を手に取り、必死にペンを走らせた。",
          DialogueId = 51004913,
          GUID = "7FAF798A",
          NextDialogue = 51004914,
          TalkActionId = {
            [1] = "700010:Explain02_Start"
          }
        },
        [51004914] = {
          ContentJP = "「私はかつて吟遊詩人でした。ある日、カロンを憎む者たちに捕まり、嘲られ、殴られ、髪を切られ、肌を裂かれたんです」",
          DialogueId = 51004914,
          GUID = "7FAF79B4",
          NextDialogue = 510049141,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Explain02_End"
          }
        },
        [51004915] = {
          ContentJP = "……なのに、どうして書き続けてるの？",
          DialogueId = 51004915,
          GUID = "7FAF79DE",
          NextDialogue = 51004916,
          SpeakNpcId = 100001
        },
        [51004916] = {
          ContentJP = "（ルナは頭を下げて紙に何かを書く）",
          DialogueId = 51004916,
          GUID = "7FAF7A08",
          NextDialogue = 51004917
        },
        [51004917] = {
          ContentJP = "「胸に抱えたままでは、あまりにも辛くて」",
          DialogueId = 51004917,
          GUID = "7FAF7A32",
          NextOptions = {
            [1] = 510049171,
            [2] = 510049172,
            [3] = 510049173
          },
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Disagree"
          },
          bForbidSkipOptions = true
        },
        [51004918] = {
          ContentJP = "「そうですね。何も変わりません。書いた物を人に見せる勇気さえ出せません。しかしそれでも、書きたくてたまらなくなるのです」",
          DialogueId = 51004918,
          GUID = "7FAF7A5C",
          NextDialogue = 51004919,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004919] = {
          ContentJP = "「私はもう歌えなくなりました。それで書くことさえもやめたらどうなるのでしょうか？最後の大切なモノまで失くしたくないのです。失くせば私は何者でもなく、何物もなくなってしまうのです」",
          DialogueId = 51004919,
          GUID = "7FAF7A86",
          NextDialogue = 51004920,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004920] = {
          ContentJP = "もっと実りあることで不満を解消した方がいいと思いますよ。それに次からは書いた物を厳重に仕舞いましょう。うっかり失くさないように。",
          DialogueId = 51004920,
          GUID = "7FAF7AB0",
          NextDialogue = 51004921,
          SpeakNpcId = 100001
        },
        [51004921] = {
          ContentJP = "（女性はしばらく考えてから、うなずいた）",
          DialogueId = 51004921,
          GUID = "7FAF7ADA",
          NextDialogue = 51004922,
          TalkActionId = {
            [1] = "700010:Agree"
          }
        },
        [51004922] = {
          ContentJP = "「親切な方。返してくれてありがとうございます。これはあなたへのお礼の品です」",
          DialogueId = 51004922,
          GUID = "7FAF7B04",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004923] = {
          ContentJP = "「とんでもありません。私は紙に文句を書き連ねているだけの臆病者です。それを人に見せる勇気さえ出せないのですから」",
          DialogueId = 51004923,
          GUID = "7FAF7B2E",
          NextDialogue = 51004924,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Disagree"
          }
        },
        [51004924] = {
          ContentJP = "書き記すだけでも本音に向き合えている時点で勇敢ですよ。ただ次からは書いた物を厳重に仕舞いましょう。うっかり失くさないように。",
          DialogueId = 51004924,
          GUID = "7FAF7B58",
          NextDialogue = 51004925,
          SpeakNpcId = 100001
        },
        [51004925] = {
          ContentJP = "（女性の口元に笑みが浮かんだ。うなずく彼女の眼には涙が溢れている）",
          DialogueId = 51004925,
          GUID = "7FAF7B82",
          NextDialogue = 51004926
        },
        [51004926] = {
          ContentJP = "「親切な方。返してくれてありがとうございます。これはあなたへのお礼の品です」",
          DialogueId = 51004926,
          GUID = "7FAF7BAC",
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004927] = {
          ContentJP = "（女性は掠れたような悲鳴をあげて、苦しそうに手のひらで顔を隠す。しばらくすると震えながらハンドバッグを開き、中から何かを取り出した）",
          DialogueId = 51004927,
          GUID = "7FAF7BD6",
          NextDialogue = 51004928,
          TalkActionId = {
            [1] = "700010:Sigh_Start"
          }
        },
        [51004928] = {
          ContentJP = "「これを全てお渡しします。どうかその紙を返してください」",
          DialogueId = 51004928,
          GUID = "7FAF7C00",
          NextDialogue = 51004929,
          SpeakNpcName = "UI_CMNpc_Name_Ziji",
          TalkActionId = {
            [1] = "700010:Give"
          }
        },
        [51004929] = {
          ContentJP = "（あなたは満足気にうなずいた——もし紙が他人の手に落ちた場合、彼女が失う物はこんな程度じゃ済まない。あなたは大きなトラブルに巻き込まれる不運から彼女を救ったのだ。ならばこれは当然得られるべき報酬である）",
          DialogueId = 51004929,
          GUID = "7FAF7C2A"
        },
        [51004930] = {
          ContentJP = "あうぅ……ううぅ……",
          DialogueId = 51004930,
          GUID = "7FAF7C54",
          NextDialogue = 51004931,
          SpeakNpcId = 700010
        },
        [51004931] = {
          ContentJP = "（ルナは普段通り、あなたへ向ける視線を少し逸らしながら、理解しがたい言葉を呟いている）",
          DialogueId = 51004931,
          GUID = "7FAF7C7E"
        },
        [51004935] = {
