        [51004936] = {
          ContentJP = "何を書いたか見せてもらおう――",
          DialogueId = 51004936,
          GUID = "7FAF7C80",
          NextDialogue = 51004937,
          SpeakNpcId = 700226
        },
        [51004937] = {
          ContentJP = "この前は声を潰したが……今度は目か？それとも手か？",
          DialogueId = 51004937,
          GUID = "7FAF7C81",
          NextDialogue = 51004938,
          SpeakNpcId = 700225
        },
        [51004938] = {
          ContentJP = "ぎゃっ、ああ……！",
