          bForbidSkipOptions = true
        },
        [51004945] = {
          ContentJP = "ん……んん……",
          DialogueId = 51004945,
          GUID = "7FAF7C88",
          NextDialogue = 51004946,
          SpeakNpcId = 700010
        },
        [51004946] = {
          ContentJP = "女性はかすかに笑みを浮かべた。どうやら感謝の気持ちを伝えようとしているようだ。",
          DialogueId = 51004946,
          GUID = "7FAF7C89",
          NextDialogue = 51004947,
          SpeakNpcId = 700010
        },
        [51004947] = {
          ContentJP = "知り合いに医者がいるんだ。今はアイスレイク城にはいないけど……彼の家に行けば、何か役立つ処方箋が見つかるかもしれない。",
          DialogueId = 51004947,
          GUID = "7FAF7C8A",
          NextDialogue = 51004948,
          SpeakNpcId = 100001
        },
        [51004948] = {
          ContentJP = "……",
          DialogueId = 51004948,
          GUID = "7FAF7C8B",
          NextDialogue = 51004949,
          SpeakNpcId = 700010
        },
        [51004949] = {
          ContentJP = "ルナはうつむいた。自分の喉がもう元に戻らないことを、きっと心のどこかで悟っている。それでも、彼女の目にはかすかな希望の光が宿っていた──まるで「わずかな望み」に賭けるかのように。",
          DialogueId = 51004949,
          GUID = "7FAF7C8C"
        },
        [51004950] = {
          ContentJP = "うう…あ…！",
          DialogueId = 51004950,
          GUID = "7FAF7C8D",
          NextDialogue = 51004951,
          SpeakNpcId = 700010
        },
        [51004951] = {
          ContentJP = "ルナは警戒心を隠そうともせず、あなたをじっと見つめ、必死に首を振った。「本当にお金は持っていない」という訴えがひしひしと伝わってくる。",
          DialogueId = 51004951,
          GUID = "7FAF7C8E",
          NextDialogue = 51004952,
          SpeakNpcId = 700010
        },
        [51004952] = {
          ContentJP = "そんなに怖がらなくても大丈夫。今回はちゃんと手伝いに来たんだ。……さすがに、何ももらわずに助けるのも気が引けるけどね。",
          DialogueId = 51004952,
          GUID = "7FAF7C8F",
          NextDialogue = 51004953,
          SpeakNpcId = 100001
        },
        [51004953] = {
          ContentJP = "知り合いに医者がいるんだ。今はアイスレイク城にはいないけど……彼の家に行けば、何か役立つ処方箋が見つかるかもしれない。",
          DialogueId = 51004953,
          GUID = "7FAF7C90",
          NextDialogue = 51004954,
          SpeakNpcId = 100001
        },
        [51004954] = {
          ContentJP = "ルナの顔にはまだ不信の色が濃く残っていた──今はあなたを完全には信じきれていないようだ。",
          DialogueId = 51004954,
          GUID = "7FAF7C91"
        },
        [51004955] = {
          ContentJP = "ある本棚",
          DialogueId = 51004955,
          GUID = "7FAF7C92"
        },
        [51004956] = {
          ContentJP = "アイスレイク城には奇妙な流行り病があり、\n子どもたちが苦しむことも少なくない。\n──風邪速効薬",
          DialogueId = 51004956,
          Duration = 4,
          GUID = "7FAF7C93",
          IsBlack = 1,
          NextDialogue = 51004957
        },
        [51004957] = {
          ContentJP = "……これは違う気がする。",
          DialogueId = 51004957,
          Duration = 3,
          GUID = "7FAF7C94",
          SpeakNpcId = 100001
        },
        [51004958] = {
          ContentJP = "ある本棚",
          DialogueId = 51004958,
          GUID = "7FAF7C95"
        },
        [51004959] = {
          ContentJP = "失敗作とされた抗穢蝕薬。だが、後に一部の難病症状に対して効果が見られた。",
          DialogueId = 51004959,
          Duration = 4,
          GUID = "7FAF7C96",
          IsBlack = 1,
          NextDialogue = 51004960
        },
        [51004960] = {
          ContentJP = "……これは違う気がする。",
          DialogueId = 51004960,
          Duration = 3,
          GUID = "7FAF7C97",
          SpeakNpcId = 100001
        },
        [51004961] = {
          ContentJP = "地面",
          DialogueId = 51004961,
          GUID = "7FAF7C98"
        },
        [51004962] = {
          ContentJP = "誤って蓮草を摂取した場合、\n軽度の中毒症状ならこれで解毒できる──蓮草解毒薬",
          DialogueId = 51004962,
          Duration = 5,
          GUID = "7FAF7C99",
          IsBlack = 1
        },
        [51004963] = {
          ContentJP = "これ……落ちてたけど、使えそう！",
          DialogueId = 51004963,
          Duration = 4,
          GUID = "7FAF7C9A",
          SpeakNpcId = 100001
        },
        [51004964] = {
          ContentJP = "喉の治療に使えそうな処方箋を発見",
          DialogueId = 51004964,
          Duration = 3,
          GUID = "7FAF7C9B"
        },
        [51004965] = {
          ContentJP = "もし、声が戻ったら……何を詠いたい？",
          DialogueId = 51004965,
          GUID = "7FAF7C9C",
          NextDialogue = 51004966,
          SpeakNpcId = 100001
        },
        [51004966] = {
          ContentJP = "ルナはうつむき、長い時間、静かに考え込んでいた。",
          DialogueId = 51004966,
          GUID = "7FAF7C9D",
          NextDialogue = 51004967,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004967] = {
          ContentJP = "「心の想いを打ち明けるわ──たとえ声を代償にしても」",
          DialogueId = 51004967,
          GUID = "7FAF7C9E",
          NextDialogue = 51004968,
          SpeakNpcName = "UI_CMNpc_Name_Ziji"
        },
        [51004968] = {
          ContentJP = "あなたは気づいた。この薬が本当に効果を発揮したなら、彼女はさらに過酷な道を選ぶかもしれないことを。",
          DialogueId = 51004968,
          GUID = "7FAF7C9F",
          NextOptions = {
            [1] = 51004969,
            [2] = 51004970
          }
        },
        [51004969] = {
          ContentJP = "処方箋をルナに手渡す。",
          DialogueId = 51004969,
          GUID = "7FAF7CA0",
          NextDialogue = 51004972
        },
        [51004970] = {
          ContentJP = "処方箋を隠す",
          DialogueId = 51004970,
          GUID = "7FAF7CA1",
          NextDialogue = 51004979
        },
        [51004971] = {
          ContentJP = "サブ1",
          DialogueId = 51004971,
          GUID = "7FAF7CA2"
        },
        [51004972] = {
          ContentJP = "この薬は……昔、知り合いの医者が作った蓮草中毒の治療薬なんだ。試してみない？",
          DialogueId = 51004972,
          GUID = "7FAF7CA3",
          NextDialogue = 51004973,
          SpeakNpcId = 100001
        },
        [51004973] = {
          ContentJP = "ルナは信じられないように紙を受け取り、目に涙を浮かべながら必死に頭を下げた。",
          DialogueId = 51004973,
          GUID = "7FAF7CA4",
          NextDialogue = 51004974
        },
        [51004974] = {
          ContentJP = "解毒できる処方箋を失う",
          DialogueId = 51004974,
          GUID = "7FAF7CA5",
          NextDialogue = 51004975
