          GUID = "7FAF8B96",
          NextOptions = {
            [1] = 510050231
          },
          SpeakNpcId = 700013,
          bForbidSkipOptions = true
        },
        [51005024] = {
          ContentJP = "まだやるべきことが残っていると、勝手に思い込んでいるだけにすぎません。",
          DialogueId = 51005024,
          GUID = "7FAF8BC0",
          NextDialogue = 51005025,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          }
        },
        [51005025] = {
          ContentJP = "ヘンリック先生は私めと接触するのに消極的でございましたから。なので私めも頻繁に訪れることは控えておりました。あなた様と私めが今までお会いできていなかったのはその点が理由でございます。",
          DialogueId = 51005025,
          GUID = "7FAF8BEA",
          NextDialogue = 51005026,
          SpeakNpcId = 700013
        },
        [51005026] = {
          ContentJP = "彼は恐らく望んでいないかと。死後に私めが何度もここへ訪れるなど……そう考えればこの鍵も元の持ち主に返還した方がよいのでしょう。私めは鍵をヘンリック先生の机に戻そうと考えております。どうかそれに立ち合ってはいただけませんでしょうか。",
          DialogueId = 51005026,
          GUID = "7FAF8C14",
          NextOptions = {
            [1] = 510050261
          },
          RestartTag = 51005026,
          SpeakNpcId = 700013,
          bForbidSkipOptions = true
        },
        [51005027] = {
          ContentJP = "（あなたは何も思い出せなかった。ただの勘違いかもしれない）",
          DialogueId = 51005027,
          GUID = "7FAF8C3E"
        },
        [51005028] = {
          ContentJP = "（マギーからもらった鍵だが、レナが持つヒュプノスの家の鍵によく似ているとあなたは気づいた）",
          DialogueId = 51005028,
          GUID = "7FAF8C68",
          NextDialogue = 51005029
        },
        [51005029] = {
          ContentJP = "（そしてヘンリックが鍵を持っていたことを思い出した。きっとあの夜の混乱に紛れた代物を、マギーが偶然に拾ったのだろう）",
          DialogueId = 51005029,
          GUID = "7FAF8C92",
          NextOptions = {
            [1] = 510050291
          }
        },
        [51005030] = {
          ContentJP = "ヘンリック先生は重要な書類を保管するチェストをお持ちでした。もしかすると、その鍵で開くかもしれません。",
          DialogueId = 51005030,
          GUID = "7FAF8CBC",
          NextDialogue = 51005031,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Think_Start"
          }
        },
        [51005031] = {
          ContentJP = "自分の身に不幸が降りかかったら、チェストを開けて中にある遺言書を公開するようにと、私めはヘンリック先生からお達しを受けておりました。",
          DialogueId = 51005031,
          GUID = "7FAF8CE6",
          NextDialogue = 51005032,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Think_End"
          }
        },
        [51005032] = {
          ContentJP = "鍵がなかったので家中を探していたのですが……まさかあなたのお手の中にあったとは。お預かりいただき、誠にありがとうございます。",
          DialogueId = 51005032,
          GUID = "7FAF8D10",
          NextDialogue = 51005033,
          SpeakNpcId = 700013
        },
        [51005033] = {
          ContentJP = "もしよろしければ証人として、私めがヘンリック先生の約束を遵守する様を見届けてはくださいませんか？",
          DialogueId = 51005033,
          GUID = "7FAF8D3A",
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Explain02_Start"
          }
        },
        [51005034] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "箱が開き、レナはヘンリックの遺言状を取り出す。あなたの立ち会いのもと、彼女はゆっくりと読み上げ始めた。",
          DialogueId = 51005034,
          GUID = "7FAF8D64",
          NextDialogue = 51005035
        },
        [51005035] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（ヘンリックは早くから来たる悲劇を予想していたのかもしれない。彼の遺言は冷静なものであったが、娘の死に対しては悔いが残されていた。そして——）",
          DialogueId = 51005035,
          GUID = "7FAF8D8E",
          NextDialogue = 51005036
        },
        [51005036] = {
          Camera = "-3490.197266,-340.706116,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "「私の死後、私名義に属する住宅の所有権をレナ・ベル氏に引き渡すものとする——」",
          DialogueId = 51005036,
          FinalCamera = "-2771.669922,-330.52002,876.251953,0.000004,0.0,0.812196,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8DB8",
          NextDialogue = 51005037,
          SpeakNpcId = 700013,
          ToFinalCameraBlendTime = 7
        },
        [51005037] = {
          Camera = "-956.953125,124.710449,851.333984,0.000029,-16.600037,26.61047,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "「長きに渡ってヒュプノスの家やカロンの患者たちに尽力してくれたことに感謝を」",
          DialogueId = 51005037,
          FinalCamera = "-938.859375,88.569275,851.333984,0.000038,-16.600002,26.610426,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8DE2",
          NextDialogue = 51005038,
          SpeakNpcId = 700013,
          ToFinalCameraBlendTime = 7
        },
        [51005038] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "「ベル氏が成した全ての行いに心からの感謝を贈る。彼女は尊敬されるべき女性だ」",
          DialogueId = 51005038,
          GUID = "7FAF8E0C",
          NextDialogue = 51005039,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "700013:Disagree"
          }
        },
        [51005039] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "…………",
          DialogueId = 51005039,
          GUID = "7FAF8E36",
          NextDialogue = 510050391,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          }
        },
        [51005040] = {
          ContentJP = "（あなたはひとりでヘンリックの事務室から出てきた。）\n（泣き崩れたレナさんにはしばらくひとりの時間が必要だろう。少なくとも今は彼女の悲しみに邪魔者などいらない）",
          DialogueId = 51005040,
          Duration = 4,
          GUID = "7FAF8E60",
          NextDialogue = 51005041
        },
        [51005041] = {
          ContentJP = "（こうして新しい大家さんが誕生した）",
          DialogueId = 51005041,
          Duration = 2,
          GUID = "7FAF8E8A"
        },
        [51005042] = {
          Camera = "460.455078,-127.329834,335.509766,0.000047,-28.799341,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "レナはヒュプノスの家をよく知っていた。あなたたちは迷うことなく箱を見つけ、そのそばに、不自然に置かれた木箱も見つけた。",
          DialogueId = 51005042,
          FinalCamera = "460.455078,-148.0,335.509766,0.000054,-28.799347,157.208237,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8EB4",
          NextDialogue = 51005043,
          ToFinalCameraBlendTime = 7
        },
        [51005043] = {
          Camera = "-372.582031,8.945923,112.0,0.0,0.0,0.208069,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "あなたはまず、その奇妙な木箱を開けた。中には丁寧な筆跡で書かれた手紙があり、あなたはその一字一句を、声に出して読んだ。",
          DialogueId = 51005043,
          FinalCamera = "-350.582031,9.078125,112.0,0.0,0.0,0.408069,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FAF8EDE",
          NextDialogue = 51005044,
          TalkActionId = {
            [1] = "100001:Explain02_Start"
          },
          ToFinalCameraBlendTime = 7,
          TurnTo = {
            [1] = "700098:n(100001)"
          }
        },
        [51005044] = {
          ContentJP = "「あなたがこの手紙を読んでいる頃には、私たちはもう「ヒュプノスの家」にはいないでしょう。\nあの夜、サイキの件で警備部隊が動き出し、私たちはアイスレイク城にいられなくなりました。\nだから、警備部隊の捜査が及ぶ前に、私は皆を連れてここを後にしました。\nどうか私たちのことで悲しまないでください。\nそして、私たちが穢蝕によって、誰かを傷つけることを心配する必要はありません。\n私たちは荒野へ向かいます。誰も知らない、どこか遠い場所へ。\nその先に死が待つのか、それとも奇跡が待っているのか、わからないけれど──\n最後の最後まで、希望を信じ続けます。\n……それは、彼女が私たちに教えてくれたことだから。\n最後に、これまで私たちにしてくれたすべてに、感謝を込めて。\n──エリーザ・テイラー」",
          DialogueId = 51005044,
          DialoguePanelType = "{type:showtext;topic:Reading_Title_200208;content:Reading_Content_200208}",
          GUID = "7FAF8F08",
          NextDialogue = 51005045
        },
        [51005045] = {
          Camera = "299.257812,85.246521,174.804688,-0.0,-9.999997,-170.990723,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "……そう……あの子たちは、無事に……旅立ったのね。",
          DialogueId = 51005045,
          GUID = "7FAF8F32",
          NextDialogue = 51005046,
          SpeakNpcId = 700013,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          },
          TurnTo = {
            [1] = "700098:p(140)"
          }
        },
        [51005046] = {
          Camera = "-236.947266,-87.956055,124.296875,0.0,0.0,23.006927,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "レナは長い沈黙のあと、ゆっくりと鍵を鍵穴に差し込んだ。あなたは、彼女の震える手が何度も鍵から滑り落ちるのを黙って見守った。",
          DialogueId = 51005046,
          GUID = "7FAF8F5C",
          NextDialogue = 51005047
        },
        [51005047] = {
          ContentJP = "……手伝うよ。",
          DialogueId = 51005047,
          GUID = "7FAF8F86",
          IsBlack = 1,
          NextDialogue = 51005048,
          SpeakNpcId = 100001
        },
        [51005048] = {
          ContentJP = "……ありがとう。",
          DialogueId = 51005048,
          GUID = "7FAF8FB0",
          IsBlack = 1,
          SpeakNpcId = 700013
        },
        [51005101] = {
          ContentJP = "おやおや、そこにいるのは{nickname}ちゃんじゃ、あーりませんかー？",
          DialogueId = 51005101,
          GUID = "7FAF9862",
          NextDialogue = 51005102,
          SpeakNpcId = 700115
        },
        [51005102] = {
          ContentJP = "この前はベリーサンキュー！ちゃんと生活費は配れたよ！スラム街に住むみんなも「くれぐれもお礼を伝えてくれ」ってさ！",
          DialogueId = 51005102,
          GUID = "7FAF988C",
          NextOptions = {
            [1] = 51005103
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005103] = {
          ContentJP = "いやいや、大したことじゃないから。",
          DialogueId = 51005103,
          GUID = "7FAF98B6",
          NextDialogue = 51005104
        },
        [51005104] = {
          ContentJP = "謙遜しないでって！マジになってくれる有能プロなのにマナーも素晴らしいとか、君みたいなタイプにお目にかかるのも久しぶりだよ！",
          DialogueId = 51005104,
          GUID = "7FAF98E0",
          NextDialogue = 51005105,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005105] = {
          ContentJP = "アイスレイク城にいる時間、いかがお過ごしでしょうか？",
          DialogueId = 51005105,
          GUID = "7FAF990A",
          NextOptions = {
            [1] = 510051051,
            [2] = 510051052,
            [3] = 510051053
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          },
          bForbidSkipOptions = true
        },
        [51005106] = {
          ContentJP = "そりゃよーいドンで目的地まで向かうのが人生だとは思うけどさ？道行く景色をスルーってのはもったいないよ？",
          DialogueId = 51005106,
          GUID = "7FAF9934",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005107] = {
          ContentJP = "わっかるーっ！！アイスレイク城に来たばかりの私もおんなじ気持ちだった！街特有の暗黙の了解とかイミフだし、住んでるのもエキセントリックな人が大量だし！",
          DialogueId = 51005107,
          GUID = "7FAF995E",
          NextDialogue = 51005109,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005108] = {
          ContentJP = "冗談じゃないなら君の実家もスラム的な……まさか君も逃亡してきた感じ？",
          DialogueId = 51005108,
          GUID = "7FAF9988",
          NextDialogue = 51005109,
          SpeakNpcId = 700115
        },
        [51005109] = {
          ContentJP = "まあいっか！この話はキャンセル！",
          DialogueId = 51005109,
          GUID = "7FAF99B2",
          NextDialogue = 51005110,
          SpeakNpcId = 700115
        },
        [51005110] = {
          ContentJP = "新しく商品を仕入れたからチェックしてよ！珍妙なレア物たちが目白押し！好みの品があったら、前の大活躍のお礼として20％offしちゃいま～～す！",
          DialogueId = 51005110,
          GUID = "7FAF99DC",
          NextDialogue = 51005111,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Explain02_Start"
          }
        },
        [51005111] = {
          ContentJP = "（あなたは身を屈めてマギーの「仕入れたばかりの商品」を観察した。さほど大きくない木の棚に雑多なモノが目一杯積まれてある。そのほとんどが未使用でない痕跡をはっきりと残していた。状態は綺麗なので、自分で丁寧に拭きあげたのだろう）",
          DialogueId = 51005111,
          GUID = "7FAF9A06",
          NextOptions = {
            [1] = 510051111,
            [2] = 510051112,
            [3] = 510051113
          },
          TalkActionId = {
            [1] = "700115:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005112] = {
          ContentJP = "大事なのは趣ですぜ！勘定ばかりで考えてちゃ楽しめないよ！",
          DialogueId = 51005112,
          GUID = "7FAF9A30",
          NextDialogue = 51005115,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005113] = {
          ContentJP = "ノット、ノットギルティ！私めは善良な市民でございますから！この子たちは持ち主に捨てられて、でも私にとっては宝物なんです！浪費を見て見ぬフリする方が本当の罪ってもんじゃない！？この子たちに帰るべき場所を探してあげたいだけなんだって！",
          DialogueId = 51005113,
          GUID = "7FAF9A5A",
          NextDialogue = 51005115,
          SpeakNpcId = 700115
        },
        [51005114] = {
          ContentJP = "ふぁふぁふぁ、そりゃ企業秘密ですよ！トップシークレット！",
          DialogueId = 51005114,
          GUID = "7FAF9A84",
          NextDialogue = 51005115,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005115] = {
          ContentJP = "（手厚いサービス精神に押されて断ることができなかったあなたは、マギーの「ガラクタ山」を探った。そこから価値があるものを見つけようとする）",
          DialogueId = 51005115,
          GUID = "7FAF9AAE",
          NextOptions = {
            [1] = 510051151,
            [2] = 510051152,
            [3] = 510051153
          },
          RestartTag = 51005115,
          bForbidSkipOptions = true
        },
        [51005116] = {
          ContentJP = "好みの品が見つからないなら無理しないで大丈夫だよ！今度仕入れた時にでも見に来てくれたらいいからさ！",
          DialogueId = 51005116,
          GUID = "7FAF9AD8",
          SpeakNpcId = 700115
        },
        [51005117] = {
          ContentJP = "さっすがお目が高い！その子が貴重品であることに気づくとは！君も探偵特有の鋭い嗅覚を持ってるようだね！",
          DialogueId = 51005117,
          GUID = "7FAF9B02",
          NextOptions = {
            [1] = 51005118
          },
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Agree"
          }
        },
        [51005118] = {
          ContentJP = "探偵って？全然関係なくない……？",
          DialogueId = 51005118,
          GUID = "7FAF9B2C",
          NextDialogue = 51005119
        },
        [51005119] = {
          ContentJP = "君のセレクトした品は無価物でもあるし有価物でもあるよ。無価物とは文字通り数枚の銅貨にもならないってこと。他の人は見向きもしないと思う。",
          DialogueId = 51005119,
          GUID = "7FAF9B56",
          NextDialogue = 51005120,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Think_Start"
          }
        },
        [51005120] = {
          ContentJP = "一方で有価物とは……この子たちの内々から漂ってくる「ストーリー性」の強さ！君はそれを見抜いたんでしょ？",
          DialogueId = 51005120,
          GUID = "7FAF9B80",
          NextDialogue = 51005121,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Think_End"
          }
        },
        [51005121] = {
          ContentJP = "ならば忍耐力と観察力をマックスにして暴き出せるはず！この宝物の裏に隠されてある物語と秘密を！",
          DialogueId = 51005121,
          GUID = "7FAF9BAA",
          NextDialogue = 51005122,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005122] = {
          ContentJP = "ゴミ箱を侮っちゃあいけないのさ。事件や噂の真相は、大体がちょっとした片隅に隠れている！私もこの街に関することは、ゴミ箱を通して少しずつ知っていったからね。",
          DialogueId = 51005122,
          GUID = "7FAF9BD4",
          NextDialogue = 51005123,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          }
        },
        [51005123] = {
          ContentJP = "気になってきたかな！？この街についてもっと知りたくなったよね！？というわけで、お支払いはこちらにて～！",
          DialogueId = 51005123,
          GUID = "7FAF9BFE",
          NextDialogue = 51005124,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Confident_Start"
          }
        },
        [51005124] = {
          ContentJP = "（なんだか上手く乗せられているだけな気が……）",
          DialogueId = 51005124,
          GUID = "7FAF9C28",
          NextDialogue = 51005125,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700115:Confident_End"
          }
        },
        [51005125] = {
          ContentJP = "待ってなんだいその目は！目ん玉に「悪徳商人」って文字を浮かべるのストップ！ただのセールトークだし、君だってもう私のコレクションに引っかかる何かを感じてるんでしょ？中途半端に終わりにする気はないよね？",
          DialogueId = 51005125,
          GUID = "7FAF9C52",
          NextOptions = {
            [1] = 510051251,
            [2] = 510051252,
            [3] = 510051253
          },
          SpeakNpcId = 700115,
          bForbidSkipOptions = true
        },
        [51005126] = {
          ContentJP = "いや、かといって素直すぎない？気恥ずかしくなるんだけど……",
          DialogueId = 51005126,
          GUID = "7FAF9C7C",
          NextDialogue = 51005129,
          SpeakNpcId = 700115
        },
        [51005127] = {
          ContentJP = "流石は月狩り人。予算管理を怠らないのは全員共通だけど……",
          DialogueId = 51005127,
          GUID = "7FAF9CA6",
          NextDialogue = 51005129,
          SpeakNpcId = 700115
        },
        [51005128] = {
          ContentJP = "タタ、タンマ、行かないで！もうちょっと粘りを見せてよ！",
          DialogueId = 51005128,
          GUID = "7FAF9CD0",
          NextDialogue = 51005129,
          SpeakNpcId = 700115
        },
        [51005129] = {
          ContentJP = "そもそも泥棒キャッチャーを手伝ってくれたからね。感謝の気持ちとして3つの商品を君にプレゼントしちゃう予定だったのさ！",
          DialogueId = 51005129,
          GUID = "7FAF9CFA",
          NextDialogue = 51005130,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Talk02_Start"
          }
        },
        [51005130] = {
          ContentJP = "（マギーは有無を言わさず3つの商品を一気にあなたの懐へ詰め込んだ）",
          DialogueId = 51005130,
          GUID = "7FAF9D24",
          NextDialogue = 51005131,
          TalkActionId = {
            [1] = "700115:Talk02_End"
          }
        },
        [51005131] = {
          ContentJP = "調査が首尾よく進展することを、心よりお祈りしておきますです！名探偵閣下！",
          DialogueId = 51005131,
          GUID = "7FAF9D4E",
          NextDialogue = 51005132,
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Explain02_Start"
          }
        },
        [51005132] = {
          ContentJP = "この3種の宝に潜むストーリーを調べ上げた先！君のアイスレイク城への想いがどうなるか！全部の調査が終わったら教えてね！",
          DialogueId = 51005132,
          GUID = "7FAF9D78",
          SpeakNpcId = 700115,
          TalkActionId = {
            [1] = "700115:Explain02_End"
          }
        },
        [51005201] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "おっかえり～～！",
          DialogueId = 51005201,
          FacialId = {
            [1] = "700127:Smile02"
          },
          GUID = "7FAFA8CA",
          NextDialogue = 51005202,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Explain02_Start"
          }
        },
        [51005202] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "というわけで早速と教えちゃってくださいな！一体全体、どんな巨大な秘密を暴き出したのか！",
          DialogueId = 51005202,
          GUID = "7FAFA8F4",
          NextOptions = {
            [1] = 510052021,
            [2] = 510052022,
            [3] = 510052023
          },
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Explain02_End"
          }
        },
        [51005203] = {
          Camera = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "だったら「今後は一切こんなこと書かないように」とか言うのは残酷すぎるね……よし！彼女の出す紙くず類のゴミに気を配っておくよ！できるだけ他の人に気づかれないようにする！",
          DialogueId = 51005203,
          GUID = "7FAFA91E",
          NextDialogue = 51005206,
          Scripts = "SEQ{PlayAnimation{ActorId{700127},AnimationId{\"Sigh_Start\"},Duration{2}},PlayAnimation{ActorId{700127},AnimationId{\"Sigh_End\"},Duration{1}}}",
          SpeakNpcId = 700127
        },
        [51005204] = {
          Camera = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "彼女が思ってるほど外の世界は美しくないかもだけど……そんな希望がどうしても必要だったんだね。",
          DialogueId = 51005204,
          FacialId = {
            [1] = "700127:Iyada01"
          },
          GUID = "7FAFA948",
          NextDialogue = 51005206,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Agree"
          }
        },
        [51005205] = {
          Camera = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "君もレナさんもWin Winで大ラッキーに終わったんだね！善き人を導いたからこそのご褒美だよきっと！",
          DialogueId = 51005205,
          FacialId = {
            [1] = "700127:Satisfy01"
          },
          GUID = "7FAFA972",
          NextDialogue = 51005206,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Agree"
          }
        },
        [51005206] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "マーベラス！流石の優れた洞察力！君ってば希代の名探偵！",
          DialogueId = 51005206,
          FacialId = {
            [1] = "700127:Ahaha02"
          },
          GUID = "7FAFA99C",
          NextDialogue = 51005207,
          SpeakNpcId = 700127
        },
        [51005207] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "君の手にかかればアイスレイク城の目立たない場所であっても、フレッシュなサプライズが見つけられるはず……単なるビックリ地点なだけかもだけどさ？",
          DialogueId = 51005207,
          GUID = "7FAFA9C6",
          NextDialogue = 51005208,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Explain02_Start"
          }
        },
        [51005208] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "まま、それはともかくとして、アっちココっちと動き回ったはずですからね。では予告通りお尋ねしましょう！アイスレイク城に対して、何か新しい気持ちは湧いたりした？",
          DialogueId = 51005208,
          FacialId = {
            [1] = "700127:Confident02"
          },
          GUID = "7FAFA9F0",
          NextOptions = {
            [1] = 510052081,
            [2] = 510052082,
            [3] = 510052083,
            [4] = 510052084,
            [5] = 510052085
          },
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005209] = {
          Camera = "0.445557,77.976562,129.532715,0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ほぉぉ……それが君の見つけ出した答えか！なんて言うか当てようと考えてたんだけど、これっぽっちも掠らなかったよ！",
          DialogueId = 51005209,
          FacialId = {
            [1] = "700127:Happy01"
          },
          GUID = "7FAFAA1A",
          NextDialogue = 51005210,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Think_Start"
          }
        },
        [51005210] = {
          Camera = "52.368652,-229.308594,141.289062,0.000091,-3.599974,111.20826,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "君ってばここに長く滞在しそうだね？ただの慌ただしい通りすがりだったら、そんな答えは出せないし！",
          DialogueId = 51005210,
          GUID = "7FAFAA44",
          NextDialogue = 51005211,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Think_End",
            [2] = "100001:Agree"
          }
        },
        [51005211] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "つまりは私たちの付き合いも長くなるはず。だよね？",
          DialogueId = 51005211,
          GUID = "7FAFAA6E",
          NextDialogue = 51005212,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Confident_Start"
          }
        },
        [51005212] = {
          Camera = "40.984619,215.874023,127.513672,0.0,1.599924,-112.192589,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "もう誰かが言ってるかもしれないけど、私からも——",
          DialogueId = 51005212,
          GUID = "7FAFAA98",
          NextDialogue = 51005213,
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Confident_End"
          }
        },
        [51005213] = {
          Camera = "12.572754,75.52832,130.532715,-0.0,0.199879,-101.394386,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "アイスレイク城へようこそ！旅人さん！",
          DialogueId = 51005213,
          FacialId = {
            [1] = "700127:Happy02"
          },
          GUID = "7FAFAAC2",
          SpeakNpcId = 700127,
          TalkActionId = {
            [1] = "700127:Talk02_Start"
          }
        },
        [51005301] = {
          ContentJP = "キチンと消毒さえ行えば、ハラショーな料理に仕上がることでしょう！",
          DialogueId = 51005301,
          GUID = "7FAFB932",
          NextDialogue = 51005302,
          SpeakNpcId = 700116
        },
        [51005302] = {
          ContentJP = "生臭さはなくなりましたが、いや、しかし、水産物本来の新鮮な甘みを引き出さなければ……",
          DialogueId = 51005302,
          GUID = "7FAFB95C",
          NextDialogue = 51005303,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Think_Start"
          }
        },
        [51005303] = {
          ContentJP = "（目の前の男は早口で何かを呟いている。手に持つ冊子と名も知らぬ魚やエビを血走った目で凝視しながら、ネギの葉が引っついた手で何かを書いている）",
          DialogueId = 51005303,
          GUID = "7FAFB986",
          NextOptions = {
            [1] = 510053031,
            [2] = 510053032
          },
          TalkActionId = {
            [1] = "700116:Think_End"
          },
          bForbidSkipOptions = true
        },
        [51005304] = {
          ContentJP = "（バインダーのリングが僅かながら錆びついている。丁重に扱われていた古い冊子なのだろうが、最近は手入れを怠っていることが分かる）",
          DialogueId = 51005304,
          GUID = "7FAFB9B0",
          NextDialogue = 51005305
        },
        [51005305] = {
          ContentJP = "（近寄って内容を観察してみる。乱雑な図形と線の間に数種のスパイスや調理方法のフレーズが記されているとギリギリ読み取れた。この男の手にしている冊子は恐らくレシピなのだろう）",
          DialogueId = 51005305,
          GUID = "7FAFB9DA",
          NextDialogue = 51005307
        },
        [51005306] = {
          ContentJP = "（今すぐ踵を返して離れるのが一番の選択だろう。そう思い足を動かしたが、地面にこぼれていた粘液を踏んでピチャッと音を立ててしまった）",
          DialogueId = 51005306,
          GUID = "7FAFBA04",
          NextDialogue = 51005307
        },
        [51005307] = {
          ContentJP = "（男の注意は音に向き、あなたの存在に気づく）",
          DialogueId = 51005307,
          GUID = "7FAFBA2E",
          NextDialogue = 51005308
        },
        [51005308] = {
          ContentJP = "……アナタ様は？",
          DialogueId = 51005308,
          GUID = "7FAFBA58",
          NextDialogue = 51005309,
          SpeakNpcId = 700116
        },
        [51005309] = {
          ContentJP = "ただの通りすがりの月狩り人です。",
          DialogueId = 51005309,
          GUID = "7FAFBA82",
          NextDialogue = 51005310,
          SpeakNpcId = 100001
        },
        [51005310] = {
          ContentJP = "月狩り人であれば、ボクの依頼を引き受けてはくれませんか？イッショにハラショーな料理を完成させましょう！",
          DialogueId = 51005310,
          GUID = "7FAFBAAC",
          NextOptions = {
            [1] = 51000001,
            [2] = 51000002
          },
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Explain02_Start"
          },
          bForbidSkipOptions = true
        },
        [51005311] = {
          ContentJP = "ありがとな。まず最初の料理は、漁師の間で伝わる生魚と生エビの漬け方を改良したもんや。エサはまだ残っとるし、漬け込みに使う素材、ちょっと釣ってきてくれへんか？",
          DialogueId = 51005311,
          GUID = "7FAFBAD6",
          NextOptions = {
            [1] = 510053111,
            [2] = 510053112
          },
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Explain02_End"
          },
          bForbidSkipOptions = true
        },
        [51005312] = {
          ContentJP = "そや！そのあいだに、うちは料理と消毒の準備しとくさかいな。エサがなくなったら、またうちのところに戻ってきてや。",
          DialogueId = 51005312,
          GUID = "7FAFBB00",
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Agree"
          }
        },
        [51005313] = {
          ContentJP = "ここの天然の塩泉には、漬物に必要な材料があるようだ。いくつか採取して持ち帰ろう。",
          DialogueId = 51005313,
          GUID = "7FAFBB2A",
          SpeakNpcId = 100001
        },
        [51005314] = {
          Content = "钓到了，回去找马库斯吧。",
          DialogueId = 51005314,
          GUID = "7FAFBB54",
          SpeakNpcId = 100001
        },
        [51005315] = {
          Content = "钓到了，回去找马库斯吧。",
          DialogueId = 51005315,
          GUID = "7FAFBB7E",
          SpeakNpcId = 100001
        },
        [51005401] = {
          ContentJP = "事前にネギの葉を切り落とす……魚やエビは丁寧に洗ってから塩と酢を加える……アイスレイク城のミナサンのお好みを考えて砂糖を少々加えるのも検討しなければ……",
          DialogueId = 51005401,
          GUID = "7FAFC99A",
          NextDialogue = 51005402,
          SpeakNpcId = 700116
        },
        [51005402] = {
          ContentJP = "（マーカスは無言で材料を受け取る。そして調理方法を呟きながら街の中へと消えていった）",
          DialogueId = 51005402,
          GUID = "7FAFC9C4"
        },
        [51005403] = {
          ContentJP = "（と思ったひと段落後にどこからともなくマーカスが飛び出してくる。そのまま雪の中に倒れ込むと、ようやく自分の失態に気づいた様子だ。気まずそうに笑いながら体についた汚れを手で払い落す）",
          DialogueId = 51005403,
          GUID = "7FAFC9EE",
          NextDialogue = 51005404
        },
        [51005404] = {
          ContentJP = "……ハハ、失礼いたしました。",
          DialogueId = 51005404,
          GUID = "7FAFCA18",
          NextDialogue = 51005405,
          SpeakNpcId = 700116
        },
        [51005405] = {
          ContentJP = "アナタ様もどうかおアジミを。アイスレイク独特の風味を舌で感じていただければ。",
          DialogueId = 51005405,
          GUID = "7FAFCA42",
          NextDialogue = 51005406,
          SpeakNpcId = 700116
        },
        [51005406] = {
          ContentJP = "（彼の懐から密封された魚とエビが取り出された。真っ黒なソースに浸されていて、キラキラと光を放っている。フィルムで閉じられていても、濃厚な味噌の香りが漏れ出ている）",
          DialogueId = 51005406,
          GUID = "7FAFCA6C",
          NextOptions = {
            [1] = 510054061,
            [2] = 510054062,
            [3] = 510054063
          },
          TalkActionId = {
            [1] = "700116:Give"
          }
        },
        [51005407] = {
          ContentJP = "古い考えで料理と向き合うのはいけません。人生一度は常識外な食文化にチョウセンしてみないと、豊かさはハンゲンしてしまいますよ。",
          DialogueId = 51005407,
          GUID = "7FAFCA96",
          NextDialogue = 51005410,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Disagree"
          }
        },
        [51005408] = {
          ContentJP = "ハハハ、無理はなさらないでください。申し訳ございません。そんな今にも泣き出しそうなおカオにさせてしまい。",
          DialogueId = 51005408,
          GUID = "7FAFCAC0",
          NextDialogue = 51005410,
          SpeakNpcId = 700116
        },
        [51005409] = {
          ContentJP = "ヌヌ、やれやれ。誰もが食材の多様性に偏見を持つ人ばかりではございませんが……ナルホド……",
          DialogueId = 51005409,
          GUID = "7FAFCAEA",
          NextDialogue = 51005410,
          SpeakNpcId = 700116
        },
        [51005410] = {
          ContentJP = "……とにかく、改良の余地がまだまだ残っているのは事実です。",
          DialogueId = 51005410,
          GUID = "7FAFCB14",
          NextDialogue = 51005411,
          SpeakNpcId = 700116,
          TalkActionId = {
            [1] = "700116:Agree"
          }
        },
        [51005411] = {
          ContentJP = "次のフタローエもどうかよろしくお頼みいたしますボクの美食のパルトニョール！",
          DialogueId = 51005411,
          GUID = "7FAFCB3E",
          SpeakNpcId = 700116
        },
        [51005501] = {
          ContentJP = "ヴァリーチで胃を温める作用を、であればザクースキとしてちょうどいいでしょうか、今まだ不足していると考えられるのは……",
          DialogueId = 51005501,
          GUID = "7FAFDA02",
          NextDialogue = 51005502,
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Think_Start"
          }
        },
        [51005502] = {
          ContentJP = "（マーカスの顔は真っ白だ。アイスレイクの冷たい風に吹かれて血の気が消え去っている。よく観察しないと誰かに捨てられた氷の彫刻だと思ってしまいそうなほどに）",
          DialogueId = 51005502,
          GUID = "7FAFDA2C",
          NextDialogue = 51005503
        },
        [51005503] = {
          ContentJP = "（だが環境の過酷さと体の悲鳴に彼はまったく関心を抱いていないようだ）",
          DialogueId = 51005503,
          GUID = "7FAFDA56",
          NextDialogue = 51005504
        },
        [51005504] = {
          ContentJP = "（材料、味付け、調理方法を一心不乱に読み上げて、すぐに否定するを繰り返して、頭の中で究極の料理への道筋を探っている）",
          DialogueId = 51005504,
          GUID = "7FAFDA80",
          NextDialogue = 51005505,
          TalkActionId = {
            [1] = "700117:Think_End"
          }
        },
        [51005505] = {
          ContentJP = "ヤー我がパルトニョール！来てくださいましたか！",
          DialogueId = 51005505,
          GUID = "7FAFDAAA",
          NextDialogue = 51005506,
          SpeakNpcId = 700117,
          TurnTo = {
            [1] = "700117:n(0)"
          }
        },
        [51005506] = {
          ContentJP = "今な、まだ「霜降りトゲウオ」っちゅう魚が足りてへんねん。あれはなかなかお目にかかれへんけど、相棒やったらきっと釣ってきてくれるって信じとる。頼んだで！",
          DialogueId = 51005506,
          GUID = "7FAFDAD4",
          NextDialogue = 51005507,
          SpeakNpcId = 700117
        },
        [51005507] = {
          ContentJP = "難易度は上がったものの、あなたはむしろほっとした。少なくとも、今度は生ものを試食させられる心配はなさそうだ。",
          DialogueId = 51005507,
          GUID = "7FAFDAFE"
        },
        [51005508] = {
          ContentJP = "しばらく釣りをして、ようやくマーカスが求めている霜降りトゲウオを手に入れた。",
          DialogueId = 51005508,
          Duration = 3,
          GUID = "7FAFDB28"
        },
        [51005601] = {
          ContentJP = "（マーカスがアイスベリーの皮を剥いている。何も言わず一心不乱なそのありようは一層、氷の彫刻かのような印象を抱いてしまうが。時折ピクピクと眉を動かしているが、あなたはそれを痛みを感じている仕草だと感じた）",
          DialogueId = 51005601,
          GUID = "7FAFEA6A",
          NextOptions = {
            [1] = 510056011,
            [2] = 510056012
          },
          bForbidSkipOptions = true
        },
        [51005602] = {
          ContentJP = "（果皮に血と土が付着している。果実の数個が力を入れすぎたせいか変形してしまっている。マーカスの手のひらにできた新しい傷を見るに、アイスベリーはマーカス自身が崖を登って摘んだのだろう）",
          DialogueId = 51005602,
          GUID = "7FAFEA94",
          NextOptions = {
            [1] = 51005604
          }
        },
        [51005603] = {
          ContentJP = "（マーカスの服の端が血で染まっている。ついさっき怪我したのだろうか。あなたは止血しようとしたが、マーカスが負った怪我にあまり効果はなかった）",
          DialogueId = 51005603,
          GUID = "7FAFEABE",
          NextOptions = {
            [1] = 51005604
          }
        },
        [51005604] = {
          ContentJP = "この血は……",
          DialogueId = 51005604,
          GUID = "7FAFEAE8",
          NextDialogue = 51005605,
          SpeakNpcId = 100001
        },
        [51005605] = {
          ContentJP = "たいしたことあらへん。アイスベリーを摘んどるときに、ちょっとすべってケガしただけや。それより……おっ、霜降りトゲウオ、釣れたんやな！さすがや、うちの目に狂いはなかったわ。ほんま、ありがとな！",
          DialogueId = 51005605,
          GUID = "7FAFEB12",
          NextDialogue = 51005606,
          SpeakNpcId = 700117,
          TurnTo = {
            [1] = "700117:n(0)"
          }
        },
        [51005606] = {
          ContentJP = "（マーカスは自分の怪我について多くを語らず手を動かし続けた。汚れていないアイスベリーを鍋に投入して、よく混ぜる。スープを掬いあげて軽くひと口、味見する）",
          DialogueId = 51005606,
          GUID = "7FAFEB3C",
          NextDialogue = 51005607
        },
        [51005607] = {
          ContentJP = "新鮮なアイスベリーをスープに入れると、豊潤なカオリが増していく……",
          DialogueId = 51005607,
          GUID = "7FAFEB66",
          NextDialogue = 51005608,
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Agree"
          }
        },
        [51005608] = {
          ContentJP = "これは霜降りトゲウオの調理方法も再考が必要ですな……",
          DialogueId = 51005608,
          GUID = "7FAFEB90",
          NextDialogue = 51005609,
          SpeakNpcId = 700117
        },
        [51005609] = {
          ContentJP = "マーカスは怪我した体を引きずりながらも材料の油抜き、茹で、煮込み、長い複雑なプロセスを完了させた。",
          DialogueId = 51005609,
          GUID = "7FAFEBBA",
          NextDialogue = 51005610
        },
        [51005610] = {
          ContentJP = "（食べ物の香りが徐々に強くなる中で焚き火の傍から立ち上がると、彼は料理を椀いっぱいによそった。そして食客の評価を心待ちにしている）",
          DialogueId = 51005610,
          GUID = "7FAFEBE4",
          NextDialogue = 51005611
        },
        [51005611] = {
          ContentJP = "ゴホゴホ……完成いたしましたよ。どうぞごショウミあれ。ハラショーな特色のある料理ができているか、評価を下していただけますでしょうか？",
          DialogueId = 51005611,
          GUID = "7FAFEC0E",
          NextOptions = {
            [1] = 51005612
          },
          SpeakNpcId = 700117,
          TalkActionId = {
            [1] = "700117:Give"
          }
        },
        [51005612] = {
          ContentJP = "とても美味しい、体が温まるよ。",
          DialogueId = 51005612,
          GUID = "7FAFEC38",
          NextDialogue = 51005613
        },
        [51005613] = {
          ContentJP = "ハラショー……本当によかった……！早急に内城区に戻って、ボスにもボクたちの成果を味わっていただきます！",
          DialogueId = 51005613,
          GUID = "7FAFEC62",
          NextDialogue = 51005614,
          SpeakNpcId = 700117
        },
        [51005614] = {
          ContentJP = "バリショエスパシーバ！我がパルトニョール！これはイッショに作り上げた料理、ボクたちの料理です！ドナタもきっと好きになってくださるに違いありません！ボスも絶賛するのが目に浮かんできます！",
          DialogueId = 51005614,
          GUID = "7FAFEC8C",
          SpeakNpcId = 700117
        },
        [51005701] = {
          ContentJP = "…………",
          DialogueId = 51005701,
          GUID = "7FAFFAD2",
          NextDialogue = 51005702
        },
        [51005702] = {
          ContentJP = "（マーカスに会ったのは3回目だろうか。彼は静かに椅子に座り込んでいる。顔は憔悴しきっており、肌はカサカサで長らく寝ていないようだ。膝には弁当箱が置かれてあった）",
          DialogueId = 51005702,
          GUID = "7FAFFAFC",
          NextDialogue = 51005703
        },
        [51005703] = {
          ContentJP = "（体に負った傷はいまだ適切に手当てされていない。もしここが蒸し暑い都市であったならば、傷口から腐臭が立ち込め始めているかもしれないほどの具合だ）",
          DialogueId = 51005703,
          GUID = "7FAFFB26",
          NextOptions = {
            [1] = 51005704
          }
        },
        [51005704] = {
          ContentJP = "{性别:……大丈夫？ボスに何かを言われちゃったの？|……大丈夫？ボスに何かを言われちゃったのか？}",
          DialogueId = 51005704,
          GUID = "7FAFFB50",
          NextDialogue = 51005705
        },
        [51005705] = {
          ContentJP = "…………",
          DialogueId = 51005705,
          GUID = "7FAFFB7A",
          LookAt = {
            [1] = "700121:n(0)"
          },
          NextDialogue = 51005706,
          SpeakNpcId = 700121
        },
        [51005706] = {
          ContentJP = "……ウージャス……ハハ。ボスは見向きもしてくれませんでした。ボクの料理はいつまで経っても儲けにならない、オマエを雇っているのはムダだと。",
          DialogueId = 51005706,
          GUID = "7FAFFBA4",
          NextOptions = {
            [1] = 51005707
          },
          SpeakNpcId = 700121
        },
        [51005707] = {
          ContentJP = "…………",
          DialogueId = 51005707,
          GUID = "7FAFFBCE",
          NextDialogue = 51005708
        },
        [51005708] = {
          ContentJP = "もう疲れてしまったのですが……実は最後の一品も完成しているのです。よろしければヒトクチ、いかがでしょうか？",
          DialogueId = 51005708,
          GUID = "7FAFFBF8",
          NextDialogue = 51005709,
          SpeakNpcId = 700121
        },
        [51005709] = {
          ContentJP = "（マーカスは震える手で弁当箱を開けると、煮込み料理とミートボールの香りが混ざり合い、食欲をそそる香りが広がる。）",
          DialogueId = 51005709,
          GUID = "7FAFFC22",
          NextDialogue = 51005710
        },
        [51005710] = {
          ContentJP = "（上品な肉料理ではないが、人々が一日中働くためのエネルギーを支えるのに十分な料理だ。星の形にカットされたポテトが添えられ、料理に独自の心遣いが感じられる。）",
          DialogueId = 51005710,
          GUID = "7FAFFC4C",
          NextDialogue = 51005711
        },
        [51005711] = {
          ContentJP = "（あなたは料理を口に運んだ。平凡な見た目からは想像できないほどの、表現しえない旨味が湧き出る。体中に力が滾り、精神が奮い立つ。アイスレイクの厳しい冬さえ恐れぬ心身が備わったかのように思えた）",
          DialogueId = 51005711,
          GUID = "7FAFFC76",
          NextDialogue = 51005712
        },
        [51005712] = {
          ContentJP = "（弁当箱の下にはレシピがしっかりと畳まれて置かれている。何度も書き直された痕跡がありありと見える試行錯誤の結晶だ。マーカスはコクリと頷いたことで、レシピの主人が今から新しくなる。そして微笑みながら彼は、食客の評価を待っていた）",
          DialogueId = 51005712,
          GUID = "7FAFFCA0",
          NextOptions = {
            [1] = 510057121,
            [2] = 510057122
          },
          bForbidSkipOptions = true
        },
        [51005713] = {
          ContentJP = "スパシーバ……本当にありがとう……ボクの作った料理を食べてくださって……",
          DialogueId = 51005713,
          GUID = "7FAFFCCA",
          NextDialogue = 51005714,
          SpeakNpcId = 700121
        },
        [51005714] = {
          ContentJP = "（マーカスは長く息を吐いたかと思うと、力なく腕を垂らし、ゆっくりと目を閉じた）",
          DialogueId = 51005714,
          GUID = "7FAFFCF4",
          NextDialogue = 51005715
        },
        [51005715] = {
          ContentJP = "食材集めも……お疲れさまでございました……ゆっくりオヤスミください……ボクも…………",
          DialogueId = 51005715,
          GUID = "7FAFFD1E",
          NextDialogue = 51005719,
          SpeakNpcId = 700121
        },
        [51005716] = {
          ContentJP = "ボクの料理を……こんなにも多くの失敗をしても信じてくださるのですか……感謝しております……ボクの作った料理を……召し上がってくださったこと……",
          DialogueId = 51005716,
          GUID = "7FAFFD48",
          NextDialogue = 51005717,
          SpeakNpcId = 700121
        },
        [51005717] = {
          ContentJP = "（マーカスは長く息を吐いたかと思うと、力なく腕を垂らし、ゆっくりと目を閉じた）",
          DialogueId = 51005717,
          GUID = "7FAFFD72",
          NextDialogue = 51005718
        },
        [51005718] = {
          ContentJP = "パルトニョールのためで……ございますからね……ボクは今よりも……励まねば……ですが今は……やはり……少しオヤスミを…………",
          DialogueId = 51005718,
          GUID = "7FAFFD9C",
          NextDialogue = 51005719,
          SpeakNpcId = 700121
        },
        [51005719] = {
          ContentJP = "（マーカスは満足そうな笑顔を見せた。彼は心の中で一番欲しかったであろう言葉を見出せたのだろう）",
          DialogueId = 51005719,
          GUID = "7FAFFDC6"
        },
