          ToFinalCameraBlendTime = 10
        },
        [51005810] = {
          ContentJP = "（『帝国三兄弟のお宝！』と明らかについさっき書いたばかりのモノだと分かる文字が箱には書かれてあった。彼は口笛を吹きながら知らないフリをしている）",
          DialogueId = 51005810,
          GUID = "7FB00CB4",
          NextDialogue = 51005811
        },
        [51005811] = {
          Camera = "1.0383,-161.240234,125.036621,0.000154,-3.793118,125.094276,35.000011,1.5,false,Disable,1.2",
          ContentJP = "俺ら帝国三兄弟のお宝に手を出すイカれポンチは帝国中をひっくり返したっていやしねえのに。こりゃベンショー的なヤツがなきゃ許さないぜ。7……8……9……きゅう、キュー。9の次ってなんぞ？",
          DialogueId = 51005811,
          GUID = "7FB00CDE",
          NextOptions = {
            [1] = 51005812,
            [2] = 51005813
          },
          Scripts = "PlayAnimation{_delay{3},ActorId{700123},AnimationId{\"Think_Start\"},Duration{1}}",
