            [1] = "700148:Explain02_Start"
          }
        },
        [51007133] = {
          ContentJP = "お前は星織人なの？！それなら…13年前にアイスレイク城に来た「嘉言」という名前の<Default note=\"text:カショ\">華胥</>の星織人を知っている？",
          DialogueId = 51007133,
          GUID = "7FB0E5C2",
