        },
        [51007134] = {
          ContentJP = "さあな。星織人なんて山ほどいるから。",
          DialogueId = 51007134,
          GUID = "7FB0E5EC",
          NextDialogue = 51007135,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Disagree"
          }
        },
        [51007135] = {
          ContentJP = "…そうか。",
          DialogueId = 51007135,
          GUID = "7FB0E616",
          NextDialogue = 51007136,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007136] = {
          ContentJP = "君が言っているその人は、お知り合い？",
          DialogueId = 51007136,
