        },
        [51007137] = {
          ContentJP = "ふふ、知り合い？違うわよ、あれは私が最も嫌いな人だ。",
          DialogueId = 51007137,
          GUID = "7FB0E66A",
          NextDialogue = 51007138,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Disagree"
          }
        },
        [51007138] = {
          ContentJP = "（ジェシカは紙星を一つ開け、文字を一瞥し、次の星を開け始める。こうして一つずつ…）",
          DialogueId = 51007138,
          GUID = "7FB0E694",
          NextDialogue = 51007139
        },
        [51007139] = {
          ContentJP = "彼は多くの国を訪れ、たくさんの面白い人々や出来事に出会ったと言ってた。それに、商品を売るたびに、遠くの地からの物語を話してくれた。",
          DialogueId = 51007139,
          GUID = "7FB0E6BE",
          NextDialogue = 51007140,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Explain01_Start"
          }
        },
        [51007140] = {
          ContentJP = "私は馬鹿みたいに、こうして彼の話を一つ一つ覚えてた。それで彼の言う広い世界に近づけると思ってたんだ。",
          DialogueId = 51007140,
          GUID = "7FB0E6E8",
          NextDialogue = 51007141,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Explain01_End"
          }
        },
        [51007141] = {
          ContentJP = "「星は願いの種。それが落ちると、願いが実る」、彼はそう言ってた。「愛するものから作られた無数の星が地上で芽生える」って。",
          DialogueId = 51007141,
          GUID = "7FB0E712",
          NextDialogue = 51007142,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Explain02_Start"
          }
        },
        [51007142] = {
          ContentJP = "彼と一緒に旅をして、話を聞き続けたかった。でも切符が買えず、最後は彼が遠くへ向かう列車に乗るのを見送るしかなかったのよ。",
          DialogueId = 51007142,
          GUID = "7FB0E73C",
          NextDialogue = 51007143,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Explain02_End"
          }
        },
        [51007143] = {
          ContentJP = "（彼女はもう一つ、少し黄ばんでいた切符で作った紙星を開けた。裏には「ここを離れて、君の足跡を追いたい」と書かれていた）",
          DialogueId = 51007143,
          GUID = "7FB0E766",
          NextDialogue = 51007144
        },
        [51007144] = {
          ContentJP = "ふふ……あった。このチケット、あの人が乗った列車のだ。あの列車はヒュペリアを越えて、ずっと南へ向かうの。",
          DialogueId = 51007144,
          GUID = "7FB0E790",
          NextDialogue = 51007145,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Talk02_Start"
          }
        },
        [51007145] = {
          ContentJP = "当時、切符売りが私を哀れんで、売れ残ったチケットを一枚タダでくれたんだ。「向こう行きの列車ならまだいっぱいあるよ」ってね。",
          DialogueId = 51007145,
          GUID = "7FB0E7BA",
          NextDialogue = 51007146,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Talk02_End"
          }
        },
        [51007146] = {
          ContentJP = "でも、結局私はチケットを買うお金もなくて、ただじっと横で見てるしかなかった。それでも売り方を覚えて、気づいたら自分が売る側になってた。",
          DialogueId = 51007146,
          GUID = "7FB0E7E4",
          NextDialogue = 51006931,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Disagree"
          }
        },
        [51007147] = {
          ContentJP = "（彼女はため息をつき、動きを止め、開けた星と開けていない星をすべてまとめて、テーブルの隅に押しのける）",
          DialogueId = 51007147,
          GUID = "7FB0E80E",
          NextDialogue = 51007148
        },
        [51007148] = {
          ContentJP = "これで分かったでしょ？この紙星はただのゴミだ。わざわざと返してくれてありがとう。次は細かく破って捨てるから。",
          DialogueId = 51007148,
          GUID = "7FB0E838",
          NextDialogue = 51007149,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Explain02_Start"
          }
        },
        [51007149] = {
          ContentJP = "なんだか、もったいない気がする…",
          DialogueId = 51007149,
          GUID = "7FB0E862",
          NextDialogue = 51007150,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700147:Explain02_End",
            [2] = "700148:Think_Start"
          }
        },
        [51007150] = {
          ContentJP = "同情なんていらないよ、星織人。",
          DialogueId = 51007150,
          GUID = "7FB0E88C",
          NextOptions = {
            [1] = 51007151
          },
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700148:Think_End"
          }
        },
        [51007151] = {
          ContentJP = "もう少し親切にしてくれる？",
          DialogueId = 51007151,
          GUID = "7FB0E8B6",
          NextDialogue = 51007152
        },
        [51007152] = {
          ContentJP = "「親切」って？星織人やあの切符売りみたいに、「遠く」とか「未来」とか言って人を期待させろってこと？",
          DialogueId = 51007152,
          GUID = "7FB0E8E0",
          NextDialogue = 51007153,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Explain01_Start"
          }
        },
        [51007153] = {
          ContentJP = "カロンなら、私より、この<Default note=\"text:カショ\">華胥</>人よりもアイスレイク城がどんな場所か分かっているはずだろう！",
          DialogueId = 51007153,
          GUID = "7FB0E90A",
          NextDialogue = 51007154,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700147:Explain01_End"
          }
        },
        [51007154] = {
          ContentJP = "街を一回りしてみなさい、みんな悲しんでいて、文句を言って、呪いの言葉を吐いているんだよ！こんな場所で、ちゃんと話す意味があるの？",
          DialogueId = 51007154,
          GUID = "7FB0E934",
          NextDialogue = 51007155,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007155] = {
          ContentJP = "待つて！",
          DialogueId = 51007155,
          GUID = "7FB0E95E",
          IsBlack = 1,
          LookAt = {
            [1] = "700147:n(700148)"
          },
          NextDialogue = 51007156,
          SpeakNpcId = 700148
        },
        [51007156] = {
          ContentJP = "（異国人が突然何かを思い出し、振り向いてバックパックを探し始める。君とジェシカは訳も分からず、ガチャガチャと音を立てる様子を見守る）",
          DialogueId = 51007156,
          GUID = "7FB0E988",
          NextDialogue = 51007157
        },
        [51007157] = {
          ContentJP = "（しばらくして音が止まり、彼はエキゾチックな小箱をジェシカに差し出す）",
          DialogueId = 51007157,
          GUID = "7FB0E9B2",
          NextDialogue = 51007158,
          TalkActionId = {
            [1] = "700148:Give"
          }
        },
        [51007158] = {
          ContentJP = "この箱は<Default note=\"text:カショ\">華胥</>産のものだ！鍵がかかるから、紙星を失くし心配もないし、誰にも見られるない。",
          DialogueId = 51007158,
          GUID = "7FB0E9DC",
          NextDialogue = 51007159,
          SpeakNpcId = 700148
        },
        [51007159] = {
          ContentJP = "…何のつもり？こんなに精巧な箱を買う金なんて持ってないわ…",
          DialogueId = 51007159,
          GUID = "7FB0EA06",
          NextDialogue = 51007160,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007160] = {
          ContentJP = "無料であげるよ！夢を諦めないで！",
          DialogueId = 51007160,
          GUID = "7FB0EA30",
          NextDialogue = 51007161,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Disagree"
          }
        },
        [51007161] = {
          ContentJP = "（ジェシカは一瞬動揺し、箱に目を落とし、再び顔を上げて黙っている）",
          DialogueId = 51007161,
          GUID = "7FB0EA5A",
          NextOptions = {
            [1] = 51007162,
            [2] = 51007168
          }
        },
        [51007162] = {
          ContentJP = "（ジェシカに箱を受け取るように勧める）",
          DialogueId = 51007162,
          GUID = "7FB0EA84",
          NextDialogue = 51007163
        },
        [51007163] = {
          ContentJP = "…ほらね。優しさは無駄じゃないんだ――少なくともそれは精巧な箱になって、星に込められた夢を守るんだよ。",
          DialogueId = 51007163,
          GUID = "7FB0EAAE",
          LookAt = {
            [1] = "700147:n(0)"
          },
          NextDialogue = 51007164,
          SpeakNpcId = 100001
        },
        [51007164] = {
          ContentJP = "（テーブルの上の紙星を集めて<Default note=\"text:カショ\">華胥</>風の箱に入れ、それをジェシカに手渡す）",
          DialogueId = 51007164,
          GUID = "7FB0EAD8",
          NextDialogue = 51007165
        },
        [51007165] = {
          ContentJP = "時間ができたら、またこの紙星を折り直そう。",
          DialogueId = 51007165,
          GUID = "7FB0EB02",
          NextDialogue = 51007166,
          SpeakNpcId = 100001
        },
        [51007166] = {
          ContentJP = "お前…",
          DialogueId = 51007166,
          GUID = "7FB0EB2C",
          NextDialogue = 51007167,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007167] = {
          ContentJP = "ったく…分かったよ。お前のしつこさには勝てないわ。受け取るよ。ま、ありがとな。",
          DialogueId = 51007167,
          GUID = "7FB0EB56",
          NextDialogue = 51007172,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007168] = {
          ContentJP = "（これでいい、他人の選んだ道に干渉しないでおこう）",
          DialogueId = 51007168,
          GUID = "7FB0EB80",
          NextDialogue = 51007169
        },
        [51007169] = {
          ContentJP = "それを持ってて。なぜ私があの星を捨てたと思う？何年もかけて、私はもう考え尽くして、現実を受け入れたんだよ。",
          DialogueId = 51007169,
          GUID = "7FB0EBAA",
          NextDialogue = 51007170,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007170] = {
          ContentJP = "なんてことだ、残念だ！",
          DialogueId = 51007170,
          GUID = "7FB0EBD4",
          NextDialogue = 51007171,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Disagree"
          }
        },
        [51007171] = {
          ContentJP = "……",
          DialogueId = 51007171,
          GUID = "7FB0EBFE",
          NextDialogue = 51007172,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007172] = {
          ContentJP = "…そうだ、同じ目的地でも列車によって料金は違うんだ。安い便もいくつかある。大した節約にはならないけど…",
          DialogueId = 51007172,
          GUID = "7FB0EC28",
          NextDialogue = 51007173,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007173] = {
          ContentJP = "…いつかお前らが本当にお金を出して切符を買えるようになったら…私は一番安い切符を取っておくよ。",
          DialogueId = 51007173,
          GUID = "7FB0EC52",
          NextDialogue = 51007174,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007174] = {
          ContentJP = "その代わり、紙星のことは内緒にしておいてね。",
          DialogueId = 51007174,
          GUID = "7FB0EC7C",
          NextDialogue = 51007175,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007175] = {
          ContentJP = "どうもだどうもだ。君って意外と優しい切符売りだね！",
          DialogueId = 51007175,
          GUID = "7FB0ECA6",
          NextDialogue = 51007176,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Agree"
          }
        },
        [51007176] = {
          ContentJP = "君の言ってた、十数年前の星織人、もし会えたら、君の言葉を伝えてあげるよ。",
          DialogueId = 51007176,
          GUID = "7FB0ECD0",
          NextDialogue = 51007177,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700148:Talk02_Start"
          }
        },
        [51007177] = {
          ContentJP = "お前の好意には感謝するけど…ま、もし本当にここを離れることができたら、彼を探しに行くことはないと思うわ。雪の降らない場所に行って、外の世界がどんなところか見てみたい。",
          DialogueId = 51007177,
          GUID = "7FB0ECFA",
          NextDialogue = 51007178,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi",
          TalkActionId = {
            [1] = "700148:Talk02_End",
            [2] = "700147:Explain02_Start"
          }
        },
        [51007178] = {
          ContentJP = "それもいいね。努力してお金を貯めるば、きっとここを出られるよ。",
          DialogueId = 51007178,
          GUID = "7FB0ED24",
          NextDialogue = 51007179,
          SpeakNpcId = 700148,
          TalkActionId = {
            [1] = "700147:Explain02_End",
            [2] = "700148:Agree"
          }
        },
        [51007179] = {
          ContentJP = "…うん。",
          DialogueId = 51007179,
          GUID = "7FB0ED4E",
          NextDialogue = 51007186,
          SpeakNpcName = "UI_CMNpc_Name_Jiexi"
        },
        [51007180] = {
          ContentJP = "君にも、自分の星がある。だから、大切にして。絶対に、ゴミ箱に捨てちゃダメだよ。",
          DialogueId = 51007180,
          GUID = "7FB0ED78",
          NextDialogue = 51007181,
          SpeakNpcId = 700148,
          TurnTo = {
            [1] = "700148:n(0)"
          }
        },
        [51007181] = {
          ContentJP = "私はリアンダー、星織人だ。最近、商売が少しうまくいくなくて、今は城門近くで商売すているんだ。ぜひ立ち寄ってくれ！",
          DialogueId = 51007181,
          GUID = "7FB0EDA2",
          SpeakNpcName = "UI_CMNpc_Name_Liande",
          TalkActionId = {
            [1] = "700148:Explain02_Start"
          }
        },
        [51007182] = {
          ContentJP = "お前か…切符を買うなら声をかけてね。",
          DialogueId = 51007182,
          GUID = "7FB0EDCC",
          SpeakNpcId = 700021,
          TalkActionId = {
            [1] = "700021:Agree"
          }
        },
        [51007186] = {
          ContentJP = "そうだ！きれいな紙を持ってるんだ。一緒に星を折ろうよ！",
          DialogueId = 51007186,
          GUID = "7FB0ED4F",
          NextDialogue = 51007187,
          SpeakNpcId = 700148
        },
        [51007187] = {
          ContentJP = "えっ？手伝ってほしいってこと？でも……星なんて折ったことないんだよね。",
          DialogueId = 51007187,
          GUID = "7FB0ED50",
          NextDialogue = 51007188,
          SpeakNpcId = 100001
        },
        [51007188] = {
          ContentJP = "私も上手くない、ぐちゃぐちゃだ。でも、助け合えばきっときれいに折れるよ！",
          DialogueId = 51007188,
          GUID = "7FB0ED51",
          NextDialogue = 51007189,
          SpeakNpcId = 700148
        },
        [51007189] = {
          ContentJP = "……じゃあ、やってみる。",
          DialogueId = 51007189,
          GUID = "7FB0ED52",
          SpeakNpcId = 100001
        },
        [51007190] = {
          ContentJP = "受け取って。優しい龍の民へ。……それと、ちょっとしたお礼もね兼ねてね。",
          DialogueId = 51007190,
          GUID = "7FB0ED53",
          NextDialogue = 51007191,
          SpeakNpcId = 700148
        },
        [51007191] = {
          ContentJP = "……くれるの？",
          DialogueId = 51007191,
          GUID = "7FB0ED54",
          NextDialogue = 51007192,
          SpeakNpcId = 100001
        },
        [51007192] = {
          ContentJP = "うん！この星は、願いだ。星織人にとって星は、旅立ちであり、故郷なんだ。",
          DialogueId = 51007192,
          GUID = "7FB0ED55",
          NextDialogue = 51007180,
          SpeakNpcId = 700148
        },
        [51007301] = {
          ContentJP = "欲望のままに、欲望のままに、欲望のままに……ああ、欲望に忠実とは、一体何をすればいいのでしょうか……",
          DialogueId = 51007301,
          GUID = "7FB10152",
          NextDialogue = 51007302,
          SpeakNpcId = 700077
        },
        [51007302] = {
          ContentJP = "私は所詮、考古学者よ！欲望なんて、学問に関係ないわ！",
          DialogueId = 51007302,
          GUID = "7FB1017C",
          NextOptions = {
            [1] = 510073021,
            [2] = 510073022,
            [3] = 510073023
          },
          SpeakNpcId = 700077,
          bForbidSkipOptions = true
        },
        [51007303] = {
          ContentJP = "その見方、面白いわ。「欲望」とはなんなのか、私にもわかるように手伝ってくれる？",
          DialogueId = 51007303,
          GUID = "7FB101A6",
          NextOptions = {
            [1] = 510073031,
            [2] = 510073032
          },
          SpeakNpcId = 700077
        },
        [51007304] = {
          ContentJP = "私はアトラシア大陸考古協会帝国支部に所属する研究員よ。ここ最近、提出した調査報告がことごとく差し戻されるの。決まり文句はいつも同じ——「欲望が感じられない」ってね。",
          DialogueId = 51007304,
          GUID = "7FB101D0",
          NextDialogue = 51007305,
          SpeakNpcId = 700077
        },
        [51007305] = {
          ContentJP = "はあ…投資家が何を求めてるのか、正直わからないわ。",
          DialogueId = 51007305,
          GUID = "7FB101FA",
          NextDialogue = 51007306,
          SpeakNpcId = 700077
        },
        [51007306] = {
          ContentJP = "学問のある投資家なんて初耳だ{性别:な|ね}？",
          DialogueId = 51007306,
          GUID = "7FB10224",
          NextDialogue = 51007307,
          SpeakNpcId = 100001
        },
        [51007307] = {
          ContentJP = "キョウンさんは、ただの投資者じゃないの。ルッカの「百年前の沈没船」、エリュシオンの「千年前の遺跡」、ヒュペリアの「戦争遺跡」など。考古学に関する様々な歴史的な発見を成し遂げたんだよ。",
          DialogueId = 51007307,
          GUID = "7FB1024E",
          NextDialogue = 51007308,
          SpeakNpcId = 700077
        },
        [51007308] = {
          ContentJP = "（シェリーは崇敬の色を湛えた目で、キョウンの過去を次々と語り出してる。）",
          DialogueId = 51007308,
          GUID = "7FB10278",
          NextDialogue = 51007309
        },
        [51007309] = {
          ContentJP = "キョウンは大陸考古協会の筆頭出資者であり、同時に偉大な考古学者にして蒐集家だ。キョウンこそ、華胥の「影」歩む君主だ——なんて噂さえ絶えないの。",
          DialogueId = 51007309,
          GUID = "7FB102A2",
          NextDialogue = 51007310,
          SpeakNpcId = 700077
        },
        [51007310] = {
          ContentJP = "彼の支援がなければ、考古協会がいまのように大陸全土へ広がる組織には育たなかったでしょう。",
          DialogueId = 51007310,
          GUID = "7FB102CC",
          NextDialogue = 51007311,
          SpeakNpcId = 700077
        },
        [51007311] = {
          ContentJP = "はあ…これまでほとんど口出ししなかったのに、どうして急にこちらに絡んでくるの？華胥の隠居暮らしって、そんなに暇なのかしら。",
          DialogueId = 51007311,
          GUID = "7FB102F6",
          NextDialogue = 51007312,
          SpeakNpcId = 700077
        },
        [51007312] = {
          ContentJP = "その報告、見せてもらえる？",
          DialogueId = 51007312,
          GUID = "7FB10320",
          NextDialogue = 51007313,
          SpeakNpcId = 100001
        },
        [51007313] = {
          ContentJP = "いいわ、『アイスレイク城酒場の客足の変動におけるシンプルデータアナリシス』、「アスフォデロスのドリンクのテクノロジーとレシピの進化」、「ルーナ族の魔王（自称）の観察日記」。どれが見たい？",
          DialogueId = 51007313,
          GUID = "7FB1034A",
          NextOptions = {
            [1] = 510073131,
            [2] = 510073132
          },
          SpeakNpcId = 700077
        },
        [51007314] = {
          ContentJP = "しょうがないよ。アイスレイク城の雪の下からは何も出てこないのよ。これでどうやって、まともな考古学の調査報告を書けっていうの？",
          DialogueId = 51007314,
          GUID = "7FB10374",
          NextOptions = {
            [1] = 510073141
          },
          SpeakNpcId = 700077
        },
        [51007315] = {
          ContentJP = "案内役でも探したら？",
          DialogueId = 51007315,
          FailDialogue = 510073151,
          GUID = "7FB1039E",
          ImprCheckId = 1061,
          NextDialogue = 510073152
        },
        [51007316] = {
          ContentJP = "お願い、私を見捨てないで。(シェリーの個人ストーリー解放)",
          DialogueId = 51007316,
          GUID = "7FB103C8",
          SpeakNpcId = 700077
        },
        [51007317] = {
          ContentJP = "ここの下水道、ほんとうに迷路ね。あなたが案内してくれなかったら、きっと迷ってたわ。",
          DialogueId = 51007317,
          GUID = "7FB103F2",
          NextDialogue = 51007318,
          SpeakNpcId = 700172
        },
        [51007318] = {
          ContentJP = "{性别:僕|私}もたまに迷子になる{性別:んだ|の}。",
          DialogueId = 51007318,
          GUID = "7FB1041C",
          NextDialogue = 51007319,
          SpeakNpcId = 100001
        },
        [51007319] = {
          ContentJP = "あなたみたいな月狩り人でも迷うくらいなら、ここは相当広いのね。",
          DialogueId = 51007319,
          GUID = "7FB10446",
          NextDialogue = 51007320,
          SpeakNpcId = 700172
        },
        [51007320] = {
          ContentJP = "ヒュペリア正史の記すところでは、アイスレイク城はこの国が最初に根を下ろしたところ。だからここの下水道は、地上の街に匹敵するくらい大きいのかもしれない。",
          DialogueId = 51007320,
          GUID = "7FB10447",
          NextDialogue = 51007321,
          SpeakNpcId = 700172
        },
        [51007321] = {
          ContentJP = "このあたりの壁は古いね。",
          DialogueId = 51007321,
          GUID = "7FB10470",
          NextDialogue = 51007322,
          SpeakNpcId = 100001
        },
        [51007322] = {
          ContentJP = "きっとアイスレイク城の拡張に合わせて継ぎ足されてきたのよ。そもそもアイスレイク城自体、カロン族の集落から始まったって聞いたし。",
          DialogueId = 51007322,
          GUID = "7FB1049A",
          NextDialogue = 51007323,
          SpeakNpcId = 700172
        },
        [51007323] = {
          ContentJP = "あ、そうだ。永久凍土のせいで地上の建物はどんどん建て替わるけれど、地下の一部は、昔の姿がそのままに残っているかもしれない。",
          DialogueId = 51007323,
          GUID = "7FB104C4",
          NextDialogue = 510073231,
          SpeakNpcId = 700172
        },
        [51007325] = {
          ContentJP = "ひゃあ……高すぎ！華胥の執律閣より高いのかどうか……いや、だめ、また高所恐怖症がぶり返してきた……",
          DialogueId = 51007325,
          GUID = "7FB10542",
          NextDialogue = 51007326,
          SpeakNpcId = 700173
        },
        [51007326] = {
          ContentJP = "足元に見つめて落ち着いて。外を見ないほうがいい",
          DialogueId = 51007326,
          GUID = "7FB1056C",
          NextDialogue = 51007327,
          SpeakNpcId = 100001
        },
        [51007327] = {
          ContentJP = "ふぅ、ふぅ……よし、だいぶ落ち着いた。",
          DialogueId = 51007327,
          GUID = "7FB10596",
          NextDialogue = 51007328,
          SpeakNpcId = 700173
        },
        [51007328] = {
          ContentJP = "それにしても、当時の帝国の建築家は何を考えてたの？どうしてこんな高さの城壁を……。",
          DialogueId = 51007328,
          GUID = "7FB105C0",
          NextDialogue = 51007329,
          SpeakNpcId = 700173
        },
        [51007329] = {
          ContentJP = "？",
          DialogueId = 51007329,
          GUID = "7FB105EA",
          NextDialogue = 51007330,
          SpeakNpcId = 700173
        },
        [51007330] = {
          ContentJP = "どうして…ええと、正史の記述どおりなら、この城はもともとカロン族の集落から始まったはずよ。",
          DialogueId = 51007330,
          GUID = "7FB10614",
          NextDialogue = 51007331,
          SpeakNpcId = 700173
        },
        [51007331] = {
          ContentJP = "大移住ののち、初代皇帝ディズ一世・ガレアこの地に来て、まずはカロン族と和を結ぼうとした。けれど弟君が饗応の約束に気を許して、カロン族に討たれてしまったの。",
          DialogueId = 51007331,
          GUID = "7FB1063E",
          NextDialogue = 51007333,
          SpeakNpcId = 700173
        },
        [51007333] = {
          ContentJP = "それでディズ一世はカロン族を「悪魔」と見なし、騎士団を率いて鎮圧して、いわゆる『シルバー・ピース』を宣言した――というわけ。",
          DialogueId = 51007333,
          GUID = "7FB10692",
          NextDialogue = 51007334,
          SpeakNpcId = 700173
        },
        [51007334] = {
          ContentJP = "だとしたら、このそびえる城壁は誰に向けられていたの？穢獣？それとも当時のカロン族はまだ抗っていたのかしら。",
          DialogueId = 51007334,
          GUID = "7FB106BC",
          NextDialogue = 51007335,
          SpeakNpcId = 700173
        },
        [51007335] = {
          ContentJP = "ひらめいた？",
          DialogueId = 51007335,
          GUID = "7FB106E6",
          NextDialogue = 51007336,
          SpeakNpcId = 100001
        },
        [51007336] = {
          ContentJP = "\nひらめきってほどじゃないけど、どこか引っかかるの。キョウンがいつも言ってたわ――違和感を見過ごすな、真実はそこに潜むって。",
          DialogueId = 51007336,
          GUID = "7FB10710",
          NextDialogue = 51007339,
          SpeakNpcId = 700173
        },
        [51007339] = {
          ContentJP = "ともあれ、本当にありがとう。これなら面白い報告書が書けそうだわ！",
          DialogueId = 51007339,
          GUID = "7FB1078E",
          NextDialogue = 51007340,
          SpeakNpcId = 700173
        },
        [51007340] = {
          ContentJP = "あなたがいなかったら、ここには考古学的価値なんてないって勝手に決めつけて、肝心なことを見落とした浅い報告を書いてたと思う。",
          DialogueId = 51007340,
          GUID = "7FB107B8",
          NextDialogue = 51007341,
          SpeakNpcId = 700173
        },
        [51007341] = {
          ContentJP = "私ってなんて目が狭かったの……。ねえ、もしかしてあなたは、アイスレイク城に隠居した大物の考古学マスターでしょうか？",
          DialogueId = 51007341,
          GUID = "7FB107E2",
          NextOptions = {
            [1] = 510073411,
            [2] = 510073412,
            [3] = 510073413
          },
          SpeakNpcId = 700173,
          bForbidSkipOptions = true
        },
        [51007342] = {
          ContentJP = "ええと……マスターにふさわしいお礼って何がいいかしら。",
          DialogueId = 51007342,
          GUID = "7FB1080C",
          NextDialogue = 51007343,
          SpeakNpcId = 700173
        },
        [51007343] = {
          ContentJP = "決めました！城門で少々お待ちください。",
          DialogueId = 51007343,
          GUID = "7FB10836",
          SpeakNpcId = 700173
        },
        [51007344] = {
          ContentJP = "わあ……やっぱりマスターの風格があります。間違いありませんわ。",
          DialogueId = 51007344,
          GUID = "7FB1080D",
          NextDialogue = 51007342,
          SpeakNpcId = 700173
        },
        [51007345] = {
          ContentJP = "（ほどなくして、シェリーは大きな袋を二つ抱えて駆け戻ってくる。）",
          DialogueId = 51007345,
          GUID = "7FB1088A",
          NextDialogue = 51007346
        },
        [51007346] = {
          ContentJP = "マスター！ご覧なさい、帝国正史の最新版――「ヒュペリア史」第三十二巻です。考古協会に届いたばかりですよ。ささやかなものですが、どうぞお納めください。",
          DialogueId = 51007346,
          GUID = "7FB108B4",
          NextDialogue = 51007347,
          SpeakNpcId = 700174
        },
        [51007347] = {
          ContentJP = "（丁寧に言いながら、断る隙はない。彼女は本の詰まった袋をぐいっとあなたに押しつけ、礼の言葉を並べながら、軽い足どりでその場を去っていった。）",
          DialogueId = 51007347,
          GUID = "7FB108DE"
        },
        [51007382] = {
          ContentJP = "13号パイプの修理中だ。やれやれ、なかはネズミがうじゃうじゃいるぞ。",
          DialogueId = 51007382,
          GUID = "7FB10E9C",
          NextDialogue = 51007383,
          SpeakNpcId = 700069
        },
        [51007383] = {
          ContentJP = "（ダートンが顔を上げると、その身体からすさまじい悪臭が立ち上る。強い刺激臭に思わず後ずさりしてしまった）",
          DialogueId = 51007383,
          GUID = "7FB10EC6",
          NextDialogue = 51007384
        },
        [51007384] = {
          ContentJP = "おいおい、そんなに避けなくてもいいだろ。下水道で一仕事したら、臭いがつかないわけがない。",
          DialogueId = 51007384,
          GUID = "7FB10EF0",
          SpeakNpcId = 700069,
          TalkOptions = {
            [1] = 510073841,
            [2] = 510073842,
            [3] = 510073843
          }
        },
        [51007388] = {
          ContentJP = "こう見えても。数年前まで、うやうやしく「ダートン先生」って呼ばれてたんだぜ。",
          DialogueId = 51007388,
          GUID = "7FB10F98",
          NextDialogue = 51007389,
          SpeakNpcId = 700069
        },
        [51007389] = {
          ContentJP = "あんただってわかるだろ。スラム街出身のカロンにとって、そんな風に呼ばれるのがどれほど意味があることか。",
          DialogueId = 51007389,
          GUID = "7FB10FC2",
          NextDialogue = 51007390,
          SpeakNpcId = 700069
        },
        [51007390] = {
          ContentJP = "俺は中央病院に務めてたんだ。カロン族の患者は数え切れないほど診てきたし、貴族に往診を頼まれたことだってある。",
          DialogueId = 51007390,
          GUID = "7FB10FEC",
          NextDialogue = 51007391,
          SpeakNpcId = 700069
        },
        [51007391] = {
          ContentJP = "信じられないなら、カロン族の若者に訊いてみるといい。子供の頃、親から「あの人を見習いなさい」ってお手本にされていたのは誰だったか。",
          DialogueId = 51007391,
          GUID = "7FB11016",
          NextDialogue = 51007392,
          SpeakNpcId = 700069
        },
        [51007392] = {
          ContentJP = "あの頃の俺はかなりの潔癖症でな。床のタイルの隙間に少しでもホコリがあると我慢できなかったんだが……",
          DialogueId = 51007392,
          GUID = "7FB11040",
          RestartTag = 51007392,
          SpeakNpcId = 700069,
          TalkOptions = {
            [1] = 51007393
          }
        },
        [51007393] = {
          ContentJP = "命を救う仕事をしていたのに、今は下水道の修理をしているなんて……",
          DialogueId = 51007393,
          GUID = "7FB1106A",
          ImprCheckId = 1062,
          NextDialogue = 510073931
        },
        [51007395] = {
          ContentJP = "昔は人を修理して、今はパイプを修理しているんだから、大して変わらんさ。",
          DialogueId = 51007395,
          GUID = "7FB110BE",
          NextDialogue = 51007396,
          SpeakNpcId = 700069
        },
        [51007396] = {
          ContentJP = "（ダートンは軽く笑った。なんだか重苦しい思い出のページを開こうとしているようだ）",
          DialogueId = 51007396,
          GUID = "7FB110E8",
          NextDialogue = 51007398
        },
        [51007398] = {
          ContentJP = "医者の目の前で、通行人が急病で倒れた。その医者は職業倫理にのっとり、救命措置を施した。",
          DialogueId = 51007398,
          GUID = "7FB1113C",
          NextDialogue = 51007399,
          SpeakNpcId = 700069
        },
        [51007399] = {
          ContentJP = "それでどうなったのか知りたいか？まずはそこのスパナを取ってくれ――",
          DialogueId = 51007399,
          GUID = "7FB11166",
          SpeakNpcId = 700069
        },
        [51007401] = {
          Content = "行，跟我来吧，路上那些乱七八糟的东西就交给你了。",
          DialogueId = 51007401,
          GUID = "7FB111BA",
          SpeakNpcId = 700069
        },
        [51007404] = {
          Content = "帮我拿下扳手——",
          DialogueId = 51007404,
          GUID = "7FB11238",
          SpeakNpcId = 700193
        },
        [51007405] = {
          Content = "总之，他的抢救不但没能请来奇迹，来的还是巨额赔偿金，医院为了名誉只好辞退了一个员工。",
          DialogueId = 51007405,
          GUID = "7FB11262",
          NextDialogue = 51007406,
          SpeakNpcId = 700194
        },
        [51007406] = {
          Content = "谁能想到呢，他竟然除了治病救人什么都不会，所以欢迎他的只有下水管道。",
          DialogueId = 51007406,
          GUID = "7FB1128C",
          NextDialogue = 51007407,
          SpeakNpcId = 700194
        },
        [51007407] = {
          Content = "好在当年怎么都没治好的洁癖，来这儿几个月就治好了。",
          DialogueId = 51007407,
          GUID = "7FB112B6",
          NextDialogue = 51007408,
          SpeakNpcId = 700194
        },
        [51007408] = {
          Content = "再者说，干这活儿也不至于被饿死在街上，不过就是得还债还到进棺材喽。",
          DialogueId = 51007408,
          GUID = "7FB112E0",
          NextDialogue = 51007409,
          SpeakNpcId = 700194
        },
        [51007409] = {
          Content = "如果再给你的人生重来一次的机会，你还会救他吗？",
          DialogueId = 51007409,
          GUID = "7FB1130A",
          NextDialogue = 51007410,
          SpeakNpcId = 700194
        },
        [51007410] = {
          Content = "（达顿转过身用扳手拧紧新换的螺丝，他甩着胳膊干得卖力又熟练，好像没听见你的问题。）",
          DialogueId = 51007410,
          GUID = "7FB11334",
          NextDialogue = 51007411
        },
        [51007411] = {
          Content = "（只是在如轰鸣般的沉默中，你和他都已经对答案心知肚明了。）",
          DialogueId = 51007411,
          GUID = "7FB1135E"
        },
        [51007415] = {
          Content = "哎呦……！里边这儿的老鼠也太多了！",
          DialogueId = 51007415,
          GUID = "7FB11406",
          SpeakNpcId = 700192
        },
        [51007501] = {
          ContentJP = "よし……栄えある実験体第1号は君に決まりだ！",
          DialogueId = 51007501,
          GUID = "7FB12222",
          NextDialogue = 51007502,
          SpeakNpcId = 700011
        },
        [51007502] = {
          ContentJP = "目の前の少年が、期待に満ちた目でこちらを見上げている。",
          DialogueId = 51007502,
          GUID = "7FB1224C",
          NextOptions = {
            [1] = 51007503,
            [2] = 51007506,
            [3] = 51007509
          }
        },
        [51007503] = {
          ContentJP = "きちんとした制服を着ている。まだ学生みたいだ。",
          DialogueId = 51007503,
          GUID = "7FB12276",
          ImprPlusId = 1003,
          NextDialogue = 51007504
        },
        [51007504] = {
          ContentJP = "実験って……学校の課題か何か？",
          DialogueId = 51007504,
          GUID = "7FB122A0",
          NextDialogue = 51007505,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007505] = {
          ContentJP = "ちがうよ！これは僕の趣味！",
          DialogueId = 51007505,
          GUID = "7FB122CA",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Disagree"
          }
        },
        [51007506] = {
          ContentJP = "一人にしておくのは心配だ。",
          DialogueId = 51007506,
          GUID = "7FB122F4",
          ImprPlusId = 1004,
          NextDialogue = 51007507
        },
        [51007507] = {
          ContentJP = "こんなところに一人じゃ危ないよ。家まで送ろうか？",
          DialogueId = 51007507,
          GUID = "7FB1231E",
          NextDialogue = 51007508,
          SpeakNpcId = 700192,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007508] = {
          ContentJP = "ありがとう！でも、先に実験だけやらせて！",
          DialogueId = 51007508,
          GUID = "7FB12348",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007509] = {
          ContentJP = "実験の報酬について聞く。",
          DialogueId = 51007509,
          GUID = "7FB12372",
          ImprPlusId = 1001,
          NextDialogue = 51007510
        },
        [51007510] = {
          ContentJP = "えっ？あ、うん、もちろん！僕のお小遣い全部あげるよ！",
          DialogueId = 51007510,
          GUID = "7FB1239C",
          NextDialogue = 51007512,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007512] = {
          ContentJP = "実は今、カロン向けの実験調査をやってるんだ。あなたが最初の協力者ってわけ！",
          DialogueId = 51007512,
          GUID = "7FB123F0",
          NextDialogue = 51007513,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_Start"
          }
        },
        [51007513] = {
          ContentJP = "{性别:どうして僕？|どうして私？}",
          DialogueId = 51007513,
          GUID = "7FB1241A",
          NextDialogue = 51007514,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Think_Start"
          }
        },
        [51007514] = {
          ContentJP = "偶然だよ！無作為に選ばないと、偏りが出ちゃうからね！",
          DialogueId = 51007514,
          GUID = "7FB12444",
          NextDialogue = 51007515,
          SpeakNpcId = 700011
        },
        [51007515] = {
          ContentJP = "えっと、まずあなたの名前を教えて。",
          DialogueId = 51007515,
          GUID = "7FB1246E",
          NextOptions = {
            [1] = 51007516,
            [2] = 51007519
          },
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Explain01_End"
          }
        },
        [51007516] = {
          ContentJP = "{性别:僕|私}は、パーガトリー島生まれ、再生の炎にして、アイスレイク城の守護者、栄光なる——{nickname}{性别:だよ|よ}。",
          DialogueId = 51007516,
          GUID = "7FB12498",
          ImprPlusId = 1005,
          NextDialogue = 51007517,
          Scripts = "SetTag{Tag{\"XiAoTag\"}, Value{\"Value_1\"}}"
        },
        [51007517] = {
          ContentJP = "え、ええっと……え？パーガトリー島生まれで、再生の炎、アイスレイクの……シュシュ……",
          DialogueId = 51007517,
          GUID = "7FB124C2",
          NextDialogue = 51007518,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Talk01_Start"
          }
        },
        [51007518] = {
          ContentJP = "うう、長い！じゃあ、{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}って呼ぶね！",
          DialogueId = 51007518,
          GUID = "7FB124EC",
          NextDialogue = 51007522,
          SpeakNpcId = 700011,
          TalkActionId = {
            [1] = "700011:Agree"
          }
        },
        [51007519] = {
          ContentJP = "シビルだよ。",
          DialogueId = 51007519,
