          GUID = "7FB134D6",
          NextDialogue = 51007618,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007616] = {
          ContentJP = "武器を見せつけて脅かす。",
          DialogueId = 51007616,
          GUID = "7FB13500",
          NextDialogue = 51007617
        },
        [51007617] = {
          ContentJP = "ん？あなたはとても強いって意味？",
          DialogueId = 51007617,
          GUID = "7FB1352A",
          NextDialogue = 51007618,
          SpeakNpcId = 700204
        },
        [51007618] = {
          ContentJP = "うーん……あなたが仕事してるところ、見てみたいな……あ、そうだ！",
          DialogueId = 51007618,
          GUID = "7FB13554",
          NextDialogue = 51007619,
          SpeakNpcId = 700204
        },
        [51007619] = {
          ContentJP = "僕、ちょうど下水道の生態環境を調査しようと思ってたんだ。一緒に来てくれない？",
          DialogueId = 51007619,
          GUID = "7FB1357E",
          NextDialogue = 51007620,
          SpeakNpcId = 700204
        },
        [51007620] = {
          ContentJP = "これは依頼だよ。ちゃんと報酬も払うから！",
          DialogueId = 51007620,
          GUID = "7FB135A8",
          NextDialogue = 51007623,
          SpeakNpcId = 700204
        },
        [51007623] = {
          ContentJP = "やった！じゃあ、行こう！",
          DialogueId = 51007623,
          GUID = "7FB13626",
          NextDialogue = 51007624,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007624] = {
          ContentJP = "知ってる？みんなはネズミを毛嫌いするけど、僕が観察した結果によれば、ネズミってすごく面白いんだよ！",
          DialogueId = 51007624,
          GUID = "7FB13650",
          NextDialogue = 51007625,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007625] = {
          ContentJP = "このあたりでも、一度だけすごく立派なネズミを見たことがあるんだ。まるで「ネズミ戦士」のお話みたいなやつ！",
          DialogueId = 51007625,
          GUID = "7FB1367A",
          NextDialogue = 51007626,
          SpeakNpcId = 700204
        },
        [51007626] = {
          ContentJP = "「ネズミ戦士」っていうのは、もともとはすごく小さくて弱いネズミだったんだけど、困難に立ち向かって戦い抜いて、ついには仲間たちを守る英雄になったっていう伝説さ。",
          DialogueId = 51007626,
          GUID = "7FB136A4",
          NextDialogue = 51007627,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Angry01_Start"
          }
        },
        [51007627] = {
          ContentJP = "僕が見たあのネズミも、傷だらけだったんだ。きっと勇敢に戦った証拠だよ。しかも、背中に小さな奇妙なボトルを背負ってたんだ。もしかして、特別な道具だったのかも？",
          DialogueId = 51007627,
          GUID = "7FB136CE",
          NextOptions = {
            [1] = 51007628,
            [2] = 51007631,
            [3] = 51007636
          },
          SpeakNpcId = 700204
        },
        [51007628] = {
          ContentJP = "それ、実験道具だったんじゃない？",
          DialogueId = 51007628,
          GUID = "7FB136F8",
          ImprPlusId = 1003,
          NextDialogue = 51007629
        },
        [51007629] = {
          ContentJP = "たしかに……誰かがネズミを使った実験だったのかも……そう考えるとちょっと怖いね。",
          DialogueId = 51007629,
          GUID = "7FB13722",
          NextDialogue = 51007630,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007630] = {
          ContentJP = "でも、運命を受け入れて勇敢に生きたんだ。それが英雄ってものだよね！……可哀想だけど。",
          DialogueId = 51007630,
          GUID = "7FB1374C",
          NextDialogue = 51007638,
          SpeakNpcId = 700204
        },
        [51007631] = {
          ContentJP = "まるで物語が現実になったみたいで、面白いね。",
          DialogueId = 51007631,
          GUID = "7FB13776",
          ImprPlusId = 1004,
          NextDialogue = 51007632
        },
        [51007632] = {
          ContentJP = "へへ、僕もそう思う！",
          DialogueId = 51007632,
          GUID = "7FB137A0",
          NextDialogue = 51007633,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007633] = {
          ContentJP = "残念だなぁ……あなたはもう見れないんだから。",
          DialogueId = 51007633,
          GUID = "7FB137CA",
          NextOptions = {
            [1] = 51007634,
            [2] = 51007635
          },
          SpeakNpcId = 700204
        },
        [51007634] = {
          ContentJP = "どうして？",
          DialogueId = 51007634,
          GUID = "7FB137F4",
          NextDialogue = 51007638
        },
        [51007635] = {
          ContentJP = "その言い方、僕を口封じするつもり？/その言い方、私を口封じするつもり？",
          DialogueId = 51007635,
          GUID = "7FB1381E",
          NextDialogue = 51007638
        },
        [51007636] = {
          ContentJP = "まさか、食べちゃったの？",
          DialogueId = 51007636,
          GUID = "7FB13848",
          ImprPlusId = 1005,
          NextDialogue = 51007637
        },
        [51007637] = {
          ContentJP = "いや、違うよ！あのネズミはすごくいい子だったんだ！でも……もういないんだ……",
          DialogueId = 51007637,
          GUID = "7FB13872",
          NextDialogue = 51007638,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007638] = {
          ContentJP = "数日前、僕、あのネズミ戦士が、物乞いのおじさんに捕まって……焼き串にされるところを見ちゃったんだ……ううっ。",
          DialogueId = 51007638,
          GUID = "7FB1389C",
          NextDialogue = 51007639,
          SpeakNpcId = 700204
        },
        [51007639] = {
          ContentJP = "……つらいけど、研究って予期せぬ出来事もつきものだよね。だから今は、あの子が世話してた小さなネズミたちがどうしてるか、見てみたいんだ。",
          DialogueId = 51007639,
          GUID = "7FB138C6",
          NextDialogue = 51007640,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007640] = {
          ContentJP = "さあ、ネズミたちの声を頼りに、巣の場所を探しに行こう！",
          DialogueId = 51007640,
          GUID = "7FB138F0",
          NextOptions = {
            [1] = 51007641,
            [2] = 51007643
          },
          SpeakNpcId = 700204
        },
        [51007641] = {
          ContentJP = "うん。しっかり着いてきて。ちゃんと守るから。",
          DialogueId = 51007641,
          GUID = "7FB1391A",
          NextDialogue = 51007642
        },
        [51007642] = {
          ContentJP = "ありがとう！あなた、頼りになるね！",
          DialogueId = 51007642,
          GUID = "7FB13944",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007643] = {
          ContentJP = "怖いから、君が前歩いて。",
          DialogueId = 51007643,
          GUID = "7FB1396E",
          NextDialogue = 51007644
        },
        [51007644] = {
          ContentJP = "ええー、さっきまであんな強がってたのに？",
          DialogueId = 51007644,
          GUID = "7FB13998",
          NextDialogue = 51007645,
          SpeakNpcId = 700204
        },
        [51007645] = {
          ContentJP = "……しょうがないなぁ、じゃあ僕が先に行くよ。",
          DialogueId = 51007645,
          GUID = "7FB139C2",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Sigh_Start"
          }
        },
        [51007646] = {
          ContentJP = "下水道って、思ったより広いんだね……",
          DialogueId = 51007646,
          GUID = "7FB139EC",
          NextDialogue = 51007647,
          SpeakNpcId = 700204
        },
        [51007647] = {
          ContentJP = "灰色の影が角をすり抜ける。どうやら小さなネズミらしい。",
          DialogueId = 51007647,
          GUID = "7FB13A16",
          NextDialogue = 51007648
        },
        [51007648] = {
          ContentJP = "あっ、見た？あれ、尾っぽが途中で切れてる！あれは前に見た、ネズミ戦士の仲間だよ！",
          DialogueId = 51007648,
          GUID = "7FB13A40",
          NextDialogue = 51007649,
          SpeakNpcId = 700204
        },
        [51007649] = {
          ContentJP = "あれっ！逃げた！？",
          DialogueId = 51007649,
          GUID = "7FB13A6A",
          NextDialogue = 51007650,
          SpeakNpcId = 700204
        },
        [51007650] = {
          ContentJP = "僕のこと忘れちゃったのかな……",
          DialogueId = 51007650,
          GUID = "7FB13A94",
          NextDialogue = 51007651,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007651] = {
          ContentJP = "少年は小さな眉をひそめ、考え込んだ。",
          DialogueId = 51007651,
          GUID = "7FB13ABE",
          NextDialogue = 51007652
        },
        [51007652] = {
          ContentJP = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}、動物に心ってあると思う？知りたいんだけど、言葉が通じないからなぁ……",
          DialogueId = 51007652,
          GUID = "7FB13AE8",
          NextOptions = {
            [1] = 51007653,
            [2] = 51007656
          },
          SpeakNpcId = 700204
        },
        [51007653] = {
          ContentJP = "信じればあるんじゃないかな。",
          DialogueId = 51007653,
          GUID = "7FB13B12",
          ImprPlusId = 1004,
          NextDialogue = 51007654
        },
        [51007654] = {
          ContentJP = "うーん、主観的な考え方じゃダメなんだよ。研究にはちゃんとした根拠が必要なんだ！",
          DialogueId = 51007654,
          GUID = "7FB13B3C",
          NextDialogue = 51007655,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007655] = {
          ContentJP = "そうだ、行動観察から証明できるかもしれない！",
          DialogueId = 51007655,
          GUID = "7FB13B66",
          NextDialogue = 51007658,
          SpeakNpcId = 700204
        },
        [51007656] = {
          ContentJP = "心は言葉だけじゃなく、行動でもわかるんじゃないかな。彼らの行動を観察してみたら？",
          DialogueId = 51007656,
          GUID = "7FB13B90",
          ImprPlusId = 1003,
          NextDialogue = 51007657
        },
        [51007657] = {
          ContentJP = "確かに！",
          DialogueId = 51007657,
          GUID = "7FB13BBA",
          NextDialogue = 51007658,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007658] = {
          ContentJP = "もしあの小ネズミたちがネズミ戦士を尊敬しているなら、きっと勇敢で、優しくて、仲間思いの行動をするはずだよね！",
          DialogueId = 51007658,
          GUID = "7FB13BE4",
          NextDialogue = 51007659,
          SpeakNpcId = 700204
        },
        [51007659] = {
          ContentJP = "よし、実際に確かめに行こう！さっきの子ネズミ、あっちへ走っていったよ。急ごう！",
          DialogueId = 51007659,
          GUID = "7FB13C0E",
          SpeakNpcId = 700204
        },
        [51007660] = {
          ContentJP = "見て！ネズミの巣だ！",
          DialogueId = 51007660,
          GUID = "7FB13C38",
          NextDialogue = 51007661,
          SpeakNpcId = 700204
        },
        [51007661] = {
          ContentJP = "ネズミの巣から「チューチュー」と鋭い鳴き声が聞こえた。わずかに漂う悪臭にも、テオは怯むことなく、目を大きく開いてネズミたちの動きを真剣に観察している。",
          DialogueId = 51007661,
          GUID = "7FB13C62",
          NextDialogue = 51007662
        },
        [51007662] = {
          ContentJP = "子ネズミたちは半分に割れたビスケットを奪い合って、必死に揉み合っていた。",
          DialogueId = 51007662,
          GUID = "7FB13C8C",
          NextDialogue = 51007663
        },
        [51007663] = {
          ContentJP = "うう……彼ら、仲間思いじゃないかも……",
          DialogueId = 51007663,
          GUID = "7FB13CB6",
          NextDialogue = 51007664,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007664] = {
          ContentJP = "人影に気づき、一部の子ネズミが驚いて慌てて逃げ出した。",
          DialogueId = 51007664,
          GUID = "7FB13CE0",
          NextDialogue = 51007665
        },
        [51007665] = {
          ContentJP = "うう……勇敢でもないみたいだね。",
          DialogueId = 51007665,
          GUID = "7FB13D0A",
          NextDialogue = 51007666,
          SpeakNpcId = 700204
        },
        [51007666] = {
          ContentJP = "残った数匹のネズミが突然目を光らせ、こちらに飛びかかってきた！",
          DialogueId = 51007666,
          GUID = "7FB13D34",
          NextDialogue = 51007667
        },
        [51007667] = {
          ContentJP = "うわああ！何もしてないのにいきなり襲ってくるなんて、失礼すぎるよ！",
          DialogueId = 51007667,
          GUID = "7FB13D5E",
          NextDialogue = 51007668,
          SpeakNpcId = 700204
        },
        [51007668] = {
          ContentJP = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}、逃げよう！",
          DialogueId = 51007668,
          GUID = "7FB13D88",
          NextDialogue = 51007669,
          SpeakNpcId = 700204
        },
        [51007669] = {
          ContentJP = "ここは任せて、君は先に逃げて。",
          DialogueId = 51007669,
          GUID = "7FB13DB2",
          SpeakNpcId = 100001
        },
        [51007670] = {
          ContentJP = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}、戻ってきたんだね！あなたの戦う姿、遠くから見てたよ！すっごくかっこよかった！",
          DialogueId = 51007670,
          GUID = "7FB13DDC",
          NextDialogue = 51007671,
          SpeakNpcId = 700204
        },
        [51007671] = {
          ContentJP = "「{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}はすごい戦闘能力を持ってる」……っと。ちゃんとメモしといたよ。",
          DialogueId = 51007671,
          GUID = "7FB13E06",
          NextDialogue = 51007672,
          SpeakNpcId = 700204
        },
        [51007672] = {
          ContentJP = "でも……やっぱり、あの子ネズミたちには情がなかったみたいだね……",
          DialogueId = 51007672,
          GUID = "7FB13E30",
          NextOptions = {
            [1] = 51007673,
            [2] = 51007675
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007673] = {
          ContentJP = "まだ成長途中なのかもしれない。",
          DialogueId = 51007673,
          GUID = "7FB13E5A",
          NextDialogue = 51007674
        },
        [51007674] = {
          ContentJP = "うん……確かに！成長すれば、きっとネズミ戦士みたいな立派なネズミになるよね！",
          DialogueId = 51007674,
          GUID = "7FB13E84",
          NextDialogue = 51007677,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007675] = {
          ContentJP = "きっと教えてくれる先輩がいなくなったからだよ。",
          DialogueId = 51007675,
          GUID = "7FB13EAE",
          NextDialogue = 51007676
        },
        [51007676] = {
          ContentJP = "そうだよね……悲しいけど、先輩がいなくなっても、強く生き抜いてほしいな。",
          DialogueId = 51007676,
          GUID = "7FB13ED8",
          NextDialogue = 51007677,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007677] = {
          ContentJP = "よし、今日の調査はこれで終わりにしよう。",
          DialogueId = 51007677,
          GUID = "7FB13F02",
          NextDialogue = 51007678,
          SpeakNpcId = 700204
        },
        [51007678] = {
          ContentJP = "付き合ってくれてありがとう{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}！あなたはすごく賢くて頼れる人だね！世間で言われてる月狩り人の噂なんて、まっぴらな嘘だね！",
          DialogueId = 51007678,
          GUID = "7FB13F2C",
          NextDialogue = 51007679,
          SpeakNpcId = 700204
        },
        [51007679] = {
          ContentJP = "ああ、もしも全てのカロンがあなたみたいに優しかったらなあ……そういえば、前に街の北側の宿屋で、緑の服を着たお姉さんを見かけたんだ。声をかけたのに、全然反応してくれなかったんだよね。",
          DialogueId = 51007679,
          GUID = "7FB13F56",
          NextDialogue = 51007680,
          SpeakNpcId = 700204
        },
        [51007680] = {
          ContentJP = "たぶん気づかなかっただけだよ。",
          DialogueId = 51007680,
          GUID = "7FB13F80",
          NextDialogue = 51007681,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007681] = {
          ContentJP = "え？もしかして知り合い？",
          DialogueId = 51007681,
          GUID = "7FB13FAA",
          NextDialogue = 51007682,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007682] = {
          ContentJP = "うん。",
          DialogueId = 51007682,
          GUID = "7FB13FD4",
          NextDialogue = 51007683,
          SpeakNpcId = 100001
        },
        [51007683] = {
          ContentJP = "すごいなあ、あなた、どうしてそんなにたくさんの人と知り合いなんだろう……その秘訣、教えてくれない？",
          DialogueId = 51007683,
          GUID = "7FB13FFE",
          NextOptions = {
            [1] = 51007684,
            [2] = 51007686
          },
          SpeakNpcId = 700204
        },
        [51007684] = {
          ContentJP = "いろんな人と会話して、経験を積むこと。",
          DialogueId = 51007684,
          GUID = "7FB14028",
          NextDialogue = 51007685
        },
        [51007685] = {
          ContentJP = "テオはノートに「{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}のコミュニケーションのコツ：いろんな人と話して経験を積む」と書き込んだ。",
          DialogueId = 51007685,
          GUID = "7FB14052",
          NextDialogue = 51007688
        },
        [51007686] = {
          ContentJP = "とりあえず武力で威圧する。",
          DialogueId = 51007686,
          GUID = "7FB1407C",
          NextDialogue = 51007687
        },
        [51007687] = {
          ContentJP = "テオはノートに「{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}のコミュニケーションのコツ：まずは武力で威圧。※この方法は僕には向かないかも」とメモした。",
          DialogueId = 51007687,
          GUID = "7FB140A6",
          NextDialogue = 51007688
        },
        [51007688] = {
          ContentJP = "うんうん、覚えたよ！",
          DialogueId = 51007688,
          GUID = "7FB140D0",
          NextDialogue = 51007689,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007689] = {
          ContentJP = "そこへ急ぎ足で誰かが駆け寄ってくる音が聞こえた。きちんとした服装の女性が、怒りに満ちた表情でこちらに向かってくる。",
          DialogueId = 51007689,
          GUID = "7FB140FA",
          IsBlack = 1
        },
        [51007690] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "テオ、またどこに行ってたの！ああもう、なんてみっともない格好……服まで泥だらけじゃない！",
          DefaultLookAt = "1.0",
          DialogueId = 51007690,
          GUID = "7FB14124",
