          }
        },
        [51007691] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "ママ……僕、さっき下水道でネズミの観察をしてたんだよ！",
          DefaultLookAt = "1.0",
          DialogueId = 51007691,
          GUID = "7FB1414E",
          NextDialogue = 51007692,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007692] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "なんですって！？そんな不潔な生き物を観察だなんて、信じられない！",
          DefaultLookAt = "1.0",
          DialogueId = 51007692,
          GUID = "7FB14178",
          NextDialogue = 51007693,
          SpeakNpcId = 700205
        },
        [51007693] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "研究だかなんだか知らないけど、そんなことしてる暇があったらちゃんと勉強しなさい！",
          DefaultLookAt = "1.0",
          DialogueId = 51007693,
          GUID = "7FB141A2",
          NextDialogue = 51007694,
          SpeakNpcId = 700205,
          TalkActionId = {
            [1] = "700205:Sigh_Start"
          }
        },
        [51007694] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "女性はまくしたてたあと、ようやくあなたに気づき、警戒するようにテオを自分の後ろに隠した。",
          DefaultLookAt = "1.0",
          DialogueId = 51007694,
          GUID = "7FB141CC",
          NextDialogue = 51007695,
          TurnTo = {
            [1] = "700204:n(100001)",
            [2] = "700205:n(100001)"
          }
        },
        [51007695] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "あなたね、この子をそそのかしたのは？",
          DefaultLookAt = "1.0",
          DialogueId = 51007695,
          GUID = "7FB141F6",
          NextOptions = {
            [1] = 51007696,
            [2] = 51007698
          },
          SpeakNpcId = 700205
        },
        [51007696] = {
          ContentJP = "証拠もないのに決めつけないでください。",
          DialogueId = 51007696,
          GUID = "7FB14220",
          ImprPlusId = 1002,
          NextDialogue = 51007697
        },
        [51007697] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "ふん、カロンの分際でよく言うわ！",
          DefaultLookAt = "1.0",
          DialogueId = 51007697,
          GUID = "7FB1424A",
          NextDialogue = 51007700,
          SpeakNpcId = 700205
        },
        [51007698] = {
          ContentJP = "そのとおりです。お見事！",
          DialogueId = 51007698,
          GUID = "7FB14274",
          ImprPlusId = 1005,
          NextDialogue = 51007699
        },
        [51007699] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "なっ……！",
          DefaultLookAt = "1.0",
          DialogueId = 51007699,
          GUID = "7FB1429E",
          NextDialogue = 51007700,
          SpeakNpcId = 700205
        },
        [51007700] = {
          Camera = "524.909058,-5.945312,503.180176,0.00013,-34.597534,178.391556,22.109655,100000.0,false,Manual,22.0",
          ContentJP = "テオ、何度言ったらわかるの！カロンと関わっちゃダメだって言ったでしょ！こいつらなんてろくなもんじゃないわ！",
          DefaultLookAt = "1.0",
          DialogueId = 51007700,
          GUID = "7FB142C8",
          NextDialogue = 51007701,
          SpeakNpcId = 700205,
          TurnTo = {
            [1] = "700204:n(700205)",
            [2] = "100001:n(700205)",
            [3] = "700205:n(700204)"
          }
        },
        [51007701] = {
          ContentJP = "女性は無理やりテオの手を引き、去っていった。テオはこっそり「またね！」と言うと、小さな包みをあなたにそっと投げた。",
          DialogueId = 51007701,
          GUID = "7FB142F2",
          IsBlack = 1
        },
        [51007702] = {
          ContentJP = "{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}！{$XiAoTag(Value_1,Value_2)$|シュシュ:シビル}{性别:お兄さん|お姉さん}！ここだよここ！",
          DialogueId = 51007702,
          GUID = "7FB1431C",
          NextDialogue = 51007703,
          SpeakNpcId = 700204
        },
        [51007703] = {
          ContentJP = "（少年が建物の陰から手を振ってくる）",
          DialogueId = 51007703,
          GUID = "7FB14346",
          NextDialogue = 51007704
        },
        [51007704] = {
          ContentJP = "また会ったね！",
          DialogueId = 51007704,
          GUID = "7FB14370",
          NextDialogue = 51007705,
          SpeakNpcId = 700204
        },
        [51007705] = {
          ContentJP = "聞いたんだけど、本当は{nickname}っていうんだよね？もー、子どもを騙しちゃダメでしょ！",
          DialogueId = 51007705,
          GUID = "7FB1439A",
          NextDialogue = 51007706,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Talk03_Start"
          }
        },
        [51007706] = {
          ContentJP = "この前はごめんね。母さん、カロン族のこと、すごく怖がってるんだ。",
          DialogueId = 51007706,
          GUID = "7FB143C4",
          NextDialogue = 51007707,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007707] = {
          ContentJP = "帰ってからずっと、「カロン族は怠け者で、生まれつき犯罪者で、すごく危険な連中だ」なんて言っててさ。",
          DialogueId = 51007707,
          GUID = "7FB143EE",
          NextDialogue = 51007708,
          SpeakNpcId = 700204
        },
        [51007708] = {
          ContentJP = "他の大人たちも、似たようなこと言ってたよ。でも、なんだか変だなって思ってきたんだ。",
          DialogueId = 51007708,
          GUID = "7FB14418",
          NextDialogue = 51007709,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007709] = {
          ContentJP = "カロンのこと、もっとちゃんと知りたいんだ。でも、僕が話しかけても怖がられたり無視されたりするし……だから、あなたが教えてくれたら嬉しいな！",
          DialogueId = 51007709,
          GUID = "7FB14442",
          NextDialogue = 51007710,
          SpeakNpcId = 700204
        },
        [51007710] = {
          ContentJP = "話すより、実際に見た方が早いよ。ちょうどカメラも持ってるし、写真を撮って帰ってからゆっくり考えてみるといい。",
          DialogueId = 51007710,
          GUID = "7FB1446C",
          NextDialogue = 51007711,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007711] = {
          ContentJP = "ほんとに？ありがとう！",
          DialogueId = 51007711,
          GUID = "7FB14496",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007712] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          ContentJP = "あの屋台、毎朝まだ暗いうちから準備を始めるんだ。こうして、カロンたちは毎日必死に働いて生計を立ててるんだよ。仲良くなれば、ちょっとした値引きとかしてくれるかもね。",
          DialogueId = 51007712,
          GUID = "7FB144C0",
          NextDialogue = 51007713,
          SpeakNpcId = 100001
        },
        [51007713] = {
          Camera = "-329.898193,-397.409424,278.790771,0.000011,-19.79974,48.99963,22.97237,100000.0,false,Manual,22.0",
          ContentJP = "……すごく、大変そうだね。",
          DialogueId = 51007713,
          GUID = "7FB144EA",
          SpeakNpcId = 700204
        },
        [51007714] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "ここが、カロンのほとんどが暮らしてる場所だよ。",
          DialogueId = 51007714,
          GUID = "7FB14514",
          NextDialogue = 51007715,
          SpeakNpcId = 100001
        },
        [51007715] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "うーん……建物、だいぶボロボロだね。あっ、あの怖そうなおじさん、隣の家の屋根を直してあげてる！あそこで子どもたちが遊んでる……僕たちも城の中で、よくああやって遊んだなあ。",
          DialogueId = 51007715,
          GUID = "7FB1453E",
          NextDialogue = 51007716,
          SpeakNpcId = 700204
        },
        [51007716] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "……あなたの言いたいこと、ちょっとわかったかも。お母さんが言ってたこと、全部が全部ほんとうじゃないんだね。確かにちょっと怖い人もいるし、変わった人もいるけど……人間だって、そういう人はいるもんね。",
          DialogueId = 51007716,
          GUID = "7FB14568",
          NextDialogue = 51007717,
          SpeakNpcId = 700204
        },
        [51007717] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "角が生えてる以外、カロン族って僕たちと変わらないんじゃないかな？",
          DialogueId = 51007717,
          GUID = "7FB14592",
          NextDialogue = 51007718,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007718] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "こんなにわかりやすいことなのに、なんで大人たちは間違ったことばっかり信じてるんだろう……？",
          DialogueId = 51007718,
          GUID = "7FB145BC",
          NextOptions = {
            [1] = 51007719,
            [2] = 51007720
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Think_Start"
          }
        },
        [51007719] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "偏見って、時に事実よりも根強いものだから。",
          DialogueId = 51007719,
          GUID = "7FB145E6",
          NextDialogue = 51007721
        },
        [51007720] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "見て見ぬふりをしてるのかもしれないね。",
          DialogueId = 51007720,
          GUID = "7FB14610",
          NextDialogue = 51007721
        },
        [51007721] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "……そうなんだ……うーん、世の中には研究しても解けない問題があるんだね。",
          DialogueId = 51007721,
          GUID = "7FB1463A",
          NextDialogue = 51007722,
          SpeakNpcId = 700204
        },
        [51007722] = {
          Camera = "128.125977,-687.591797,132.197266,0.00004,9.199882,90.600075,21.238844,100000.0,false,Manual,22.0",
          ContentJP = "もうやめやめ！ウジウジ悩んでも仕方ない！せっかくカメラもあるんだし、次はあの北の綺麗なお屋敷――ヒュプノスの家を撮りに行こうよ！先に行ってるね！",
          DialogueId = 51007722,
          GUID = "7FB14664",
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007723] = {
          ContentJP = "来てくれたんだ！えへへ……実はさ、ここのお兄さんお姉さんたちのこと、前からちょっと気になってたんだ。今日、いろんなことを知って、もっと話してみたくなったんだ！",
          DialogueId = 51007723,
          GUID = "7FB1468E",
          NextDialogue = 51007724,
          SpeakNpcId = 700204
        },
        [51007724] = {
          ContentJP = "{nickname}、一緒に行ってくれない？",
          DialogueId = 51007724,
          GUID = "7FB146B8",
          NextDialogue = 51007725,
          SpeakNpcId = 700204
        },
        [51007725] = {
          ContentJP = "…………",
          DialogueId = 51007725,
          GUID = "7FB146E2",
          NextOptions = {
            [1] = 51007726,
            [2] = 51007727
          },
          SpeakNpcId = 100001
        },
        [51007726] = {
          ContentJP = "真実を話す。",
          DialogueId = 51007726,
          GUID = "7FB1470C",
          ImprPlusId = 1002,
          NextDialogue = 51007728
        },
        [51007727] = {
          ContentJP = "言うのをためらう。",
          DialogueId = 51007727,
          GUID = "7FB14736",
          ImprPlusId = 1004,
          NextDialogue = 51007728
        },
        [51007728] = {
          ContentJP = "……今は、あんまりいいタイミングじゃないかも。",
          DialogueId = 51007728,
          GUID = "7FB14760",
          NextDialogue = 51007729,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Disagree"
          }
        },
        [51007729] = {
          ContentJP = "えっ、そうなの……？",
          DialogueId = 51007729,
          GUID = "7FB1478A",
          NextDialogue = 51007730,
          SpeakNpcId = 700204
        },
        [51007730] = {
          ContentJP = "じゃあ、ちょっとだけドアをノックしてもいい？挨拶だけでも……もしかしたら、誰かいるかもしれないし！",
          DialogueId = 51007730,
          GUID = "7FB147B4",
          NextDialogue = 51007731,
          SpeakNpcId = 700204
        },
        [51007731] = {
          ContentJP = "……実はね、そこにはもう誰もいないの。だから、ノックする必要はないよ。",
          DialogueId = 51007731,
          GUID = "7FB147DE",
          NextDialogue = 51007732,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Explain01_Start"
          }
        },
        [51007732] = {
          ContentJP = "えっ……？でも、この前こっそり覗いたときは、お兄さんやお姉さんが何人もいたのに……",
          DialogueId = 51007732,
          GUID = "7FB14808",
          NextDialogue = 51007733,
          SpeakNpcId = 700204
        },
        [51007733] = {
          ContentJP = "みんな……引っ越したんだ。",
          DialogueId = 51007733,
          GUID = "7FB14832",
          NextDialogue = 51007734,
          SpeakNpcId = 100001
        },
        [51007734] = {
          ContentJP = "じゃあ、いつ戻ってくるの？",
          DialogueId = 51007734,
          GUID = "7FB1485C",
          NextDialogue = 51007735,
          SpeakNpcId = 700204
        },
        [51007735] = {
          ContentJP = "あの緑の服のお姉さんに、どうしても聞きたいことがあって……あの怒りんぼなおじさんは……会いたくないけど。",
          DialogueId = 51007735,
          GUID = "7FB14886",
          NextDialogue = 51007736,
          SpeakNpcId = 700204
        },
        [51007736] = {
          ContentJP = "……もう戻ってこないよ。",
          DialogueId = 51007736,
          GUID = "7FB148B0",
          NextDialogue = 51007737,
          SpeakNpcId = 100001
        },
        [51007737] = {
          ContentJP = "えっ、なんで！？軍の人たちに追い出されたの？それとも、他の町に引っ越したの？それならそれでいいや。きっとアイスレイク城よりは暖かいと思うし、研究のネタもいっぱいありそうだし――",
          DialogueId = 51007737,
          GUID = "7FB148DA",
          NextDialogue = 51007738,
          SpeakNpcId = 700204
        },
        [51007738] = {
          ContentJP = "……っ！{性别:お兄さん|お姉さん}、どうして泣いてるの？ナデナデするから……泣かないで！",
          DialogueId = 51007738,
          GUID = "7FB14904",
          NextDialogue = 51007739,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Shock_Start"
          }
        },
        [51007739] = {
          ContentJP = "……大丈夫。宿の主人、ヘンリックさんっていう医者がね、みんなを連れて南の方へ向かったんだ。とある病気を治す方法を探すために。",
          DialogueId = 51007739,
          GUID = "7FB1492E",
          NextDialogue = 51007740,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Disagree"
          }
        },
        [51007740] = {
          ContentJP = "病気って、どんな？",
          DialogueId = 51007740,
          GUID = "7FB14958",
          NextDialogue = 51007741,
          SpeakNpcId = 700204
        },
        [51007741] = {
          ContentJP = "……穢蝕だよ。カロンの人だけがかかる病気で、今のところ治療法は見つかっていないんだ。たくさんの人たちが、それで苦しんでる。",
          DialogueId = 51007741,
          GUID = "7FB14982",
          NextDialogue = 51007742,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "0:Think_Start"
          }
        },
        [51007742] = {
          ContentJP = "えっ……治らないの？僕の知ってるお医者さんは、どんな難しい病気でも治せるのに。錬金院の人間たちってすごいんだよ？賢くて、研究もいっぱいしてるんだよ？",
          DialogueId = 51007742,
          GUID = "7FB149AC",
          NextDialogue = 51007743,
          SpeakNpcId = 700204
        },
        [51007743] = {
          ContentJP = "「人間」と言ったあと、少年は一瞬黙り込んだ。何かに気づいたようだ。",
          DialogueId = 51007743,
          GUID = "7FB149D6",
          NextDialogue = 51007744
        },
        [51007744] = {
          ContentJP = "……もしかして……その人たち、カロン族の病気は研究してくれないの？",
          DialogueId = 51007744,
          GUID = "7FB14A00",
          NextDialogue = 51007745,
          SpeakNpcId = 700204
        },
        [51007745] = {
          ContentJP = "そんなの、絶対おかしいよ！同じ命なのに、どうしてカロンってだけで見捨てるのさ！",
          DialogueId = 51007745,
          GUID = "7FB14A2A",
          NextOptions = {
            [1] = 51007746
          },
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Disagree"
          }
        },
        [51007746] = {
          ContentJP = "ここにはいないかもしれないけど、世界のどこかには、きっと努力してる人がいるよ。",
          DialogueId = 51007746,
          GUID = "7FB14A54",
          ImprPlusId = 1004,
          NextDialogue = 51007747
        },
        [51007747] = {
          ContentJP = "……そうだね。僕、決めたよ！偏見は変えられなくても、病気なら……きっと研究で治せる！",
          DialogueId = 51007747,
          GUID = "7FB14A7E",
          NextDialogue = 51007748,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Angry01_Start"
          }
        },
        [51007748] = {
          ContentJP = "僕もその病気のこと、研究してみるよ！あなたが話してくれたあのお医者さんみたいに、頑張ってたくさんの人を助けたい！",
          DialogueId = 51007748,
          GUID = "7FB14AA8",
          NextDialogue = 51007749,
          SpeakNpcId = 700204
        },
        [51007749] = {
          ContentJP = "錬金院には、人間の病気を治すすごい錬金術師がたくさんいるけど、僕は――世界初のカロンを助ける錬金術師になる！",
          DialogueId = 51007749,
          GUID = "7FB14AD2",
          NextDialogue = 51007750,
          SpeakNpcId = 700204
        },
        [51007750] = {
          ContentJP = "ねえ、「穢蝕」って漢字、書いてもらえる？ちゃんと覚えておきたいんだ。",
          DialogueId = 51007750,
          GUID = "7FB14AFC",
          NextDialogue = 51007751,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Explain01_Start"
          }
        },
        [51007751] = {
          ContentJP = "少年が差し出したノートに、君は「穢蝕」の二文字を丁寧に記した。",
          DialogueId = 51007751,
          GUID = "7FB14B26",
          NextDialogue = 51007752
        },
        [51007752] = {
