          GUID = "7FB14B50",
          NextDialogue = 51007753,
          SpeakNpcId = 700204,
          TalkActionId = {
            [1] = "700204:Agree"
          }
        },
        [51007753] = {
          ContentJP = "{nickname}、教えてくれてありがとう！今日は、たくさん学べたよ！",
          DialogueId = 51007753,
          GUID = "7FB14B7A",
          NextDialogue = 51007754,
          SpeakNpcId = 700204
        },
        [51007754] = {
          ContentJP = "あなたもがんばってね！あなたならきっと、アイスレイク城で一番すごい月狩り人になれるよ。みんなも、カロンを見直してくれるはず！",
          DialogueId = 51007754,
          GUID = "7FB14BA4",
          NextDialogue = 51007755,
          SpeakNpcId = 700204
        },
        [51007755] = {
