          NextDialogue = 51007757,
          SpeakNpcId = 700204
        },
        [51007757] = {
          ContentJP = "少年は手を振って別れを告げた。その笑顔には、子どもらしい無邪気さと……ほんの少し、大人びた覚悟がにじんでいた。",
          DialogueId = 51007757,
          GUID = "7FB14C22"
        },
        [51007758] = {
          ContentJP = "{NickName}、また会ったね！僕は新しい知識を学んでいるところさ！お互い頑張ろう！",
          DialogueId = 51007758,
          GUID = "7FB14C4C",
          SpeakNpcId = 700204
        },
        [51007801] = {
          Content = "向自然法则扔出的石头，最终一定会砸到自己的头上。",
          DialogueId = 51007801,
          GUID = "7FB1535A",
          NextDialogue = 51007802,
          SpeakNpcId = 700018
        },
        [51007802] = {
          Content = "（这是一个瘦弱潦倒的中年男性，看起来有些神经质，鼻梁上挂着一副厚厚的眼镜。）",
          DialogueId = 51007802,
          GUID = "7FB15384",
          NextDialogue = 51007803
        },
        [51007803] = {
          Content = "（周围散落的报告署名是“阿尔加尔”，你似乎在某些生物学期刊上见过这个名字。）",
          DialogueId = 51007803,
          GUID = "7FB153AE",
          NextOptions = {
            [1] = 51007804,
            [2] = 51007806,
            [3] = 51007808
          }
        },
        [51007804] = {
          Content = "自然是万物的起源，我们理应保护好它。",
          DialogueId = 51007804,
          GUID = "7FB153D8",
          ImprPlusId = 1002,
          NextDialogue = 51007805
        },
        [51007805] = {
          Content = "是的是的，我正是为此而来的。",
          DialogueId = 51007805,
          GUID = "7FB15402",
          NextDialogue = 51007810,
          SpeakNpcId = 100001
        },
        [51007806] = {
          Content = "自然是镜子，破坏它的苦果只会由自己吞食。",
          DialogueId = 51007806,
          GUID = "7FB1542C",
          ImprPlusId = 1001,
          NextDialogue = 51007807
        },
        [51007807] = {
          Content = "深刻的见解，我是生物学者阿尔加尔，很高兴认识你。",
          DialogueId = 51007807,
          GUID = "7FB15456",
          NextDialogue = 51007810,
          SpeakNpcId = 100001
        },
        [51007808] = {
          Content = "笑死，根本活不到砸到我的那天。",
          DialogueId = 51007808,
          GUID = "7FB15480",
          ImprPlusId = 1005,
          NextDialogue = 51007809
        },
        [51007809] = {
          Content = "……",
          DialogueId = 51007809,
          GUID = "7FB154AA",
          NextDialogue = 51007810,
          SpeakNpcId = 100001
        },
        [51007810] = {
          Content = "唉，年轻人，你听说过冰湖城的红角鹿吗？",
          DialogueId = 51007810,
          GUID = "7FB154D4",
          NextDialogue = 51007811,
          SpeakNpcId = 700018
        },
        [51007811] = {
          Content = "那是非常古老的物种，已经存在了三亿多年，至今保留着其原始而古老的相貌。",
          DialogueId = 51007811,
          GUID = "7FB154FE",
          NextDialogue = 51007812,
          SpeakNpcId = 700018
        },
        [51007812] = {
          Content = "这不只是一对红角，这是整片大陆诞生时的......脐血。",
          DialogueId = 51007812,
          GUID = "7FB15528",
          NextDialogue = 51007813,
          SpeakNpcId = 700018
        },
        [51007813] = {
          Content = "（阿尔加尔说话时，原本苍白的脸上浮现出了激动的红晕。可随后他似乎又想起了什么，露出焦虑悲戚的神色。）",
          DialogueId = 51007813,
          GUID = "7FB15552",
          NextDialogue = 51007814
        },
        [51007814] = {
          Content = "所以我一定要阻止那些贪得无厌的猎人，不能再任由他们无节制地狩猎红角鹿了......",
          DialogueId = 51007814,
          GUID = "7FB1557C",
          NextDialogue = 51007815,
          SpeakNpcId = 700018
        },
        [51007815] = {
          Content = "红角鹿的鹿角具有极高的药用价值，内城的贵族们开了高价收购。",
          DialogueId = 51007815,
          GUID = "7FB155A6",
          NextDialogue = 51007816,
          SpeakNpcId = 700018
        },
        [51007816] = {
          Content = "那群贵族们的拥趸像一群见了血肉的苍蝇一样蜂拥而上。他们握着枪杆杀红了眼，射向红角鹿的子弹越多，他们腰间的钱袋越重。",
          DialogueId = 51007816,
          GUID = "7FB155D0",
          NextDialogue = 51007817,
          SpeakNpcId = 700018
        },
        [51007817] = {
          Content = "仅仅十年，冰湖城郊区的红角鹿就从随处可见变成如今濒临灭绝的境地。",
          DialogueId = 51007817,
          GUID = "7FB155FA",
          NextOptions = {
            [1] = 51007818
          },
          RestartTag = 51007817,
          SpeakNpcId = 700018
        },
        [51007818] = {
          Content = "红角鹿活了三亿年，不该被人们的贪婪一朝逼入绝境。",
          DialogueId = 51007818,
          GUID = "7FB15624",
          ImprCheckId = 1063,
          NextDialogue = 51007819
        },
        [51007819] = {
          Content = "算了，多说无益......",
          DialogueId = 51007819,
          GUID = "7FB1564E",
          NextDialogue = 51007820,
          SpeakNpcId = 700018
        },
        [51007820] = {
          Content = "（阿尔加尔叹了口气，瘦弱的身体在转身时踉跄了一下，离开的背影如同一位殉道者。）",
          DialogueId = 51007820,
          GUID = "7FB15678",
          NextDialogue = 51007821,
          SpeakNpcId = 700018
        },
        [51007821] = {
          Content = "正如你所说，它们珍贵的鹿角不该成了猎人的摇钱树。",
          DialogueId = 51007821,
          GUID = "7FB156A2",
          NextDialogue = 51007822,
          SpeakNpcId = 700018
        },
        [51007822] = {
          Content = "红角鹿的繁殖期马上就要到了，我们必须为自然真的做些什么。",
          DialogueId = 51007822,
          GUID = "7FB156CC",
          NextDialogue = 51007823,
          SpeakNpcId = 700018
        },
        [51007823] = {
          Content = "咳，年轻人，可以拜托你帮我阻止那些滥杀红角鹿的猎人吗？",
          DialogueId = 51007823,
          GUID = "7FB156F6",
          NextDialogue = 51007824,
          SpeakNpcId = 700018
        },
        [51007824] = {
          Content = "年轻人，那就靠你了，我在这里等你回来。",
          DialogueId = 51007824,
          GUID = "7FB15720",
          SpeakNpcId = 700018
        },
        [51007825] = {
          Content = "赶走滥杀红角鹿的猎人，已经刻不容缓了。",
          DialogueId = 51007825,
          GUID = "7FB1574A",
          SpeakNpcId = 700018
        },
        [51007826] = {
          Content = "（这只红角鹿的脖颈已经被猎人的子弹击穿，胸腔微弱起伏是它最后的挣扎。）",
          DialogueId = 51007826,
          GUID = "7FB15774",
          NextDialogue = 51007827
        }
      }
    end
  },
