        },
        [51007918] = {
          ContentJP = "管内の音に引き寄せられた<Default note=\"text:エジュウ\">穢獣</>が現れる。すべてを倒すと、どこかからダートンの声が聞こえてくる。",
          DialogueId = 51007918,
          GUID = "7FB1668C",
          IsBlack = 1,
          NextDialogue = 51007919
        },
        [51007919] = {
          ContentJP = "たーーのーーしーーいーーねーー！ゴーーールーーでーーあーーおーーねーー！",
          DialogueId = 51007919,
          GUID = "7FB166B6",
          SpeakNpcId = 700191
        },
        [51007920] = {
          ContentJP = "ゴールには水たまりしかない。パイプに耳を当てると、さらに先から金属のきしむ音が聞こえてきた。どうやらダートンは先まで滑っていったらしい。",
          DialogueId = 51007920,
          GUID = "7FB166E0"
        },
        [51007921] = {
          ContentJP = "パイプから次々と<Default note=\"text:エジュウ\">穢獣</>が湧き出てくる。進路をふさぐ敵を倒せ！",
          DialogueId = 51007921,
          GUID = "7FB1670A",
          IsBlack = 1
        },
        [51007922] = {
          Camera = "-143.335342,-546.682495,487.077148,0.000039,-45.799725,92.919357,15.353726,100000.0,false,Manual,22.0",
          ContentJP = "うっ……うえっ……げほっ……",
          DialogueId = 51007922,
          FinalCamera = "-60.066826,-542.436035,487.077148,0.000039,-45.799725,92.919357,15.353726,100000.0,false,Manual,22.0",
          GUID = "7FB16734",
          NextDialogue = 51007923,
          SpeakNpcId = 700191,
          TalkActionId = {
            [1] = "700191:Hurt01"
          },
          ToFinalCameraBlendTime = 8,
          TurnTo = {
            [1] = "100001:n(700191)"
          }
        },
        [51007923] = {
          ContentJP = "ダートンは誤った出口から吹っ飛んできた。そして、地面に突っ伏してゲーゲーと吐いている。「ウォータースライダー」は想像以上に過酷だったらしい。",
          DialogueId = 51007923,
          GUID = "7FB1675E",
          NextOptions = {
            [1] = 51007924,
            [2] = 51007925
          }
        },
        [51007924] = {
          ContentJP = "大丈夫？",
          DialogueId = 51007924,
          GUID = "7FB16788",
          ImprPlusId = 1002,
          NextDialogue = 51007926
        },
        [51007925] = {
          ContentJP = "ごめん、良く見えなかったからもう一回滑ってくれる？",
          DialogueId = 51007925,
          GUID = "7FB167B2",
          ImprPlusId = 1005,
          NextDialogue = 51007926
        },
        [51007926] = {
          Camera = "-310.433411,-170.472031,157.965942,0.000161,-12.197788,12.9158,15.353726,100000.0,false,Manual,22.0",
          ContentJP = "はぁ……はぁ……",
          DialogueId = 51007926,
          GUID = "7FB167DC",
          NextDialogue = 51007927,
          SpeakNpcId = 700191
        },
        [51007927] = {
          ContentJP = "無理……ちょっと休ませて……ああ、これ報酬……先に帰るね……",
          DialogueId = 51007927,
          GUID = "7FB16806",
          NextDialogue = 51007928,
          SpeakNpcId = 700191,
          TalkActionId = {
            [1] = "700191:Sigh_Start"
          }
        },
        [51007928] = {
          Camera = "-125.646004,-486.612549,465.015015,-0.001072,-47.41058,90.325813,15.353726,100000.0,false,Manual,22.0",
          ContentJP = "……どうすれば、ミスト区の人たちでも楽しめる、安くて面白いアトラクションが作れるんだろう……",
          DialogueId = 51007928,
          GUID = "7FB16830",
          NextDialogue = 51007929,
          SpeakNpcId = 700191
        },
        [51007929] = {
          ContentJP = "ダートンは小さな包みを君に手渡すと、胸を押さえながらその場を後にした。もう戻ってくることはないだろう。",
          DialogueId = 51007929,
          GUID = "7FB1685A",
          IsBlack = 1
        },
        [51007930] = {
          ContentJP = "ミスト区には娯楽がない……まだビジネスチャンスは残ってるはずだ……",
          DialogueId = 51007930,
          GUID = "7FB16884",
          SpeakNpcId = 700191
        },
        [51008001] = {
          ContentJP = "じゃ、邪魔だ……月ノ石を買わないなら、どっかに行けってんだ……頼む、兵士たちの目を引かないでくれ……",
          DialogueId = 51008001,
          GUID = "7FB1742A",
          NextDialogue = 51008002,
          SpeakNpcId = 700113
        },
        [51008002] = {
          ContentJP = "（たくましい体の男が隅に縮こまっている。月ノ石を早急に売りつけるか、他者に助けを求めるか、色々とためらいが窺える目を逸らし方だ。見てくれのイメージとはまったく違う）",
          DialogueId = 51008002,
          GUID = "7FB17454",
          NextOptions = {
            [1] = 51008003,
            [2] = 51008004,
            [3] = 51008005,
            [4] = 51008007
          }
        },
        [51008003] = {
          ContentJP = "{性别:私は買わないけど、報酬の半分を分けてくれるなら、買い手を探してあげないこともない。|僕は買わないけど、報酬の半分を分けてくれるなら、買い手を探してやらないこともない。}",
          DialogueId = 51008003,
          GUID = "7FB1747E",
          ImprPlusId = 1001,
          NextDialogue = 51008009
        },
        [51008004] = {
          ContentJP = "{性别:何か手伝いが必要なの？|何か手伝いが必要なのか？}",
          DialogueId = 51008004,
          GUID = "7FB174A8",
          ImprPlusId = 1004,
          NextDialogue = 51008009
        },
        [51008005] = {
          ContentJP = "{性别:帝国がそんな商売を許すわけないじゃない。早く行かないと面倒事に巻き込まれるよ？|帝国がそんな商売を許すわけないじゃないか。早く行かないと面倒事に巻き込まれるぞ？}",
          DialogueId = 51008005,
          GUID = "7FB174D2",
          ImprPlusId = 1002,
          NextDialogue = 51008006
        },
        [51008006] = {
          ContentJP = "こ、今回だけは大目に見てくれないか。この月ノ石を売っぱらったらアイスレイク城から速攻で離れる。二度と帰ってこないから……",
          DialogueId = 51008006,
          GUID = "7FB174FC",
          NextDialogue = 51008009,
          SpeakNpcId = 700113
        },
        [51008007] = {
          ContentJP = "帝国軍の兵士様からお前に尋問しろと依頼を受けた！サッサと通行許可証を出せ！",
          DialogueId = 51008007,
          GUID = "7FB17526",
          ImprPlusId = 1005,
          NextDialogue = 51008008
        },
        [51008008] = {
          ContentJP = "（男はそれを聞くや否や瞬間で袋を持ち上げて逃げようとした。慌てて自分の身分と冗談であることを説明すると、彼は小声で話し始める。何やら困った状況なようだ）",
          DialogueId = 51008008,
          GUID = "7FB17550",
          NextDialogue = 51008009,
          SpeakNpcId = 700113
        },
        [51008009] = {
          ContentJP = "……買い手を探してくれたら報酬の70％、いや、80％を渡す！どうか頼む、後生の頼みだ！",
          DialogueId = 51008009,
          GUID = "7FB1757A",
          SpeakNpcId = 700113
        },
        [51008010] = {
          ContentJP = "男の依頼には応じたものの──あの表情と、袋に滲んだ暗赤色の染みが、この月ノ石たちがただの品物じゃないことを物語っている。",
          DialogueId = 51008010,
          GUID = "7FB175A4",
          NextDialogue = 51008011
        },
        [51008011] = {
          ContentJP = "下手に売り手探すより、まずはこの月ノ石の出どころを確かめたほうがいいかもしれない。",
          DialogueId = 51008011,
          GUID = "7FB175CE"
        },
        [51008012] = {
          ContentJP = "（あの草むらで、何かが光ったような……？）",
          DialogueId = 51008012,
          GUID = "7FB175F8",
          NextOptions = {
            [1] = 51008053
          }
        },
        [51008013] = {
          ContentJP = "草むらをかき分けたが、何も見つからなかった。気のせいだったかもしれない。",
          DialogueId = 51008013,
          GUID = "7FB17622"
        },
        [51008014] = {
          ContentJP = "草をかき分けると、ほんのり光る石を見つけた──月ノ石だ。ただ、その表面には、男の袋と同じように暗赤色の血がこびりついていた。",
          DialogueId = 51008014,
          GUID = "7FB1764C",
          NextDialogue = 51008015
        },
        [51008015] = {
          ContentJP = "こんな日に道ばたで都合よく月ノ石が拾えるなんて、あるわけない。しかも血まみれの月ノ石なんて──なおさら、ね。",
          DialogueId = 51008015,
          GUID = "7FB17676",
          NextDialogue = 51008016,
          SpeakNpcId = 100001
        },
        [51008016] = {
          ContentJP = "グオォォォ……！",
          DialogueId = 51008016,
          GUID = "7FB176A0",
          NextDialogue = 51008017
        },
        [51008017] = {
          ContentJP = "まずは、<Default note=\"text:エジュウ\">穢獣</>を片付けないと……",
          DialogueId = 51008017,
          GUID = "7FB176CA",
          SpeakNpcId = 100001
        },
        [51008018] = {
          ContentJP = "石くれ、折れた枝、砕けた瓦礫……散乱した痕跡から、ここで激しい争いがあったことがわかる。",
          DialogueId = 51008018,
          GUID = "7FB176F4",
          NextDialogue = 51008019
        },
        [51008019] = {
          ContentJP = "残骸には引き裂かれた安物の布と綿屑も混じっており、それはあの買い手探しの男の着ていた服に酷似していた。",
          DialogueId = 51008019,
          GUID = "7FB1771E"
        },
        [51008020] = {
          ContentJP = "瓦礫をかき分けると、小さな血に染まった月ノ石のかけらが見つかった。",
          DialogueId = 51008020,
          GUID = "7FB17748"
        },
        [51008021] = {
          ContentJP = "辺りの足跡は乱雑だが、<Default note=\"text:エジュウ\">穢獣</>や野生動物の蹄跡は見当たらず、人の足跡だけが残っている。",
          DialogueId = 51008021,
          GUID = "7FB17772"
        },
        [51008022] = {
          ContentJP = "重たいものを引きずった跡が、遠くまで続いている。",
          DialogueId = 51008022,
          GUID = "7FB1779C",
          NextDialogue = 51008023
        },
        [51008023] = {
          ContentJP = "……だいたい見えてきた。血のついた月ノ石の出どころは──",
          DialogueId = 51008023,
          GUID = "7FB177C6",
          NextOptions = {
            [1] = 51008024,
            [2] = 51008026,
            [3] = 51008028
          },
          SpeakNpcId = 100001
        },
        [51008024] = {
          ContentJP = "人だ",
          DialogueId = 51008024,
          GUID = "7FB177F0",
          NextDialogue = 51008025
        },
        [51008025] = {
          ContentJP = "（ここには穢獣も野生動物も来ていないからね。）",
          DialogueId = 51008025,
          GUID = "7FB1781A",
          NextDialogue = 51008030
        },
        [51008026] = {
          ContentJP = "獣だ",
          DialogueId = 51008026,
          GUID = "7FB17844",
          NextDialogue = 51008027
        },
        [51008027] = {
          ContentJP = "（もし野生動物なら蹄跡が残るはずだ。）",
          DialogueId = 51008027,
          GUID = "7FB1786E",
          NextDialogue = 51008030
        },
        [51008028] = {
          ContentJP = "穢獣だ",
          DialogueId = 51008028,
          GUID = "7FB17898",
          NextDialogue = 51008029
        },
        [51008029] = {
          ContentJP = "（もし<Default note=\"text:エジュウ\">穢獣</>なら蹄跡が残るはずだ。）",
          DialogueId = 51008029,
          GUID = "7FB178C2",
          NextDialogue = 51008030
        },
        [51008030] = {
          ContentJP = "──誰かがここで人を襲ったんだ。狙いは……月ノ石入りの袋か。さて、どうしよう……",
          DialogueId = 51008030,
          GUID = "7FB178EC",
          SpeakNpcId = 100001,
          TalkOptions = {
            [1] = 51008031,
            [2] = 51008032
          }
        },
        [51008031] = {
          ContentJP = "あの男の月ノ石はやっぱり怪しい。黙って自分の物にしてしまおう。",
          DialogueId = 51008031,
          GUID = "7FB17916",
          ImprPlusId = 1005
        },
        [51008032] = {
          ContentJP = "あの男は悪事に手を染めたんだ。警備部隊に通報しよう。",
          DialogueId = 51008032,
          GUID = "7FB17940",
          ImprPlusId = 1002
        },
        [51008033] = {
          ContentJP = "ねえ、何か隠してるでしょ？",
          DialogueId = 51008033,
          GUID = "7FB1796A",
          NextDialogue = 51008034,
          SpeakNpcId = 100001
        },
        [51008034] = {
          ContentJP = "この月ノ石のことは覚えてないかもしれないけど……この血付きの月ノ石とその主は、きっとあんたのことを忘れないだろうね。",
          DialogueId = 51008034,
          GUID = "7FB17994",
          NextDialogue = 51008035,
          SpeakNpcId = 100001
        },
        [51008035] = {
          ContentJP = "わ、わけがわからない……何の話だよ……！",
          DialogueId = 51008035,
          GUID = "7FB179BE",
          NextDialogue = 51008036,
          SpeakNpcId = 700113
        },
        [51008036] = {
          ContentJP = "もう結構だ！お前に手伝ってもらわんでもいい！月ノ石だのなんだの、わけのわからんことを！",
          DialogueId = 51008036,
          GUID = "7FB179E8",
          NextDialogue = 51008037,
          SpeakNpcId = 700113
        },
        [51008037] = {
          ContentJP = "そんなに焦らなくてもいいよ。でも──この袋の中身は、いただいてくよ。",
          DialogueId = 51008037,
          GUID = "7FB17A12",
          NextDialogue = 51008038,
          SpeakNpcId = 100001
        },
        [51008038] = {
          ContentJP = "なっ……貴様……",
          DialogueId = 51008038,
          GUID = "7FB17A3C",
          NextDialogue = 51008039,
          SpeakNpcId = 700113
        },
        [51008039] = {
          ContentJP = "もちろん、どうするかはあんたの自由だけどね。",
          DialogueId = 51008039,
          GUID = "7FB17A66",
          NextDialogue = 51008040,
          SpeakNpcId = 100001
        },
        [51008040] = {
          ContentJP = "どう選択してもいいけど、警備部隊が到着するまでそう時間もないと思うな。どうする？",
          DialogueId = 51008040,
          GUID = "7FB17A90",
          NextDialogue = 51008041,
          SpeakNpcId = 100001
        },
        [51008041] = {
          ContentJP = "わかったよ！全部やる！",
          DialogueId = 51008041,
          GUID = "7FB17ABA",
          NextDialogue = 51008042,
          SpeakNpcId = 700113
        },
        [51008042] = {
          ContentJP = "これさえ拾わなければ……あいつらが死ぬこともなかったんだ！今頃家に帰って休んでただろうよ……",
          DialogueId = 51008042,
          GUID = "7FB17AE4",
          NextDialogue = 51008043,
          SpeakNpcId = 700113
        },
        [51008043] = {
          ContentJP = "今日は運がよかった……夜になったら、みんなで乾杯して、大声で笑いあって……そんなはずだったんだ……！",
          DialogueId = 51008043,
          GUID = "7FB17B0E",
          NextDialogue = 51008044,
          SpeakNpcId = 700113
        },
        [51008044] = {
          ContentJP = "またみんなで騒いで、明日もきっと笑って過ごせるって、信じてたのに……！",
          DialogueId = 51008044,
          GUID = "7FB17B38",
          NextDialogue = 51008045,
          SpeakNpcId = 700113
        },
        [51008045] = {
          ContentJP = "わ……渡さんぞ！",
          DialogueId = 51008045,
          GUID = "7FB17B62",
          SpeakNpcId = 700113
        },
        [51008046] = {
          Camera = "-607.952148,-441.947266,565.15332,0.000023,-34.799801,23.996548,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "うそだな！警備部隊なんて来ないんだろ！月ノ石を奪うために、俺を騙したな！",
          DialogueId = 51008046,
          GUID = "7FB17B8C",
          NextDialogue = 51008047,
          SpeakNpcId = 700113
        },
        [51008047] = {
          ContentJP = "あなただって、その月ノ石のために友人を殺したよね？さっきみたいに。",
          DialogueId = 51008047,
          GUID = "7FB17BB6",
          NextDialogue = 51008048,
          SpeakNpcId = 100001
        },
        [51008048] = {
          ContentJP = "先に手を出したのはあいつらだ…ただの正当防衛だったんだ！",
          DialogueId = 51008048,
          GUID = "7FB17BE0",
          NextDialogue = 51008049,
          SpeakNpcId = 700113
        },
        [51008049] = {
          ContentJP = "それに、お前だって──結局は月ノ石が狙いなんだろ？きれいごとを言う資格などない……！",
          DialogueId = 51008049,
          GUID = "7FB17C0A",
          NextOptions = {
            [1] = 51008050,
            [2] = 51008051
          },
          SpeakNpcId = 700113
        },
        [51008050] = {
          ContentJP = "大人なら自分の罪に責任を持つべきだ。この月ノ石はほんの教訓だよ。",
          DialogueId = 51008050,
          GUID = "7FB17C34",
          ImprPlusId = 1001,
          NextDialogue = 51008052
        },
        [51008051] = {
          ContentJP = "こっちだって善人じゃないから。あなたと同じようにね。でも、命だけは見逃してあげる。さっさと失せな。",
          DialogueId = 51008051,
          GUID = "7FB17C5E",
          ImprPlusId = 1005,
          NextDialogue = 51008052
        },
        [51008052] = {
          ContentJP = "手に残った血まみれの月ノ石は、やけに重かった。その重みは、まるで全ての「ラリー」を呑み込もうとする怪物のようだった。",
          DialogueId = 51008052,
          GUID = "7FB17C88",
          IsBlack = 1
        },
        [51008053] = {
          ContentJP = "頭を下げて探してみる",
          DialogueId = 51008053,
          GUID = "7FB17CB2",
          ImprCheckId = 1070
        },
        [51008054] = {
          ContentJP = "目障りな穢獣どもを一掃したあと、周囲の地面に何かが埋められていたような痕跡が露わになった。あなたは、その新たな手がかりを調べてみることにした。",
          DialogueId = 51008054,
          GUID = "7FB17CDC"
        },
        [51009001] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "新作公演だよ、新作上映中！そこの君、ちょっと見ていかない？",
          DialogueId = 51009001,
          GUID = "7FB2183A",
          LookAt = {
            [1] = "700240:n(100001)"
          },
          NextDialogue = 51009002,
          SpeakNpcId = 700240
        },
        [51009002] = {
          ContentJP = "{性别:え、僕？|え、私？}",
          DialogueId = 51009002,
          GUID = "7FB21864",
          NextDialogue = 51009003,
          SpeakNpcId = 100001
        },
        [51009003] = {
          ContentJP = "そうそう、君だよ！今、ガレア劇場では全く新しい形式の劇のテスト公演をしてるんだ――その名も「体験型劇場」だ！",
          DialogueId = 51009003,
          GUID = "7FB2188E",
          NextDialogue = 51009004,
          SpeakNpcId = 700240
        },
        [51009004] = {
          Camera = "-758.908325,369.843262,211.244629,0.000082,-6.598509,-20.974316,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "これはルッカ発祥の革新的な舞台劇でね！観客席に縛られることなく、君自身が「どこへ行くか」を選べる！もっと言えば、物語の登場人物として、君自身が劇に参加できるんだ！",
          DialogueId = 51009004,
          GUID = "7FB218B8",
          NextDialogue = 51009005,
          SpeakNpcId = 700240,
          TalkActionId = {
            [1] = "700240:Explain02_Start"
          }
        },
        [51009005] = {
          ContentJP = "今上演しているのは、英雄の冒険譚！私たちは今、この壮大な芸術実験を成功させるために、志ある参加者を募集しているんだ。参加者には、特別なプレゼントも用意しているよ！",
          DialogueId = 51009005,
          GUID = "7FB218E2",
          SpeakNpcId = 700240,
          TalkActionId = {
