            [1] = "100001:Explain02_Start"
          }
        },
        [51009116] = {
          Camera = "-47.538391,-157.203125,145.923813,0.00021,-15.601462,76.384178,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "旅に出る若者にとって、武器は何より大事な相棒じゃ。備えあれば憂いなしってな。",
          DialogueId = 51009116,
          FacialId = {
            [1] = "230002:Happy02"
          },
          GUID = "7FB22B18",
          NextDialogue = 51009117,
          SpeakNpcId = 230002,
          TalkActionId = {
            [1] = "100001:Explain02_End"
          }
        },
        [51009117] = {
          ContentJP = "私はの、お主みたいな若いのを山ほど見てきた。静かに消えてったやつもおれば、アトラシアの伝説になったやつもおる。――でもな、最初はみんな、好奇心と無鉄砲だけが取り柄の青二才だった。",
          DialogueId = 51009117,
          FacialId = {
            [1] = "230002:Ahaha02"
          },
          GUID = "7FB22B42",
          NextDialogue = 51009118,
          SpeakNpcId = 230002
        },
        [51009118] = {
          ContentJP = "頼れる武器ってのはな、未熟さや軽率さを補ってくれる、いわば特効薬みたいなもんじゃ。",
          DialogueId = 51009118,
          FacialId = {
            [1] = "230002:Satisfy01"
          },
          GUID = "7FB22B6C",
          NextDialogue = 51009119,
          SpeakNpcId = 230002
        },
        [51009119] = {
          Camera = "-11.187744,-30.125488,113.694717,0.000209,-16.401381,81.782051,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "お主にはもうあまり必要ないかもしれんが――予備としてでも持っていくといい。この武器は託しておくよ。若いもんへの、年寄りからのささやかな忠告じゃ。",
          DialogueId = 51009119,
          GUID = "7FB22B96",
          NextDialogue = 51009120,
          SpeakNpcId = 230002
        },
        [51009120] = {
          Camera = "-36.630005,38.096924,125.536903,0.000215,5.798011,-71.413826,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "先輩……",
          DialogueId = 51009120,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB22BC0",
          NextDialogue = 51009121,
          SpeakNpcId = 100001
        },
        [51009121] = {
          Camera = "-23.448242,-113.345947,147.890976,0.000217,-16.601587,81.187027,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "これから先、新しい素材や図譜を手に入れたら、私のところへ持ってくるといい。また新しい武器を打ってやろう。",
          DialogueId = 51009121,
          FacialId = {
            [1] = "230002:Confident02"
          },
          GUID = "7FB22BEA",
          NextDialogue = 51009122,
          SpeakNpcId = 230002
        },
        [51009122] = {
          ContentJP = "じゃが、この一振りだけは特別じゃ……もしもいつか、切れ味を失い、欠け、あるいは折れてしまったら――そのときは持って帰ってくるんじゃ。何度でも、鍛え直してやろう。",
          DialogueId = 51009122,
          GUID = "7FB22C14",
          NextDialogue = 51009123,
          SpeakNpcId = 230002
        },
        [51009123] = {
          Camera = "-72.498413,-159.67749,187.376312,0.000227,-25.601515,61.982807,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "願わくば、いつどんなときでも――この剣を握れば、お主が旅立ちを決意したあの気持ちを、ふと思い出してくれるといい。",
          DialogueId = 51009123,
          FacialId = {
            [1] = "230002:Happy02"
          },
          GUID = "7FB22C3E",
          NextDialogue = 51009124,
          SpeakNpcId = 230002
        },
        [51009124] = {
          Camera = "-77.020996,37.951172,120.615501,0.000228,5.798578,-53.617523,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "大事に使うよ。",
          DialogueId = 51009124,
          FacialId = {
            [1] = "100001:Confident02"
          },
          GUID = "7FB22C68",
          NextDialogue = 51009125,
          SpeakNpcId = 100001,
          TalkActionId = {
