        },
        [51009205] = {
          Camera = "182.905762,56.904785,140.219238,0.000167,0.19811,-165.575302,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "どうか警戒なさらずに。私がここをうろついていたのは、ただ――<H>美学的</>な疑問に心を惑わされていただけだ。",
          DialogueId = 51009205,
          FacialId = {
            [1] = "100001:None"
          },
          FinalCamera = "209.431152,63.451172,140.220459,0.000167,-0.001858,-166.175751,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB239B2",
          NextDialogue = 51009206,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "100001:Think_End",
            [2] = "230003:Explain01_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009206] = {
          ContentJP = "君も感じたことはないかね、友よ――近ごろの武器ときたら、殺傷力やコストばかりが重視されて、鍛造品たるべき美というものが、すっかり忘れられている気がしてならんのだ。",
          DialogueId = 51009206,
          GUID = "7FB239DC",
          NextDialogue = 51009207,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Explain01_End"
          }
        },
        [51009207] = {
          Camera = "-2849.924805,472.516602,-933.664307,0.000118,-4.801397,-111.175285,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "武器というのは、元来私の主な研究対象ではなかったのだが……気づいているかい？近ごろこの街の兵たちが、なんともまあ粗野になってきているのだよ。",
          DialogueId = 51009207,
          FinalCamera = "-2585.590332,363.479004,-933.664307,0.000116,-5.401429,-115.973396,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "7FB23A06",
          NextDialogue = 51009208,
          SpeakNpcId = 230003,
          ToFinalCameraBlendTime = 15
        },
        [51009208] = {
          Camera = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "思うに――ヒュペリアの錬金院が美の探求を放棄してしまったがゆえに、あの兵たちもここまで無粋に、無様になってしまったのだ。そして私が、彼らの装備に美学的な修正を施したところ……まったく、理不尽にも咎められてしまってね……",
          DialogueId = 51009208,
          GUID = "7FB23A30",
          NextDialogue = 51009209,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Explain02_Start"
          }
        },
        [51009209] = {
          Camera = "107.540039,43.087402,155.901123,0.000135,-9.202333,39.223675,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "「修正」って……何か行き過ぎたことでもしちゃったんじゃ？",
          DialogueId = 51009209,
          GUID = "7FB23A5A",
          NextDialogue = 51009210,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009210] = {
          Camera = "323.17334,117.169922,145.404541,0.000149,-2.002072,-168.165207,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "行き過ぎ？とんでもない！ただ交代の隙に彼らの武器や装飾をほんの少し手直ししただけだよ。それに対して十五日の監禁とは……むしろ非常識なのはあちらではないかね！？",
          DialogueId = 51009210,
          GUID = "7FB23A84",
          NextDialogue = 51009211,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Angry01_Start"
          }
        },
        [51009211] = {
          ContentJP = "万人に美学の素養を行き渡らせるのが、いかに困難で偉大な試みであろうとも――我々はその険しさに屈して歩みを止めてはならんのだ！",
          DialogueId = 51009211,
          GUID = "7FB23AAE",
          NextDialogue = 51009212,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Angry01_End"
          }
        },
        [51009212] = {
          Camera = "355.351074,108.127441,146.656494,0.000137,-3.402848,-172.570343,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "このアミエット、芸術の名にかけて誓おう！伝説の英雄が振るう剣であろうと、身を守るだけの小さなナイフであろうと――その出自や値段に関わらず、すべての武器には美が宿るべきなのだ！",
          DialogueId = 51009212,
          GUID = "7FB23AD8",
          NextDialogue = 51009213,
          SpeakNpcId = 230003,
          TalkActionId = {
            [1] = "230003:Agree"
          }
        },
        [51009213] = {
