          GUID = "7FB24B40",
          NextDialogue = 51009317
        },
        [51009313] = {
          Content = "哦不，我讨厌粉红色！",
          DialogueId = 51009313,
          GUID = "7FB24B6A",
          ImprPlusId = 1005,
          NextDialogue = 51009314
        },
        [51009314] = {
          Content = "哎呀，那真是抱歉了。",
