          GUID = "7FB26778",
          NextDialogue = 51009485,
          SpeakNpcId = 700313,
          TalkActionId = {
            [1] = "700313:Shock_End"
          }
        },
        [51009485] = {
          ContentJP = "……そっか。これを君が持ってるってことは……俺の想いは、届かなかったんだな。わかったよ。もう邪魔はしない。君たちを祝福するよ……",
          DialogueId = 51009485,
          GUID = "7FB267A2",
          NextOptions = {
            [1] = 510093951,
            [2] = 510093952
          },
          SpeakNpcId = 700313
        },
        [51009486] = {
          Camera = "62.644531,-11.876099,183.486328,0.000056,-8.794127,105.195045,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……もう何も言わなくていい……この燃える心は、そっとしまうよ……",
          DialogueId = 51009486,
