          TalkActionId = {
            [1] = "700300:Talk02_End",
            [2] = "100001:Give"
          }
        },
        [51009491] = {
          ContentJP = "このリボン……十年以上もずっとつけてたって聞いたけど、本当？",
          DialogueId = 51009491,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2689E",
          NextDialogue = 51009492,
