          }
        },
        [51009492] = {
          Camera = "-225.489746,72.248535,138.279785,0.000003,0.400024,-11.196719,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ええ、これは――ある友人が残してくれた形見なの。とても才能のある人だったけど、運命に恵まれなかった……",
          DialogueId = 51009492,
          FacialId = {
            [1] = "700300:CM_Sad01"
