          GUID = "7FB268C8",
          NextDialogue = 51009493,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Explain01_End",
            [2] = "700300:Sigh_Start"
          }
        },
        [51009493] = {
          ContentJP = "彼女には叶わなかった夢、でも私なら舞台に立てる。だからせめて、一緒に輝けるようにと思って、このリボンを身につけるようになったの。",
          DialogueId = 51009493,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB268F2",
          NextDialogue = 51009494,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009494] = {
          ContentJP = "初舞台のとき、自分でポスターをデザインしたのよ。白黒の構図に、一筋だけ鮮やかな紫――それがこのリボン。",
          DialogueId = 51009494,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2691C",
          NextDialogue = 51009495,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009495] = {
          ContentJP = "「千面のヴィオレッタ」って、知ってるかしら？役に合わせて姿を変えるのが私のスタイル。",
          DialogueId = 51009495,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26946",
          NextDialogue = 51009496,
          SpeakNpcId = 700300
        },
        [51009496] = {
          ContentJP = "でも、このリボンだけはいつも変わらないわ。いつしかそれが、<H>私だけのチャームポイント</>になったの。",
          DialogueId = 51009496,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB26970",
          NextDialogue = 51009497,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_End"
