            [1] = "700300:Sigh_Start"
          }
        },
        [51009507] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "一体、何が……？",
          DialogueId = 51009507,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB26B3E",
          NextDialogue = 51009508,
