          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009508] = {
          Camera = "-401.135742,235.075195,139.57666,0.000003,-1.799823,-39.399132,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "これを見て。",
          DialogueId = 51009508,
          GUID = "7FB26B68",
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "100001:Talk02_End",
            [2] = "700300:Give"
          }
        },
        [51009509] = {
          ContentJP = "ヴィオレッタ――いや、E・Rと呼ぶべきか。お前が十六年間隠してきた汚れた過去を、私は知っている。今夜、アイスレイク城の脇門近く、池のほとりへ一人で来い。さもなくば、お前の弟子の命はない。",
          DialogueId = 51009509,
          Duration = 5,
          GUID = "7FB26B92"
        },
        [51009510] = {
          Camera = "154.741699,155.880859,184.548828,0.000014,-8.400074,-153.591629,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "…………",
          DialogueId = 51009510,
          FacialId = {
            [1] = "100001:Shock02"
          },
          GUID = "7FB26BBC",
          NextDialogue = 51009511,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock02_Start"
          }
        },
        [51009511] = {
          Camera = "-143.32959,40.580566,146.557373,0.000003,-2.199983,-3.996218,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……これまでの手紙は、ただのカモフラージュだったのかも。油断したわ。",
          DialogueId = 51009511,
          GUID = "7FB26BE6",
          NextDialogue = 51009512,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009512] = {
          ContentJP = "ごめんなさい、これで失礼するわ。あなたへの依頼は、これで終了よ。報酬も約束通り。",
          DialogueId = 51009512,
          GUID = "7FB26C10",
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51009513] = {
          ContentJP = "どうやら目の前で、誘拐事件が進行しているようだ。ヴィオレッタは警備部隊に協力を仰ぐつもりのようだが――もし機会があれば、この事件の行方も追ってみよう。",
          DialogueId = 51009513,
          GUID = "7FB26C3A",
          Scripts = "PlayOrStopBGM{_delay{10},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt02/0043_story_empire\"}}"
        },
        [51009601] = {
          ContentJP = "お願いです、どうか……助けてください……！",
          DialogueId = 51009601,
          GUID = "7FB27AAA",
          SpeakNpcId = 700303
        },
        [51009602] = {
          ContentJP = "少年が焦った様子で、あなたの袖をぐっと掴んだ。",
          DialogueId = 51009602,
          GUID = "7FB27AD4",
          IsBlack = 1,
          NextDialogue = 510095121
        },
        [51009603] = {
          ContentJP = "ドナートおじさんが……ひどい病気なんです……",
          DialogueId = 51009603,
          GUID = "7FB27AFE",
          NextDialogue = 51009604,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Sigh_Start"
          }
        },
        [51009604] = {
          ContentJP = "皆言ってました。{性别:お兄さん|お姉さん}はこの街で一番すごい月狩り人で、それにすごく優しいって。お願い……助けてあげてください！",
          DialogueId = 51009604,
          GUID = "7FB27B28",
          NextDialogue = 51009605,
          SpeakNpcId = 700303
        },
        [51009605] = {
          ContentJP = "病気って……お医者さんには診てもらった？",
          DialogueId = 51009605,
          GUID = "7FB27B52",
          NextDialogue = 51009606,
          SpeakNpcId = 100001
        },
        [51009606] = {
          ContentJP = "はい……でも、もう手の施しようがないって……",
          DialogueId = 51009606,
          GUID = "7FB27B7C",
          NextDialogue = 51009607,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Disagree"
          }
        },
        [51009607] = {
          ContentJP = "僕のお金、全部あげます。足りないなら、どんなことでもしますから……！",
          DialogueId = 51009607,
          GUID = "7FB27BA6",
          SpeakNpcId = 700303
        },
        [51009608] = {
          ContentJP = "そのドナートって人、今どこに？",
          DialogueId = 51009608,
          GUID = "7FB27BD0",
          NextDialogue = 51009609,
          SpeakNpcId = 100001
