          DialogueId = 51009663,
          GUID = "7FB284D6",
          NextDialogue = 51009664,
          SpeakNpcId = 100001
        },
        [51009664] = {
          Camera = "201.632812,149.822754,39.556641,0.000044,-1.60086,173.405228,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ああ……そうだったな。戻ろうか。",
          DialogueId = 51009664,
          GUID = "7FB28500",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009665] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ドナートおじさん、帰ってきてくれたんだね！",
          DialogueId = 51009665,
          GUID = "7FB2852A",
          NextDialogue = 51009666,
          SpeakNpcId = 700303,
          TurnTo = {
            [1] = "700303:n(700301)",
            [2] = "700301:n(700303)",
            [3] = "100001:n(700303)"
          }
        },
        [51009666] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "すまないな、心配かけたね……ゴホッ、ゴホッ……",
          DialogueId = 51009666,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB28554",
          NextDialogue = 51009667,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009667] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "また咳が……！すぐにお医者さんに行こう！",
          DialogueId = 51009667,
          GUID = "7FB2857E",
          NextDialogue = 51009668,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Talk02_Start"
          }
        },
        [51009668] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "いや、いいんだ……これは、俺が背負うべき報いなんだ。治るもんじゃないさ。",
          DialogueId = 51009668,
          GUID = "7FB285A8",
          NextDialogue = 51009669,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700303:Talk02_End"
          }
        },
        [51009669] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "またそんなこと言って……",
          DialogueId = 51009669,
          GUID = "7FB285D2",
          NextDialogue = 51009670,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Confident_Start"
          }
        },
        [51009670] = {
          ContentJP = "覚えてないの？あの冬、寒さが厳しくてさ、僕は工場の排気管のそばで暖を取ってたんだ。おじさんも寒さで震えてたのに、自分のたった一着のコートをぼくにくれたじゃないか！",
          DialogueId = 51009670,
          GUID = "7FB285FC",
          NextDialogue = 51009671,
          SpeakNpcId = 700303
        },
        [51009671] = {
          ContentJP = "この通りにいる人なら、誰だって知ってる。おじさんがどれだけ優しい人かをね。そんな人が、「報い」なんて言葉を口にするのおかしいよ！",
          DialogueId = 51009671,
          GUID = "7FB28626",
          LookAt = {
            [1] = "100001:n(700301)"
          },
          NextDialogue = 51009672,
          SpeakNpcId = 700303
        },
        [51009672] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……その「報い」って、もしかして昔のことと関係があるの？",
          DialogueId = 51009672,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28650",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextDialogue = 51009673,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start",
            [2] = "700301:Explain02_End"
          }
        },
        [51009673] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……ああ、十六年前の話さ。",
          DialogueId = 51009673,
          FacialId = {
            [1] = "700301:CM_Sad01"
          },
          GUID = "7FB2867A",
          NextDialogue = 51009674,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_Start",
            [2] = "700303:Confident_End"
          }
        },
        [51009674] = {
          Camera = "51.153076,68.407227,128.048828,0.000057,-5.000518,-77.201683,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "たわいのない人生だった。鉱夫として働いてたあの頃は、良くも悪くもない、ただの毎日だった。精一杯働いて、家族を養う。それだけだった。",
          DialogueId = 51009674,
          GUID = "7FB286A4",
          NextDialogue = 51009675,
          SpeakNpcId = 700301
        },
        [51009675] = {
          ContentJP = "今思えば、抗えぬ存在に理不尽に扱われながらも……あの頃の方が、ずっと心は穏やかだったかもしれない。",
          DialogueId = 51009675,
          GUID = "7FB286CE",
          NextDialogue = 51009676,
          SpeakNpcId = 700301
        },
        [51009676] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "でも、俺の親友、シグには……過酷すぎる現実があった。彼の妹――ヴェルレッタが、若くして重い病にかかったんだ。まだ十八だったのに。",
          DialogueId = 51009676,
          GUID = "7FB286F8",
          NextDialogue = 51009677,
          SpeakNpcId = 700301
        },
        [51009677] = {
          ContentJP = "しかも状況は悪化するばかりだった。",
          DialogueId = 51009677,
          GUID = "7FB28722",
          NextDialogue = 51009678,
          SpeakNpcId = 700301
        },
        [51009678] = {
          ContentJP = "鉱山から採れる月ノ石は日に日に減り、給料も雀の涙。最初は白パンだったのが黒パンに変わり、しまいには木くず入りの代用品だ。",
          DialogueId = 51009678,
          GUID = "7FB2874C",
          NextDialogue = 51009679,
          SpeakNpcId = 700301
        },
        [51009679] = {
          ContentJP = "病を抱えるヴェルレッタにとって、それは「死ね」って言われるも同然だった。",
          DialogueId = 51009679,
          GUID = "7FB28776",
          NextDialogue = 51009680,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009680] = {
          ContentJP = "覚えてるよ――あの夜明け前、安酒をかき集めて、ふたりで鉱山の前の岩に腰かけてさ、何も言わずに酒を流し込んだ。",
          DialogueId = 51009680,
          GUID = "7FB287A0",
          NextDialogue = 51009681,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk01_Start"
          }
        },
        [51009681] = {
          ContentJP = "シグは泣いてた。情けないくらい泣きながら、妹との思い出を語ってた。ときどきヴェルレッタの真似して歌ってみたり、ファブリス・ルスフォードの名前をボロカスに罵ったりしてな。",
          DialogueId = 51009681,
          GUID = "7FB287CA",
          NextDialogue = 51009682,
          SpeakNpcId = 700301
        },
        [51009682] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ファブリス・ルスフォードって？",
          DialogueId = 51009682,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB287F4",
          NextDialogue = 51009683,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start",
            [2] = "700301:Talk01_End"
          }
        },
        [51009683] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ああ、当時鉱山を仕切ってた工学錬金院のお偉いさんだ。",
          DialogueId = 51009683,
          GUID = "7FB2881E",
          NextDialogue = 51009684,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_Start"
          }
        },
        [51009684] = {
          ContentJP = "で、俺は……あいつの肩を叩いて、酔った勢いでこう言ってしまったんだ。「文句ばっか言いな。ほんとに腹立ってんなら、あの野郎をさらって一発かましてやりゃいいだろ」って。",
          DialogueId = 51009684,
          GUID = "7FB28848",
          NextDialogue = 51009685,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Talk02_End"
          }
        },
        [51009685] = {
          ContentJP = "……あの夜、余計なことさえ言わなけりゃ……いまだに考えるよ。俺の一言がなきゃ、あんなことにはならなかったんじゃないかってな。",
          DialogueId = 51009685,
          GUID = "7FB28872",
          NextDialogue = 51009686,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009686] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "まさか、そのシグおじさんって……",
          DialogueId = 51009686,
          GUID = "7FB2889C",
          NextDialogue = 51009687,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700301:Explain02_End"
          },
          TurnTo = {
            [1] = "700301:n(700303)"
          }
        },
        [51009687] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ああ……ある日突然、鉱山を辞めちまってさ。俺が家に行ったときには、もうシグもヴェルレッタも姿を消してた。",
          DialogueId = 51009687,
          GUID = "7FB288C6",
          NextDialogue = 51009688,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009688] = {
          ContentJP = "最初は、どっか治療に行ったんだろうと思った。……でも、一週間後に届いた手紙が、全てをひっくり返した。",
          DialogueId = 51009688,
          GUID = "7FB288F0",
          NextDialogue = 51009689,
          SpeakNpcId = 700301
        },
        [51009689] = {
          ContentJP = "ヴェルレッタからの手紙だったよ。俺とシグは長いつきあいだけど、彼女とはほとんど会ったことがなかった。それでも、最後の持ち金を使って、旅する月狩り人に託してくれたんだ。",
          DialogueId = 51009689,
          GUID = "7FB2891A",
          NextDialogue = 51009690,
          SpeakNpcId = 700301
        },
        [51009690] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "「兄が長官の娘をさらった。どうか止めてください」――そう書いてあった。",
          DialogueId = 51009690,
          GUID = "7FB28944",
          NextDialogue = 51009691,
          SpeakNpcId = 700301
        },
        [51009691] = {
          ContentJP = "その子を閉じ込めてたのは、街はずれの古い家だった。俺が乗り込んだとき、シグは驚いてたけど……しばらくして、観念したようにうなずいた。",
          DialogueId = 51009691,
          GUID = "7FB2896E",
          NextDialogue = 51009692,
          SpeakNpcId = 700301
        },
        [51009692] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "全部、俺のせいだ。あの夜の言葉が、あいつの背中を押してしまったんだ。悔しかったよ……たまらなく。止めなきゃいけなかった。でも、何も言えなかった。そばにいたヴェルレッタが、あまりにも弱ってて……声も出せないくらいだったから。",
          DialogueId = 51009692,
          GUID = "7FB28998",
          NextDialogue = 51009693,
          SpeakNpcId = 700301
        },
        [51009693] = {
          ContentJP = "シグは「なかったことにしてくれ」と言った。でも、捜索はどんどん厳しくなってたし、俺は怖くなって……震えて、寝ても覚めてもあのことばかり考えてた。",
          DialogueId = 51009693,
          GUID = "7FB289C2",
          NextDialogue = 51009694,
          SpeakNpcId = 700301
        },
        [51009694] = {
          ContentJP = "そして、俺は――",
          DialogueId = 51009694,
          GUID = "7FB289EC",
          NextDialogue = 51009695,
          SpeakNpcId = 700301
        },
        [51009695] = {
          Camera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……告発した？",
          DialogueId = 51009695,
          GUID = "7FB28A16",
          NextDialogue = 51009696,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_End"
          },
          TurnTo = {
            [1] = "700301:n(100001)"
          }
        },
        [51009696] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ああ……やってしまった。やるべきじゃなかったんだ。",
          DialogueId = 51009696,
          GUID = "7FB28A40",
          NextDialogue = 51009697,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009697] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "それで……二人は？",
          DialogueId = 51009697,
          GUID = "7FB28A6A",
          LookAt = {
            [1] = "700301:n(700303)"
          },
          NextDialogue = 51009698,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700301:Sigh_End"
          }
        },
        [51009698] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "帝国軍の長官が自ら乗り込んできた。シグは必死に抵抗したけど、そのときうっかり火がついてしまってね。",
          DialogueId = 51009698,
          GUID = "7FB28A94",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009699,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_Start"
          }
        },
        [51009699] = {
          ContentJP = "俺は必死で中に飛び込んだ。ヴェルレッタだけは……なんとか助け出した。顔中すすまみれで、涙の跡だけがくっきりと黒をぬぐってた……",
          DialogueId = 51009699,
          GUID = "7FB28ABE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009700,
          SpeakNpcId = 700301
        },
        [51009700] = {
          ContentJP = "彼女が兄に巻き込まれるのが怖くて、水桶に隠して、帝国軍の目をかいくぐった。",
          DialogueId = 51009700,
          GUID = "7FB28AE8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023101.T_Story_Recall_20023101'",
          NextDialogue = 51009701,
          SpeakNpcId = 700301
        },
        [51009701] = {
          ContentJP = "結局、シグは捕まって……長官の娘は、焼け跡から炭になった遺体で見つかった。",
          DialogueId = 51009701,
          GUID = "7FB28B12",
          NextDialogue = 51009702,
          SpeakNpcId = 700301
        },
        [51009702] = {
          ContentJP = "怒り狂った長官は、裁判もせずに、シグをその場で処刑した。俺は懸賞金をすべてヴェルレッタに渡して、混乱に紛れて街の外に逃した。",
          DialogueId = 51009702,
          GUID = "7FB28B3C",
          NextDialogue = 51009703,
          SpeakNpcId = 700301
        },
        [51009703] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "去り際の彼女の顔、今でも忘れられないよ。やつれてたけど、目だけは怒ってた。あのときつけてたのが――この紫色のリボンだ。",
          DialogueId = 51009703,
          GUID = "7FB28B66",
          NextDialogue = 51009704,
          SpeakNpcId = 700301
        },
        [51009704] = {
          ContentJP = "彼女は言ったよ。「もう二度と、あなたの顔は見たくない」ってね。",
          DialogueId = 51009704,
          GUID = "7FB28B90",
          NextDialogue = 51009705,
          SpeakNpcId = 700301
        },
        [51009705] = {
          Camera = "12.182617,54.006836,128.048828,0.000051,-5.600557,-66.002014,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……そりゃそうだ。友を道連れにして、その妹を地獄に落として、罪の後始末にすら失敗した臆病者に、誰が会いたいと思うよ。",
          DialogueId = 51009705,
          FinalCamera = "-115.218262,-202.711914,123.809082,0.000057,-5.200553,24.798326,30.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB28BBA",
          LookAt = {
            [1] = "700301:n(100001)"
          },
          NextOptions = {
            [1] = 510095461,
            [2] = 510095462
          },
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain02_End"
          }
        },
        [51009706] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……そうだね。君の言うとおりだ。",
          DialogueId = 51009706,
          GUID = "7FB28BE4",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Agree"
          }
        },
        [51009707] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "そうだよ、ドナートおじさんは……ちゃんとできることをやっただけだよ！",
          DialogueId = 51009707,
          GUID = "7FB28C0E",
          NextDialogue = 51009708,
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700303:Angry01_Start"
          }
        },
        [51009708] = {
          Camera = "78.660156,141.991211,123.371582,0.000067,-4.400513,-84.600342,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "そんなふうに言ってくれる人もいたよ、これまでに。でもな……二人の命が消えちまったって事実は、どうやっても変えられない。",
          DialogueId = 51009708,
          GUID = "7FB28C38",
          NextDialogue = 51009709,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Disagree",
            [2] = "700303:Angry01_End"
          }
        },
        [51009709] = {
          ContentJP = "あの事件のあと、俺は重い病にかかった。死にかけてさ……そのときから、何かが変わった。とにかく人に尽くそうと思った。ひとつでも多くの善いことをすれば、あのときの罪を少しは清算できるんじゃないかって。",
          DialogueId = 51009709,
          GUID = "7FB28C62",
          NextDialogue = 51009710,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Explain01_Start"
          }
        },
        [51009710] = {
          Camera = "-21.725342,235.385742,212.564453,0.000078,-22.799852,-68.394066,20.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "でもね……夜になると、夢に出てくるんだ。俺を睨みつけるシグと、炎の中で泣き叫ぶあの娘――エノラの姿が。「どれだけ生者を助けたって、死者はお前を許さない」ってさ……",
          DialogueId = 51009710,
          GUID = "7FB28C8C",
          NextDialogue = 51009711,
          SpeakNpcId = 700301
        },
        [51009711] = {
          ContentJP = "ヴェルレッタ……君も、そうなんだろう？戻ってきたのは、俺を裁くためなのか？",
          DialogueId = 51009711,
          GUID = "7FB28CB6",
          NextDialogue = 51009712,
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Disagree"
          }
        },
        [51009712] = {
          ContentJP = "この罪人の命を――刈るために……",
          DialogueId = 51009712,
          GUID = "7FB28CE0",
          SpeakNpcId = 700301,
          TalkActionId = {
            [1] = "700301:Sigh_Start"
          }
        },
        [51009713] = {
          ContentJP = "ドナートの声がかすれ、そしてその場に崩れ落ちる",
          DialogueId = 51009713,
          GUID = "7FB28D0A"
        },
        [51009714] = {
          Camera = "564.476807,-378.041016,169.732422,0.00009,-13.999387,141.803299,30.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "おじさん！ドナートおじさん！",
          DialogueId = 51009714,
          GUID = "7FB28D34",
          NextDialogue = 51009715,
          Scripts = [[
