}
}]],
          SpeakNpcId = 700303,
          TalkActionId = {
            [1] = "700301:Onground02"
          }
        },
        [51009715] = {
          ContentJP = "……ふう、よかった。気を失っただけみたいだ。体力も精神も、限界だったんだよ。目を離さない方がいい。これ以上無理させちゃいけない。",
          DialogueId = 51009715,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB28D5E",
          LookAt = {
            [1] = "700303:n(100001)"
          },
          NextDialogue = 51009716,
          SpeakNpcId = 100001,
          TalkActionId = {
