        },
        [51009716] = {
          Camera = "489.740967,-276.444336,121.044434,0.000018,-7.20046,148.799316,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "うん、みんな呼んで、おじさんのそばについてるよ！",
          DialogueId = 51009716,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28D88",
