        },
        [51009720] = {
          Camera = "174.810547,-35.033203,84.850098,0.000033,-4.400117,168.992874,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "{性别:お兄さん|お姉さん}がそう思うなら、きっとそうなんだね。ありがとう……これ、僕からのお礼！すっごい貯めたんだから！",
          DialogueId = 51009720,
          GUID = "7FB28E30",
          NextDialogue = 51009721,
          SpeakNpcId = 700303,
          TalkActionId = {
