        [51009721] = {
          Camera = "34.74585,-46.004883,96.84375,0.000042,-1.400134,16.193537,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "（あの紫色のリボン……どうやら、あれはヴェルレッタがシグの墓に手向けたものらしい。）",
          DialogueId = 51009721,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB28E5A",
          NextDialogue = 51009722,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009722] = {
          ContentJP = "（十八だったあの子も、今はもう立派な大人だ……もしかして、今もこの街に？時間があれば、探してみようかな……）",
          DialogueId = 51009722,
          GUID = "7FB28E84",
          Scripts = "PlayOrStopBGM{_delay{10},PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 100001
        },
        [51009723] = {
          Camera = "-1245.721924,-374.627869,402.247803,-8.001631,-17.80077,20.798534,23.337744,100000.0,true,DoNotOverride,2.8",
          ContentJP = "眠れぬ……安らかに眠れぬ……！",
          DialogueId = 51009723,
          FinalCamera = "-1026.618896,-291.636963,327.767822,-8.001973,-14.000665,19.198555,23.337744,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB28EAE",
          NextDialogue = 51009724,
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023200"}},
PlayFacial{ActorId{100001},FacialId{"Angry01"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          ToFinalCameraBlendTime = 3
        },
        [51009724] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentJP = "哀れな人よ、あなたも私と同じなのでしょう？凍てつく回廊の中、胸を焦がし、愛と希望の星をじっと見上げているのでは……",
          DialogueId = 51009724,
          GUID = "7FB28ED8",
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009725] = {
          ContentJP = "街角から歌声が聞こえる。あたりを見回しても、歌声の主は見当たらない……もう少し探してみる？",
          DialogueId = 51009725,
          GUID = "7FB28F02"
        },
        [51009726] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ダッ……ダダッ……",
          DialogueId = 51009726,
          FacialId = {
            [1] = "100001:Shock01"
          },
          GUID = "7FB28F2C",
          NextDialogue = 51009727,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "100001:Shock_Start"
          }
        },
        [51009727] = {
          ContentJP = "誰？",
          DialogueId = 51009727,
          GUID = "7FB28F56",
          NextDialogue = 51009728,
          SpeakNpcId = 100001
        },
        [51009728] = {
          ContentJP = "あら、ごめんなさい。驚かせちゃった？私はここよ、あと五歩前に出てみて。そう、こっち。",
          DialogueId = 51009728,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB28F80",
          NextDialogue = 51009729,
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "100001:Shock_End"
          }
        },
        [51009729] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentJP = "こんばんは、眠れぬ夜を過ごす旅人さん。",
          DialogueId = 51009729,
          GUID = "7FB28FAA",
          NextOptions = {
            [1] = 510096391,
            [2] = 510096392,
            [3] = 510096393
          },
          Scripts = [[
SEQ{
MoveTo{ActorId{100001},MoveSpeed{150},TargetPoint{"NvzhuPoint_20023201"}},
TurnTo{TurnToDescription{"100001:n(700309)"}}
}]],
          SpeakNpcId = 700309,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009730] = {
          ContentJP = "そう、あなたは今、まさに箱と会話しているのよ。",
          DialogueId = 51009730,
          GUID = "7FB28FD4",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009731] = {
          ContentJP = "なぜそう決めつけるの？お喋りする箱がいても、不思議はないでしょう？",
          DialogueId = 51009731,
          GUID = "7FB28FFE",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009732] = {
          ContentJP = "残念、私はただの箱。願いを叶える力なんて持ってないの。",
          DialogueId = 51009732,
          GUID = "7FB29028",
          NextDialogue = 51009733,
          SpeakNpcId = 700309
        },
        [51009733] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "でも、どうして箱が喋るの？",
          DialogueId = 51009733,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29052",
          NextDialogue = 51009734,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009734] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentJP = "どうしてって聞かれても……歌うのと話すの、どっちが難しいと思う？",
          DialogueId = 51009734,
          GUID = "7FB2907C",
          NextDialogue = 51009735,
          SpeakNpcId = 700309
        },
        [51009735] = {
          ContentJP = "……歌かな。",
          DialogueId = 51009735,
          GUID = "7FB290A6",
          NextDialogue = 51009736,
          SpeakNpcId = 100001
        },
        [51009736] = {
          ContentJP = "なら、ゼンマイを巻けば歌い出すオルゴールは？歌えるのに、言葉は話せない……って、不思議じゃない？私はそれよりちょっと大きくて、ちょっと賢いだけ。",
          DialogueId = 51009736,
          GUID = "7FB290D0",
          NextDialogue = 51009737,
          SpeakNpcId = 700309
        },
        [51009737] = {
          ContentJP = "だからこうして、あなたと話せるのよ。",
          DialogueId = 51009737,
          GUID = "7FB290FA",
          NextDialogue = 51009738,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009738] = {
          ContentJP = "でも……",
          DialogueId = 51009738,
          GUID = "7FB29124",
          NextDialogue = 51009739,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009739] = {
          ContentJP = "うん、わかってる。まだ信じられないんでしょ？",
          DialogueId = 51009739,
          GUID = "7FB2914E",
          NextDialogue = 51009740,
          SpeakNpcId = 700309
        },
        [51009740] = {
          ContentJP = "「箱が喋るなんて変だ」ってよく言われるわ。でも、もしその箱が、誰かの声に応えてくれるなら……どう？ちょっとだけ、話してみたくならない？",
          DialogueId = 51009740,
          GUID = "7FB29178",
          NextDialogue = 51009741,
          SpeakNpcId = 700309
        },
        [51009741] = {
          ContentJP = "それに、あなた……私をすぐに開けたり壊したりしなかった。つまり少しだけでも、私とお喋りしたいって思ったんじゃない？",
          DialogueId = 51009741,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB291A2",
          NextDialogue = 51009742,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Explain01_End"
          }
        },
        [51009742] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "…………",
          DialogueId = 51009742,
          GUID = "7FB291CC",
          NextDialogue = 51009743,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009743] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ふふ、少しは納得してくれたみたいね。じゃあ、少しだけお話ししましょう。",
          DialogueId = 51009743,
          GUID = "7FB291F6",
          NextDialogue = 51009744,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51009744] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "何の話したいの？",
          DialogueId = 51009744,
          FacialId = {
            [1] = "100001:Uninterested01"
          },
          GUID = "7FB29220",
          NextDialogue = 51009745,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009745] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentJP = "そうね、たとえば……二日前のオペラ劇場の演目の話とか。どう？",
          DialogueId = 51009745,
          GUID = "7FB2924A",
          NextDialogue = 51009746,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009746] = {
          ContentJP = "『プティニー』って作品、観たことある？あのヒロインの歌声、どうだった？",
          DialogueId = 51009746,
          GUID = "7FB29274",
          NextDialogue = 51009747,
          SpeakNpcId = 700309
        },
        [51009747] = {
          ContentJP = "私は箱だから、劇場に入ることもできなくて……",
          DialogueId = 51009747,
          GUID = "7FB2929E",
          NextDialogue = 51009748,
          SpeakNpcId = 700309
        },
        [51009748] = {
          Camera = "258.270447,-156.542389,96.182617,0.000091,-4.999384,138.403717,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ごめん、観てないや。",
          DialogueId = 51009748,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB292C8",
          NextDialogue = 51009749,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:DisagreeHead"
          }
        },
        [51009749] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentJP = "いいの、責めたりしないわ。でも、もし機会があったら、観てほしいな。彼女はとても美しくて、優しくて――そして何より、「自由を求める」勇気を持っていたの。",
          DialogueId = 51009749,
          GUID = "7FB292F2",
          NextDialogue = 51009750,
          SpeakNpcId = 700309
        },
        [51009750] = {
          ContentJP = "私も、彼女みたいになりたい。でも……私はただの木箱でしかない。",
          DialogueId = 51009750,
          GUID = "7FB2931C",
          NextDialogue = 51009751,
          SpeakNpcId = 700309
        },
        [51009751] = {
          ContentJP = "だから、決めたの。",
          DialogueId = 51009751,
          GUID = "7FB29346",
          NextDialogue = 51009752,
          SpeakNpcId = 700309
        },
        [51009752] = {
          ContentJP = "何を？",
          DialogueId = 51009752,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29370",
          NextDialogue = 51009753,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02_Start"
          }
        },
        [51009753] = {
          Camera = "693.018372,159.482361,393.903809,0.000131,-25.999353,-158.378677,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentJP = "遠くへ旅に出ようと思うの。木箱は角に積まれるだけじゃない、船にもなれる。波に乗って、潮風を受けて……大海原を漂ってみたい。",
          DialogueId = 51009753,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2939A",
          NextDialogue = 51009754,
          SpeakNpcId = 700309,
          TalkActionId = {
            [1] = "100001:Talk02_End"
          }
        },
        [51009754] = {
          ContentJP = "でも、ここを離れたら、今あるすべてを失ってしまう。",
          DialogueId = 51009754,
          GUID = "7FB293C4",
          NextDialogue = 51009755,
          SpeakNpcId = 700309
        },
        [51009755] = {
          ContentJP = "「檻」を捨てるってことは、「居場所」を捨てることになる。「自由」を得るってことは、「不安」を受け入れることになる。",
          DialogueId = 51009755,
          GUID = "7FB293EE",
          NextDialogue = 51009756,
          SpeakNpcId = 700309
        },
        [51009756] = {
          Camera = "165.608704,156.288574,79.068604,0.000101,-0.599274,-97.799728,13.284671,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ねえ、あなたなら……どうする？",
          DialogueId = 51009756,
          GUID = "7FB29418",
          NextOptions = {
            [1] = 510096661,
            [2] = 510096662
          },
          SpeakNpcId = 700309
        },
        [51009757] = {
          ContentJP = "……たしかに、そうかもね。",
          DialogueId = 51009757,
          GUID = "7FB29442",
          NextDialogue = 51009758,
          SpeakNpcId = 700309
        },
        [51009758] = {
          ContentJP = "ありがとう。こんな夜に、箱と話してくれたあなたは、きっと優しい人。もうすぐ夜明けよ。朽ち木の魔法は、朝には消えてしまうの。",
          DialogueId = 51009758,
          GUID = "7FB2946C",
          NextDialogue = 51009759,
          SpeakNpcId = 700309
        },
        [51009759] = {
          ContentJP = "眠れぬ夜を過ごすことがあっても……いいえ。あなたが毎晩、安らかな夢に包まれますように。",
          DialogueId = 51009759,
          GUID = "7FB29496",
          SpeakNpcId = 700309
        },
        [51009760] = {
          ContentJP = "小さな震えが聞こえる。\nまるで夜明け前、子どもの枕元から妖精がそっと姿を消すみたいに――\n気づけば、箱の姿は消えていた。",
          DialogueId = 51009760,
          GUID = "7FB294C0"
        },
        [51009761] = {
          Camera = "181.495728,-78.722099,88.629395,0.000093,-3.999294,136.804047,30.022871,100000.0,true,DoNotOverride,2.8",
          ContentJP = "（さっきの……なんとなく、流れで話してしまったけど……）",
          DialogueId = 51009761,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB294EA",
          NextDialogue = 51009762,
          SpeakNpcId = 100001,
