        },
        [51009762] = {
          Camera = "-5654.617676,-3244.824707,4837.760742,0.000161,-38.599369,19.822903,27.283031,100000.0,true,DoNotOverride,2.8",
          ContentJP = "（もしかしたら、近所の子がイタズラしてたのかも？少し聞き込みをしてみようかな。）",
          DialogueId = 51009762,
          GUID = "7FB29514",
          SpeakNpcId = 100001
        },
        [51009763] = {
          ContentJP = "あの……誰？さっきからうちの周りをウロウロして……",
          DialogueId = 51009763,
          GUID = "7FB2953E",
          NextDialogue = 51009764,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009764] = {
          ContentJP = "もしかして依頼？人探し？それとも素材集め？なんでも受けるけど、ちゃんと合法の範囲でね。",
          DialogueId = 51009764,
          GUID = "7FB29568",
          NextDialogue = 51009765,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009765] = {
          ContentJP = "……依頼？",
          DialogueId = 51009765,
          GUID = "7FB29592",
          NextDialogue = 51009766,
          SpeakNpcId = 100001
        },
        [51009766] = {
          ContentJP = "えっ、違うの？依頼しに来たんじゃないの？",
          DialogueId = 51009766,
          GUID = "7FB295BC",
          NextDialogue = 51009767,
          SpeakNpcId = 700302,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51009767] = {
          ContentJP = "なーんだ、じゃあ「狩月人ジゼル」もまだまだってことか。カミラめ、大げさなこと言っちゃって。",
          DialogueId = 51009767,
          GUID = "7FB295E6",
          NextDialogue = 51009768,
          SpeakNpcId = 700302
        },
        [51009768] = {
          ContentJP = "狩月人ジゼル……どこかで聞いたような……",
          DialogueId = 51009768,
          GUID = "7FB29610",
          NextDialogue = 51009769,
          SpeakNpcId = 100001
        },
        [51009769] = {
          ContentJP = "別に、気を遣わなくていいのよ。",
          DialogueId = 51009769,
          GUID = "7FB2963A",
          NextDialogue = 51009770,
          SpeakNpcId = 700302
        },
        [51009770] = {
          ContentJP = "いや、本当に……",
          DialogueId = 51009770,
          GUID = "7FB29664",
          NextDialogue = 51009771,
          SpeakNpcId = 100001
        },
        [51009771] = {
          ContentJP = "ジゼルに裏口の箱の話を伝えた。",
          DialogueId = 51009771,
          GUID = "7FB2968E",
          NextDialogue = 51009772
        },
        [51009772] = {
          ContentJP = "箱が喋った？しかもオペラを勧めてきたって？……なるほどね。",
          DialogueId = 51009772,
          GUID = "7FB296B8",
          NextDialogue = 51009773,
          SpeakNpcId = 700302
        },
        [51009773] = {
          ContentJP = "……",
          DialogueId = 51009773,
          GUID = "7FB296E2",
          NextDialogue = 51009774,
          SpeakNpcId = 100001
        },
        [51009774] = {
          ContentJP = "もっと驚くかと思ったけど……",
          DialogueId = 51009774,
          GUID = "7FB2970C",
          NextDialogue = 51009775,
          SpeakNpcId = 100001
        },
        [51009775] = {
          ContentJP = "あら、そう？私ってそういうタイプなのかも。子どもの悪ふざけにしろ、本当に箱が喋ったにしろ、私にとっては、どちらもありうることだと思うし、受け入れられるわ。",
          DialogueId = 51009775,
          GUID = "7FB29736",
          NextDialogue = 51009776,
          SpeakNpcId = 700302
        },
        [51009776] = {
          ContentJP = "教えてくれてありがとう。この辺で、少し聞いて回ってみるわ。",
          DialogueId = 51009776,
          GUID = "7FB29760",
          NextDialogue = 51009777,
          SpeakNpcId = 700302
        },
        [51009777] = {
          ContentJP = "あ、そうそう、思い出した。あなた、{nickname}よね？月狩り人の中でも最近評判になってる新人の。",
          DialogueId = 51009777,
          GUID = "7FB2978A",
          NextOptions = {
            [1] = 510096871,
            [2] = 510096872,
            [3] = 510096873
          },
          SpeakNpcId = 700302
        },
        [51009778] = {
          ContentJP = "やっぱり。私の目もまだ衰えてないみたいね。",
          DialogueId = 51009778,
          GUID = "7FB297B4",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009779] = {
          ContentJP = "そんなに警戒しなくても。腕の立つ新人はすぐに話題になるものよ。",
          DialogueId = 51009779,
          GUID = "7FB297DE",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009780] = {
          ContentJP = "そのネーミング、センスはさておき……印象には残るわね。",
          DialogueId = 51009780,
          GUID = "7FB29808",
          NextDialogue = 51009781,
          SpeakNpcId = 700302
        },
        [51009781] = {
          ContentJP = "ところで、ヒマにしてるのなら、ちょっと頼んでもいいかしら？",
          DialogueId = 51009781,
          GUID = "7FB29832",
          NextDialogue = 51009782,
          SpeakNpcId = 700302
        },
        [51009782] = {
          ContentJP = "薬草を集めてきてほしいの。種類と数はメモにして渡すわ。揃ったら「アスフォデロス」に置いておいて。報酬はカミラに預けておくから。",
          DialogueId = 51009782,
          GUID = "7FB2985C",
          NextDialogue = 51009783,
          SpeakNpcId = 700302
        },
        [51009783] = {
          ContentJP = "ここに直接届けなくていいの？",
          DialogueId = 51009783,
          GUID = "7FB29886",
          NextDialogue = 51009784,
          SpeakNpcId = 100001
        },
        [51009784] = {
          ContentJP = "ええ、大丈夫。アスフォデロスに置いといて。",
