          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009787] = {
          ContentJP = "（……それに、今思い返すと、彼女の様子もどこか変だった。）",
          DialogueId = 51009787,
          GUID = "7FB2992E",
          NextDialogue = 51009788,
          SpeakNpcId = 100001
        },
        [51009788] = {
          ContentJP = "（とにかく、アスフォデロスに戻ってカミラに話を聞いてみようかな。）",
          DialogueId = 51009788,
          GUID = "7FB29958",
          SpeakNpcId = 100001
        },
        [51009789] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "こんにちは。飲みにきたの？それとも依頼の確認かしら？",
          DialogueId = 51009789,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29982",
          NextDialogue = 51009790,
          SpeakNpcId = 200003
        },
        [51009790] = {
          ContentJP = "いえ、荷物を届けに来ました。ジゼルからの依頼で、ここに届けてって言われて。",
          DialogueId = 51009790,
          GUID = "7FB299AC",
          NextDialogue = 51009791,
          SpeakNpcId = 100001
        },
        [51009791] = {
          ContentJP = "ジゼル？ああ、確かに少し前に来てたわね。あなたに渡してほしいって荷物をひとつ預かったけど……なんか、ちょっと引っかかるのよね。その依頼の内容って、どんなものだったの？",
          DialogueId = 51009791,
