          NextDialogue = 51009795,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009795] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "依頼そのものは別に変じゃない。けどね……なんでそんな内容を、わざわざ人に頼むのかって話よ。",
          DialogueId = 51009795,
          GUID = "7FB29A7E",
          NextDialogue = 51009796,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "100001:Talk01_End"
          }
        },
        [51009796] = {
          ContentJP = "見たところ、風邪や寒気に効くような、ごくありふれた薬草ばかり。彼女なら、自分で少し歩けばすぐに採ってこられる。わざわざ他人に頼むほどのものじゃないわ。",
          DialogueId = 51009796,
          GUID = "7FB29AA8",
          NextDialogue = 51009797,
          SpeakNpcId = 200003
        },
        [51009797] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "そういえば、本人も「月狩り人」だって言ってましたね。",
          DialogueId = 51009797,
          GUID = "7FB29AD2",
          NextDialogue = 51009798,
          SpeakNpcId = 100001
        },
        [51009798] = {
          Camera = "-263.901001,-18.859375,168.283203,0.000002,-5.799807,9.398898,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ええ。彼女昔、警備部隊にいたのよ。十六年前、ある事件の判決で上層部と揉めて、部隊を離れてね。それから月狩り人になった。頭の回転も速いし、動きもいい。界隈ではちょっと名の知れた人よ。",
          DialogueId = 51009798,
          GUID = "7FB29AFC",
          NextDialogue = 51009799,
          SpeakNpcId = 200003
        },
        [51009799] = {
          ContentJP = "ま、過去の話はこれくらいにしましょう。依頼自体に問題はないし、彼女からも前もって連絡はもらってるからね。",
          DialogueId = 51009799,
          FacialId = {
            [1] = "200003:None"
          },
          GUID = "7FB29B26",
          NextDialogue = 51009800,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk03_End"
          }
        },
        [51009800] = {
          ContentJP = "これは彼女があなたに残したものよ。受け取ってちょうだい。",
          DialogueId = 51009800,
          GUID = "7FB29B50",
          NextDialogue = 51009801,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Give"
          }
        },
        [51009801] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……これは、依頼の報酬？それと手紙……？",
          DialogueId = 51009801,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB29B7A",
          SpeakNpcId = 100001
        },
        [51009802] = {
          ContentJP = "こんにちは、親愛なる友よ。夜遅くまで、あんな突飛な箱の話し相手になってくれてありがとう。そして、私が旅立つ勇気を持てたのは、あなたのおかげです。きっと、こんなやり方は友人や師匠に対して不誠実だと思われるかもしれません。でも、彼女たちなら、きっと私の選択を理解してくれると信じています。この広い世界のどこかで、またきっと舞台を通じて再会できるはずだから。それから――ジゼルを責めないでください。これは私自身の意思です。私の身勝手が、どうか誰にも迷惑をかけませんように。あっ、そういえば……まだ、あなたに自分の名前を言ってませんでしたね。でも、その名前はもう、使わないつもりです。そうですね――もし、いつか「プティニー」という名の娘に出会ったら……どうか、私だと気づいてください。私もきっと、あなたを見つけてみせますから。",
          DialogueId = 51009802,
          Duration = 10,
          GUID = "7FB29BA4"
        },
        [51009803] = {
          Camera = "-670.438599,-35.56543,192.935547,0.000003,-7.599917,-2.401886,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……なんだか、風変わりな知り合いができたみたいね。でも、悪くない話だと思うわ。",
          DialogueId = 51009803,
          FacialId = {
            [1] = "200003:Smile01"
          },
          GUID = "7FB29BCE",
          NextDialogue = 51009804,
          SpeakNpcId = 200003,
          TalkActionId = {
            [1] = "200003:Talk02_Start"
          }
        },
        [51009804] = {
          Camera = "-172.41748,71.862305,163.089844,0.000016,-8.200038,-114.998413,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "いや……正直、まだ何が起きたのかよくわかってなくて……",
          DialogueId = 51009804,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB29BF8",
