          ContentJP = "（あの箱の中にいた子が、本当に舞台に立てなかった役者だとしたら……）",
          DialogueId = 51009817,
          GUID = "7FB29E1A",
          NextDialogue = 51009818,
          SpeakNpcId = 100001
        },
        [51009818] = {
          ContentJP = "（ジゼルは、最初からそれを知ってた？……ここで考えてても仕方ない。もう一度、ジゼルに会いに行ってみよう。）",
          DialogueId = 51009818,
          GUID = "7FB29E44",
          SpeakNpcId = 100001
        },
        [51009819] = {
          Camera = "-459.554443,-130.776611,223.984375,0.000025,-13.400024,3.198126,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "だから、俺は最初から反対だったんだ！",
          DialogueId = 51009819,
          FacialId = {
            [1] = "700307:CM_Angry01"
          },
          GUID = "7FB29E6E",
          NextDialogue = 51009820,
          SpeakNpcId = 700307,
          TalkActionId = {
            [1] = "700307:Angry01_Start"
          }
        },
        [51009820] = {
          ContentJP = "あんな素性の知れない女を家庭教師に雇うべきじゃなかった！ロザリンに歌唱なんて教えさせるんじゃなかったんだ！",
          DialogueId = 51009820,
          GUID = "7FB29E98",
          NextDialogue = 51009821,
          SpeakNpcId = 700307
        },
        [51009821] = {
          ContentJP = "でも、家で一日中ウロウロするよりマシだって、あなたが言ったんじゃない！",
          DialogueId = 51009821,
          FacialId = {
            [1] = "700308:CM_Sad01"
          },
          GUID = "7FB29EC2",
          NextDialogue = 51009822,
          SpeakNpcId = 700308,
          TalkActionId = {
            [1] = "700308:Explain01_Start"
          }
        },
        [51009822] = {
          ContentJP = "言ったさ、でもそれは「おとなしく家にいてほしい」からだろうが！結果的に、外に出る口実ができて、あの子が誘拐犯に狙われたんだぞ！",
          DialogueId = 51009822,
          GUID = "7FB29EEC",
          NextDialogue = 51009823,
          SpeakNpcId = 700307,
          TalkActionId = {
            [1] = "700307:Angry01_End",
            [2] = "700308:Explain01_End"
          }
        },
        [51009823] = {
          ContentJP = "それにお前ら、警備部隊もそうだ！やっとここまでたどり着いたのに、そののろまっぷり、犯人を取り逃がすとは何事だ！",
          DialogueId = 51009823,
          GUID = "7FB29F16",
