          GUID = "7FB2A10E",
          NextDialogue = 51009836,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51009836] = {
          ContentJP = "（誘拐事件……？もしかして、アスフォデロスで受け取ったあの手紙と関係がある？）",
          DialogueId = 51009836,
          GUID = "7FB2A138",
          NextDialogue = 51009837,
          SpeakNpcId = 100001
        },
        [51009837] = {
          ContentJP = "（今は他に手がかりもないし……周囲をもっと慎重に確認しよう。）",
          DialogueId = 51009837,
          GUID = "7FB2A162",
          SpeakNpcId = 100001
        },
        [51009838] = {
