          SpeakNpcId = 100001
        },
        [51009854] = {
          ContentJP = "（もしこの推理が正しければ、もうジゼルはヴィオレッタさんと会っているはず。）",
          DialogueId = 51009854,
          GUID = "7FB2A42C",
          NextDialogue = 51009855,
          SpeakNpcId = 100001
        },
        [51009855] = {
          ContentJP = "（あの手紙に書かれていた場所――急がなきゃ。どうか、無事でいて……）",
          DialogueId = 51009855,
          GUID = "7FB2A456",
