        },
        [51009856] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,true,Manual,2.8",
          ContentJP = "時間道理ね。",
          DialogueId = 51009856,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2A480",
          NextDialogue = 51009857,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009857] = {
          ContentJP = "……",
          DialogueId = 51009857,
          GUID = "7FB2A4AA",
          NextDialogue = 51009858,
          SpeakNpcId = 700300
        },
        [51009858] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,true,DoNotOverride,2.8",
          ContentJP = "だんまりを続けるつもり？あいにくだけど――私は裁判官じゃないの。「黙秘権」なんて、私には通用しないわよ。",
          DialogueId = 51009858,
          GUID = "7FB2A4D4",
          NextDialogue = 51009859,
          SpeakNpcId = 700302
        },
        [51009859] = {
          ContentJP = "……それで？私に何を言わせたいの？まずはあなたの言い分を聞かせて。こんな卑劣なやり方で、どんな答えが欲しいのかしら？",
          DialogueId = 51009859,
          FacialId = {
            [1] = "700300:CM_Angry01"
          },
          GUID = "7FB2A4FE",
          NextDialogue = 51009860,
          SpeakNpcId = 700300
        },
        [51009860] = {
          Camera = "148.300781,-316.230469,157.037598,0.999999,-5.400179,115.588638,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "とぼけるつもり？それとも、自分のやったことを、その厚塗り化粧のように隠せると思ってるのかしら？",
          DialogueId = 51009860,
          GUID = "7FB2A528",
          NextDialogue = 51009861,
          SpeakNpcId = 700302
        },
        [51009861] = {
          ContentJP = "……いいわ、ここで思い出させてあげる。",
          DialogueId = 51009861,
          GUID = "7FB2A552",
          NextDialogue = 51009862,
          SpeakNpcId = 700302
        },
        [51009862] = {
          Camera = "-1404.640625,-280.359375,849.211426,0.00002,-23.200226,22.597872,35.0,100000.0,true,Manual,2.8",
          ContentJP = "16年前、アイスレイク城で起きた誘拐事件。とある若者シグが、グルビューム鉱山の責任者ファブリス・ルスフォードの娘――エノラ・ルスフォードを誘拐した。",
          DialogueId = 51009862,
          GUID = "7FB2A57C",
          NextDialogue = 51009863,
          SpeakNpcId = 700302
        },
        [51009863] = {
          ContentJP = "その逃走中、彼は火事を起こし、エノラは焼死。シグは死刑判決を受けた。",
          DialogueId = 51009863,
          GUID = "7FB2A5A6",
          NextDialogue = 51009864,
          SpeakNpcId = 700302
        },
        [51009864] = {
          Camera = "-314.688477,142.042969,142.037598,1.000012,-0.599793,-21.008369,40.559872,100000.0,true,DoNotOverride,2.8",
          ContentJP = "その古い事件なら聞いたことがあるわ。……実に悲劇だったわ。",
          DialogueId = 51009864,
          GUID = "7FB2A5D0",
          NextDialogue = 51009865,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51009865] = {
          ContentJP = "でも私は数年前にアイスレイク城へ来たばかり。その事件と私に、何の関係があるのかしら？",
          DialogueId = 51009865,
          GUID = "7FB2A5FA",
          NextDialogue = 51009866,
          SpeakNpcId = 700300
        },
        [51009866] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,true,DoNotOverride,2.8",
          ContentJP = "あるのよ。あの火事には――生き残りがいた。",
          DialogueId = 51009866,
          GUID = "7FB2A624",
          NextDialogue = 51009867,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Explain02_End"
          }
        },
        [51009867] = {
          ContentJP = "ある知人から聞いたの。現場にはシグとエノラ以外に、もう一人いたと。シグの妹――ヴェルレッタ。エノラと同じ年頃の少女だそうよ。",
          DialogueId = 51009867,
          GUID = "7FB2A64E",
          NextDialogue = 51009868,
          SpeakNpcId = 700302
        },
        [51009868] = {
          ContentJP = "その混乱の中、あの知人はヴェルレッタを助け出したと言っていた……いいえ、正確には、そうだと<H>思い込んでいた</>というべきかしら。",
          DialogueId = 51009868,
          GUID = "7FB2A678",
          NextDialogue = 51009869,
          SpeakNpcId = 700302
        },
        [51009869] = {
          ContentJP = "そうでしょう？――16年前、ヴェルレッタを殺して彼女に成りすました、エノラ・ルスフォード！",
          DialogueId = 51009869,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A6A2",
          NextDialogue = 51009870,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009870] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……フフ、なかなか面白い推理劇じゃない。",
          DialogueId = 51009870,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2A6CC",
          NextDialogue = 51009871,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Angry01_End"
          }
        },
        [51009871] = {
          ContentJP = "好みのジャンルだわ。続けて。",
          DialogueId = 51009871,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2A6F6",
          NextDialogue = 51009872,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51009872] = {
          Camera = "-357.697266,-104.112305,130.897461,0.99998,-2.799988,24.192202,24.205383,100000.0,true,DoNotOverride,2.8",
          ContentJP = "あの事件はずっと私の中で引っかかってた。焼け焦げた遺体、ひとりだけ生き延びた少女……どうにも出来すぎてる。",
          DialogueId = 51009872,
          GUID = "7FB2A720",
          NextDialogue = 51009873,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009873] = {
          ContentJP = "接点はいくつもあった。でも線がなかったのよ。すべてを繋ぐ糸が。",
          DialogueId = 51009873,
          GUID = "7FB2A74A",
          NextDialogue = 51009874,
          SpeakNpcId = 700302
        },
        [51009874] = {
          ContentJP = "――でも、私がかつて警備部隊としてファブリスの護衛をしたとき、偶然聞いたことがあるの。あの娘の歌声をね。",
          DialogueId = 51009874,
          GUID = "7FB2A774",
          NextDialogue = 51009875,
          SpeakNpcId = 700302
        },
        [51009875] = {
          Camera = "-220.682617,16.6875,142.309082,1.000003,-2.999962,-14.610696,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "そこでようやく、あんたとあの事件が結びついた。ねぇ、「千面のヴィオレッタ」。",
          DialogueId = 51009875,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2A79E",
          NextDialogue = 51009876,
          SpeakNpcId = 700302
        },
        [51009876] = {
          ContentJP = "その後もいろいろ調査したわ。信頼できる相手を使って、手紙を届けさせたり――あんたの生活パターンを探ったりね。",
          DialogueId = 51009876,
          GUID = "7FB2A7C8",
          NextDialogue = 51009877,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Explain01_Start"
          }
        },
        [51009877] = {
          ContentJP = "……あの衛兵、あなたの差し金だったのね。",
          DialogueId = 51009877,
          GUID = "7FB2A7F2",
          NextDialogue = 51009878,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk01_Start",
            [2] = "700302:Explain01_End"
          }
        },
        [51009878] = {
          ContentJP = "いいえ、彼は本当にあんたのファンよ。ただ、少し焚きつけてみただけ。それで確信が持てたわ。",
          DialogueId = 51009878,
          GUID = "7FB2A81C",
          NextDialogue = 51009879,
          SpeakNpcId = 700302
        },
        [51009879] = {
          Camera = "127.291016,-233.679688,146.983398,1.000008,-1.000206,118.987587,38.469608,100000.0,true,DoNotOverride,2.8",
          ContentJP = "けど、ひとつだけわからないことがあるの。",
          DialogueId = 51009879,
          GUID = "7FB2A846",
          NextDialogue = 51009880,
          SpeakNpcId = 700302
        },
        [51009880] = {
          ContentJP = "あの火事でどうやってヴェルレッタと入れ替わったの？協力なしには無理なはず。",
          DialogueId = 51009880,
          GUID = "7FB2A870",
          NextDialogue = 51009881,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700300:Talk01_End",
            [2] = "700302:Think_Start"
          }
        },
        [51009881] = {
          Camera = "-294.663086,168.334961,176.219727,1.000005,-6.799897,-27.606359,56.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "何かと思えば……そんなこと？",
          DialogueId = 51009881,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A89A",
          NextDialogue = 51009882,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start",
            [2] = "700302:Think_End"
          }
        },
        [51009882] = {
          ContentJP = "私はファブリスの娘よ。あの男の気性を知っていれば、どれだけ危険か分かるでしょう？",
          DialogueId = 51009882,
          GUID = "7FB2A8C4",
          NextDialogue = 51009883,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009883] = {
          ContentJP = "シグは初めから、命を捨てる覚悟だった。でも、あの父のことだから、ヴェルレッタだって無事では済まない。",
          DialogueId = 51009883,
          GUID = "7FB2A8EE",
          NextDialogue = 51009884,
          SpeakNpcId = 700300
        },
        [51009884] = {
          ContentJP = "だから私は言ったの。唯一の手は、身代金を受け取ったあとできるだけ時間を稼いでって、その間に彼女を逃がすとね。",
          DialogueId = 51009884,
          GUID = "7FB2A918",
          NextDialogue = 51009885,
          SpeakNpcId = 700300
        },
        [51009885] = {
          ContentJP = "――笑えるでしょう？パニックになった彼は、本当に警備部隊を足止めしに行ったのよ。重病の少女が、火事の中を逃げ切れると信じて。",
          DialogueId = 51009885,
          GUID = "7FB2A942",
          NextDialogue = 51009886,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009886] = {
          ContentJP = "私はその隙をついた。あの子を殺して、彼女の名前を奪ったの。あの崩れかけの家も、父親の束縛も、すべてから自由になるために。",
          DialogueId = 51009886,
          GUID = "7FB2A96C",
          NextDialogue = 51009887,
          SpeakNpcId = 700300
        },
        [51009887] = {
          Camera = "96.022461,-329.655273,121.388672,0.999973,0.800034,107.991287,33.074104,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……",
          DialogueId = 51009887,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2A996",
          NextDialogue = 51009888,
          SpeakNpcId = 700302
        },
        [51009888] = {
          ContentJP = "どうしたの？十数年追い続けて、やっと真相にたどり着いたってのに、なんだか浮かない顔ね、ジゼルさん？",
          DialogueId = 51009888,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2A9C0",
          NextDialogue = 51009889,
          SpeakNpcId = 700300
        },
        [51009889] = {
          ContentJP = "信じられない……たったそれだけの理由で？二人も殺しておいて、何とも思わないの？",
          DialogueId = 51009889,
          GUID = "7FB2A9EA",
          NextDialogue = 51009890,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009890] = {
          ContentJP = "で、どうするの？ヴィオレッタの正体を暴いて私の評判を地に落とす？それとも……この場で仇を討つつもり？",
          DialogueId = 51009890,
          GUID = "7FB2AA14",
          NextDialogue = 51009891,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Confident_Start"
          }
        },
        [51009891] = {
          ContentJP = "……元はただ、真実を明らかにして、あんたを警備部隊に突き出すつもりだった。",
          DialogueId = 51009891,
          GUID = "7FB2AA3E",
          NextDialogue = 51009892,
          SpeakNpcId = 700302
        },
        [51009892] = {
          ContentJP = "ジゼルが腰から短剣を抜いた。その目に浮かぶ怒りは、握った柄を軋ませる音すら聞こえるようだった。",
          DialogueId = 51009892,
          GUID = "7FB2AA68",
          IsBlack = 1,
          NextDialogue = 51009893,
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009893] = {
          ContentJP = "このままでは――ヴィオレッタの喉を裂く血の一閃が、次の瞬間に訪れるだろう。誰もが望まない惨劇が、すぐそこにあった。",
          DialogueId = 51009893,
          GUID = "7FB2AA69",
          IsBlack = 1
        },
        [51009894] = {
          ContentJP = "{nickname}？あなた……なぜここに？",
          DialogueId = 51009894,
          GUID = "7FB2AABC",
          NextDialogue = 51009895,
          SpeakNpcId = 700300
        },
        [51009895] = {
          ContentJP = "どきなさい！こんな外道、絶対に許さない！",
          DialogueId = 51009895,
          GUID = "7FB2AAE6",
          NextDialogue = 51009896,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009896] = {
          ContentJP = "（ジゼル、怒りで我を忘れている……なんとか、落ち着かせないと。）",
          DialogueId = 51009896,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2AB10",
          SpeakNpcId = 100001
        },
        [51009897] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "落ち着いて、ジゼル。もしかしたら、まだ何か見落としてるかもしれない。",
          DialogueId = 51009897,
          GUID = "7FB2AB3A",
          NextDialogue = 51009898,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009898] = {
          ContentJP = "……今のあの女の言葉、聞いてなかったの！？どうしてそれで落ち着けるっていうのよ！",
          DialogueId = 51009898,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2AB64",
          NextDialogue = 51009899,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_Start"
          }
        },
        [51009899] = {
          ContentJP = "でも、現状彼女はもう逃げられない。だったらせめて、少しだけでも話をさせてくれない？",
          DialogueId = 51009899,
          GUID = "7FB2AB8E",
          NextDialogue = 51009900,
          SpeakNpcId = 100001
        },
        [51009900] = {
          Camera = "157.706055,-54.485352,141.052246,0.0001,-1.599849,150.594193,53.202648,100000.0,true,DoNotOverride,2.8",
          ContentJP = "…………",
          DialogueId = 51009900,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2ABB8",
          NextDialogue = 51009901,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Angry01_End"
          }
        },
        [51009901] = {
          ContentJP = "……いいわ。話して。",
          DialogueId = 51009901,
          GUID = "7FB2ABE2",
          NextDialogue = 51009902,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk03_Start",
            [2] = "100001:Talk02R_End"
          },
          TurnTo = {
            [1] = "100001:n(700300)",
            [2] = "700300:n(100001)"
          }
        },
        [51009902] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "その前に、ヴィオレッタさん。これを見て、何か思い出しませんか？",
          DialogueId = 51009902,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Image/Guide/T_Guide_ChapterFire_Ribbon02.T_Guide_ChapterFire_Ribbon02'}",
          GUID = "7FB2AC0C",
          NextDialogue = 51009903,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Give"
          }
        },
        [51009903] = {
          ContentJP = "それは……",
          DialogueId = 51009903,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2AC36",
          NextDialogue = 51009904,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          }
        },
        [51009904] = {
          ContentJP = "ヴィオレッタは思わず後頭部へ手を伸ばす。そこに触れた馴染みの感触に、彼女は動きを止めた。",
          DialogueId = 51009904,
          GUID = "7FB2AC60",
          NextDialogue = 51009905,
          Scripts = "PlayOrStopBGM{PlayType{\"Play\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}"
        },
        [51009905] = {
          ContentJP = "その様子を見るに、やっぱり……このリボン、シグの墓前に供えたのは、あなただよね？",
          DialogueId = 51009905,
          GUID = "7FB2AC8A",
          NextDialogue = 51009906,
          SpeakNpcId = 100001
        },
        [51009906] = {
          ContentJP = "あなた、言ってたよね。「これは親友の形見で、その子の夢を叶えるために舞台に立った」と。",
          DialogueId = 51009906,
          GUID = "7FB2ACB4",
          NextDialogue = 51009907,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "700300:Sigh_End"
          }
        },
        [51009907] = {
          ContentJP = "……ふふ、なんてお人好しなのかしら。あんなクサい台詞、信じてたの？",
          DialogueId = 51009907,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2ACDE",
          NextDialogue = 51009908,
          SpeakNpcId = 700300
        },
        [51009908] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "信じたから、ドナートさんに頼んでこのリボンを借りて、調べたんだよ。",
          DialogueId = 51009908,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2AD08",
          NextDialogue = 51009909,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009909] = {
          ContentJP = "ドナートさんが教えてくれた――ヴェルレッタという少女のことを。貧しく、病弱だったけど、類まれな才能を持っていた。もし健康で裕福だったなら、きっと立派な劇作家になっていたって。",
          DialogueId = 51009909,
          GUID = "7FB2AD32",
          NextDialogue = 51009910,
          SpeakNpcId = 100001
        },
        [51009910] = {
          ContentJP = "彼女は命が尽きかけても、夢を諦めなかった。ベッドから起き上がれなくなっても、自分の作品を完成させようと筆を取り続けた。",
          DialogueId = 51009910,
          GUID = "7FB2AD5C",
          NextDialogue = 51009911,
          SpeakNpcId = 100001
        },
        [51009911] = {
          ContentJP = "世界一の俳優に、自分の作品を演じてもらう。自分の作品をアトラシア全土に届けたい――それが、彼女の願いだった。",
          DialogueId = 51009911,
          GUID = "7FB2AD86",
          NextDialogue = 51009912,
          SpeakNpcId = 100001
        },
        [51009912] = {
          ContentJP = "その作品の名は……",
          DialogueId = 51009912,
          GUID = "7FB2ADB0",
          NextDialogue = 51009913,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51009913] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……三幕劇『プティニー』。その後、同名の歌劇として再編されたわ。",
          DialogueId = 51009913,
          GUID = "7FB2ADDA",
          NextDialogue = 51009914,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009914] = {
          Camera = "233.676758,-71.671875,155.098145,0.000096,-6.00058,179.598373,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……気付いたようだね。もうこれ以上、嘘を重ねても意味はないと。",
          DialogueId = 51009914,
          GUID = "7FB2AE04",
          NextOptions = {
            [1] = 510098241,
            [2] = 510098242
          },
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:ConfidentLR_Start"
          }
        },
        [51009915] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……フフ、その通りね。どんな劇にも、終幕は必要だもの。",
          DialogueId = 51009915,
          GUID = "7FB2AE2E",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Agree"
          }
        },
        [51009916] = {
          Camera = "-62.486328,-300.395508,128.418945,0.000093,0.0,73.193901,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "あら……こんな場面で探偵劇の決まり文句とは。",
          DialogueId = 51009916,
          GUID = "7FB2AE58",
          NextDialogue = 51009917,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51009917] = {
          ContentJP = "でも、あなたのような観客ばかりなら、作家たちも脚本をもっと単純に書いてたでしょうね。",
          DialogueId = 51009917,
          GUID = "7FB2AE82",
          NextDialogue = 51009918,
          SpeakNpcId = 700300
        },
        [51009918] = {
          Camera = "167.182617,-305.451172,119.724609,0.000095,2.599987,124.794083,44.87347,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ちょっと待って。どういうこと？あんたたち……何を言ってるの？",
          DialogueId = 51009918,
          GUID = "7FB2AEAC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009919,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:ConfidentLR_End"
          },
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009919] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ジゼル、もしヴィオレッタさんが本当にヴェルレッタを使い捨ての駒としか見ていなかったなら、彼女の名を模した「ヴィオレッタ」なんて名乗るはずはない。",
          DialogueId = 51009919,
          GUID = "7FB2AED6",
          NextDialogue = 51009920,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk01_Start"
          }
        },
        [51009920] = {
          Camera = "-1216.617188,-202.104492,761.92041,0.000021,-23.200226,22.597822,35.0,100000.0,true,Manual,2.8",
          ContentJP = "16年前、シグはヴェルレッタの治療費を工面するため、エノラ・ルスフォード――今のヴィオレッタを誘拐した。",
          DialogueId = 51009920,
          FinalCamera = "-1418.189453,-286.000977,855.499756,0.000021,-23.200226,22.597822,35.0,100000.0,true,Manual,2.8",
          GUID = "7FB2AF00",
          NextDialogue = 51009921,
          SpeakNpcId = 100001,
          ToFinalCameraBlendTime = 10
        },
        [51009921] = {
          ContentJP = "その間に、エノラとヴェルレッタは知り合い、親友になった。",
          DialogueId = 51009921,
          GUID = "7FB2AF2A",
          NextDialogue = 51009922,
          SpeakNpcId = 100001
        },
        [51009922] = {
          ContentJP = "けれど……その幸福な時間は長く続かなかった。",
          DialogueId = 51009922,
          GUID = "7FB2AF54",
          NextDialogue = 51009923,
          SpeakNpcId = 100001
        },
        [51009923] = {
          ContentJP = "ヴェルレッタは自分の病状が末期であることに気づき、兄のシグに無理をさせたくない一心で、彼の親友――ドナートに手紙を書き、誘拐のことを伝えた。",
          DialogueId = 51009923,
          GUID = "7FB2AF7E",
          NextDialogue = 51009924,
          SpeakNpcId = 100001
        },
        [51009924] = {
          ContentJP = "ドナートはあなた、ジゼルのもとへ駆け込み、シグがエノラを攫ったことを告げた。でも、きっとその頃には――ヴェルレッタはもう……",
          DialogueId = 51009924,
          GUID = "7FB2AFA8",
          NextDialogue = 51009925,
          SpeakNpcId = 100001
        },
        [51009925] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……笑っちゃうでしょう。誘拐されたはずなのに、あの数日間は、私の人生で一番幸せな時間だった。",
          DialogueId = 51009925,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          FinalCamera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2AFD2",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009926,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          },
          ToFinalCameraBlendTime = 15
        },
        [51009926] = {
          ContentJP = "シグは私を傷つける気なんてなかったし、むしろ私にはほとんど関心を向けていなかった。ずっと落ち着きなく部屋を出入りしていたわ。",
          DialogueId = 51009926,
          GUID = "7FB2AFFC",
          NextDialogue = 51009927,
          SpeakNpcId = 700300
        },
        [51009927] = {
          ContentJP = "私は気づいていた。あの家にはもうひとりの少女がいたことに。彼女は、気分のいいときは、いつも鼻歌を歌っていた――",
          DialogueId = 51009927,
          GUID = "7FB2B026",
          NextDialogue = 51009928,
          SpeakNpcId = 700300
        },
        [51009928] = {
          ContentJP = "二人分の世話はよほど大変だったのでしょう。数日後、シグは私の縄を解いて、1階だけなら自由にしていいって言ったの。",
          DialogueId = 51009928,
          GUID = "7FB2B050",
          NextDialogue = 51009929,
          SpeakNpcId = 700300
        },
        [51009929] = {
          Camera = "-91.950195,124.576172,144.41748,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "シグが外に出かけるたびに、私はこっそり2階に上がり、彼女と会ってたの。彼女は物語を語り、私はそれを演じる。まるで……ふたりでひとつの劇を作っているみたいだったわ。",
          DialogueId = 51009929,
          GUID = "7FB2B07A",
          NextDialogue = 51009930,
          SpeakNpcId = 700300
        },
        [51009930] = {
          ContentJP = "「愛しき人よ、私のために泣かないで――この眠れぬ夜に、私は旅立つわ」",
          DialogueId = 51009930,
          GUID = "7FB2B0A4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009931,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009931] = {
          ContentJP = "「風よ、帆をふくらませて！私は櫂をとる――灯台が波間にきらめいて、月光が、ああ……なんて眩しいの！」",
          DialogueId = 51009931,
          GUID = "7FB2B0CE",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009932,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009932] = {
          ContentJP = "ありがとう、エノラ……すごく、すごく素敵だった……ふふ……私が思い描いてた『プティニー』そのものだよ……情熱的で、勇敢で、自由を求めて生きる……まさに、あなたのような子……",
          DialogueId = 51009932,
          GUID = "7FB2B0F8",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009933,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009933] = {
          ContentJP = "ありがとう！……いまのは、即興だったけどね。でも、知り合いにすごく腕のいい作曲家がいるの。名前はカヴァラドッシ。彼にお願いすれば、『プティニー』を歌劇にしてもらえるかもしれない！",
          DialogueId = 51009933,
          GUID = "7FB2B122",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009934,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009934] = {
          ContentJP = "……でも、私が歌うチャンスは、もうないと思う。",
          DialogueId = 51009934,
          GUID = "7FB2B14C",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009935,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009935] = {
          ContentJP = "私は十八歳になったわ。父が決めた結婚相手と二ヶ月後に式を挙げるの。相手は錬金院の若い士官なんですって。",
          DialogueId = 51009935,
          GUID = "7FB2B176",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009936,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009936] = {
          ContentJP = "この先の人生は、小さな部屋で飾り人形のように座って過ごすか、あの忌まわしいイコル液の瓶と一生付き合うかの二択でしょうね。",
          DialogueId = 51009936,
          GUID = "7FB2B1A0",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009937,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Anora"
        },
        [51009937] = {
          ContentJP = "……やだよ、それ……そんなの間違ってる……エノラには、ヒバリみたいな歌声があるのに……そんな狭い部屋にいるべきじゃない……あなたは……スポットライトに包まれた……舞台に立つべきよ……",
          DialogueId = 51009937,
          GUID = "7FB2B1CA",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009938,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009938] = {
          ContentJP = "歌を愛するすべての人は……誰でも舞台に立つ資格がある……種族も……貧富も……関係ない……",
          DialogueId = 51009938,
          GUID = "7FB2B1F4",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009939,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009939] = {
          ContentJP = "……私、兄さんに頼んでみる。あなたを逃がしてくれるよう……私は……もう、たぶん長くないけど……せめて『プティニー』の最後だけは……",
          DialogueId = 51009939,
          GUID = "7FB2B21E",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009940,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009940] = {
          ContentJP = "でも、エノラ……お願い……どうか舞台に立って……この物語を……私たちの『プティニー』を……世界に響かせて……",
          DialogueId = 51009940,
          GUID = "7FB2B248",
          GraphPath = "Texture2D'/Game/UI/Texture/Dynamic/Image/Story/Recall/T_Story_Recall_20023301.T_Story_Recall_20023301'",
          NextDialogue = 51009941,
          SpeakNpcId = 700300,
          SpeakNpcName = "UI_CMNpc_Name_Violet"
        },
        [51009941] = {
          ContentJP = "「歌を愛するすべての人は…誰でも舞台に立つ資格がある。種族も貧富も関係ない」それが、ヴェルレッタの遺した言葉。そして、私の座右の銘となったわ。",
          DialogueId = 51009941,
          GUID = "7FB2B272",
          NextDialogue = 51009942,
          SpeakNpcId = 700300
        },
        [51009942] = {
          ContentJP = "彼女が亡くなったあと――私は、憔悴しきったシグの前で、『プティニー』の最後の幕を歌ったの。そのとき、彼の目には驚きが浮かんでいた……ほんの少しだけ、消えかけた灰に火が灯ったようだった。",
          DialogueId = 51009942,
          GUID = "7FB2B29C",
          NextDialogue = 51009943,
          SpeakNpcId = 700300
        },
        [51009943] = {
          ContentJP = "私たちには、まだヴェルレッタに報いる道が残っている。彼女の喜び、悲しみ、希望、そして想い――すべてこの作品に込められている。私はこの作品を世界中に届けたい……できるはずだし、何より……そうしなければならない。",
          DialogueId = 51009943,
          GUID = "7FB2B2C6",
          NextDialogue = 51009944,
          SpeakNpcId = 700300
        },
        [51009944] = {
          ContentJP = "彼女も私も、舞台のために生まれた者。たとえ病が彼女の命を奪っても、私は彼女の魂と共に舞台に立つ。",
          DialogueId = 51009944,
          GUID = "7FB2B2F0",
          NextDialogue = 51009945,
          SpeakNpcId = 700300
        },
        [51009945] = {
          ContentJP = "つまり、あなたが父親の支配から逃れ、そしてヴェルレッタの願いを叶えるために――シグはこの芝居に協力した……ということだね。",
          DialogueId = 51009945,
          GUID = "7FB2B31A",
          NextDialogue = 51009946,
          SpeakNpcId = 100001
        },
        [51009946] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,true,DoNotOverride,2.8",
          ContentJP = "そんな……じゃあ、さっきまでのあの態度は何だったの……？",
          DialogueId = 51009946,
          FacialId = {
            [1] = "700302:CM_Shock01"
          },
          GUID = "7FB2B344",
          NextDialogue = 51009947,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Shock_Start"
          }
        },
        [51009947] = {
          ContentJP = "ジゼル、君は最初から「こうあってほしい」という答えを持って来た。生徒のロザリンを守るために、彼女は黙って従うしかなかったんだよ。",
          DialogueId = 51009947,
          GUID = "7FB2B36E",
          NextDialogue = 51009948,
          SpeakNpcId = 100001
        },
        [51009948] = {
          ContentJP = "え……",
          DialogueId = 51009948,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2B398",
          NextDialogue = 51009949,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Shock_End"
          }
        },
        [51009949] = {
          Camera = "-158.601562,204.59082,150.237305,0.000071,-3.199944,-50.20327,35.333332,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……ひとつだけ、お願いがあるの。私は逃げたりしない。だから、少しだけ……付き合ってくれない？",
          DialogueId = 51009949,
          GUID = "7FB2B3C2",
          NextOptions = {
            [1] = 510098591
          },
          Scripts = "PlayOrStopBGM{PlayType{\"Stop\"},SoundType{\"SOUND_BGM\"},EventPath{\"event:/bgm/cbt01/0036_story_renweidaozu\"}}",
          SpeakNpcId = 700300
        },
        [51009950] = {
          Camera = "173.006836,-16.306641,127.36377,0.000095,0.999769,158.194092,44.87347,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……いいわ。ただし、変な真似はしないで。",
          DialogueId = 51009950,
          GUID = "7FB2B3EC",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Agree"
          }
        },
        [51009951] = {
          Camera = "-257.950684,511.992188,553.037598,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ここはもう建て直されたけれど、私は今でも……当時の光景が浮かぶわ。",
          DialogueId = 51009951,
          FinalCamera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2B416",
          LookAt = {
            [1] = "100001:n(700300)",
            [2] = "700302:n(700300)"
          },
          NextDialogue = 51009952,
          SpeakNpcId = 700300,
          ToFinalCameraBlendTime = 5
        },
        [51009952] = {
          ContentJP = "ヴェルレッタ……また来たよ。私たちの作品と一緒にね。",
          DialogueId = 51009952,
          FacialId = {
            [1] = "700300:CM_Sad01"
          },
          GUID = "7FB2B440",
          LookAt = {
            [1] = "100001:n(700300)"
          },
          NextDialogue = 51009953,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain01_Start"
          }
        },
        [51009953] = {
          ContentJP = "ようやく誰かが、私たちの物語に気づいてくれたわ……けど、不思議と怖くはないの。むしろ……少しだけ、心が軽くなった気がする。ようやく言えるから――……あのときのこと、本当に……ごめんね。シグのことも。",
          DialogueId = 51009953,
          GUID = "7FB2B46A",
          NextDialogue = 51009954,
          SpeakNpcId = 700300
        },
        [51009954] = {
          ContentJP = "ヴィオレッタの指が、壁にそっと触れる。懐かしむように、何かを伝えるように。別れの時を感じ取ったからこそ、彼女は今日ここへ戻ってきたのだろう。",
          DialogueId = 51009954,
          GUID = "7FB2B494",
          NextDialogue = 51009955,
          TalkActionId = {
            [1] = "700300:Explain01_End"
          }
        },
        [51009955] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……こんなわがままを聞いてくれて、ありがとう。",
          DialogueId = 51009955,
          GUID = "7FB2B4BE",
          NextDialogue = 51009956,
          SpeakNpcId = 700300,
          TurnTo = {
            [1] = "700300:n(700302)"
          }
        },
        [51009956] = {
          ContentJP = "……つまり、ヴィオレッタさん。あなたが罪を背負ったのは――シグが処刑されたのが、計画外のことだったからだね？",
          DialogueId = 51009956,
          GUID = "7FB2B4E8",
          NextDialogue = 51009957,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Explain01_Start"
          }
        },
        [51009957] = {
          ContentJP = "……ファブリス・ルスフォード。あの男は冷酷非道な支配者だった。鉱山の労働者は飢え、警備部隊ですらその圧政に苦しめられていた。",
          DialogueId = 51009957,
          GUID = "7FB2B512",
          NextDialogue = 51009958,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree",
            [2] = "100001:Explain01_End"
          }
        },
        [51009958] = {
          Camera = "-412.794434,216.719727,171.631836,0.000165,-6.39514,-27.7768,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "娘である私にさえ、夢を認めず、自由を奪い、決められたレールの上で生きるよう、無理やり従わせた。",
          DialogueId = 51009958,
          FinalCamera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,true,DoNotOverride,2.8",
          GUID = "7FB2B53C",
          NextDialogue = 51009959,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_Start"
          },
          ToFinalCameraBlendTime = 10
        },
        [51009959] = {
          ContentJP = "――そんな父が、私の死を知った瞬間、すべての法を無視してシグを処刑した。どれほど自身の地位を危うくしても、私の仇を討つために。",
          DialogueId = 51009959,
          GUID = "7FB2B566",
          NextDialogue = 51009960,
          SpeakNpcId = 700300
        },
        [51009960] = {
          ContentJP = "私は考えた。逃げ延びたあとに、どうやって手紙を裁判所に届けるか――でも……まさか、あの父があんなに……",
          DialogueId = 51009960,
          GUID = "7FB2B590",
          NextDialogue = 51009961,
          SpeakNpcId = 700300
        },
        [51009961] = {
          ContentJP = "……お父さんは、あなたを愛していたのね……",
          DialogueId = 51009961,
          GUID = "7FB2B5BA",
          NextDialogue = 51009962,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk02_Start"
          }
        },
        [51009962] = {
          ContentJP = "……それでも私は、真実を告げることができなかった。ヒュペリアはただの始まり。彼女の物語を、もっと広く伝える必要があったから。私には、それを果たす責任があると思ったの。",
          DialogueId = 51009962,
          GUID = "7FB2B5E4",
          NextDialogue = 51009963,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Sigh_End",
            [2] = "700302:Talk02_End"
          }
        },
        [51009963] = {
          ContentJP = "でも、あなたが真実にたどり着いたとき、私は少し……救われた気がしたの。今は生徒もいる。才能ある子たちが育ってきている。彼らなら私の代わりに『プティニー』を、もっと遠くまで運んでくれるわ。",
          DialogueId = 51009963,
          GUID = "7FB2B60E",
          LookAt = {
            [1] = "700300:n(700302)"
          },
          NextDialogue = 51009964,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Talk02_Start"
          }
        },
        [51009964] = {
          ContentJP = "つまりあなたは、自ら罪を被ることで――シグにかけられた、冤罪の汚名を晴らしたいんだね。",
          DialogueId = 51009964,
          GUID = "7FB2B638",
          NextDialogue = 51009965,
          SpeakNpcId = 100001
        },
        [51009965] = {
          ContentJP = "……ジゼル、あなたと一緒に行くわ。でも条件がある――ロザリン・マグナスを、必ず無事に解放して。",
          DialogueId = 51009965,
          FacialId = {
            [1] = "700300:CM_Idle"
          },
          GUID = "7FB2B662",
          NextDialogue = 51009966,
          SpeakNpcId = 700300
        },
        [51009966] = {
          ContentJP = "これは私自身のためでもあるし、シグとヴェルレッタのためでもある。彼女を傷つけることは、絶対に許さない。",
          DialogueId = 51009966,
          GUID = "7FB2B68C",
          NextDialogue = 51009967,
          SpeakNpcId = 700300
        },
        [51009967] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……彼女はもう、アイスレイク城を出たわ。",
          DialogueId = 51009967,
          GUID = "7FB2B6B6",
          LookAt = {
            [1] = "100001:n(700302)"
          },
          NextDialogue = 51009968,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Talk01_Start",
            [2] = "700300:Talk02_End"
          }
        },
        [51009968] = {
          Camera = "-134.225342,69.999023,159.965332,0.000165,-6.39514,-27.776773,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……え？",
          DialogueId = 51009968,
          FacialId = {
            [1] = "700300:CM_Shock01"
          },
          GUID = "7FB2B6E0",
          NextDialogue = 51009969,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Shock_Start"
          }
        },
        [51009969] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          ContentJP = "あなたが教師として彼女の両親と関わっていたなら、ロザリンの置かれた状況も知っているはず。",
          DialogueId = 51009969,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2B70A",
          NextDialogue = 51009970,
          SpeakNpcId = 700302
        },
        [51009970] = {
          ContentJP = "籠の鳥が飛び立つためなら、自ら羽を折ることもいとわない――あんたと彼女、まったく同じね。",
          DialogueId = 51009970,
          GUID = "7FB2B734",
          NextDialogue = 51009971,
          SpeakNpcId = 700302
        },
        [51009971] = {
          ContentJP = "……つまり、最初から……私を騙してたのね。",
          DialogueId = 51009971,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2B75E",
          NextDialogue = 51009972,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Shock_End"
          }
        },
        [51009972] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          ContentJP = "まさか、あんたとあんなに親しい関係の者から「誘拐」の依頼が来るとは思ってなかったけどね。この偶然を利用させてもらっただけよ。",
          DialogueId = 51009972,
          GUID = "7FB2B788",
          NextDialogue = 51009973,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51009973] = {
          ContentJP = "どう？私の演技、なかなかのものでしょ？そろそろ舞台女優に転職でもしようかしら。",
          DialogueId = 51009973,
          GUID = "7FB2B7B2",
          NextDialogue = 51009974,
          SpeakNpcId = 700302
        },
        [51009974] = {
          Camera = "-204.130859,4.202148,148.053223,0.000166,-3.794798,6.829297,41.877083,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ジゼル、もう月狩り人はやめるの？",
          DialogueId = 51009974,
          FacialId = {
            [1] = "100001:Happy01"
          },
          GUID = "7FB2B7DC",
          NextDialogue = 51009975,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51009975] = {
          Camera = "214.642578,12.081055,146.839844,0.000166,-1.794707,-168.969223,41.877083,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ふふ、マグナス家のお嬢様が失踪したって、大騒ぎになってるし。しばらくは大人しくしてた方がいいかも。",
          DialogueId = 51009975,
          GUID = "7FB2B806",
          NextDialogue = 51009976,
          SpeakNpcId = 700302
        },
        [51009976] = {
          ContentJP = "ヴィオレッタに関しては……",
          DialogueId = 51009976,
          GUID = "7FB2B830",
