            [1] = "700302:Confident_Start"
          }
        },
        [51009991] = {
          Camera = "-156.373047,321.121094,390.135742,0.000167,-36.995567,-61.979073,17.27956,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ああ、そうだ――もしよかったら、二日後の公演を観に来てくれない？おふたりには特等席を用意するわ。",
          DialogueId = 51009991,
          GUID = "7FB2BAA6",
          NextDialogue = 51009992,
          SpeakNpcId = 700300
        },
        [51009992] = {
          ContentJP = "……公演？",
          DialogueId = 51009992,
          GUID = "7FB2BAD0",
          NextDialogue = 51009993,
          SpeakNpcId = 700302
        },
        [51009993] = {
          ContentJP = "ええ。『プティニー』よ。これはあの子のための「お別れの舞台」――彼女が一番愛した物語を、今こそ、世界に響かせたいの。",
          DialogueId = 51009993,
          GUID = "7FB2BAFA",
          NextDialogue = 51010006,
          SpeakNpcId = 700300
        },
        [51009994] = {
          Camera = "-62.87207,113.884766,154.009766,0.000172,-4.994904,-44.169758,41.877083,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……あなたの選んだ道も理解できます、ヴィオレッタさん。でも――亡くなった命が、ただ「人殺し」としてしか語られないなんて……あまりにも悲しすぎる。",
          DialogueId = 51009994,
          GUID = "7FB2BB24",
          LookAt = {
            [1] = "700300:n(100001)"
          },
          NextDialogue = 51009995,
          Scripts = [[
SEQ{
