}}]],
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010053] = {
          Camera = "-442.745117,136.447266,137.21167,0.000002,-3.200169,-35.40036,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ご、ごめんなさいっ！……どこかお怪我は？",
          DialogueId = 51010053,
          FacialId = {
            [1] = "700302:CM_Angry01"
          },
          GUID = "7FB2C4D2",
          NextDialogue = 51010054,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010054] = {
          ContentJP = "大丈夫。次は気をつけてね。",
          DialogueId = 51010054,
          GUID = "7FB2C4FC",
          NextDialogue = 51010055,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Shock_End",
            [2] = "700302:Angry01_End"
          }
        },
        [51010055] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "うん――ん？",
          DialogueId = 51010055,
          GUID = "7FB2C526",
          NextDialogue = 51010056,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "700305:Think_Start"
          }
        },
        [51010056] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……なにか、顔についてる？",
          DialogueId = 51010056,
          FacialId = {
            [1] = "100001:Unhappy01"
          },
          GUID = "7FB2C550",
          NextDialogue = 51010057,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk03_Start"
          }
        },
        [51010057] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ふふっ、なんでもないよ。薬草、ありがとね！あっ、遅れちゃう！",
          DialogueId = 51010057,
          FacialId = {
            [1] = "700305:CM_Happy01"
          },
          GUID = "7FB2C57A",
          NextDialogue = 51010058,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02",
          TalkActionId = {
            [1] = "700305:Think_End"
          }
        },
        [51010058] = {
          ContentJP = "薬草……？待って、これ落としたよ！",
          DialogueId = 51010058,
          GUID = "7FB2C5A4",
          NextDialogue = 51010059,
          Scripts = [[
SEQ{
MoveTo{ActorId{700305},TargetPoint{"RosalindPoint2_20023305"},MoveSpeed{250},Visibility{"Hide"}},
PlayAnimation{ActorId{100001},AnimationId{"Nvzhu_Story_StretchHand_Start"},Duration{1}}
}]],
          SpeakNpcId = 100001
        },
        [51010059] = {
          ContentJP = "――あげるっ！！",
          DialogueId = 51010059,
          GUID = "7FB2C5CE",
          NextDialogue = 51010060,
          SpeakNpcId = 700305,
          SpeakNpcName = "UI_CMNpc_Name_Rosalind02"
        },
        [51010060] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "はは、最近の若い子って、ほんとせっかち。",
          DialogueId = 51010060,
          GUID = "7FB2C5F8",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010061,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Nvzhu_Story_StretchHand_End"
          }
        },
        [51010061] = {
          ContentJP = "……刺繍がある。……あの子の名前、かな。",
          DialogueId = 51010061,
          FacialId = {
            [1] = "100001:Doubt01"
          },
          GUID = "7FB2C622",
          NextDialogue = 51010062,
          SpeakNpcId = 100001
        },
        [51010062] = {
          ContentJP = "……プティニー？",
          DialogueId = 51010062,
          GUID = "7FB2C64C",
          NextDialogue = 51010063,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010063] = {
          ContentJP = "「もし、いつか『プティニー』という名の娘に出会ったら……どうか、私だと気づいてください。私もきっと、あなたを見つけてみせますから」",
          DialogueId = 51010063,
          GUID = "7FB2C676",
          IsBlack = 1,
          NextDialogue = 51010064
        },
        [51010064] = {
          ContentJP = "何？急に笑って。",
          DialogueId = 51010064,
          FacialId = {
            [1] = "100001:Happy02"
          },
          GUID = "7FB2C6A0",
          NextDialogue = 51010065,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010065] = {
          ContentJP = "ふふ……ジゼルすらわからなかったんだね。千面なのは、ヴィオレッタさんだけじゃないみたい。",
          DialogueId = 51010065,
          GUID = "7FB2C6CA",
          NextDialogue = 51010066,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010066] = {
          ContentJP = "舞台はまだ終わらない。またどこかで、きっと会える。その日まで――よい旅を、物語の主役さん。",
          DialogueId = 51010066,
          GUID = "7FB2C6F4",
          IsBlack = 1,
          SpeakNpcId = 100001
        },
        [51010067] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……",
          DialogueId = 51010067,
          FacialId = {
            [1] = "100001:Sad01"
          },
          GUID = "7FB2C71E",
          NextDialogue = 51010068,
          SpeakNpcId = 100001
        },
        [51010068] = {
          ContentJP = "おはよう、{nickname}。どうしたの？なんだか元気ないわね。",
          DialogueId = 51010068,
          GUID = "7FB2C748",
          NextDialogue = 51010069,
          SpeakNpcId = 700300
        },
        [51010069] = {
          ContentJP = "ヴィオレッタさん……",
          DialogueId = 51010069,
          GUID = "7FB2C772",
          NextDialogue = 51010070,
          SpeakNpcId = 100001
        },
        [51010070] = {
          Camera = "-182.809326,149.35498,133.001709,0.000049,-0.999878,-49.996906,35.520077,340.13559,true,Manual,2.8",
          ContentJP = "あらあら、そんな顔しないの。引退するのは私のほうなのに、なぜあなたが落ち込むの。",
          DialogueId = 51010070,
          FacialId = {
            [1] = "700300:CM_Smile01"
          },
          GUID = "7FB2C79C",
          NextDialogue = 51010071,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Disagree"
          }
        },
        [51010071] = {
          ContentJP = "あなたは、自分の信念を貫いただけよ。誰だってそうするわ。重く受け止めなくていいの。――ちょっと家出娘を見つけてきたと思えばいいわ。",
          DialogueId = 51010071,
          GUID = "7FB2C7C6",
          NextDialogue = 51010072,
          SpeakNpcId = 700300
        },
        [51010072] = {
          Camera = "-257.685547,-253.308594,133.213379,0.000042,-0.199585,40.001606,38.587292,100000.0,true,DoNotOverride,2.8",
          ContentJP = "全員そろったようね？",
          DialogueId = 51010072,
          GUID = "7FB2C7F0",
          NextDialogue = 51010073,
          Scripts = "MoveTo{ActorId{700302},TargetPoint{\"GisellePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700302
        },
        [51010073] = {
          ContentJP = "ジゼルも来たのね。はい、あなたたちのチケットよ。",
          DialogueId = 51010073,
          GUID = "7FB2C81A",
          NextDialogue = 51010074,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Give"
          }
        },
        [51010074] = {
          ContentJP = "ありがたく受け取るわ。衛兵たちには話をつけてあるわよ。公演が終わるまでは動かないって。",
          DialogueId = 51010074,
          GUID = "7FB2C844",
          NextDialogue = 51010075,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010075] = {
          ContentJP = "感謝するわ。じゃあ私は、そろそろ舞台裏に行くわね。",
          DialogueId = 51010075,
          GUID = "7FB2C86E",
          NextDialogue = 51010076,
          SpeakNpcId = 700300,
          TalkActionId = {
            [1] = "700300:Explain02_Start"
          }
        },
        [51010076] = {
          ContentJP = "私たちも中に入りましょうか。私のせいとはいえ……ヴィオレッタの引退公演、少し楽しみではあるから。",
          DialogueId = 51010076,
          GUID = "7FB2C898",
          LookAt = {
            [1] = "100001:n(700302)",
            [2] = "700302:n(100001)"
          },
          NextDialogue = 51010077,
          SpeakNpcId = 700302
        },
        [51010077] = {
          ContentJP = "うん。",
          DialogueId = 51010077,
          GUID = "7FB2C8C2",
          SpeakNpcId = 100001
        },
        [51010078] = {
          ContentJP = "ヴィオレッタが用意してくれた席に腰かけ、そっと幕開けを待つ。",
          DialogueId = 51010078,
          GUID = "7FB2C8EC",
          NextDialogue = 51010079
        },
        [51010079] = {
          ContentJP = "やがて照明が落ち、力強く響く女声が幕の向こうから会場を包み込む。",
          DialogueId = 51010079,
          GUID = "7FB2C916",
          NextDialogue = 51010080
        },
        [51010080] = {
          ContentJP = "しんと静まり返る客席。慣れない空気に、少しだけそわそわする。",
          DialogueId = 51010080,
          GUID = "7FB2C940",
          NextDialogue = 51010081
        },
        [51010081] = {
          ContentJP = "声を漏らさないように気をつけていたけれど――",
          DialogueId = 51010081,
          GUID = "7FB2C96A",
          NextDialogue = 51010082
        },
        [51010082] = {
          ContentJP = "そんな心配は杞憂だった。",
          DialogueId = 51010082,
          GUID = "7FB2C994",
          NextDialogue = 51010083
        },
        [51010083] = {
          ContentJP = "気づけば息を飲み、拍手さえ忘れていた。舞台に心を奪われたまま、静かに幕が降りた――",
          DialogueId = 51010083,
          GUID = "7FB2C9BE"
        },
        [51010084] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "ジゼル、ちゃんと説明してもらおうか！",
          DialogueId = 51010084,
          FacialId = {
            [1] = "700304:CM_Angry01"
          },
          GUID = "7FB2C9E8",
          NextDialogue = 51010085,
          SpeakNpcId = 700304,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700304:Angry01_Start"
          }
        },
        [51010085] = {
          Camera = "-446.109863,-216.286133,176.425781,0.000133,-6.999605,41.589813,60.202423,100000.0,true,DoNotOverride,2.8",
          ContentJP = "あら？なんでもお見通しのファブリス様が、私なんかに説明を求めるとは。",
          DialogueId = 51010085,
          GUID = "7FB2CA12",
          NextDialogue = 51010086,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010086] = {
          ContentJP = "お前がヴィオレッタの正体がエノラだと通報したから来たというのに、舞台裏には誰もいなかった！",
          DialogueId = 51010086,
          GUID = "7FB2CA3C",
          NextDialogue = 51010087,
          SpeakNpcId = 700304
        },
        [51010087] = {
          ContentJP = "ああ、その件ね……わざわざ自ら足を運ぶとは、立派な長官様だこと。",
          DialogueId = 51010087,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2CA66",
          NextDialogue = 51010088,
          SpeakNpcId = 700302
        },
        [51010088] = {
          ContentJP = "皮肉はやめろ！命令だ、今すぐエノラの居場所を案内しろ！",
          DialogueId = 51010088,
          GUID = "7FB2CA90",
          NextDialogue = 51010089,
          SpeakNpcId = 700304
        },
        [51010089] = {
          ContentJP = "お忘れかしら？私はもう警備部隊の人間じゃないし、あなたも違う。ただの市民として、ちょっとした情報提供をしただけよ。",
          DialogueId = 51010089,
          FacialId = {
            [1] = "700302:CM_Idle"
          },
          GUID = "7FB2CABA",
          NextDialogue = 51010090,
          SpeakNpcId = 700302
        },
        [51010090] = {
          ContentJP = "だから、あなたの命令に従う義理はないわ。どうしてもと言うなら――「月狩り人ジゼル」に、正式に依頼でも出してみる？",
          DialogueId = 51010090,
          GUID = "7FB2CAE4",
          NextDialogue = 51010091,
          SpeakNpcId = 700302
        },
        [51010091] = {
          Camera = "-34.440796,-11.397461,144.465332,0.000003,0.80015,-179.606598,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "……出してやるよ、依頼でも何でも！",
          DialogueId = 51010091,
          GUID = "7FB2CB0E",
          NextDialogue = 51010092,
          SpeakNpcId = 700304,
          TalkActionId = {
            [1] = "700302:Confident_End"
          }
        },
        [51010092] = {
