          SpeakNpcId = 700302
        },
        [51010116] = {
          ContentJP = "あげるって言われても……",
          DialogueId = 51010116,
          FacialId = {
            [1] = "100001:Doubt01",
            [2] = "700302:CM_Idle"
          },
