          NextDialogue = 51010117,
          SpeakNpcId = 100001
        },
        [51010117] = {
          ContentJP = "勇敢な蝶は繭を破って羽ばたき、風に乗って消えていきました――まるで紫のスミレが、花の海へと溶け込むように。",
          DialogueId = 51010117,
          FacialId = {
            [1] = "100001:None"
          },
          GUID = "7FB2CF52",
          NextDialogue = 51010118,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"ViolettePoint_20023305\"},MoveSpeed{150},Visibility{\"Show\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010118] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "もうしばらく、彼女があなたの前に現れることはないでしょう。だからこそ、これは彼女から大切な友人への最後の贈り物です。",
          DialogueId = 51010118,
          GUID = "7FB2CF7C",
          LookAt = {
            [1] = "100001:n(700311)",
            [2] = "700302:n(700311)"
          },
          NextDialogue = 51010119,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010119] = {
          Camera = "-304.188965,-104.091309,139.379639,0.000002,-0.600189,4.199689,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "贈り物……刺繍がある……あの子の名前かな？",
          DialogueId = 51010119,
          GUID = "7FB2CFA6",
          NextDialogue = 51010120,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_Start"
          }
        },
        [51010120] = {
          ContentJP = "……プティニー？",
          DialogueId = 51010120,
          GUID = "7FB2CFD0",
          NextDialogue = 51010121,
          SpeakNpcId = 100001
        },
        [51010121] = {
          ContentJP = "「もし、いつか『プティニー』という名の娘に出会ったら……どうか、私だと気づいてください。私もきっと、あなたを見つけてみせますから」",
          DialogueId = 51010121,
          GUID = "7FB2CFFA",
          IsBlack = 1,
          NextDialogue = 51010122
        },
        [51010122] = {
          ContentJP = "そうか……箱の中のあの子、ちゃんと旅立てたんだね。ということは、あなたは……",
          DialogueId = 51010122,
          GUID = "7FB2D024",
          NextDialogue = 51010123,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Think_End"
          }
        },
        [51010123] = {
          Camera = "-77.586914,100.682129,157.737793,0.000019,-6.000089,-109.999786,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "しーっ。真相を暴いてくれたことは感謝してるけど、秘密を守れる子のほうが私は好きよ。",
          DialogueId = 51010123,
          GUID = "7FB2D04E",
          NextDialogue = 51010124,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700311:Disagree"
          }
        },
        [51010124] = {
          ContentJP = "そんなに堂々と正体バラして、また私に告発されるかもって思わないの？",
          DialogueId = 51010124,
          GUID = "7FB2D078",
          NextDialogue = 51010125,
          SpeakNpcId = 700302
        },
        [51010125] = {
          ContentJP = "「ヴィオレッタ」はもう舞台に立たない。けど私はしばらくここにいるつもりよ。あなたがまた私を告発しても、恨んだりはしないわ。でも、もうひとりの教え子のこと――どうしても放っておけなくてね。",
          DialogueId = 51010125,
          GUID = "7FB2D0A2",
          NextDialogue = 51010126,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010126] = {
          ContentJP = "……",
          DialogueId = 51010126,
          GUID = "7FB2D0CC",
          NextDialogue = 51010127,
          SpeakNpcId = 700302
        },
        [51010127] = {
          ContentJP = "……ありがとう。",
          DialogueId = 51010127,
          FacialId = {
            [1] = "700311:CM_Happy01"
          },
          GUID = "7FB2D0F6",
          NextDialogue = 51010128,
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "700311:Agree"
          }
        },
        [51010128] = {
          ContentJP = "それでは、素敵な休暇を。",
          DialogueId = 51010128,
          GUID = "7FB2D120",
          NextDialogue = 51010129,
          Scripts = "MoveTo{ActorId{700311},TargetPoint{\"RosalindPoint2_20023305\"},MoveSpeed{150},Visibility{\"Hide\"}}",
          SpeakNpcId = 700311,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [51010129] = {
          Camera = "-423.906006,-31.62793,121.737549,0.0,1.799973,0.000049,35.0,100000.0,true,DoNotOverride,2.8",
          ContentJP = "やっぱりね。あの女が大人しく捕まるわけないと思ってた。",
          DialogueId = 51010129,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D14A",
          LookAt = {
            [1] = "700302:n(100001)",
            [2] = "100001:n(700302)"
          },
          NextDialogue = 51010130,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "700302:Confident_Start"
          }
        },
        [51010130] = {
          ContentJP = "なんだか、うれしそう？",
          DialogueId = 51010130,
          GUID = "7FB2D174",
          NextDialogue = 51010131,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010131] = {
          ContentJP = "そう見える？……正直言うとね、生きてる人間の人生を犠牲にして、死者の名誉を守るってのは、悩んだわ。",
          DialogueId = 51010131,
          GUID = "7FB2D19E",
          NextDialogue = 51010132,
          SpeakNpcId = 700302,
          TalkActionId = {
            [1] = "100001:Talk02R_End"
          }
        },
        [51010132] = {
          ContentJP = "でも、私なりの答えを出した。これが、ジゼルの選んだ道よ。",
          DialogueId = 51010132,
          GUID = "7FB2D1C8",
          NextDialogue = 51010133,
          SpeakNpcId = 700302
        },
        [51010133] = {
          ContentJP = "それに――こうしてどちらも失わずに済んで、今、少しでもホッとしてるってことは……私も、この十六年で少しは成長できたってことかもね。",
          DialogueId = 51010133,
          FacialId = {
            [1] = "700302:CM_Sad01"
          },
          GUID = "7FB2D1F2",
          NextDialogue = 51010134,
          SpeakNpcId = 700302
        },
        [51010134] = {
          ContentJP = "十六年前も、今の私みたいに振る舞えてたら……誰も死なずに済んだのかなって、少し思っただけ。",
          DialogueId = 51010134,
          GUID = "7FB2D21C",
          NextDialogue = 51010135,
          SpeakNpcId = 700302
        },
        [51010135] = {
          ContentJP = "ジゼルのせいじゃないよ。",
          DialogueId = 51010135,
          FacialId = {
            [1] = "100001:Smile01"
          },
          GUID = "7FB2D246",
          NextDialogue = 51010136,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Disagree"
          }
        },
        [51010136] = {
          ContentJP = "大丈夫よ、落ち込んでるわけじゃないから。ただ――「月狩り人ジゼル」が休業になったから、次は何をしようかって考えてただけ。",
          DialogueId = 51010136,
          FacialId = {
            [1] = "700302:CM_Smile01"
          },
          GUID = "7FB2D270",
          NextDialogue = 51010137,
          SpeakNpcId = 700302
        },
        [51010137] = {
          ContentJP = "役者はもうやめるわ。ヴィオレッタの舞台を観てたら、なんだか恥ずかしくなっちゃった。",
          DialogueId = 51010137,
          GUID = "7FB2D29A",
          NextOptions = {
            [1] = 510100471,
            [2] = 510100472
          },
          SpeakNpcId = 700302
        },
        [51010138] = {
          ContentJP = "だって、儲かりそうじゃん。",
          DialogueId = 51010138,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D2C4",
          NextDialogue = 51010140,
          SpeakNpcId = 700302
        },
        [51010139] = {
          ContentJP = "茶化さないでよ、名探偵さん。",
          DialogueId = 51010139,
          GUID = "7FB2D2EE",
          NextDialogue = 51010140,
          SpeakNpcId = 700302
        },
        [51010140] = {
          ContentJP = "じゃあこれから……どうするつもり？",
          DialogueId = 51010140,
          GUID = "7FB2D318",
          NextDialogue = 51010141,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "100001:Talk02R_Start"
          }
        },
        [51010141] = {
          ContentJP = "うーん、まだ決めてない。でも、時間はあるから、ゆっくり考えるわ。",
          DialogueId = 51010141,
          FacialId = {
            [1] = "700302:CM_Happy01"
          },
          GUID = "7FB2D342",
          NextDialogue = 51010142,
          SpeakNpcId = 700302
        },
        [51010142] = {
          ContentJP = "だって舞台は広いもの。きっといつか、自分にぴったりの役が見つかると思う。",
          DialogueId = 51010142,
          GUID = "7FB2D36C",
          SpeakNpcId = 700302
        },
        [51010143] = {
          Camera = "-19.636719,461.339844,156.540039,0.000053,-6.400208,-95.20314,35.333332,100000.0,true,DoNotOverride,2.8",
