        },
        [51011306] = {
          ContentJP = "私に試させてくれる？",
          DialogueId = 51011306,
          GUID = "7FB39264",
          ImprPlusId = 1004,
          NextDialogue = 51011307
        },
        [51011307] = {
          ContentJP = "わ、わからない……",
