          GUID = "7FB3928E",
          NextDialogue = 51011308,
          SpeakNpcId = 700341
        },
        [51011308] = {
          ContentJP = "ハンター……私はどうすればいいの？",
          DialogueId = 51011308,
          GUID = "7FB392B8",
          NextDialogue = 51011309,
          SpeakNpcId = 700341
        },
        [51011309] = {
          ContentJP = "じゃあ、ハンターに一体何があったの？",
          DialogueId = 51011309,
          GUID = "7FB392E2",
          NextDialogue = 51011310,
          SpeakNpcId = 100001
        },
        [51011310] = {
          ContentJP = "彼は……",
          DialogueId = 51011310,
          GUID = "7FB3930C",
          NextDialogue = 51011311,
          SpeakNpcId = 700341
        },
        [51011311] = {
          ContentJP = "だめ、言えない。ここから出ていって。もう来ないで。",
          DialogueId = 51011311,
          GUID = "7FB39336",
          NextDialogue = 51011317,
          SpeakNpcId = 700341
        },
        [51011312] = {
