          DialogueId = 51011312,
          GUID = "7FB39360",
          ImprPlusId = 1003,
          NextDialogue = 51011313
        },
        [51011313] = {
          ContentJP = "それなら、あなたに……",
          DialogueId = 51011313,
          GUID = "7FB3938A",
          NextDialogue = 51011314,
          SpeakNpcId = 700341
        },
        [51011314] = {
          ContentJP = "だめ……外の人は信じられない。",
          DialogueId = 51011314,
          GUID = "7FB393B4",
          NextDialogue = 51011315,
          SpeakNpcId = 700341
        },
        [51011315] = {
          ContentJP = "今のは全部なかったことにして。",
          DialogueId = 51011315,
          GUID = "7FB393DE",
          NextDialogue = 51011316,
          SpeakNpcId = 700341
        },
        [51011316] = {
          ContentJP = "ここから出ていって。もう来ないで。",
          DialogueId = 51011316,
          GUID = "7FB39408",
          NextDialogue = 51011317,
          SpeakNpcId = 700341
        },
        [51011317] = {
          ContentJP = "（少女の感情の急変に、あなたはどう対処すべきか分からず、彼女の瞳からさらなる手がかりを得ようとする。）",
          DialogueId = 51011317,
          GUID = "7FB39432",
          NextDialogue = 51011318
        },
        [51011318] = {
          ContentJP = "（それは迷いと悲しみに満ちた目でありながら、かすかに気づきにくい信念が混じっていた。その信念がどこから来て何を意味するのか、あなたには分からない。だが、彼女が口をつぐむ理由がそこにあるのだと理解した。）",
          DialogueId = 51011318,
          GUID = "7FB3945C"
        },
        [51011401] = {
          ContentJP = "テーブル……拭いた。床……もう拭いた。残ってるのは……手すり、そうだ、手すりはまだだ。",
