          GUID = "7FB3A1FA",
          NextDialogue = 51011402,
          SpeakNpcId = 700340
        },
        [51011402] = {
          ContentJP = "（少年はぶつぶつと独り言を言い、慌てた顔で両手を忙しく振り回している。）",
          DialogueId = 51011402,
          GUID = "7FB3A224",
          NextDialogue = 51011403
        },
        [51011403] = {
          ContentJP = "……ちょっとどいて。",
          DialogueId = 51011403,
          GUID = "7FB3A24E",
          NextDialogue = 51011404,
          SpeakNpcId = 700340
        },
        [51011404] = {
          ContentJP = "ん？",
