          GUID = "7FB3A278",
          NextDialogue = 51011405,
          SpeakNpcId = 100001
        },
        [51011405] = {
          ContentJP = "手すり、まだ拭いてない。道をふさがないで。",
          DialogueId = 51011405,
          GUID = "7FB3A2A2",
          NextDialogue = 51011406,
          SpeakNpcId = 700340
        },
        [51011406] = {
          ContentJP = "（少年の切迫した視線を追うと、彼が凝視しているもの――階段の手すりが見えた。新しくはないが、ピカピカで塵ひとつないようにあなたには見える。）",
          DialogueId = 51011406,
          GUID = "7FB3A2CC",
          NextOptions = {
            [1] = 51011407,
            [2] = 51011411
          }
        },
        [51011407] = {
          ContentJP = "拭かなくていいよ。見た感じ、その手すりはかなりきれいだよ。",
          DialogueId = 51011407,
          GUID = "7FB3A2F6",
          ImprPlusId = 1001,
          NextDialogue = 51011408
        },
        [51011408] = {
          ContentJP = "きれいじゃない！そこは今日はまだ拭いてない、だからきれいとは言えない……",
          DialogueId = 51011408,
          GUID = "7FB3A320",
          NextDialogue = 51011409,
          SpeakNpcId = 700340
        },
        [51011409] = {
          ContentJP = "それから二階の額縁、本棚、フロアランプ……それに……",
          DialogueId = 51011409,
          GUID = "7FB3A34A",
          NextDialogue = 51011410,
          SpeakNpcId = 700340
        },
        [51011410] = {
          ContentJP = "放っておいて、お願い……君には自分の用事はないの？",
          DialogueId = 51011410,
          GUID = "7FB3A374",
          NextDialogue = 51011412,
          SpeakNpcId = 700340
        },
        [51011411] = {
          ContentJP = "（道を空ける。）",
          DialogueId = 51011411,
          GUID = "7FB3A39E",
          ImprPlusId = 1004,
          NextDialogue = 51011412
        },
        [51011412] = {
          ContentJP = "（あなたは肩をすくめ、体を横にして道を空け、彼の好きにさせた。）",
          DialogueId = 51011412,
          GUID = "7FB3A3C8"
        },
        [51011501] = {
