        [70010100] = {
          Camera = "6426.663086,7746.713379,-121.966454,0.253341,0.343415,-129.197754,35.0,350.0,false,Manual,2.8",
          Content = "TalkMechanism测试",
          DialogueId = 70010100,
          GUID = "AF435008",
          SpeakNpcId = 10201
        },
        [70010101] = {
          Camera = "240.799805,-19.96875,71.943665,0.000028,-8.199457,146.99736,18.0,100000,false,Manual,2.8",
          ContentJP = "最近、島内の<Default note=\"text:エジュウ\">穢獣</>の活動が活発化している。島民はいつでも海へと避難できるよう、船と物資の準備を整えている。",
          DialogueId = 70010101,
          Duration = 5,
          GUID = "AF435032",
          SpeakNpcId = 102011
        },
        [70010201] = {
          Camera = "299.416992,-190.118652,-59.832947,0.000008,10.199979,140.800186,20.0,100000.0,false,Manual,2.8",
          ContentJP = "住民の皆様へ、漁に出て見知らぬ船舶を発見した際には、速やかに遠ざかるように。ヒュペリア軍に見つかってはいけません。\n先祖たちは無益な戦争を避けるためにこの島まで逃れてきました。彼らの知恵を信じて戒めを守り抜きましょう。",
          DialogueId = 70010201,
          Duration = 5,
          GUID = "AF43609A",
          SpeakNpcId = 102012
        },
        [70010301] = {
          Camera = "-364.107666,1506.973633,120.13916,0.000131,13.391685,87.755157,18.0,100000.0,false,Manual,18.0",
          ContentJP = "穢獣から逃れるべく、村人たちは船に乗って村を脱出したに違いない。遠くの「天上樹」は彼らの出航を導く天然の灯台だ",
          DialogueId = 70010301,
          Duration = 5,
          GUID = "AF437102",
          SpeakNpcId = 102013
        },
        [70010401] = {
          Camera = "-564.918457,-24.525635,71.417542,0.000015,34.991844,0.800468,18.0,1932.963745,false,Manual,2.8",
          ContentJP = "見たこともない彫像。名も知らぬ神が祀られている。いつの時代の遺物なのだろうか……",
          DialogueId = 70010401,
          Duration = 5,
          GUID = "AF43816A",
          SpeakNpcId = 102014
        },
        [70010501] = {
          Camera = "-33.021576,347.337158,98.72699,0.000062,6.798647,-91.995422,18.0,100000.0,false,Manual,2.8",
          ContentJP = "剣の刃で刻まれた銘文。読み取れるのは一部のみ。\n……\nグリオニアのギャラス、ブレンダンの将軍とこの地に参じ、偽教エリュシオンの盲目的な信者全員を追放した。\n……\nできる限り偽神の痕跡を滅した。\n……\nこの島に留まりたいが、土地は貧しく常駐できるのか判断いたしかねる。\n……",
          DialogueId = 70010501,
          Duration = 5,
          GUID = "AF4391D2",
          SpeakNpcId = 102015
        },
        [70010601] = {
          Camera = "-1111.150024,-564.398438,447.803864,0.000071,30.199543,17.596375,15.0,100000.0,false,Manual,2.8",
          ContentJP = "巨大な彫像と崖に残された建築物の残骸から察するに、大昔に神殿だった場所なのだろう。",
          DialogueId = 70010601,
          Duration = 5,
          GUID = "AF43A23A",
          SpeakNpcId = 102016
        },
        [70010701] = {
          Camera = "507.757812,-5157.005371,-457.544922,0.000083,-13.799645,-41.00135,20.0,511.06842,false,Manual,2.8",
          ContentJP = "息絶えた穢獣の身体はまだ温かい。ここで何者かが穢獣と戦ってからまだそれほど時間は過ぎていないようだ。",
          DialogueId = 70010701,
          Duration = 5,
          GUID = "AF43B2A2",
          SpeakNpcId = 102017
        },
        [70010801] = {
          Camera = "454.451172,-463.453125,534.632812,0.000046,-15.999574,138.796616,15.0,100000.0,false,Manual,8.0",
          ContentJP = "いろ鮮やかな神像はきれいな状態を保っているが、周りの壁などの損傷が激しい。この場所ではかつてひどい略奪が行われたようだ。",
          DialogueId = 70010801,
          Duration = 5,
          GUID = "AF43C30A",
          SpeakNpcId = 102018
        },
        [70010901] = {
          Camera = "-742.34668,128.554199,307.391235,0.000063,-10.999725,71.996475,15.0,100000.0,false,Manual,2.8",
          ContentJP = "錬金術用の装置のようだが、なぜそんなものが遺跡にあるのか、理由はわからない。",
          DialogueId = 70010901,
          Duration = 5,
          GUID = "AF43D372",
          SpeakNpcId = 102019
        },
        [70011001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.8",
          ContentJP = "10年以上前に撮られた写真で、フォトフレームのガラスには明らかに弄られた形跡がある。写真の少女は、風に髪の先をなびかせながら穏やかに微笑んでいた。\n写真の裏にはペンで 「私の娘——ヘイリー、レッドバリー城で撮影 」と書かれている。あまり似ているわけではないが、少女の澄んだ微笑みは、なんとなくサイキを思い出させる。",
          DialogueId = 70011001,
          Duration = 5,
          GUID = "AF43E3DA",
          SpeakNpcId = 102020
        },
        [70011101] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentJP = "（高い書類棚、アルファベット順に「宿泊客」の個人ファイルがずらり並んでいる。それぞれの個人ファイルに子供の写真のほかに、子供たちがヒュプノスの家に過ごした日常が記載されている。）\n\nサイキの個人ファイル\n年齢: 17歳\n症状: 失明、聴覚障害\n\n……\nサイキが来たときには既に穢蝕（えしょく）中期に達していたが、それでも彼女は皆に元気よく挨拶をしていた。診断結果が間違いであってほしいと、どれほど願ったことか。そうすれば、サイキには穢蝕の兆候がなく、彼女の人生は再び正常に戻ると自分を欺くことができたのに。\n……\n彼女は両親が見舞いに来たときに持ってきた花をすべてベッドの頭に置いており、足の踏み場も寝る場所もほんの少ししか残されていなかった。\n……\n俺は2階の空き部屋を片付けた。あちらの方が採光が良いので、サイキと彼女の花をそこに移した方が、もう少し快適に過ごせるだろう。\n……\n彼女は本当に花が好きで、毎日丁寧に花束を手入れし、他の子供たちにも分け与えていた。もし穢蝕がなければ、彼女は将来、「想いを寄せる花」を両親よりも上手に手入れできるに違いない。\n……\nサイキは今日俺にも花をくれた。彼女の穏やかな笑顔を見ていると、まるでヘイリー……君をまた見たかのようだった。\n……\n帳簿を見て悩んでいる俺の様子を、サイキにうっかり見られてしまった。彼女はしつこく理由を聞きたがり、俺は仕方なく、ヒュプノスの家の財政問題を正直に彼女に話した。\n（注釈：早急に買収者に返答しなければならない。これ以上、子供たちに心配をかけたくない。）\n……\nサイキは古い家を掃除し、ついでに素性の分からない少年に貸し出した……あの少年がヒュプノスの家に問題を持ち込まないことを願うばかりだ。\n……\n<H>彼女は生きたいと、ソラの民として一日でも長く生きられるならそれでいいと言った。その言葉を聞いたとき、俺は嬉しくもあり、同時に怒りを感じた。\n嬉しかったのは、彼女がついに本音を打ち明けてくれたこと。彼女はずっと命を気にしないふりをして強がっていたのだ。\n怒りを感じたのは、あの少年だ！俺は、あの少年がサイキに何をしたのか分からないが、死にゆく者に生きる勇気を与えるのは、あまりに残酷だ。\n救えないのであれば、無意味な希望を与えないでほしい！</>\n……\n（注釈：もしこれが本当にサイキの願いだったら…穢蝕を抑える手術の研究を急がないと。サイキのためにも、子供たちのためにも。）\n",
          DialogueId = 70011101,
          Duration = 5,
          GUID = "AF43F442",
          SpeakNpcId = 102021
        },
        [70011201] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentJP = "エイクの個人ファイル\n年齢: 19歳\n症状: 失明\n\nエイクは一人でヒュプノスの家に来た。親が自分の子供の最期を見ていられないか単なる非情か、目の不自由な子供一人でアイスレイク城まで行かせたなんて。\n……\n本を読みたいってエイクが言った。しかしここはつまんなくて長い医学の本しかない。それでも彼はなんの嫌がらせもなく、俺が本を読み聞かせて、そばで彼は静かに聞いて、そのまま一日を過ごした。\n……\nエイクが父親の名前を呼ぶ寝言を聞いた。\n……\nフレグサン領でエイクの父親を探した。俺のことはぜんぜん気にしてくれず、ただひたすらに懐のソラの赤ちゃんに子守唄を歌い聞かせて、寝かしつけたばっかりだ。\n……\n点字の本を買ってエイクに送った。「ありがとう、お父さん」と嬉しく返事してくれた。お父さんではないと言いたかったが、結局無理矢理に「うん」しか相づちを打たなくて、病室を後にした。",
          DialogueId = 70011201,
          Duration = 5,
          GUID = "AF4404AA",
          SpeakNpcId = 102022
        },
        [70011301] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentJP = "ロビーの個人ファイル\n年齢:18歳\n症状: 骨形成不全\nはじめてロビーがヒュプノスの家に送ってくれた時に、全身は包帯に巻かれていて、ちょっとだけこするだけでひどい骨折になりそうで、ベッドを離れて歩くのもできなかった。\n……\n彼のベッドを窓のところまでに移動し、これで長時間に陽に当たるのは便利になった。\n……\nリハビリは大成功だった。レナさんの料理がロビーにたっぷりの栄養摂取を提供し、今は杖をついてヒュプノスの家をちょっとだけ歩くようになった。\n……\n今日またロビーの脚は骨折してしまって、来たばかりの時よりひどくなっていた。俺に迷惑をかけてくれないために、階段から落ちた時にさえも大声を出さなかった。どうやら最近の俺は憔悴しすぎて、逆に子供たちに心配してくれるようになってしまった。\n……\nロビーは外でお礼としてお花を摘んでサイキに送りたがって、俺の許可を得た。\n枯木の枝しか拾わなかったが、ロビーはとても嬉しく笑った。",
          DialogueId = 70011301,
          Duration = 5,
          GUID = "AF441512",
          SpeakNpcId = 102023
        },
        [70011401] = {
          Camera = "460.416016,1822.310425,211.930038,0.000008,-4.800414,169.194534,35.0,100000.0,false,Manual,2.8",
          ContentJP = "ジョセフィンの個人ファイル\n年齢:17歳\n症状:臓器変形、呼吸困難\n彼女の穢蝕の印が首に現れてて、はしゃいでいる彼女の様子を見て逆に嫌な予感がする。\n……\n急に倒れてて荒い息をした。全身検査の結果はどうにもいいとは言えなかった。彼女の臓器がひどく変形してて、これからの数日に恐らく手術室で過ごすしかないだろう。\n……\n彼女の体の調子は良くなってきた。それでも、レスピレーターの補助は今は欠かせない状態で、睡眠中に症状が悪くならないため、毎晩彼女のベッドのそばでレスピレーターの運転を常にチェックし、彼女の冷や汗を拭う。\n幸い、コーヒーはまだ足りててなんとか持ちこたえそう。",
          DialogueId = 70011401,
          Duration = 5,
          GUID = "AF44257A",
          SpeakNpcId = 102024
        },
        [70011501] = {
          Camera = "589.100586,92.850586,87.400391,0.000028,0.0,-178.390396,22.0,400.0,false,DoNotOverride,2.8",
          ContentJP = "悪天候の影響により、郊外の公道1号線にて重大な横転事故が発生し、現在第六軍団所属警備部隊が修復作業にあたっている。一般市民は外出を控えるように。やむを得ず外出する際は滑り止め対策をしっかりと行うよう注意されたし。",
          DialogueId = 70011501,
          Duration = 5,
          GUID = "AF4435E2",
          SpeakNpcId = 102025
        },
        [70011601] = {
          Camera = "-83.132812,-721.489746,92.419189,0.000006,-0.600217,80.994888,20.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "動かなくなった門扉が鉱山への侵入を封じている。鉱山が封鎖される際に流れた坑内放送であろう、冷たい機械音が断続的に響く。\n\n……月ノ石の鉱脈は枯渇した……本日より放棄状態へと指定……\n \n帝国軍は安全保障を停止する……\n本警告を無視して立ち入った場合は、一切の責任を負わない……",
          DialogueId = 70011601,
          Duration = 5,
          GUID = "AF44464A",
          SpeakNpcId = 102026
        },
        [70011701] = {
          ContentJP = "帝国軍が鉱山労働者を移送する際に流されたであろう坑内放送が、冷たい機械音で繰り返される。\n\n帝国軍第六軍団の駐留部隊が、関連作業を継続させるべく、名簿に記載のある鉱山労働者をフレグサン領まで護送する。護送用の列車はグルビューム鉱山閉鎖の3時間前に発進するので注意されたし。また名簿に載っている鉱山労働者の各員は今より告げる事項を聞き逃さないように。\n1. 5kg以上の所持品を携帯している者は処刑。\n2. 指定された時刻までに列車に乗らなかった者は処刑。\n3. 名簿について質問する者は処刑。",
          DialogueId = 70011701,
          Duration = 5,
          GUID = "AF4456B2",
          SpeakNpcId = 102027
        },
        [70011801] = {
          Camera = "-415.066528,-79.582031,152.246094,0.000006,0.599875,-0.799286,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（年季の入った古い集合写真。アスフォデロス開業時の華やかな様子が記録されている。庶民や富裕な商人、さらには内城区の役人までもが集まり、生まれたばかりの酒場を祝福している）",
          DialogueId = 70011801,
          Duration = 5,
          GUID = "AF44671A",
          SpeakNpcId = 102028
        },
        [70011901] = {
          Camera = "-652.218567,-446.646545,311.657959,0.000055,7.500012,42.603733,10.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（帝国の至るところにある巨大なポスター。「我らが皇帝に栄光あれ」といったスローガンが書かれている）",
          DialogueId = 70011901,
          Duration = 5,
          GUID = "AF447782",
          SpeakNpcId = 102029
        },
        [70012001] = {
          Camera = "251.815674,-114.571671,67.927124,0.000047,-3.399658,170.391632,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "新期の第六軍団選抜試験（カロン族限定）がまもなく開始される。申告条件を満たしているカロン族は保安署へ行き必要資料を提出されたし。\n運命を変える時が来たのだ！黒狼の旗の下、我らが皇帝ジュリアスの名を叫び、ヒュペリアに忠誠を捧げよ！\n\n『注意事項』\n\n1. 試験で特別優秀な成績を収めた者は、内城区への移住資格を得られる「桂冠カロン勲章」を授与する。\n2. 「桂冠カロン勲章」の授与には届かないが好成績であった者は、城外の警備部隊に配属する。\n3. 試験の最終権限は第六軍団コキュートス領駐留部隊に委ねられる。また試験中に発生した不利益や事故はすべて自己責任として処理する。",
          DialogueId = 70012001,
          Duration = 5,
          GUID = "AF4487EA",
          SpeakNpcId = 102030
        },
        [70012101] = {
          Camera = "-413.806396,24.681641,230.520782,0.000089,-29.19894,-18.408882,35.0,400.0,false,DoNotOverride,2.8",
          ContentJP = "保存タンクには「イコル液」と記載されている。帝国の交通機関や照明など、さまざまな物にてこれと同じ名前の表記を見たことがある。察するに月ノ石から生まれた何らかの産物なのだろう。",
          DialogueId = 70012101,
          Duration = 5,
          GUID = "AF449852",
          SpeakNpcId = 102031
        },
        [70012201] = {
          Camera = "-829.676514,67.595215,115.704071,0.000047,28.996904,-8.414193,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "時計の針が12時を指すたびに「トッド・ウェルズ」という名前が一瞬だけ文字盤に浮かび上がる。機械技術と光学原理を融合させた作品に名前を残すことができるウェルズ氏は、優れた時計職人なのだろう。",
          DialogueId = 70012201,
          Duration = 5,
          GUID = "AF44A8BA",
          SpeakNpcId = 102032
        },
        [70012301] = {
          Camera = "576.424805,22.139282,190.283051,0.000035,-16.800291,175.187546,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（車両に近づくや否や興奮した声が聞こえてきた。\n\n「おいおいおい、このPRT20Aに興味があるのか？まあそりゃ仕方ない！軍用から民生用に改造されたイコル駆動輪搭載の第二世代小型車なんだからな！こいつはたくさんの人々が携わった知恵の結晶なんだ。スピードは軍用規格には劣るがイコル駆動輪の轟音を至近距離で聞けるし、それを公道で走らせられるのは高貴な身分の象徴であって……」\n\n車の歴史から構造、イコル駆動輪から車体、さらにはタイヤのトレッドパターンに至るまで、問答無用の熱弁が延々と続いた。ようやく静かになってももエンジンや回転数などの意味不明な専門用語の羅列が頭から離れない。なぜ話が急に終わったのだろうと周囲を見回すと、熱狂的な車好きは別の不運な通行人を捕まえたようで、速度全開の新たなトークに興じていた）",
          DialogueId = 70012301,
          Duration = 5,
          GUID = "AF44B922",
          SpeakNpcId = 102033
        },
        [70012401] = {
          Camera = "-712.020264,-289.200195,10.626465,0.000082,16.793509,22.182402,10.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "高くそびえる記念碑。背面には帝国人の名前が、正面には短い言葉が深く刻まれている。\n\nとこしえの平和をもたらすべく、果敢にも命を捧げた兵士たちを称える。\n我らが皇帝に栄光あれ。",
          DialogueId = 70012401,
          Duration = 5,
          GUID = "AF44C98A",
          SpeakNpcId = 102034
        },
        [70012501] = {
          Camera = "-593.807617,-151.208984,181.682983,0.000059,-13.99979,25.798237,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（ランプ、ツルハシ、トロッコ……街でよく見かける道具類は、アイスレイク城が月ノ石の採掘を主産業として栄えていた証なのだろう。だが、これらの道具がゴミ捨て場の傍らに放置されてホコリまみれになっているところを見ると、鉱夫たちの栄華はすでに過去となったことは明らかだ）",
          DialogueId = 70012501,
          Duration = 5,
          GUID = "AF44D9F2",
          SpeakNpcId = 102035
        },
        [70012601] = {
          Camera = "-429.546875,-25.467529,208.017578,0.000075,25.39749,-29.411985,20.0,100000.0,false,Manual,2.8",
          ContentJP = "何千人もの労働者が出入りしている巨大な工場、その影が街を覆っている。まるで働きアリたちを見下ろす巨人のように。かなり離れたところからもこの巨人の咆吼が聞こえる。",
          DialogueId = 70012601,
          Duration = 5,
          GUID = "AF44EA5A",
          SpeakNpcId = 102036
        },
        [70012701] = {
          Camera = "7.69043,-170.557617,63.654785,0.0,0.0,-89.999939,10.0,100000.0,false,DoNotOverride,2.24",
          ContentJP = "通行禁止のバリケードがはられている。傍らの目立つ注意書きから察するに、この先は第六軍団警備部隊の管理下にあるようだ。",
          DialogueId = 70012701,
          Duration = 5,
          GUID = "AF44FAC2",
          SpeakNpcId = 102037
        },
        [70012801] = {
          Camera = "902.932129,1093.807129,22.332031,0.000012,7.59978,-122.402924,35.0,100000.0,false,Manual,2.8",
          ContentJP = "イコル液で動く暖房設備。近くに座ると心地よい暖かさを感じられる。しかし適当に組み立てられた様子からして、設置したのは専門家ではない一般人だろう。帝国側にとっては、カロン族に何か融通を利かせるなんてありえないし、まして暖が取れる場所を提供するなんて無意味極まりないはずだ。",
          DialogueId = 70012801,
          Duration = 5,
          GUID = "AF450B2A",
          SpeakNpcId = 102038
        },
        [70012901] = {
          Camera = "538.746094,139.100586,83.406647,0.000042,-10.399529,-172.984406,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "スプレーで乱雑に描かれた落書き。カロン族を侮辱する言葉で埋め尽くされている。",
          DialogueId = 70012901,
          Duration = 5,
          GUID = "AF451B92",
          SpeakNpcId = 102039
        },
        [70013001] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.27",
          ContentJP = "鳥が1羽入るかぐらいの小さなお墓。墓石に名前はなく、一文だけが刻まれている。\n（永遠の友、俺をを命がけで助けてくれた英雄、どうか安らかに。——コノン）",
          DialogueId = 70013001,
          Duration = 5,
          GUID = "AF452BFA",
          SpeakNpcId = 102040
        },
        [70013101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.28",
          ContentJP = "布の袋がうっすらと黄色く光り、角がデコボコと突き出ているのを見ると、恐らくなかには月ノ石が満杯に入っているのだろう。底部には血痕が付着している。",
          DialogueId = 70013101,
          Duration = 5,
          GUID = "AF453C62",
          SpeakNpcId = 102041
        },
        [70013201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.29",
          ContentJP = "積み木\n（子供たちに人気があったデザインのシンプルな積み木だ。今だと少し時代遅れで古臭く見える）",
          DialogueId = 70013201,
          Duration = 5,
          GUID = "AF454CCA",
          SpeakNpcId = 102042
        },
        [70013301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.30",
          ContentJP = "サイキの部屋\n（扉には緑色のチョウのルームプレートが掛かっていて、子供っぽい文字で「サイキの部屋」と書かれている。かつてサイキが住んでいた場所のようだが、扉は固く施錠されている。母親であるデイジーの意向なのだろうか）",
          DialogueId = 70013301,
          Duration = 5,
          GUID = "AF455D32",
          SpeakNpcId = 102043
        },
        [70013401] = {
          Camera = "-274.459961,499.943848,20.897705,0.000001,4.999999,-79.999969,16.0,100000.0,false,Manual,2.8",
          ContentJP = "（「エニー&エブリー」という洋服店のショーウィンドウ越しに、ハイセンスなロングドレスが見えた。生地選びが絶妙で、体型を引き立てつつもドレスの持ち主の優雅な雰囲気を強く主張している。ハーランのスタイルにピッタリのデザインだ）",
          DialogueId = 70013401,
          Duration = 5,
          GUID = "AF456D9A",
          SpeakNpcId = 102044
        },
        [70013501] = {
          Camera = "36.606445,286.352539,23.979492,0.000003,-8.400025,-108.599854,15.0,100000.0,false,Manual,2.32",
          ContentJP = "（リオの横にバケツと雑巾が置いてある。隣にある赤黒いシミを掃除するのに使う予定なのだろう。かなり凄惨な出来事がこの場で起きたと推察できる）",
          DialogueId = 70013501,
          Duration = 5,
          GUID = "AF457E02",
          SpeakNpcId = 102045
        },
        [70013601] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.33",
          ContentJP = "退色して黄ばんだポスター。何が書いてあるのかギリギリわかるぐらいの状態だ。\n……\nトップシンガー、ヴィオレッタの公演が来週開幕！\n代表作『雪国の幼子』再び！？天国のような歌声がアイスレイク城に蘇る！\n今週いっぱい開催予定なので、ぜひぜひ、絶対にお見逃しなく！\n料金を頂ければ内城区への侵入をお手伝い！高貴な音楽の宴を体験しよう！\n……\n連絡先：ミスタージャック\n連絡方法：深夜に下水道マンホールの傍で待ち合わせ。赤毛の男に「カッコウカッコウ」という合言葉を伝える。",
          DialogueId = 70013601,
          Duration = 5,
          GUID = "AF458E6A",
          SpeakNpcId = 102046
        },
        [70013701] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.34",
          ContentJP = "（ボロボロな教科書。空白の部分は下品な落書きで埋まっている。フェイは落書きの中だと角の生えた悪魔として描かれており、恐ろしい魔術を唱えられるようだ）",
          DialogueId = 70013701,
          Duration = 5,
          GUID = "AF459ED2",
          SpeakNpcId = 102047
        },
        [70013801] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.35",
          ContentJP = "ときおり、ヒュプノスの家でこの顔つきが厳しい女性を見かけることがある。定期的に訪れては掃除をし、子どもたちに温かい食事を用意しているようだ。\n\n誰かに尋ねられると、彼女はこう答える――「ヘンリックさんに雇われたのだから、働くのが筋でしょう。そういう業界なのよ」と。\n\nその言葉の端々には、どこかやるせなさが滲んでいる。だから人々も、それ以上は深く聞かない。\n\nけれど、ヒュプノスの家の子どもたちはみんな知っている。レナさんは、ヘンリックから報酬をたったの一銭も受け取ったことがないのだと。",
          DialogueId = 70013801,
          Duration = 5,
          GUID = "AF45AF3A",
          SpeakNpcId = 102048
        },
        [70013901] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.36",
          ContentJP = "（多種多様な廃品の数々。マーティンが何を基準に選んだのかはわからない。これらの元の所有者は誰だったのだろうか？）",
          DialogueId = 70013901,
          Duration = 5,
          GUID = "AF45BFA2",
          SpeakNpcId = 102049
        },
        [70014001] = {
          Camera = "-394.105225,225.10498,147.011475,0.00004,-19.999113,-46.394775,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（カミラが受け取り拒否したお酒。次はどこへと運ばれるのやら）",
          DialogueId = 70014001,
          Duration = 5,
          GUID = "AF45D00A",
          SpeakNpcId = 102050
        },
        [70014101] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.38",
          ContentJP = "足跡\n（子供サイズ。ここでバックは足音を聞いたようだが）",
          DialogueId = 70014101,
          Duration = 5,
          GUID = "AF45E072",
          SpeakNpcId = 102051
        },
        [70014201] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.39",
          ContentJP = "ポップコーン\n（犯人のカバンに小さな穴が開いていたようだ。ポップコーンが足跡の周りに散らばっている。「豊かな果実の香り」……なるほど）",
          DialogueId = 70014201,
          Duration = 5,
          GUID = "AF45F0DA",
          SpeakNpcId = 102052
        },
        [70014301] = {
          Camera = "-1014.009033,-38.646729,437.392578,0.000006,-1.999756,-2.801728,20.0,100000.0,false,Manual,2.40",
          ContentJP = "簡素で小さなテント。ここでベリンダが相談所のような商売を行っている。看板もなく相談分野の指定もない。客の大半は口に出せない悩みを抱えてやってくるようだ。",
          DialogueId = 70014301,
          Duration = 5,
          GUID = "AF460142",
          SpeakNpcId = 102053
        },
        [70014401] = {
          Camera = "-277.21875,1095.014038,199.530029,0.000023,24.997671,-88.593628,15.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "イコル液を動力源とする巨大クレーン。工学錬金院の改良により制御室でレバーを操作するだけで複数のクレーンが動かせる。作業員がクレーンに乗る必要もなくなったので、作業効率が大幅に向上した。しかし同時に巨大クレーンに憧れていた多くの少年たちの夢を、そして多くの労働者たちの就業機会を奪ってしまった。",
          DialogueId = 70014401,
          Duration = 5,
          GUID = "AF4611AA",
          SpeakNpcId = 102054
        },
        [70014501] = {
          Camera = "-553.419922,-854.08313,145.091064,0.000012,-2.200284,52.400944,20.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（ラベルから見る限り、この車両はPRT05MVという名の軍用掘削装置らしい。雨風にさらされてしみ出たサビが、車体に年月を刻んでいる。メンテナンスも回収もせずに放置してあるのは、車両盗難防止に帝国軍が自信を持っているのか、それとも帝国軍の威光がこの車両に興味を抱く者たちを遠ざけているのか）",
          DialogueId = 70014501,
          Duration = 5,
          GUID = "AF462212",
          SpeakNpcId = 102055
        },
        [70014601] = {
          Camera = "18.892578,-214.330688,159.580475,0.000026,-31.400263,99.99868,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（カビの生えた黒いパンが新聞紙に包まれている。もはやかじってみる気も浮かんでこないパンはともかくとして、新聞紙を広げてカビを拭き取りながら読んでみると、10年以上前に発行された古新聞であることが分かった。帝国軍第六軍団との契約にグルビューム鉱山の元経営者が合意した件に関する記事が載っている。\n……\n鉱山労働者の利益とアイスレイク城の発展のため、<H>グルビューム鉱山は本日をもって民間での採掘を終了。全権を帝国軍が引き継ぐこととなった。</>\n……\n……記事と一緒に祝賀式の白黒写真が何枚か掲載されているが、不思議なことに写っているのは合意書を手にした将校と拍手喝采している労働者たちだけで、元経営者の姿が一切なかった。現場を見たくなかったのか、それとも二度と現場を見ることができなくなったのか、理由は不明である）",
          DialogueId = 70014601,
          Duration = 5,
          GUID = "AF46327A",
          SpeakNpcId = 102056
        },
        [70014701] = {
          ContentJP = "もみくちゃにされてシワだらけの手紙。筆跡を見る限り手書きでなく印刷された物のようだ。\n\nご機嫌よう、帝国の諸君。\n \n\n余はヒュペリア帝国の建国者、最も偉大なるディス1世である。帝都からこの手紙を書いている。\nそうだ、余は死んでいない、秘術によって蘇ったのだ。\n \n現在の余はエリュシオン礼讃会征討を再開すべく準備を進めているが、すべての戦争資金はアイスレイク城に保管されてあり、\n身体が不自由なため自分で取りに行くことができない状態だ。\n \nそこで諸君らに提案を申し出たい。帝国の民としての誇りと情熱を抱くならば、帝都のグローリーアヴェニュー233号に寄付を送るのだ。\n余の体調が回復次第、すべての戦争資金を回収した暁には、必ず倍額にして返還しよう。\n戦火が近づいていることを忘れてはならぬ！迷っている暇はない！\n諸君らの寄付を待つ！余は電光石火で戻ってくる！",
          DialogueId = 70014701,
          Duration = 5,
          GUID = "AF4642E2",
          SpeakNpcId = 102057
        },
        [70014801] = {
          Camera = "-233.383423,129.945312,39.479553,0.000071,26.799578,-19.787138,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（「アイスフォルクテイル」と呼ばれる発酵飲料。バルブを回すとグラス1杯分を注ぐことができる。その色は月ノ石のようだ。最初の舌触りはミントような清涼感でアイスレイクを横切る冷たい風を感じられる。飲み込むと蜂蜜のような甘さで月ノ石の採掘産業の過去の栄華を感じられる。続けて泥炭のような苦味が五臓六腑に染みわたり、果てしない余韻が残る。\nその名の意味は「アイスレイクの伝承」。アスフォデロスで最も人気な飲み物であるのもうなずける）",
          DialogueId = 70014801,
          Duration = 5,
          GUID = "AF46534A",
          SpeakNpcId = 102058
        },
        [70014901] = {
          Camera = "144.133301,295.799561,71.270615,0.000111,5.599437,-116.392715,20.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "（精巧な歯車だが、どのように回してもアスフォデロスに変化は起こらない。カウンターの後ろからかすかに機械の作動音が聞こえるので、単なる装飾品でないのは推測できる。商人はわずかな利益のために絞首台で首を吊られことさえ厭わない時があると、カミラが言っていたのを思い出す。アスフォデロスは表向きには発酵飲料を販売しているだけだが、もっと深い何かが裏にあるのだろう）",
          DialogueId = 70014901,
          Duration = 5,
          GUID = "AF4663B2",
          NextDialogue = 70014902,
          SpeakNpcId = 102059
        },
        [70014902] = {
          ContentJP = "商人はわずかな利益のために絞首台で首を吊られことさえ厭わない時があると、カミラが言っていたのを思い出す。アスフォデロスは表向きには発酵飲料を販売しているだけだが、もっと深い何かが裏にあるのだろう）",
          DialogueId = 70014902,
          GUID = "AF4663B3",
          SpeakNpcId = 102059
        },
        [70015001] = {
          Camera = "267.163086,229.933594,218.354156,0.000008,-28.000093,-144.996719,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "帝国市民の生活に役立つ月ノ石の技術の象徴のひとつ。照明効果は普通なのだが低消費で低コスト、おまけに長持ちするという優秀な特徴から、アイスレイク城の市民の主な照明器具となっている。第六軍団がグルビューム鉱山を拡張する際にも大量に使用された。",
          DialogueId = 70015001,
          Duration = 5,
          GUID = "AF46741A",
          SpeakNpcId = 102060
        },
        [70015101] = {
          Camera = "-293.902832,-246.538574,58.947754,0.000011,22.198734,42.000011,35.0,100000.0,false,Manual,2.8",
          ContentJP = "明らかに帝国によくあるスタイルの門飾りだが、2つの小さな四角い囲みを見ていると、無意識のうちに、「何を見ているんだ！」と歯をむき出す奇妙な顔に見えてくる。",
          DialogueId = 70015101,
          Duration = 5,
          GUID = "AF46741B",
          SpeakNpcId = 102061
        },
        [70015201] = {
          ContentJP = "ボロボロのバックパックの下には、骨や武器、食べかけの食料が押し込められており、廃坑の深淵に消えていった月狩り人たちの最期の物語っている。\nこれらのバックパックには新しいものも古いものもあるが、持ち主たちは同じような目的で廃坑に入り、自分だけは失敗しないと信じていたが、最終的には同じような悲しい結末を迎えてしまったのだろう。",
          DialogueId = 70015201,
          GUID = "AF4694EA"
        },
        [70015301] = {
          ContentJP = "バックパックに入っていた日記や、すでに輝きを失った月ノ石を見ると、もし運命の変化がもう少し遅れていたなら、持ち主にはもっと良い未来が待っていたかもしれない。",
          DialogueId = 70015301,
          GUID = "AF46A552"
        },
        [70015401] = {
          ContentJP = "ゴミ箱に捨てられていた『アイスレイクモーニングポスト』をよく見ると、何ヶ所も誤植がある――単なる模倣品のようだ。広げてみると、センセーショナルな記事がいくつも掲載されている。",
          DialogueId = 70015401,
          Duration = 5,
          GUID = "AF46B5BA",
          NextDialogue = 70015402,
          SpeakNpcId = 102064
        },
        [70015402] = {
          ContentJP = "モーリス・グレンビル秘話\n……アイスレイクの住民は、短命に終わったグレンビル一族と、モーリス・グレンビル氏が生前、何もないところから財を築き、鉄鋼王となったことを誰もが知っている。しかし、彼の一族は呪いに苦しみ、精神を病んだり、事故死したり、行方不明になってしまった。だが、今日は別の話をしよう――なぜグレンビル氏は、貧しい少年時代の歴史を記録することを選んだのか？",
          DialogueId = 70015402,
          Duration = 5,
          GUID = "AF46B5E4",
          NextDialogue = 70015403,
          SpeakNpcId = 102064
        },
        [70015403] = {
          ContentJP = "……知らない読者のために説明しておくと、モーリスが初めて大金を手にしたのは、少年時代にこの工学錬金院の高官の下で働いて得たもので、その高官は桂冠カロン族だった。モーリスが後に正真正銘の反カロン族主義者になったことを考えると、少年時代に彼とカロン族の上司との間には、何か隠された過去があったに違いない……",
          DialogueId = 70015403,
          Duration = 5,
          GUID = "AF46B60E",
          NextDialogue = 70015404,
          SpeakNpcId = 102064
        },
        [70015404] = {
          ContentJP = "衝撃の事実！ジュリアス陛下の正体は実は替え玉？\n……新聞報道や当時の宮中に仕えていた人々の回想録には、即位前のジュリアス陛下の言葉が記録されており、控えめで優雅な王子であったことは間違いない。では、なぜ即位後に陛下の気性が激変したのか？真実はただ一つ、それは――本物の陛下はとうの昔に殺害され、現在ベローナ宮殿にいる皇帝は紛れもない偽物だということだ！……",
          DialogueId = 70015404,
          Duration = 5,
          GUID = "AF46B638",
          NextDialogue = 70015405,
          SpeakNpcId = 102064
        },
        [70015405] = {
          ContentJP = "あまり深入りしないほうがよさそうな内容だ。慌ててその偽造された新聞紙をゴミ箱に捨てた。",
          DialogueId = 70015405,
          Duration = 5,
          GUID = "AF46B662",
          SpeakNpcId = 102064
        },
        [70015501] = {
          Camera = "382.455078,-10.461182,127.896484,0.000083,-5.801112,-108.595062,30.0,96.67099,false,Manual,4.0",
          ContentJP = "10年以上前に撮られた写真で、フォトフレームのガラスには明らかに弄られた形跡がある。写真の少女は、風に髪の先をなびかせながら穏やかに微笑んでいた。\n写真の裏にはペンで 「私の娘——ヘイリー、レッドバリー城で撮影 」と書かれている。あまり似ているわけではないが、少女の澄んだ微笑みは、なんとなくサイキを思い出させる。",
          DialogueId = 70015501,
          Duration = 5,
          GUID = "AF46C622"
        },
        [70015601] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          ContentJP = "「魂よ、ニブルヘイムで安らかに 」という短い言葉が書かれている。この分厚い日誌をめくると、聞き覚えのある名前と日付が次々に目に入る。",
          DialogueId = 70015601,
          Duration = 5,
          GUID = "AF46D68A",
          NextDialogue = 70015602
        },
        [70015602] = {
          Camera = "-277.050781,-1.119873,213.634766,0.0,0.0,-179.999985,10.0,100000.0,false,Manual,2.8",
          ContentJP = "……\n9月3日、キャロライナ・ブラウン\n……\n10月29日、ハンター・クラーク\n……\n11月25日、サイキ・フレイ",
          DialogueId = 70015602,
          Duration = 5,
          GUID = "AF46D6B4"
        },
        [70015701] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          ContentJP = "月ノ石に似た色の晶石。しかし、よく見ると、月ノ石とは模様も質感もまったく異なり、ただの「光る石」にすぎない。",
          DialogueId = 70015701,
          Duration = 5,
          GUID = "AF46E6F2",
          NextDialogue = 70015702
        },
        [70015702] = {
          Camera = "-746.286377,-2980.045654,256.510742,0.000001,14.999996,-44.999969,18.0,100000.0,false,Disable,2.8",
          ContentJP = "人間は鉱石をその利用価値に応じて様々な等級に分類する。月ノ石は貴重な資源であるが、これらの晶石は役に立たない廃棄物と見なされている。\nそのため、月ノ石は掘り尽くされ、砕かれ、切断され、最終的には工場で冷たいイコル液にされる一方で、これらの晶石は幸運にも完全な形で残されている。",
          DialogueId = 70015702,
          Duration = 5,
          GUID = "AF46E71C"
        },
        [70016001] = {
          ContentJP = "<H>銀燭祭り</>は予定通り、ガレア劇場で開催されます。参加者はお好きな衣装を用意し、ご自分の演じたい役を選んでください。\nさあ、職業や種族、争いごとを忘れ、ここに集いましょう。皇帝の恩寵を浴び、皇帝の仁徳をたたえるために！皇帝に栄光あれ！",
          DialogueId = 70016001,
          GUID = "AF47182A"
        },
        [70016002] = {
          ContentJP = "厚い点呼記録簿。スタッフ全員の1日の行動が詳細に記録されている。リハーサルだけでなく、食事や睡眠、トイレに行く時間まですべてが記録されている。\n果たして、座長が皆を「軟禁」しているのか、あるいは自分の俳優たちを守るために行動を常に監視しているのか。",
          DialogueId = 70016002,
          GUID = "AF471854"
        },
        [70016003] = {
          ContentJP = "純金で作られた勲章。一枚の黄金から成るその輝きは、帝国への卓越した貢献を称える証だ。添えられた賞賛の書状によれば、この勲章は並外れた功績を上げた軍人のみに授与されるという。",
          DialogueId = 70016003,
          GUID = "AF47187E"
        },
        [70016004] = {
          ContentJP = "ガラクタの下に埋もれていた一枚の古びた新聞――そこには、かつて起きた悲劇的な事件が記されていた。\n\n<H>穢蝕者は極めて危険！見た目に惑わされるな！</>\n9月24日、本市にて極めて凶悪な「穢蝕」事件が発生した。第六軍団衛戍部隊の調査により、以下の結論が下されている。\n9月13日、アイスレイク城在住のフィッシャー夫妻が、ダクリ湖のほとりにある公道沿いで瀕死の青年ロビー・ブラウンを発見。夫妻は彼を自宅へ連れ帰り、手厚く看病した。しかし、この行為が想像を絶する惨劇へと繋がることとなる。調査によると、ロビー・ブラウンは穢蝕者であり、帝国による定期検査を逃れ、城外へと潜伏していたことが判明。フィッシャー夫妻の厚意を受ける際も、自らの穢蝕の兆候を巧妙に隠していたという。事件は10日後に発生。ブラウンは突如として<Default note=\"text:エジュウ\">穢獣</>へと変異し、フィッシャー夫妻を含むアイスレイク城南区の住民数十名を襲撃。第六軍団衛戍部隊が緊急出動し、鎮圧作戦を実施。混乱はようやく収束したものの、被害は甚大であった。\n\nこの事件による被害者数は死亡者が18名、うち3名がソーラー族と判明。負傷者は34名にまでのぼった。今回の事件を受け、市民に向けた注意喚起が改めて発表された。\n「正体不明のカロン族を安易に受け入れてはならない。もし『穢蝕者』と思われる者を発見した場合、直ちに保安署へ通報せよ」\nまた、政府関係者によると、穢蝕者を意図的に匿い、報告を怠った者は「ヒュペリア刑法第54条」に基づき、死刑が適用されるとのこと。\n「奴らは例外なく人類の敵である。これを肝に銘じよ。」\n今後、帝国軍は定期検査の強化と、穢蝕者発見時の対応策を改めて検討していくとしている。",
          DialogueId = 70016004,
          GUID = "AF4718A8"
        },
        [70016005] = {
          ContentJP = "リボンの結び目が少し歪んだ、質素な贈り物の箱。そのすぐ隣には、帝国最高級の鎮痛剤の瓶が置かれている。\nそして、箱の中に入れられなかった一枚の紙片。そこには、こう綴られていた――「早く元気になりますように」",
          DialogueId = 70016005,
          GUID = "AF4718D2"
        },
        [70016006] = {
          Camera = "-35.015625,151.625,225.035156,0.000034,-14.798724,-71.592674,35.0,100000.0,false,Manual,22.0",
          ContentJP = "内城の城壁の下で撮られた、姉弟の記念写真。写真の右上には「リズム・フィッシャー」と「ブルース・フィッシャー」の名が記され、弟・ブルースが第六軍団の試験に合格したことを祝う言葉が添えられている。",
          DialogueId = 70016006,
          GUID = "AF4718FC"
        },
        [70016007] = {
          Camera = "36.316406,112.411133,226.279297,0.00002,-31.198172,-98.592926,35.0,100000.0,false,Manual,22.0",
          ContentJP = "長い間使われた形跡のないハーモニカ。リズムの趣味というより、誰かから贈られたもののようだ。",
          DialogueId = 70016007,
          GUID = "AF471926"
        },
        [70016008] = {
          ContentJP = "石灰の壁の一角には、小刀でびっしりと刻まれた言葉が並んでいる。歪んだ字もあれば、幼い子どもの筆跡のようなものもある。一方で、しっかりとした大人の手による文字も見受けられる。だが、刻まれている内容は全て同じだ――\n「もう二度と、<Default note=\"text:エジュウ\">穢獣</>に殺される人を見過ごしたりしない」",
          DialogueId = 70016008,
          GUID = "AF471950"
        },
        [70016009] = {
          ContentJP = "ガレア劇団の道具リスト\n\n多くの裏方スタッフが記録した準備リスト。過去半月分の小道具の出入りが詳細に記録されている。\n\n10月8日：衣装、寝袋の準備完了。担当者：モンドリ。備考：食料が不足しているため、<H>次の集中リハーサル用に追加の食料を用意する必要あり。</>\n…………\n11月12日：新しいマイク3本の交換完了。担当者：グリンド。備考：1本は音が非常に大きいと座長に指摘されたが、そのまま使用を続行すること。\n11月14日：赤い幕布の交換完了。金色の幕布は倉庫に保管。担当者：ベル。\n…………\n11月24日：紛失した5つのかつらを回収完了。担当者：ベル。備考：更衣室の隅は物が溜まりやすい。本日清掃を行うことにする。\n11月25日：花冠15個、乗馬靴9足の準備完了。担当者：モンドリ",
          DialogueId = 70016009,
          GUID = "AF47197A"
        },
        [70016010] = {
          ContentJP = "劇場の幕とよく似た材質の布。古びているが、とても清潔に保たれている。誰かが丁寧に手入れをしたのだろう。\n注意深く観察し、触れてみると、襲撃現場で見つかった幕と同じ布であることが分かる。",
          DialogueId = 70016010,
          GUID = "AF4719A4"
        },
        [70016011] = {
          ContentJP = "古びたマネキン。その着こなしやポーズには明らかに工夫が施されており、端正で優雅な印象を与えている。",
          DialogueId = 70016011,
          GUID = "AF4719CE"
        },
        [70016012] = {
          ContentJP = "周囲には巨大で無数の爪痕が残されており、怪物の巣でなくとも頻繁に活動していた痕跡が伺える。この地が第十三軍団によって封鎖区域に指定された理由の一つと考えられる。",
          DialogueId = 70016012,
          GUID = "AF4719F8"
        },
        [70016013] = {
          ContentJP = "アイスレイク城・地下水路の一部のレイアウト図。迷路のように入り組んだ配管が各区域を結んでおり、多くの場所に「警備部隊の許可なく立ち入り禁止」と記された標識が描かれている。",
          DialogueId = 70016013,
          GUID = "AF471A22"
        },
        [70016101] = {
          Camera = "-15.959961,1605.265137,1322.948242,0.000059,-29.399687,-89.596825,20.875948,100000.0,false,Manual,22.0",
          ContentJP = "砲台搬送装置の動力供給には、4本のケーブルを接続する必要がある。",
          DialogueId = 70016101,
          GUID = "AF472892",
          NextDialogue = 70016102
        },
        [70016102] = {
          Camera = "224.294922,655.639038,672.151611,0.000109,-27.999538,-125.796112,20.875948,100000.0,false,Manual,22.0",
          ContentJP = "1本はすでに接続済みだ。",
          DialogueId = 70016102,
          GUID = "AF4728BC",
          NextDialogue = 70016103
        },
        [70016103] = {
          Camera = "-1774.869141,-1374.734619,1171.844727,0.000131,-33.399078,23.004192,20.875948,100000.0,false,Manual,22.0",
          ContentJP = "残る3本のケーブルを辿り、イコル駆動輪を探して接続しよう。",
          DialogueId = 70016103,
          GUID = "AF4728E6"
        },
        [70016104] = {
          Camera = "-5344.007812,-255.292114,647.478394,0.000156,-14.998623,83.199738,20.875948,100000.0,false,Manual,22.0",
          ContentJP = "<H>第1グループ</>のイコル駆動輪を発見。<H>特定の時間</>内に起動する必要がありそうだ。",
          DialogueId = 70016104,
          GUID = "AF472910"
        },
        [70016105] = {
          Camera = "5543.811523,-2108.574219,180.364319,0.000151,-3.998317,-104.994102,20.875948,100000.0,false,Manual,22.0",
          ContentJP = "近づけそうにない。<H>遠隔</>でイコル駆動輪を作動させる方法はないだろうか？",
          DialogueId = 70016105,
          GUID = "AF47293A"
        },
        [70016106] = {
          Camera = "157.341797,-91.314453,242.558594,0.0,-60.19952,101.398407,16.122608,100000.0,false,Manual,22.0",
          ContentJP = "見覚えのない顔だ。",
          DialogueId = 70016106,
          GUID = "AF472964"
        },
        [70016107] = {
          Camera = "-71.794922,628.722656,135.195312,0.000076,12.199674,-90.596268,17.78793,100000.0,false,Manual,22.0",
          ContentJP = "\n※「<Default note=\"text:ナーファル\">一角鯨</>」隊の兵士ケイルムの証言\n「中央制御室から{nickname2}隊長が一人で▇▇▇から出てくるのを見た。胸に大量の▇▇▇▇が付いていた」\n「{性别2:彼|彼女}は『▇▇▇▇で待機せよ』と指示し、自分は▇▇▇▇に潜む同盟メンバーを探すと言った」\n「数分後、警報が鳴ったため▇▇▇▇に戻った。そこには血まみれのアヴァール隊長が倒れており、▇▇▇▇が起動していた」",
          DialogueId = 70016107,
          GUID = "AF47298E"
        },
        [70016108] = {
          ContentJP = "兵士たちはすでに息絶えている。",
          DialogueId = 70016108,
          GUID = "AF4729B8"
        },
        [70016109] = {
          ContentJP = "穢獣の死骸――これらの怪物が若き兵士たちの命を奪った。だが、兵士たちも最後の瞬間に、獣たちに致命の一撃を刻んでいた。",
          DialogueId = 70016109,
          GUID = "AF4729E2"
        },
        [70016110] = {
          Camera = "129.879883,311.569336,152.664062,0.000072,3.399556,-2.996889,17.78793,100000.0,false,Manual,22.0",
          ContentJP = "※{nickname2}の家族調査\n{nickname2}は3年前の「▇▇▇▇」時、▇▇▇▇から生還した人物。自身は記憶喪失を主張するが、思考は明晰。しかし、他の生存者によれば、{nickname2}は本来あの▇▇▇▇に乗っていなかった。\nすなわち<H>は{性别2:彼|彼女}正真正銘の「幽霊乗客」</>だった。\n十三軍団による徹底調査でも正体は特定できず、▇▇▇▇の可能性は排除。\n周囲の砲撃から逃れるために▇▇▇▇に隠れ、負傷して記憶を失ったと推測される。",
          DialogueId = 70016110,
          GUID = "AF47298F"
        },
        [71000000] = {
          ContentJP = "ニャー……",
          DialogueId = 71000000,
          Duration = 3,
          GUID = "B1BDB580",
          SpeakNpcId = 800002
        },
        [71000100] = {
          ContentJP = "野良猫が寂しそうに鳴いている。誰かのぬくもりを求めているのかもしれない。",
          DialogueId = 71000100,
          GUID = "B1BDC5E8",
          SpeakNpcId = 800006
        },
        [71000200] = {
          ContentJP = "すみません、ここでキャットフードは売っていますか？",
          DialogueId = 71000200,
          GUID = "B1BDD650",
          NextDialogue = 710002001,
          SpeakNpcId = 100001
        },
        [71000210] = {
          ContentJP = "すみません、ここでキャットフードは売っていますか？",
          DialogueId = 71000210,
          GUID = "B1BDD7F4",
          NextDialogue = 710002101,
          SpeakNpcId = 100001
        },
        [71000220] = {
          ContentJP = "（キャットフードを置く）",
          DialogueId = 71000220,
          GUID = "B1BDD998",
          NextDialogue = 710002201,
          SpeakNpcId = 100001
        },
        [71000300] = {
          ContentJP = "（野良猫は少し跳ねるように走り出し、立ち止まってこちらを振り返った。まるで「ついておいで」と言わんばかりだ。）",
          DialogueId = 71000300,
          Duration = 3,
          GUID = "B1BDE6B8",
          SpeakNpcId = 800006
        },
        [71000310] = {
          ContentJP = "（野良猫は少し跳ねるように走り出し、立ち止まってこちらを振り返った。まるで「ついておいで」と言わんばかりだ。）",
          DialogueId = 71000310,
          Duration = 3,
          GUID = "B1BDE85C",
          SpeakNpcId = 800006
        },
        [71000320] = {
          ContentJP = "（野良猫は少し跳ねるように走り出し、立ち止まってこちらを振り返った。まるで「ついておいで」と言わんばかりだ。）",
          DialogueId = 71000320,
          Duration = 3,
          GUID = "B1BDEA00",
          SpeakNpcId = 800006
        },
        [71000330] = {
          ContentJP = "（野良猫は嬉しそうに足元をぐるぐると回った。その満足げな表情を見ていると、こちらの心も癒されていく。）",
          DialogueId = 71000330,
          GUID = "B1BDEBA4",
          SpeakNpcId = 800006
        },
        [71000501] = {
          ContentJP = "もう勘弁して！これ以上やったら必殺技を使っちゃうよ……よーし、ほんとに使うからね……たすけてえええええ！！！",
          DialogueId = 71000501,
          Duration = 3,
          GUID = "B1BE07B2",
          SpeakNpcId = 800005
        },
        [71000502] = {
          ContentJP = "うわあああ……",
          DialogueId = 71000502,
          Duration = 3,
          GUID = "B1BE07DC",
          SpeakNpcId = 800005
        },
        [71000503] = {
          ContentJP = "これで最後だ。片付いたね。",
          DialogueId = 71000503,
          GUID = "B1BE0806",
          SpeakNpcId = 818014
        },
        [71000504] = {
          ContentJP = "周りに敵がいないか見てくる。気をつけて。",
          DialogueId = 71000504,
          GUID = "B1BE0830",
          NextDialogue = 71000505,
          SpeakNpcId = 818014
        },
        [71000505] = {
          ContentJP = "了解した。気をつけるよ。",
          DialogueId = 71000505,
          GUID = "B1BE085A",
          NextDialogue = 71000506,
          SpeakNpcId = 818015
        },
        [71000506] = {
          ContentJP = "あ、来てくれたんだ。うぅ……こんなにたくさんの人が助けてくれるなんて……これ、みんなへのお礼だよ。これからよろしく頼んでいいかな？かな？",
          DialogueId = 71000506,
          GUID = "B1BE0884",
          Scripts = "TurnTo{TurnToDescription{\"818015:n(0)\"}}",
          SpeakNpcId = 818015
        },
        [71000511] = {
          Camera = "182.995117,-239.510742,101.057129,0.000077,-2.797147,129.385254,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ありがとう！探検家の大ピンチ脱出！冒険を続けるよ。",
          DialogueId = 71000511,
          GUID = "B1BE0956",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000512] = {
          Camera = "125.800781,-57.036377,76.0,0.000008,0.0,155.202805,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ありがとう！探検家の大ピンチ脱出！冒険の続きに行ってくるね！",
          DialogueId = 71000512,
          GUID = "B1BE0980",
          SpeakNpcId = 800005,
          TalkActionId = {
            [1] = "800005:Confident_Start"
          }
        },
        [71000601] = {
          ContentJP = "（波に流されて打ち上げられた樽が砂浜に積み重なっている。何か使えるものが見つかるかもしれない。）",
          DialogueId = 71000601,
          Duration = 3,
          GUID = "B1BE181A",
          SpeakNpcId = 800006
        },
        [71000612] = {
          ContentJP = "（樽の底には大きな穴が開いている。かつてどんな宝物が入っていたとしても、今はただのガラクタだ。ほかの樽を探してみよう。）",
          DialogueId = 71000612,
          GUID = "B1BE19E8"
        },
        [71000613] = {
          ContentJP = "（樽の中には腐った魚とエビしか入っていない。ほかの樽を探してみよう。）",
          DialogueId = 71000613,
          GUID = "B1BE1A12"
        },
        [71000615] = {
          ContentJP = "努力は報われる。よく探した結果、ようやく樽の二重底から使えそうな物資を見つけた。",
          DialogueId = 71000615,
          GUID = "B1BE1A66"
        },
        [71000701] = {
          ContentJP = "困ったなぁ。残りはあと数本だけなんだか。",
          DialogueId = 71000701,
          Duration = 3,
          GUID = "B1BE2882",
          SpeakNpcId = 800007
        },
        [71000710] = {
          ContentJP = "どうしたんですか？",
          DialogueId = 71000710,
          GUID = "B1BE29FC",
          NextDialogue = 71000711,
          SpeakNpcId = 100001
        },
        [71000711] = {
          ContentJP = "ああ、街のイコルパイプが壊れていないか点検しないといけなくてね。",
          DialogueId = 71000711,
          Duration = 3,
          GUID = "B1BE2A26",
          NextDialogue = 71000721,
          SpeakNpcId = 800007
        },
        [71000721] = {
          ContentJP = "さっきのパイプを点検中に作業用のロープが切れてしまってね。すまないが、残りのパイプを見てきてくれないかい？",
          DialogueId = 71000721,
          Duration = 3,
          GUID = "B1BE2BCA",
          NextOptions = {
            [1] = 710007210,
            [2] = 710007211
          },
          SpeakNpcId = 800007
        },
        [71000741] = {
          ContentJP = "残りのパイプには印をつけておいたよ。助かるよ、ありがとう！",
          DialogueId = 71000741,
          Duration = 3,
          GUID = "B1BE2F12",
          SpeakNpcId = 800007
        },
        [71000751] = {
          ContentJP = "（このパイプに異常はないな。次のパイプを確認しよう。）",
          DialogueId = 71000751,
          Duration = 2,
          GUID = "B1BE30B6",
          SpeakNpcId = 800006
        },
        [71000761] = {
          ContentJP = "（最後のパイプも問題なかった。作業員に報告しに戻ろう。）",
          DialogueId = 71000761,
          GUID = "B1BE325A",
          SpeakNpcId = 800006
        },
        [71000771] = {
          ContentJP = "問題なかったか？ そうか、本当にありがとう！",
          DialogueId = 71000771,
          GUID = "B1BE33FE",
          SpeakNpcId = 800007
        },
        [71000780] = {
          ContentJP = "（このパイプに少し損傷があるな。作業員に報告しに戻ろう。）",
          DialogueId = 71000780,
          GUID = "B1BE3578",
          SpeakNpcId = 800006
        },
        [71000781] = {
          ContentJP = "はぁ……また残業か。工具を取りに戻るから、この鍵を使ってイコルパイプの元栓を止めておいてくれないか。",
          DialogueId = 71000781,
          GUID = "B1BE35A2",
          SpeakNpcId = 800007
        },
        [71000782] = {
          ContentJP = "ありがとう。あとは任せてくれ。",
          DialogueId = 71000782,
          GUID = "B1BE35CC",
          SpeakNpcId = 800007
        },
        [71000801] = {
          ContentJP = "{nickname}！はやくはやく！新しい研究対象を見つけたんだ！",
          DialogueId = 71000801,
          Duration = 3,
          GUID = "B1BE38EA",
          SpeakNpcId = 800011
        },
        [71000802] = {
          ContentJP = "今回のは湖の向こう岸にあって……だから、手伝ってくれない？",
          DialogueId = 71000802,
          Duration = 3,
          GUID = "B1BE3914",
          NextOptions = {
            [1] = 710008021,
            [2] = 710008022
          },
          SpeakNpcId = 800011
        },
        [71000803] = {
          ContentJP = "これがテオの言ってた研究対象かな。持っていってあげよう。",
          DialogueId = 71000803,
          Duration = 2,
          GUID = "B1BE393E",
          SpeakNpcId = 100001
        },
        [71000804] = {
          ContentJP = "ありがとう！偉大なる錬金術師になるには、まだ学ばなければならないものがたくさんあるな……",
          DialogueId = 71000804,
          Duration = 2,
          GUID = "B1BE3968",
          SpeakNpcId = 800011
        },
        [71000805] = {
          ContentJP = "……そっか、あんたの気持ちはよく分かったよ。偉大なる錬金術師への第一歩は自分で踏み出せって言いたいんでしょ？頑張るぞ！",
          DialogueId = 71000805,
          GUID = "B1BE3992",
          SpeakNpcId = 800011
        },
        [71000901] = {
          ContentJP = "かくれんぼ、かくれんぼ、みんなでかくれんぼしようよ！",
          DialogueId = 71000901,
          Duration = 3,
          GUID = "B1BE4952",
          SpeakNpcId = 800008
        },
        [71000902] = {
          ContentJP = "かくれんぼ、かくれんぼ、みんなでかくれんぼしようよ！",
          DialogueId = 71000902,
          GUID = "B1BE497C",
          NextDialogue = 71000903,
          Scripts = "SEQ{TurnTo{TurnToDescription{\"800008:n(0)\"}},LookAt{LookAtDescription{\"800008:n(0)\"}},PlayAnimation{ActorId{800008},AnimationId{\"Explain02_Start\"},Duration{1}}}",
          SpeakNpcId = 800008,
          TurnTo = {
            [1] = "800009:n(0)",
            [2] = "800010:n(0)"
          }
        },
        [71000903] = {
          ContentJP = "うん、いいよ！でも、鬼になるのはいやだな、隠れたいな。",
          DialogueId = 71000903,
          Duration = 3,
          GUID = "B1BE49A6",
          NextDialogue = 71000904,
          SpeakNpcId = 800009,
          TalkActionId = {
            [1] = "800009:Explain01_Start"
          }
        },
        [71000904] = {
          ContentJP = "僕もだよ。すっごくいい隠れ場所見つけたんだ。あそこなら絶対見つからない。",
          DialogueId = 71000904,
          Duration = 3,
          GUID = "B1BE49D0",
          NextDialogue = 71000905,
          SpeakNpcId = 800010,
          TalkActionId = {
            [1] = "800010:Talk03_Start"
          }
        },
        [71000905] = {
          ContentJP = "どうしよう？私たちとかくれんぼする人、ほかにいないかな……",
          DialogueId = 71000905,
          Duration = 3,
          GUID = "B1BE49FA",
          NextDialogue = 71000906,
          SpeakNpcId = 800009
        },
        [71000906] = {
          ContentJP = "（通りかかったあなたに気づいた子供たちは、期待の眼差しで返事を待っている。）",
          DialogueId = 71000906,
          Duration = 3,
          GUID = "B1BE4A24",
          SpeakNpcId = 800006
        },
        [71000907] = {
          ContentJP = "（子供たちは喜んで飛び跳ね、あっという間に街角に姿を消した。さて、どこを探せばいいか考えてみよう。）",
          DialogueId = 71000907,
          GUID = "B1BE4A4E"
        },
        [71000908] = {
          ContentJP = "わぁ、こんなに早く見つかっちゃった。",
          DialogueId = 71000908,
          GUID = "B1BE4A78",
          SpeakNpcId = 800008
        },
        [71000909] = {
          ContentJP = "すごいね！",
          DialogueId = 71000909,
          Duration = 2,
          GUID = "B1BE4AA2",
          SpeakNpcId = 800009
        },
        [71000910] = {
          ContentJP = "もう、負けちゃった……",
          DialogueId = 71000910,
          Duration = 2,
          GUID = "B1BE4ACC",
          SpeakNpcId = 800010
        },
        [71000911] = {
          ContentJP = "はいはい、約束だもんね。これお礼だよ。また遊んでね！",
          DialogueId = 71000911,
          Duration = 2,
          GUID = "B1BE4AF6",
          SpeakNpcId = 800008
        },
        [71001001] = {
          ContentJP = "新しい車だ。もしかしたら……一儲けのチャンスかも？",
          DialogueId = 71001001,
          Duration = 3,
          GUID = "B1BE59BA",
          SpeakNpcId = 800006
        },
        [71001002] = {
          ContentJP = "（車のイコルエネルギー装置が満タンだ。やはりひと儲けできるチャンスのようだ）",
          DialogueId = 71001002,
          GUID = "B1BE59E4",
          SpeakNpcId = 800006
        },
        [71001003] = {
          ContentJP = "おい、何をしている！誰か来てくれ！",
          DialogueId = 71001003,
          Duration = 2,
          GUID = "B1BE5A0E",
          SpeakNpcId = 818010
        },
        [71001004] = {
          ContentJP = "（もう邪魔する者はいない。車の鍵を開け、イコル液の詰まったエネルギー装置を持ち去り、いい値で売りさばこう。すべては計画通りだ。今日も気分のいい一日になりそうだ。）",
          DialogueId = 71001004,
          Duration = 4,
          GUID = "B1BE5A38",
          SpeakNpcId = 800006
        },
        [71001005] = {
          ContentJP = "良心が欲に打ち勝った。あなたは車両の警備に不備があることを、城門の護衛に報告することにした。",
          DialogueId = 71001005,
          Duration = 3,
          GUID = "B1BE5A62",
          SpeakNpcId = 800006
        },
        [71001006] = {
          ContentJP = "ご報告に感謝します。すぐに警備を強化します。つまらないものですが、お礼の品をお受け取りください。",
          DialogueId = 71001006,
          GUID = "B1BE5A8C",
          SpeakNpcId = 818010
        },
        [71001101] = {
          ContentJP = "（<Default note=\"text:エジュウ\">穢獣</>襲来、撃退しろ！）",
          DialogueId = 71001101,
          Duration = 3,
          GUID = "B1BE6A22",
          SpeakNpcId = 800006
        },
        [71001201] = {
          ContentJP = "あなたとベレの痕跡は、すっかり雑草に覆われていた。そろそろ、この神像のまわりの草むしりをするべきなのかもしれない。",
          DialogueId = 71001201,
          Duration = 2,
          GUID = "B1BE7A8A",
          SpeakNpcId = 800006
        },
        [71001202] = {
          ContentJP = "努力の甲斐あって、神像の周辺は、記憶にある、整然とした景色に戻った。",
          DialogueId = 71001202,
          GUID = "B1BE7AB4",
          SpeakNpcId = 800006
        },
        [71001301] = {
          ContentJP = "ベレは、昔ここに{性别:僕|私}たちが住んでいたというけれど、まったく覚えていない……\n",
          DialogueId = 71001301,
          GUID = "B1BE8AF2",
          NextDialogue = 71001302,
          SpeakNpcId = 100001
        },
        [71001302] = {
          ContentJP = "このあたりを少し歩いてみれば、何か思い出すかもしれない。",
          DialogueId = 71001302,
          GUID = "B1BE8B1C",
          SpeakNpcId = 100001
        },
        [71001303] = {
          ContentJP = "家具の作りはとても乱暴で、多くの釘が木の中に深く打ち込まれている。村で私たちが使っていた扉の取っ手と同じだ。……ベレは子供の頃からこんなに力があったのかな。",
          DialogueId = 71001303,
          GUID = "B1BE8B46"
        },
        [71001304] = {
          ContentJP = "これは……錬金術に関する物語の本？子供の頃、眠る前にベレガ{性别:僕|私}に聞かせてくれた奇妙なお話は、この本から来ていた{性别:んだ|のね}。",
          DialogueId = 71001304,
          GUID = "B1BE8B70",
          NextDialogue = 71001305
        },
        [71001305] = {
          ContentJP = "でも、この本に書かれている注釈はベレの字よりもずっと整然としている。誰が書いたのかな?",
          DialogueId = 71001305,
          GUID = "B1BE8B9A"
        },
        [71001306] = {
          ContentJP = "ベレのことはたくさん思い出したけど、ここについては全然思い出せない……",
          DialogueId = 71001306,
          GUID = "B1BE8BC4",
          NextDialogue = 71001307,
          SpeakNpcId = 100001
        },
        [71001307] = {
          ContentJP = "まあ、そのうち自然に思い出せるかも。",
          DialogueId = 71001307,
          GUID = "B1BE8BEE",
          SpeakNpcId = 100001
        },
        [71001401] = {
          ContentJP = "（遠くからアイスベリーの香りが漂ってきたな。摘んで売れば、いい値段になるだろう。）",
          DialogueId = 71001401,
          Duration = 4,
          GUID = "B1BE9B5A",
          SpeakNpcId = 800006
        },
        [71001402] = {
          ContentJP = "（このアイスベリーは色も鮮やかで実も大きい。誰が見ても、素晴らしい極上品だ。）",
          DialogueId = 71001402,
          Duration = 4,
          GUID = "B1BE9B84",
          SpeakNpcId = 800006
        },
        [71001403] = {
          ContentJP = "（遠くに二人の商人がアイスベリーを買い取っているようだ。二人と話してから、どちらに売るか決めよう。）",
          DialogueId = 71001403,
          Duration = 4,
          GUID = "B1BE9BAE",
          SpeakNpcId = 800006
        },
        [71001404] = {
          ContentJP = "この小さな店をアイスレイクで何年もやってるんだ。儲けは少ないけど、お客さんはみんな顔なじみさ。このアイスベリー、全部引き取らせてもらうよ。これも縁だ。みんなアイスレイクに住んでるんだから、これからも互いに助け合いでやっていこうよ。",
          DialogueId = 71001404,
          GUID = "B1BE9BD8",
          NextOptions = {
            [1] = 710014041,
            [2] = 710014042
          },
          SpeakNpcId = 818002
        },
        [71001405] = {
          ContentJP = "おや、その懐のアイスベリー、うちの店ならアイスレイクのあの貧乏商人たちより高い値段で買い取るよ。どうだい、一緒に一儲けしないか？",
          DialogueId = 71001405,
          GUID = "B1BE9C02",
          NextOptions = {
            [1] = 710014051,
            [2] = 710014052
          },
          SpeakNpcId = 818003
        },
        [71001406] = {
          ContentJP = "（利益よりも長く付き合える人脈を選んで、地元の商人と取引を済ませた。）",
          DialogueId = 71001406,
          Duration = 3,
          GUID = "B1BE9C2C",
          SpeakNpcId = 800006
        },
        [71001407] = {
          ContentJP = "（将来の約束より目の前の利益のほうが確実だ。よそ者の商人と取引を済ませ、報酬をたっぷり手に入れた。）",
          DialogueId = 71001407,
          Duration = 4,
          GUID = "B1BE9C56",
          SpeakNpcId = 800006
        },
        [71001501] = {
          ContentJP = "はぁ……また故障かよ……",
          DialogueId = 71001501,
          Duration = 3,
          GUID = "B1BEABC2",
          SpeakNpcId = 818006
        },
        [71001502] = {
          ContentJP = "どうしたんですか？",
          DialogueId = 71001502,
          GUID = "B1BEABEC",
          NextDialogue = 71001503,
          SpeakNpcId = 100001
        },
        [71001503] = {
          ContentJP = "この機械、俺じゃうまく扱えなくて。よかったらきみが試してくれないか？機械の問題なのか、俺の問題なのか確かめたいんだ。",
          DialogueId = 71001503,
          GUID = "B1BEAC16",
          SpeakNpcId = 818006
        },
        [71001504] = {
          ContentJP = "ありがとう。",
          DialogueId = 71001504,
          Duration = 2,
          GUID = "B1BEAC40",
          SpeakNpcId = 818006
        },
        [71001505] = {
          ContentJP = "すごいじゃないか！はぁ、やっぱり俺の使い方が悪かったんだな……",
          DialogueId = 71001505,
          GUID = "B1BEAC6A",
          SpeakNpcId = 818006
        },
        [71001506] = {
          ContentJP = "え？そんなので直るの？",
          DialogueId = 71001506,
          Duration = 2,
          GUID = "B1BEAC94",
          SpeakNpcId = 818006
        },
        [71001507] = {
          ContentJP = "えっと……本当にたたくだけで直るのか？",
          DialogueId = 71001507,
          Duration = 2,
          GUID = "B1BEACBE",
          SpeakNpcId = 818006
        },
        [71001508] = {
          ContentJP = "おい、今、部品がふっ飛んだ気がするんだが……",
          DialogueId = 71001508,
          Duration = 2,
          GUID = "B1BEACE8",
          SpeakNpcId = 818006
        },
        [71001509] = {
          ContentJP = "すごいな！本当に直ったぞ！",
          DialogueId = 71001509,
          GUID = "B1BEAD12",
          SpeakNpcId = 818006
        },
        [71001601] = {
          ContentJP = "<Default note=\"text:エジュウ\">穢獣</>がたくさんいるよ……どうしよう……",
          DialogueId = 71001601,
          Duration = 3,
          GUID = "B1BEBC2A",
          SpeakNpcId = 818004
        },
        [71001602] = {
          ContentJP = "何があったんですか？",
          DialogueId = 71001602,
          GUID = "B1BEBC54",
          NextDialogue = 71001603,
          SpeakNpcId = 100001
        },
        [71001603] = {
          ContentJP = "わっ、その格好からしてすごく強い月狩り人さんですよね！あの……実は私も月狩り人なんです。でも、私は弱くて……",
          DialogueId = 71001603,
          GUID = "B1BEBC7E",
          NextDialogue = 71001604,
          SpeakNpcId = 818004
        },
        [71001604] = {
