        },
        [71002304] = {
          ContentJP = "15秒ほどでいい。頼んだぜ！",
          DialogueId = 71002304,
          GUID = "B1BF2F80",
          SpeakNpcId = 818020
        },
        [71002305] = {
          ContentJP = "全部躱しやがった……エリュシオンから奪った宝物だと聞いたが、どうみてもただのガラクタじゃねぇか――あ、いや、なんでもねぇよ。ほら、金だ。このことは誰にも言うんじゃねぇぞ。",
          DialogueId = 71002305,
          GUID = "B1BF2FAA",
          SpeakNpcId = 818020
        },
        [71002306] = {
          ContentJP = "命中したってのに、ピンピンしてやがる……エリュシオンから奪った宝物だと聞いたが、本当か？……あ、いや、なんでもねぇよ。ほら、金だ。このことは誰にも言うんじゃねぇぞ。",
          DialogueId = 71002306,
          GUID = "B1BF2FD4",
          SpeakNpcId = 818020
        },
        [71002401] = {
          ContentJP = "探査機め、使う前から壊れるなんてどういうこと！？ええと、修理道具はっと……",
          DialogueId = 71002401,
          GUID = "B1BF3F6A",
          SpeakNpcId = 818015
        },
        [71002402] = {
          ContentJP = "ここで会えるなんて、これも何かの縁だね！せっかくだし、うちのお宝探査機を見ててくれない？",
          DialogueId = 71002402,
          GUID = "B1BF3F94",
          SpeakNpcId = 818015
        },
        [71002403] = {
          ContentJP = "サンキュー！じゃあ、そこで待ってて。使える道具を見つけたら、すぐに戻ってくるから！",
          DialogueId = 71002403,
          GUID = "B1BF3FBE",
          NextDialogue = 71002404,
          SpeakNpcId = 818015
        },
        [71002404] = {
          ContentJP = "（部品がいくつか引っかかってるようだ。うまく外せば、修理しやすくなるはず。）",
          DialogueId = 71002404,
          GUID = "B1BF3FE8",
          SpeakNpcId = 100001
        },
        [71002405] = {
          ContentJP = "探査機の音に、周囲の<Default note=\"text:エジュウ\">穢獣</>が集まってきてしまった。退治しよう！",
          DialogueId = 71002405,
          GUID = "B1BF4012",
          SpeakNpcId = 800006
        },
        [71002406] = {
          ContentJP = "あれ、引っかかってた部品を外してくれたの！？ちょっと感動だよ！！",
          DialogueId = 71002406,
          GUID = "B1BF403C",
          SpeakNpcId = 818015
        },
        [71002407] = {
          ContentJP = "おまたせ！あなたに任せたのは正解だったようだね！",
          DialogueId = 71002407,
          GUID = "B1BF4066",
          SpeakNpcId = 818015
        },
        [71002501] = {
          ContentJP = "はぁ……また詰まっちまったぜ",
          DialogueId = 71002501,
          GUID = "B1BF4FD2",
          SpeakNpcId = 818021
        },
        [71002502] = {
          ContentJP = "どうしたの？",
          DialogueId = 71002502,
          GUID = "B1BF4FFC",
          NextDialogue = 71002503,
          SpeakNpcId = 100001
        },
        [71002503] = {
          ContentJP = "ここ一帯の下水道が詰まっちまったんだよ。長官から説明書をもらったんだが、まったく理解できねぇ……手を貸してくれるか？",
          DialogueId = 71002503,
          GUID = "B1BF5026",
          NextOptions = {
            [1] = 710025041,
            [2] = 710025042
          },
          SpeakNpcId = 818021
        },
        [71002505] = {
          ContentJP = "説明書には「下水道が詰まった場合は、三つの水門を開けて、勢いよく水を流せば解消できる」と書いてある。",
          DialogueId = 71002505,
          GUID = "B1BF507A",
          NextDialogue = 71002511,
          SpeakNpcId = 100001
        },
        [71002507] = {
          ContentJP = "了解！2つ目はあっちだ。",
          DialogueId = 71002507,
          GUID = "B1BF50CE",
          SpeakNpcId = 818021
        },
        [71002508] = {
          ContentJP = "3つ目は……あった！あそこだ！",
          DialogueId = 71002508,
          GUID = "B1BF50F8",
          SpeakNpcId = 818021
        },
        [71002509] = {
          ContentJP = "よし、もうバッチリ覚えたぜ！これ、ほんの気持ちだけど……ありがとうな！",
          DialogueId = 71002509,
          GUID = "B1BF5122",
          SpeakNpcId = 818021
        },
        [71002510] = {
          ContentJP = "へえ、あんたのやり方、なかなか悪くないな。ほら、報酬だ。",
          DialogueId = 71002510,
          GUID = "B1BF514C",
          SpeakNpcId = 818021
        },
        [71002511] = {
          ContentJP = "なるほどな。じゃあ、ちょっとやり方を見せてもらってもいいか？見ながら覚えるからさ。",
          DialogueId = 71002511,
          GUID = "B1BF507B",
          SpeakNpcId = 818021
        },
        [71002601] = {
          ContentJP = "ちくしょう、このツルハシ脆すぎだろ……残りの岩、どうすんだよ。まさか素手で掘れってか……",
          DialogueId = 71002601,
          GUID = "B1BF603A",
          SpeakNpcId = 818023
        },
        [71002602] = {
          ContentJP = "その身なり……あんたも月狩り人か。実は石を掘る依頼を引き受けたんだけど、一人じゃどうも手に負えなくてな。一緒にやらねぇか？報酬は半分分けてやるからさ。",
          DialogueId = 71002602,
          GUID = "B1BF6064",
          NextOptions = {
            [1] = 710026021,
            [2] = 710026022
          },
          SpeakNpcId = 818023,
          bForbidSkipOptions = true
        },
        [71002603] = {
          ContentJP = "よし、じゃあ残りの採掘は頼むぜ。俺はさっき堀り出した石を整理しとくから。",
          DialogueId = 71002603,
          GUID = "B1BF608E",
          SpeakNpcId = 818023
        },
        [71002604] = {
          ContentJP = "その手があったか！あんた賢いな！！",
          DialogueId = 71002604,
          GUID = "B1BF60B8",
          NextDialogue = 71002605,
          SpeakNpcId = 818023
        },
        [71002605] = {
          ContentJP = "ご苦労様。約束の報酬だ。",
          DialogueId = 71002605,
          GUID = "B1BF60E2",
          SpeakNpcId = 818023
        },
        [71002701] = {
          ContentJP = "いくつかの木樽水路を伝って流れてきた。中には不気味な音を立てているものもある。慎重に開ければ、役に立つものが見つかるかもしれない。",
          DialogueId = 71002701,
          GUID = "B1BF70A2",
          SpeakNpcId = 800006
        },
        [71002702] = {
          ContentJP = "樽の底に大きな穴が開いていて、風が通り抜けるヒュウヒュウという音しか聞こえない。役に立ちそうなものは何も見つからなかった。他の樽も見てみよう。",
          DialogueId = 71002702,
          GUID = "B1BF70CC",
          SpeakNpcId = 800006
        },
        [71002703] = {
          ContentJP = "樽の中にはゴミが詰まっていた。ブクブクと鈍い音を立てながら、鼻をつく悪臭が漂ってきた。他の樽を見てみよう。",
          DialogueId = 71002703,
          GUID = "B1BF70F6",
          SpeakNpcId = 800006
        },
        [71002704] = {
          ContentJP = "やっぱり、努力は報われるものだ。念入りに探ったおかげで、樽の二重底から使えそうな物資を見つけた。",
          DialogueId = 71002704,
          GUID = "B1BF7120",
          SpeakNpcId = 800006
        },
        [71002705] = {
          ContentJP = "ボロボロの木樽が派手な音を立てて崩れ落ちた。その音で周囲の<Default note=\"text:エジュウ\">穢獣</>が集まってきてしまった。奴らを倒して、戦利品を手に入れよう。",
          DialogueId = 71002705,
          GUID = "B1BF714A",
          SpeakNpcId = 800006
        },
        [71002801] = {
          ContentJP = "崩れ落ちた瓦礫が道を塞いでいる。片づけて道を開こう。",
          DialogueId = 71002801,
          GUID = "B1BF810A",
          SpeakNpcId = 800006
        },
        [71002802] = {
          ContentJP = "瓦礫を片付けてる最中に、使えそうなものをいくつか見つけた。さっそく回収しよう。",
          DialogueId = 71002802,
          GUID = "B1BF8134",
          SpeakNpcId = 800006
        },
        [71002803] = {
          ContentJP = "瓦礫を整理する音に、周囲の<Default note=\"text:エジュウ\">穢獣</>が集まってきてしまった。頭上の岩を利用して、退治しよう。",
          DialogueId = 71002803,
          GUID = "B1BF815E",
          SpeakNpcId = 800006
        },
        [71002804] = {
          ContentJP = "戦闘の末、使える物資をいくつか見つけた。さっそく回収しよう。",
          DialogueId = 71002804,
          GUID = "B1BF8188",
          SpeakNpcId = 800006
        },
        [71002901] = {
          ContentJP = "（司令官に率いられた敵が着々と迫ってくる。司令官を倒して、敵の陣形を崩そう。）",
          DialogueId = 71002901,
          GUID = "B1BF9172",
          SpeakNpcId = 800006
        },
        [71002902] = {
          ContentJP = "（あなたの冷静な判断と的確な対応で、敵は崩れ去った。）",
          DialogueId = 71002902,
          GUID = "B1BF919C",
          SpeakNpcId = 800006
        },
        [71002903] = {
          ContentJP = "（司令官が援軍を要請した。新手の敵が押し寄せてくる。）",
          DialogueId = 71002903,
          GUID = "B1BF91C6",
          SpeakNpcId = 800006
        },
        [71003001] = {
          ContentJP = "（<Default note=\"text:エジュウ\">穢獣</>たちが不気味に唸り、あたり不吉な気配が漂う。早くやつらを追い払おう。）",
          DialogueId = 71003001,
          GUID = "B1BFA1DA",
          SpeakNpcId = 800006
        },
        [71003002] = {
          ContentJP = "（この場に漂う不吉な気配が濃くなってきた。何かが、降り立とうとしている。）",
          DialogueId = 71003002,
          GUID = "B1BFA204",
          SpeakNpcId = 800006
        },
        [71003003] = {
          ContentJP = "（戦いの音が災いを呼び寄せ、不吉な化身が姿を現した。過去に何度もそうしてきたように、撃退しよう。）",
          DialogueId = 71003003,
          GUID = "B1BFA22E",
          SpeakNpcId = 800006
        },
        [71003004] = {
          ContentJP = "（<Default note=\"text:エジュウ\">穢獣</>と共に不吉な気配も消え去った。しばらくは、この辺りも安全だろう。）",
          DialogueId = 71003004,
          GUID = "B1BFA258",
          SpeakNpcId = 800006
        },
        [71003101] = {
          ContentJP = "最近、ジェネモンを狙う輩が増えてきている。今すぐ彼らを撃破し、可哀そうなジェネモンを救おう。",
          DialogueId = 71003101,
          GUID = "B1BFB242",
          SpeakNpcId = 800006
        },
        [71003102] = {
          ContentJP = "さらに多くの敵が、遠方から駆けつけてきた。",
          DialogueId = 71003102,
          GUID = "B1BFB26C",
          SpeakNpcId = 800006
        },
        [71003103] = {
          ContentJP = "このジェネモンはもう安全だ。",
          DialogueId = 71003103,
          GUID = "B1BFB296",
          SpeakNpcId = 800006
        },
        [71003201] = {
          ContentJP = "崩れ落ちた瓦礫が道を塞いでいる。この辺りに転がってる爆発物をうまく使えば、手っ取り早く片付けられるかも。",
          DialogueId = 71003201,
          GUID = "B1BFC2AA",
          SpeakNpcId = 800006
        },
        [71003202] = {
          ContentJP = "鉱夫たちが使ってた簡易な爆破マニュアルを見つけた。かなり汚れているが、ギリギリ内容が読める。",
          DialogueId = 71003202,
          GUID = "B1BFC2D4",
          SpeakNpcId = 800006
        },
        [71003203] = {
          ContentJP = "爆発物をいくつか見つけた。少し加工すれば使えるかも。",
          DialogueId = 71003203,
          GUID = "B1BFC2FE",
          SpeakNpcId = 800006
        },
        [71003204] = {
          ContentJP = "導火線をいくつか見つけた。少し加工すれば使えるかも。",
          DialogueId = 71003204,
          GUID = "B1BFC328",
          SpeakNpcId = 800006
        },
        [71003206] = {
          ContentJP = "マニュアル通りに爆発物を組み立てた。さっそく目の前の障害物を吹き飛ばそう。",
          DialogueId = 71003206,
          Duration = 3,
          GUID = "B1BFC37C",
          SpeakNpcId = 800006
        },
        [71003207] = {
          ContentJP = "瓦礫を片付けてる最中に、使えそうなものをいくつか見つけた。さっそく回収しよう。",
          DialogueId = 71003207,
          GUID = "B1BFC3A6",
          SpeakNpcId = 800006
        },
        [71003501] = {
          ContentJP = "遠くで何かが光っている……近くまで行って、確かめてみよう。",
          DialogueId = 71003501,
          GUID = "B1BFF3E2",
          SpeakNpcId = 800006
        },
        [71003502] = {
          ContentJP = "ほらな！この鏡を使えば月狩り人が釣れるって言っただろ！！",
          DialogueId = 71003502,
          GUID = "B1BFF40C",
          SpeakNpcId = 818028
        },
        [71003504] = {
          ContentJP = "や、やめてくれ……もう二度としませんから……",
          DialogueId = 71003504,
          GUID = "B1BFF460",
          SpeakNpcId = 818028
        },
        [71003601] = {
          ContentJP = "突如、四方から警報が鳴り響いた。次の瞬間、無数の磁気ドローンがなだれ込んできた。",
          DialogueId = 71003601,
          GUID = "B1C0044A",
          SpeakNpcId = 800006
        },
        [71003602] = {
          ContentJP = "警報はさらに激しく鳴り響き、敵がこちらへとなだれ込んできた。",
          DialogueId = 71003602,
          GUID = "B1C00474",
          SpeakNpcId = 800006
        },
        [71003603] = {
          ContentJP = "警報が徐々に静まっていく中、敵の集団は全員この場所に到達した。",
          DialogueId = 71003603,
          GUID = "B1C0049E",
          SpeakNpcId = 800006
        },
        [71003604] = {
          ContentJP = "すべての敵が倒れ、辺りはようやく静寂を取り戻した。",
          DialogueId = 71003604,
          GUID = "B1C004C8",
          SpeakNpcId = 800006
        },
        [71003701] = {
          ContentJP = "はぁ……仕事キライ……さぼりたい……",
          DialogueId = 71003701,
          GUID = "B1C014B2",
          SpeakNpcId = 818019
        },
        [71003702] = {
          ContentJP = "はぁ……なんで皆してダクリ湖に飯運ぶのさ。たまにはもっとマシな場所で食べられないの？危険だとか思うでしょ普通……もう、走りすぎて足ガクガクだよ……",
          DialogueId = 71003702,
          GUID = "B1C014DC",
          NextDialogue = 71003703,
          SpeakNpcId = 818019
        },
        [71003703] = {
          ContentJP = "手伝おっか？",
          DialogueId = 71003703,
          GUID = "B1C014DD",
          NextDialogue = 71003704,
          SpeakNpcId = 100001
        },
        [71003704] = {
          ContentJP = "お願い！！あの面倒くさい客どもに一発かましてよ！それと雪玉、いっぱいぶつけてやって！もう二度とあんなわけわかんない場所で出前なんて頼ませないんだから！",
          DialogueId = 71003704,
          GUID = "B1C014DE",
          NextOptions = {
            [1] = 710037041,
            [2] = 710037042
          },
          SpeakNpcId = 818019,
          bForbidSkipOptions = true
        },
        [71003705] = {
          ContentJP = "ったく……文句ぐらいしか言えないんだもん。来たなら付き合ってよ。ひとりよりマシだし。……んじゃ、しぶしぶ出発～、おしごとおしごと。",
          DialogueId = 71003705,
          GUID = "B1C01506",
          SpeakNpcId = 818019
        },
        [71003706] = {
          ContentJP = "うわ、こんな氷の破片が料理に入ったら大変だよ。どうにかして片づけられないかな～……",
          DialogueId = 71003706,
          GUID = "B1C01530",
          SpeakNpcId = 818019
        },
        [71003707] = {
          ContentJP = "えっ、もうっ！？料理もまだ冷めてない……よし、急ごう！また店長に小言言われる前に！",
          DialogueId = 71003707,
          GUID = "B1C01656",
          SpeakNpcId = 818019
        },
        [71003708] = {
          ContentJP = "助けてくれー！せめて腹いっぱい食わせてから殺して！",
          DialogueId = 71003708,
          GUID = "B1C0155A",
          NextDialogue = 71003709,
          SpeakNpcId = 818029
        },
        [71003709] = {
          ContentJP = "ほ～ら言わんこっちゃない！はやく助けてあげよ！店長の前で褒めてくれるかもしれないし。そんでもって……給料アップ……えへ、えへへ……",
          DialogueId = 71003709,
          GUID = "B1C01584",
          SpeakNpcId = 818019
        },
        [71003710] = {
          ContentJP = "邪魔者はいなくなったし、ダクリ湖の景色を眺めながら、出来立てホヤホヤの料理を堪能できるなんて……極楽極楽～",
          DialogueId = 71003710,
          GUID = "B1C015AE",
          NextDialogue = 71003711,
          SpeakNpcId = 818024
        },
        [71003711] = {
          ContentJP = "あ、その……お客さん、まだお代をいただいてないんだけど……",
          DialogueId = 71003711,
          GUID = "B1C015D8",
          NextDialogue = 71003712,
          SpeakNpcId = 818019
        },
        [71003712] = {
          ContentJP = "ん？ただの使いっ走りが、いつまでそこに突っ立ってるつもりだ？金なら今度店に行った時に払うよ。",
          DialogueId = 71003712,
          GUID = "B1C01602",
          NextDialogue = 71003713,
          SpeakNpcId = 818024
        },
        [71003713] = {
          ContentJP = "そんな……店長に怒られちゃうよ……",
          DialogueId = 71003713,
          Duration = 3,
          GUID = "B1C0162C",
          NextDialogue = 71003714,
          SpeakNpcId = 818019
        },
        [71003714] = {
          ContentJP = "全てを見ていたあなたは、誰にも気付かれずにそっと彼らに近づいた。その背中に隠した手には、ひとつの雪玉が静かに握られていた。あなたはグッと力を込めた。",
          DialogueId = 71003714,
          Duration = 4,
          GUID = "B1C0162D",
          NextDialogue = 71003715,
          SpeakNpcId = 800006
        },
        [71003715] = {
          ContentJP = "ぎゃっ！なんだこの雪玉は！！つ、冷たっ！ああああ！飯が湖に……！！",
          DialogueId = 71003715,
          GUID = "B1C0162E",
          SpeakNpcId = 818024
        },
        [71003801] = {
          ContentJP = "通路が<Default note=\"text:エジュウ\">穢獣</>の集団で塞がれている。退治しよう。",
          DialogueId = 71003801,
          GUID = "B1C0251A",
          SpeakNpcId = 800006
        },
        [71003802] = {
          ContentJP = "戦闘の音に引き寄せられ、さらに多くの<Default note=\"text:エジュウ\">穢獣</>が通路へとなだれ込んできた。はやく退治しよう。",
          DialogueId = 71003802,
          GUID = "B1C02544",
          SpeakNpcId = 800006
        },
        [71003803] = {
          ContentJP = "通路の<Default note=\"text:エジュウ\">穢獣</>はすべて排除された。これでひとまず安全だ。",
          DialogueId = 71003803,
          GUID = "B1C0256E",
          SpeakNpcId = 800006
        },
        [71003901] = {
          Content = "房间中传来一股肃杀的气息，不安的预感萦绕在心头（待包装）",
          DialogueId = 71003901,
          GUID = "B1C03582",
          SpeakNpcId = 800006
        },
        [71003902] = {
          Content = "齿轮运动的声音响起，敌人正从开启的通道口中窜出（待包装）",
          DialogueId = 71003902,
          GUID = "B1C035AC",
          SpeakNpcId = 800006
        },
        [71003903] = {
          Content = "又是齿轮响动的声音，不远处的两个通道也开启了（待包装）",
          DialogueId = 71003903,
          GUID = "B1C035D6",
          SpeakNpcId = 800006
        },
        [71003904] = {
          Content = "齿轮转动，室内的全部通道均已开启，努力击杀敌人吧（待包装）",
          DialogueId = 71003904,
          GUID = "B1C03600",
          SpeakNpcId = 800006
        },
        [71003905] = {
          Content = "所有通道均已关闭，剩余的敌人将在不久后溃散（待包装）",
          DialogueId = 71003905,
          GUID = "B1C0362A",
          SpeakNpcId = 800006
        },
        [71004101] = {
          ContentJP = "いつの間にか、廃棄された飛空艇が山中の動物たちの巨大な物置になっていたらしい。中を探ってみれば、何か役に立つ物資が見つかるかもしれない。",
          DialogueId = 71004101,
          GUID = "B1C05652",
          SpeakNpcId = 800006
        },
        [71004102] = {
          ContentJP = "物資を探る音が周囲の敵を引き寄せてしまった。撃退しよう。",
          DialogueId = 71004102,
          GUID = "B1C056A6",
          SpeakNpcId = 800006
        },
        [71004103] = {
          ContentJP = "敵を撃退した。今のうちに、さきほど集めた物資を確認しておこう。",
          DialogueId = 71004103,
          GUID = "B1C056D0",
          SpeakNpcId = 800006
        },
        [71004201] = {
          ContentJP = "うひょー！かったい……",
          DialogueId = 71004201,
          GUID = "B1C066BA",
          SpeakNpcId = 818038
        },
        [71004202] = {
          ContentJP = "何をしてるの？",
          DialogueId = 71004202,
          GUID = "B1C066E4",
          NextDialogue = 71004203,
          SpeakNpcId = 100001
        },
        [71004203] = {
          ContentJP = "<Default note=\"text:エジュウ\">穢獣</>の生態を調べてるんだよ。暇なら<Default note=\"text:エジュウ\">穢獣</>のサンプルを集めてくれない？もちろん、息してないやつでお願いね。",
          DialogueId = 71004203,
          GUID = "B1C066E5",
          NextOptions = {
            [1] = 710042031,
            [2] = 710042032
          },
          SpeakNpcId = 818038
        },
        [71004204] = {
          ContentJP = "やった！それじゃお願いね。私はちょっと休んでくるよ。ひとりで集めてたから、マジ倒れるとこだったんだ～",
          DialogueId = 71004204,
          GUID = "B1C0670E",
          SpeakNpcId = 818038
        },
        [71004205] = {
          ContentJP = "ぎゃあああ！な、なんで生きた<Default note=\"text:エジュウ\">穢獣</>がここに！？く、来るな！研究するのは私であって、あんたたちじゃないのよ！",
          DialogueId = 71004205,
          GUID = "B1C06738",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 818038
        },
        [71004206] = {
          ContentJP = "ほんとありがと！サンプルも揃ったことだし、そろそろ研究に戻るよ。またね！",
          DialogueId = 71004206,
          GUID = "B1C0678C",
          SpeakNpcId = 818038
        },
        [71004301] = {
          ContentJP = "このあたりでは、キレイな貝殻がたくさん堕ちている。打ち上げられた箱を割ってみよう。",
          DialogueId = 71004301,
          GUID = "B1C07722",
          SpeakNpcId = 800006
        },
        [71004302] = {
          ContentJP = "箱の底から大量の貝殻が見つかった。",
          DialogueId = 71004302,
          GUID = "B1C0774C",
          SpeakNpcId = 800006
        },
        [71004303] = {
          ContentJP = "一部の<Default note=\"text:エジュウ\">穢獣</>は、暗い箱に潜んで他者を襲うことがある――そんな噂は前から聞いていた。だが、それが自分の身に降りかかるとは思ってもいなかった。退治して戦利品を手に入れよう。",
          DialogueId = 71004303,
          GUID = "B1C07776",
          SpeakNpcId = 800006
        },
        [71004401] = {
          ContentJP = "あたりは<Default note=\"text:エジュウ\">穢獣</>で埋め尽くされている。やつらを退治してから、ジェネモンの捕獲に移ろう。",
          DialogueId = 71004401,
          GUID = "B1C0878A",
          SpeakNpcId = 800006
        },
        [71004402] = {
          ContentJP = "争いの音が不屈の禍を呼び寄せ、不吉の化身がついに姿を現した。あとは退治するだけだ。これまで幾度となくそうしてきたように。",
          DialogueId = 71004402,
          GUID = "B1C087B4",
          SpeakNpcId = 800006
        },
        [71004403] = {
          ContentJP = "付近はひとまず安全だ。今のうちに、ジェネモンと仲良くしよう。",
          DialogueId = 71004403,
          GUID = "B1C087DE",
          SpeakNpcId = 800006
        },
        [71004501] = {
          ContentJP = "敵が回収する物資の前に立ちはだかっている。退治しよう。",
          DialogueId = 71004501,
          GUID = "B1C097F2",
          SpeakNpcId = 800006
        },
        [71004502] = {
          ContentJP = "不吉の化身がついにこの地に現れた。さきに退治してから物資を回収しよう。",
          DialogueId = 71004502,
          GUID = "B1C0981C",
          SpeakNpcId = 800006
        },
        [71004503] = {
          ContentJP = "付近はひとまず安全だ。今のうちに、物資を回収しよう。",
          DialogueId = 71004503,
          GUID = "B1C09846",
          SpeakNpcId = 800006
        },
        [71004601] = {
          ContentJP = "目の前には大量の物資箱が並んでいる。開いて、中から使える物資を探し出そう。",
          DialogueId = 71004601,
          GUID = "B1C0A85A",
          SpeakNpcId = 800006
        },
        [71004602] = {
          ContentJP = "箱の中から、いくつかの使える物資を見つけた。",
          DialogueId = 71004602,
          GUID = "B1C0A884",
          SpeakNpcId = 800006
        },
        [71004603] = {
          ContentJP = "一部の<Default note=\"text:エジュウ\">穢獣</>は、暗い箱に潜んで他者を襲うことがある――そんな噂は前から聞いていた。だが、それが自分の身に降りかかるとは思ってもいなかった。退治して戦利品を手に入れよう。",
          DialogueId = 71004603,
          GUID = "B1C0A8AE",
          SpeakNpcId = 800006
        },
        [71004701] = {
          ContentJP = "遠くで何かが光っている……近くまで行って、確かめてみよう。",
          DialogueId = 71004701,
          GUID = "B1C0B8C2",
          SpeakNpcId = 800006
        },
        [71004702] = {
          ContentJP = "物資を拾い上げたその瞬間、警報が鳴り響き、大量の敵が押し寄せてきた。撃破しよう。",
          DialogueId = 71004702,
          GUID = "B1C0B8EC",
          SpeakNpcId = 800006
        },
        [71004703] = {
          ContentJP = "警報は解除されたが、その音を聞きつけて新たな敵が現れた。撃破しよう。",
          DialogueId = 71004703,
          GUID = "B1C0B916",
          SpeakNpcId = 800006
        },
        [71004704] = {
          ContentJP = "すべての敵が倒れ、辺りはようやく静寂を取り戻した。",
          DialogueId = 71004704,
          GUID = "B1C0B940",
          SpeakNpcId = 800006
        },
        [71004801] = {
          ContentJP = "遠くから氷の砕ける音が聞こえた……何があったのか、見に行ってみよう。",
          DialogueId = 71004801,
          GUID = "B1C0C92A",
          SpeakNpcId = 800006
        },
        [71004802] = {
          ContentJP = "君は……月狩り人か？ちょうどいい。最近公路の下に氷柱がたくさんできてしまってね。一緒に片付けてくれないか？",
          DialogueId = 71004802,
          GUID = "B1C0C954",
          NextOptions = {
            [1] = 710048021,
            [2] = 710048022
          },
          SpeakNpcId = 818039
        },
        [71004803] = {
          ContentJP = "おお、ありがとう。ではあちらの方は君に任せよう。",
          DialogueId = 71004803,
          GUID = "B1C0C97E",
          SpeakNpcId = 818039
        },
        [71004805] = {
          ContentJP = "おかげで危険がほぼ解消されたよ。ほら、報酬だ。",
          DialogueId = 71004805,
          GUID = "B1C0C9D2",
          SpeakNpcId = 818039
        },
        [71004901] = {
          ContentJP = "はぁ……困ったなぁ。こんなことなら、事前に草エサを買っとけばよかったよ。",
          DialogueId = 71004901,
          GUID = "B1C0D992",
          SpeakNpcId = 818040
        },
        [71004902] = {
          ContentJP = "月狩り人か。魚のエサを作るのに蓮草が必要なんだが、湖の向こう側にあって、採れないんだ。手を貸してくれないか？",
          DialogueId = 71004902,
          GUID = "B1C0D9BC",
          NextOptions = {
            [1] = 710049021,
            [2] = 710049022
          },
          SpeakNpcId = 818040,
          bForbidSkipOptions = true
        },
        [71004903] = {
          ContentJP = "おお、ありがとう！じゃあ先に竿でも立てて待ってるよ。",
          DialogueId = 71004903,
          GUID = "B1C0D9E6",
          SpeakNpcId = 818040
        },
        [71004905] = {
          ContentJP = "周囲は彷徨う<Default note=\"text:エジュウ\">穢獣</>であふれている。まずは奴らを撃退してから、蓮草を採取しよう。",
          DialogueId = 71004905,
          GUID = "B1C0DA3A",
          SpeakNpcId = 800006
        },
        [71004906] = {
          ContentJP = "近くの蓮草をすべて採取した。これらを漁師に渡そう。",
          DialogueId = 71004906,
          GUID = "B1C0DA64",
          SpeakNpcId = 800006
        },
        [71004907] = {
          ContentJP = "よしよし、これだけエサがあれば、今日こそ絶対に魚が釣れるはずだ！",
          DialogueId = 71004907,
          GUID = "B1C0DA8E",
          SpeakNpcId = 818040
        },
        [71005001] = {
          ContentJP = "おーい、そこの君！ちょっと写真を撮ってくれない？",
          DialogueId = 71005001,
          GUID = "B1C0E9FA",
          SpeakNpcId = 818041
        },
        [71005002] = {
          ContentJP = "ねぇ君、ちょっと写真撮ってくれない？せっかくアイスレイク城まで来たんだし、記念に何枚か残しておきたくてさ！",
          DialogueId = 71005002,
          GUID = "B1C0EA24",
          NextOptions = {
            [1] = 710050021,
            [2] = 710050022
          },
          SpeakNpcId = 818041,
          bForbidSkipOptions = true
        },
        [71005004] = {
          ContentJP = "やった！ありがとう！後ろのこの建物もちゃんと写してね、あのデザイン、すっごく気に入ってるんだ〜！",
          DialogueId = 71005004,
          GUID = "B1C0EA78",
          SpeakNpcId = 818041
        },
        [71005005] = {
          ContentJP = "うわっ、めっちゃ上手に撮れてる！ほんとありがとう〜！",
          DialogueId = 71005005,
          GUID = "B1C0EAA2",
          SpeakNpcId = 818041
        },
        [71005101] = {
          Content = "鱼来，鱼来。",
          DialogueId = 71005101,
          GUID = "B1C0EAA3",
          SpeakNpcId = 818045
        },
        [71005102] = {
          ContentJP = "何をしてるの？",
          DialogueId = 71005102,
          GUID = "B1C0FA62",
          NextDialogue = 71005103,
          SpeakNpcId = 100001
        },
        [71005103] = {
          ContentJP = "しっ！今魚釣りで忙しいんだ。話なら後にしてくれ。",
          DialogueId = 71005103,
          GUID = "B1C0FA8C",
          SpeakNpcId = 818045
        },
        [71005104] = {
          ContentJP = "しばらく様子を見ていたが、男性は一匹も釣れなかった。",
          DialogueId = 71005104,
          GUID = "B1C0FA8D",
          NextDialogue = 71005105,
          SpeakNpcId = 800006
        },
        [71005105] = {
          ContentJP = "とても釣れるとは思えないけど……",
          DialogueId = 71005105,
          GUID = "B1C0FAB6",
          NextDialogue = 71005106,
          SpeakNpcId = 100001
        },
        [71005106] = {
          ContentJP = "黙って見てろって！",
          DialogueId = 71005106,
          GUID = "B1C0FAE0",
          SpeakNpcId = 818045
        },
        [71005107] = {
          ContentJP = "またしばらく様子を見ていたが、やはり一匹も釣れなかった。",
          DialogueId = 71005107,
          GUID = "B1C0FAE1",
          NextDialogue = 71005108,
          SpeakNpcId = 800006
        },
        [71005108] = {
          ContentJP = "来い！来い！",
          DialogueId = 71005108,
          GUID = "B1C0FAE2",
          NextDialogue = 71005109,
          SpeakNpcId = 818045
        },
        [71005109] = {
          ContentJP = "少なくとも、釣り竿が必要なんじゃないかな？口で呼んだって釣れないと思う。",
          DialogueId = 71005109,
          GUID = "B1C0FB0A",
          NextDialogue = 71005110,
          SpeakNpcId = 100001
        },
        [71005110] = {
          ContentJP = "これは俺が大勢の人と交流してつかんだ最新の釣りテクニックだ。デカくて質のいい魚が釣れるらしい。信じられないならお前も一匹釣ってみろ。",
          DialogueId = 71005110,
          GUID = "B1C0FB34",
          SpeakNpcId = 818045
        },
        [71005111] = {
          ContentJP = "釣れたよ。あなたは？",
          DialogueId = 71005111,
          GUID = "B1C0FB5E",
          NextDialogue = 71005112,
          SpeakNpcId = 100001
        },
        [71005112] = {
          ContentJP = "うん、確かに大きいな。だが、俺のとは比べ物にもならん！",
          DialogueId = 71005112,
          GUID = "B1C0FB88",
          NextDialogue = 71005113,
          SpeakNpcId = 818045
        },
        [71005113] = {
          ContentJP = "あっちから蓮草の匂いがする。そのせいで魚が俺の針に食いつかないんだ。ちょっと引っこ抜いて来てくれないか。",
          DialogueId = 71005113,
          GUID = "B1C0FC06",
          SpeakNpcId = 818045
        },
        [71005114] = {
          ContentJP = "男性の言う通り、すべて引っこ抜いた。急いで戻ろう。",
          DialogueId = 71005114,
          GUID = "B1C0FC30",
          SpeakNpcId = 100001
        }
      }
    end
  },
