          Content = "钓鱼钓的也可以不是鱼。撒下几句话，做一些奇怪的事，就会有无数鱼争相咬钩。",
          DialogueId = 71005138,
          GUID = "B1C0FEFD",
          NextDialogue = 71005139,
          SpeakNpcId = 818045
        },
        [71005139] = {
          ContentJP = "これが俺が人との交流で気付いた心得ってやつだ。お前も今後、他人が撒いた「エサ」にまんまと引っかかって、からかわれるようなことがないといいな。",
          DialogueId = 71005139,
          GUID = "B1C0FF24",
          NextDialogue = 71005140,
          SpeakNpcId = 818045
        },
        [71005140] = {
          ContentJP = "振り回して悪かったな。これはほんの詫びだ。受け取ってくれ。",
          DialogueId = 71005140,
          GUID = "B1C0FF4E",
          SpeakNpcId = 818045
        },
        [71005141] = {
          ContentJP = "どうやら、真面目に話しをさせるには、こうするしかないようだね。",
          DialogueId = 71005141,
          GUID = "B1C0FF78",
          SpeakNpcId = 100001
        },
        [71005142] = {
          ContentJP = "わ、悪かったって！ただ、言葉のひとつや二つで、他人を振り回す者をよくみてきたから……俺も試してみようと思っただけで……",
          DialogueId = 71005142,
          GUID = "B1C0FFA2",
          NextDialogue = 71005143,
          SpeakNpcId = 818045
        },
        [71005143] = {
          ContentJP = "振り回して悪かったな。これはほんの詫びだ。受け取ってくれ。",
          DialogueId = 71005143,
          GUID = "B1C0FFCC",
          SpeakNpcId = 818045
        },
        [71005201] = {
          ContentJP = "ラッキーコインはいかが？魔法のラッキーコインだよ！お兄さん、お姉さん、おひとついかがですか！",
          DialogueId = 71005201,
          GUID = "B1C10ACA",
          SpeakNpcId = 818046
        },
        [71005202] = {
          ContentJP = "近づいてみると、少女はすぐさま懐から数枚の銅貨を取り出し、あなたの目の前に差し出した。",
          DialogueId = 71005202,
          GUID = "B1C10AF4",
          NextDialogue = 71005203,
          SpeakNpcId = 800006
        },
        [71005203] = {
          ContentJP = "{性别:お兄さん|お姉さん}、こんにちは！ラッキーコインはいかが？これはね、ママが遺してくれたものなの。たった1枚で悩みが消えて、2枚あれば幸せになれて、3枚揃えたら……なんでも願いが叶っちゃうんだよ！",
          DialogueId = 71005203,
          GUID = "B1C10B1E",
          NextDialogue = 71005204,
          SpeakNpcId = 818046
        },
        [71005204] = {
          ContentJP = "……",
          DialogueId = 71005204,
          GUID = "B1C10B48",
          NextDialogue = 71005205,
          SpeakNpcId = 100001
        },
        [71005205] = {
          ContentJP = "これらにはママの魔法がかかってるの！嘘じゃないよ！なんなら、他の人に聞いたっていいわ！私はずっとここにいるから。買いたくなったら、いつでも来てよ！",
          DialogueId = 71005205,
          GUID = "B1C10B49",
          SpeakNpcId = 818046
        },
        [71005206] = {
          ContentJP = "老人の足元に、数枚のラッキーコインが置かれているのに気づいたあなたは、声をかけることにした。",
          DialogueId = 71005206,
          GUID = "B1C10B72",
          NextDialogue = 71005207,
          SpeakNpcId = 800006
        },
        [71005207] = {
          ContentJP = "ラッキーコイン？ははは、そんなもんあったら、今頃こんなとこで腹を空かせているはずあるまい。",
          DialogueId = 71005207,
          GUID = "B1C10B73",
          NextDialogue = 71005208,
          SpeakNpcId = 818047
        },
        [71005208] = {
          ContentJP = "あの娘には言わないでやってくれ。あの歳でひとりぼっちなんて、可哀そうじゃろう……たとえ嘘でも、希望ってのは人を支えるもんだ。お前も、そう思うだろ？",
          DialogueId = 71005208,
          GUID = "B1C10B74",
          SpeakNpcId = 818047
        },
        [71005209] = {
          ContentJP = "数枚のラッキーコインを弄んでる少年に気づき、あなたは声をかけることにした。",
          DialogueId = 71005209,
          GUID = "B1C10B9C",
          NextDialogue = 71005210,
          SpeakNpcId = 800006
        },
        [71005210] = {
          ContentJP = "僕の左手に持ってるラッキーコインと、右手に持ってるただの銅貨……違いがわかるか？",
          DialogueId = 71005210,
          GUID = "B1C10B9D",
          NextDialogue = 71005211,
          SpeakNpcId = 818048
        },
        [71005211] = {
          ContentJP = "少年は両手を掲げる。よく見ると、確かに差はまったくない。",
          DialogueId = 71005211,
          GUID = "B1C10B9E",
          NextDialogue = 71005212,
          SpeakNpcId = 800006
        },
        [71005212] = {
          Content = "是呀，幸福硬币就是我们手里的铜币。它不是魔法创造出来的宝贝，而是诞生自大家的善意。",
          DialogueId = 71005212,
          GUID = "B1C10B9F",
          NextDialogue = 71005213,
          SpeakNpcId = 818048
        },
        [71005213] = {
          Content = "一枚幸福硬币就能买到她的笑容，这么轻松的买卖可不多见呀。",
          DialogueId = 71005213,
          GUID = "B1C10BA0",
          SpeakNpcId = 818048
        },
        [71005214] = {
          ContentJP = "どう？これでわかったでしょ？",
          DialogueId = 71005214,
          GUID = "B1C10BC6",
          SpeakNpcId = 818046
        },
        [71005215] = {
          ContentJP = "えへへ、もう、しょうがないなぁ。じゃあ全部うってあげる！あなたにも、ちゃんと自分の「幸せ」が見つかりますように。",
          DialogueId = 71005215,
          GUID = "B1C10BF0",
          SpeakNpcId = 818046
        },
        [71005216] = {
          ContentJP = "自分の手で……かっこいい！私もいつかあなたみたいになれるかな？",
          DialogueId = 71005216,
          GUID = "B1C10C1A",
          NextDialogue = 71005217,
          SpeakNpcId = 818046
        },
        [71005217] = {
          ContentJP = "もちろん。",
          DialogueId = 71005217,
          GUID = "B1C10C1B",
          NextDialogue = 71005218,
          SpeakNpcId = 100001
        },
        [71005218] = {
          ContentJP = "う……そっか……ちゃんと考えてみるよ。ありがとう！",
          DialogueId = 71005218,
          GUID = "B1C10C1C",
          SpeakNpcId = 818046
        },
        [71005301] = {
          ContentJP = "ど、泥棒！だれか、誰か助けて！！",
          DialogueId = 71005301,
          GUID = "B1C11B32",
          SpeakNpcId = 818042
        },
        [71005302] = {
          ContentJP = "その人はどっちに似てげったの？",
          DialogueId = 71005302,
          GUID = "B1C11B5C",
          NextDialogue = 71005303,
          SpeakNpcId = 100001
        },
        [71005303] = {
          ContentJP = "あ、あっちよ！で、でも……ううっ、外城区はとても危険な場所だし……",
          DialogueId = 71005303,
          GUID = "B1C11B86",
          SpeakNpcId = 818042
        },
        [71005304] = {
          ContentJP = "内城の連中はホント金持ちばっかだな～。これでしばらくは、メシの心配しなくて済みそうだぜ。",
          DialogueId = 71005304,
          GUID = "B1C11C04",
          NextDialogue = 71005305,
          SpeakNpcId = 818043
        },
        [71005305] = {
          ContentJP = "止まれ！盗んだモンを返{性别:せ|して}！",
          DialogueId = 71005305,
          GUID = "B1C11C2E",
          NextDialogue = 71005306,
          SpeakNpcId = 100001
        },
        [71005306] = {
          ContentJP = "ふん、もう助っ人を呼びやがったか。痛い目見せてやらぁ！",
          DialogueId = 71005306,
          GUID = "B1C11C58",
          SpeakNpcId = 818043
        },
        [71005307] = {
          ContentJP = "チッ、今日はツイてねぇなぁ。引くぞ！",
          DialogueId = 71005307,
          GUID = "B1C11CAC",
          SpeakNpcId = 818043
        },
        [71005308] = {
          ContentJP = "強盗たちはそう言い残すと、散り散りに逃げていった。あなたは地面に落ちたバッグを拾い、どうすべきか考え始めた。",
          DialogueId = 71005308,
          GUID = "B1C11CD6",
          SpeakNpcId = 800006
        },
        [71005309] = {
          ContentJP = "これは、あの子が外城区の厳しさを知るための「学費」なのだから、貰ってもいいはずだ。もっとふんだくろうとしなかっただけ、感謝してほしいくらいだ。",
          DialogueId = 71005309,
          GUID = "B1C11D2A",
          SpeakNpcId = 800006
        },
        [71005310] = {
          ContentJP = "ただいま。盗られたバッグってこれ？",
          DialogueId = 71005310,
          GUID = "B1C11D54",
          NextDialogue = 71005311,
          SpeakNpcId = 100001
        },
        [71005311] = {
          ContentJP = "ええ、ありがとう！！",
          DialogueId = 71005311,
          GUID = "B1C11D7E",
          NextDialogue = 71005312,
          SpeakNpcId = 818042
        },
        [71005312] = {
          ContentJP = "少女は涙をぬぐい、バッグから大金を取り出して、あなたに手渡した。",
          DialogueId = 71005312,
          GUID = "B1C11DA8",
          NextDialogue = 71005313,
          SpeakNpcId = 800006
        },
        [71005313] = {
          ContentJP = "これはほんのお気持ちよ。外城区にあなたのような心優しい月狩り人がいるなんて……ありがとう……ううっ……",
          DialogueId = 71005313,
          GUID = "B1C11DA9",
          SpeakNpcId = 818042
        },
        [71005401] = {
          ContentJP = "よってらっしゃいみてらっしゃい！お宝はすぐ目の前ですぜ",
          DialogueId = 71005401,
          GUID = "B1C12B9A",
          SpeakNpcId = 818044
        },
        [71005402] = {
          ContentJP = "おっと、そこの月狩り人さん、どうです？この箱を開ければ、中の賞品はすべて差し上げますぜ！",
          DialogueId = 71005402,
          GUID = "B1C12BC4",
          SpeakNpcId = 818044
        },
        [71005403] = {
          ContentJP = "鍵穴が開く音が聞こえた。だがゆっくりと開きかけたその箱は、突然「カチッ」と鋭い音を立てて再び重く閉ざされてしまった。どんなに試しても、二度とその箱が開くことはなかった——",
          DialogueId = 71005403,
          GUID = "B1C12C18",
          SpeakNpcId = 800006
        },
        [71005404] = {
          ContentJP = "あ！よくもうちの宝箱を壊してくれたな！！弁償しろ！！",
          DialogueId = 71005404,
          GUID = "B1C12C42",
          NextOptions = {
            [1] = 710054041,
            [2] = 710054042
          },
          SpeakNpcId = 818044
        },
        [71005405] = {
          ContentJP = "なっ、しー！そんなに騒ぐな！ここ一体で騙せ……じゃなかった。商売できなくなるだろ！ほら、これ全部やるから、黙っててくれ。",
          DialogueId = 71005405,
          GUID = "B1C12CC0",
          NextDialogue = 71005406,
          SpeakNpcId = 818044
        },
        [71005406] = {
          ContentJP = "男はバツの悪そうな顔で重そうな袋を手渡すと、箱を抱えてそそくさと立ち去った。",
          DialogueId = 71005406,
          GUID = "B1C12CEA",
          SpeakNpcId = 800006
        },
        [71005407] = {
          ContentJP = "こいつ、調子に乗りやがって！痛い目みたいようだな！",
          DialogueId = 71005407,
          GUID = "B1C12D14",
          NextDialogue = 71005408,
          SpeakNpcId = 818044
        },
        [71005408] = {
          ContentJP = "口だけの詐欺師かと思ってたけど……血の気も多いようだね。相手してあげる。",
          DialogueId = 71005408,
          GUID = "B1C12D3E",
          SpeakNpcId = 100001
        },
        [71005409] = {
          ContentJP = "男はバツの悪そうな顔で、箱を抱えてそそくさと立ち去った。",
          DialogueId = 71005409,
          GUID = "B1C12D68",
          SpeakNpcId = 800006
        },
        [71005501] = {
          ContentJP = "そこの月狩り人、ちょっといいか？",
          DialogueId = 71005501,
          GUID = "B1C13C02",
          SpeakNpcId = 818049
        },
        [71005502] = {
          ContentJP = "ま、前の方から不気味な声が聞こえるんだ……ちょっくら見てきてくれねぇか？",
          DialogueId = 71005502,
          GUID = "B1C13C2C",
          SpeakNpcId = 818049
        },
        [71005503] = {
          ContentJP = "特に恐ろしい物とやらは見当たらない。男の錯覚だったのだろう。",
          DialogueId = 71005503,
          GUID = "B1C13CAA",
          SpeakNpcId = 800006
        },
        [71005504] = {
          ContentJP = "数匹の<Default note=\"text:エジュウ\">穢獣</>が水路の上流をうろつき、ときおりかすれた咆哮を響かせている。男を怯えさせたのは、おそらくこの声だろう。",
          DialogueId = 71005504,
          GUID = "B1C13CFE",
          SpeakNpcId = 800006
        },
        [71005505] = {
          ContentJP = "すべての<Default note=\"text:エジュウ\">穢獣</>を退治し、あたりには静けさが戻った――彼のもとに戻ろう。",
          DialogueId = 71005505,
          GUID = "B1C13D28",
          SpeakNpcId = 800006
        },
        [71005506] = {
          ContentJP = "金属の破片が数枚、水路の縁に引っかかり、ときおり耳障りな音を立てている。男を怯えさせたのは、おそらくこの音だろう。",
          DialogueId = 71005506,
          Duration = 3,
          GUID = "B1C13D52",
          NextDialogue = 71005507,
          SpeakNpcId = 800006
        },
        [71005507] = {
          ContentJP = "金属の破片を拾い上げた。こういうものは買い手に困らない――男の依頼を片づけてから、売れる場所を探すとしよう。",
          DialogueId = 71005507,
          GUID = "B1C13D53",
          SpeakNpcId = 800006
        },
        [71005508] = {
          ContentJP = "あの恐ろしい声がなくなったよ……ありがとう。",
          DialogueId = 71005508,
          GUID = "B1C13D7C",
          SpeakNpcId = 818049
        },
        [71005601] = {
          ContentJP = "ぐぬぬぅ……おもっ……糸が、引けん……",
          DialogueId = 71005601,
          GUID = "B1C14C6A",
          SpeakNpcId = 818050
        },
        [71005602] = {
          ContentJP = "どうした{性别:んだ|の}？",
          DialogueId = 71005602,
          GUID = "B1C14C94",
          NextDialogue = 71005603,
          SpeakNpcId = 100001
        },
        [71005603] = {
          ContentJP = "月狩り人か。どうやら釣り糸にゴミが絡まってしまったようでね。手伝ってくれないか？",
          DialogueId = 71005603,
          GUID = "B1C14CBE",
          NextOptions = {
            [1] = 710056031,
            [2] = 710056032
          },
          SpeakNpcId = 818050
        },
        [71005604] = {
          ContentJP = "よし、では俺はこっちで引いてるから、あそこのゴミを砕いてくれ。",
          DialogueId = 71005604,
          GUID = "B1C14CE8",
          SpeakNpcId = 818050
        },
        [71005605] = {
          ContentJP = "ふぅ……助かった。ありがとな。",
          DialogueId = 71005605,
          GUID = "B1C14D12",
          SpeakNpcId = 818050
        },
        [71005701] = {
          ContentJP = "だ、誰か！助けてくれ！！",
          DialogueId = 71005701,
          GUID = "B1C15CD2",
          SpeakNpcId = 818051
        },
        [71005702] = {
          ContentJP = "た、助かったよ……その、もう一つだけ……お願い、できるかな？実は逃げたときに、釣り竿を置いてきてしまって……あっちまだ<Default note=\"text:エジュウ\">穢獣</>がうろついてるし……",
          DialogueId = 71005702,
          GUID = "B1C15CFC",
          NextOptions = {
            [1] = 710057021,
            [2] = 710057022
          },
          SpeakNpcId = 818051
        },
        [71005703] = {
          ContentJP = "ああ、ありがとう！ここで待ってるよ。",
          DialogueId = 71005703,
          GUID = "B1C15D26",
          SpeakNpcId = 818051
        },
        [71005704] = {
          ContentJP = "これだよこれ！本当にありがとう！",
          DialogueId = 71005704,
          GUID = "B1C15D50",
          SpeakNpcId = 818051
        },
        [71005801] = {
          ContentJP = "ねえそこの月狩り人……ちょっといい話あるんだけどさ、知りたいかい？",
          DialogueId = 71005801,
          GUID = "B1C16D3A",
          SpeakNpcId = 818052
        },
        [71005802] = {
          ContentJP = "前の方で銀輝石をいっぱい見つけたんだけどな……この通り、もう荷物がパンパンなんだ。よかったら、全部あげるよ。欲しいなら案内しよう。",
          DialogueId = 71005802,
          GUID = "B1C16D64",
          NextOptions = {
            [1] = 710058031,
            [2] = 710058032
          },
          SpeakNpcId = 818052
        },
        [71005804] = {
          ContentJP = "よし、じゃあついてこい。",
          DialogueId = 71005804,
          GUID = "B1C16DB8",
          SpeakNpcId = 818052
        },
        [71005805] = {
          ContentJP = "ここだここ。",
          DialogueId = 71005805,
          GUID = "B1C16DE2",
          SpeakNpcId = 818052
        },
        [71005806] = {
          ContentJP = "前にまだあるぜ。欲しいか？",
          DialogueId = 71005806,
          GUID = "B1C16E0C",
          NextOptions = {
            [1] = 710058061,
            [2] = 710058062
          },
          SpeakNpcId = 818052
        },
        [71005807] = {
          ContentJP = "よし、じゃあついてこい。",
          DialogueId = 71005807,
          GUID = "B1C16E36",
          SpeakNpcId = 818052
        },
        [71005808] = {
          ContentJP = "ここだ。",
          DialogueId = 71005808,
          GUID = "B1C16E60",
          SpeakNpcId = 818052
        },
        [71005809] = {
          ContentJP = "前にまだあるぜ。欲しいか？",
          DialogueId = 71005809,
          GUID = "B1C16E8A",
          NextOptions = {
            [1] = 710058091,
            [2] = 710058092
          },
          SpeakNpcId = 818052
        },
        [71005810] = {
          ContentJP = "このまままっすぐ進めば見えてくるぜ。",
          DialogueId = 71005810,
          GUID = "B1C16EB4",
          SpeakNpcId = 818052
        },
        [71005811] = {
          ContentJP = "今だ、お前らやれ！",
          DialogueId = 71005811,
          GUID = "B1C16EDE",
          NextDialogue = 71005812,
          SpeakNpcId = 818052
        },
        [71005812] = {
          ContentJP = "どうやら銀輝石は、鉱山労働者に扮した強盗たちの罠だったようだ。彼らを撃退しよう。",
          DialogueId = 71005812,
          Duration = 3,
          GUID = "B1C16F08",
          SpeakNpcId = 800006
        },
        [71005813] = {
          ContentJP = "強盗を撃退した後、あなたは今日の収穫を数え始めた。",
          DialogueId = 71005813,
          GUID = "B1C16F32",
          SpeakNpcId = 800006
        },
        [71005814] = {
          ContentJP = "くそ、あと一歩で……いや、ええと、残念だなぁ。じゃあ俺はこの辺で！！",
          DialogueId = 71005814,
          GUID = "B1C16F5C",
          SpeakNpcId = 818052
        },
        [71005901] = {
          ContentJP = "パパ、速い！誰もパパには勝てないね！",
          DialogueId = 71005901,
          GUID = "B1C17DA2",
          SpeakNpcId = 818053
        },
        [71005902] = {
          ContentJP = "あ、また挑戦者が来たぞ！パパはとっても足が速いんだ！信じないのなら、勝負してみる？",
          DialogueId = 71005902,
          GUID = "B1C17DCC",
          NextOptions = {
            [1] = 710059021,
            [2] = 710059022
          },
          SpeakNpcId = 818053,
          bForbidSkipOptions = true
        },
        [71005903] = {
          ContentJP = "ゴホン、受けて立とう。だが、その前に伝えておきたいことがあるんだ。ちょっと来てくれ。",
          DialogueId = 71005903,
          GUID = "B1C17DF6",
          SpeakNpcId = 818054
        },
        [71005904] = {
          ContentJP = "この金はやるよ。だから、後で走る時……少しだけ手加減してくれないか……頼むよ。息子に失望されたくなくて、つい誰も足では俺に勝てないとか行っちまったんだ。",
          DialogueId = 71005904,
          GUID = "B1C17E20",
          NextOptions = {
            [1] = 710059041,
            [2] = 710059042
          },
          SpeakNpcId = 818054,
          bForbidSkipOptions = true
        },
        [71005905] = {
          ContentJP = "すまないね、ありがとう……",
          DialogueId = 71005905,
          GUID = "B1C17E4A",
          SpeakNpcId = 818054
        },
        [71005906] = {
          ContentJP = "はあ……わかったよ……",
