          GUID = "B1C17EF2",
          NextDialogue = 71005910,
          SpeakNpcId = 818053
        },
        [71005910] = {
          ContentJP = "一！",
          DialogueId = 71005910,
          Duration = 1,
          GUID = "B1C17F1C",
          SpeakNpcId = 818053
        },
        [71005911] = {
          ContentJP = "わぁ、パパすっごい！！",
          DialogueId = 71005911,
          GUID = "B1C17F46",
          NextDialogue = 71005912,
          SpeakNpcId = 818053
        },
        [71005912] = {
          ContentJP = "ありがとう……これはほんのお礼だ。受け取ってくれ。",
          DialogueId = 71005912,
          GUID = "B1C17F70",
          SpeakNpcId = 818054
        },
        [71005913] = {
          ContentJP = "おいおい、話が違うじゃないか……",
          DialogueId = 71005913,
          GUID = "B1C17F9A",
          NextDialogue = 71005914,
          SpeakNpcId = 818054
        },
        [71005914] = {
          ContentJP = "ん？なんのこと？",
          DialogueId = 71005914,
          GUID = "B1C17FC4",
          NextDialogue = 71005915,
          SpeakNpcId = 818053
        },
        [71005915] = {
          ContentJP = "ぐっ、いや、なんでもない。すまんな。パパ、負けちまった……",
          DialogueId = 71005915,
          GUID = "B1C17FEE",
          NextDialogue = 71005916,
          SpeakNpcId = 818054
        },
        [71005916] = {
          ContentJP = "ううん、全然平気だよ！誰だってうっかりすることくらいあるもんね！次は絶対勝とう！",
          DialogueId = 71005916,
          GUID = "B1C18018",
          NextDialogue = 71005917,
          SpeakNpcId = 818053
        },
        [71005917] = {
          ContentJP = "あ、ああ……そうだな。これはお礼の品だ、受け取ってくれ。",
          DialogueId = 71005917,
          GUID = "B1C18042",
          SpeakNpcId = 818054
        },
        [71005918] = {
          ContentJP = "すまんな。パパ、負けちまった……",
          DialogueId = 71005918,
          GUID = "B1C1806C",
          NextDialogue = 71005919,
          SpeakNpcId = 818054
        },
        [71005919] = {
          ContentJP = "ううん、全然平気だよ！誰だってうっかりすることくらいあるもんね！次は絶対勝とう！",
          DialogueId = 71005919,
          GUID = "B1C18096",
          NextDialogue = 71005920,
          SpeakNpcId = 818053
        },
        [71005920] = {
          ContentJP = "あ、ああ……そうだな。月狩り人さんも感謝するよ。よかったら、これを受け取ってくれ。",
          DialogueId = 71005920,
          GUID = "B1C180C0",
          SpeakNpcId = 818054
        },
        [71005921] = {
          Content = "哇，爸爸真的好厉害！",
          DialogueId = 71005921,
          GUID = "B1C180EA",
          NextDialogue = 71005922,
          SpeakNpcId = 818053
        },
        [71005922] = {
          ContentJP = "おい……わざと手を抜いたな。ありがとう……これはほんのお礼だ。受け取ってくれ。",
          DialogueId = 71005922,
          GUID = "B1C18114",
          SpeakNpcId = 818054
        },
        [71006001] = {
          ContentJP = "あたりは<Default note=\"text:エジュウ\">穢獣</>で埋め尽くされている。やつらを退治してから、ジェネモンの捕獲に移ろう。",
          DialogueId = 71006001,
          GUID = "B1C18E0A",
          SpeakNpcId = 800006
        },
        [71006002] = {
          ContentJP = "争いの音に、さらに多くの<Default note=\"text:エジュウ\">穢獣</>が引き寄せられてしまった。",
          DialogueId = 71006002,
          GUID = "B1C18E34",
          SpeakNpcId = 800006
        },
        [71006003] = {
          ContentJP = "付近はひとまず安全だ。今のうちに、ジェネモンを捕獲しよう。",
          DialogueId = 71006003,
          GUID = "B1C18E5E",
          SpeakNpcId = 800006
        },
        [71006101] = {
          ContentJP = "はぁ……仕事キライ……さぼりたい……",
          DialogueId = 71006101,
          GUID = "B1C19E72",
          SpeakNpcId = 818019
        },
        [71006102] = {
          ContentJP = "はぁ……なんで皆して鉱山に飯運ぶのさ。たまにはもっとマシな場所で食べられないの？危険だとか思うでしょ普通……もう、走りすぎて足ガクガクだよ……",
          DialogueId = 71006102,
          GUID = "B1C19E9C",
          NextDialogue = 71006103,
          SpeakNpcId = 818019
        },
        [71006103] = {
          ContentJP = "手伝おっか？",
          DialogueId = 71006103,
          GUID = "B1C19EC6",
          NextDialogue = 71006104,
          SpeakNpcId = 100001
        },
        [71006104] = {
          ContentJP = "わーい！この下に<Default note=\"text:エジュウ\">穢獣</>がうじゃうじゃいて通れないんだ。手伝ってくれない？",
          DialogueId = 71006104,
          GUID = "B1C19EF0",
          NextDialogue = 71006105,
          SpeakNpcId = 818019
        },
        [71006105] = {
          ContentJP = "もちろん、任せて。",
          DialogueId = 71006105,
          GUID = "B1C19F1A",
          SpeakNpcId = 100001
        },
        [71006106] = {
          ContentJP = "大量の<Default note=\"text:エジュウ\">穢獣</>があなたの行く手を阻んでいる。さっそく退治しよう。",
          DialogueId = 71006106,
          GUID = "B1C19F44",
          SpeakNpcId = 800006
        },
        [71006107] = {
          ContentJP = "おっそいなぁ……",
          DialogueId = 71006107,
          GUID = "B1C19F6E",
          SpeakNpcId = 818058
        },
        [71006108] = {
          ContentJP = "こんにちは。ご注文の品を届けにきました。",
          DialogueId = 71006108,
          GUID = "B1C19F98",
          NextDialogue = 71006109,
          SpeakNpcId = 100001
        },
        [71006109] = {
          ContentJP = "どれどれ……なんだこれは！こぼれてるじゃないか！これでは食べられん！！「シルバーピース」はまったく頼りにならんな！",
          DialogueId = 71006109,
          GUID = "B1C19FC2",
          NextOptions = {
            [1] = 710061091,
            [2] = 710061092
          },
          SpeakNpcId = 818058,
          bForbidSkipOptions = true
        },
        [71006110] = {
          ContentJP = "そうだったのか……どうやら、私の論文作業と同じくらい苦労したようだな。まあいい。これをやろう。先ほどはついカッとなってしまって……すまなかったね。",
          DialogueId = 71006110,
          GUID = "B1C19FEC",
          SpeakNpcId = 818058
        },
        [71006111] = {
          ContentJP = "地質学者の前で料理を一気に頬張った。",
          DialogueId = 71006111,
          Duration = 3,
          GUID = "B1C1A016",
          NextDialogue = 71006112,
          SpeakNpcId = 800006
        },
        [71006112] = {
          ContentJP = "ちょっ、ゆっくり食べなさい！喉をつまらせたらどうするんだ……はぁ……ここまで送ってくるのに、私の論文作業と同じくらい苦労したんだろう？まあいい。これをやろう。先ほどはついカッとなってしまって……すまなかったね。",
          DialogueId = 71006112,
          GUID = "B1C1A040",
          SpeakNpcId = 818058
        },
        [71006201] = {
          ContentJP = "今日はどういうわけか、魚が一匹も釣れないんだ。",
          DialogueId = 71006201,
          GUID = "B1C1AEDA",
          SpeakNpcId = 818055
        },
        [71006202] = {
          ContentJP = "月狩り人、よく来たね。今日はここには魚なんていないんじゃないかと思ってるんだが……見てくれないか？",
          DialogueId = 71006202,
          GUID = "B1C1AF04",
          SpeakNpcId = 818055
        },
        [71006203] = {
          ContentJP = "ありがとう。",
          DialogueId = 71006203,
          GUID = "B1C1AF2E",
          SpeakNpcId = 818055
        },
        [71006204] = {
          Content = "（待捕鱼系统做好后接入捕鱼系统）",
          DialogueId = 71006204,
          Duration = 3,
          GUID = "B1C1AF58",
          SpeakNpcId = 800006
        },
        [71006205] = {
          ContentJP = "おお、一発で釣れるなんてすごいじゃないか！！どうやら場所の問題ではなかったようだね。",
          DialogueId = 71006205,
          GUID = "B1C1AF82",
          NextDialogue = 71006206,
          SpeakNpcId = 818055
        },
        [71006206] = {
          ContentJP = "ありがとう。今度は自分で釣ってみるよ。今日こそは空のバケツで帰るわけにはいかん！",
          DialogueId = 71006206,
          GUID = "B1C1AFAC",
          SpeakNpcId = 818055
        },
        [71006301] = {
          ContentJP = "だ、誰か！助けてくれ！！",
          DialogueId = 71006301,
          GUID = "B1C1BF42",
          SpeakNpcId = 818056
        },
        [71006302] = {
          ContentJP = "ああ、ありがとう……ついでに一つ、手伝ってほしいことがあるんだ。ここ数日魚がまったく釣れなくて、みんなに笑われてるんだよ。代わりに一匹釣ってくれないか？",
          DialogueId = 71006302,
          GUID = "B1C1BF6C",
          SpeakNpcId = 818056
        },
        [71006303] = {
          ContentJP = "おお、ありがたい！バケツはここに置いとくぞ。",
          DialogueId = 71006303,
          GUID = "B1C1BF96",
          SpeakNpcId = 818056
        },
        [71006304] = {
          Content = "（待捕鱼系统做好后接入捕鱼系统）",
          DialogueId = 71006304,
          Duration = 3,
          GUID = "B1C1BFC0",
          SpeakNpcId = 800006
        },
        [71006305] = {
          ContentJP = "ああ、良かった。今日こそ笑われずに済みそうだ。これはお礼だ。ご苦労さま。",
          DialogueId = 71006305,
          GUID = "B1C1BFEA",
          SpeakNpcId = 818056
        },
        [71006401] = {
          Content = "（玄色狴犴骤然出现，击退它们！）",
          DialogueId = 71006401,
          GUID = "B1C1CFAA",
          SpeakNpcId = 800006
        },
        [71006501] = {
          Content = "有奖竞猜有奖竞猜，那边那位朋友要不要来看看呀。",
          DialogueId = 71006501,
          GUID = "B1C1E012",
          SpeakNpcId = 818060
        },
        [71006502] = {
          Content = "恰逢奉香大典临近，本店特推出节庆活动，在举办一个叫非常大脑的智力问答活动，答错也有安慰奖，要不要来挑战一下？",
          DialogueId = 71006502,
          GUID = "B1C1E03C",
          NextOptions = {
            [1] = 710065021,
            [2] = 710065022
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006504] = {
          Content = "好，你先稍作休息，我们马上开始。",
          DialogueId = 71006504,
          GUID = "B1C1E090",
          SpeakNpcId = 818060
        },
        [71006505] = {
          Content = "喂，那边的朋友先别急着去答题，要不要听听我的提议？",
          DialogueId = 71006505,
          GUID = "B1C1E0BA",
          SpeakNpcId = 818061
        },
        [71006506] = {
          Content = "那家伙净出一些麻烦的脑筋急转弯，你要是帮我搬下货，我就直接告诉你答案。如何？这样也省得你动脑子了。",
          DialogueId = 71006506,
          GUID = "B1C1E0E4",
          NextDialogue = 71006507,
          SpeakNpcId = 818061
        },
        [71006507] = {
          Content = "辛苦了，货就在那边的船上。",
          DialogueId = 71006507,
          GUID = "B1C1E10E",
          SpeakNpcId = 818061
        },
        [71006508] = {
          Content = "辛苦了，他今天这个问题应该选第一个。",
          DialogueId = 71006508,
          GUID = "B1C1E138",
          SpeakNpcId = 818061
        },
        [71006509] = {
          Content = "辛苦了，他今天这个问题应该选第二个。",
          DialogueId = 71006509,
          GUID = "B1C1E162",
          SpeakNpcId = 818061
        },
        [71006510] = {
          Content = "辛苦了，他今天这个问题应该选第三个。",
          DialogueId = 71006510,
          GUID = "B1C1E18C",
          SpeakNpcId = 818061
        },
        [71006511] = {
          Content = "休息好了吗？",
          DialogueId = 71006511,
          GUID = "B1C1E1B6",
          NextOptions = {
            [1] = 710065111,
            [2] = 710065112
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006512] = {
          Content = "休息好了吗？",
          DialogueId = 71006512,
          GUID = "B1C1E1E0",
          NextOptions = {
            [1] = 710065121,
            [2] = 710065122
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006513] = {
          Content = "休息好了吗？",
          DialogueId = 71006513,
          GUID = "B1C1E20A",
          NextOptions = {
            [1] = 710065131,
            [2] = 710065132
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006514] = {
          Content = "请听题！织星客丢了一件商品，经过调查找到了甲乙丙三人。甲指责：“是乙偷的！”。乙声称：“是丙偷的！”。丙说：“确实是我偷的！”。仅一人说了真话，请问到底是谁偷走了商品？",
          DialogueId = 71006514,
          GUID = "B1C1E234",
          NextOptions = {
            [1] = 710065141,
            [2] = 710065142,
            [3] = 710065143
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006515] = {
          Content = "请听题！锦鲤皎皎的好友有三个皎皎朋友，第一个叫黄金皎皎，第二个叫白银皎皎，第三个叫什么？",
          DialogueId = 71006515,
          GUID = "B1C1E25E",
          NextOptions = {
            [1] = 710065151,
            [2] = 710065152,
            [3] = 710065153
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006516] = {
          Content = "请听题！三人前后排队，各带帽子一顶，帽子颜色可能会出现红、黄、蓝其中一种。最后一人能看到前两人的帽子，中间的人只能看前面。最后一人沉默，接着中间人也沉默。第一人说自己戴黄帽。已知至少一人戴黄帽。下列哪个说法是正确的？",
          DialogueId = 71006516,
          GUID = "B1C1E288",
          NextOptions = {
            [1] = 710065161,
            [2] = 710065162,
            [3] = 710065163
          },
          SpeakNpcId = 818060,
          bForbidSkipOptions = true
        },
        [71006517] = {
          Content = "恭喜你答对了！这是为你准备的豪华奖品，请拿好～",
          DialogueId = 71006517,
          GUID = "B1C1E2B2",
          Scripts = "SetOutport{FinishType{2},OptionIdx{1}}",
          SpeakNpcId = 818060
        },
        [71006518] = {
          Content = "回答错误，这是你的安慰奖，欢迎下次再来挑战哦～",
          DialogueId = 71006518,
          GUID = "B1C1E2DC",
          Scripts = "SetOutport{FinishType{2},OptionIdx{2}}",
          SpeakNpcId = 818060
        },
        [71006519] = {
          Content = "好吧好吧，还是年轻人有干劲，那你加油。",
          DialogueId = 71006519,
          GUID = "B1C1E306",
          SpeakNpcId = 818061
        },
        [71006520] = {
          Content = "嗯，准备好了再来找我吧！",
          DialogueId = 71006520,
          GUID = "B1C1E330",
          SpeakNpcId = 818060
        },
        [71006601] = {
          Content = "好想要小青蛙呀，咕咕呱呱呱。",
          DialogueId = 71006601,
          GUID = "B1C1F07A",
          SpeakNpcId = 818062
        },
        [71006602] = {
          Content = "小青蛙，好想要小青蛙，小青蛙小青蛙小青蛙。",
          DialogueId = 71006602,
          GUID = "B1C1F0A4",
          NextOptions = {
            [1] = 710066021,
            [2] = 710066022
          },
          SpeakNpcId = 818062,
          bForbidSkipOptions = true
        },
        [71006603] = {
          Content = "（它似乎对青蛙有什么执念，帮它找找看吧。）",
          DialogueId = 71006603,
          GUID = "B1C1F0CE",
          SpeakNpcId = 100001
        },
        [71006604] = {
          Content = "这些应该足够了，回去交给它吧。",
          DialogueId = 71006604,
          GUID = "B1C1F0F8",
          SpeakNpcId = 100001
        },
        [71006605] = {
          Content = "小青蛙，好耶，小青蛙，好～咕呱咕呱。",
          DialogueId = 71006605,
          GUID = "B1C1F122",
          NextDialogue = 71006606,
          SpeakNpcId = 818062
        },
        [71006606] = {
          Content = "（就这样，无由生消失在了你的面前。）",
          DialogueId = 71006606,
          GUID = "B1C1F14C",
          SpeakNpcId = 800006
        },
        [71006701] = {
          Content = "这么简单的题要是再答错，今晚就给我留下来抄一百遍吧。",
          DialogueId = 71006701,
          GUID = "B1C200E2",
          NextDialogue = 71006702,
          SpeakNpcId = 818064
        },
        [71006702] = {
          Content = "（愤怒的声音从远处传来，过去看看发生了什么吧。）",
          DialogueId = 71006702,
          GUID = "B1C2010C",
          SpeakNpcId = 800006
        },
        [71006703] = {
          Content = "这是怎么了？",
          DialogueId = 71006703,
          GUID = "B1C20136",
          NextDialogue = 71006704,
          SpeakNpcId = 100001
        },
        [71006704] = {
          Content = "呼……这孩子连大风九章都默写不下来。这点定性都没有，以后还怎么精进学业？",
          DialogueId = 71006704,
          GUID = "B1C20160",
          NextDialogue = 71006705,
          SpeakNpcId = 818064
        },
        [71006705] = {
          Content = "不行，越想越气，我去喝口茶冷静一下，你帮我盯一下吧。",
          DialogueId = 71006705,
          GUID = "B1C2018A",
          NextOptions = {
            [1] = 710067051,
            [2] = 710067052
          },
          SpeakNpcId = 818064,
          bForbidSkipOptions = true
        },
        [71006706] = {
          Content = "劳烦你了，我很快回来。",
          DialogueId = 71006706,
          GUID = "B1C201B4",
          SpeakNpcId = 818064
        },
        [71006707] = {
          Content = "呜呜呜呜……下一句到底是什么来着……",
          DialogueId = 71006707,
          GUID = "B1C201DE",
          NextDialogue = 71006708,
          SpeakNpcId = 818063
        },
        [71006708] = {
          Content = "这位朋友，你能不能也帮帮我呀……",
          DialogueId = 71006708,
          GUID = "B1C20208",
          SpeakNpcId = 818063
        },
        [71006709] = {
