        [72999999] = {
          DialogueId = 72999999,
          DialoguePanelType = "AllHide",
          Duration = 1.4,
          GUID = "B6BF7256"
        },
        [73000201] = {
          ContentJP = "この装置を改良したんだ。効果を確かめたいから、引き続きテスト頼む。わざわざエリュシオンから高い金払って取り寄せたんだ。これまでみたいに簡単に避けきれると思うなよ。",
          DialogueId = 73000201,
          GUID = "B6BF937A",
          SpeakNpcId = 818022
        },
        [73000202] = {
          ContentJP = "まだやるのか？いいだろう。まったく、お前ら身軽なやつは跳ね回ったりが好きだな。",
          DialogueId = 73000202,
          GUID = "B6BF93A4",
          SpeakNpcId = 818022
        },
        [73000203] = {
          ContentJP = "おいおい、また成功したのか？せめて一回くらい失敗してくれよ……もっと改善せねば。",
          DialogueId = 73000203,
          GUID = "B6BF93CE",
          SpeakNpcId = 818022
        },
        [73000204] = {
          ContentJP = "うん、これだ。この結果が欲しかったんだ。……何に使えるのかは分からんが、きっと役に立つはず！",
          DialogueId = 73000204,
          GUID = "B6BF93F8",
          SpeakNpcId = 818022
        },
        [73000301] = {
          ContentJP = "また来たな。前回は簡単すぎたから、もっと難易度を上げたぞ。今度こそ、お前の手を地につかせてやる！",
          DialogueId = 73000301,
          GUID = "B6BFA3E2",
          SpeakNpcId = 818022
        },
        [73000302] = {
          ContentJP = "まだやるのか？いいだろう。まったく、お前ら身軽なやつは跳ね回ったりが好きだな。",
          DialogueId = 73000302,
          GUID = "B6BFA40C",
          SpeakNpcId = 818022
        },
        [73000303] = {
          ContentJP = "ま、また全部躱した……だと！？銅貨を山ほど使って改良したんだ。ここで諦められるか……待ってろ、次こそ……必ずギャフンと言わせてやる！",
          DialogueId = 73000303,
          GUID = "B6BFA436",
          SpeakNpcId = 818022
        },
        [73000304] = {
          ContentJP = "ふむふむ、あたふたしてるお前を見て思いついたぞ。この装置、アイスレイク城の門に設置してやろう。強制突破とするやつを止めるのに使えるはずだ！",
          DialogueId = 73000304,
          GUID = "B6BFA460",
          SpeakNpcId = 818022
        },
        [73000401] = {
          ContentJP = "ついに来たな。待ってたぞ。今回は全財産をつぎ込んで、この装置をとんでもなくパワーアップさせたんだ。もはや完璧。突破など絶対ムリだ！",
          DialogueId = 73000401,
          GUID = "B6BFB44A",
          SpeakNpcId = 818022
        },
        [73000402] = {
          ContentJP = "まだやるのか？いいだろう。まったく、お前ら身軽なやつは跳ね回ったりが好きだな。",
          DialogueId = 73000402,
          GUID = "B6BFB474",
          SpeakNpcId = 818022
        },
        [73000403] = {
          ContentJP = "また……また失敗か。もういい……やっぱり礼賛会のモノなどに期待するんじゃなかった。これも陛下への忠誠心を欠いた俺への罰ってわけか。",
          DialogueId = 73000403,
          GUID = "B6BFB49E",
          SpeakNpcId = 818022
        },
        [73000404] = {
          ContentJP = "この装置はもうここに置いておく。好きなだけ遊んでくれ。どうやらお前、けっこう楽しんでるみたいだしな。",
          DialogueId = 73000404,
          GUID = "B6BFB4C8",
          SpeakNpcId = 818022
        },
        [73000405] = {
          ContentJP = "どうだ、これで分かっただろう？……おっと、いいこと思いついた。これを陛下に献上して、兵士の訓練と選抜に使っていただこう。きっとたくさん褒美がもらえるはずだ。この改良にかかった借金も返せるし、一石二鳥じゃないか！",
          DialogueId = 73000405,
          GUID = "B6BFB4F2",
          SpeakNpcId = 818022
        },
        [73000502] = {
          ContentJP = "装置は無言でたたずんでいる。上には粗末なつまみと、「やさしい」「難しい」「ゲキムズ」と、どう見ても、あのおしゃべりな兵士の手書きと思われる３つの難易度表記がある。",
          DialogueId = 73000502,
          GUID = "B6BFC4DC",
          SpeakNpcId = 818022
        },
        [73000601] = {
          ContentJP = "（物資輸送用のエレベーターか……補給が手に入るかもしれない。でも、待ち伏せには警戒しておいた方がよさそうだ。）",
          DialogueId = 73000601,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFD51A",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD7"
        },
        [73000701] = {
          ContentJP = "この部屋はひとまず安全だ。制御装置を操作しよう。",
          DialogueId = 73000701,
          ExStoryInfo = "EXPlayer",
          GUID = "B6BFE582",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD8"
        },
        [73000801] = {
          ContentJP = "制御権限取得中。少々お待ちください。",
          DialogueId = 73000801,
          GUID = "B6BFF5EA",
          SpeakNpcName = "UI_Npc_MechVoice",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDD9"
        },
        [73000901] = {
          ContentJP = "（中央制御室は独立した電力供給だから……ここにあるイコル駆動輪は、動力室の爆発の影響を受けていないみたい。）",
          DialogueId = 73000901,
          ExStoryInfo = "EXPlayer",
          GUID = "B6C00652",
          SpeakNpcId = 110022,
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDA"
        },
        [73001001] = {
          ContentJP = "回路エラー、制御装置は保護状態にあります。保護状態を解除するために、イコル駆動輪を停止してください。",
          DialogueId = 73001001,
          GUID = "B6C016BA",
          SpeakNpcName = "UI_Npc_MechVoice",
          VoiceName = "voice/$Locale$/story/1002/110192/1B95DDDB"
        },
        [80001001] = {
          ContentJP = "わぁ、ようやく大魔法使いの家に着いた！（コンコンコン）ーー大魔法使い、お家にいますか？",
          DialogueId = 80001001,
          GUID = "C8462C3A",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80001002,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C3A"
        },
        [80001002] = {
          ContentJP = "う......返事がない。ちょうど出かけているのかな。外で探してみよう。",
          DialogueId = 80001002,
          GUID = "C8462C64",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80001003,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C64"
        },
        [80001003] = {
          ContentJP = "ええと、この先の物語はまだ色を塗ってない......でも大丈夫！フィーナには魔法の絵筆があるから、進みながら物語に色をつけていこう。",
          DialogueId = 80001003,
          GUID = "C8462C8E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462C8E"
        },
        [80001004] = {
          ContentJP = "この道に沿って大魔法使いの痕跡を探そう。",
          DialogueId = 80001004,
          GUID = "C8462CB8",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CB8"
        },
        [80001005] = {
          ContentJP = "え......？花園なのに、花一本も見えない？",
          DialogueId = 80001005,
          GUID = "C8462CE2",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 80001006,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462CE2"
        },
        [80001006] = {
          ContentJP = "それじゃフィーナが、綺麗な花を描いてあげよう。",
          DialogueId = 80001006,
          GUID = "C8462D0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D0C"
        },
        [80001007] = {
          ContentJP = "これで、花園がもっと綺麗になったね。先へ進もう。",
          DialogueId = 80001007,
          GUID = "C8462D36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D36"
        },
        [80001008] = {
          ContentJP = "これは......ナイチンゲールが残してくれた羽根！",
          DialogueId = 80001008,
          GUID = "C8462D60",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80001009,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D60"
        },
        [80001009] = {
          ContentJP = "羽根を集めよう。きっと幸運を呼び込むから。",
          DialogueId = 80001009,
          GUID = "C8462D8A",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462D8A"
        },
        [80001010] = {
          ContentJP = "この先は蔓に塞がれている......どうしよう。",
          DialogueId = 80001010,
          GUID = "C8462DB4",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DB4"
        },
        [80001011] = {
          ContentJP = "よかった。これで先へ進めるね！",
          DialogueId = 80001011,
          GUID = "C8462DDE",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462DDE"
        },
        [80001012] = {
          ContentJP = "大魔法使いはそこにいるの？",
          DialogueId = 80001012,
          GUID = "C8462E08",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E08"
        },
        [80001013] = {
          ContentJP = "あれ？焚き火はまだ燃えているの。大魔法使い、ついさっきまでここにいたみたいね。",
          DialogueId = 80001013,
          GUID = "C8462E32",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E32"
        },
        [80001014] = {
          ContentJP = "わぁ、蛍がピカピカと飛び交ってる......まるで星々に翼が生えたみたい！",
          DialogueId = 80001014,
          GUID = "C8462E5C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E5C"
        },
        [80001015] = {
          ContentJP = "ここにも綺麗な花が咲いてきた！",
          DialogueId = 80001015,
          GUID = "C8462E86",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80001016,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462E86"
        },
        [80001016] = {
          ContentJP = "ほら見て、丸っこいキノコもあるよ！踏んだら、きっと高く跳べるよね。",
          DialogueId = 80001016,
          GUID = "C8462EB0",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EB0"
        },
        [80001017] = {
          ContentJP = "なぜこんなところに宝物が......大魔法使いがわざと隠しておいたのかな？",
          DialogueId = 80001017,
          GUID = "C8462EDA",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462EDA"
        },
        [80001018] = {
          ContentJP = "道が途切れてる......ここから先はどう進めばいいのかな。",
          DialogueId = 80001018,
          GUID = "C8462F04",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F04"
        },
        [80001019] = {
          ContentJP = "わぁ......！可愛いキノコたち、私を助けにきてくれたの？",
          DialogueId = 80001019,
          GUID = "C8462F2E",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          NextDialogue = 80001020,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F2E"
        },
        [80001020] = {
          ContentJP = "助けてくれてありがとう！これじゃ向こうまで跳べそう。",
          DialogueId = 80001020,
          GUID = "C8462F58",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120111/C8462F58"
        },
        [80001021] = {
          ContentJP = "あれ、ここにも宝物......大魔法使いがわざと残してくれたのかな？",
