        [80002001] = {
          ContentJP = "わぁ、ここは迷宮庭園なの！",
          DialogueId = 80002001,
          GUID = "C846D04A",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          NextDialogue = 80002002,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D04A"
        },
        [80002002] = {
          ContentJP = "ユニコーンの{性别:お兄さん|お姉さん}はどこに隠れてるのかな......",
          DialogueId = 80002002,
          GUID = "C846D074",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D074"
        },
        [80002003] = {
          ContentJP = "あれ？反応が全く出てこない......同じ色で描かないとだめなのかな？",
          DialogueId = 80002003,
          GUID = "C846D09E",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D09E"
        },
        [80002004] = {
          ContentJP = "フィーナの手元にはまだほかの絵具がないの。迷宮の中で探してみよう。",
          DialogueId = 80002004,
          GUID = "C846D0C8",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D0C8"
        },
        [80002005] = {
          ContentJP = "うぅ......こっちがロックされてるみたい。そっちから謎解きしなきゃならないね。",
          DialogueId = 80002005,
          GUID = "C846D0F2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D0F2"
        },
        [80002006] = {
          ContentJP = "ユニコーンの{性别:お兄さん|お姉さん}が化け物から逃れるため、家族と一緒に狭い洞穴に隠れてて......",
          DialogueId = 80002006,
          GUID = "C846D11C",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D11C"
        },
        [80002007] = {
          ContentJP = "その後、{性别:彼ら|彼女たち}は勇気を出して武器を手に取り、化け物に立ち向かった。",
          DialogueId = 80002007,
          GUID = "C846D146",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D146"
        },
        [80002008] = {
          ContentJP = "やがて、ユニコーンの{性别:お兄さん|お姉さん}が家族と一緒に穢獣を撃退し、包囲を突破できた。",
          DialogueId = 80002008,
          GUID = "C846D170",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D170"
        },
        [80002009] = {
          ContentJP = "でも、もっと手強い敵に出くわしたの。",
          DialogueId = 80002009,
          GUID = "C846D19A",
          GuideFacialId = "Confident",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120112/C846D19A"
        },
