        [80004101] = {
          ContentJP = "この森は霧が濃すぎない？",
          DialogueId = 80004101,
          Duration = 3,
          GUID = "C84828D2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004102,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C84828D2"
        },
        [80004102] = {
          ContentJP = "迷子にならないように、この小川に沿って進んでみよう。",
          DialogueId = 80004102,
          Duration = 3,
          GUID = "C84828FC",
          GuideFacialId = "Idle",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C84828FC"
        },
        [80004103] = {
          ContentJP = "ええっと......これらの棘も一部色が欠けてるね。",
          DialogueId = 80004103,
          Duration = 3,
          GUID = "C8482926",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          NextDialogue = 80004104,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8482926"
        },
        [80004104] = {
          ContentJP = "欠けているところに色を足してあげたら、動き始めるかもね。",
          DialogueId = 80004104,
          Duration = 3,
          GUID = "C8482950",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8482950"
        },
        [80004105] = {
          ContentJP = "ナイチンゲール、どうして出てこないの？棘に囚われてるからなの？",
          DialogueId = 80004105,
          Duration = 3,
          GUID = "C848297A",
          GuideFacialId = "Sad",
          HeadIconType = "Npc",
          NextDialogue = 80004106,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C848297A"
        },
        [80004106] = {
          ContentJP = "怖がらないでね、フィーナが助けてあげるから！",
          DialogueId = 80004106,
          Duration = 3,
          GUID = "C84829A4",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C84829A4"
        },
        [80004107] = {
          ContentJP = "棘が生い茂りすぎて、ナイチンゲールの巣がすっかり見えなくなってしまったよ。",
          DialogueId = 80004107,
          Duration = 3,
          GUID = "C84829CE",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80004108,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C84829CE"
        },
        [80004108] = {
          ContentJP = "まずは先の方法で色を付けてあげよう、そうすれば、ナイチンゲールが中から出てこられるはずよ。",
          DialogueId = 80004108,
          Duration = 3,
          GUID = "C84829F8",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C84829F8"
        },
        [80004109] = {
          ContentJP = "道を塞いでいた棘、片付いたみたいね。さあ、前に進んでみようよ、ナイチンゲール！",
          DialogueId = 80004109,
          Duration = 3,
          GUID = "C8482A22",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8482A22"
        },
