        [80004201] = {
          ContentJP = "前の霧、どんどん濃くなってきたみたい......",
          DialogueId = 80004201,
          Duration = 3,
          GUID = "C848393A",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
