          VoiceName = "voice/$Locale$/story/1201/120114/C848393A"
        },
        [80004202] = {
          ContentJP = "ナイチンゲール、道を案内してくれる？",
          DialogueId = 80004202,
          Duration = 3,
          GUID = "C8483964",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483964"
        },
        [80004203] = {
          ContentJP = "わぁ......この石、光ってるよ！石さんのおかげで、霧が少しずつ晴れてきたね～",
          DialogueId = 80004203,
          Duration = 3,
          GUID = "C848398E",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          NextDialogue = 80004204,
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C848398E"
        },
        [80004204] = {
          ContentJP = "また別の石を探しに行こう。",
          DialogueId = 80004204,
          Duration = 3,
          GUID = "C84839B8",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C84839B8"
        },
        [80004205] = {
          ContentJP = "霧のせいで、ちょっとでも道を見失いそう......ナイチンゲールの傍から、離れないでいてね。",
          DialogueId = 80004205,
          Duration = 3,
          GUID = "C84839E2",
          GuideFacialId = "Shock",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C84839E2"
        },
        [80004206] = {
          ContentJP = "ついに霧の迷宮を出たね！ほらほら、森の出口は、もうすぐそこよ！",
          DialogueId = 80004206,
          Duration = 3,
          GUID = "C8483A0C",
          GuideFacialId = "Smile",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A0C"
        },
        [80004207] = {
          ContentJP = "森の向こうに、どんな景色が広がっているかな？すごく楽しみ！",
          DialogueId = 80004207,
          Duration = 3,
          GUID = "C8483A36",
          GuideFacialId = "Happy",
          HeadIconType = "Npc",
          SpeakNpcId = 700142,
          VoiceName = "voice/$Locale$/story/1201/120114/C8483A36"
        },
        [80004208] = {
          ContentJP = "あれ、あれは......大魔法使いとユニコーンの{性别:お兄さん|お姉さん}、蝶々さんまでも！ずっと私たちを待っていたのね。",
          DialogueId = 80004208,
          Duration = 3,
          GUID = "C8483A60",
