          VoiceName = "voice/$Locale$/inv/Xibi/001/C87274F2"
        },
        [80070102] = {
          ContentJP = "では、これからはお前があの執務室を使いなさい。少佐に昇進した褒美のひとつだから。",
          DialogueId = 80070102,
          GUID = "C872751C",
