          SpeakNpcId = 790013,
          TalkActionId = {
            [1] = "790013:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727714"
        },
        [80070115] = {
          ContentJP = "私たちの作戦が帝国のほかの組織に関わる場合、「過程」は重要じゃないの。第十三軍団は陛下の求める「結果」だけを重視するのよ。",
          DialogueId = 80070115,
          GUID = "C872773E",
          IsBlack = 1,
