          GUID = "C8727810",
          NextDialogue = 80070121,
          SpeakNpcId = 790016,
          TalkActionId = {
            [1] = "790015:Think_End",
            [2] = "790016:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727810"
        },
        [80070121] = {
