          VoiceName = "voice/$Locale$/inv/Xibi/001/C8727864"
        },
        [80070123] = {
          ContentJP = "密輸で稼いだお前の身銭に、前線で戦う兵士の血がどれだけこびりついているか、考えたことはあるかしら？",
          DialogueId = 80070123,
