          TalkActionId = {
            [1] = "790013:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87278B8"
        },
        [80070125] = {
          ContentJP = "忠誠の言葉を叫ぶだけのハエなんて、帝国には必要ないのよ。",
          DialogueId = 80070125,
          GUID = "C87278E2",
          NextDialogue = 80070126,
          SpeakNpcId = 790013,
          TalkActionId = {
            [1] = "790013:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Xibi/001/C87278E2"
        },
        [80070126] = {
          ContentJP = "は、うそ、そんな……この程度の額であれば死罪にならないはずだ！き、君も、命をつなぎ止められると語ったではないか！公正に裁判を行っていただきたい！",
          DialogueId = 80070126,
          GUID = "C872790C",
