        [80090100] = {
          ContentJP = "キキキ、今日は何して遊んでやろっかな？",
          DialogueId = 80090100,
          GUID = "C87F4608"
        },
        [80090101] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentJP = "……",
          DialogueId = 80090101,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4632",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090102,
          SpeakNpcId = 92301
        },
        [80090102] = {
          ContentJP = "……",
          DialogueId = 80090102,
          GUID = "C87F465C",
          NextDialogue = 80090103,
          SpeakNpcId = 92301
        },
        [80090103] = {
          ContentJP = "……おい！飲み終えた瞬間にオレ様の姿が消えたってのに。何事もなかったみたいに平然としてんじゃねーよ！",
          DialogueId = 80090103,
          GUID = "C87F4686",
          NextDialogue = 80090104,
          SpeakNpcId = 92301
        },
        [80090104] = {
          ContentJP = "白昼堂々「悪魔の大泥棒」が消えたんだぞ。びっくりしたりとか、心配になったりとかねーのかよ！",
          DialogueId = 80090104,
          GUID = "C87F46B0",
          NextOptions = {
            [1] = 80090105,
            [2] = 80090107
          },
          SpeakNpcId = 92301
        },
        [80090105] = {
          ContentJP = "{性别:急に椅子がひとつ増えたの、タビテの変身だよね？|急に椅子がひとつ増えたの、タビテの変身でしょ？}",
          DialogueId = 80090105,
          GUID = "C87F46DA",
          NextDialogue = 80090106
        },
        [80090106] = {
          ContentJP = "なんだと！？お前、オレの変身術を見抜いてたのか！",
          DialogueId = 80090106,
          FacialId = {
            [1] = "92301:Shock01"
          },
          GUID = "C87F4704",
          NextDialogue = 80090109,
          SpeakNpcId = 92301
        },
        [80090107] = {
          ContentJP = "{性别:心配っていうより、うれしいよ。タビテが椅子に変身してまで僕を楽しませてくれたから。|心配っていうより、うれしいよ。タビテが椅子に変身してまで私を楽しませてくれたから。}",
          DialogueId = 80090107,
          GUID = "C87F472E",
          NextDialogue = 80090108
        },
        [80090108] = {
          ContentJP = "ナヌゥッ！うぬぼれやがって！オレはお前を驚かしたいだけだっての！ビビれよーーこいつめーー！",
          DialogueId = 80090108,
          GUID = "C87F4758",
          NextDialogue = 80090109,
          SpeakNpcId = 92301
        },
        [80090109] = {
          ContentJP = "……ちっ、今回はオレがしくじったけど！次は絶対お前が想像もできないような、とんでもないもんに変身してやるからな！",
          DialogueId = 80090109,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F4782",
          NextDialogue = 80090110,
          SpeakNpcId = 92301
        },
        [80090110] = {
          ContentJP = "何になってやろっかな……酒樽？シャンデリア？それともハンマー？",
          DialogueId = 80090110,
          GUID = "C87F47AC",
          NextDialogue = 80090111,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          }
        },
        [80090111] = {
          ContentJP = "すごい技だよね、タビテのそれ。",
          DialogueId = 80090111,
          GUID = "C87F47D6",
          NextDialogue = 80090112,
          SpeakNpcId = 790008
        },
        [80090112] = {
          ContentJP = "当ったり前だぜ！オレ様のこの能力は……ぎ、ぎなんたら、えーっと、ぎだい？……ぎたい！そうそう「擬態」ってのさ！",
          DialogueId = 80090112,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4800",
          NextDialogue = 80090113,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090113] = {
          ContentJP = "なんにでも擬態することができるの？",
          DialogueId = 80090113,
          GUID = "C87F482A",
          NextDialogue = 80090114,
          SpeakNpcId = 790008
        },
        [80090114] = {
          ContentJP = "キキキ、おうよ！しっかり見てろ――",
          DialogueId = 80090114,
          GUID = "C87F4854",
          NextDialogue = 80090144,
          SpeakNpcId = 92301
        },
        [80090115] = {
          Camera = "159.880188,-5.018555,149.99321,0.000005,1.39885,175.800934,30.000002,159.585938,false,Manual,3.0",
          ContentJP = "私から提示するのは、あなたが断れない条件よ。しっかりと考えたうえで返答しなさいな。",
          DialogueId = 80090115,
          GUID = "C87F487E",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090116,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090116] = {
          ContentJP = "私を目覚めさせるものはビジネスだけど、あなたを目覚めさせるものは、何かしら？",
          DialogueId = 80090116,
          GUID = "C87F48A8",
          NextOptions = {
            [1] = 80090117,
            [2] = 80090119
          },
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090117] = {
          ContentJP = "{性别:ふふっ――僕を目覚めさせるのは、悪魔の大泥棒さんの光り輝く勇姿さ！|ふふっ――私を目覚めさせるのは、悪魔の大泥棒さんの光り輝く勇姿ね！}",
          DialogueId = 80090117,
          GUID = "C87F48D2",
          NextDialogue = 80090118
        },
        [80090118] = {
          ContentJP = "ふふ、ほんと、あなたって口がうまいんだから。あなたの作った飲み物よりも甘々ね？",
          DialogueId = 80090118,
          FacialId = {
            [1] = "790052:Happy01"
          },
          GUID = "C87F48FC",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "790052:Explain02_Start"
          }
        },
        [80090119] = {
          ContentJP = "ふふっ――カミラに教えちゃおうか？",
          DialogueId = 80090119,
          GUID = "C87F4926",
          NextDialogue = 80090120
        },
        [80090120] = {
          ContentJP = "あいつなんて怖くねえし！悪魔の大泥棒は誰にだって捕まらないからなぁ！",
          DialogueId = 80090120,
          FacialId = {
            [1] = "790052:Confident01"
          },
          GUID = "C87F4950",
          NextDialogue = 80090144,
          SpeakNpcId = 790052,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "790052:Angry01_Start"
          }
        },
        [80090121] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentJP = "まあ流石になんにでも擬態できるほどオレも万能じゃないぜ？大きすぎるのとか小さすぎるのは厳しいな。猫はいけてもネズミはアウト。樽はいけても街灯はアウト。",
          DialogueId = 80090121,
          GUID = "C87F497A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090122,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          }
        },
        [80090122] = {
          ContentJP = "まぁだとしても十分だけどな。そこらの缶やゴミ箱に擬態してりゃあ、よっぽどのことがなきゃ見抜かれない！悪党気取りの泥棒なんざオレ様のカモってわけだな！",
          DialogueId = 80090122,
          GUID = "C87F49A4",
          NextOptions = {
            [1] = 80090123,
            [2] = 80090131
          },
          SpeakNpcId = 92301
        },
        [80090123] = {
          ContentJP = "ふぅ……面倒なことが増えたな……",
          DialogueId = 80090123,
          GUID = "C87F49CE",
          NextDialogue = 80090124
        },
        [80090124] = {
          ContentJP = "何をブツブツ言ってるんだ？",
          DialogueId = 80090124,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F49F8",
          NextDialogue = 80090125,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          }
        },
        [80090125] = {
          ContentJP = "いや、タビテのすごさに感心していただけだよ。",
          DialogueId = 80090125,
          GUID = "C87F4A22",
          NextDialogue = 80090126,
          SpeakNpcId = 790008
        },
        [80090126] = {
          ContentJP = "ただ缶とかゴミ箱に擬態するのはやめておいた方がいいんじゃない？蹴っ飛ばされたり、中身を探られたら大変だと思うんだけど……",
          DialogueId = 80090126,
          GUID = "C87F4A4C",
          NextDialogue = 80090127,
          SpeakNpcId = 790008
        },
        [80090127] = {
          ContentJP = "誰がそんな手癖の悪いことするんだよ？",
          DialogueId = 80090127,
          GUID = "C87F4A76",
          NextDialogue = 80090128,
          SpeakNpcId = 92301
        },
        [80090128] = {
          ContentJP = "ええと……通りすがりの好奇心旺盛な街の人……とか？",
          DialogueId = 80090128,
          GUID = "C87F4AA0",
          NextDialogue = 80090129,
          SpeakNpcId = 790008
        },
        [80090129] = {
          ContentJP = "役立ちそうなら利用して、用済みになったらポイってわけか。悪い大人はみんなそうだな！",
          DialogueId = 80090129,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4ACA",
          NextDialogue = 80090130,
          SpeakNpcId = 92301
        },
        [80090130] = {
          ContentJP = "{性别:いや通りすがりの人はそこまで考えてないよ。「悪い大人」なんて言わなくてもさ？|いや通りすがりの人はそこまで考えてないよ。「悪い大人」なんて言わなくてもね？}",
          DialogueId = 80090130,
          GUID = "C87F4AF4",
          NextDialogue = 80090136,
          SpeakNpcId = 790008
        },
        [80090131] = {
          ContentJP = "ほんとにすごいね。タビテに悪意がなさそうで、よかった。",
          DialogueId = 80090131,
          GUID = "C87F4B1E",
          NextDialogue = 80090132
        },
        [80090132] = {
          ContentJP = "どういう意味だ？",
          DialogueId = 80090132,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F4B48",
          NextDialogue = 80090133,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToTalkL_End"
          }
        },
        [80090133] = {
          ContentJP = "{性别:ずる賢い悪者がそんな能力を持っていたら、街全体が大騒ぎになっちゃうだろ？|ずる賢い悪者がそんな能力を持っていたら、街全体が大騒ぎになっちゃうでしょ？}",
          DialogueId = 80090133,
          GUID = "C87F4B72",
          NextDialogue = 80090134,
          SpeakNpcId = 790008
        },
        [80090134] = {
          ContentJP = "ふふん、確かにな！オレ様は悪い大人どもとは月とスッポンぐらい違……ん？それって遠回しに「悪魔の大泥棒」様が賢くないって言ってるよな？",
          DialogueId = 80090134,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F4B9C",
          NextDialogue = 80090135,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090135] = {
          ContentJP = "いやいや。タビテは賢い悪魔だよ。それより「悪い大人」って？",
          DialogueId = 80090135,
          GUID = "C87F4BC6",
          NextDialogue = 80090136,
          SpeakNpcId = 790008
        },
        [80090136] = {
          ContentJP = "弱い者いじめをするのが悪い大人だ！オレが最初に出会った悪い大人は、孤児院で子供たちを世話してたヤツらだけど……チッ、あんなの囚人の管理と一緒だぜ。",
          DialogueId = 80090136,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F4BF0",
          NextDialogue = 80090137,
          SpeakNpcId = 92301
        },
        [80090137] = {
          ContentJP = "腹がへって食いもんを探しに厨房に行っても、悪い大人どもに見つかったら殴られるんだ。理不尽すぎるだろ！そもそもあいつらが飯くれないから腹へってるのに！",
          DialogueId = 80090137,
          GUID = "C87F4C1A",
          NextDialogue = 80090138,
          SpeakNpcId = 92301
        },
        [80090138] = {
          ContentJP = "今度もしあいつらに出くわしたら、ひとりずつ逆さ吊りにしてやる！屋根から宙ぶらりんになってるあいつらの目の前で、厨房の食い物を食らい尽くしてやるのさ！",
          DialogueId = 80090138,
          GUID = "C87F4C44",
          NextOptions = {
            [1] = 80090139,
            [2] = 80090140
          },
          SpeakNpcId = 92301
        },
        [80090139] = {
          ContentJP = "もう過ぎたことだから。今のタビテは悪い大人たちに殴られることはないよ。",
          DialogueId = 80090139,
          GUID = "C87F4C6E",
          NextDialogue = 80090141
        },
        [80090140] = {
          ContentJP = "そうだね、悪い連中には少し痛い目を見せてやらないと。",
          DialogueId = 80090140,
          GUID = "C87F4C98",
          NextDialogue = 80090141
        },
        [80090141] = {
          ContentJP = "おう！それはそうと……",
          DialogueId = 80090141,
          FacialId = {
            [1] = "92301:Satisfy01"
          },
          GUID = "C87F4CC2",
          NextDialogue = 80090142,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090142] = {
          ContentJP = "「悪い大人」の話はまた今度にして、今すぐオレ様と遊びに行こうぜ！ちょうど飲みもんも空になったし！",
          DialogueId = 80090142,
          GUID = "C87F4CEC",
          NextDialogue = 80090143,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          }
        },
        [80090143] = {
          ContentJP = "キキキ、かくれんぼだ！次こそ簡単には見つからないぜ！",
          DialogueId = 80090143,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F4D16",
          SpeakNpcId = 92301
        },
        [80090144] = {
          DialogueId = 80090144,
          DialoguePanelType = "None",
          Duration = 1,
          GUID = "C87F4D17",
          IsBlack = 1
        },
        [80090201] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentJP = "くひぃ～ちょっと塩っ辛いけど美味いぞぉ！なんだか海風の味がするマシュマロみたいだ！",
          DialogueId = 80090201,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F569A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090202,
          SpeakNpcId = 92301
        },
        [80090202] = {
          ContentJP = "なんか大昔に似たようなもんを飲んだ気がするんだよな。親と一緒に乗った船がまだ沈没してなくて、孤児院に押し込められる前のことかな……",
          DialogueId = 80090202,
          GUID = "C87F56C4",
          NextDialogue = 80090203,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Think_Start"
          }
        },
        [80090203] = {
          ContentJP = "もう1回やり直せるんだったら、ひとりでさまようことになっても、あんな場所には行かなかったぜ！悪い大人どもは食い物すらケチるんだからな、あそこでまともな飲みもんなんて出るわけがねえ！",
          DialogueId = 80090203,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F56EE",
          NextDialogue = 80090204,
          SpeakNpcId = 92301
        },
        [80090204] = {
          ContentJP = "さまようことになったって、ゴミ箱を漁れば何かしらは食えるはずだ。悪い大人の魔の手の下で、空きっ腹抱えるよりマシに決まってる。",
          DialogueId = 80090204,
          GUID = "C87F5718",
          NextDialogue = 80090205,
          SpeakNpcId = 92301
        },
        [80090205] = {
          ContentJP = "オレみたいな角の生えたガキは誰も引き取りたがらないんだけどよ。少し育つと、たまに偉そうな客が引き取ったりもするんだよな。金持ちの養子にされるとかなんとかで。",
          DialogueId = 80090205,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F5742",
          NextDialogue = 80090206,
          SpeakNpcId = 92301
        },
        [80090206] = {
          ContentJP = "オレは父親も母親も欲しくないけど、金持ちの家なら必ず食いもんがあるだろう？だから行ってみたかったんだけどな。いたずら好きの悪ガキを金持ちが気に入るはずがない、とか悪い大人どもが言いやがって！",
          DialogueId = 80090206,
          GUID = "C87F576C",
          NextDialogue = 80090207,
          SpeakNpcId = 92301
        },
        [80090207] = {
          ContentJP = "ふん！それがなんだってんだよ！おとなしく言いなりになるオレ様なんて、もうオレ様じゃないぜ！とにかくあんなクソみたいな場所にはもう1日だっていたくなかったからな。客が目を離したすきにスーツケースに変身したんだ。",
          DialogueId = 80090207,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5796",
          NextDialogue = 80090208,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090208] = {
          ContentJP = "金持ちなんてマヌケなもんで、そいつは何も気づかずオレを持って帰ったってわけよ！ただ取っ手代わりにずっと耳をつかまれてたから、痛くて痛くて……危うく地面に落ちるとこだったぜ！",
          DialogueId = 80090208,
          GUID = "C87F57C0",
          NextOptions = {
            [1] = 80090209,
            [2] = 80090211
          },
          SpeakNpcId = 92301
        },
        [80090209] = {
          ContentJP = "{性别:うわ、痛そうだな！これからは僕がタビテの耳を守ってあげるからな！|うわ、痛そうだね！これから私がタビテの耳を守ってあげるね！}",
          DialogueId = 80090209,
          GUID = "C87F57EA",
          NextDialogue = 80090210
        },
        [80090210] = {
          ContentJP = "……なんか変な方向に話がいっちゃったような……まあいい、それは置いといて……",
          DialogueId = 80090210,
          FacialId = {
            [1] = "92301:Doubt01"
          },
          GUID = "C87F5814",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          }
        },
        [80090211] = {
          ContentJP = "そんな場所から逃げ出せたなんて！小さい頃から「悪魔の大泥棒」の片鱗があったんだね！",
          DialogueId = 80090211,
          GUID = "C87F583E",
          NextDialogue = 80090212
        },
        [80090212] = {
          ContentJP = "キキキ、トーゼンだぜ！って言いたいところだけど、あの頃のオレ様は今ほど腕前はよくなかったからな……じゃなきゃ耳を取っ手になんてするわけねぇし！",
          DialogueId = 80090212,
          GUID = "C87F5868",
          NextDialogue = 80090213,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090213] = {
          ContentJP = "実はオレ、引き取られるガキたちに紛れ込もうと考えてたんだ。金持ちの養子になったら、もう空きっ腹を抱えることもないだろうってな。",
          DialogueId = 80090213,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5892",
          NextDialogue = 80090214,
          SpeakNpcId = 92301
        },
        [80090214] = {
          ContentJP = "けど何かが、おかしかったんだ。金持ちの客からツンとする匂いがしてさ。なんか消毒薬みたいな……。それに、わかんねえけど……オレ様にはなんか……あいつの子供を見定める目つきが、ちょっぴり怖くて……",
          DialogueId = 80090214,
          GUID = "C87F58BC",
          NextDialogue = 80090215,
          SpeakNpcId = 92301
        },
        [80090215] = {
          ContentJP = "まるでありゃ……料理人のおっさんが魚とかアヒルを見るような目つきだったぜ！",
          DialogueId = 80090215,
          GUID = "C87F58E6",
          NextDialogue = 80090216,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_Start"
          }
        },
        [80090216] = {
          ContentJP = "いい大人なんて滅多にいないし、オレが出会ってきたのは悪い大人ばかりだからな！ヤツらを信じるより自分を頼りにした方がいいだろ？だから結局は、ガキどもに紛れ込むのはやめて、ひとりでこっそり逃げ出したのさ。",
          DialogueId = 80090216,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F5910",
          NextDialogue = 80090217,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090217] = {
          ContentJP = "これがタビテ様の偉大な第一歩！悪魔の大泥棒への序章だ！",
          DialogueId = 80090217,
          GUID = "C87F593A",
          NextOptions = {
            [1] = 80090218,
            [2] = 80090220
          },
          SpeakNpcId = 92301
        },
        [80090218] = {
          ContentJP = "{性别:タビテは悪魔なんて言うほどの悪い子じゃない。ただ……とっても特別だったんだ。|タビテは悪魔なんて言うほどの悪い子じゃない。ただ……とっても特別だったの。}",
          DialogueId = 80090218,
          GUID = "C87F5964",
          NextDialogue = 80090219
        },
        [80090219] = {
          ContentJP = "悪い子じゃなくて、特別だって？そんな風に言われたことなんてなかった……特別な子、特別な子……キ、キキキ！",
          DialogueId = 80090219,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F598E",
          NextDialogue = 80090223,
          SpeakNpcId = 92301
        },
        [80090220] = {
          ContentJP = "その「金持ちの客」って怪しいと思う。タビテは冷静な判断をしたよ。",
          DialogueId = 80090220,
          GUID = "C87F59B8",
          NextDialogue = 80090221
        },
        [80090221] = {
          ContentJP = "だろだろ！お前もそう思うよな！？",
          DialogueId = 80090221,
          GUID = "C87F59E2",
          NextDialogue = 80090222,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090222] = {
          ContentJP = "あの時のオレは逃げるので精いっぱいだったから……今の実力だったらば、絶対にあいつらを尾行して悪いことしてないか暴いてやったのに！",
          DialogueId = 80090222,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F5A0C",
          NextDialogue = 80090223,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03ToThink_End"
          }
        },
        [80090223] = {
          ContentJP = "無事に脱出できただけでも、十分よくやったよ。自由になれて本当によかった。",
          DialogueId = 80090223,
          GUID = "C87F5A36",
          NextDialogue = 80090224,
          SpeakNpcId = 790008
        },
        [80090224] = {
          ContentJP = "まぁそうだな！自分自身におめでとうさ！やっとこさ新鮮な空気が吸えるようになってからだ。夜空はいつも薄暗く煤けてるわけじゃないって気がついたのは。汚れたガラス越しに見てたぼんやりした星だって、本当はこんなに明るいんだなって。",
          DialogueId = 80090224,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F5A60",
          NextDialogue = 80090225,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090225] = {
          ContentJP = "原っぱの上で寝転がって星を眺めながら眠って、目覚めた次の日にはすげえ晴れた空が広がっててな！それからオレ様は海辺の町を根城にしたんだけど、もう「悪い大人」に殴られることもなくなったぜ！",
          DialogueId = 80090225,
          GUID = "C87F5A8A",
          NextDialogue = 80090226,
          SpeakNpcId = 92301
        },
        [80090226] = {
          ContentJP = "しかも、あいつとも出会えたし……",
          DialogueId = 80090226,
          GUID = "C87F5AB4",
          NextDialogue = 80090227,
          SpeakNpcId = 92301
        },
        [80090227] = {
          ContentJP = "タビテはいい人にも出会えたんだね？どんな人？",
          DialogueId = 80090227,
          GUID = "C87F5ADE",
          NextDialogue = 80090228,
          SpeakNpcId = 790008
        },
        [80090228] = {
          ContentJP = "大がつくほどのお人好しさ！でも今日は話しくたびれちゃったぜ……「悪魔の大泥棒」だって疲れるのさ！",
          DialogueId = 80090228,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F5B08",
          NextDialogue = 80090229,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090229] = {
          ContentJP = "続きは次回だ！新しい飲みもんを用意してくれたら、話してやるよ！",
          DialogueId = 80090229,
          GUID = "C87F5B32",
          SpeakNpcId = 92301
        },
        [80090301] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentJP = "今回の飲みもんもハンパなくうまかったぞ！キキキ、お前は本当にオレの好みをわかってるな！",
          DialogueId = 80090301,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F6702",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090302,
          SpeakNpcId = 92301
        },
        [80090302] = {
          ContentJP = "昨日の夜も原っぱで夜空を見ながら寝っ転がってたら、空の青が段々と濃くなって、星がポツポツ光ってさ。粉砂糖のかかったブルーベリーラテみたいだったぜ！",
          DialogueId = 80090302,
          GUID = "C87F672C",
          NextDialogue = 80090303,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_Start"
          }
        },
        [80090303] = {
          ContentJP = "孤児院を逃げ出した夜を除けば、のんびり原っぱで寝転ぶなんて、滅多になかったな。",
          DialogueId = 80090303,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6756",
          NextDialogue = 80090304,
          SpeakNpcId = 92301
        },
        [80090304] = {
          ContentJP = "なんせ町に着いたばかりの頃は……散々悪さをしてたから……",
          DialogueId = 80090304,
          GUID = "C87F6780",
          NextDialogue = 80090305,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk02_End"
          }
        },
        [80090305] = {
          ContentJP = "だから町の大人たちはオレ様のことを嫌ってる。「悪魔」って呼ばれても仕方ない……",
          DialogueId = 80090305,
          GUID = "C87F67AA",
          NextOptions = {
            [1] = 80090306,
            [2] = 80090308
          },
          SpeakNpcId = 92301
        },
        [80090306] = {
          ContentJP = "{性别:悪さって……イタズラで済む範囲じゃなかったのか？|悪さって……イタズラで済む範囲じゃなかったの？}",
          DialogueId = 80090306,
          GUID = "C87F67D4",
          NextDialogue = 80090307
        },
        [80090307] = {
          ContentJP = "だってあいつらマジでマヌケだったし！いや……うん、お前の言う通りだ。",
          DialogueId = 80090307,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F67FE",
          NextDialogue = 80090310,
          SpeakNpcId = 92301
        },
        [80090308] = {
          ContentJP = "海辺の町で売ってた魚を全部食べちゃったとか？",
          DialogueId = 80090308,
          GUID = "C87F6828",
          NextDialogue = 80090309
        },
        [80090309] = {
          ContentJP = "全部は無理だ全部は！あ、でも、うん……あながち的外れじゃねえけどさ……",
          DialogueId = 80090309,
          FacialId = {
            [1] = "92301:Angry01"
          },
          GUID = "C87F6852",
          NextDialogue = 80090310,
          SpeakNpcId = 92301
        },
        [80090310] = {
          ContentJP = "実はオレ、屋台の食いもんを盗んで生活してたんだ。露天商のヤツらはカンカンに怒ったけど、オレはその怒った姿をまねしたり、おどけた顔でバカにしてみたり。……それが間違いだとか考えもしなかった。",
          DialogueId = 80090310,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F687C",
          NextDialogue = 80090311,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          }
        },
        [80090311] = {
          ContentJP = "「ちょっとぐらいオレにわけたって飢え死にはしないだろ。ケチくせえな」って。",
          DialogueId = 80090311,
          GUID = "C87F68A6",
          NextDialogue = 80090312,
          SpeakNpcId = 92301
        },
        [80090312] = {
          ContentJP = "あいつに出会うまでは……",
          DialogueId = 80090312,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F68D0",
          NextDialogue = 80090313,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          }
        },
        [80090313] = {
          ContentJP = "あいつは魚屋の店主の娘だった。あいつんちのモノを盗んでも、あいつは殴らなかった。逆に魚をわけてくれたのさ。挙句に家族はどこかって訊いてきて、「迷子だったらうちに泊まってもいいんだよ」なんて言い出しやがってな。あんなお人好しに出会ったの、初めてだったんだ。",
          DialogueId = 80090313,
          GUID = "C87F68FA",
          NextDialogue = 80090314,
          SpeakNpcId = 92301
        },
        [80090314] = {
          ContentJP = "それからいろいろあって、あいつ家がなくなっちゃって。どうにもならず孤児院行きに……ってダメに決まってるだろ！オレと同じ苦しみを味わわせてたまるもんか！だからあいつを連れ出した！一緒に生きてくって決めたんだ！",
          DialogueId = 80090314,
          GUID = "C87F6924",
          NextDialogue = 80090315,
          SpeakNpcId = 92301
        },
        [80090315] = {
          ContentJP = "一緒に太陽の下で笑ったり、浜辺で水かけっこしたり、泥んこ道を走ったり。オレが小動物に化けてあいつを笑わせてやろうって。",
          DialogueId = 80090315,
          GUID = "C87F694E",
          NextDialogue = 80090316,
          SpeakNpcId = 92301
        },
        [80090316] = {
          ContentJP = "あいつはオレ様を「タビテお姉さん」って呼ぶんだぜ！？オレと一緒にその日暮らしの毎日だったのに、「幸せだね」ってずっと言ってくれてた。",
          DialogueId = 80090316,
          GUID = "C87F6978",
          NextDialogue = 80090317,
          SpeakNpcId = 92301
        },
        [80090317] = {
          ContentJP = "いい大人からモノを盗むのをやめたきっかけはあいつなんだ！あいつがいたから、オレ様は悪い大人どもをこらしめる「悪魔の大泥棒」になるって決意できたのさ！",
          DialogueId = 80090317,
          GUID = "C87F69A2",
          NextOptions = {
            [1] = 80090318,
            [2] = 80090320
          },
          SpeakNpcId = 92301
        },
        [80090318] = {
          ContentJP = "その子の優しさに応えたかったんだね？",
          DialogueId = 80090318,
          GUID = "C87F69CC",
          NextDialogue = 80090319
        },
        [80090319] = {
          ContentJP = "ああ、あいつを悲しませたくなかった。",
          DialogueId = 80090319,
          GUID = "C87F69F6",
          NextDialogue = 80090326,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090320] = {
          ContentJP = "タビテお姉さん！",
          DialogueId = 80090320,
          GUID = "C87F6A20",
          NextDialogue = 80090321
        },
        [80090321] = {
          ContentJP = "な、なんのつもりだ急に！？や、やめ、こら、恥ずかしいだろ！",
          DialogueId = 80090321,
          FacialId = {
            [1] = "92301:Unacceptable01"
          },
          GUID = "C87F6A4A",
          NextDialogue = 80090322,
          SpeakNpcId = 92301
        },
        [80090322] = {
          ContentJP = "{性别:僕も同じように呼んだらタビテが一緒に暮らしてくれるかなって……|私も同じように呼んだらタビテが一緒に暮らしてくれるかなって……}",
          DialogueId = 80090322,
          GUID = "C87F6A74",
          NextDialogue = 80090323,
          SpeakNpcId = 790008
        },
        [80090323] = {
          ContentJP = "ギッ！？お、お前もう大人だろうが！8歳の子供と自分を一緒にするんじゃねえっての！",
          DialogueId = 80090323,
          GUID = "C87F6A9E",
          NextDialogue = 80090324,
          SpeakNpcId = 92301
        },
        [80090324] = {
          ContentJP = "冗談だって。タビテはその子のことをすごく気にかけていたんだね？",
          DialogueId = 80090324,
          GUID = "C87F6AC8",
          NextDialogue = 80090325,
          SpeakNpcId = 790008
        },
        [80090325] = {
          ContentJP = "「いい人からモノを盗むのはいいことなの？」って、あいつに言われてさ。",
          DialogueId = 80090325,
          GUID = "C87F6AF2",
          NextDialogue = 80090326,
          SpeakNpcId = 92301
        },
        [80090326] = {
          ContentJP = "「露天商どものどこがいい人なんだよ。オレ様が腹ペコなのを見ても何もくれやしないし、怒ってばかりの悪いヤツらだぞ！」って最初は思ってたんだけど。",
          DialogueId = 80090326,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6B1C",
          NextDialogue = 80090327,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_Start"
          }
        },
        [80090327] = {
          ContentJP = "あとになって気づいたんだ。露天商はオレが食いもんを盗んでも、知らないフリしてたってことに。",
          DialogueId = 80090327,
          GUID = "C87F6B46",
          NextDialogue = 80090328,
          SpeakNpcId = 92301
        },
        [80090328] = {
          ContentJP = "オレを殴ろうとした露天商も、少し追いかけるだけで諦めたし……も、もちろん、この大泥棒様の逃げ足が速いからってのもあるけどさ！",
          DialogueId = 80090328,
          GUID = "C87F6B70",
          NextDialogue = 80090329,
          SpeakNpcId = 92301
        },
        [80090329] = {
          ContentJP = "ある露天商なんかは頼んでもないのに売れ残った食いもんをオレに残しておいてくれた。「オレ様を恐れるあまり、みかじめ料を払うようになったか！」なんて思ってたけど……",
          DialogueId = 80090329,
          GUID = "C87F6B9A",
          NextDialogue = 80090330,
          SpeakNpcId = 92301
        },
        [80090330] = {
          ContentJP = "オレ様は自分に酷いことをした連中だけ根に持って、いい人は見て見ぬフリをしてたんだよ。",
          DialogueId = 80090330,
          GUID = "C87F6BC4",
          NextDialogue = 80090331,
          SpeakNpcId = 92301
        },
        [80090331] = {
          ContentJP = "……そう考えると、胸になにがが詰まったみたいな気分になって、食いもんも味がしなくなった。",
          DialogueId = 80090331,
          FacialId = {
            [1] = "92301:Sad01"
          },
          GUID = "C87F6BEE",
          NextDialogue = 80090332,
          SpeakNpcId = 92301
        },
        [80090332] = {
          ContentJP = "オレは「悪い大人」への恨みを、露天商たちにぶつけてただけ。",
          DialogueId = 80090332,
          GUID = "C87F6C18",
          NextDialogue = 80090333,
          SpeakNpcId = 92301
        },
        [80090333] = {
          ContentJP = "オレは本当に、ただの「悪魔」だったってことだ……",
          DialogueId = 80090333,
          GUID = "C87F6C42",
          NextOptions = {
            [1] = 80090334,
            [2] = 80090336
          },
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk03_End"
          }
        },
        [80090334] = {
          ContentJP = "それでもタビテは偉いよ。一生かけても自分の過ちを直視できない人だっているのに。",
          DialogueId = 80090334,
          GUID = "C87F6C6C",
          NextDialogue = 80090335
        },
        [80090335] = {
          ContentJP = "ありがとな……うん、でも……慰めなんていらねえさ。間違いは間違いなんだし。",
          DialogueId = 80090335,
          FacialId = {
            [1] = "92301:None"
          },
          GUID = "C87F6C96",
          NextDialogue = 80090338,
          SpeakNpcId = 92301
        },
        [80090336] = {
          ContentJP = "タビテだっていつかは大人になる。ずっといい人をいじめ続けたら、悪い大人になっちゃうね？",
          DialogueId = 80090336,
          GUID = "C87F6CC0",
          NextDialogue = 80090337
        },
        [80090337] = {
          ContentJP = "お前の言う通りだぜ……ああ、叱れよ、もっと叱ってくれ。そこには口答えもしないし、おとなしく聞くさ。",
          DialogueId = 80090337,
          GUID = "C87F6CEA",
          NextDialogue = 80090338,
          SpeakNpcId = 92301
        },
        [80090338] = {
          ContentJP = "ともかく、今のオレ様は泥棒や悪い大人からしか盗まない！いい人を傷つけない大泥棒って格好いいしな！",
          DialogueId = 80090338,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F6D14",
          NextDialogue = 80090339,
          SpeakNpcId = 92301
        },
        [80090339] = {
          ContentJP = "悪党ってヤツらはたんまりカネを貯め込んでるんだ。オレ様はもう腹の足しには困ってないけど、時々ちょっかい出して、怒った顔を見て……キキキ！毎日楽しく過ごしてるぜ！",
          DialogueId = 80090339,
          GUID = "C87F6D3E",
          NextOptions = {
            [1] = 80090340
          },
          SpeakNpcId = 92301
        },
        [80090340] = {
          ContentJP = "それって、からかうのが目的になっていない？",
          DialogueId = 80090340,
          GUID = "C87F6D68",
          NextDialogue = 80090341
        },
        [80090341] = {
          ContentJP = "当たり前だ、あ、いや！ゲホゲホ……違う！これは「勧善懲悪」ってこと！痛い目を見ないと反省できないヤツらなんだからな、こうして「いい人をいじめるな」ってわからせるんだよ！",
          DialogueId = 80090341,
          GUID = "C87F6D92",
          NextDialogue = 80090342,
          SpeakNpcId = 92301
        },
        [80090342] = {
          ContentJP = "ああってか喉がカラカラだ！ずっとしゃべりっぱなしだったしな！",
          DialogueId = 80090342,
          GUID = "C87F6DBC",
          NextDialogue = 80090343,
          SpeakNpcId = 92301
        },
        [80090343] = {
          ContentJP = "キキキ、さっきのブルーベリーの飲みもん、もう1杯くれよ！",
          DialogueId = 80090343,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F6DE6",
          SpeakNpcId = 92301
        },
        [80090401] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentJP = "うまい！何度飲んでも飽きねえぜ！大泥棒様はあんまり人を褒めないが、いつも美味いもん用意してくれるお前は称えてやるぞ！",
          DialogueId = 80090401,
          FacialId = {
            [1] = "92301:Smile01"
          },
          GUID = "C87F776A",
          LookAt = {
            [1] = "92301:p(18000P1)"
          },
          NextDialogue = 80090402,
          SpeakNpcId = 92301
        },
        [80090402] = {
          ContentJP = "キキキ、タダでいっぱい飲ませてもらってるからな。この大泥棒様の腕前も見せてやるぜ！",
          DialogueId = 80090402,
          FacialId = {
            [1] = "92301:Smile02"
          },
          GUID = "C87F7794",
          NextDialogue = 80090403,
          SpeakNpcId = 92301
        },
        [80090403] = {
          ContentJP = "目の前には怪しい黒い液体が置かれている。小さな泡が絶えず昇ってきて、匂いはヤバいの一言に尽きる。中には色々なドライフルーツやキャンディが入っているのだが。",
          DialogueId = 80090403,
          GUID = "C87F77BE",
          NextDialogue = 80090404
        },
        [80090404] = {
          ContentJP = "じゃじゃじゃじゃーん！これがタビテ様の特製スペシャルドリンク――名づけて「デビルシーフ」！オレ様と同じ称号を持つ代物だ！キキキ、オレの感謝の気持ちをぜーんぶブチこんでやったぜ！",
          DialogueId = 80090404,
          GUID = "C87F77E8",
          NextOptions = {
            [1] = 80090405,
            [2] = 80090410
          },
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_Start"
          }
        },
        [80090405] = {
          ContentJP = "いや、飲まないけど。",
          DialogueId = 80090405,
          GUID = "C87F7812",
          NextDialogue = 80090406
        },
        [80090406] = {
          ContentJP = "はぁお前センスねえぞ！？こいつは世界でたった1杯の「悪魔の大泥棒」なのに！？",
          DialogueId = 80090406,
          FacialId = {
            [1] = "92301:Unhappy01"
          },
          GUID = "C87F783C",
          NextDialogue = 80090407,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_DisagreeHead"
          }
        },
        [80090407] = {
          ContentJP = "使ってる材料はいい大人たちがオレ様に分けてくれたもんだ！食べるのがもったいなくて少しずつ貯めてたのを全部ブチこんでるんだから、ハンパねえとんでもねえ計り知れねえうまさなんだぞ！",
          DialogueId = 80090407,
          GUID = "C87F7866",
          NextDialogue = 80090408,
          SpeakNpcId = 92301
        },
        [80090408] = {
          ContentJP = "ならこうしようぜ！大泥棒様とお前で半分ずつだ！うぉっほん、この提案はオレ様が飲みたいからじゃないぞ？臆病者に手本ってヤツを見せるために、しょうがなく飲むんだからな？",
          DialogueId = 80090408,
          FacialId = {
            [1] = "92301:Confident01"
          },
          GUID = "C87F7890",
          NextDialogue = 80090409,
          SpeakNpcId = 92301
        },
        [80090409] = {
          ContentJP = "ほら、乾杯だ！",
          DialogueId = 80090409,
          GUID = "C87F78BA",
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          }
        },
        [80090410] = {
          ContentJP = "わかった、飲むよ。",
          DialogueId = 80090410,
          GUID = "C87F78E4",
          NextDialogue = 80090411
        },
        [80090411] = {
          ContentJP = "わかってるねえ！見る目あるじゃんか！",
          DialogueId = 80090411,
          FacialId = {
            [1] = "92301:Happy01"
          },
          GUID = "C87F790E",
          NextDialogue = 80090412,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_AgreeHead"
          }
        },
        [80090412] = {
          ContentJP = "使ってる材料はいい大人たちがオレ様に分けてくれたもんだ！食べるのがもったいなくて少しずつ貯めてたのを全部ブチこんでるんだから、ハンパねえとんでもねえ計り知れねえうまさなんだぞ！",
          DialogueId = 80090412,
          GUID = "C87F7938",
          NextDialogue = 80090413,
          SpeakNpcId = 92301
        },
        [80090413] = {
          ContentJP = "こんなレアもの誰に飲ませるって考えたら……やっぱりお前に味わってもらいたいし？でもちょびっとは分けてくれよ？キキキ、この大泥棒様も「世界一うまい飲み物」がどんな味か気になるからな！",
          DialogueId = 80090413,
          GUID = "C87F7962",
          NextDialogue = 80090414,
          SpeakNpcId = 92301
        },
        [80090414] = {
          ContentJP = "はいはい！気まずい話はおしまい。ほら、乾杯！",
          DialogueId = 80090414,
          GUID = "C87F798C",
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Talk01_End"
          }
        },
        [80090415] = {
          ContentJP = "タビテのスペシャルドリンクをふたりで一緒に飲んだ。奇妙な甘さが口の中に広がったかと思うと、そこであなたは意識を失った。",
          DialogueId = 80090415,
          GUID = "C87F79B6",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}"
        },
        [80090416] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentJP = "息はある。寝てるだけっぽいし大丈夫かな、知らんけど。",
          DialogueId = 80090416,
          DisableMouth = 1,
          FacialId = {
            [1] = "92301:Close"
          },
          GUID = "C87F79E0",
          IsBlack = 1,
          NextDialogue = 80090417,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao",
          TalkActionId = {
            [1] = "92301:Zhangyu_Story_Tentacle"
          }
        },
        [80090417] = {
          ContentJP = "ふぎぃ……びび、びっくりした……なんでも全部いれちゃうのはヤバいってタビテに言ったじゃんか……このまま何事かが、起きちゃったら……ちゃったら……ひいぃ……",
          DialogueId = 80090417,
          DisableMouth = 1,
          GUID = "C87F7A0A",
          IsBlack = 1,
          NextDialogue = 80090418,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090418] = {
          ContentJP = "キキキ、頭ブッ壊れたんじゃね？変な後遺症が残っちまうかもな！かもな！",
          DialogueId = 80090418,
          DisableMouth = 1,
          GUID = "C87F7A34",
          IsBlack = 1,
          NextDialogue = 80090419,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090419] = {
          ContentJP = "縁起でもない！",
          DialogueId = 80090419,
          DisableMouth = 1,
          GUID = "C87F7A5E",
          IsBlack = 1,
          NextOptions = {
            [1] = 80090420
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090420] = {
          ContentJP = "{性别:……誰だ？|……誰なの？}",
          DialogueId = 80090420,
          GUID = "C87F7A88",
          NextDialogue = 80090421
        },
        [80090421] = {
          ContentJP = "タビテの体から伸びた何本かの触手が、あなたに向かって緩やかに揺れているのが見える。",
          DialogueId = 80090421,
          DisableMouth = 1,
          GUID = "C87F7AB2",
          NextDialogue = 80090422
        },
        [80090422] = {
          ContentJP = "んぇー聞こえたー？{nickname}、私たちに話しかけてるよー？",
          DialogueId = 80090422,
          DisableMouth = 1,
          GUID = "C87F7ADC",
          NextDialogue = 80090423,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090423] = {
          ContentJP = "吾輩の知る限りでは、吾輩たちの声を傾聴できるのはタビテだけのはずだが？",
          DialogueId = 80090423,
          DisableMouth = 1,
          GUID = "C87F7B06",
          NextDialogue = 80090424,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090424] = {
          ContentJP = "……大変です大変です、不味いですよ！本当に何事かが起きちゃいました！やっぱりですね、5号が余計なことを言うと絶対その通りになっちゃうんです！もうお願いだから絶対に口を開かないでくださいね！",
          DialogueId = 80090424,
          DisableMouth = 1,
          GUID = "C87F7B30",
          NextOptions = {
            [1] = 80090425
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wenhao"
        },
        [80090425] = {
          ContentJP = "触手が……喋ってる……？",
          DialogueId = 80090425,
          GUID = "C87F7B5A",
          NextDialogue = 80090426
        },
        [80090426] = {
          ContentJP = "えっと……こんにちは、でよろしいのですかね？私たちはタビテの触手ですよ。こんな状況でお話することになるなんて夢にも思いませんでしたね！人生やっぱり何が起きるかわかりませんね！アハ、アハハハハ……",
          DialogueId = 80090426,
          DisableMouth = 1,
          GUID = "C87F7B84",
          NextDialogue = 80090427,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090427] = {
          ContentJP = "ああ……わ、私らの声が聞こえるのは……多分あの飲み物のせい……変なの飲ませてごめんなさいなんだけど……わざとじゃないの……タビテも私らもわざとじゃ……うううう……",
          DialogueId = 80090427,
          DisableMouth = 1,
          GUID = "C87F7BAE",
          NextOptions = {
            [1] = 80090428,
            [2] = 80090429
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2"
        },
        [80090428] = {
          ContentJP = "{性别:タビテは大丈夫なのか？|タビテは大丈夫なの？}",
          DialogueId = 80090428,
          GUID = "C87F7BD8",
          NextDialogue = 80090430
        },
        [80090429] = {
          ContentJP = "{性别:僕、大丈夫なのか？|私、大丈夫なの？}",
          DialogueId = 80090429,
          GUID = "C87F7C02",
          NextDialogue = 80090430
        },
        [80090430] = {
          ContentJP = "吾輩の所見では、貴君らの現在の状況は、何点かの――特別な食材により生じた顛末かと。少し眠れば差し当たっての問題はなかろう。",
          DialogueId = 80090430,
          DisableMouth = 1,
          GUID = "C87F7C2C",
          NextDialogue = 80090431,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3"
        },
        [80090431] = {
          ContentJP = "しかし、ウォッホン――このように貴君との出会いを果たしたのは偶然でなく計画通り！全触手が吾輩の指揮下で協力して、この大泥棒の飲み物を調合したが故である！",
          DialogueId = 80090431,
          DisableMouth = 1,
          GUID = "C87F7C56",
          NextDialogue = 80090432,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3"
        },
        [80090432] = {
          ContentJP = "えぇ？飲み物の調合なんてタビテは全然わかりませんし、適当にキレイなキノコをスライスして放り込んだからではありませんかね……？",
          DialogueId = 80090432,
          DisableMouth = 1,
          GUID = "C87F7C80",
          NextDialogue = 80090433,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090433] = {
          ContentJP = "キキキ、3号が偉そうに宣ってら。あんまり偉そうにすると、次はこの飲み物の食材になっちまうぜ。キキキ……",
          DialogueId = 80090433,
          DisableMouth = 1,
          GUID = "C87F7CAA",
          NextDialogue = 80090434,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu5"
        },
        [80090434] = {
          ContentJP = "ひひぃー、恐ろしやぁぁー！",
          DialogueId = 80090434,
          DisableMouth = 1,
          GUID = "C87F7CD4",
          NextDialogue = 80090435,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2"
        },
        [80090435] = {
          ContentJP = "騒ぐとー……みんな疲れるってー……というかー……{nickname}、怖がってるしー……",
          DialogueId = 80090435,
          DisableMouth = 1,
          GUID = "C87F7CFE",
          NextOptions = {
            [1] = 80090436
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu4"
        },
        [80090436] = {
          ContentJP = "{性别:そっか、夢か。僕、気絶しているんだね。|そっか、夢か。私、気絶しているのね。}",
          DialogueId = 80090436,
          GUID = "C87F7D28",
          NextDialogue = 80090437
        },
        [80090437] = {
          ContentJP = "夢と思ってくださっても構いませんが……飲み物の効果がどこまで続くかも不明ですし……あの、せっかくですので……私たちあなたに伝えたいことがたくさんあるんです！この機会にえっとあの……ほら1号から！",
          DialogueId = 80090437,
          DisableMouth = 1,
          GUID = "C87F7D52",
          NextDialogue = 80090438,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090438] = {
          ContentJP = "……俺の意識は海で生まれた。海難事故の最中だったかな。いつ死んでもおかしくない状況でふたり漂流してた。タビテは俺と話すことで、あの状況に堪えたんだ。",
          DialogueId = 80090438,
          DisableMouth = 1,
          GUID = "C87F7D7C",
          NextDialogue = 80090439,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1"
        },
        [80090439] = {
          ContentJP = "わ、わ、私は孤児院で目覚めた……新しい場所で慣れてないのもあったけど……大人たちが酷い態度で……た、た、タビテは、ほんと、怖かったはずなのに……弱みを見せたくないからって誰の前でも強気で……なのに……夜になるたび、私を抱き締めて震えてた……",
          DialogueId = 80090439,
          DisableMouth = 1,
          GUID = "C87F7DA6",
          NextDialogue = 80090440,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu2"
        },
        [80090440] = {
          ContentJP = "吾輩は孤児院の厨房にてこの寄り合いに加入した。危急の際は吾輩が適切な采配を振るって警備網をあざむき、パンを半かけ収集する大戦果を得たこともある！",
          DialogueId = 80090440,
          DisableMouth = 1,
          GUID = "C87F7DD0",
          NextDialogue = 80090441,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3"
        },
        [80090441] = {
          ContentJP = "吾輩の口調に関しては、孤児院院長の完コピでもあるのだ。",
          DialogueId = 80090441,
          DisableMouth = 1,
          GUID = "C87F7DFA",
          NextDialogue = 80090442,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3"
        },
        [80090442] = {
          ContentJP = "くはぁ……ねむー……私は孤児院を脱出した夜に目覚めたねー……生き延びたのはいいけど、もう疲れたしんどいマジ無理って感じでー……だから安全な場所まで逃げ切ってから、すぐタビテと一緒に原っぱで寝たっけなー……",
          DialogueId = 80090442,
          DisableMouth = 1,
          GUID = "C87F7E24",
          NextDialogue = 80090443,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu4"
        },
        [80090443] = {
          ContentJP = "キキキ、お次はオレ様だ！オレ様はタビテの最高のダチって感じだな！一緒んなって、略奪したんだよ！最高に爽快なんだぜ！キャッホー！",
          DialogueId = 80090443,
          DisableMouth = 1,
          GUID = "C87F7E4E",
          NextDialogue = 80090444,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu5"
        }
      }
    end
  },
  {
    MinKey = 80090444,
