    Loader = function()
      return {
        [80090444] = {
          ContentJP = "あなた本当いい加減にしてくださいね！すみません、この子はまだ分別がついてなくて……！えぇっと、ゴホン、次は私ですね！私はみんなの中で一番新しい存在でして、意識を持ち始めたのはまだ最近なんです。",
          DialogueId = 80090444,
          DisableMouth = 1,
          GUID = "C87F7E78",
          NextDialogue = 80090445,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090445] = {
          ContentJP = "実はずっと前に一度だけ目覚めたことはあるんですが……タビテはあの魚屋の子と離ればなれになってから、口にはしませんが悲しくて仕方がなかったようで……私もあの頃に囚われてますから、逃げるように眠ってしまいました。",
          DialogueId = 80090445,
          DisableMouth = 1,
          GUID = "C87F7EA2",
          NextDialogue = 80090446,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090446] = {
          ContentJP = "彼女が再び心を通じ合える人と出会うまでは——間違いないですね。私はあなたのお陰で目覚めたんです。",
          DialogueId = 80090446,
          DisableMouth = 1,
          GUID = "C87F7ECC",
          NextDialogue = 80090447,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090447] = {
          ContentJP = "ありがとうございます、タビテに優しく接してくれて。あなたの暖かい心が、私をまどろみから引き上げてくれました。感謝の気持ちを贈りたいと思いまして、私の提案でタビテは飲み物を作ったのですが……",
          DialogueId = 80090447,
          DisableMouth = 1,
          GUID = "C87F7EF6",
          NextDialogue = 80090448,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090448] = {
          ContentJP = "まさかここまで加減を知らない子だとは私も予想してなかったんです！アハハ……飲み物の作り方なんてなにもわからないものでして、タビテったらなんでも手当たり次第に放り込んじゃいましたから――それにみんなも！特に3号と5号なんて酷すぎます！もっとやれってタビテを煽ったんです！",
          DialogueId = 80090448,
          DisableMouth = 1,
          GUID = "C87F7F20",
          NextDialogue = 80090449,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090449] = {
          ContentJP = "ごめんなさい、申し開きのしようも……",
          DialogueId = 80090449,
          DisableMouth = 1,
          GUID = "C87F7F4A",
          NextOptions = {
            [1] = 80090450
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu6"
        },
        [80090450] = {
          ContentJP = "ははは——大丈夫だよ。",
          DialogueId = 80090450,
          GUID = "C87F7F74",
          NextDialogue = 80090451
        },
        [80090451] = {
          ContentJP = "……",
          DialogueId = 80090451,
          DisableMouth = 1,
          GUID = "C87F7F9E",
          NextDialogue = 80090452,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1"
        },
        [80090452] = {
          ContentJP = "タビテ、目を覚ますかも。お前はどうだ？",
          DialogueId = 80090452,
          DisableMouth = 1,
          GUID = "C87F7FC8",
          NextDialogue = 80090453,
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu1"
        },
        [80090453] = {
          ContentJP = "性急すぎるではないか！吾輩まだ全然話せておらんぞ……",
          DialogueId = 80090453,
          DisableMouth = 1,
          GUID = "C87F7FF2",
          NextOptions = {
            [1] = 80090454,
            [2] = 80090455
          },
          SpeakNpcId = 92301,
          SpeakNpcName = "UI_Npc_Name_Wanzu3"
        },
        [80090454] = {
          ContentJP = "変な夢だね、早く目を覚まさないと……",
          DialogueId = 80090454,
          GUID = "C87F801C",
          NextDialogue = 80090456
        },
        [80090455] = {
          ContentJP = "なんだか可愛く見えてきた……いつも話せたらいいのに。",
          DialogueId = 80090455,
          GUID = "C87F8046",
          NextDialogue = 80090456
        },
        [80090456] = {
          ContentJP = "あの匂いがまた押し寄せてくる。再び嗅いでも結果は同じく、目の前が真っ黒になってしまう。",
          DialogueId = 80090456,
          GUID = "C87F8070",
          IsBlack = 1,
          NextDialogue = 80090457
        },
        [80090457] = {
          ContentJP = "再び意識を失う前に声が聞こえてくる。「良き者の生涯は幸福であろうぞ」「腐ったモノを食べてもお腹を壊しませんように……」「私たちのタビテをよろしく」……そして、たくさんの「ありがとう」の声が。",
          DialogueId = 80090457,
          GUID = "C87F809A",
          IsBlack = 1
        },
        [80090458] = {
          Camera = "138.374878,24.149231,125.715088,-0.0,-0.799959,-137.395096,35.0,175.0,false,Manual,2.8",
          ContentJP = "あわわわわ、大変だ大変だまずいぞ……！あの飲みもんのせいじゃ……ないよな……？",
          DialogueId = 80090458,
          FacialId = {
            [1] = "92301:Shock01"
          },
          GUID = "C87F80C4",
          NextDialogue = 80090459,
          SpeakNpcId = 92301,
          TalkActionId = {
            [1] = "92301:Sit_Idle_Loop"
          }
        },
        [80090459] = {
          ContentJP = "……こ、この大泥棒様も飲んだけどよ！あんまりにもうまいからちょっぴし気絶しただけで、今はなんともないし！お前も、おい、早く目を覚ましてくれよ！この大泥棒様をビビらすなって！",
          DialogueId = 80090459,
          GUID = "C87F80EE",
          NextOptions = {
            [1] = 80090460
          },
          SpeakNpcId = 92301
        },
        [80090460] = {
          ContentJP = "ストップ……もう大丈夫だから……ちょっと触手と話してただけで……",
          DialogueId = 80090460,
          GUID = "C87F8118",
          NextDialogue = 80090461
        },
        [80090461] = {
          ContentJP = "……",
          DialogueId = 80090461,
          FacialId = {
            [1] = "92301:Shock02"
          },
          GUID = "C87F8142",
          NextDialogue = 80090462,
          SpeakNpcId = 92301
        },
        [80090462] = {
          ContentJP = "医者だ！今医者を呼ぶからなぁぁッ！！",
          DialogueId = 80090462,
          GUID = "C87F816C",
          NextDialogue = 80090463,
          SpeakNpcId = 92301
        },
        [80090463] = {
          ContentJP = "まだ意識が朦朧としている最中、タビテの触手があなたに向かって楽しそうに揺れているのが見えた。",
          DialogueId = 80090463,
          GUID = "C87F8196"
        },
        [80100100] = {
          ContentJP = "これは私たちだけのデートなのよね？",
          DialogueId = 80100100,
          GUID = "C885AEA8",
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AEA8"
        },
        [80100101] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "やっとエスコートしてくれるのね。私がここに来てからずいぶん経つのに、このさまよえる調香師をいつまで待たせるつもりだったの？",
          DialogueId = 80100101,
          FacialId = {
            [1] = "92101:Satisfy01"
          },
          GUID = "C885AED2",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100102,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AED2"
        },
        [80100102] = {
          ContentJP = "薄情な人なんだから……いい？どんなに燃える心であっても、長ぁ～～い、長い時が経つと、冷えてしまうものなの。",
          DialogueId = 80100102,
          GUID = "C885AEFC",
          NextOptions = {
            [1] = 801001021,
            [2] = 801001022
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AEFC"
        },
        [80100103] = {
          ContentJP = "私の扱いが冷たいって言ってるの。ああ、運命って残酷。せっかくの恋の訪れが、スタートからヒエヒエだなんて……",
          DialogueId = 80100103,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF26",
          NextOptions = {
            [1] = 801001041
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF26"
        },
        [80100104] = {
          ContentJP = "ああ、行動より言葉のほうがもっとヒエヒエだなんて。まさか気づいていないの？恋が始まろうとしていることに。",
          DialogueId = 80100104,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF50",
          NextOptions = {
            [1] = 801001041
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF50"
        },
        [80100105] = {
          ContentJP = "しらばっくれないで。もちろん、いまこの瞬間、目と目で通じ合っている私とあなたの恋。",
          DialogueId = 80100105,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885AF7A",
          NextDialogue = 80100106,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AF7A"
        },
        [80100106] = {
          ContentJP = "そんなにビックリしなくてもいいの。あなたにとって、私なんてひと時だけ一緒に過ごしている旅人かもしれない。でも私にとっては、偶然の出会いには必ず意味があるの。ましてやあなたとの出会いは。",
          DialogueId = 80100106,
          GUID = "C885AFA4",
          NextDialogue = 80100107,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFA4"
        },
        [80100107] = {
          ContentJP = "目をそらさないで。あなたのワインレッドの瞳の向こうに私たちの未来が見えるの……うっとりと酔いしれながら愛のダンスを踊っているかも。それか、ハーブ園で散歩を楽しんでいるかもしれないわ。",
          DialogueId = 80100107,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885AFCE",
          NextDialogue = 80100108,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFCE"
        },
        [80100108] = {
          ContentJP = "最後には私の愛になじんで、あなたの全身に私の香りが染みつくの。そうしたら運命が教えてくれるわ。あなたが私の運命の人かどうか。",
          DialogueId = 80100108,
          GUID = "C885AFF8",
          NextDialogue = 80100109,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885AFF8"
        },
        [80100109] = {
          ContentJP = "大丈夫、あなたから一歩を踏み出さなくてもいいの。ただ私の手を握って、ついてきてくれれば。純粋で甘い愛がどんなものか感じさせてあげる。",
          DialogueId = 80100109,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B022",
          NextOptions = {
            [1] = 801001091,
            [2] = 801001092
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B022"
        },
        [80100110] = {
          ContentJP = "うふふ、不安になるのも仕方がないけど。あなたも知ってるでしょ。出会ってすぐに恋に落ちるのは禁止なんて、そんな法律は存在しないの。",
          DialogueId = 80100110,
          GUID = "C885B04C",
          NextDialogue = 80100112,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B04C"
        },
        [80100111] = {
          ContentJP = "まあ……かわいらしい推測ね。じゃあこんな風に言い換えようかしら？私はいま、探しているの。愛という名の舞台で一緒にダンスしてくれるパートナーを。",
          DialogueId = 80100111,
          FacialId = {
            [1] = "92101:Shock02"
          },
          GUID = "C885B076",
          NextDialogue = 80100112,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B076"
        },
        [80100112] = {
          ContentJP = "当然だけど、お断りしたいならそれでもいいの。私があなたのために調合した香りで夢を見ていたと、今日の出来事を終わらせてくれたっていいわ。",
          DialogueId = 80100112,
          GUID = "C885B0A0",
          NextDialogue = 80100113,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0A0"
        },
        [80100113] = {
          ContentJP = "でもあなたには知っておいてほしい――私は……調香師のレベッカは諸国をさまよって、運命の人をずっと探しているの。",
          DialogueId = 80100113,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B0CA",
          NextDialogue = 80100114,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0CA"
        },
        [80100114] = {
          ContentJP = "数え切れないほどの出会いを繰り返して、運命の人を見つけ出したい。それから千の言葉、万の台詞を捧げて、ずっとずっと永遠に一緒にいるの。",
          DialogueId = 80100114,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885B0F4",
          NextDialogue = 80100115,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B0F4"
        },
        [80100115] = {
          ContentJP = "難しいのは承知のうえよ。だって私は毒液に包まれているから。甘くて温かいソレは私を守ってくれるけど、そのせいで私は抱擁やキスの感覚を知らずにいるの。",
          DialogueId = 80100115,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885B11E",
          NextDialogue = 80100116,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B11E"
        },
        [80100116] = {
          ContentJP = "それでも私は諦めないわ。私みたいな変わった存在を世界が生み出したのなら、そんな私を受け入れてくれる存在だって世界は生み出しているはずだもの。",
          DialogueId = 80100116,
          GUID = "C885B148",
          NextDialogue = 80100117,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B148"
        },
        [80100117] = {
          ContentJP = "ねえ、あなたのワインレッドの瞳は、その可能性を見せてくれたのよ。",
          DialogueId = 80100117,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885B172",
          NextDialogue = 80100118,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B172"
        },
        [80100118] = {
          ContentJP = "飲み物で一緒に渇きを癒したこの時間を、私たちの甘酸っぱい初デートとして。私の告白への答えとして受け取ってもいいかしら？",
          DialogueId = 80100118,
          GUID = "C885B19C",
          NextDialogue = 80100119,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B19C"
        },
        [80100119] = {
          ContentJP = "拒絶してもいいの。でも私の秘密は守ってもらう。あなたの口を毒液でトロトロに満たして、封じることになるけど……あなたはどうしたい？",
          DialogueId = 80100119,
          GUID = "C885B1C6",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/001/C885B1C6"
        },
        [80100201] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "またふたりきりで過ごせるのね。ほとんどの人は「あのこと」を知ると私から離れていくのに。",
          DialogueId = 80100201,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885BF3A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801002011
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF3A"
        },
        [80100202] = {
          ContentJP = "気づいているでしょ？",
          DialogueId = 80100202,
          GUID = "C885BF64",
          NextDialogue = 80100203,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF64"
        },
        [80100203] = {
          ContentJP = "ねえ、手を伸ばしてみて。ほら、なんてきれい。タコや傷跡があっても、清潔で無垢な手。疲れた時に塩辛い汗をかく手――",
          DialogueId = 80100203,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885BF8E",
          NextDialogue = 80100204,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BF8E"
        },
        [80100204] = {
          ContentJP = "でも私の手はどう？にじみ出るのは死に至らしめる毒だけ。",
          DialogueId = 80100204,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885BFB8",
          NextDialogue = 80100205,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFB8"
        },
        [80100205] = {
          ContentJP = "手に余る毒液はひねくれ者なお友達なの。森の小道に潜む<Default note=\"text:エジュウ\">穢獣</>を追い払うとか、私を捕まえようとする兵士たちを闇のなかで永遠に眠らせるとか、そういうのには頼りになるけど。",
          DialogueId = 80100205,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885BFE2",
          NextDialogue = 80100206,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885BFE2"
        },
        [80100206] = {
          ContentJP = "私が仲良くしたいモノにも牙を向けてしまうの。泉で顔を洗うだけでも、近づいてきた魚は身体がマヒして息が絶えてしまうわ。",
          DialogueId = 80100206,
          GUID = "C885C00C",
          NextDialogue = 80100207,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C00C"
        },
        [80100207] = {
          ContentJP = "昔は嫌いだった。毒さえなければ私も同じ年頃の女の子たちみたいに過ごせたのに。街で服を選んだり、物陰からこっそり気になる人を観察したり。",
          DialogueId = 80100207,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C036",
          NextOptions = {
            [1] = 801002071,
            [2] = 801002072
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C036"
        },
        [80100208] = {
          ContentJP = "夢とは違うの。昔に少しだけ思い悩んだこと。振り返ってみると笑えるかしらね。",
          DialogueId = 80100208,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C060",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C060"
        },
        [80100209] = {
          ContentJP = "慣れたというより、飼い慣らしたって感じかしら。上手な付き合い方を見つけたの。",
          DialogueId = 80100209,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C08A",
          NextDialogue = 80100210,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C08A"
        },
        [80100210] = {
          ContentJP = "いまの私はこっそりのぞき見る必要もないし、長々と話して探り合う必要もない。私と一緒に人生を歩める人かどうかは、ほんの一瞬、甘く抱きしめるだけでわかるから。",
          DialogueId = 80100210,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C0B4",
          NextDialogue = 80100211,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0B4"
        },
        [80100211] = {
          ContentJP = "毒は私にとって一番の大切な試金石なの――もしいつか本当に、私が抱きしめても耐えられる人が現れたら、その人こそが運命の人よ。",
          DialogueId = 80100211,
          GUID = "C885C0DE",
          NextDialogue = 80100212,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C0DE"
        },
        [80100212] = {
          ContentJP = "残念ながらまだそんな人は現れていないし、この先もずっと出会えないかもしれない。でも薄っぺらで退屈な愛の言葉より、はるかにロマンチックだと思わない？",
          DialogueId = 80100212,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885C108",
          NextDialogue = 80100213,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C108"
        },
        [80100213] = {
          ContentJP = "少なくとも私にとって毒はプレゼントだった。私を恐れる人も、脅す人も、慈しむ人も、媚びる人も、全員を平等に試すことができるもの。",
          DialogueId = 80100213,
          GUID = "C885C132",
          NextDialogue = 80100214,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C132"
        },
        [80100214] = {
          ContentJP = "あちこちさまよう根なし草なのは、昔もいまも同じだけど。もう誰かを羨むことなんてないわ。唯一無二の毒液で、唯一無二の愛を見つけられると信じているもの。",
          DialogueId = 80100214,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C15C",
          NextDialogue = 80100215,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C15C"
        },
        [80100215] = {
          ContentJP = "というわけで質問。今まさに両手を広げている私を、あなたは抱きしめてくれるかしら？",
          DialogueId = 80100215,
          GUID = "C885C186",
          NextOptions = {
            [1] = 801002151,
            [2] = 801002152
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C186"
        },
        [80100216] = {
          ContentJP = "ふふ、怖がらないで。私の昔話をこんなにたくさん聞いてくれたのはあなたが初めてなの。一か八か、チャンスは1度きりだけど。あなたが私の探し人かもしれないでしょ？",
          DialogueId = 80100216,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885C1B0",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1B0"
        },
        [80100217] = {
          ContentJP = "本当に？抱きしめるふりして剣で私の喉を刺し貫くつもりだったり？そんなに警戒しないでいいのに。私たちはほかの人たちとは違う運命を持ってる、似たもの同士じゃない。私にはわかるの。",
          DialogueId = 80100217,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885C1DA",
          NextDialogue = 80100218,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C1DA"
        },
        [80100218] = {
          ContentJP = "あーあ、あなたから始めてくれたデートなのに、拒絶で終わってしまうなんて。とっても残念。",
          DialogueId = 80100218,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C204",
          NextDialogue = 80100219,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C204"
        },
        [80100219] = {
          ContentJP = "まあ私たちに時間はたっぷりとあるものね。いつか後ろからムギュッと捕まえてあげる。気をつけておいてね。",
          DialogueId = 80100219,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885C22E",
          NextOptions = {
            [1] = 801002191
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C22E"
        },
        [80100220] = {
          ContentJP = "まあ、かわいい。警戒した子猫がシャーって威嚇してるみたい……これはちょっと機会を改めたほうがいいかしらね？チャオ、次に会える日を楽しみにしているわ。",
          DialogueId = 80100220,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885C258",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C258"
        },
        [80100221] = {
          Camera = "106.860352,-6.606262,134.715088,0.0,-0.99996,-137.396057,51.444664,130.0,false,Manual,2.8",
          ContentJP = "ねえ、数秒ぶりの再会ね。",
          DialogueId = 80100221,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C282",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100222,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C282"
        },
        [80100222] = {
          ContentJP = "実際にはあんまり警戒していないみたいで、うれしいわ。安心して、今すぐあなたを抱きしめるつもりはないの。ただひとつアドバイスしにきただけ――",
          DialogueId = 80100222,
          GUID = "C885C2AC",
          NextDialogue = 80100223,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2AC"
        },
        [80100223] = {
          ContentJP = "次に私の声を聞いたら、必ず身体ごと振りかえって私を見て。視線を逸らさないで。じゃないと、アブない目に遭ってしまうかもしれないわよ？",
          DialogueId = 80100223,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885C2D6",
          NextDialogue = 80100224,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C2D6"
        },
        [80100224] = {
          ContentJP = "それじゃあ本当に。アリヴェデルチ。",
          DialogueId = 80100224,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885C300",
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/002/C885C300"
        },
        [80100301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "今日は「愛のシンパシー」に呼ばれたの。毒の一滴一滴が、会いたがっているわ。",
          DialogueId = 80100301,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885CFA2",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100302,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFA2"
        },
        [80100302] = {
          ContentJP = "ねえ、試してみない？私たちの心がどれだけ通じ合っているか……今から私が何の話をするか、わかる？",
          DialogueId = 80100302,
          GUID = "C885CFCC",
          NextOptions = {
            [1] = 801003021,
            [2] = 801003022
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFCC"
        },
        [80100303] = {
          ContentJP = "素直なのも、あなたの魅力のひとつね。",
          DialogueId = 80100303,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885CFF6",
          NextDialogue = 80100304,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885CFF6"
        },
        [80100304] = {
          ContentJP = "じゃあ回りくどい話はやめるわ。早速だけど昔のお話を聞いてほしいの。",
          DialogueId = 80100304,
          GUID = "C885D020",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D020"
        },
        [80100305] = {
          ContentJP = "正解、やっぱり私たちは心が通じ合っているみたいね。これなら話しても大丈夫そう。",
          DialogueId = 80100305,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885D04A",
          NextDialogue = 80100306,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D04A"
        },
        [80100306] = {
          ContentJP = "実はね、打ち明けなければいけないことがあるの。警告と言った方が正しいかしら。",
          DialogueId = 80100306,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D074",
          NextDialogue = 80100307,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D074"
        },
        [80100307] = {
          ContentJP = "前にね、私と似た人に会ったことがあるの。彼女は生まれつき炎のような真っ赤な肌を持っていたわ。性格も怒りっぽくて気難しい、汚点や欠点を許せない人よ。",
          DialogueId = 80100307,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D09E",
          NextDialogue = 80100308,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D09E"
        },
        [80100308] = {
          ContentJP = "私みたいに幼い頃から嫌われていた化け物と違って、彼女は一族の使命を背負って、大きな期待を寄せられていたみたい。最終的には囚人を取り締まる正義の断罪者になって、目をつけた罪人は決して逃さないとか。",
          DialogueId = 80100308,
          GUID = "C885D0C8",
          NextDialogue = 80100309,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0C8"
        },
        [80100309] = {
          ContentJP = "でも彼女の炎は私の毒と同じ、近づこうとするすべてを追い払うヤマアラシのトゲなの。善意であれ悪意であれ、誰も近づけない。みんな彼女を恐れて離れていく。",
          DialogueId = 80100309,
          GUID = "C885D0F2",
          NextOptions = {
            [1] = 801003091
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D0F2"
        },
        [80100310] = {
          ContentJP = "ご名答。わかるでしょ？私みたいな生まれつき猛毒を持つ化け物は、ウッカリであれワザとであれ、ほかの人の命を奪ってしまうことがあるから。誰かに追われたって不思議じゃないわ。",
          DialogueId = 80100310,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D11C",
          NextDialogue = 80100311,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D11C"
        },
        [80100311] = {
          ContentJP = "彼女の追跡はネチネチと長く続いたけど、私はあることに気づいたの。彼女も私と同じ、ひとりぼっちの化け物。だから、その点を利用すればいい。",
          DialogueId = 80100311,
          GUID = "C885D146",
          NextDialogue = 80100312,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D146"
        },
        [80100312] = {
          ContentJP = "健気で真剣な感じで心を打ち明けて、彼女を惑わせた。「自分にも同類がいた。このアトラシア大陸でたったひとりの異端者じゃない」「優しく寛大に接すればレベッカは改心するだろう」……って思うよう仕向けたの。",
          DialogueId = 80100312,
          GUID = "C885D170",
          NextDialogue = 80100313,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D170"
        },
        [80100313] = {
          ContentJP = "彼女が私の罪の証拠を隠滅するのを待って、まんまと逃げ出したってわけ。",
          DialogueId = 80100313,
          GUID = "C885D19A",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100314,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D19A"
        },
        [80100314] = {
          ContentJP = "怒りに燃えたあの人が、私を捕まえようと歯ぎしりする姿、想像できるかしら？私をかばうあなたも共犯者とみなされて、もし彼女に捕まったら牢獄送り。そこを理解しておいてね。",
          DialogueId = 80100314,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D1C4",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801003141,
            [2] = 801003142
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1C4"
        },
        [80100315] = {
          ContentJP = "ああ、そういうことだったのね！道理で……初めて会った時に感じていたのよ、溺れそうなくらい危険な香りを。",
          DialogueId = 80100315,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885D1EE",
          NextDialogue = 80100316,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D1EE"
        },
        [80100316] = {
          ContentJP = "将来に起こるかもしれないリスクを伝えたのに、あなたは私を拒絶しない。つまり……あなたにもっと近づいてもいいってことかしら？",
          DialogueId = 80100316,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D218",
          NextDialogue = 80100317,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D218"
        },
        [80100317] = {
          ContentJP = "こんな不穏な過去を打ち明けるのは不安だったの。あなたの反応次第で、私はまたあてのない旅路に逆戻りになるんじゃないかって。",
          DialogueId = 80100317,
          GUID = "C885D242",
          NextDialogue = 80100318,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D242"
        },
        [80100318] = {
          ContentJP = "でも、あなたがもっと危ない目に遭うのも嫌で――私の毒だけでも危ないでしょ？",
          DialogueId = 80100318,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885D26C",
          NextDialogue = 80100319,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D26C"
        },
        [80100319] = {
          ContentJP = "でもよかった。あなたの答えで確信したわ。ここにいれば、きっと運命の人が見つかるはずよ。",
          DialogueId = 80100319,
          GUID = "C885D296",
          NextOptions = {
            [1] = 801003191
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D296"
        },
        [80100320] = {
          ContentJP = "ルッカ共和国からヒュペリアまで探してもまだ見つからないの。私の夢のなかにしか存在しないんじゃないかって思ったこともあるわ。キラキラ輝いて、でもぼんやりとつかみどころがない存在。",
          DialogueId = 80100320,
          GUID = "C885D2C0",
          NextDialogue = 80100321,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2C0"
        },
        [80100321] = {
          ContentJP = "{性别:彼|彼女}は丈夫な身体の持ち主で、私の毒のすべてを受け止めてくれる……曇りひとつない心で、私の愛のすべてを受け入れてくれるの。優しさにあふれた手で、私の悲しみのすべてを拭い去ってくれる……",
          DialogueId = 80100321,
          FacialId = {
            [1] = "92101:Confident02"
          },
          GUID = "C885D2EA",
          NextDialogue = 80100322,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D2EA"
        },
        [80100322] = {
          ContentJP = "この気持ちは……あの人に、{性别:彼|彼女}に届いているのかしら？",
          DialogueId = 80100322,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D314",
          NextOptions = {
            [1] = 801003221,
            [2] = 801003222
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D314"
        },
        [80100323] = {
          ContentJP = "あ……ぷっ……ふふふふ……",
          DialogueId = 80100323,
          FacialId = {
            [1] = "92101:Happy02"
          },
          GUID = "C885D33E",
          NextDialogue = 80100324,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D33E"
        },
        [80100324] = {
          ContentJP = "やっぱりあなたってかわいくて、変わってて、面白い人。",
          DialogueId = 80100324,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D368",
          NextDialogue = 80100325,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D368"
        },
        [80100325] = {
          ContentJP = "今すぐにでもあなたを毒で包めたら……けど軽はずみな冗談で終わらせたくはないわ……",
          DialogueId = 80100325,
          GUID = "C885D392",
          NextDialogue = 80100326,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D392"
        },
        [80100326] = {
          ContentJP = "少しだけ時間をもらえないかしら？どうしたらいいのか、考える時間がほしいの。",
          DialogueId = 80100326,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D3BC",
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3BC"
        },
        [80100327] = {
          ContentJP = "ずるい人ね。突き放しておきながら、そんな曖昧な言葉で希望も残しておくなんて。",
          DialogueId = 80100327,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D3E6",
          NextDialogue = 80100328,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D3E6"
        },
        [80100328] = {
          ContentJP = "「適切な距離」ってどう解釈すればいいのかしら？私にとっての最適な距離ってぴったりくっついて離れないことだもの。でも……あなたの思う適切な距離はどこまでなの？",
          DialogueId = 80100328,
          GUID = "C885D410",
          NextDialogue = 80100329,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D410"
        },
        [80100329] = {
          ContentJP = "他人の前では知らんぷりして、裡で愛を育む秘密のカップルみたいな感じ？それとも今日を限りに二度と会わないつもり？",
          DialogueId = 80100329,
          GUID = "C885D43A",
          NextDialogue = 80100330,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D43A"
        },
        [80100330] = {
          ContentJP = "というより……天秤の両方にあるのは簡単な答えなのかしら。「あなたの望むままに」とか「あなたならもっといい人に出会えるはず」みたいにはっきりした答えを出すのじゃなくて、会話と探り合いを続けるほうを選ぶのね？",
          DialogueId = 80100330,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885D464",
          NextDialogue = 80100331,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D464"
        },
        [80100331] = {
          ContentJP = "私に近づきすぎればあなたは危険な目に合う。離れすぎれば完全に別々の道を進むことになる。",
          DialogueId = 80100331,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885D48E",
          NextDialogue = 80100332,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D48E"
        },
        [80100332] = {
          ContentJP = "最適な結果を見つけるには、ふたりの傾きを何度も測る必要があるの。レシピのない香水を調合する時みたいに。",
          DialogueId = 80100332,
          GUID = "C885D4B8",
          NextOptions = {
            [1] = 801003321
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4B8"
        },
        [80100333] = {
          ContentJP = "ええ。こんな難しいこと初めてだけど、乗り越えられたら探していた答えが導き出せるもの。運命の人が見つかるって信じているから。",
          DialogueId = 80100333,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D4E2",
          NextOptions = {
            [1] = 801003331
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D4E2"
        },
        [80100334] = {
          ContentJP = "ルッカ共和国からヒュペリアまで探してもまだ見つからないの。私の夢のなかにしか存在しないんじゃないかって思ったこともあるわ。キラキラ輝いて、でもぼんやりとつかみどころがない存在。",
          DialogueId = 80100334,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885D50C",
          NextDialogue = 80100335,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D50C"
        },
        [80100335] = {
          ContentJP = "{性别:彼|彼女}は丈夫な身体の持ち主で、私の毒のすべてを受け止めてくれる……曇りひとつない心で、私の愛のすべてを受け入れてくれるの。優しさに溢れた手で、私の悲しみのすべてを拭い去ってくれる……",
          DialogueId = 80100335,
          GUID = "C885D536",
          NextDialogue = 80100336,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D536"
        },
        [80100336] = {
          ContentJP = "かわいくて、変わってて、面白い人よ。それこそ、あなたのような……",
          DialogueId = 80100336,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885D560",
          NextDialogue = 80100337,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D560"
        },
        [80100337] = {
          ContentJP = "少しだけ時間をもらえないかしら？どうしたらいいのか、考える時間がほしいの。",
          DialogueId = 80100337,
          GUID = "C885D58A",
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/003/C885D58A"
        },
        [80100401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "はぁ……",
          DialogueId = 80100401,
          FacialId = {
            [1] = "92101:Sad02"
          },
          GUID = "C885E00A",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextOptions = {
            [1] = 801004011,
            [2] = 801004012
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E00A"
        },
        [80100402] = {
          ContentJP = "そう。とっても悩んで心が乱れているの。その悩みの種はいま私の目の前に現れたあなたよ。",
          DialogueId = 80100402,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E034",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E034"
        },
        [80100403] = {
          ContentJP = "いいえ、タイミングじゃなくて、誘ってくれる人のせい。あなたが招待してくれたあの時から、私の心は乱れてしまったの。",
          DialogueId = 80100403,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E05E",
          NextDialogue = 80100404,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E05E"
        },
        [80100404] = {
          ContentJP = "あなたは純粋無垢に見えるけど、毒で人を窒息させることもできるのね。",
          DialogueId = 80100404,
          GUID = "C885E088",
          NextDialogue = 80100405,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E088"
        },
        [80100405] = {
          ContentJP = "でもあなたは私みたいに初対面から自分が危険な存在だと宣言しない。言葉の網を丹念に編みあげるの。",
          DialogueId = 80100405,
          GUID = "C885E0B2",
          NextDialogue = 80100406,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0B2"
        },
        [80100406] = {
          ContentJP = "意図していないかもしれないけど……だからこそ、私たちはこの場所に留まることに慣れてしまう。いつのまにかあなたの毒に染められて、本来の自分とは違う存在になってしまうの。",
          DialogueId = 80100406,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E0DC",
          NextDialogue = 80100407,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E0DC"
        },
        [80100407] = {
          ContentJP = "ルッカ共和国を離れてから同じ場所にずっと留まることなんてなかったし、本当に大切にしたい人と出会うこともなかった。",
          DialogueId = 80100407,
          GUID = "C885E106",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100408,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E106"
        },
        [80100408] = {
          ContentJP = "今回も同じつもりだった。飽きたら抱き締めて、最後の別れを告げるはずだったのに。",
          DialogueId = 80100408,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E130",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          NextDialogue = 80100409,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E130"
        },
        [80100409] = {
          ContentJP = "ためらってしまうの。体内の毒液が私にヒソヒソと語りかけてくる……お前はここから離れられないって。",
          DialogueId = 80100409,
          FacialId = {
            [1] = "92101:Iyada01"
          },
          GUID = "C885E15A",
          NextDialogue = 80100410,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E15A"
        },
        [80100410] = {
          ContentJP = "受け入れられない、私はそんなこと。そのせいでこんなに心が乱れているの。だからね、私は決めたの。今日こそ休息にピリオドを打って旅立とうって。",
          DialogueId = 80100410,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E184",
          NextDialogue = 80100411,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E184"
        },
        [80100411] = {
          ContentJP = "シンプルに言うと――あなたとサヨナラするつもり。毒液でドロドロに包み込んでね。",
          DialogueId = 80100411,
          FacialId = {
            [1] = "92101:Sad01"
          },
          GUID = "C885E1AE",
          NextDialogue = 80100412,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1AE"
        },
        [80100412] = {
          ContentJP = "さて、あなたの人生は残り数秒となってしまったわ。何か最後に言いたいことはあるかしら？",
          DialogueId = 80100412,
          GUID = "C885E1D8",
          NextOptions = {
            [1] = 801004121,
            [2] = 801004122
          },
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E1D8"
        },
        [80100413] = {
          ContentJP = "逃げる？ふふふ、私は自分の気持ちに正直よ？だって私はあなたの怖がる顔が見たかっただけだから。",
          DialogueId = 80100413,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E202",
          NextDialogue = 80100414,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E202"
        },
        [80100414] = {
          ContentJP = "でも脅しは通じていないみたいね。本当に残念。",
          DialogueId = 80100414,
          GUID = "C885E22C",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E22C"
        },
        [80100415] = {
          ContentJP = "ばれちゃった？全然怖くないの？あなたの怖がる顔が見たかったのに……本当に残念。",
          DialogueId = 80100415,
          FacialId = {
            [1] = "92101:Shock01"
          },
          GUID = "C885E256",
          NextDialogue = 80100416,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E256"
        },
        [80100416] = {
          ContentJP = "じゃあ怖がる顔はあきらめて、代わりに私が本当に決めたことを教えてあげる。",
          DialogueId = 80100416,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E280",
          NextDialogue = 80100417,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E280"
        },
        [80100417] = {
          ContentJP = "あなたと過ごす日々は……いままでの毎日とはまったく違うの。こうやって午後に甘い言葉を語り合って、お互いを探り合う……",
          DialogueId = 80100417,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E2AA",
          NextDialogue = 80100418,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2AA"
        },
        [80100418] = {
          ContentJP = "またねって分かれた後は、傘をさして、人気のない路地でひとりステップを踏むの。さっき話した内容を思い出しながら……",
          DialogueId = 80100418,
          GUID = "C885E2D4",
          NextDialogue = 80100419,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2D4"
        },
        [80100419] = {
          ContentJP = "ふふ……こういうのもロマンチックよね？",
          DialogueId = 80100419,
          FacialId = {
            [1] = "92101:None"
          },
          GUID = "C885E2FE",
          NextDialogue = 80100420,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E2FE"
        },
        [80100420] = {
          ContentJP = "今までの私は、私の抱擁に耐えられる運命の人に焦がれていたわ。でも今日になってやっとわかったの。私が本当に欲しいのは唯一無二の愛、それだけなの。",
          DialogueId = 80100420,
          FacialId = {
            [1] = "92101:Smile01"
          },
          GUID = "C885E328",
          NextDialogue = 80100421,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E328"
        },
        [80100421] = {
          ContentJP = "「抱擁」は私にとっての試金石だったけど。たった一度心がときめいた瞬間に、わかったの。唯一無二の愛を試す必要なんかないって。",
          DialogueId = 80100421,
          GUID = "C885E352",
          NextDialogue = 80100422,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E352"
        },
        [80100422] = {
          ContentJP = "キスや抱擁は絶対じゃない。私の求めているのは香水で言うラストノート。長く、消えることのない香り。",
          DialogueId = 80100422,
          GUID = "C885E37C",
          NextDialogue = 80100423,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E37C"
        },
        [80100423] = {
          ContentJP = "毎日、おはようの挨拶から始めて、私が新しく調合した香水を試しながら、いろいろなレシピを研究して。そんな風に暮らすのも、悪くないかなって。",
          DialogueId = 80100423,
          FacialId = {
            [1] = "92101:Happy01"
          },
          GUID = "C885E3A6",
          NextDialogue = 80100424,
          SpeakNpcId = 92101,
          TalkActionId = {
            [1] = "92101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3A6"
        },
        [80100424] = {
          ContentJP = "故郷の童謡に登場する人魚姫は、好きな人のために手段を尽くして生まれ変わったわ。私もそうするつもり。自分の毒を無効化する香水の調合とか、毒素を浄化する魔法を探してみる。",
          DialogueId = 80100424,
          GUID = "C885E3D0",
          NextDialogue = 80100425,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3D0"
        },
        [80100425] = {
          ContentJP = "そしていつか、あなたを抱きしめることができたら……",
          DialogueId = 80100425,
          GUID = "C885E3FA",
          LookAt = {
            [1] = "92101:p(18000P2)"
          },
          NextDialogue = 80100426,
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E3FA"
        },
        [80100426] = {
          ContentJP = "試すのではなく、ただ、大好きって気持ちを込めて……",
          DialogueId = 80100426,
          FacialId = {
            [1] = "92101:Smile02"
          },
          GUID = "C885E424",
          LookAt = {
            [1] = "92101:p(18000P1)"
          },
          SpeakNpcId = 92101,
          VoiceName = "voice/$Locale$/inv/Shuimu/004/C885E424"
        },
        [80110100] = {
          ContentJP = "おう……あんがとよ。",
          DialogueId = 80110100,
          GUID = "C88C1748",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1748"
        },
        [80110101] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentJP = "お前の作ったカクテルの味を評価しろだ？人選間違ってんじゃねえか？アタシにわかるわけねえだろうが。",
          DialogueId = 80110101,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1772",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110102,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1772"
        },
        [80110102] = {
          ContentJP = "どんな酒だろうと飲めりゃいいんだよ。シェイカーやら瓶やらいじくり回したって、アタシにとっちゃあ詩をタラタラ読まれんのと一緒さ。なんかうるせえなぁってな。",
          DialogueId = 80110102,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C179C",
          NextOptions = {
            [1] = 801101021
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C179C"
        },
        [80110103] = {
          ContentJP = "軍がやんのは戦争だ。ピクニックじゃねえよ。",
          DialogueId = 80110103,
          GUID = "C88C17C6",
          NextDialogue = 80110104,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17C6"
        },
        [80110104] = {
          ContentJP = "おい待て、「帝国軍」だと……",
          DialogueId = 80110104,
          FacialId = {
            [1] = "93101:Doubt01"
          },
          GUID = "C88C17F0",
          NextDialogue = 80110105,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C17F0"
        },
        [80110105] = {
          ContentJP = "……お前、何者だ？何を企んでやがる？目的は？お前を送り込んだヤツは？なにを探ろうとしてる？白状しやがれ。",
          DialogueId = 80110105,
          GUID = "C88C181A",
          NextOptions = {
            [1] = 801101051,
            [2] = 801101052
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C181A"
        },
        [80110106] = {
          ContentJP = "ただの「月狩り人」のくせして、いろいろと知ってんのなあお前は。",
          DialogueId = 80110106,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1844",
          NextDialogue = 80110107,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1844"
        },
        [80110107] = {
          ContentJP = "……わかってんだよ。やたら親切なヤツってのは何か企んでるもんさ。",
          DialogueId = 80110107,
          GUID = "C88C186E",
          NextDialogue = 80110108,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C186E"
        },
        [80110108] = {
          ContentJP = "とにかくお前を帝国軍まで連行すんぞ。んで尋問を受けやがれ。断るってんなら、簀巻きにしてアタシが担いでやる。面倒くせぇし、おとなしく従ってほしいがな。",
          DialogueId = 80110108,
          FacialId = {
            [1] = "93101:Confident01"
          },
          GUID = "C88C1898",
          NextDialogue = 80110109,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1898"
        },
        [80110109] = {
          ContentJP = "（リーンは問答無用で銃を取り出し、真っ黒な銃口があなたの眉間に向けられる――そんな場面があなたの脳裏に浮かんだ）",
          DialogueId = 80110109,
          GUID = "C88C18C2",
          IsBlack = 1,
          NextDialogue = 80110110,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18C2"
        },
        [80110110] = {
          ContentJP = "（こうなるのはわかりきっている。あなたは首をふって、無謀な考えを打ち消した）",
          DialogueId = 80110110,
          GUID = "C88C18EC",
          IsBlack = 1,
          NextDialogue = 80110111,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C18EC"
        },
        [80110111] = {
          ContentJP = "誤解だって。リーンを見かけたから、一緒に一杯どうかなって思っただけだよ。",
          DialogueId = 80110111,
          GUID = "C88C1916",
          NextDialogue = 80110112,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1916"
        },
        [80110112] = {
          ContentJP = "…………",
          DialogueId = 80110112,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1940",
          NextDialogue = 80110113,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1940"
        },
        [80110113] = {
          ContentJP = "あー、コホン。すまねえ、{性别:坊や|嬢ちゃん}。",
          DialogueId = 80110113,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C196A",
          NextDialogue = 80110114,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C196A"
        },
        [80110114] = {
          ContentJP = "怖い物知らずの月狩り人が帝国軍の秘密を暴こうって近づいてきたりすんだよ。アタシが元同業者だからってな。",
          DialogueId = 80110114,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1994",
          NextOptions = {
            [1] = 801101141,
            [2] = 801101142
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1994"
        },
        [80110115] = {
          ContentJP = "まあな、かなり昔の話だが。やべっ、これ話しちまっていいのか？",
          DialogueId = 80110115,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C19BE",
          NextDialogue = 80110116,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19BE"
        },
        [80110116] = {
          ContentJP = "……ま、いいか。昔の身分を隠せなんて決まりは帝国軍にねえし。",
          DialogueId = 80110116,
          GUID = "C88C19E8",
          NextOptions = {
            [1] = 801101161
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C19E8"
        },
        [80110117] = {
          ContentJP = "けっ……どんだけステキなクソ溜めなのか、帝国軍の実態をお前は知らねえのな。",
          DialogueId = 80110117,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C1A12",
          NextDialogue = 80110118,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A12"
        },
        [80110118] = {
          ContentJP = "帝国軍基地を囲う塀の上には火花バチバチなイコル電気柵が張ってあんだ。盗賊やらスパイやらの侵入を防ぎつつ、兵士の脱走も許さねえ。",
          DialogueId = 80110118,
          GUID = "C88C1A3C",
          NextDialogue = 80110119,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A3C"
        },
        [80110119] = {
          ContentJP = "つっても、見てわかる電気柵は避けりゃいいけどよ。やべえのは帝国軍内の見えねえ電気柵だ――うっかり口を滑らせたりトチった行動をしようもんなら、「バチンッ！」感電死さ。",
          DialogueId = 80110119,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1A66",
          NextDialogue = 80110120,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A66"
        },
        [80110120] = {
          ContentJP = "特にアタシの上の長官サマは裏切り者が大嫌いでな。うっかりで内通者認定でも食らったら目も当てらんねえ。",
          DialogueId = 80110120,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C1A90",
          NextOptions = {
            [1] = 801101201,
            [2] = 801101202
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1A90"
        },
        [80110121] = {
          ContentJP = "今さらすぎんだろ。アタシだって好き好んで帝国軍人やってるわけじゃねえよ。",
          DialogueId = 80110121,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1ABA",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1ABA"
        },
        [80110122] = {
          ContentJP = "自分の命を銃口にさらして毎日アブねえ仕事すんなら、お前どう思う？威張れんなら大歓迎ってか？",
          DialogueId = 80110122,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1AE4",
          NextDialogue = 80110123,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1AE4"
        },
        [80110123] = {
          ContentJP = "……月狩り人の頃のほうがマシだったさ。楽じゃなかったけどよ、少なくとも自由だったからな。",
          DialogueId = 80110123,
          GUID = "C88C1B0E",
          NextDialogue = 80110124,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B0E"
        },
        [80110124] = {
          ContentJP = "依頼っつっても毎日が血みどろの命がけじゃねえ。犬の散歩や鹿狩りなんかの楽な仕事だってあったし、デカい仕事を片付けた日にゃあ「アスフォデロス」で1杯ひっかけてさ、体が芯からあったまるときた。",
          DialogueId = 80110124,
          GUID = "C88C1B38",
          NextDialogue = 80110125,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B38"
        },
        [80110125] = {
          ContentJP = "誰とも組まずにひとり気ままにやったっていい。自分の計画を通すために誰かを説得しなくたっていい。任務中に足手まといのケツを拭く必要もねえんだ。",
          DialogueId = 80110125,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1B62",
          NextDialogue = 80110126,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B62"
        },
        [80110126] = {
          ContentJP = "なかでも長官サマに気を遣わないで済むのは最高だな。スズメみてーにピーチクパーチクうるせえのなんので。",
          DialogueId = 80110126,
          GUID = "C88C1B8C",
          NextOptions = {
            [1] = 801101261
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1B8C"
        },
        [80110127] = {
          ContentJP = "長官のことをそんな風に話したら失言じゃない？「感電死」したりしないかな？",
          DialogueId = 80110127,
          GUID = "C88C1BB6",
          NextDialogue = 80110128,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BB6"
        },
        [80110128] = {
          ContentJP = "…………！！",
          DialogueId = 80110128,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1BE0",
          NextDialogue = 80110129,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1BE0"
        },
        [80110129] = {
          ContentJP = "当然アウトだ、やっちまった！アタシは貴族連中と違って、脂肪とぜい肉だけ無駄に分厚いクソデカ<Default note=\"text:エジュウ\">穢獣</>みたいな腹してねえから、「電流」なんざ耐えらんねえぞ！つーか、この話が広まったら「電流」でくたばらなくても、ただじゃ済まねえ……",
          DialogueId = 80110129,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1C0A",
          NextDialogue = 80110130,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C0A"
        },
        [80110130] = {
          ContentJP = "誰かほかのヤツに吹き込んでみろ！1発でお前の頭をブッ飛ばしてやっからな！忘れんなよ！？",
          DialogueId = 80110130,
          GUID = "C88C1C34",
          NextOptions = {
            [1] = 801101301
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C34"
        },
        [80110131] = {
          ContentJP = "でも意外{性别:だな|ね}。実際に話してみるとリーンってイメージと全然違うんだね。",
          DialogueId = 80110131,
          GUID = "C88C1C5E",
          NextDialogue = 80110132,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C5E"
        },
        [80110132] = {
          ContentJP = "ヒュペリアの将校として――「信念」とか？「栄光」やら「忠誠心」やらを持っている人だと思っていたけど……",
          DialogueId = 80110132,
          GUID = "C88C1C88",
          NextDialogue = 80110133,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1C88"
        },
        [80110133] = {
          ContentJP = "ふっ、そりゃ部下の新兵たちをダマくらかすのにゃあ都合のいい言葉だけどよ。アタシ自身は……",
          DialogueId = 80110133,
          GUID = "C88C1CB2",
          NextDialogue = 80110134,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CB2"
        },
        [80110134] = {
          ContentJP = "見えもつかめもしねえもんのために全部を投げ出すヤツは確かにいやがる。でもアタシはそうじゃねえ。月狩り人になったのも、帝国軍に加わったのも、自分が何のために動いてんのかハッキリと言い切れる。",
          DialogueId = 80110134,
          GUID = "C88C1CDC",
          NextDialogue = 80110135,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1CDC"
        },
        [80110135] = {
          ContentJP = "……ま、要するに食うためさ。はなっから何も変わらねえ。帝国軍がアタシの力を求めて、アタシもヤツらにカネを求めた。利害が一致した取引ってだけだ。",
          DialogueId = 80110135,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C1D06",
          NextDialogue = 80110136,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D06"
        },
        [80110136] = {
          ContentJP = "お前の言う栄光や信念なんざ欠片もねえのさ。",
          DialogueId = 80110136,
          GUID = "C88C1D30",
          NextOptions = {
            [1] = 801101361
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D30"
        },
        [80110137] = {
          ContentJP = "…………！！",
          DialogueId = 80110137,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C1D5A",
          NextDialogue = 80110138,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D5A"
        },
        [80110138] = {
          ContentJP = "**！チクショウがやってられっかぁ！これ以上は飲まねえぞぉ！余計な言葉を引っ張りだしやがるクソ酒がぁ！",
          DialogueId = 80110138,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C1D84",
          NextDialogue = 80110139,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1D84"
        },
        [80110139] = {
          ContentJP = "もう行く！もう飲まねえ！いいか！余計なこと言いふらしたら承知しねえからな！",
          DialogueId = 80110139,
          GUID = "C88C1DAE",
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/001/C88C1DAE"
        },
        [80110201] = {
          Camera = "127.060242,12.009277,131.847168,0.0,-0.799959,-137.39563,30.0,150.0,false,Manual,2.8",
          ContentJP = "……もう一杯くれ。",
          DialogueId = 80110201,
          GUID = "C88C27DA",
          LookAt = {
            [1] = "93101:p(18000P3)"
          },
          NextDialogue = 80110202,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C27DA"
        },
        [80110202] = {
          ContentJP = "なあ、お前ってアイスレイク城でどうやって仕事を受けてんだ？やっぱ「アスフォデロス」か？",
          DialogueId = 80110202,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2804",
          NextOptions = {
            [1] = 801102021
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2804"
        },
        [80110203] = {
          ContentJP = "昔からちーっとも変わっちゃねえんだな。まあ「アスフォデロス」だったらワルくねえわ……少なくともカミラなら、殺人とか強盗なんかさせねえから。",
          DialogueId = 80110203,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C282E",
          NextOptions = {
            [1] = 801102031
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C282E"
        },
        [80110204] = {
          ContentJP = "アイスレイクはちんけなとこだが、そっち方面の人材が帝都よりも豊富だ。特に外周区とか保安署すら面倒見たがらねえ場所はな……お前はカミラんとこで働いてっから安心しろ。個人の仕事をむやみに引き受けなきゃ、そういう類の依頼とは無縁だろうさ。",
          DialogueId = 80110204,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2858",
          NextDialogue = 80110205,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2858"
        },
        [80110205] = {
          ContentJP = "そういやカミラはどうしてる？相変わらずおっかねえのか？",
          DialogueId = 80110205,
          GUID = "C88C2882",
          NextOptions = {
            [1] = 801102051,
            [2] = 801102052
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2882"
        },
        [80110206] = {
          ContentJP = "そりゃあいい！あー時が経つって早えもんだな！あのカミラが丸くなったとか想像できねえよ！それに引き換えアタシんとこの長官サマは相変わらず凶暴なままだ……",
          DialogueId = 80110206,
          FacialId = {
            [1] = "93101:Happy01"
          },
          GUID = "C88C28AC",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28AC"
        },
        [80110207] = {
          ContentJP = "そうかい、カミラも変わんねえか……まーアタシの長官サマとおんなじだ。美人なクセして、一日中頭にツノ生やしてやがる。",
          DialogueId = 80110207,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C28D6",
          NextOptions = {
            [1] = 801102071
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C28D6"
        },
        [80110208] = {
          ContentJP = "名前は……いや教えらんねえわ。口が滑ったら最後、例の電気柵にブン投げられて殺されちまう。",
          DialogueId = 80110208,
          GUID = "C88C2900",
          NextDialogue = 80110209,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2900"
        },
        [80110209] = {
          ContentJP = "長官サマは1日中しかめっ面だ。帝国兵士全員から借金を取り立てるみたいな感じに。",
          DialogueId = 80110209,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C292A",
          NextOptions = {
            [1] = 801102091
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C292A"
        },
        [80110210] = {
          ContentJP = "長官は変な癖が盛りだくさんな女なんだぜ？例えば武器とか、まともなヤツなら銃を選ぶだろうに、長官サマときたら電気を帯びたムチを使うんだぜ？銃よりずっと使いやすいんだってよ。",
          DialogueId = 80110210,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2954",
          NextDialogue = 80110211,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2954"
        },
        [80110211] = {
          ContentJP = "（あなたは急に心がずっしりと沈んだ。リーンの説明はある人物を連想させる。あなたが探している人物――シビルを）",
          DialogueId = 80110211,
          GUID = "C88C297E",
          NextDialogue = 80110212,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C297E"
        },
        [80110212] = {
          ContentJP = "考えごとって普通は静かな環境でするもんだよな？でも長官サマはノイズみてえな録音を1日中聞いてんだ。眠気覚まし、疲れて集中力が切れた時に使うとか言ってさ。",
          DialogueId = 80110212,
          GUID = "C88C29A8",
          NextDialogue = 80110213,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29A8"
        },
        [80110213] = {
          ContentJP = "執務室でカラスを何羽も飼ってやがるしよ。そいつのクソが陛――いや、上司への報告書に落ちたらとか、普通は心配すんだろ！",
          DialogueId = 80110213,
          GUID = "C88C29D2",
          NextDialogue = 80110214,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29D2"
        },
        [80110214] = {
          ContentJP = "まだまだあるぜ。気晴らしで川に行くなら風に当たったり、景色を眺めたりするだろ？ところがアタシの長官サマは釣り人が手ぶらで帰るツラを拝むんだとさ。なによりのストレス解消法なんだとか。",
          DialogueId = 80110214,
          GUID = "C88C29FC",
          NextDialogue = 80110215,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C29FC"
        },
        [80110215] = {
          ContentJP = "何をどうこじらせたらそんなヤツになんだよッ！！",
          DialogueId = 80110215,
          GUID = "C88C2A26",
          NextOptions = {
            [1] = 801102151
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A26"
        },
        [80110216] = {
          ContentJP = "ハンパなく変わり者だ。面白いだなんてお前、実際にツラを合わせたら言ってらんねえぞ。しかも長官が社長なら、副社長までいやがんのよこれが。長官よりも頭の中がバグってやがるヤツがよ。",
          DialogueId = 80110216,
          FacialId = {
            [1] = "93101:Sad02"
          },
          GUID = "C88C2A50",
          NextDialogue = 80110217,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A50"
        },
        [80110217] = {
          ContentJP = "気取った言い回しの口八丁なヤツでさ。あいつは優雅に話してるつもりだろうが、アタシからすりゃあガチョウの鳴き声にしか聞こえねえ。首を揺らしながらガーガーとわめき散らしやがって。",
          DialogueId = 80110217,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2A7A",
          NextDialogue = 80110218,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2A7A"
        },
        [80110218] = {
          ContentJP = "日がな一日「高効率省エネなんやら」だとか口にしちゃあいるが……ハンッ！実際はサボる口実さ。あのヤロウの考えなんざ誰だってお見通しだっつの。",
          DialogueId = 80110218,
          GUID = "C88C2AA4",
          NextDialogue = 80110219,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AA4"
        },
        [80110219] = {
          ContentJP = "それでいておつむはやたらと出来がいいのが厄介だ。ずっとサボってるクセして仕事は漏らさねえから、誰も文句は言えねえ。",
          DialogueId = 80110219,
          GUID = "C88C2ACE",
          NextDialogue = 80110220,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2ACE"
        },
        [80110220] = {
          ContentJP = "このあいだも長官サマが何年もかけてずっと探してたお宝の隠し場所を、わずかな手がかりだけで見抜きやがった。まあ途中で……ちょいとトラブルもあったらしいが……",
          DialogueId = 80110220,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C2AF8",
          NextDialogue = 80110221,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2AF8"
        },
        [80110221] = {
          ContentJP = "（「お宝」……推測が間違っていなければ、ベレニカのことだろう）",
          DialogueId = 80110221,
          GUID = "C88C2B22",
          NextOptions = {
            [1] = 801102211
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B22"
        },
        [80110222] = {
          ContentJP = "アタシに聞くなって……あれは機密事項だからあの二人が直々に捜索に行ったんだ。アタシが知るわけないだろ。",
          DialogueId = 80110222,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2B4C",
          NextDialogue = 80110223,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B4C"
        },
        [80110223] = {
          ContentJP = "…………",
          DialogueId = 80110223,
          GUID = "C88C2B76",
          NextDialogue = 80110224,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2B76"
        },
        [80110224] = {
          ContentJP = "マズった、今日はマジで言うべきじゃねえ話を次々と……ああ、ぜってえこの酒のせいだ！お前もしかして酒に自白剤でも入れたんじゃねえのか！？",
          DialogueId = 80110224,
          FacialId = {
            [1] = "93101:Shock01"
          },
          GUID = "C88C2BA0",
          NextDialogue = 80110225,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BA0"
        },
        [80110225] = {
          ContentJP = "ああもう、ヤメだヤメ、ったく――ディズマニアで酒を飲まなくてよかったぜ。さもなきゃ長官にムチで打たれて電撃を……いや、この話はもうやめておこう……",
          DialogueId = 80110225,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C2BCA",
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/002/C88C2BCA"
        },
        [80110226] = {
          Camera = "164.130432,-127.039795,145.762421,0.000003,0.8,176.399841,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "誰にも言わねえって信じてるからな。",
          DialogueId = 80110226,
          FinalCamera = "164.130432,-118.0,145.762421,0.000003,0.8,176.399841,35.0,100000.0,false,DoNotOverride,2.8",
