  {
    MinKey = 80110304,
    MaxKey = 80120439,
    Loader = function()
      return {
        [80110304] = {
          ContentJP = "まあ、筋は通っちゃいるし、開けてもいいが……中に入ってんのは銃とお面だ。",
          DialogueId = 80110304,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C38C0",
          NextDialogue = 80110305,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38C0"
        },
        [80110305] = {
          ContentJP = "そうピリつくなよ玩具の銃だ。心配だっつーんならアタシに向けて撃ってみてもいいぜ。",
          DialogueId = 80110305,
          FacialId = {
            [1] = "93101:Iyada01"
