          NextOptions = {
            [1] = 801103051
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C38EA"
        },
        [80110306] = {
          ContentJP = "（バンッ――）",
          DialogueId = 80110306,
          GUID = "C88C3914",
          NextDialogue = 80110307,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3914"
        },
        [80110307] = {
          ContentJP = "のおおぉ痛ったぁコラおい！玩具の弾丸つっても普通に痛てえから額に向かって撃つんじゃねえドアホ！ちょっとこっち来い。仕返しにデコピンさせろ。**ッタレ遠慮なくヤりすぎだ！",
          DialogueId = 80110307,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C393E",
          NextDialogue = 80110308,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_toysshot\"},PlayAs2D{true}}",
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C393E"
        },
        [80110308] = {
          ContentJP = "たっく、お前のお陰で思い出しちまったぜ。子供の頃にリオラとケンカした時は、お互いにパチンコで頭を狙ったな。いま思うとよく死なずに済んだぜ………まあこの銃も……あいつに渡すモノなんだが。",
          DialogueId = 80110308,
          GUID = "C88C3968",
          NextOptions = {
            [1] = 801103081
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3968"
        },
        [80110309] = {
          ContentJP = "ああ、そうなるな……今回の任務でアイスレイク城に戻ることになったから、なんか手土産でもって。",
          DialogueId = 80110309,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3992",
          NextDialogue = 80110310,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3992"
        },
        [80110310] = {
          ContentJP = "つーかさっきからクドクドと質問ばっかじゃねえかよ。やんのかやんねえのかどっちだ？やんねえならほかの月狩り人に頼むぞ。",
          DialogueId = 80110310,
          GUID = "C88C39BC",
          NextOptions = {
            [1] = 801103101
          },
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39BC"
        },
        [80110311] = {
          ContentJP = "自分でだと？チッ、よけいなお世話だよ。そもそも長官の命令がなけりゃあな、こんなクソみてえな街に戻ってくるわけねえだろうが。",
          DialogueId = 80110311,
          FacialId = {
            [1] = "93101:Sad01"
          },
          GUID = "C88C39E6",
          NextOptions = {
            [1] = 801103111,
            [2] = 801103112
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C39E6"
        },
        [80110312] = {
          ContentJP = "皮肉はもうたくさんだ。",
          DialogueId = 80110312,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3A10",
          NextDialogue = 80110313,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A10"
        },
        [80110313] = {
          ContentJP = "街に戻ってきたことは何度かあんだよ。そんでガキの頃のダチと飲もうとか考えた。一緒に鳥の巣を探したりジャガイモを盗んだりした昔のバカ話でもしながら、一時でも帝国軍のことなんざ忘れようってな。",
          DialogueId = 80110313,
          GUID = "C88C3A3A",
          NextDialogue = 80110314,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A3A"
        },
        [80110314] = {
          ContentJP = "ところがなんだ？どっからアタシが帰ってくるって聞いたのか、あいつらきちんと整列して、アタシを見つけるなり遠くから「リーン長官殿！」って敬礼しやがった。屋根に止まってた鳥までビビって飛んでったんだぜ？",
          DialogueId = 80110314,
          GUID = "C88C3A64",
          NextDialogue = 80110315,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A64"
        },
        [80110315] = {
          ContentJP = "少し疎遠になっちまったが、街で一緒にたむろしてた昔話でもすりゃあ距離もすぐに縮まるだろうって、最初は気楽に考えたさ。",
          DialogueId = 80110315,
          GUID = "C88C3A8E",
          NextDialogue = 80110316,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3A8E"
        },
        [80110316] = {
          ContentJP = "でも結局、そんな話をする空気じゃなかった。どいつもこいつもへーこらペコペコしやがって、アタシと目を合わせようとすらしねえ。",
          DialogueId = 80110316,
          GUID = "C88C3AB8",
          NextOptions = {
            [1] = 801103161
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AB8"
        },
        [80110317] = {
          ContentJP = "ああ、そういうもんさ。アイツらの立場からすりゃ兵士を見てビビんのが普通なんだよ。だからアタシのことを恐れんのは仕方ねえ。ガキの頃からそう言う感じだったし、アタシだってこの仕事をやってなけりゃ同じようにブルっちまってるだろうさ。",
          DialogueId = 80110317,
          FacialId = {
