          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3AE2"
        },
        [80110318] = {
          ContentJP = "アイスレイク……いや、ヒュペリアはずっとそうだ。腕っぷしの強いヤツが弱いヤツを痛めつけて、金持ちが貧乏人を踏みにじる……ガキの頃からずっとそう、今でも何も変わっちゃねえ。",
          DialogueId = 80110318,
          GUID = "C88C3B0C",
          NextDialogue = 80110319,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B0C"
        },
        [80110319] = {
          ContentJP = "なあ、この銃と仮面、なんなのか知ってるか？",
          DialogueId = 80110319,
          GUID = "C88C3B36",
          NextDialogue = 80110320,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B36"
        },
        [80110320] = {
          ContentJP = "ガキの頃にリオラと一緒に絵本を読んだんだ。「ルブラン」って名の義賊の物語だ。ルブランは意地悪な金持ちの家から財宝を盗んでは貧しい連中に分けてまわって、「仮面の英雄」って呼ばれてる。",
          DialogueId = 80110320,
          GUID = "C88C3B60",
          NextDialogue = 80110321,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B60"
        },
        [80110321] = {
          ContentJP = "アタシとリオラは段ボールで仮面を作ってさ、パチンコを銃代わりに、アイスレイクの城壁を駆けあがって絵本のルブランの台詞を大声で叫んだもんだ。恥ずかしいだなんてちっとも思っちゃなかった。",
          DialogueId = 80110321,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3B8A",
          NextDialogue = 80110322,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3B8A"
        },
        [80110322] = {
          ContentJP = "あの時のアタシたちふたりは……いつか……「英雄」になれんだって信じてたからさ。",
          DialogueId = 80110322,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3BB4",
          NextDialogue = 80110323,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BB4"
        },
        [80110323] = {
          ContentJP = "ディズマニアの店で本物と瓜ふたつな、アタシらが使ってたもんとは比べ物になんねえくらいきれいなルブランの仮面と玩具の銃を見つけた。んでカネを出して買った。",
          DialogueId = 80110323,
          GUID = "C88C3BDE",
          NextDialogue = 80110324,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3BDE"
        },
        [80110324] = {
          ContentJP = "「アタシはカロンを撃つしか能がねえ悪人に成り下がっちまったが、リオラには『英雄』になれるチャンスがまだある」……その時のアタシはそう思ってたよ。",
          DialogueId = 80110324,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3C08",
          NextDialogue = 80110325,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C08"
        },
        [80110325] = {
          ContentJP = "……アイスレイクでアタシを見たアイツはガチョウみてえにビクビク震えてさ。ほかのダチと同じで「リーン」から「リーン長官殿」に呼び方も変わっちまって。嫌でもわかったさ……あいつもアタシも、あの頃には戻れねえんだ。",
          DialogueId = 80110325,
          GUID = "C88C3C32",
          NextDialogue = 80110326,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C32"
        },
        [80110326] = {
          ContentJP = "……はぁ、頭がイッテェ……頼む、もう一杯くれ！",
          DialogueId = 80110326,
          FacialId = {
            [1] = "93101:Syouganai01"
          },
          GUID = "C88C3C5C",
          NextDialogue = 80110327,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C5C"
        },
        [80110327] = {
          ContentJP = "そんなくだんねえ理由でアタシはもうこれっぽっちもアイスレイク城に帰りたかねえってことさ。弟や妹にさえ会いたかねえ。遠くからひと目見てまだ生きてんのか、成長してんのか、いい感じに生活できてんのかだけ知れりゃあ腹いっぱいだ。",
          DialogueId = 80110327,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3C86",
          NextOptions = {
            [1] = 801103271
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3C86"
        },
        [80110328] = {
          ContentJP = "んや逆だな。手紙にいつもアタシのことが恋しいだの、もっと会いに来て欲しいだのって書いてあるし。",
          DialogueId = 80110328,
          FacialId = {
            [1] = "93101:Iyada01"
          },
          GUID = "C88C3CB0",
          NextDialogue = 80110329,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CB0"
        },
        [80110329] = {
          ContentJP = "でもアイツらに会っても何を話しゃいい？錬金院の実験を見たとかか？また<Default note=\"text:ソラ\">ヒト族</>を何人か捕まえたとかか？",
          DialogueId = 80110329,
          GUID = "C88C3CDA",
          NextDialogue = 80110330,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3CDA"
        },
        [80110330] = {
          ContentJP = "……まあ誰だって悩みのひとつやふたつ抱えてんのが普通さ。こんなもん、よくあるありきたりな話だよ。",
          DialogueId = 80110330,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3D04",
          NextOptions = {
            [1] = 801103301
          },
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D04"
        },
        [80110331] = {
          ContentJP = "家に帰りたいと思ったら帰っていいのが普通で……というか、それが常識だって世界に、{性别:僕|私}たちで変えていかなきゃダメだと思う。",
          DialogueId = 80110331,
          GUID = "C88C3D2E",
          NextDialogue = 80110332,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D2E"
        },
        [80110332] = {
          ContentJP = "これが普通じゃないって思えんのはお前がよそ者だからだ。常識を変えるとか言ってのけられんのが特にな。",
          DialogueId = 80110332,
          GUID = "C88C3D58",
          NextDialogue = 80110333,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D58"
        },
        [80110333] = {
          ContentJP = "いつかカロン族と<Default note=\"text:ソラ\">ヒト族</>で仲良しゴッコが叶うとか夢見てんじゃねえだろうな？カロン族は変な角と脊椎を持ってて、魔法が使えるってだけで、ヒト族と同じだって思ってもらえるとかさ。",
          DialogueId = 80110333,
          GUID = "C88C3D82",
          NextDialogue = 80110334,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3D82"
        },
        [80110334] = {
          ContentJP = "いつかそうなるかも。",
          DialogueId = 80110334,
          GUID = "C88C3DAC",
          NextDialogue = 80110335,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DAC"
        },
        [80110335] = {
          ContentJP = "アイスレイク城に雪が降らないようにするのは無理かもだけど、雪をかき集めて雪だるまを作るくらいなら、{性别:僕|私}たちだってできるはず。",
          DialogueId = 80110335,
          GUID = "C88C3DD6",
          NextDialogue = 80110336,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3DD6"
        },
        [80110336] = {
          ContentJP = "夢は砕けてしまったかもしれないけど、友達を訪ねて、あの頃の夢をまだ覚えているって伝えることはできるよ。実家のドアをノックして、「どんな立場になってもみんなことをずっと想っている」って言えるはず。気持ちはずっと変わらないって。",
          DialogueId = 80110336,
          GUID = "C88C3E00",
          NextDialogue = 80110337,
          SpeakNpcName = "UI_Npc_Name_Nvzhu",
          TalkActionId = {
            [1] = "93101:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E00"
        },
        [80110337] = {
          ContentJP = "……ハハ、マジでお前さ、ふざけんじゃねえって言いてえけどよ……正直好きだぜ、お前の考え方はよ。花畑な話だとしても「世界はこんなもんで誰にも変えられない」みてえなゴミカスな嘆きよりはずっといい。",
          DialogueId = 80110337,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E2A",
          NextDialogue = 80110338,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E2A"
        },
        [80110338] = {
          ContentJP = "お前と話しているとアイスレイク城の風の冷たさが、ちょいとマシになったような気がすんな……ああ、もう一杯くれよ。",
          DialogueId = 80110338,
          FacialId = {
            [1] = "93101:Happy02"
          },
          GUID = "C88C3E54",
          NextDialogue = 80110339,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E54"
        },
        [80110339] = {
          ContentJP = "お前がどこまでやれんのかを見たくなっちまった。世界を変えたいなんざ白昼夢を口に出すってんならアタシに見せてみな。純情な世間知らずが世界を少しでも変えられるかどうかをさ。",
          DialogueId = 80110339,
          FacialId = {
            [1] = "93101:Smile01"
          },
          GUID = "C88C3E7E",
          NextDialogue = 80110340,
          SpeakNpcId = 93101,
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3E7E"
        },
        [80110340] = {
          ContentJP = "手伝いが必要になったら呼べ。アタシが忙しい時と――もちろん帝国軍に逆らうようなことはダメだが。それと今日は店じまい、たったいま、予定ができちまった。",
          DialogueId = 80110340,
          GUID = "C88C3EA8",
          NextDialogue = 80110341,
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3EA8"
        },
        [80110341] = {
          ContentJP = "仮面と銃を返してくれ。お前への依頼はキャンセルする。",
          DialogueId = 80110341,
          FacialId = {
            [1] = "93101:None"
          },
          GUID = "C88C3ED2",
          SpeakNpcId = 93101,
          TalkActionId = {
            [1] = "93101:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Linen/003/C88C3ED2"
        },
        [80120000] = {
          ContentJP = "ふぁあ、完璧――椅子に飲み物にお菓子に暖炉、君もすっかりくつろいでる……",
          DialogueId = 80120000,
          GUID = "C8926F80"
        },
        [80120100] = {
          Camera = "254.617188,-63.0,110.607666,0.0,0.0,155.600769,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "部屋の家具は30年前に帝都ディズマニアから運んできた代物だ。その素材の希少さ、技術の耽美さは、君たちには到底理解できまい。",
          DialogueId = 80120100,
          FinalCamera = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C8927FE8",
          NextDialogue = 80120101,
          SpeakNpcId = 790018,
          TalkActionId = {
            [1] = "790018:Explain01_Start"
          },
          ToFinalCameraBlendTime = 7,
          VoiceName = "voice/$Locale$/inv/Maer/001/C8927FE8"
        },
        [80120101] = {
          Camera = "-270.549316,-21.425171,153.719727,0.000001,-9.200162,19.797686,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "そんな貴重なもの、くれちゃっていいんですか？言っときますけど、後になって返金とかできませんからね……",
          DialogueId = 80120101,
          FacialId = {
            [1] = "790019:Iyada01"
          },
          GUID = "C8928012",
          NextDialogue = 80120102,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Explain02_Start",
            [2] = "790018:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928012"
        },
        [80120102] = {
          Camera = "254.617188,-54.528625,110.607666,0.0,0.0,155.600739,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "何度も言ったが、好きにしろ。私にとって唯一価値のある宝は、数十年かけて仕上げてきた楽譜だけだ。それらは既に然るべき場所に保管しておる。",
          DialogueId = 80120102,
          GUID = "C892803C",
          NextDialogue = 80120103,
          SpeakNpcId = 790018,
          TalkActionId = {
            [1] = "790019:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C892803C"
        },
        [80120103] = {
          Camera = "-91.792969,-17.010254,119.101807,0.000001,-2.600096,26.798737,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ではでは～～……念のために確認してくださいな。書斎に散らばってた紙を整理したら、こんな分厚い束になっちゃいましたよ！これらも楽譜では……",
          DialogueId = 80120103,
          GUID = "C8928066",
          NextDialogue = 80120104,
          SpeakNpcId = 790019,
          TalkActionId = {
            [1] = "790019:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928066"
        },
        [80120104] = {
          Camera = "188.380859,5.304199,118.568604,0.000005,0.0,165.387512,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "燃やしてくれ。",
          DialogueId = 80120104,
          GUID = "C8928090",
          NextDialogue = 80120105,
          SpeakNpcId = 790018,
          TalkActionId = {
            [1] = "790019:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C8928090"
        },
        [80120105] = {
          Camera = "-194.875488,-9.761597,155.702393,0.000033,-32.798512,130.396423,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "それらはボツになったゴミだ。貧家に薪代わりにくれてやれ。",
          DialogueId = 80120105,
          FinalCamera = "-183.950195,-22.665466,181.275146,0.000027,-35.598583,129.996002,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89280BA",
          NextDialogue = 80120106,
          SpeakNpcId = 790018,
          ToFinalCameraBlendTime = 9,
          VoiceName = "voice/$Locale$/inv/Maer/001/C89280BA"
        },
        [80120106] = {
          Camera = "7.850098,-71.797974,9.991455,0.000032,31.599302,132.795364,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "それに、大切な物を地面にばら撒くわけなかろう？バカか君は？",
          DialogueId = 80120106,
          GUID = "C89280E4",
          NextDialogue = 80120107,
          SpeakNpcId = 790018,
          TalkActionId = {
            [1] = "790018:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Maer/001/C89280E4"
        },
        [80120107] = {
          Camera = "-65.708008,-20.782593,149.700928,0.000017,-11.799984,31.404984,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "…………",
          DialogueId = 80120107,
          FacialId = {
            [1] = "790019:Sad01"
          },
