        },
        [80120301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "おお……",
          DialogueId = 80120301,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A0E2",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120302,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A0E2"
        },
        [80120302] = {
          ContentJP = "スウィートだけどビターな……なんーとまぁ、うちのバカオヤジが好きそうな味！私がこの味を理解するには、あと10年、いや20年はかかるかも。",
          DialogueId = 80120302,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A10C",
          NextOptions = {
            [1] = 801203021,
            [2] = 801203031
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A10C"
        },
        [80120303] = {
          ContentJP = "そもそも、なぜ自ら苦しい思いをするんだね！？",
          DialogueId = 80120303,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A136",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A136"
        },
        [80120304] = {
          ContentJP = "ザッツライッ！仕事終わりに飲めば、頭のてっぺんからつま先までスッキリ爽快になるんだぁ！",
          DialogueId = 80120304,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A160",
          NextOptions = {
            [1] = 801203041
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A160"
        },
        [80120305] = {
          ContentJP = "ああ、私の父親だよ！みんなからはオールドマーティンって呼ばれてる。私が一人前になるまで、アイスレイク城のゴミ箱は全部親父が管理してたんだ。",
          DialogueId = 80120305,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A18A",
          NextDialogue = 80120306,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A18A"
        },
        [80120306] = {
          ContentJP = "「ゴミ拾いの王様」なんてあだ名を付けられてね。おかげで私は「ゴミ拾いの姫様」になったってわけ。こんなダサい名前……ムキ―！あのバカ親父いいぃぃぃ！あやつのせいで私はこんな辱めをおぉぉ！",
          DialogueId = 80120306,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A1B4",
          NextDialogue = 80120307,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1B4"
        },
        [80120307] = {
          ContentJP = "本当はクールで、インテリジェンスなレディを目指してたのに……",
          DialogueId = 80120307,
          FacialId = {
            [1] = "93301:Iyada01"
          },
          GUID = "C892A1DE",
          NextOptions = {
            [1] = 801203071,
            [2] = 801203081
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A1DE"
        },
        [80120308] = {
          ContentJP = "ウハハハ！分かってるじゃないか！",
          DialogueId = 80120308,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A208",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A208"
        },
        [80120309] = {
          ContentJP = "こらぁぁ！？――シャラァーップ！お口チャーック！これ以上はシャベルでお仕置きするよ！！",
          DialogueId = 80120309,
          FacialId = {
            [1] = "93301:Disappoint01"
          },
          GUID = "C892A232",
          NextDialogue = 80120310,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A232"
        },
        [80120310] = {
          ContentJP = "はぁ……うちのバカ親父、仕事を私に丸投げして、どこをほっつき歩いているんだか。私とカミラお姉様に迷惑かけないで欲しいんだけど！？",
          DialogueId = 80120310,
          FacialId = {
            [1] = "93301:Unhappy01"
          },
          GUID = "C892A25C",
          NextOptions = {
            [1] = 801203101
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A25C"
        },
        [80120311] = {
          ContentJP = "えーあー確かに。コーヒー効果かな……私ってば……正直言うと、父親のこと忘れてたんだよね……",
          DialogueId = 80120311,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892A286",
          NextOptions = {
            [1] = 801203111,
            [2] = 801203121
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A286"
        },
        [80120312] = {
          ContentJP = "私はお仕事で忙しいんだからショウガナイの！そもそも押し付けたの親父だし！私は無罪！",
          DialogueId = 80120312,
          FacialId = {
            [1] = "93301:Shock02"
          },
          GUID = "C892A2B0",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2B0"
        },
        [80120313] = {
          ContentJP = "ごっほん……可愛い子猫ちゃんもいずれは成長するもの。私のは巣立ちだよ。",
          DialogueId = 80120313,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A2DA",
          NextDialogue = 80120314,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A2DA"
        },
        [80120314] = {
          ContentJP = "生まれてから10年ぐらいはバカ親父に振り回されっぱなしだった。特に故郷からアイスレイク城までの旅路――1年まるまる雪野原の中を歩いたし、親父以外には誰ひとり会わなかったよ。",
          DialogueId = 80120314,
          GUID = "C892A304",
          NextDialogue = 80120315,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A304"
        },
        [80120315] = {
          ContentJP = "そんなこんなで、あの人のスベリジョークやら、ふざけた歌やイタズラにはうんざりしちゃってまして。だから、あんまりあの人のこと考えないようにしてたのかも……",
          DialogueId = 80120315,
          GUID = "C892A32E",
          NextDialogue = 80120316,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A32E"
        },
        [80120316] = {
          ContentJP = "なのに、バカ親父の方はアイスレイク城に着くなり「テリトリーゲットだぜ！」だの、「現地の有力者を取り込んだぜ！」だの、「ショバ代を取るぞ！」だの、「既存勢力と手を組む！」だの、「俺がボスだ」だの……楽しそうにしてたなーあの人。",
          DialogueId = 80120316,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A358",
          NextOptions = {
            [1] = 801203161
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A358"
        },
        [80120317] = {
          ContentJP = "ああ、つまり、ゴミ箱の場所を把握して、元清掃員と手を組んで、ゴミ箱の「仕入れルール」を決めつつ、カミラお姉様を通して回収先を探して、「ゴミ拾いの王様」になったってこと。",
          DialogueId = 80120317,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A382",
          NextDialogue = 80120318,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A382"
        },
        [80120318] = {
          ContentJP = "それに、バカ親父は小難しくてキザなセリフばっかり言いたがるんだよー！まるで、劇の台本を読んでるみたいな感じでさ。たぶん、故郷のあの喧嘩っ早いボロ街で染みついた悪い癖が抜けないんだろうね。うへぇ――",
          DialogueId = 80120318,
          GUID = "C892A3AC",
          NextOptions = {
            [1] = 801203181
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3AC"
        },
        [80120319] = {
          ContentJP = "どうだか！自分の昔話を「武勇伝」みたく自慢気に話してたし！例えば……",
          DialogueId = 80120319,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A3D6",
          NextDialogue = 80120320,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A3D6"
        },
        [80120320] = {
          ContentJP = "「清掃員」に与えられたミッションはすべて、個人の名誉と家族の利益に関わる。計画の立案から当日の身なりまで、すべて完璧に準備しなければならない！そして、お前の父親は史上最高の「清掃員」なのだぁぁ！！",
          DialogueId = 80120320,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A400",
          NextDialogue = 80120321,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A400"
        },
        [80120321] = {
          ContentJP = "アイスレイク城に着いたばっかの頃、私もあやつの悪っちい部分が影響して話し方が似ちゃったんだ。結局、カミラ姉さんがその口調を嫌って、正してくれたんだけどね……まともになるまで結構な時間がかかったっけ……",
          DialogueId = 80120321,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892A42A",
          NextOptions = {
            [1] = 801203211
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A42A"
        },
        [80120322] = {
          ContentJP = "教えるわけないじゃん！恥ずかしい！",
          DialogueId = 80120322,
          FacialId = {
            [1] = "93301:Unacceptable01"
          },
          GUID = "C892A454",
          NextOptions = {
            [1] = 801203221,
            [2] = 801203231
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A454"
        },
        [80120323] = {
          ContentJP = "もう……今回だけだよ！",
          DialogueId = 80120323,
          FacialId = {
            [1] = "93301:Smile02"
          },
          GUID = "C892A47E",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A47E"
        },
        [80120324] = {
          ContentJP = "ぎゃああああ！！！！分かったよぉー！分かったからやめてぇ――",
          DialogueId = 80120324,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A4A8",
          NextDialogue = 80120325,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4A8"
        },
        [80120325] = {
          ContentJP = "ええと……親父が私をカミラお姉様の店に預けたことがあって……あの人の去り際に、私は……",
          DialogueId = 80120325,
          FacialId = {
            [1] = "93301:Think01"
          },
          GUID = "C892A4D2",
          NextDialogue = 80120326,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4D2"
        },
        [80120326] = {
          ContentJP = "「自らのミッションをハートに刻み込むのよダディ！ダディと私のニューライフがかかってるんだから！忘れないで！お顔のチェックはしたの？歯のブラッシングは？パーフェクトな計画は？全て抜かりないって、この姫様に誓いなさい！」",
          DialogueId = 80120326,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A4FC",
          NextOptions = {
            [1] = 801203261
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A4FC"
        },
        [80120327] = {
          ContentJP = "それで、親父は帽子を取ってこう言ったの。「もちろんだ、マイリトルプリンス！もし私とあなたのどちらかがミッションに失敗した場合は、この名に『バカ』を加えて、アスフォデロスのゲートに貼りつけましょう！」",
          DialogueId = 80120327,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A526",
          NextOptions = {
            [1] = 801203271
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A526"
        },
        [80120328] = {
          ContentJP = "だから私も、「同じラストネームの者同士、お鍋の底に刻むのがベストだわ！私のナイトに恥をかかせずに済むし、恥を炎で焼き消すことができるしね！」と言ったね。",
          DialogueId = 80120328,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A550",
          NextOptions = {
            [1] = 801203281
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A550"
        },
        [80120329] = {
          ContentJP = "アハハハハハハハハハ！",
          DialogueId = 80120329,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A57A",
          NextDialogue = 80120330,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A57A"
        },
        [80120330] = {
          ContentJP = "「ゴミ拾いの姫様」ってあだ名、オールドマーティンだけが原因じゃないと思うよ！",
          DialogueId = 80120330,
          GUID = "C892A5A4",
          NextDialogue = 80120331,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5A4"
        },
        [80120331] = {
          ContentJP = "知るかーい！！全部あの人のせいだもん！！危うくあんな気取ったヤツになりかけたかと思うと、全身ゾワッとするよ！",
          DialogueId = 80120331,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892A5CE",
          NextDialogue = 80120332,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5CE"
        },
        [80120332] = {
          ContentJP = "それにさ、気づいた？あのバカ親父、自分の過去をやたら懐かしんで得意げに話すんだよ。どうも、故郷のゴタゴタが嫌で出てきたってだけじゃなさそうなんだよね。",
          DialogueId = 80120332,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A5F8",
          NextDialogue = 80120333,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A5F8"
        },
        [80120333] = {
          ContentJP = "いったい何が理由なんだろう？私を連れて、雪野原を越えてまで故郷を離れた理由……",
          DialogueId = 80120333,
          FacialId = {
            [1] = "93301:Unhappy02"
          },
          GUID = "C892A622",
          NextDialogue = 80120334,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A622"
        },
        [80120334] = {
          ContentJP = "絶対にデカい秘密を隠してるに違いない！でも、聞くたびに「教えないぞ。知りたきゃ、自分の頭で考えろ」なんて言うんだよ！",
          DialogueId = 80120334,
          FacialId = {
            [1] = "93301:Doubt01"
          },
          GUID = "C892A64C",
          NextDialogue = 80120335,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A64C"
        },
        [80120335] = {
          ContentJP = "だから去年、こっそり長いこと調べてみたんだけど、あのバカ親父は神出鬼没だし、故郷から持ってきた荷物もどこに隠したのかさっぱり分からなかったんだよ。",
          DialogueId = 80120335,
          GUID = "C892A676",
          NextDialogue = 80120336,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A676"
        },
        [80120336] = {
          ContentJP = "何ヶ月も調べまくったのに、結局なんの収穫もなし。あの人に思いっきりバカにされたってオチさ――",
          DialogueId = 80120336,
          FacialId = {
            [1] = "93301:Syouganai01"
          },
          GUID = "C892A6A0",
          NextOptions = {
            [1] = 801203361
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6A0"
        },
        [80120337] = {
          ContentJP = "そう、思いっきりね！でもその後、ある日突然、あの神出鬼没の親父が珍しく帰ってきたんだ。それも、まる一日遊んでくれてさ。挙げ句の果てに、なんと――故郷から持ってきたあのスーツケースを置き忘れていったんだよ！",
          DialogueId = 80120337,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A6CA",
          NextDialogue = 80120338,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6CA"
        },
        [80120338] = {
          ContentJP = "それを見て、「やった！あのバカ親の尻尾を掴んだぞ！」って思った。それで、意気揚々とスーツケースを開けたら――お鍋が一つポツンと置かれてるだけだった……",
          DialogueId = 80120338,
          GUID = "C892A6F4",
          NextDialogue = 80120339,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A6F4"
        },
        [80120339] = {
          ContentJP = "マギーは怒って頭に被った物を力いっぱい叩いた。",
          DialogueId = 80120339,
          GUID = "C892A71E",
          NextDialogue = 80120340,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A71E"
        },
        [80120340] = {
          ContentJP = "コレだよコレ！コレと一緒に、メモが一枚入ってた……",
          DialogueId = 80120340,
          GUID = "C892A748",
          NextDialogue = 80120341,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A748"
        },
        [80120341] = {
          ContentJP = "「マイリトルプリンス、君は必ずこのスーツケースを開けて、俺の秘密を探るだろうと予測していたよ。そこで、俺は秘密をプリンセスには想像もつかない場所に移動させた」",
          DialogueId = 80120341,
          FacialId = {
            [1] = "93301:Confident01"
          },
          GUID = "C892A772",
          NextDialogue = 80120342,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A772"
        },
        [80120342] = {
          ContentJP = "「さぞかしご不満だろうと思い、これを残した――この多機能ヘルメットは、正しく使えば頭部をしっかり守り、逆さにすれば火を起こして料理も可能、前面のランプは照明として使える。まさに家でも出先でも使える逸品でありましょう」",
          DialogueId = 80120342,
          GUID = "C892A79C",
          NextDialogue = 80120343,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A79C"
        },
        [80120343] = {
          ContentJP = "「最後に一言……マギー、ハッピーバースデー――マーティンより」",
          DialogueId = 80120343,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A7C6",
          NextOptions = {
            [1] = 801203431,
            [2] = 801203432
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7C6"
        },
        [80120344] = {
          ContentJP = "……いいや！どうせ揶揄ってるだけだよ！",
          DialogueId = 80120344,
          GUID = "C892A7F0",
          NextDialogue = 80120345,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A7F0"
        },
        [80120345] = {
          ContentJP = "とにかく、それ以来、あの人の秘密なんてどうでもよくなったよ。",
          DialogueId = 80120345,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892A81A",
          NextDialogue = 80120346,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A81A"
        },
        [80120346] = {
          ContentJP = "急に思ったんだけど……",
          DialogueId = 80120346,
          GUID = "C892A844",
          NextDialogue = 80120347,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "93301:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A844"
        },
        [80120347] = {
          ContentJP = "何を？",
          DialogueId = 80120347,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892A86E",
          NextDialogue = 80120348,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A86E"
        },
        [80120348] = {
          ContentJP = "オールドマーティンの秘密って……もしかしたら、この「多機能ヘルメット」に隠されているんじゃないかな？",
          DialogueId = 80120348,
          GUID = "C892A898",
          NextDialogue = 80120349,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A898"
        },
        [80120349] = {
          ContentJP = "「想像もつかない場所に移動させた」ってことは……灯台下暗しって可能性もあるよね？",
          DialogueId = 80120349,
          GUID = "C892A8C2",
          NextDialogue = 80120350,
          SpeakNpcId = 100001,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8C2"
        },
        [80120350] = {
          ContentJP = "あっ……！！そういえば、あの時はもうガッカリしすぎて、このヘルメットをちゃんと調べもしなかった！でも今考えたら、これって改造されてるんだし、中に何か仕込まれてるかも！？よし、今すぐ分解してみる！",
          DialogueId = 80120350,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892A8EC",
          NextDialogue = 80120351,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A8EC"
        },
        [80120351] = {
          ContentJP = "本当だ！衝撃吸収ライナーの下に隠しスペースがある！私の見る目は曇っちゃいなかった！あなたってやっぱり探偵の才能あるんじゃない！？",
          DialogueId = 80120351,
          GUID = "C892A916",
          IsBlack = 1,
          NextDialogue = 80120352,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A916"
        },
        [80120352] = {
          ContentJP = "バカ親父め！あんたの秘密、やっと掴んだぞ～～！",
          DialogueId = 80120352,
          GUID = "C892A940",
          IsBlack = 1,
          NextDialogue = 80120353,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A940"
        },
        [80120353] = {
          ContentJP = "マギーは鍋で作られたヘルメットを器用に扱いながら、何度も改造されたであろう廃品を素早く分解していった。指先が滑らかに動き、すぐに解体を終えた。",
          DialogueId = 80120353,
          GUID = "C892A96A",
          IsBlack = 1,
          NextDialogue = 80120354,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A96A"
        },
        [80120354] = {
          ContentJP = "こ、これは……",
          DialogueId = 80120354,
          GUID = "C892A994",
          IsBlack = 1,
          NextDialogue = 80120355,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A994"
        },
        [80120355] = {
          ContentJP = "マギーは目を見開き、言葉を失いながら鍋を見つめた。彼女の手から鍋を受け取ると、底の部分に小さな文字が刻まれていた――",
          DialogueId = 80120355,
          GUID = "C892A9BE",
          IsBlack = 1,
          NextDialogue = 80120356,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9BE"
        },
        [80120356] = {
          ContentJP = "「マイリトルプリンセス、おバカなマギーへ」",
          DialogueId = 80120356,
          GUID = "C892A9E8",
          IsBlack = 1,
          NextDialogue = 80120357,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892A9E8"
        },
        [80120357] = {
          ContentJP = "「おめでとう。君はまたも『オールドマーティンの秘密探し』に失敗した。よって、君の名前に『バカ』を付け加えることにしよう」",
          DialogueId = 80120357,
          GUID = "C892AA12",
          IsBlack = 1,
          NextDialogue = 80120358,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA12"
        },
        [80120358] = {
          ContentJP = "「同じラストネームの者同士、お鍋の底に刻むのがベストだ！我がプリンセスに恥をかかせずに済むし、恥を炎で焼き消すことができるしな！」",
          DialogueId = 80120358,
          GUID = "C892AA3C",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Maer/003/C892AA3C"
        },
        [80120401] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "ふええぇぇぇん！うぅぅぅ……！このレディ・マギー、またしても衝撃の大事件を解決したよぉ……",
          DialogueId = 80120401,
          GUID = "C892B14A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204011
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B14A"
        },
        [80120402] = {
          ContentJP = "ノー！これは、喜びの涙でぇす！",
          DialogueId = 80120402,
          FacialId = {
            [1] = "93301:Ahaha02"
          },
          GUID = "C892B174",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204021
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B174"
        },
        [80120403] = {
          ContentJP = "マギーはコップいっぱいの水を一気に飲み干し、ポケットの中から何かを慎重に取り出し、あなたの前に差し出した。それは小動物の抜け毛だった。どこか見覚えのある色をしている……",
          DialogueId = 80120403,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B19E",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextDialogue = 80120404,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B19E"
        },
        [80120404] = {
          ContentJP = "「まんまるニャーゴ」を見つけたの！",
          DialogueId = 80120404,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B1C8",
          NextOptions = {
            [1] = 801204041
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1C8"
        },
        [80120405] = {
          ContentJP = "昔、私と一緒に雪野原を彷徨った子猫だよ！",
          DialogueId = 80120405,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B1F2",
          NextDialogue = 80120406,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B1F2"
        },
        [80120406] = {
          ContentJP = "アイスレイクの街に入るのを嫌がったから、お外でバイバイしたの……思い出の品として、その子そっくりのぬいぐるみを縫い上げたほどなんだから……！",
          DialogueId = 80120406,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B21C",
          NextDialogue = 80120407,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B21C"
        },
        [80120407] = {
          ContentJP = "今日、城門近くのゴミ箱で仕入れをしていたら、たまたまこのフワ毛が拾ったの！ほら見て！",
          DialogueId = 80120407,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B246",
          NextDialogue = 80120408,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B246"
        },
        [80120408] = {
          ContentJP = "この灰色に黒い斑点の混じった毛色、柔らかいけどちょっと硬さのある手触り、それに拾った時はまだ少し湿ってたし……絶対にまんまるニャーゴが会いに来たに違いない！間違いないって！",
          DialogueId = 80120408,
          GUID = "C892B270",
          NextDialogue = 80120409,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B270"
        },
        [80120409] = {
          ContentJP = "ニャーゴと「ケイドロ」をしてた時、毛繕いで抜けた毛を逃走経路と別方向に残すのがあの子の得意技だった。",
          DialogueId = 80120409,
          GUID = "C892B29A",
          NextDialogue = 80120410,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B29A"
        },
        [80120410] = {
          ContentJP = "あの頃は、まだ駆け出しペーペーの探偵だったから、いつもあの子に翻弄されっぱなしだった。さんざん振り回されて、息を切らしながら必死で追いかけたのに――結局、あいつは頭を高く上げて、尻尾をピンと立てて、得意げに私の目の前を悠々と歩いていくんだよ！",
          DialogueId = 80120410,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B2C4",
          NextDialogue = 80120411,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2C4"
        },
        [80120411] = {
          ContentJP = "思い出した……全部思い出した……！「泥棒キャット」に翻弄された怒り、追跡の手がかりを見失った焦り、雪野原で迷子になった時の恐怖……そして、濡れた猫の毛を握りしめたまま、どうしていいか分からなくなったあの戸惑いまでも……！",
          DialogueId = 80120411,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B2EE",
          NextOptions = {
            [1] = 801204111
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B2EE"
        },
        [80120412] = {
          ContentJP = "へん！今は立派なベテランだよ！それに、ここアイスレイク城はレディ・マギーのガーデンだ。今回は絶対に、「泥棒キャット」を捕まえてやるんだから！",
          DialogueId = 80120412,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B318",
          NextDialogue = 80120413,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B318"
        },
        [80120413] = {
          ContentJP = "まずは路地裏の地形をもとにまんまるニャーゴの潜伏先を推理！更に地元の「ちびノラ」たちをニボシで買収！お外から来た猫ちゃんの手がかりを提供した者には、豪華報酬を用意してるぞってね！",
          DialogueId = 80120413,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B342",
          NextOptions = {
            [1] = 801204131,
            [2] = 801204141
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B342"
        },
        [80120414] = {
          ContentJP = "虚偽の情報を流した白猫さんは、このマギーが逮捕しちゃうぞ！罰として、半月ほどニボシ禁止の刑に処する！",
          DialogueId = 80120414,
          FacialId = {
            [1] = "93301:Confident02"
          },
          GUID = "C892B36C",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B36C"
        },
        [80120415] = {
          ContentJP = "えっへへぇ、そーんなに褒めなくても、うふっ、何も出ないぞ？ニャッハッハ！",
          DialogueId = 80120415,
          FacialId = {
            [1] = "93301:Happy02"
          },
          GUID = "C892B396",
          NextDialogue = 80120416,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B396"
        },
        [80120416] = {
          ContentJP = "ゴホン、話を戻そう……精密な推理の末、ついに段ボールが山積みになった路地裏でニャーゴを発見！ノラ生活を送る猫にとっては、まさに抗えない誘惑だからね！",
          DialogueId = 80120416,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B3C0",
          NextDialogue = 80120417,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3C0"
        },
        [80120417] = {
          ContentJP = "案の定、容疑者は段ボールの中で日向ぼっこしながらゴロゴロしてたんだよ！しかも、余裕しゃくしゃくでこっちに尻尾まで振ってきて！",
          DialogueId = 80120417,
          FacialId = {
            [1] = "93301:Happy01"
          },
          GUID = "C892B3EA",
          NextDialogue = 80120418,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B3EA"
        },
        [80120418] = {
          ContentJP = "こんなに久しぶりなのに、ニャーゴは相変わらずまんまるだった。でも……なんだか昔とは少し違って見えたんだよ。",
          DialogueId = 80120418,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B414",
          NextDialogue = 80120419,
          Scripts = "PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B414"
        },
        [80120419] = {
          ContentJP = "お別れした頃のニャーゴは、大きくなったばかりで、触られるのが嫌いだった。ちょっとでも気に入らないことがあると、行方をくらますような子だったの。でも、今回会った時は…なんだか落ち着いてて、むしろ少し年を取ったように見えたな。",
          DialogueId = 80120419,
          GUID = "C892B43E",
          NextDialogue = 80120420,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B43E"
        },
        [80120420] = {
          ContentJP = "「年を取ると性格が丸くなる」って、動物にも当てはまるのかな？大好物の干し肉を持ってなかったのに、目を細めながら好きに触らせてくれたんだ。お腹も、肉球も、尻尾もね。",
          DialogueId = 80120420,
          GUID = "C892B468",
          NextDialogue = 80120421,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B468"
        },
        [80120421] = {
          ContentJP = "しかもニャーゴってば子猫を何匹か連れたの！昔のニャーゴとみたいに怖がりで、箱の中からちょこんと頭を出してこっそりこちらを覗くだけだったけど、その毛並みを見れば一目瞭然――ニャーゴに丁寧に世話されてたってね！",
          DialogueId = 80120421,
          GUID = "C892B492",
          NextDialogue = 80120422,
          Scripts = "SEQ{PlayAnimation{ActorId{93301},AnimationId{\"Sit_Talk01_Start\"},Duration{1}},PlayAnimation{_delay{2},ActorId{93301},AnimationId{\"Sit_Talk01_End\"},Duration{1}}}",
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B492"
        },
        [80120422] = {
          ContentJP = "なんだか感慨深いなぁ……雪ネズミすら捕まえられなかったドジ猫が、今じゃ子猫たちを守る、立派なボス猫になるなんて！",
          DialogueId = 80120422,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4BC",
          NextOptions = {
            [1] = 801204221
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4BC"
        },
        [80120423] = {
          ContentJP = "そう言われると、私もニャーゴも出会った頃よりずっと成長してるんだなぁ。へへ……なんか、ちょっと照れるな……",
          DialogueId = 80120423,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B4E6",
          NextDialogue = 80120424,
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B4E6"
        },
        [80120424] = {
          ContentJP = "正直に言うとさ、アイスレイク城に来たばかりの頃は、今みたいじゃなかったんだよね。あの頃はよく泣いてたんだ……って、ちょっと！笑わないでよ！？",
          DialogueId = 80120424,
          GUID = "C892B510",
          NextDialogue = 80120425,
          Scripts = "LookAt{_delay{2},LookAtDescription{\"93301:p(18000P2)\"}}",
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B510"
        },
        [80120425] = {
          ContentJP = "何度も思ったんだぁ……アイスレイク城なんてもう出ていこうって。ここに来たこと自体、全部なかったことにしようってね。ニャーゴを見つけて、一緒にあちこちを放浪するのも、なんだか悪くない気がしてさ。",
          DialogueId = 80120425,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B53A",
          LookAt = {
            [1] = "93301:p(18000P3)"
          },
          NextOptions = {
            [1] = 801204251
          },
          SpeakNpcId = 93301,
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B53A"
        },
        [80120426] = {
          ContentJP = "「街ってのはいい場所だ」ってオールドマーティンはいつも言ってた。だから、私もそう思ってたんだ。「街」ってのは、たいまつを掲げた人々が集まって、お互いに支え合い、守り合う避難所みたいなものだって……そう信じてたんだよ。",
          DialogueId = 80120426,
          FacialId = {
            [1] = "93301:Smile01"
          },
          GUID = "C892B564",
          NextDialogue = 80120427,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B564"
        },
        [80120427] = {
          ContentJP = "でも――はぁ……避難所って思ってた街には、バカげたことが山ほどあったよ。カロンたちは理不尽な差別を受けて、貴族の旦那様たちは何世代もが使えるほどの獣皮を持ってるのに、スラムの貧しい人たちはこの冬を越せるかどうかも分からない……",
          DialogueId = 80120427,
          FacialId = {
            [1] = "93301:Sad01"
          },
          GUID = "C892B58E",
          NextDialogue = 80120428,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B58E"
        },
        [80120428] = {
          ContentJP = "それに、ニャーゴに会いたくてたまらなかったの！どこに行っても良いことも悪いこともあるのなら、大好きなニャーゴと一緒にいる方がいいじゃん！って、そう思ったんだよ。",
          DialogueId = 80120428,
          FacialId = {
            [1] = "93301:Satisfy01"
          },
          GUID = "C892B5B8",
          NextOptions = {
            [1] = 801204281,
            [2] = 801204291
          },
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5B8"
        },
        [80120429] = {
          ContentJP = "へ？そんなわけ――いや、ま、まあ……あり得なくはないけど……！とにかく、私は結局はこうしてアイスレイク城にいるでしょ！",
          DialogueId = 80120429,
          FacialId = {
            [1] = "93301:Shock01"
          },
          GUID = "C892B5E2",
          NextDialogue = 80120431,
          Scripts = "PlayAnimation{_delay{1},ActorId{93301},AnimationId{\"Sit_DisagreeHead\"},Duration{1}}",
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B5E2"
        },
        [80120430] = {
          ContentJP = "今振り返ってみると、……ヤなことから逃げるしかできないお子様らしい考えってやつだよ。",
          DialogueId = 80120430,
          FacialId = {
            [1] = "93301:None"
          },
          GUID = "C892B60C",
          NextDialogue = 80120431,
          SpeakNpcId = 93301,
          TalkActionId = {
            [1] = "93301:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Maer/004/C892B60C"
        },
        [80120431] = {
          ContentJP = "あの日、ソラの子供に石を投げつけられたことがあってさ。頭に血が上って、そのまま城門を飛び出したことがあったの。そして、ニャーゴの名前を叫びながら、ただひたすら前へ、前へと走り続けた――",
          DialogueId = 80120431,
          FacialId = {
            [1] = "93301:Uninterested01"
          },
          GUID = "C892B636",
          NextDialogue = 80120432,
          SpeakNpcId = 93301,
          TalkActionId = {
