        },
        [80130120] = {
          ContentJP = "あ？……お前なぁ、こんなのまだ序の口だっての。とっておきの商品があるんだ。ほれ、これだ。",
          DialogueId = 80130120,
          GUID = "C898EBD0",
          NextDialogue = 80130121,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBD0"
        },
        [80130121] = {
          ContentJP = "一見、ただの目覚まし時計に見えるだろ？だが、その威力は半端ねぇんだ。お前が気に食わねぇものを一発で吹き飛ばす、その名も――「流星アラシ」だ。",
          DialogueId = 80130121,
          GUID = "C898EBFA",
          NextDialogue = 80130122,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EBFA"
        },
        [80130122] = {
          ContentJP = "あんたのことはレッドバリー城にいた時から聞いてるぜ。最近大活躍してるっていう月狩り人の新入りだろ。",
          DialogueId = 80130122,
          GUID = "C898EC24",
          NextDialogue = 80130123,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC24"
        },
        [80130123] = {
          ContentJP = "その、覚えにくかったら、「キュートちゃん」でも、いいですよ。これは僕がつけた名前なんです。帝国の兵士たちも、この名前を聞いて爆弾だなんて、思わないでしょ？",
          DialogueId = 80130123,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898EC4E",
          NextDialogue = 80130124,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC4E"
        },
        [80130124] = {
          ContentJP = "あ、その絵は、僕が描いたものです。ええと、少しでも爆弾を、可愛らしくできたらなと、思って。",
          DialogueId = 80130124,
          GUID = "C898EC78",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130125,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898EC78"
        },
        [80130125] = {
          ContentJP = "はぁ、何度言えばわかる！こんなもんを買いに来る時点で、客が見たいのは爆発する瞬間だけだ。外面なんざ、気にするやつはいねぇよ！",
          DialogueId = 80130125,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECA2",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130126,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECA2"
        },
        [80130126] = {
          ContentJP = "でも、僕たちの商品は他のとは違うんだって思わせたいんだ。そもそも、どんな絵を描けばお客さんに気に入ってもらえるか、ずっと横で指図してたじゃないか。",
          DialogueId = 80130126,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ECCC",
          NextDialogue = 80130127,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECCC"
        },
        [80130127] = {
          ContentJP = "そ、それは……描くからには完璧に仕上げないとだろ！見た目が悪いと売上に影響するからな！",
          DialogueId = 80130127,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ECF6",
          NextDialogue = 80130128,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ECF6"
        },
        [80130128] = {
          ContentJP = "ゴホン、とにかく、話は以上だ。俺らの商品を買いたい時には手紙をくれ。",
          DialogueId = 80130128,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED20",
          NextDialogue = 80130129,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED20"
        },
        [80130129] = {
          ContentJP = "あ、手紙には「キュートちゃん」って書いとけよ。帝国軍にバレると厄介だからな。",
          DialogueId = 80130129,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C898ED4A",
          NextDialogue = 80130130,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED4A"
        },
        [80130130] = {
          ContentJP = "僕たちの店の位置は、商品リストに乗ってますので。では、ご注文、お待ちしてます。",
          DialogueId = 80130130,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898ED74",
          NextDialogue = 80130131,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED74"
        },
        [80130131] = {
          ContentJP = "レッドバリー城からやって来た、イェールとオリバー。なんとも印象に残る不思議なコンビだ。時間があれば、あの小さなおもちゃを買ってみるのも悪くない。ボムこまにビュンビュン花火……どれも面白そうだ。",
          DialogueId = 80130131,
          GUID = "C898ED9E",
          VoiceName = "voice/$Locale$/inv/Yeer/001/C898ED9E"
        },
        [80130201] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentJP = "あ、こんにちは……",
          DialogueId = 80130201,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F91A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130202,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F91A"
        },
        [80130202] = {
          ContentJP = "覚えてますか？僕です、「ドンパチ」の店長、イェールです。",
          DialogueId = 80130202,
          FacialId = {
            [1] = "93103:Ahaha02"
          },
          GUID = "C898F944",
          NextOptions = {
            [1] = 801302021,
            [2] = 801302022
          },
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F944"
        },
        [80130203] = {
          ContentJP = "あ……あの時は初対面だったので……今はもう、大丈夫です。",
          DialogueId = 80130203,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F96E",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F96E"
        },
        [80130204] = {
          ContentJP = "まぁ……彼は僕よりずっと、口数が多いので。",
          DialogueId = 80130204,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898F998",
          NextDialogue = 80130205,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F998"
        },
        [80130205] = {
          ContentJP = "けど、今日は色々あって、一人なんです。",
          DialogueId = 80130205,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898F9C2",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130206,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9C2"
        },
        [80130206] = {
          ContentJP = "あ、誤解しないでください。けんかしたわけじゃないので。僕たちはとっても仲がいいんです。でも、だからこそ、彼に言えない悩みもあって……",
          DialogueId = 80130206,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898F9EC",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130207,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898F9EC"
        },
        [80130207] = {
          ContentJP = "だから、こうしてあなたに会いに来ました。解決策を求めるつもりはありません。ただ、聞いてくれるだけでいいんです。だって、あなたは人の話を聞くのが上手そうなので……",
          DialogueId = 80130207,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FA16",
          NextDialogue = 80130208,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA16"
        },
        [80130208] = {
          ContentJP = "実は、「ドンパチ」の初代店長は僕たちではなく、とっても怒りんぼなおじいさんだったんです。",
          DialogueId = 80130208,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FA40",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130209,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA40"
        },
        [80130209] = {
          ContentJP = "彼はせっかちで、いつもあれこれ命令してくるんだけど、僕は不器用だから何もうまくできなくて……それでも、あれこれ言われてるうちに、なんとか店の切り盛りを覚えていきました。",
          DialogueId = 80130209,
          FacialId = {
            [1] = "93103:Unhappy01"
          },
          GUID = "C898FA6A",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130210,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA6A"
        },
        [80130210] = {
          ContentJP = "そんなある日、突然遠出するからって、「ドンパチ」を任されたんです。",
          DialogueId = 80130210,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FA94",
          NextDialogue = 80130211,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FA94"
        },
        [80130211] = {
          ContentJP = "それからは、ひとりで店を切り盛りするようになりました。おじいさんがいないので、新しいおもちゃの作り方もわからない。なんとか昔の在庫を頼りに、細々とやっていくしかありませんでした。",
          DialogueId = 80130211,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FABE",
          NextOptions = {
            [1] = 801302111,
            [2] = 801302112
          },
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FABE"
        },
        [80130212] = {
          ContentJP = "はい……僕もずっと不思議だったんです。なぜ、おじいさんは何の前触れもなく、ふっと姿を消してしまったのか……",
          DialogueId = 80130212,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FAE8",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FAE8"
        },
        [80130213] = {
          ContentJP = "ありがとうございます。あの頃は本当に、毎日必死にいろんなことを覚えようとしていました。",
          DialogueId = 80130213,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FB12",
          NextDialogue = 80130214,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB12"
        },
        [80130214] = {
          ContentJP = "とにかく、そんなふうにして何ヶ月かが過ぎた頃、今まで見たことのない大人たちが子どもを連れて、おもちゃを買いに来るようになりました。「ドンパチ」の商売もだんだん良くなっていったんです。",
          DialogueId = 80130214,
          FacialId = {
            [1] = "93103:Happy01"
          },
          GUID = "C898FB3C",
          NextDialogue = 80130215,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB3C"
        },
        [80130215] = {
          ContentJP = "そんな時でした、僕と同じくらいの年の男の子がふらっと現れたのは。最初は、普通のお客さんだと思って、おもちゃをおすすめしました。",
          DialogueId = 80130215,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C898FB66",
          NextDialogue = 80130216,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB66"
        },
        [80130216] = {
          ContentJP = "すると彼は、冷たい声でこう言ったんです――「『ドンパチ』はあのじいさんの店なんかじゃない。俺の店だ」って。",
          DialogueId = 80130216,
          FacialId = {
            [1] = "93103:Shock01"
          },
          GUID = "C898FB90",
          NextDialogue = 80130217,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FB90"
        },
        [80130217] = {
          ContentJP = "最初はもちろん信じられませんでした。でも彼は、店の中も外もまるで自分の庭みたいに知り尽くしていました。そうして、まっすぐ作業台へ向かい、道具を手に取りました。",
          DialogueId = 80130217,
          GUID = "C898FBBA",
          NextDialogue = 80130218,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBBA"
        },
        [80130218] = {
          ContentJP = "危ないからやめてって言おうとしたら……彼はあっという間に爆弾をひとつ作り上げたんです。その手際の良さは、あのおじいさんよりも、むしろ上手いくらいで……",
          DialogueId = 80130218,
          GUID = "C898FBE4",
          NextDialogue = 80130219,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FBE4"
        },
        [80130219] = {
          ContentJP = "その後、彼は冷たくこう言い放ったんです。あのおじいさんは泥棒だって、そんなおじいさんと一緒に店をやってる僕も……泥棒だって……",
          DialogueId = 80130219,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FC0E",
          NextDialogue = 80130220,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC0E"
        },
        [80130220] = {
          ContentJP = "認めたくはなかったけど……店内にあれほど詳しい点から見れば、彼はまぎれもなく「ドンパチ」の本当の持ち主だったんだと思います。",
          DialogueId = 80130220,
          GUID = "C898FC38",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130221,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC38"
        },
        [80130221] = {
          ContentJP = "だから……僕は……",
          DialogueId = 80130221,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FC62",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302211,
            [2] = 801302212
          },
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC62"
        },
        [80130222] = {
          ContentJP = "はい……か、彼の話が本当だったら……「ドンパチ」を返すつもりでした。",
          DialogueId = 80130222,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FC8C",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FC8C"
        },
        [80130223] = {
          ContentJP = "……もし彼の話が本当なら……ですが。",
          DialogueId = 80130223,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FCB6",
          NextDialogue = 80130224,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCB6"
        },
        [80130224] = {
          ContentJP = "でも……正直すごく怖いんです。彼が本当に「ドンパチ」の主だったら、僕はどうすれば……",
          DialogueId = 80130224,
          FacialId = {
            [1] = "93103:Iyada01"
          },
          GUID = "C898FCE0",
          NextDialogue = 80130225,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FCE0"
        },
        [80130225] = {
          ContentJP = "僕、このお店がすごく好きで……やっと子どもたちに話しかけたり、新しいおもちゃを勧めたりできるようになってきたのに……あの人に、それができるのかな……",
          DialogueId = 80130225,
          GUID = "C898FD0A",
          NextDialogue = 80130226,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD0A"
        },
        [80130226] = {
          ContentJP = "それに……彼にどう謝ればいいんでしょう……なぜ「ドンパチ」を離れたのか分からないけど、でも、なんとか償いたいって気持ちがあって……",
          DialogueId = 80130226,
          FacialId = {
            [1] = "93103:Sad01"
          },
          GUID = "C898FD34",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextDialogue = 80130227,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD34"
        },
        [80130227] = {
          ContentJP = "自分の店を失って、戻ってきたら……もう店が他の人のものになってたら……すごくつらいことだと思うんです……",
          DialogueId = 80130227,
          GUID = "C898FD5E",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextOptions = {
            [1] = 801302271
          },
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FD5E"
        },
        [80130229] = {
          ContentJP = "オリバーに話したら、きっとすごく怒られちゃいます。「せっかく店主になったのに、簡単に手放すなんて馬鹿だ！」って……",
          DialogueId = 80130229,
          FacialId = {
            [1] = "93103:Confident02"
          },
          GUID = "C898FDB2",
          NextDialogue = 80130230,
          SpeakNpcId = 93103,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDB2"
        },
        [80130230] = {
          ContentJP = "彼は絶対止めると思います……口は悪いけど、本当はすごく優しい子なんです……",
          DialogueId = 80130230,
          FacialId = {
            [1] = "93103:Syouganai01"
          },
          GUID = "C898FDDC",
          NextDialogue = 80130231,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FDDC"
        },
        [80130231] = {
          ContentJP = "それに……元の店主も、きっといい人なんだと思うんです。いい人には、ちゃんと優しくしてくれる誰かが必要だと思います……",
          DialogueId = 80130231,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE06",
          NextDialogue = 80130232,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE06"
        },
        [80130232] = {
          ContentJP = "お茶、ありがとうございました……おかげで、自分の気持ちが少し分かった気がします。では……レッドバリー城に帰りますね……",
          DialogueId = 80130232,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C898FE30",
          NextDialogue = 80130233,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE30"
        },
        [80130233] = {
          ContentJP = "それから……「ドンパチ」のおもちゃが必要な時は、手紙を送ってください。店は、まだしばらく続けるつもりですから…",
          DialogueId = 80130233,
          FacialId = {
            [1] = "93103:Smile01"
          },
          GUID = "C898FE5A",
          NextDialogue = 80130234,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE5A"
        },
        [80130234] = {
          ContentJP = "イェールはあわてて駆け出していった。その後ろ姿は、「ドンパチ」を本当の店主に返す決意を固めたように見えた。",
          DialogueId = 80130234,
          GUID = "C898FE84",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Yeer/002/C898FE84"
        },
        [80130301] = {
          Camera = "126.583923,7.386108,128.715088,0.0,-0.799959,-137.795624,30.0,150.0,false,Manual,2.8",
          ContentJP = "あ、どうも。",
          DialogueId = 80130301,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990982",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130302,
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990982"
        },
        [80130302] = {
          ContentJP = "今ひま？ちょっと付き合って。",
          DialogueId = 80130302,
          GUID = "C89909AC",
          NextOptions = {
            [1] = 801303021,
            [2] = 801303022
          },
          SpeakNpcId = 93103,
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909AC"
        },
        [80130303] = {
          ContentJP = "はっ、あの間抜けと一緒にすんな。",
          DialogueId = 80130303,
          GUID = "C89909D6",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89909D6"
        },
        [80130304] = {
          ContentJP = "違うに決まってるだろ。もう爆弾ごっこにはうんざりだ。",
          DialogueId = 80130304,
          GUID = "C8990A00",
          NextDialogue = 80130305,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_YeerWenhao",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A00"
        },
        [80130305] = {
          ContentJP = "俺はオリバー・グスカだ。爆弾に閉じ込められてる哀れなガキじゃねぇ。",
          DialogueId = 80130305,
          GUID = "C8990A2A",
          NextDialogue = 80130306,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A2A"
        },
        [80130306] = {
          ContentJP = "……知らないのか？まあいい、覚えとけ。いつかディズマニアに行くことがあったらな、北門から15キロ先にある廃墟を見てみな。あれを吹き飛ばしたの、俺だから。",
          DialogueId = 80130306,
          GUID = "C8990A54",
          NextDialogue = 80130307,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A54"
        },
        [80130307] = {
          ContentJP = "で、俺がここに来た理由だけど……それはお前の出方次第だ。イェールが前にここで、何を話していったのか――教えてもらおうか？",
          DialogueId = 80130307,
          GUID = "C8990A7E",
          NextOptions = {
            [1] = 801303071,
            [2] = 801303072
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990A7E"
        },
        [80130308] = {
          ContentJP = "へえ、案外口が硬いタイプか。気に入った……お前も「強引な手口の方が効かない」やつだな。",
          DialogueId = 80130308,
          GUID = "C8990AA8",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AA8"
        },
        [80130309] = {
          ContentJP = "……そういうストレートなやつは嫌いじゃない。いいだろう、教えてやるよ。",
          DialogueId = 80130309,
          GUID = "C8990AD2",
          NextDialogue = 80130310,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AD2"
        },
        [80130310] = {
          ContentJP = "じゃあ話してやる。最初から、全部な。",
          DialogueId = 80130310,
          GUID = "C8990AFC",
          NextDialogue = 80130311,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990AFC"
        },
        [80130311] = {
          ContentJP = "さっきも言ったが、この身体は元々俺のもんだった。オリバー・グスカ――爆弾の天才のな。",
          DialogueId = 80130311,
          GUID = "C8990B26",
          NextDialogue = 80130312,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B26"
        },
        [80130312] = {
          ContentJP = "あの頃の俺はな……まだガキだったが、自分の作ったオモチャで世界ひっくり返せるって本気で思ってた。ヒュペリアを丸ごと、吹き飛ばしてやるってな。捕まった後のことなんて想像もしなかった。ってか、そもそも捕まるなんて考えてなかった。",
          DialogueId = 80130312,
          GUID = "C8990B50",
          NextDialogue = 80130313,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B50"
        },
        [80130313] = {
          ContentJP = "で、いざ軍に捕まった時……何が起きるのかすら、サッパリだった。",
          DialogueId = 80130313,
          GUID = "C8990B7A",
          NextDialogue = 80130314,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990B7A"
        },
        [80130314] = {
          ContentJP = "俺は「サーベル錬金院」って研究所に連行された。そこで待ってたのは、ジョーンズって名の、妙に優しげな顔したジジイだった。",
          DialogueId = 80130314,
          GUID = "C8990BA4",
          NextDialogue = 80130315,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BA4"
        },
        [80130315] = {
          ContentJP = "そいつはずっとニコニコしててな、「犯罪は心の病気ですからね、治療すればよくなりますよ」とか……そんなクソみたいな寝言を延々聞かされた。",
          DialogueId = 80130315,
          GUID = "C8990BCE",
          NextDialogue = 80130316,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BCE"
        },
        [80130316] = {
          ContentJP = "メシはちゃんと出た。けど、薬と検査は毎日続いた。薬は苦くなかったが、飲むたびに……頭が回らなくなっていくのを感じたよ。",
          DialogueId = 80130316,
          GUID = "C8990BF8",
          NextDialogue = 80130317,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990BF8"
        },
        [80130317] = {
          ContentJP = "最初はさ、あのジジイの顔見るたびに罵ってやったよ。けど、ある日気づいた。罵り方を思い出せなくなってたんだ。",
          DialogueId = 80130317,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990C22",
          NextDialogue = 80130318,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C22"
        },
        [80130318] = {
          ContentJP = "誰かが言ってた言葉を思い出したよ――「暴言すら吐けない奴は、言語能力を失ってるのと同じだ」ってな。ああ……今ならよくわかる。",
          DialogueId = 80130318,
          GUID = "C8990C4C",
          NextDialogue = 80130319,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C4C"
        },
        [80130319] = {
          ContentJP = "だが、地獄はそこからだった。歩き方が分からなくなったんだ。そして、手が動かせなくなった。最後には……息の仕方まで、わかんなくなった。",
          DialogueId = 80130319,
          GUID = "C8990C76",
          NextDialogue = 80130320,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990C76"
        },
        [80130320] = {
          ContentJP = "頭のどっかで、「薬がおかしい」ってわかってたよ。でも飲んでる時は……その思考すら浮かばねぇんだ。記憶が、じわじわ溶けてくだけでな。いっそ爆弾で吹き飛ばされた方がマシだった。",
          DialogueId = 80130320,
          GUID = "C8990CA0",
          NextDialogue = 80130321,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CA0"
        },
        [80130321] = {
          ContentJP = "気づいたら俺は、鏡の中の自分を見てるような気分になってた。見えるのは俺の身体……でも、誰だよこれって感じでさ。",
          DialogueId = 80130321,
          GUID = "C8990CCA",
          NextDialogue = 80130322,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CCA"
        },
        [80130322] = {
          ContentJP = "そしてある日、あのジジイが言ったんだ――「君の名前はイェールだ」って。",
          DialogueId = 80130322,
          GUID = "C8990CF4",
          NextDialogue = 80130323,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990CF4"
        },
        [80130323] = {
          ContentJP = "……なるほど、イェールね。じゃあ、俺は一体誰なんだ？",
          DialogueId = 80130323,
          GUID = "C8990D1E",
          NextOptions = {
            [1] = 801303231,
            [2] = 801303232
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D1E"
        },
        [80130324] = {
          ContentJP = "……まあ、それも無理ないさ。俺だって、自分の身に何が起きたのか理解するまで、だいぶ時間かかったからな。",
          DialogueId = 80130324,
          GUID = "C8990D48",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D48"
        },
        [80130325] = {
          ContentJP = "――ああ、あいつは、俺の中に「新しい人格」を作ったんだ。そう、オリバーって「犯罪者」を完全に消し去るための、まっさらな代替品をな。",
          DialogueId = 80130325,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990D72",
          NextDialogue = 80130326,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D72"
        },
        [80130326] = {
          ContentJP = "……でもな、イェールが現れたこと自体は、俺にとっちゃ悪い話じゃなかったんだ。だってこれまでの俺はさ――この身体に完全に閉じ込められてて、どれだけ「動け」って念じても、指一本ピクリとも動かせなかったんだよ。",
          DialogueId = 80130326,
          GUID = "C8990D9C",
          NextDialogue = 80130327,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990D9C"
        },
        [80130327] = {
          ContentJP = "けどな、不思議なことに――俺の「考え」は、イェールにだけは伝わるんだよ。「お前なんか偽物だ」って強く念じるだけで、あいつはビクッて怯えて、キョロキョロしながら首すくめて……まるで驚いたウズラみたいにな。",
          DialogueId = 80130327,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990DC6",
          NextDialogue = 80130328,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DC6"
        },
        [80130328] = {
          ContentJP = "あの頃の俺がどれほど奴を憎んだか、わかるだろ？知る限りの汚い言葉を、毎日毎日ぶつけてやったよ。",
          DialogueId = 80130328,
          GUID = "C8990DF0",
          NextDialogue = 80130329,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990DF0"
        },
        [80130329] = {
          ContentJP = "あいつにとっての俺は、きっと頭の中に突然湧いてきた妙な声って感じだったんだろうな。",
          DialogueId = 80130329,
          GUID = "C8990E1A",
          NextDialogue = 80130330,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E1A"
        },
        [80130330] = {
          ContentJP = "あいつも、俺を頭の中から追い出そうとしたことがある。だが、俺が負けるわけないだろ？もともとこの身体の持ち主は俺だったんだから。",
          DialogueId = 80130330,
          GUID = "C8990E44",
          NextDialogue = 80130331,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E44"
        },
        [80130331] = {
          ContentJP = "だが、腹立たしいことに、ジョーンズは奴の異変に気付いてしまった。あのくそジジイはイェールに「オリバーを知ってるか」って聞きやがったんだ。",
          DialogueId = 80130331,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990E6E",
          NextDialogue = 80130332,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E6E"
        },
        [80130332] = {
          ContentJP = "イェールは「知らない」と答えた。だが、ジョーンズはずっと、ずーっとイェールから目を離さなかった。まるで……俺のことまで見透かしてるみたいな気分だったよ。",
          DialogueId = 80130332,
          GUID = "C8990E98",
          NextDialogue = 80130333,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990E98"
        },
        [80130333] = {
          ContentJP = "\n――それから間もなくして、ジョーンズはイェールに一台の蓄音機を持ってきた。その蓄音機が音楽を流す瞬間、俺の意識はプツンと消える。まるで闇の中の蝋燭が、誰かに吹き消されたみたいにな。",
          DialogueId = 80130333,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8990EC2",
          NextDialogue = 80130334,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EC2"
        },
        [80130334] = {
          ContentJP = "\nわかってたよ。あの蓄音機と音楽はジョーンズが俺を消すために用意した新しい「薬」だ。やつは、俺の意識を完全に「イェール」にしようとしていたんだ。",
          DialogueId = 80130334,
          GUID = "C8990EEC",
          NextDialogue = 80130335,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990EEC"
        },
        [80130335] = {
          ContentJP = "\nこんなふうに意識の浮き沈みを繰り返してるうちに、いずれはすべての記憶を失ってしまうんじゃないか――ずっとそう思ってた。でもある日突然、目を覚ました俺にイェールがこう言ったんだ。「もう、あの音楽は聞きたくない」って。",
          DialogueId = 80130335,
          GUID = "C8990F16",
          NextDialogue = 80130336,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F16"
        },
        [80130336] = {
          ContentJP = "\n……その時、ふと気づいたんだ。ずっと「偽物」呼ばわりしてたこいつは、確かに俺とは違う、別の存在なんだって。それから俺たちは一緒に計画を立てた。ジョーンズの目を欺いて、うまく逃げ出す作戦をな。",
          DialogueId = 80130336,
          GUID = "C8990F40",
          NextDialogue = 80130337,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F40"
        },
        [80130337] = {
          ContentJP = "こうして、最終的に辿り着いたのがレッドバリー城だ。俺たちは小さなおもちゃ屋を開いた。店の名前は……「ドンパチ」。イェールが付けた、なんともセンスがわりぃ名だろ。あの日から、研究所のことは――ふたりとも、一度も口にしてない。",
          DialogueId = 80130337,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8990F6A",
          NextDialogue = 80130338,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F6A"
        },
        [80130338] = {
          ContentJP = "それからずっと何事もなく過ごしてきたけど……数日前、あの懐かしい感覚がまた俺を襲った。意識がふっと途切れて、ああ、こいつまた薬を飲んだなってすぐにわかった。だが、あいつがどこに行ったのかはまるで見当もつかなかった。いろいろ聞き回って、やっと分かったんだ――あいつはアイスレイク城に来たんだってな。",
          DialogueId = 80130338,
          GUID = "C8990F94",
          NextDialogue = 80130339,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990F94"
        },
        [80130339] = {
          ContentJP = "俺はあいつを一番理解しているつもりだ。臆病で、人見知りで……でも、それ以上に優しいやつ。だからさ……俺に隠しごとなんて、するはずがないって思ってたんだよ。",
          DialogueId = 80130339,
          GUID = "C8990FBE",
          NextDialogue = 80130340,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FBE"
        },
        [80130340] = {
          ContentJP = "そこで、俺もあいつが飲んだのと同じ、もう一つの人格を眠らせる薬を飲んだ。何があったのか、あいつがここで何を話したのか――それを確かめるためにな。",
          DialogueId = 80130340,
          GUID = "C8990FE8",
          NextOptions = {
            [1] = 801303401
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8990FE8"
        },
        [80130341] = {
          ContentJP = "（イェールが話した「ドンパチ」とその本当の持ち主の話をした。この話はきっと、彼自身の身体とオリバーに対する複雑な想いだったのだろう。）",
          DialogueId = 80130341,
          GUID = "C8991012",
          IsBlack = 1,
          NextDialogue = 80130342,
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991012"
        },
        [80130342] = {
          ContentJP = "――つまり、あいつが薬を飲んだのは、この身体を……俺に返すって、覚悟を決めたから、だったのか？",
          DialogueId = 80130342,
          GUID = "C899103C",
          NextDialogue = 80130343,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899103C"
        },
        [80130343] = {
          ContentJP = "あ、あんの……バカ野郎が！！",
          DialogueId = 80130343,
          FacialId = {
            [1] = "93103:Yeer_EyeChangedSad"
          },
          GUID = "C8991066",
          LookAt = {
            [1] = "93103:p(18000P2)"
          },
          NextOptions = {
            [1] = 801303431,
            [2] = 801303432
          },
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991066"
        },
        [80130344] = {
          ContentJP = "……冷やかすな。俺はここであいつの目覚めるのを待つ。そんで、ちゃんと話すんだ。過去のことを、全部な。",
          DialogueId = 80130344,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C8991090",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C8991090"
        },
        [80130345] = {
          ContentJP = "……さぁな。だが、ここであいつが目覚めるのを待つつもりだ。そして――ちゃんと話すよ。過去のことをすべてな。",
          DialogueId = 80130345,
          FacialId = {
            [1] = "93103:Yeer_EyeChanged"
          },
          GUID = "C89910BA",
          LookAt = {
            [1] = "93103:p(18000P3)"
          },
          NextDialogue = 80130346,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910BA"
        },
        [80130346] = {
          ContentJP = "……ああ、それと――ありがとうな。こんな昔話に付き合ってくれて。あとでイェールが目を覚ましたら……きっと、また一悶着あるだろうし、そのときは、そばであいつを少しなだめてやってくれ。頼んだぜ。",
          DialogueId = 80130346,
          FacialId = {
            [1] = "93103:Happy02"
          },
          GUID = "C89910E4",
          NextDialogue = 80130347,
          SpeakNpcId = 93103,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "93103:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/003/C89910E4"
        },
        [80130347] = {
          ContentJP = "オリバーは不安げに椅子に腰かけ、足をそわそわと揺らしている。どうやら、イェールが目を覚ますまでには、まだ少しかかりそうだ……",
          DialogueId = 80130347,
          FacialId = {
            [1] = "93103:None"
          },
          GUID = "C899110E",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Yeer/003/C899110E"
        },
