        [80130418] = {
          Camera = "353.637695,44.699951,122.273438,0.0,0.0,15.598783,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "僕も外の世界がどんなのかは、正直わからなかった。その時、僕の記憶にあったのは、いつも明かりが灯っている、消毒液の匂いが充満した部屋だけだったから。",
          DialogueId = 80130418,
          FinalCamera = "353.637695,60.0,122.273438,0.0,0.0,15.598783,35.0,100000.0,false,DoNotOverride,2.8",
