          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991F2A"
        },
        [80130434] = {
          Camera = "-55.089355,-146.949646,115.0,0.0,0.0,167.992569,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "<Default note=\"text:お前\">イェール</>は<Default note=\"text:俺\">オリバー</>にとっての恩人であり、借りがある存在であり、そして――「ドンパチ」のもう一人の店主だ。",
          DialogueId = 80130434,
          FacialId = {
            [1] = "790024:Yeer_EyeChangedSad"
          },
          GUID = "C8991F54",
          NextDialogue = 80130435,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991F54"
        },
        [80130435] = {
          Camera = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "だから、もう謝るな。申し訳ないって思うんなら、一緒に店を手伝え。償いの機会など、いやって言うほどくれてやるから。",
          DialogueId = 80130435,
          GUID = "C8991F7E",
          NextDialogue = 80130436,
          SpeakNpcId = 790024,
