          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8991FFC"
        },
        [80130439] = {
          Camera = "-5.302734,-158.019836,107.0,0.0,0.0,167.592896,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "へぇ、いいじゃん。今度一緒に行こうぜ。だが、見終わった後でまた身体を返すなんて、なしだからな。",
          DialogueId = 80130439,
          GUID = "C8992026",
          NextDialogue = 80130440,
          SpeakNpcId = 790024,
          SpeakNpcName = "UI_Npc_Name_Oliver",
          TalkActionId = {
            [1] = "790023:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8992026"
        },
        [80130440] = {
          Camera = "-160.233398,-161.052856,109.0,0.0,0.0,15.397967,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "うん、もう絶対言わないよ。帰ろう、オリバー。きっと、子どもたちが「ドンパチ」の開店を待ってるよ。",
          DialogueId = 80130440,
          FacialId = {
            [1] = "790023:Happy02"
          },
          GUID = "C8992050",
          NextDialogue = 80130441,
          SpeakNpcId = 790023,
          TalkActionId = {
            [1] = "790023:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C8992050"
        },
        [80130441] = {
          Camera = "-315.086426,-472.144592,127.0,-0.0,-4.000004,58.795139,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "それから、{nickname}さん。ありがとうございました。後ほど、「キュートちゃん」を一つ送りますね。もちろん、タダです。",
          DialogueId = 80130441,
          GUID = "C899207A",
          NextOptions = {
            [1] = 801304411
          },
          SpeakNpcId = 790023,
          TurnTo = {
            [1] = "100001:n(790023)",
            [2] = "790023:n(100001)",
            [3] = "790024:n(100001)"
          },
          VoiceName = "voice/$Locale$/inv/Yeer/004/C899207A"
        },
        [80130443] = {
          ContentJP = "長く感じられた一日がようやく終わりを迎えた。\n訪れたのは、同じように長い夜ではなく、遠くの空の端にほんのりと光が差し込み始めている。\nまるで新たな一日の始まりを告げるかのような、朝日の兆しだった。",
          DialogueId = 80130443,
          GUID = "C89920CE",
          VoiceName = "voice/$Locale$/inv/Yeer/004/C89920CE"
        },
        [80140101] = {
          ContentJP = "君は誰……？",
          DialogueId = 80140101,
          Duration = 3,
          GUID = "C89F5152",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5152"
        },
        [80140102] = {
          ContentJP = "何をしてるの？",
          DialogueId = 80140102,
          Duration = 3,
          GUID = "C89F517C",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F517C"
        },
        [80140103] = {
          Camera = "308.258453,-324.54126,203.320312,0.000018,-13.199941,134.196289,45.171967,100000.0,false,DoNotOverride,2.8",
          ContentJP = "パシファル、教えて。一体何があったの？あなたの角を折ったのは誰なの？",
          DialogueId = 80140103,
          FacialId = {
            [1] = "790031:CM_Angry01",
            [2] = "790030:Disappoint01"
          },
          GUID = "C89F51A6",
          LookAt = {
            [1] = "790031:n(790030)"
          },
          NextDialogue = 80140104,
          Scripts = "SetLocation{ActorId{790032},TargetPoint{\"SetPoint_Puqi\"},Visibility{\"Hide\"}}",
          SpeakNpcId = 790031,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F51A6"
        },
        [80140104] = {
          Camera = "-311.42627,-48.326935,136.539062,0.000017,-3.399344,6.607203,41.865784,100000.0,false,DoNotOverride,2.8",
          ContentJP = "世間の目や意見なんて、私にはどうでもいいの。でも、「マジックフルート」においては、いかなるいじめも許されないわ！馬鹿げた差別や憎しみは――高潔な芸術を汚す行為よ！",
          DialogueId = 80140104,
          GUID = "C89F51D0",
          LookAt = {
            [1] = "790031:n(790030)"
          },
          NextDialogue = 80140105,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F51D0"
        },
        [80140105] = {
          ContentJP = "怖がらないで、パシファル。ただ事実をありのままに話してくれればいいの。誰であれ公正に処罰するわ。その者は必ず除名されると約束しましょう。",
          DialogueId = 80140105,
          GUID = "C89F51FA",
          LookAt = {
            [1] = "790031:n(790030)"
          },
          NextDialogue = 80140106,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F51FA"
        },
        [80140106] = {
          Camera = "-60.211216,-179.25705,55.679688,0.000037,18.399382,95.598686,58.124969,100000.0,false,DoNotOverride,2.8",
          ContentJP = "「愚馬鹿げた差別や憎しみは高潔な芸術を汚す行為」か――劇団に「カロン族は俳優として舞台に立てない」なんて暗黙のルールがなければ、信じるとこでしたよ。",
          DialogueId = 80140106,
          GUID = "C89F5224",
          NextDialogue = 80140107,
          Scripts = "LookAt{_delay{6},LookAtDescription{\"790030:n(790031)\"}}",
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5224"
        },
        [80140107] = {
          Camera = "-64.211678,-24.009537,132.21875,0.000007,2.199819,-2.797291,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "それは……！",
          DialogueId = 80140107,
          FacialId = {
            [1] = "790031:CM_Shock01"
          },
          GUID = "C89F524E",
          LookAt = {
            [1] = "790030:n(790031)"
          },
          NextDialogue = 80140108,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F524E"
        },
        [80140108] = {
          Camera = "285.028381,-293.271179,282.699219,0.000063,-23.799669,134.202179,35.63834,100000.0,false,DoNotOverride,2.8",
          ContentJP = "……あ、ごめんなさい！僕、なんて失礼なことを……",
          DialogueId = 80140108,
          FinalCamera = "249.140015,-256.372009,260.007812,0.000063,-23.799669,134.202179,35.63834,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F5278",
          NextDialogue = 80140109,
          SpeakNpcId = 790030,
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5278"
        },
        [80140109] = {
          ContentJP = "先生を疑っているわけではありません。先生はソラであろうとカロンであろうと、偏見を持たず接してくれました。自己中で傲慢なのは、観客たちだけだってわかってます。",
          DialogueId = 80140109,
          GUID = "C89F52A2",
          NextDialogue = 80140110,
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F52A2"
        },
        [80140110] = {
          ContentJP = "劇団のみんなもとても優しくて、いじめられたことはありません。この角は、<H>自分で</>切り落としたんです。",
          DialogueId = 80140110,
          GUID = "C89F52CC",
          NextDialogue = 80140111,
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F52CC"
        },
        [80140111] = {
          ContentJP = "……なっ……",
          DialogueId = 80140111,
          GUID = "C89F52F6",
          NextDialogue = 80140112,
          SpeakNpcId = 790031,
          TalkActionId = {
            [1] = "790031:Shock_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F52F6"
        },
        [80140112] = {
          Camera = "3689.480957,-784.508362,319.140625,0.000159,7.198042,-109.808243,11.909616,100000.0,false,DoNotOverride,2.8",
          ContentJP = "先生、僕は舞台に立ちたいんです。自分の声で歌詞を歌い、自分の目で観客を見て、スポットライトに照らされたあの世界に踏み入れたいんです……",
          DialogueId = 80140112,
          FinalCamera = "3452.359619,-1442.865723,407.496094,0.000159,7.198042,-109.808243,11.909616,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F5320",
          NextDialogue = 80140113,
          SpeakNpcId = 790030,
          TalkActionId = {
            [1] = "790031:Shock_End"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5320"
        },
        [80140113] = {
          Camera = "-79.301102,-133.298798,120.894531,0.000185,-0.201231,89.005852,42.56609,134.092804,false,Manual,2.8",
          ContentJP = "この「悪魔の角」さえなければ、僕も舞台に立てるんですよね？",
          DialogueId = 80140113,
          GUID = "C89F534A",
          NextDialogue = 80140114,
          SpeakNpcId = 790030,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F534A"
        },
        [80140114] = {
