          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5AD6"
        },
        [80140160] = {
          ContentJP = "僕はただ、舞台に立ちたかっただけなんだ。",
          DialogueId = 80140160,
          GUID = "C89F5B00",
          NextDialogue = 80140161,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5B00"
        },
        [80140161] = {
          ContentJP = "しかし、舞台に降り注いだのは花ではなく、血だった。",
          DialogueId = 80140161,
          GUID = "C89F5B2A",
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5B2A"
        },
        [80140162] = {
          ContentJP = "僕は哀しき囚人、自らの手で汚らわしい罪状を差し出す。",
          DialogueId = 80140162,
          Duration = 4,
          GUID = "C89F5B54",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5B54"
        },
        [80140163] = {
          ContentJP = "そして、裁きを受ける。",
          DialogueId = 80140163,
          Duration = 3,
          GUID = "C89F5B7E",
          VoiceName = "voice/$Locale$/inv/Tuosi/001/C89F5B7E"
        },
        [80140164] = {
