          GUID = "C89F578F",
          IsBlack = 1,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/invite/applaud\"},PlayAs2D{true}}"
        },
        [80140201] = {
          ContentJP = "君は誰……？",
          DialogueId = 80140201,
          Duration = 3,
          GUID = "C89F61BA",
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F61BA"
        },
        [80140202] = {
          ContentJP = "何を探しているの？",
          DialogueId = 80140202,
          Duration = 3,
          GUID = "C89F61E4",
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F61E4"
        },
        [80140203] = {
          Camera = "-894.0,93.0,384.207031,0.0,-18.199085,2.584682,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "私に用があるそうだね、若き俳優よ。",
          DialogueId = 80140203,
          FinalCamera = "-894.0,84.0,384.207031,0.0,-18.199085,2.584682,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F620E",
          LookAt = {
            [1] = "790043:n(790040)",
            [2] = [[

790040:n(790043)]]
          },
          NextDialogue = 80140204,
          Scripts = "MoveTo{ActorId{790043},MoveSpeed{100},TargetPoint{\"P80140204\"}}",
          SpeakNpcId = 790040,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F620E"
        },
        [80140204] = {
          Camera = "-26.839844,69.702148,131.152344,0.000001,4.999924,119.395248,35.000011,224.273438,false,Manual,2.8",
          ContentJP = "……始めまして、グレンヴィル様。",
          DialogueId = 80140204,
          GUID = "C89F6238",
          NextDialogue = 80140205,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6238"
        },
        [80140205] = {
          ContentJP = "僕は『マジックフルート』劇団の俳優――パシファル・スノーフィルド。モーリス・グレンヴィル様がこちらにいるとお聞きし、団長からご挨拶とささやかな贈り物をお持ちするよう申し付かりました。",
          DialogueId = 80140205,
          GUID = "C89F6262",
          NextDialogue = 80140206,
          Scripts = "PlayAnimation{_delay{3},ActorId{790043},AnimationId{\"Explain02_End\"},Duration{1},_click{false}}",
          SpeakNpcId = 790043,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6262"
        },
        [80140206] = {
          ContentJP = "こちらは劇場の二百周年の記念バッジです。どうぞお納めください。",
          DialogueId = 80140206,
          GUID = "C89F628C",
          NextDialogue = 80140207,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F628C"
        },
        [80140207] = {
          Camera = "-362.974609,231.725586,229.28125,0.000003,-18.599478,-6.208903,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ほう？私はあまり劇場には来ないのだが、こうしたもてなしを受けるのは初めてだよ。光栄だ。プッチ夫人にはよろしく伝えてくれ。",
          DialogueId = 80140207,
          GUID = "C89F62B6",
          NextDialogue = 80140208,
          SpeakNpcId = 790040,
          TalkActionId = {
            [1] = "790043:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F62B6"
        },
        [80140208] = {
          Camera = "-26.839844,69.702148,131.152344,0.000001,4.999924,119.395248,35.000011,224.273438,false,Manual,2.8",
          ContentJP = "あなたは劇場の大切なお客様ですから。突然の訪問をお許しください。",
          DialogueId = 80140208,
          GUID = "C89F62E0",
          NextDialogue = 80140209,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790043},AnimationId{"Explain02_Start"},Duration{4}},
PlayAnimation{ActorId{790043},AnimationId{"Explain02_End"},Duration{1}}
}]],
          SpeakNpcId = 790043,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F62E0"
        },
        [80140209] = {
          Camera = "-408.677734,262.879395,203.933594,0.000049,-12.399716,-12.21366,37.0,490.941406,false,Manual,2.8",
          ContentJP = "構わないよ。妻と子どもたちはまだ到着していなくてね、ちょうど暇をしてたとろこだ。君は俳優と言ったね。これから舞台に上がるのかい？",
          DialogueId = 80140209,
          GUID = "C89F630A",
          NextDialogue = 80140210,
          SpeakNpcId = 790040,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F630A"
        },
        [80140210] = {
          Camera = "-110.558594,139.20166,173.46875,0.00002,-8.599856,100.192047,35.000008,108.885063,false,Manual,2.8",
          ContentJP = "……いえ、今日の舞台には上がりません。実は、今回ご挨拶の他に……少し個人的な話があって参りました。",
          DialogueId = 80140210,
          GUID = "C89F6334",
          NextDialogue = 80140211,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6334"
        },
        [80140211] = {
          Camera = "-478.255859,-5.12793,182.710938,0.00001,-7.599002,24.784918,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ほう？話してごらん。若者の悩みを聞くのは嫌いじゃない。",
          DialogueId = 80140211,
          GUID = "C89F635E",
          NextDialogue = 80140212,
          SpeakNpcId = 790040,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F635E"
        },
        [80140212] = {
          Camera = "-16.511719,59.08252,140.367188,0.000026,1.999565,118.993134,35.000015,220.325043,false,Manual,2.8",
          ContentJP = "その前に、この古い手紙と懐中時計を見て頂けますか。昔を思い出す手助けになるかと。",
          DialogueId = 80140212,
          GUID = "C89F6388",
          NextDialogue = 80140213,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Give"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6388"
        },
        [80140213] = {
          Camera = "-395.544922,246.702637,229.242188,0.000005,-17.199884,-7.005292,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "この懐中時計、かなり値の張る物だな。それにグレンヴィル家の家紋が刻まれている……私が特注したものか。この手紙も……ふむ、確かに私の筆跡だ。「ヘゼレードへ」と書いてあるな……",
          DialogueId = 80140213,
          DialoguePanelType = "{type:showpic;dir:Texture2D'/Game/UI/Texture/Dynamic/Atlas/Prop/Item/T_Read_03.T_Read_03'}",
          GUID = "C89F63B2",
          NextDialogue = 80140214,
          SpeakNpcId = 790040,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F63B2"
        },
        [80140214] = {
          Camera = "259.349609,-125.29248,118.851562,0.000007,1.999504,130.99202,46.855404,100000.0,false,DoNotOverride,2.8",
          ContentJP = "はい、これは二十二年前、あなたがある女性に当てた手紙です。彼女の名前はヘゼレード・スノーフィルド……僕の母です。彼女は数年前に病気で亡くなりました。",
          DialogueId = 80140214,
          GUID = "C89F63DC",
          NextDialogue = 80140215,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F63DC"
        },
        [80140215] = {
          ContentJP = "母は生前、一切僕の父親のことを口にしませんでした。でも、彼女の遺品を整理していた時、若い頃のあなたとの手紙が見つかったんです。これはそのうちの一通です。",
          DialogueId = 80140215,
          FacialId = {
            [1] = "790043:Disappoint01"
          },
          GUID = "C89F6406",
          NextDialogue = 80140216,
          Scripts = "PlayAnimation{ActorId{790043},AnimationId{\"Disagree\"},Duration{1},_delay{1}}",
          SpeakNpcId = 790043,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6406"
        },
        [80140216] = {
          Camera = "-43.1875,107.541016,135.941406,0.00001,5.599901,121.996529,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "手紙の内容によれば、二十数年前、あなたと母は子爵様の晩餐会で出会い、互いに惹かれた……そして、その晩餐会は、僕が生まれるちょうど十ヶ月前のことでした。",
          DialogueId = 80140216,
          GUID = "C89F6430",
          NextDialogue = 80140217,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790043},AnimationId{"Explain02_Start"},Duration{4}},
PlayAnimation{ActorId{790043},AnimationId{"Explain02_End"},Duration{1}}
}]],
          SpeakNpcId = 790043,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6430"
        },
        [80140217] = {
          Camera = "-22.451172,56.513184,131.0,0.0,4.999951,121.795105,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "……つまり、君は私の子だと言いたいのか？",
          DialogueId = 80140217,
          GUID = "C89F645A",
          IsBlack = 1,
          NextDialogue = 80140218,
          SpeakNpcId = 790040,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F645A"
        },
        [80140218] = {
          Camera = "-22.451172,56.513184,131.0,0.0,4.999951,121.795105,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "そうだと……思います。",
          DialogueId = 80140218,
          GUID = "C89F6484",
          IsBlack = 1,
          SpeakNpcId = 790043,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6484"
