        },
        [80140220] = {
          ContentJP = "うちのバカ息子どもが君のように礼儀正しく振る舞えたら、この額のシワも少しは減っただろう。",
          DialogueId = 80140220,
          FacialId = {
            [1] = "790041:CM_Smile01"
          },
