        [80140221] = {
          Camera = "74.876953,-124.654785,174.847656,0.000015,-4.99993,100.007851,42.987816,100000.0,false,DoNotOverride,2.8",
          ContentJP = "とんでもない。これも母のおかげです。決して裕福ではありませんでしたが、母はいつも僕の言葉遣いや振る舞いに人一倍厳しかったので。",
          DialogueId = 80140221,
          GUID = "C89F6502",
