        },
        [80140224] = {
          Camera = "-34.798828,193.138184,154.609375,0.0,0.799924,-54.994884,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "もちろんさ、はっきりと覚えているよ！彼女は本当に美しかった。どこへ行っても彼女の周りにはいつも人が集まる。まるで星のように輝かしい女性だった。",
          DialogueId = 80140224,
          FacialId = {
            [1] = "790041:CM_Ahaha01"
          },
          FinalCamera = "-18.773438,170.275879,154.949219,0.0,0.799924,-54.994884,35.000008,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F6580",
          NextDialogue = 80140225,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Agree"
          },
          ToFinalCameraBlendTime = 20,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6580"
        },
        [80140225] = {
          ContentJP = "「あの晩、幸運にも一曲一緒に踊ったんだ。興奮で一晩中眠れなかった。その後彼女も私に好意を抱いたと知った時は、本当に夢を見てる気分だった！",
          DialogueId = 80140225,
          FacialId = {
