        [80140226] = {
          Camera = "-411.96875,787.237305,417.886719,0.0,10.799888,-2.394898,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "彼女は薔薇色のドレスに身を包み、肌は月光に照らされた雪よりも白く輝いていた。酒を飲んだせいか、頬を真っ赤にしていてね。まるで摘みたてのバラのようにみずみずしくて美しかった。",
          DialogueId = 80140226,
          FinalCamera = "-417.09375,664.340332,417.886719,0.000003,10.799894,-2.394897,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F65D4",
          NextDialogue = 80140227,
          SpeakNpcId = 790041,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F65D4"
        },
        [80140227] = {
          Camera = "-45.705078,202.01123,152.460938,0.0,0.200002,-51.597355,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "君が舞台俳優になったのも、きっと彼女の影響を受けたのだろう？あの頃、私たちはよく一緒に劇を観に行ったものだ。彼女は劇中の歌詞をすべて覚えていて、自宅でもよく口ずさんでいたよ。",
          DialogueId = 80140227,
          GUID = "C89F65FE",
          NextDialogue = 80140228,
          Scripts = [[
SEQ{
PlayAnimation{ActorId{790041},AnimationId{"Think_Start"},Duration{3}},
PlayAnimation{ActorId{790041},AnimationId{"Think_End"},Duration{1},_click{false}}
}]],
          SpeakNpcId = 790041,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F65FE"
        },
        [80140228] = {
          Camera = "0.203125,58.743164,162.792969,0.000001,-1.199982,94.401482,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "はい……！幼い頃、母は暇さえあれば歌を教えてくれました。彼女は僕の最初の先生なんです。",
          DialogueId = 80140228,
          FacialId = {
            [1] = "790043:Happy01"
          },
          GUID = "C89F6628",
          NextDialogue = 80140229,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6628"
        },
        [80140229] = {
          Camera = "-33.238281,218.664062,168.585938,0.000047,-3.400478,-59.395172,44.726002,198.823807,false,Manual,2.8",
          ContentJP = "でも、なぜかある日、彼女は突然私の前から姿を消した。随分と探したけれど、彼女の消息は掴めなかった。",
          DialogueId = 80140229,
          FacialId = {
            [1] = "790041:CM_Sad01"
          },
          GUID = "C89F6652",
          NextDialogue = 80140230,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6652"
        },
        [80140230] = {
          ContentJP = "すまない、坊や……君に嘘をついた。彼女を失って以来、あまりの悲しみにオペラを見に行っていないんだ……ああ、私のせいだ……もっと時間をかけて探していれば……",
          DialogueId = 80140230,
          FacialId = {
            [1] = "790041:CM_Smile01"
          },
          GUID = "C89F667C",
          NextDialogue = 80140231,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Sigh_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F667C"
        },
        [80140231] = {
          Camera = "77.599609,-172.286133,173.375,0.000016,-3.599824,98.804359,53.30518,100000.0,false,DoNotOverride,2.8",
          ContentJP = "物心がついた時から、母は体が弱い人でした。ご存知でしょうが、彼女はプライドの高い人でしたから――弱った姿をあなたに見られたくなかったのでしょう……",
          DialogueId = 80140231,
          GUID = "C89F66A6",
          NextDialogue = 80140232,
          Scripts = "PlayAnimation{_delay{3},ActorId{790043},AnimationId{\"Explain01_Start\"},Duration{3}}",
          SpeakNpcId = 790043,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F66A6"
        },
        [80140232] = {
          Camera = "-184.095703,349.422363,165.8125,0.000016,-3.599824,-45.596992,45.495754,100000.0,false,DoNotOverride,2.8",
          ContentJP = "なんてバカな娘なんだ……私がそんなこと気にするわけないだろう……！別れの機会すらくれぬなど、本当にひどいことをしてくれたものだ。",
          DialogueId = 80140232,
          FacialId = {
            [1] = "790041:CM_Sad01"
          },
          GUID = "C89F66D0",
          NextDialogue = 80140233,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790043:Explain01_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F66D0"
        },
        [80140233] = {
          Camera = "-200.789062,-353.42627,352.734375,0.000034,-22.800413,63.99617,31.488432,100000.0,false,DoNotOverride,2.8",
          ContentJP = "気にしないでください。もう過ぎたことです。母を覚えていると知れただけでも嬉しいです。正直に言うと、突然の訪問が無礼に思われないか心配で――",
          DialogueId = 80140233,
          FinalCamera = "-359.621094,-233.489746,352.734375,0.000046,-23.200396,43.196053,31.488432,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F66FA",
          NextDialogue = 80140234,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Explain02_Start"
          },
          ToFinalCameraBlendTime = 30,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F66FA"
        },
        [80140234] = {
          ContentJP = "そんな！君のような優秀な息子がいるなんて、私は幸せ者だよ！",
          DialogueId = 80140234,
          FacialId = {
            [1] = "790041:CM_Smile01"
          },
          GUID = "C89F6724",
          NextDialogue = 80140235,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Disagree",
            [2] = "790043:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6724"
        },
        [80140235] = {
          Camera = "-641.517578,1081.805664,364.761719,0.0,4.999999,121.995232,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "実はね、グレンヴィル家はガレア劇場に投資をして、互いに利益を最大化したいんだ。今回ここに来たのも、プッチ夫人とその話をするためでね。もし劇団の誰かが仲介してくれれば……",
          DialogueId = 80140235,
          FinalCamera = "-768.751953,1002.334961,361.761719,0.0,4.999999,121.995232,35.0,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F674E",
          NextDialogue = 80140236,
          SpeakNpcId = 790041,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F674E"
        },
        [80140236] = {
          Camera = "-108.212891,125.750488,144.558594,0.000007,3.800044,-23.395102,40.72089,100000.0,false,DoNotOverride,2.8",
          ContentJP = "そういえば君、どんな役を演じたんだい？こんなに優秀なのだから、きっと主役なんだろうね？",
          DialogueId = 80140236,
          GUID = "C89F6778",
          NextDialogue = 80140237,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6778"
        },
        [80140237] = {
          Camera = "-54.142578,120.238281,142.078125,0.000007,9.999929,72.400467,35.000011,100000.0,false,DoNotOverride,2.8",
          ContentJP = "ええと……色んな役を演じました。先日、『雪国の幼子』の主役を務めたばかりです。",
          DialogueId = 80140237,
          GUID = "C89F67A2",
          NextDialogue = 80140238,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790041:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F67A2"
        },
        [80140238] = {
          Camera = "-230.673828,393.289062,190.988281,0.000021,-6.600032,-46.195755,43.502876,100000.0,false,DoNotOverride,2.8",
          ContentJP = "なんと、もしかして月の初めの公演かい？！商売仲間に誘われたんだ。あの劇は大人気で、チケットを手に入れるのも一苦労だったらしい。残念ながら、私は外で用事があって行けなかったんだけどね。",
          DialogueId = 80140238,
          FacialId = {
            [1] = "790041:CM_Shock01"
          },
          FinalCamera = "-177.8125,338.127441,182.257812,0.000021,-6.600032,-46.195755,43.502876,100000.0,false,DoNotOverride,2.8",
          GUID = "C89F67CC",
          NextDialogue = 80140239,
          SpeakNpcId = 790041,
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F67CC"
        },
        [80140239] = {
          ContentJP = "いやあ、本当に残念だよ！君が主演だと知っていたら、仕事を後回しにしてでも見に行ったのに。ああ、友人に息子を自慢できる機会を逃してしまったよ。",
          DialogueId = 80140239,
          FacialId = {
            [1] = "790041:CM_Smile01"
          },
          GUID = "C89F67F6",
          NextDialogue = 80140240,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F67F6"
        },
        [80140240] = {
          ContentJP = "この劇、次はいつ公演されるんだい？",
          DialogueId = 80140240,
          GUID = "C89F6820",
          NextDialogue = 80140241,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6820"
        },
        [80140241] = {
          Camera = "-45.677734,68.809082,207.492188,0.00004,-15.200093,79.400414,42.689743,178.367188,false,Manual,3.75102",
          ContentJP = "……少なくとも、しばらくは公演されないでしょう。でも、他の劇にも出演しますし、新しい役にも挑戦するつもりです。",
          DialogueId = 80140241,
          FacialId = {
            [1] = "790043:Disappoint01"
          },
          GUID = "C89F684A",
          NextDialogue = 80140242,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Disagree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F684A"
        },
        [80140242] = {
          Camera = "-166.054688,340.296387,174.617188,0.000012,-4.99993,-47.595356,44.120461,100000.0,false,DoNotOverride,2.8",
          ContentJP = "うんうん、それがいい。若者は恐れず何度も試すべきだ！見た目は母親譲りだけど、性格は少し私に似ているね。次はいつ舞台に上がるんだい？",
          DialogueId = 80140242,
          GUID = "C89F6874",
          NextDialogue = 80140243,
          SpeakNpcId = 790041,
          TalkActionId = {
            [1] = "790041:Agree"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F6874"
        },
        [80140243] = {
          Camera = "-66.726562,115.17627,204.988281,0.000037,-18.800034,69.001747,35.000011,134.03508,false,Manual,2.8",
          ContentJP = "その……実はこれこそが今日会いに来た理由なんです。最近、少し困ったことに遭遇しまして……",
          DialogueId = 80140243,
          GUID = "C89F689E",
          NextDialogue = 80140244,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F689E"
        },
        [80140244] = {
          ContentJP = "前回の公演が終わったときに、舞台に乱入した数名の観客とトラブルになってしまい、保安署の耳に届いてしまったんです。それが原因で、劇団に非難の声が数多く寄せられ、僕はしばらく舞台に立つ機会を失ってしまいました。そこで……もし可能であれば、お力添え頂けないかと思いまして……",
          DialogueId = 80140244,
          FacialId = {
            [1] = "790043:Sad01"
          },
          GUID = "C89F68C8",
          NextDialogue = 80140245,
          SpeakNpcId = 790043,
          TalkActionId = {
            [1] = "790043:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F68C8"
        },
        [80140245] = {
          Camera = "425.240234,70.813965,156.609375,0.0,0.0,170.202316,35.0,100000.0,false,DoNotOverride,2.8",
          ContentJP = "は、世の中はそういうものだ！成功を手にした途端、妬ましいネズミどもが匂いを嗅ぎつけて、成功者を溝に引きずり込もうとするんだ。",
          DialogueId = 80140245,
          FacialId = {
            [1] = "790041:CM_Happy01"
          },
          GUID = "C89F68F2",
          LookAt = {
            [1] = "790043:n(790041)"
