          NextDialogue = 80140246,
          Scripts = "MoveTo{ActorId{790041},MoveSpeed{100},TargetPoint{\"P80140245\"}}",
          SpeakNpcId = 790041,
          VoiceName = "voice/$Locale$/inv/Tuosi/002/C89F68F2"
        },
        [80140246] = {
          Camera = "-359.679688,-24.628906,136.578125,0.000006,0.0,28.202164,35.000008,100000.0,false,DoNotOverride,2.8",
          ContentJP = "私もこれまで、数えきれないほどの噂や中傷を受けてきた。安心しなさい。厄介事は私がすべてなんとかしてやろう。君はただ、心置きなく芝居に打ち込んでいればいい。",
          DialogueId = 80140246,
