          DialogueId = 80140356,
          GUID = "C89F7B28",
          IsBlack = 1,
          SpeakNpcId = 790036,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7B28"
        },
        [80140357] = {
          ContentJP = "僕は凶暴な獣。命令のままに、獲物を引き裂く。",
          DialogueId = 80140357,
          Duration = 4,
          GUID = "C89F7B52",
          NextDialogue = 80140358,
          VoiceName = "voice/$Locale$/inv/Tuosi/003/C89F7B52"
        },
