          SpeakNpcId = 790026,
          TalkActionId = {
            [1] = "790026:Think_Start"
          },
          ToFinalCameraBlendTime = 35,
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8404"
        },
        [80140411] = {
          ContentJP = "団長が言ってたじゃん、『雨の日』だって。",
          DialogueId = 80140411,
          GUID = "C89F842E",
          NextDialogue = 80140412,
          SpeakNpcId = 790027,
          TalkActionId = {
            [1] = "790027:Explain01_Start",
            [2] = "790026:Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F842E"
        },
        [80140412] = {
          ContentJP = "『雨の日』って、それほど人気じゃないよね？名声もそんなに立たないんじゃ……ああ、もう一度『雪国の幼子』を演じたいな。あの劇、アイスレイク城ですごく人気だったよね……",
          DialogueId = 80140412,
          GUID = "C89F8458",
          NextDialogue = 80140413,
          SpeakNpcId = 790026,
          TalkActionId = {
            [1] = "790026:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F8458"
        },
        [80140413] = {
          ContentJP = "そうそう！僕も無名の妖精、もう一度演じたい！あの役、すごく自信があるんだ。歌は多くて難しいけど、最後まで演じきった時の達成感が最高だったな。",
          DialogueId = 80140413,
          GUID = "C89F8482",
          NextDialogue = 80140414,
          Scripts = [[
