          TurnTo = {
            [1] = "790027:p(90)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F867A"
        },
        [80140426] = {
          ContentJP = "その後、僕は何度も自分に聞いたんだ――彼の行為は本当に「悪」なのか？間違っていたのは、「カロンは舞台に上がれない」という規則を破ったパシファルなのか、それとも規則自体なのか……",
          DialogueId = 80140426,
          GUID = "C89F86A4",
          LookAt = {
            [1] = "790027:n(790026)"
          },
          NextDialogue = 80140427,
          SpeakNpcId = 790027,
          TurnTo = {
            [1] = "790027:n(790026)"
          },
          VoiceName = "voice/$Locale$/inv/Tuosi/004/C89F86A4"
        },
        [80140427] = {
          ContentJP = "僕たちが舞台に立つ理由――それは<H>至高の芸術</>のためだ……",
