        },
        [80150325] = {
          Camera = "-167.373047,41.786133,148.665527,0.000146,-6.203799,-14.629342,35.0,245.243332,false,Manual,5.0",
          ContentJP = "焦って働き続けるより、いつ前に進むか、いつ立ち止まるかを自分で決めて、自由に生きてみたら？その曲をマスターすれば、{性别:君|あなた}も自分の「リズム」を見つけられると思うよ。",
          DialogueId = 80150325,
          GUID = "C8A5DEB2",
