        },
        [80160101] = {
          Camera = "151.585999,-190.824707,95.898872,0.000003,1.80011,-153.390167,39.474983,223.616684,false,Manual,2.8",
          ContentJP = "確かに静かな場所だ。",
          DialogueId = 80160101,
          Duration = 1,
          GUID = "C8AC2292",
          NextDialogue = 80160102,
          Scripts = "MoveTo{ActorId{790055},TargetPoint{\"Move_320101\"},MoveSpeed{80},Visibility{\"Show\"}}",
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2292"
        },
        [80160102] = {
          Camera = "-31.074158,-13.146484,130.436157,0.000003,0.199305,-130.376617,28.875509,223.616684,false,Manual,2.8",
          ContentJP = "店長、酒を一杯くれ。",
          DialogueId = 80160102,
          Duration = 3,
          GUID = "C8AC22BC",
          LookAt = {
            [1] = "790055:n(790008)"
          },
          NextOptions = {
            [1] = 801601021,
            [2] = 801601022
          },
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC22BC"
        },
        [80160103] = {
          ContentJP = "「アイスレイク城の北、ピアノ、鉄の金床、砂時計がある屋敷。そこには、自家製の飲み物で客をもてなす住人がいる。悪意がなければ、{性别：彼|彼女}は快く歓迎してくれるだろう」",
          DialogueId = 80160103,
          Duration = 3,
          GUID = "C8AC22E6",
          NextDialogue = 80160104,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC22E6"
        },
        [80160104] = {
          ContentJP = "「そこなら、誰にも邪魔されずに、ゆっくり一杯やれる」",
          DialogueId = 80160104,
          Duration = 3,
          GUID = "C8AC2310",
          NextDialogue = 80160105,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2310"
        },
        [80160105] = {
          ContentJP = "アスフォデロスの店主、カミラ・スカーレットがそう言ってたぞ。まさか、嘘だったのか？",
          DialogueId = 80160105,
          Duration = 3,
          GUID = "C8AC233A",
          NextOptions = {
            [1] = 801601071
          },
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk01_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC233A"
        },
        [80160106] = {
          ContentJP = "カミラ・スカーレットのアスフォデロスだろ？私は彼女に紹介されて、ここに来たんだ。",
          DialogueId = 80160106,
          Duration = 3,
          GUID = "C8AC2364",
          NextDialogue = 80160107,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2364"
        },
        [80160107] = {
          ContentJP = "あそこの酒は、帝都にも引けを取らないって評判だ。飲んだくれが群がるのも無理はない。でも今日はな、賑やかなのはゴメンだなんだ。静かな場所で、気兼ねなく二、三杯やりたいんだよ。",
          DialogueId = 80160107,
          Duration = 3,
          GUID = "C8AC238E",
          NextOptions = {
            [1] = 801601071
          },
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC238E"
        },
        [80160108] = {
          ContentJP = "なんだよ、私の肌の色が気に入らねぇのか、それともこの武器が怖ぇのか？まあ、落ち着けって。これはカミラから預かった伝言だ、ほれ。",
          DialogueId = 80160108,
          Duration = 3,
          GUID = "C8AC23B8",
          NextDialogue = 80160109,
          Scripts = "PlayAnimation{_delay{2},ActorId{790055},AnimationId{\"Talk02_Start\"},Duration{1}}",
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC23B8"
        },
        [80160109] = {
          ContentJP = "「この客をしっかりもてなしなさい。報酬は明日、アスフォデロスに取りに来るといいわ」",
          DialogueId = 80160109,
          Duration = 3,
          GUID = "C8AC23E2",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC23E2"
        },
        [80160110] = {
          Camera = "-147.684692,-116.645508,164.708984,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "……正直、あなたの要求にはできるだけ応じたいんですよ。あなたのような大物を怒らせたって、こちらにはなんの得のないのですから。",
          DialogueId = 80160110,
          Duration = 5,
          GUID = "C8AC240C",
          NextDialogue = 80160111,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC240C"
        },
        [80160111] = {
          Camera = "359.205933,-102.777344,311.273438,0.000032,-20.600035,174.999359,25.177044,203.023346,false,Manual,5.70148",
          ContentJP = "余計な連れもいないし、ここに来ることも誰にも言ってない。それに、私の素性を見抜いたってだけでも、ここで一杯やる理由には十分だろ？",
          DialogueId = 80160111,
          Duration = 5,
          FinalCamera = "359.205933,-102.777344,276.765625,0.000032,-20.600035,174.999359,25.177044,203.023346,false,Manual,5.70148",
          GUID = "C8AC2436",
