        [80160113] = {
          Camera = "14.798828,-154.951172,149.396484,0.000091,-9.39922,-174.809311,43.855331,203.023346,false,Manual,5.70148",
          ContentJP = "それに、あなたについての噂には、決まってその炎のような肌のことが語られていますから。",
          DialogueId = 80160113,
          Duration = 3,
          FinalCamera = "14.798828,-154.951172,177.433594,0.000091,-9.39922,-174.809311,43.855331,203.023346,false,Manual,5.70148",
          GUID = "C8AC248A",
          NextDialogue = 80160114,
          SpeakNpcId = 790052,
          ToFinalCameraBlendTime = 15,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC248A"
        },
        [80160114] = {
          ContentJP = "すっかり寂れたとはいえ、アイスレイク城は北方最大の都市ですからね……私はこの街で長く店を構えてきました。あなたの素性を見抜くのは、そう難しいことではありませんよ。",
          DialogueId = 80160114,
          Duration = 5,
          GUID = "C8AC24B4",
          NextDialogue = 80160115,
          SpeakNpcId = 790052,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC24B4"
        },
        [80160115] = {
          Camera = "263.591919,95.413086,166.505859,0.000114,-4.198818,-154.60791,49.593163,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "たく、めんどくせぇな。せいぜいチラチラ見られるくらいだと思ってたのによ、こんな閑散とした酒場でも一発でバレちまうとはな。",
          DialogueId = 80160115,
          Duration = 3,
          GUID = "C8AC24DE",
          NextDialogue = 80160116,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC24DE"
        },
        [80160116] = {
          Camera = "-318.082764,-391.271484,146.335938,0.000113,-0.998813,54.392494,49.593163,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "典獄様……囚人との付き合いが長すぎて、世情に疎くなられたようですね。こんな時間に客が一人しかいない酒場なんて、本来ならとっくに潰れていますよ。",
          DialogueId = 80160116,
          Duration = 3,
          GUID = "C8AC2508",
          NextDialogue = 80160117,
          Scripts = [[
SEQ{
CameraMoveTo{_delay{3},TargetPosition{"-46.92395,-890.245117,476.808594,0.000107,-12.998778,134.186493,25.505644,451.476898,false,DoNotOverride,10.496961"},duration{0}},
CameraMoveTo{TargetPosition{"-46.92395,-890.245117,476.808594,0.000113,-11.398554,-178.21524,25.505644,451.476898,false,DoNotOverride,10.496961"},duration{40}}
}]],
          SpeakNpcId = 790052,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2508"
        },
        [80160117] = {
          ContentJP = "ほら、入口で何人も様子をうかがっているでしょう？あなたの素性に気づいたのは、私だけじゃないようですね。……本来ならば、私一人でお相手したいところですが、「帝都の役人が酒場を占拠している」なんて噂話までは、さすがに私にも止められません。",
          DialogueId = 80160117,
          Duration = 5,
          GUID = "C8AC2532",
          NextDialogue = 80160118,
          SpeakNpcId = 790052,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2532"
        },
        [80160118] = {
          Camera = "393.698364,122.831055,270.308594,0.000183,-14.198112,-159.790924,28.136471,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "確かに、お前の言うとおりだ。ここで行方を知られるのは、私の本意じゃねぇ。忠告には感謝しとく……もっとも、お前の目的はそれだけじゃないんだろ。",
          DialogueId = 80160118,
          Duration = 3,
          FinalCamera = "378.453979,117.220703,266.197266,0.000183,-14.198112,-159.790924,28.136471,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC255C",
          NextDialogue = 80160119,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk02_Start"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC255C"
        },
        [80160119] = {
          Camera = "-65.366943,-360.875,145.677734,0.000188,-1.99826,138.407349,28.136471,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "ヘルファイアは酒場のホールにある機械仕掛けの歯車を一瞥した。どうやら、そのからくりの奥に秘密が隠されていることに気づいたらしい。",
          DialogueId = 80160119,
          Duration = 3,
          GUID = "C8AC2586",
          LookAt = {
            [1] = "790055:p(Look_H)"
          },
          NextDialogue = 80160120,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2586"
        },
        [80160120] = {
          Camera = "-75.942627,-56.601562,151.488281,0.000211,-2.598238,-139.994705,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "そこに隠しもんがあるんだろ。こんな目立つ場所に仕掛けを置くとは……その度胸、驚いたぞ。",
          DialogueId = 80160120,
          Duration = 3,
          GUID = "C8AC25B0",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160121,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC25B0"
        },
        [80160121] = {
          ContentJP = "それとも、お前は私が思ってる以上にやり手なのかもな。ここで酒を飲み続けるためか、あるいはこの街で無事に暮らすためか……みんな、お前のために口をつぐんでるってわけだ。",
          DialogueId = 80160121,
          Duration = 3,
          GUID = "C8AC25DA",
          NextDialogue = 80160122,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC25DA"
        },
        [80160122] = {
          Camera = "-59.147827,-133.68457,134.808594,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "ふふ……お褒めに預かり光栄です。でも私は、税金を滞納する勇気すらない、ただの酒場の店主ですよ。それに……誰だって、秘密の一つや二つくらい抱えているものでしょう？",
          DialogueId = 80160122,
          Duration = 5,
          FacialId = {
            [1] = "790052:Smile01"
          },
          FinalCamera = "-46.137329,-99.043945,142.054688,0.000211,8.401542,69.408882,35.0,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC2604",
          NextDialogue = 80160123,
          SpeakNpcId = 790052,
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2604"
        },
        [80160123] = {
          ContentJP = "それに、「秘密」は必ずしも鋭い刃になるとは限りません。たとえば、三代にわたって受け継がれてきたハムの秘伝レシピ――そんなものだって、立派な秘密です。今お出ししていないのは、あなたのお口に合うか自信がないからかもしれませんよ。",
          DialogueId = 80160123,
          Duration = 5,
          GUID = "C8AC262E",
          NextDialogue = 80160124,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC262E"
        },
        [80160124] = {
          Camera = "-86.051514,-78.273438,146.841797,0.000205,-1.598749,-143.392212,35.0,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "へぇ、面白いな……捜索の腕が立つ部下から、似たような冗談を聞いたことがあるぜ。",
          DialogueId = 80160124,
          Duration = 3,
          GUID = "C8AC2658",
          NextDialogue = 80160125,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Confident_Start",
            [2] = "790052:Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2658"
        },
        [80160125] = {
          ContentJP = "まあ、そう緊張するな。",
          DialogueId = 80160125,
          Duration = 3,
          GUID = "C8AC2682",
          NextDialogue = 80160126,
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2682"
        },
        [80160126] = {
          Camera = "279.85791,105.764648,170.447266,0.000227,-3.998898,-152.592499,68.94529,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "ここはお前のアスフォデロス<Default note=\"text:アスフォデロス\">縄張り</>であって、法廷でも皇立監獄でもない。白状剤を飲ませたりしないから安心しな。",
          DialogueId = 80160126,
          Duration = 3,
          GUID = "C8AC26AC",
          NextDialogue = 80160127,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC26AC"
        },
        [80160127] = {
          ContentJP = "私は私なりの事情があってここに来た。お前はここでお前なりの生き方がある。……たかが「ハムの秘伝レシピ」に、これ以上時間を費やす必要はないよな。",
          DialogueId = 80160127,
          Duration = 3,
          GUID = "C8AC26D6",
          NextDialogue = 80160128,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC26D6"
        },
        [80160128] = {
          ContentJP = "話はもう済んだしな。これ以上、商売の邪魔はしねぇよ。",
          DialogueId = 80160128,
          GUID = "C8AC2700",
          NextDialogue = 80160129,
          Scripts = [[
SEQ{
LookAt{_delay{1},LookAtDescription{"790055:n(790055)"}},
TurnTo{TurnToDescription{"790055:p(-180)"}},
MoveTo{ActorId{790055},TargetPoint{"Move_H"},MoveSpeed{80},Visibility{"Show"}}
}]],
          SpeakNpcId = 790055,
          TalkActionId = {
            [1] = "790055:Confident_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2700"
        },
        [80160129] = {
          Camera = "-105.736328,-382.012695,149.125,0.000248,-3.398559,147.008057,39.565411,252.247864,false,Manual,2.892425",
          ContentJP = "私がわざわざお前の秘密に触れた理由、気になるか？",
          DialogueId = 80160129,
          Duration = 3,
          GUID = "C8AC272A",
          NextDialogue = 80160130,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC272A"
        },
        [80160130] = {
          ContentJP = "悪気があったわけじゃない。「職業病」とでも思ってくれればいい――目の前でうろつく嘘や隠し事を見て見ぬふりできない性でね。",
          DialogueId = 80160130,
          Duration = 5,
          GUID = "C8AC2754",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160131,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2754"
        },
        [80160131] = {
          ContentJP = "アイスレイク城最高の酒場で、一杯やれないってのは残念だが……これで失礼させてもらうよ。",
          DialogueId = 80160131,
          Duration = 3,
          GUID = "C8AC277E",
          LookAt = {
            [1] = "790055:n(790055)"
          },
          NextDialogue = 80160132,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC277E"
        },
        [80160132] = {
          Camera = "-141.847046,-192.130859,169.498047,0.000235,-3.798828,56.604771,47.597221,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "お待ちください。",
          DialogueId = 80160132,
          Duration = 3,
          FacialId = {
            [1] = "790052:None"
          },
          GUID = "C8AC27A8",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160133,
          SpeakNpcId = 790052,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27A8"
        },
        [80160133] = {
          Camera = "204.932251,65.897461,166.253906,0.000237,-5.198696,-153.398605,35.000008,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "まだ何か？",
          DialogueId = 80160133,
          Duration = 3,
          GUID = "C8AC27D2",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160134,
          SpeakNpcId = 790055,
          TurnTo = {
            [1] = "790055:p(75)"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27D2"
        },
        [80160134] = {
          Camera = "-146.874878,-117.574219,164.708984,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "アイスレイク城の北、ピアノ、鉄の金床、砂時計がある屋敷。そこには、自家製の飲み物で客をもてなす住人がいます。悪意さえなければ、{性别：彼|彼女}は快く歓迎してくれるでしょう。",
          DialogueId = 80160134,
          Duration = 5,
          FinalCamera = "-117.245117,-91.633789,163.6875,0.000248,-3.398497,41.200367,42.28323,451.476898,false,DoNotOverride,10.496961",
          GUID = "C8AC27FC",
          NextDialogue = 80160135,
          SpeakNpcId = 790052,
          ToFinalCameraBlendTime = 25,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC27FC"
        },
        [80160135] = {
          ContentJP = "もし話し相手が必要なら、{性别：彼|彼女}はいい人選だと思いますよ……私の依頼書を持っていけば、きっと拒まれないでしょう。",
          DialogueId = 80160135,
          Duration = 3,
          GUID = "C8AC2826",
          NextDialogue = 80160136,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2826"
        },
        [80160136] = {
          Camera = "209.813721,89.859375,159.263672,0.000217,-2.798328,-149.798874,61.554684,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "ありがとう。その洞察力、とても辺境の店主で満足できるとは思えないがね。",
          DialogueId = 80160136,
          Duration = 3,
          GUID = "C8AC2850",
          LookAt = {
            [1] = "790055:n(790052)"
          },
          NextDialogue = 80160137,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC2850"
        },
        [80160137] = {
          Camera = "-246.633789,-309.449219,143.691406,0.00022,0.201757,52.802853,61.554684,451.476898,false,DoNotOverride,10.496961",
          ContentJP = "ですが、現実というのは往々にして、思い通りにはいかないものです。……私もまさか典獄様が、これほど話の通じるお客様だとは思いませんでしたよ。",
          DialogueId = 80160137,
          Duration = 3,
          GUID = "C8AC287A",
          NextDialogue = 80160138,
          SpeakNpcId = 790052,
          TalkActionId = {
            [1] = "790052:Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC287A"
        },
        [80160138] = {
          ContentJP = "訳あって、名は言えん……そうだな、旅の埃をかぶった通りすがりだと思ってくれりゃいい。今はただ、煩わしいことを忘れさせてくれる一杯が欲しいだけだ。",
          DialogueId = 80160138,
          Duration = 5,
          GUID = "C8AC28A4",
          IsBlack = 1,
          SpeakNpcId = 790055,
          VoiceName = "voice/$Locale$/inv/Haier/001/C8AC28A4"
        },
        [80160201] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentJP = "……",
          DialogueId = 80160201,
          GUID = "C8AC32FA",
          NextOptions = {
            [1] = 801602011
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC32FA"
        },
        [80160202] = {
          ContentJP = "構わん。今夜は暇だからな。",
          DialogueId = 80160202,
          GUID = "C8AC3324",
          NextDialogue = 80160203,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3324"
        },
        [80160203] = {
          ContentJP = "この部屋の暮らしぶりを見る限り、ずいぶん長い間住んでいたはずだ。……なのに、モノの配置にはやけに不慣れなんだな。",
          DialogueId = 80160203,
          GUID = "C8AC334E",
          NextDialogue = 80160204,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC334E"
        },
        [80160204] = {
          ContentJP = "まあ、あくまで仮住まいだろうが……今度、一度この家を隅から隅まで掃除してみな。できるなら、ここにあるもん全部、把握しとけ。",
          DialogueId = 80160204,
          GUID = "C8AC3378",
          NextOptions = {
            [1] = 801602041,
            [2] = 801602042
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3378"
        },
        [80160205] = {
          ContentJP = "ま、ただの経験談だ。昔な、私と一番頼りになる仲間でいろんな場所を回ったもんさ。「温もりあふれる我が家」ってやつも、山ほど調べた。……誰がそんなもんに、裏があるなんて思うよ？",
          DialogueId = 80160205,
          GUID = "C8AC33A2",
          NextDialogue = 80160206,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33A2"
        },
        [80160206] = {
          ContentJP = "高級な花を植えた鉢の下に、丁寧に仕込まれた爆弾が埋まってたり……我が子の昔の日記がしまってある引き出しの底に、密輸組織の名簿が貼りつけてあったりな。……土産にもらった酒に、猛毒が仕込まれてたなんてこともあったぜ。",
          DialogueId = 80160206,
          GUID = "C8AC33CC",
          NextOptions = {
            [1] = 801602061,
            [2] = 801602062
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33CC"
        },
        [80160207] = {
          ContentJP = "そんな顔するな。人生の教訓を教えてやっただけだ。……安く貸し出されてる家ってのはな、とくにあんたみてぇなよそ者に貸される物件は、何かと訳アリなことが多いもんだ。",
          DialogueId = 80160207,
          GUID = "C8AC33F6",
          NextDialogue = 80160208,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC33F6"
        },
        [80160208] = {
          ContentJP = "大家ってのは、うまいこと言って、できるだけお前の財布から金を引き出そうとするもんだ。……でもよ、この家で昔何があったのか、どうしてこんなに安いのか――何も知らないよそ者に、話すと思うか？",
          DialogueId = 80160208,
          GUID = "C8AC3420",
          NextOptions = {
            [1] = 801602081,
            [2] = 801602082
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3420"
        },
        [80160209] = {
          ContentJP = "ひとつ忠告しといてやるよ。――「周りのすべてに気を配れ。変化ってのは、いつだって不意打ちで来るもんだからな」",
          DialogueId = 80160209,
          GUID = "C8AC344A",
          NextDialogue = 80160210,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC344A"
        },
        [80160210] = {
          ContentJP = "へっ……口で言うのは簡単だけどな。私自身も、まだ合格にはほど遠いんだ。",
          DialogueId = 80160210,
          GUID = "C8AC3474",
          NextDialogue = 80160211,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3474"
        },
        [80160211] = {
          ContentJP = "あいつはな、私なんかよりずっと細かいとこに気づくのが得意だった。鋭い目と、器用な手を持っててな。爆弾に、名簿に、毒酒に……ありとあらゆるイカれた犯罪の痕跡を、逃さず見つけ出してたよ。",
          DialogueId = 80160211,
          GUID = "C8AC349E",
          NextDialogue = 80160212,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC349E"
        },
        [80160212] = {
          ContentJP = "あいつの捜査から逃れられたものはなかった。",
          DialogueId = 80160212,
          GUID = "C8AC34C8",
          NextDialogue = 80160213,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC34C8"
        },
        [80160213] = {
          ContentJP = "あいつは私にとっちゃ、まさに右腕ってやつだった。例え話ではなく本当の意味でだ……私の手はガラスを溶かし、本を燃やす。だから、細かい証拠を自分の手で確かめることも、脆っこい証物に触れることもできなかったんだ。",
          DialogueId = 80160213,
          GUID = "C8AC34F2",
          NextDialogue = 80160214,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC34F2"
        },
        [80160214] = {
          ContentJP = "あいつは私の「もう一つの手」になってくれた。",
          DialogueId = 80160214,
          GUID = "C8AC351C",
          NextOptions = {
            [1] = 801602141
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC351C"
        },
        [80160215] = {
          ContentJP = "っ……まあ、そんなものだ。",
          DialogueId = 80160215,
          GUID = "C8AC3546",
          NextDialogue = 80160216,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3546"
        },
        [80160216] = {
          ContentJP = "かつて、私たちはそれこそ無二の相棒だった。銃弾が飛び交う中で背中を預け合い、入り組んだ暗号の中から手がかりを拾い上げて、真実にたどり着くために、行き止まりの中でも夜通しもがき続けた。",
          DialogueId = 80160216,
          GUID = "C8AC3570",
          NextDialogue = 80160217,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3570"
        },
        [80160217] = {
          ContentJP = "重要な情報を手に入れるために、あいつは命懸けで危険に飛び込んだ。かろうじて生き延びたが、左耳の聴力を永遠に失ってしまった。……すべては、ある罪人を裁きの場に引きずり出すためだった。",
          DialogueId = 80160217,
          GUID = "C8AC359A",
          NextDialogue = 80160218,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC359A"
        },
        [80160218] = {
          ContentJP = "ずっと、あいつとは最高の相棒でいられるって思ってた。……だけどな、変化ってのは、いつだって不意打ちでやってくるもんだ。",
          DialogueId = 80160218,
          GUID = "C8AC35C4",
          NextDialogue = 80160219,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC35C4"
        },
        [80160219] = {
          ContentJP = "ひとつだけ、秘密を教えてやるよ。……私がここに来たのはな、フォーセイクン同盟とつるんでた裏切り者を引き取るためだ。あいつのせいで、本来なら死ぬはずのなかった兵士たちが、何人も命を落とした。……長年、私についてきた部下まで、な。",
          DialogueId = 80160219,
          GUID = "C8AC35EE",
          NextDialogue = 80160220,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC35EE"
        },
        [80160220] = {
          ContentJP = "本当なら、この手であいつを処刑台に縛り上げるつもりだった。……死んでいった連中一人一人に、懺悔をさせながらな。",
          DialogueId = 80160220,
          GUID = "C8AC3618",
          NextOptions = {
            [1] = 801602201,
            [2] = 801602202
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3618"
        },
        [80160221] = {
          ContentJP = "ヒュペリアのために命を落としたって方がマシだった……だが、あいつは裏切り者になっちまったんだ。",
          DialogueId = 80160221,
          GUID = "C8AC3642",
          NextDialogue = 80160223,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3642"
        },
        [80160222] = {
          ContentJP = "ああ、あいつは私を裏切ったんだ。",
          DialogueId = 80160222,
          GUID = "C8AC366C",
          NextDialogue = 80160223,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC366C"
        },
        [80160223] = {
          ContentJP = "あなたが動くより先に、招かざる客は自分で杯を満たし、そのまま一気に飲み干した。",
          DialogueId = 80160223,
          GUID = "C8AC3696",
          IsBlack = 1,
          NextDialogue = 80160224,
          Scripts = "PlayNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3696"
        },
        [80160224] = {
          ContentJP = "ふぅ……思ったよりずっと強ぇ酒だな。しかも、やけに苦ぇ。……もうすぐ迎える裁きの時ですら、これに比べりゃマシに思えてくるぜ。",
          DialogueId = 80160224,
          GUID = "C8AC36C0",
          NextOptions = {
            [1] = 801602241,
            [2] = 801602242
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC36C0"
        },
        [80160225] = {
          ContentJP = "……いや、私の意思はブレはない。ただ……そうだな、あいつとまた顔を合わせた時に、あのふざけた理屈をどう叩き潰してやるか、まだ考えがまとまってないだけだ。",
          DialogueId = 80160225,
          GUID = "C8AC36EA",
          NextDialogue = 80160226,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC36EA"
        },
        [80160226] = {
          ContentJP = "「長官、私はとっくにあなたにも、この仕事にも心底うんざりしてた。地べたに這いつくばって生きるのが好きなら、勝手にすりゃいい。でも私はもう、こんな泥沼はごめんだ。……光を求めるのは人間の本能だ。あんたみてぇな化け物には分からないんだろうがね」",
          DialogueId = 80160226,
          GUID = "C8AC3714",
          NextDialogue = 80160227,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3714"
        },
        [80160227] = {
          ContentJP = "気づいた時には、あんな言い争いを何度も繰り返してた。……今日みたいな結末になるのも、きっと最初から兆しはあったんだろうな。なのに私は、信頼に目をくらまされていた。",
          DialogueId = 80160227,
          GUID = "C8AC373E",
          NextDialogue = 80160228,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC373E"
        },
        [80160228] = {
          ContentJP = "私はあいつを責めるべきなのか、それとも悼むべきなのか……私はどんな立場であいつを裁こうとしてんるんだ？友か、相棒か、上司か……それとも、ただの裁判官か。",
          DialogueId = 80160228,
          GUID = "C8AC3768",
          NextDialogue = 80160229,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3768"
        },
        [80160229] = {
          ContentJP = "答えを出せるのは……今夜だけだ。",
          DialogueId = 80160229,
          GUID = "C8AC3792",
          NextDialogue = 80160230,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC3792"
        },
        [80160230] = {
          ContentJP = "その前に……その酒、もう一杯ついでくれ。",
          DialogueId = 80160230,
          GUID = "C8AC37BC",
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/002/C8AC37BC"
        },
        [80160301] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentJP = "……もう一杯くれ。",
          DialogueId = 80160301,
          GUID = "C8AC4362",
          NextOptions = {
            [1] = 801603051,
            [2] = 801603052
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4362"
        },
        [80160306] = {
          ContentJP = "見くびるな。大抵のアルコールは、私の体ん中で蒸発しちまう。私を酔わせられる酒なんて、まだこの世にゃ存在しねぇよ。",
          DialogueId = 80160306,
          FacialId = {
            [1] = "93201:Angry01"
          },
          GUID = "C8AC4434",
          NextOptions = {
            [1] = 801603071
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4434"
        },
        [80160307] = {
          ContentJP = "報酬はちゃんと払ったろ？この程度の酒、あと十本は買えるはずだぜ。",
          DialogueId = 80160307,
          FacialId = {
            [1] = "93201:Angry01"
          },
          GUID = "C8AC445E",
          NextOptions = {
            [1] = 801603071
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC445E"
        },
        [80160308] = {
          ContentJP = "……さあね。",
          DialogueId = 80160308,
          FacialId = {
            [1] = "93201:Doubt01"
          },
          GUID = "C8AC4488",
          NextDialogue = 80160309,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4488"
        },
        [80160309] = {
          ContentJP = "あなたは、屋敷にあったすべての菓子を取り出して、ヘルファイアの前に並べた。",
          DialogueId = 80160309,
          GUID = "C8AC44B2",
          IsBlack = 1,
          NextOptions = {
            [1] = 801603091
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC44B2"
        },
        [80160310] = {
          ContentJP = "なら、これだな。",
          DialogueId = 80160310,
          FacialId = {
            [1] = "93201:None"
          },
          GUID = "C8AC44DC",
          NextOptions = {
            [1] = 801603101
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC44DC"
        },
        [80160311] = {
          ContentJP = "いい思い出か……ふっ。",
          DialogueId = 80160311,
          GUID = "C8AC4506",
          NextDialogue = 80160312,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4506"
        },
        [80160312] = {
          ContentJP = "ムラサキツユクサの蜜って聞くと、思い出すのは調香の達人さ――ただし、筋金入りの犯罪者でもあった。ムラサキツユクサを使ってな、「運命の人」って名の、嗅いだら二度と目覚めねぇ香水を作ってた女だよ。",
          DialogueId = 80160312,
          GUID = "C8AC4530",
          NextOptions = {
            [1] = 801603121
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4530"
        },
        [80160313] = {
          ContentJP = "……いや。",
          DialogueId = 80160313,
          GUID = "C8AC455A",
          NextDialogue = 80160314,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC455A"
        },
        [80160314] = {
          ContentJP = "あいつは口先ばっかり達者で、狡猾な小悪党だった。きれいなツラ下げて、頭の中は「愛」だのなんだのってお花畑さ。……でもな、甘く見りゃ、毒まみれの死体になるのがオチだ。",
          DialogueId = 80160314,
          GUID = "C8AC4584",
          NextDialogue = 80160315,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4584"
        },
        [80160315] = {
          ContentJP = "「調香師レベッカ」――ルッカじゃちょっとした有名人だったが、帝国の記録には一切名前が残ってねぇ。",
          DialogueId = 80160315,
          GUID = "C8AC45AE",
          NextDialogue = 80160316,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC45AE"
        },
        [80160316] = {
          ContentJP = "あいつがなぜ故郷を捨てたのかを知る者はいねぇ。いつディズマニアに紛れ込んだのかもな。気づいた時には、まるで一晩で湧いたみてぇに、そこにいたんだ。",
          DialogueId = 80160316,
          GUID = "C8AC45D8",
          NextDialogue = 80160317,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC45D8"
        },
        [80160317] = {
          ContentJP = "帝都の安全を脅かすかもしれねぇもんは、どんな小せぇ芽でも摘み取るべきだ。ましてや、相手が強力な「骸」かもしれねぇとなりゃな。……だから私は、あいつの素性を探り、ここに現れた目的を推し量った。",
          DialogueId = 80160317,
          GUID = "C8AC4602",
          NextDialogue = 80160318,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4602"
        },
        [80160318] = {
          ContentJP = "驚いたぜ。あいつの野心は買いかぶりすぎてたくせに、その厄介さを見くびってた。",
          DialogueId = 80160318,
          GUID = "C8AC462C",
          NextDialogue = 80160319,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC462C"
        },
        [80160319] = {
          ContentJP = "あいつは、帝都の銀行から金をかっさらう気もなけりゃ、パレードで皇帝を暗殺するつもりもなかった。……要塞の防衛図も、命がけで届けられた極秘文書も、あいつにとっちゃ香料の配合をメモるためのただの紙切れだったんだ。",
          DialogueId = 80160319,
          GUID = "C8AC4656",
          NextDialogue = 80160320,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4656"
        },
        [80160320] = {
          ContentJP = "調香師レベッカの目的は、笑っちまうくらい単純だった。……自分に最もふさわしい恋人を見つけること。ただそれだけのために、手段を選ばず、全精力を注ぎ込んでたんだ。",
          DialogueId = 80160320,
          GUID = "C8AC4680",
          NextDialogue = 80160321,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4680"
        }
      }
    end
  },
  {
    MinKey = 80160321,
    MaxKey = 80170322,
    Loader = function()
      return {
        [80160321] = {
          ContentJP = "ディズマニアの闇に巣食う連中にとっちゃ、これ以上都合のいい駒はないだろう。――よそ者で、毒の扱いに長けてて、何よりちょろい口車にすぐ乗る骸だったんだからな。",
          DialogueId = 80160321,
          GUID = "C8AC46AA",
          NextDialogue = 80160322,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46AA"
        },
        [80160322] = {
          ContentJP = "当然の成り行きだ。あいつは陰謀の渦に巻き込まれた。……軽口ばっか叩いてた権力者どもを何人か始末させられたあげく、黒幕にいいように使い捨てられて、牢獄にぶち込まれたってわけだ。",
          DialogueId = 80160322,
          GUID = "C8AC46D4",
          NextDialogue = 80160323,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46D4"
        },
        [80160323] = {
          ContentJP = "そんで私は、真相を洗いざらい暴き出す役目を任された。",
          DialogueId = 80160323,
          GUID = "C8AC46FE",
          NextDialogue = 80160324,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC46FE"
        },
        [80160324] = {
          ContentJP = "尋問の時、あいつに言ったんだ。ヒュペリア法典に従えば、五十年はブチ込まれることになるってな。……でも、私に協力すりゃ、十年の減刑を申請してやるって。",
          DialogueId = 80160324,
          GUID = "C8AC4728",
          NextOptions = {
            [1] = 801603241
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4728"
        },
        [80160325] = {
          ContentJP = "言い終わる前に、あいつは飛びつくように返事しやがった。",
          DialogueId = 80160325,
          GUID = "C8AC4752",
          NextOptions = {
            [1] = 801603251,
            [2] = 801603252
          },
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4752"
        },
        [80160326] = {
          ContentJP = "あんなに捜査に協力的だった罪人は、後にも先にも見たことがない。まるで自分の願いを叶えるために動いてるみたいだったよ……手段も選ばず、力の限りを尽くしてな。",
          DialogueId = 80160326,
          GUID = "C8AC477C",
          NextDialogue = 80160327,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC477C"
        },
        [80160327] = {
          ContentJP = "私はてっきり、利用されたことへの報復かと思った。……けど、あいつはそれを否定した。",
          DialogueId = 80160327,
          GUID = "C8AC47A6",
          NextDialogue = 80160328,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47A6"
        },
        [80160328] = {
          ContentJP = "あいつはこう言った。「調香師の鼻は利くんだよ。……あなたから、私と同じ匂いがしたの」ってな。",
          DialogueId = 80160328,
          GUID = "C8AC47D0",
          NextOptions = {
            [1] = 801603281,
            [2] = 801603282
          },
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk01_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47D0"
        },
        [80160329] = {
          ContentJP = "あんたの言うとおりだ。真相を突き止めた直後、私たちは黒幕の襲撃を受けた。……私は重傷を負って、身動きが取れなくなっちまった。",
          DialogueId = 80160329,
          GUID = "C8AC47FA",
          NextDialogue = 80160330,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC47FA"
        },
        [80160330] = {
          ContentJP = "あいつは逃げなかった。私を殺そうともしなかった。……代わりに、必死で応急手当をしてくれた。でも、私が意識を手放そうとしなかった時、あいつは私に香水を吹きかけたんだ。――自慢の作品、「運命の人」をな。",
          DialogueId = 80160330,
          GUID = "C8AC4824",
          NextDialogue = 80160331,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4824"
        },
        [80160331] = {
          ContentJP = "あのムラサキツユクサの香りで編まれた夢は、そっからずっと、私にまとわりつくようになった。",
          DialogueId = 80160331,
          GUID = "C8AC484E",
          NextDialogue = 80160332,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC484E"
        },
        [80160332] = {
          ContentJP = "……",
          DialogueId = 80160332,
          GUID = "C8AC4878",
          NextDialogue = 80160333,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4878"
        },
        [80160333] = {
          ContentJP = "なぁ、考えたことはあるか？もし、あの「事故」さえなかったら……お前の人生はどんなふうになってたと思う？",
          DialogueId = 80160333,
          GUID = "C8AC48A2",
          NextDialogue = 80160334,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48A2"
        },
        [80160334] = {
          ContentJP = "あの夢の中じゃ……私は赤い肌の骸なんかじゃなかった。親族も、私を聖人みたいに崇めたりはしなかった。母さんの手だって、ちゃんと頬に触れてくれた。",
          DialogueId = 80160334,
          GUID = "C8AC48CC",
          NextDialogue = 80160335,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48CC"
        },
        [80160335] = {
          ContentJP = "久々に思い出したよ……ああ、私にもこんなに白い手があったんだってな。",
          DialogueId = 80160335,
          GUID = "C8AC48F6",
          NextDialogue = 80160336,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC48F6"
        },
        [80160336] = {
          ContentJP = "私は、ただの普通のカロンだった。角も折れちゃいねぇ、人を焼くこともなかった。熱すぎる体温に悩まされて、一年中床に寝転がる必要もなかった。証拠品や書類も、当たり前みてぇにこの手に落ち着き、燃えちまう心配なんて、これっぽっちもなかったんだ。",
          DialogueId = 80160336,
          GUID = "C8AC4920",
          NextDialogue = 80160337,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4920"
        },
        [80160337] = {
          ContentJP = "私は父さんたちと同じように、先祖から託された使命を果たしていた。……相変わらず、闇の中を歩く仕事には違いなかったが、先祖と同じ力を持たなかった私のまわりには、むしろたくさんの人が集まってきたんだ。",
          DialogueId = 80160337,
          GUID = "C8AC494A",
          NextDialogue = 80160338,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC494A"
        },
        [80160338] = {
          ContentJP = "最初のうちはな、ちゃんと分かってた。こんなやたらと「優しい」世界なんざ、ただの甘ったるい餌だって。……腹に一物抱えた連中が、どんな企みを巡らせてるかも分かってたさ。",
          DialogueId = 80160338,
          GUID = "C8AC4974",
          NextDialogue = 80160339,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4974"
        },
        [80160339] = {
          ContentJP = "だけどな、穏やかで満ち足りた日々が、何度も何度も繰り返されるうちに……一年、二年、三年……十年が過ぎても、私が恐れてたことなんざ一度も起きなかった。この夢は、終わりなんか見えないまま、ただひたすら続いていったんだ。",
          DialogueId = 80160339,
          GUID = "C8AC499E",
          NextDialogue = 80160340,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC499E"
        },
        [80160340] = {
          ContentJP = "ああ、そうさ。……こんな「幸せ」な日々が、いつまでも終わらずに続いていくんだ。",
          DialogueId = 80160340,
          GUID = "C8AC49C8",
          NextDialogue = 80160341,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC49C8"
        },
        [80160341] = {
          ContentJP = "まるで終わりのねぇ拷問だったよ。……拷問に耐える苦しみもきついがな、手にした幸せを自分で突き返すってのは、それ以上に胸を抉られるような地獄なんだ。",
          DialogueId = 80160341,
          GUID = "C8AC49F2",
          NextDialogue = 80160342,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC49F2"
        },
        [80160342] = {
          ContentJP = "情けねぇ話だがな……私はいつの間にか、あの狡猾な調香師が仕組んだ幻だってことを忘れちまった。それが当たり前だと思い込んで、何の疑いもなく、受け入れてたんだ。……これが本当の自分の人生だってな。",
          DialogueId = 80160342,
          GUID = "C8AC4A1C",
          NextDialogue = 80160343,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A1C"
        },
        [80160343] = {
          ContentJP = "いつから完全に屈したんだろうな……たぶん、私の誕生日を祝うパーティーでさ。みんなからのカードを一枚ずつ開けてった、あの時かもしれない。",
          DialogueId = 80160343,
          GUID = "C8AC4A46",
          NextDialogue = 80160344,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A46"
        },
        [80160344] = {
          ContentJP = "ああ、間違いない。……今でもはっきり覚えてる。あのカードに書かれてた言葉、一枚残らずな",
          DialogueId = 80160344,
          GUID = "C8AC4A70",
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A70"
        },
        [80160345] = {
          ContentJP = "「私の小さなユキ玉ちゃん――\nあなたが大きくなってくれて、本当に嬉しいわ！\n陛下の栄光にかけて、\nあなたが本当は楽しくないんじゃないかってずっと心配してたの。\nあなたはいつも昼夜問わず働きづめで、\n一分一秒たりとも無駄にするのを恐れてた。\nまるで、休むことが罪でもあるみたいにね。\nでもね、母としてはただ、あなたに自分の人生を思いっきり楽しんでほしいの。\n人生は短いし、たった一度しかないわ。\nどうか、もっと自分を大切にしなさい」",
          DialogueId = 80160345,
          Duration = 30,
          GUID = "C8AC4A9A",
          IsBlack = 1,
          NextDialogue = 80160346,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4A9A"
        },
        [80160346] = {
          ContentJP = "「長官、今年もお疲れさまでした。お誕生日、おめでとうございます。\n……と、かしこまった言葉はここまで。\nこれ以上、コマみたいに回り続けるのはやめてください。\nそれから、仕事を言い訳や逃げ道にするのも、なしです。\n正直言うと、私たちも知り合ってもうすぐ十年になりますが――\n証拠探しのプロである私ですら、あなたが何をそんなに心配してるのか、いまだにわかりません。\nそこまで不幸な人生でもあるまいし！\nもう悩んでばかりいないで、人生を楽しむべきです！\n……あなたは休まなくても平気かもですけど、私は、休まないと死ぬんで！」",
          DialogueId = 80160346,
          Duration = 30,
          GUID = "C8AC4AC4",
          IsBlack = 1,
          NextDialogue = 80160347,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4AC4"
        },
        [80160347] = {
          ContentJP = "「尊敬する典獄様、\n長年にわたりヒュペリアのために尽力してくださったことに、心より感謝申し上げます。\nあなたに、誠実な敬意を捧げます。\nお誕生日おめでとうございます。どうか、この特別な一分一秒を存分にお楽しみください。\nこれからの毎日が、今日のような喜びに満ちたものとなりますように。\n\nなお、今年度の食事補助金、残業手当、そして健康診断のご案内を同封しておりますので、内容をご確認のうえ、お受け取りください」",
          DialogueId = 80160347,
          Duration = 30,
          GUID = "C8AC4AEE",
          IsBlack = 1,
          NextDialogue = 80160348,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4AEE"
        },
        [80160348] = {
          ContentJP = "「親愛なる典獄様へ：\nこの手紙に名前を記せないことを、どうかお許しください。\nただ、私は密かにあなたを見守り続けてきたひとりの崇拝者だと知っていただければ、それだけで構いません。\nきっと、あなたはもう私のことなんて覚えていないでしょう。\nでも私は、悪と戦うあなたの姿を忘れたことはありません。\n自分の理想のために、誰かの期待のために、そして……ちっぽけな私のために（えへへ）、\nすべてを燃やし尽くすあなたは、その名にふさわしく、眩しく熱かった。\nお誕生日、おめでとうございます。\nどうか忘れないでください――あなたは、今手にしているすべてを受け取る権利がある者です。\nだから、もっと胸を張って、この祝福と栄誉に向き合ってください」",
          DialogueId = 80160348,
          Duration = 30,
          GUID = "C8AC4B18",
          IsBlack = 1,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B18"
        },
        [80160349] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentJP = "あの夜からだ……私は、自分がどんな人生を歩んでか、思い返すのをやめた。",
          DialogueId = 80160349,
          GUID = "C8AC4B42",
          NextOptions = {
            [1] = 801603491,
            [2] = 801603492
          },
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Idle_Loop"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B42"
        },
        [80160350] = {
          ContentJP = "私はあの夢の中で、一生を終えた。……家族や仲間たちに囲まれて、穏やかに死んだんだ。これ以上の終わり方なんて、きっとありゃしないよ。",
          DialogueId = 80160350,
          GUID = "C8AC4B6C",
          NextDialogue = 80160351,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B6C"
        },
        [80160351] = {
          ContentJP = "その人生では、裏切りもなけりゃ、思いがけない別れもなかった。……死に目に遭うことも、悔いを残すことも、一度だってなかった。",
          DialogueId = 80160351,
          GUID = "C8AC4B96",
          NextDialogue = 80160352,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4B96"
        },
        [80160352] = {
          ContentJP = "目を開けた時、私は夢の中の死から引き戻されてた。……そこにあったのは、焼け跡の灰と、体を引き裂く痛み、そして頭の中に渦巻く、どうしようもない混乱だけだった。",
          DialogueId = 80160352,
          GUID = "C8AC4BC0",
          NextDialogue = 80160353,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4BC0"
        },
        [80160353] = {
          ContentJP = "残った力でできたのは、片手をかろうじて持ち上げることだけだった――",
          DialogueId = 80160353,
          GUID = "C8AC4BEA",
          NextDialogue = 80160354,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4BEA"
        },
        [80160354] = {
          ContentJP = "私は見た。灰と血にまみれて、震えながら空中へと伸びる、この真っ赤な手を。……あの瞬間、もしかしたら涙を流してたかもしれない。――あいつは迷いもせず、その手をしっかり握ってくれた。",
          DialogueId = 80160354,
          GUID = "C8AC4C14",
          NextDialogue = 80160355,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C14"
        },
        [80160355] = {
          ContentJP = "あの高温に、あいつの肌が耐えられるわけがなかったのにな。……私はてっきり、とっくに逃げたもんだと思ってた。",
          DialogueId = 80160355,
          GUID = "C8AC4C3E",
          NextDialogue = 80160356,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C3E"
        },
        [80160356] = {
          ContentJP = "レベッカは、ずっとそこにいたんだ。",
          DialogueId = 80160356,
          GUID = "C8AC4C68",
          NextOptions = {
            [1] = 801603561,
            [2] = 801603562
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C68"
        },
        [80160357] = {
          ContentJP = "目を覚ました私に、あいつはこう言ったんだ。「私たちは、他人から見れば化け物かもしれない。……でも、化け物にだって、夢を見る権利や夢を叶える権利があるはずよ」",
          DialogueId = 80160357,
          GUID = "C8AC4C92",
          NextDialogue = 80160358,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4C92"
        },
        [80160358] = {
          ContentJP = "あの言葉だけは、どうしても否定したくなかった。……たぶんだからだな。私は、あいつを逃がしてやった。",
          DialogueId = 80160358,
          GUID = "C8AC4CBC",
          NextDialogue = 80160359,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4CBC"
        },
        [80160359] = {
          ContentJP = "私には、もっと重い責任があった。それを捨てちまったら、もっと大勢の者に過酷な運命が降りかかる。……だから私は、夢を見る権利をあいつに譲った。たった一度きり、な。",
          DialogueId = 80160359,
          GUID = "C8AC4CE6",
          NextDialogue = 80160363,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4CE6"
        },
        [80160360] = {
          ContentJP = "目を覚ました私に、あいつはこう言ったんだ。「私たちは、他人から見れば化け物かもしれない。……でも、化け物にだって、夢を見る権利や夢を叶える権利があるはずよ」",
          DialogueId = 80160360,
          GUID = "C8AC4D10",
          NextDialogue = 80160361,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToTalkL_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D10"
        },
        [80160361] = {
          ContentJP = "今なら分かる。……あんなもん、結局は空っぽな満足感にすぎなかったってな。だけど、あの時の私は、「同じもの同士だ」なんていう妙な共感に、どっぷり浸かっちまった。……そして、取り返しのつかない過ちを犯したんだ。",
          DialogueId = 80160361,
          GUID = "C8AC4D3A",
          NextDialogue = 80160362,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D3A"
        },
        [80160362] = {
          ContentJP = "けどよ、そんな言い訳で自分をごまかす気はない。私は、自分の中にある欲望をちゃんと認めた。……正面から向き合ったうえで、二度と手を伸ばさないって決めたんだ。",
          DialogueId = 80160362,
          GUID = "C8AC4D64",
          NextDialogue = 80160363,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D64"
        },
        [80160363] = {
          ContentJP = "自分の罪に言い訳するつもりはない。同じ過ちは繰り返さない。次こそ、あいつに自分の犯した罪の代償を払わせてやるって、私は誓ったんだ。",
          DialogueId = 80160363,
          GUID = "C8AC4D8E",
          NextDialogue = 80160364,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4D8E"
        },
        [80160364] = {
          ContentJP = "……だけどな、今でもムラサキツユクサの香りをかぐと、どんなにイラついてても、不思議と心が落ち着くんだよ。",
          DialogueId = 80160364,
          GUID = "C8AC4DB8",
          NextDialogue = 80160365,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4DB8"
        },
        [80160365] = {
          ContentJP = "いつか、あの夢を忘れられる日が来るかもしれない。「運命の人」って名の幻に作られた、この檻からも抜け出せるかもしれない。……でも、少なくとも今日だけは、この安らぎが、どうしても必要なんだ。",
          DialogueId = 80160365,
          GUID = "C8AC4DE2",
          NextDialogue = 80160366,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4DE2"
        },
        [80160366] = {
          ContentJP = "最後に……",
          DialogueId = 80160366,
          GUID = "C8AC4E0C",
          NextDialogue = 80160367,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E0C"
        },
        [80160367] = {
          ContentJP = "これがあいつの指名手配書だ。もし彼女の足取りを見つけたら、即座に地元の保安署に通報しろ。",
          DialogueId = 80160367,
          GUID = "C8AC4E36",
          NextOptions = {
            [1] = 801603671,
            [2] = 801603672
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E36"
        },
        [80160368] = {
          ContentJP = "もう一杯、頼む。今度はムラサキツユクサの蜜も入れてみてくれないか？",
          DialogueId = 80160368,
          GUID = "C8AC4E60",
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC4E60"
        },
        [80160401] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentJP = "ごちそうさま。",
          DialogueId = 80160401,
          GUID = "C8AC53CA",
          NextDialogue = 80160402,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC53CA"
        },
        [80160402] = {
          ContentJP = "カミラのお前に対する信頼の訳が分かったよ。お前は、誰もが思わず警戒を解いてしまうタイプだ。忍耐力、洞察力、理解力……酒場の店主として、これらは一番褒められるべき美徳だ。",
          DialogueId = 80160402,
          GUID = "C8AC53F4",
          NextDialogue = 80160403,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC53F4"
        },
        [80160403] = {
          ContentJP = "もし、いつかお前が酒場を開くことになったら、ちょくちょく、顔を出すかもな。",
          DialogueId = 80160403,
          GUID = "C8AC541E",
          NextOptions = {
            [1] = 801604031
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC541E"
        },
        [80160404] = {
          ContentJP = "ふっ……「友」か。",
          DialogueId = 80160404,
          FacialId = {
            [1] = "93201:Smile01"
          },
          GUID = "C8AC5448",
          NextDialogue = 80160405,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5448"
        },
        [80160405] = {
          ContentJP = "そうだな、ちょっと休みすぎてしまった。最後の一杯を飲み干したら、そろそろ旧友に会いに行かないとな。",
          DialogueId = 80160405,
          GUID = "C8AC5472",
          NextOptions = {
            [1] = 801604051
          },
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5472"
        },
        [80160406] = {
          ContentJP = "いいや、シンプルなものでいい。",
          DialogueId = 80160406,
          GUID = "C8AC549C",
          NextDialogue = 80160407,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC549C"
        },
        [80160407] = {
          ContentJP = "「インフェルノ」、その口当たりは鋭く、飲み込んだ瞬間、まるで刀を飲み込んだような感覚が広がる。胃に届くと、まるでそこに火をつけられたかのように熱くなる――今思えば、この酒は雪国や凍土にぴったりだ。",
          DialogueId = 80160407,
          GUID = "C8AC54C6",
          NextDialogue = 80160408,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC54C6"
        },
        [80160408] = {
          ContentJP = "これでいい。だが、少し待ってくれ。",
          DialogueId = 80160408,
          GUID = "C8AC54F0",
          NextDialogue = 80160409,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk02_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC54F0"
        },
        [80160409] = {
          ContentJP = "ヘルファイアは慎重に、できるだけ杯に直接触れないようにして、屋根から落ちてきた氷で杯に満たした。そして、あなたに「インフェルノ」を注ぐように促した。",
          DialogueId = 80160409,
          GUID = "C8AC551A",
          IsBlack = 1,
          NextDialogue = 80160410,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC551A"
        },
        [80160410] = {
          ContentJP = "氷はすぐに溶け始め、ヘルファイアは一気にそれを飲み干した。そして一杯、また一杯と……ひたすら飲み続けた。",
          DialogueId = 80160410,
          GUID = "C8AC5544",
          IsBlack = 1,
          NextDialogue = 80160411,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5544"
        },
        [80160411] = {
          ContentJP = "……",
          DialogueId = 80160411,
          FacialId = {
            [1] = "93201:Pain01"
          },
          GUID = "C8AC556E",
          NextDialogue = 80160412,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC556E"
        },
        [80160412] = {
          ContentJP = "…………",
          DialogueId = 80160412,
          GUID = "C8AC5598",
          NextOptions = {
            [1] = 801604121,
            [2] = 801604122
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5598"
        },
        [80160413] = {
          ContentJP = "大げさだな。氷が入った分、度数はそんなにないよ。",
          DialogueId = 80160413,
          FacialId = {
            [1] = "93201:Confident01"
          },
          GUID = "C8AC55C2",
          NextDialogue = 80160414,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC55C2"
        },
        [80160414] = {
          ContentJP = "ただ、氷が手の中で一瞬で溶けちまうのが、ちょっと惜しいだけだ。いくら保とうとしても、結局は蒸気と一緒に、酒と一緒に消えちまう。",
          DialogueId = 80160414,
          GUID = "C8AC55EC",
          NextDialogue = 80160415,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC55EC"
        },
        [80160415] = {
          ContentJP = "長ったらしい言い回しは嫌いだが、氷が溶けて水になるのと、理想が消え去るのは、あまりにも似てると思う。",
          DialogueId = 80160415,
          GUID = "C8AC5616",
          NextDialogue = 80160416,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5616"
        },
        [80160416] = {
          ContentJP = "何年も前のことを思い出す……まだ覚醒してなかった頃、角も折れてなかったし、あの裏切り者もいなかった。あの頃、私たち若者は、学校を出たばかりで、未来と理想に胸を膨らませてた。",
          DialogueId = 80160416,
          GUID = "C8AC5640",
          NextDialogue = 80160417,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Talk03ToThink_Start"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5640"
        },
        [80160417] = {
          ContentJP = "私たちは一番安い酒を飲みながら、同僚たちの乾杯を誘う声は、グラスとグラスがぶつかる音よりも大きく響いてた。",
          DialogueId = 80160417,
          GUID = "C8AC566A",
          NextDialogue = 80160418,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC566A"
        },
        [80160418] = {
          ContentJP = "みんなの顔が同じように真っ赤になって、入社時に誓った熱い言葉が、何度も何度も繰り返された。",
          DialogueId = 80160418,
          GUID = "C8AC5694",
          NextDialogue = 80160419,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5694"
        },
        [80160419] = {
          ContentJP = "「ヒュペリアの正義のために戦い、光のために燃え、誇りのために志を貫く」",
          DialogueId = 80160419,
          GUID = "C8AC56BE",
          NextDialogue = 80160420,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC56BE"
        },
        [80160420] = {
          ContentJP = "「『不屈なる者』、不屈なる魂に敬意を込めて」",
          DialogueId = 80160420,
          GUID = "C8AC56E8",
          NextDialogue = 80160421,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC56E8"
        },
        [80160421] = {
          ContentJP = "当時の同僚はもうほとんど残ってない。私と、エルディンって奴だけが、今生き残ってる唯一の二人だ。",
          DialogueId = 80160421,
          FacialId = {
            [1] = "93201:Sad01"
          },
          GUID = "C8AC5712",
          NextDialogue = 80160422,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5712"
        },
        [80160422] = {
          ContentJP = "だが、まもなくあいつもこの世を去ることになるかもしれない。",
          DialogueId = 80160422,
          GUID = "C8AC573C",
          NextOptions = {
            [1] = 801604221
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC573C"
        },
        [80160423] = {
          ContentJP = "……",
          DialogueId = 80160423,
          FacialId = {
            [1] = "93201:None"
          },
          GUID = "C8AC5766",
          NextDialogue = 80160424,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5766"
        },
        [80160424] = {
          ContentJP = "同じ過ちは、二度と繰り返さない。",
          DialogueId = 80160424,
          GUID = "C8AC5790",
          NextDialogue = 80160425,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5790"
        },
        [80160425] = {
          ContentJP = "私たちは同僚から上司と部下になり、やがて裁く者と裁かれる者になった。歳月は色々なものを変えたが、私はあの日の誓いを守るために、できる限りのことをするつもりだ。",
          DialogueId = 80160425,
          GUID = "C8AC57BA",
          NextDialogue = 80160426,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC57BA"
        },
        [80160426] = {
          ContentJP = "たとえこの道に私一人しかいなくなってもな。",
          DialogueId = 80160426,
          GUID = "C8AC57E4",
          NextOptions = {
            [1] = 801604261
          },
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC57E4"
        },
        [80160427] = {
          ContentJP = "何も言わないな。",
          DialogueId = 80160427,
          GUID = "C8AC580E",
          NextDialogue = 80160428,
          SpeakNpcId = 93201,
          TalkActionId = {
            [1] = "93201:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC580E"
        },
        [80160428] = {
          ContentJP = "私が尊敬する同僚は、あの頃の「不屈なる者」だけだ。罪人に対する私の態度は、決して変わらない。",
          DialogueId = 80160428,
          GUID = "C8AC5838",
          NextDialogue = 80160429,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5838"
        },
        [80160429] = {
          ContentJP = "ヘルファイアは、グラスの中の溶けた氷水を一気に飲み干した。",
          DialogueId = 80160429,
          GUID = "C8AC5862",
          IsBlack = 1,
          NextDialogue = 80160430,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC5862"
        },
        [80160430] = {
          ContentJP = "その罪人が錬金院の者だろうと、皇立士官学校だろうと関係ない。かつての敵であれ味方であれ、同じことだ。",
          DialogueId = 80160430,
          GUID = "C8AC588C",
          NextDialogue = 80160431,
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC588C"
        },
        [80160431] = {
          ContentJP = "これこそが、皇立監獄の典獄としてあるべき姿であり、唯一のやり方だ。",
          DialogueId = 80160431,
          GUID = "C8AC58B6",
          SpeakNpcId = 93201,
          VoiceName = "voice/$Locale$/inv/Haier/003/C8AC58B6"
        },
        [80170001] = {
          ContentJP = "お疲れでしたら、少し座って休まれてはどうでしょう？",
          DialogueId = 80170001,
          GUID = "C8B27ACA",
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B27ACA"
        },
        [80170101] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentJP = "今日はお招きいただきありがとうございます。こうして腰を据えながら友人とお話しするのは、ずいぶん久しぶりでしたの。",
          DialogueId = 80170101,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B28B32",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextDialogue = 80170102,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B32"
        },
        [80170102] = {
          ContentJP = "「久しぶり」って、どれくらい？",
          DialogueId = 80170102,
          GUID = "C8B28B5C",
          NextDialogue = 80170103,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B5C"
        },
        [80170103] = {
          ContentJP = "そうですね。十数年ぶりでしょうか。もっと前となると………数百年前だったかもしれませんね。",
          DialogueId = 80170103,
          GUID = "C8B28B86",
          NextDialogue = 80170104,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28B86"
        },
        [80170104] = {
          ContentJP = "え……？",
          DialogueId = 80170104,
          GUID = "C8B28BB0",
          NextDialogue = 80170105,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28BB0"
        },
        [80170105] = {
          ContentJP = "ふふ、驚かせてしまったようですね。私はあなた方がいる土地――ヒュペリア帝国よりもずっと年上なのですよ。",
          DialogueId = 80170105,
          GUID = "C8B28BDA",
          NextOptions = {
            [1] = 801701051,
            [2] = 801701052
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28BDA"
        },
        [80170106] = {
          ContentJP = "「骸」の魔法は千差万別でね。そのほとんどが先天的な能力か、血筋によるものなのですから、他の人に教えるのは難しいかもしれません。",
          DialogueId = 80170106,
          GUID = "C8B28C04",
          NextDialogue = 80170107,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C04"
        },
        [80170107] = {
          ContentJP = "いや、気にしないで。ちょっと気になっただけ。ただ……",
          DialogueId = 80170107,
          GUID = "C8B28C2E",
          NextDialogue = 80170108,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C2E"
        },
        [80170108] = {
          ContentJP = "まさかニフル夫人がそんなに年長の方だったなんて……こうしてお話しできて光栄です。",
          DialogueId = 80170108,
          GUID = "C8B28C58",
          NextDialogue = 80170109,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C58"
        },
        [80170109] = {
          ContentJP = "そんなにかしこまらないで。友人のように話をしましょう。",
          DialogueId = 80170109,
          GUID = "C8B28C82",
          NextDialogue = 80170110,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28C82"
        },
        [80170110] = {
          ContentJP = "さて、何を話しましょうか？俗離れしてからずいぶん経つので、流行りの話題にはついていけないかもしれません。ですが、異郷や昔話に興味があるのなら、いくつか面白い話を聞かせてあげましょう。",
          DialogueId = 80170110,
          GUID = "C8B28CAC",
          NextOptions = {
            [1] = 801701101
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28CAC"
        },
        [80170111] = {
          ContentJP = "そういえば、前に「ニヴルヘイムの導き手」だって言ってたよね。それって具体的になんのこと？",
          DialogueId = 80170111,
          GUID = "C8B28CD6",
          NextDialogue = 80170112,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28CD6"
        },
        [80170112] = {
          ContentJP = "そうですね……カロン族にまつわる神話を耳にしたことはありますか？",
          DialogueId = 80170112,
          GUID = "C8B28D00",
          NextDialogue = 80170113,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D00"
        },
        [80170113] = {
          ContentJP = "最初、天地は混沌としたニヴルヘイムでした。そして、そのニヴルヘイムから聖樹が生まれ、聖樹は純白の花を咲かせました。その白い花こそが私たちの祖先――最初の生命の女神エムブラを宿したのです。そして、女神によって万物は創造されたのですよ。",
          DialogueId = 80170113,
          GUID = "C8B28D2A",
          NextDialogue = 80170114,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D2A"
        },
        [80170114] = {
          ContentJP = "すべての生きとし生けるものはニヴルヘイムから生まれ、「塵世」と呼ばれる川を漂い歩んだ後、再びニヴルヘイムへと還っていくのです。",
          DialogueId = 80170114,
          GUID = "C8B28D54",
          NextDialogue = 80170115,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D54"
        },
        [80170115] = {
          ContentJP = "導き手の役目は道に迷った魂たちをニヴルヘイムへと導くこと。私の一日のほとんどは亡者の声に耳を傾け、そっと囁き合いながら過ごしているのですよ。",
          DialogueId = 80170115,
          GUID = "C8B28D7E",
          NextDialogue = 80170116,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28D7E"
        },
        [80170116] = {
          ContentJP = "ちょっと怖いね。",
          DialogueId = 80170116,
          GUID = "C8B28DA8",
          NextDialogue = 80170117,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DA8"
        },
        [80170117] = {
          ContentJP = "ふふ、そうですね。ほとんどの方にとって、死というのはとても恐ろしいものですから。",
          DialogueId = 80170117,
          GUID = "C8B28DD2",
          NextOptions = {
            [1] = 801701171
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DD2"
        },
        [80170118] = {
          ContentJP = "そうね……せっかくですし、「死」にまつわる物語を聞かせてあげましょう。とある少女と重い病を患った妹の物語を――",
          DialogueId = 80170118,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B28DFC",
          NextDialogue = 80170119,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28DFC"
        },
        [80170119] = {
          ContentJP = "姉妹は、エリュシオンの貧しい家庭に生まれました。幼い頃に両親を失い、二人は互いに支え合いながら、飢えや寒さに耐えて生きてきました。不幸なことに、ある厳しい冬、妹が不治の病にかかってしまったのです。",
          DialogueId = 80170119,
          GUID = "C8B28E26",
          NextDialogue = 80170120,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E26"
        },
        [80170120] = {
          ContentJP = "少女は妹を救うために、あらゆる医者を訪ね、薬を求めて走り回りました。でも、いくら探しても治療法は見つからず、彼女は絶望の淵に立たされました。そんな時、とある老人から「黄金の血」にまつわる伝説を聞いたのです。",
          DialogueId = 80170120,
          GUID = "C8B28E50",
          NextDialogue = 80170121,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E50"
        },
        [80170121] = {
          ContentJP = "エリュシオンの貴族たちはかつて神から祝福を受けた女性を崇めていたという伝説があります。彼女の血液は、どんな病をも癒し、永遠の若さを手に入れる力が宿っているとされていました。まさに、黄金の川のように貴重なものでした。",
          DialogueId = 80170121,
          GUID = "C8B28E7A",
          NextDialogue = 80170122,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28E7A"
        },
        [80170122] = {
          ContentJP = "多くの貴族たちが、小瓶一本分の血液を得るために、数え切れないほどの黄金を差し出しました。そんな中、戦火がエリュシオンを襲ったのです。『大移住』のさなか、彼女は反乱軍に捕らえられ、それ以来行方知れずとなってしまいました。",
          DialogueId = 80170122,
          GUID = "C8B28EA4",
          NextDialogue = 80170123,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28EA4"
        },
        [80170123] = {
          ContentJP = "妹を救うため、少女は並外れた忍耐力であらゆる場所を探し続けました。そして驚くことに、彼女がまだ生きているという事実を知ったのです。百歳を超えた彼女は、深い森の国――イーザーで暮らしていました。",
          DialogueId = 80170123,
          GUID = "C8B28ECE",
          NextDialogue = 80170124,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28ECE"
        },
        [80170124] = {
          ContentJP = "少女は、重病の妹を連れて山を越え谷を越え、ついに祝福されし女性の前までやってきました。今にも息絶えそうな妹を抱きかかえながら、少女は涙を流して女性に奇跡の血を分けてほしいと懇願しました。",
          DialogueId = 80170124,
          GUID = "C8B28EF8",
          NextDialogue = 80170125,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28EF8"
        },
        [80170125] = {
          ContentJP = "しかし、「神に祝福された黄金の血」などというものは、貪欲な貴族たちが自らの悪行を美化するためにでっち上げた虚言に過ぎませんでした。女性は確かに癒しの魔法を持っていましたが、そのせいで囚われの身となり、数々の苦難を乗り越えてようやくエリュシオンから逃げ延びたのです。",
          DialogueId = 80170125,
          GUID = "C8B28F22",
          NextDialogue = 80170126,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F22"
        },
        [80170126] = {
          ContentJP = "再び災いを招かないため、彼女は二度と癒しの力を使わないと、心に決めていました。",
          DialogueId = 80170126,
          GUID = "C8B28F4C",
          NextDialogue = 80170127,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F4C"
        },
        [80170127] = {
          ContentJP = "それじゃあ少女の努力は無駄に……",
          DialogueId = 80170127,
          GUID = "C8B28F76",
          NextDialogue = 80170128,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28F76"
        },
        [80170128] = {
          ContentJP = "いや、こうして話してくれたってことは、きっとまだ終わりじゃないんだよね？",
          DialogueId = 80170128,
          GUID = "C8B28FA0",
          NextDialogue = 80170129,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FA0"
        },
        [80170129] = {
          ContentJP = "ふふ、当たりです――最終的に、女性は少女の願いを聞き入れることにしたのです。",
          DialogueId = 80170129,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B28FCA",
          NextDialogue = 80170130,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FCA"
        },
        [80170130] = {
          ContentJP = "どうして？",
          DialogueId = 80170130,
          GUID = "C8B28FF4",
          NextDialogue = 80170131,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B28FF4"
        },
        [80170131] = {
          ContentJP = "実際のところ、彼女は過去に二度、自分の血で他人を癒そうとしたことがありました。一度目は親友を、二度目は彼女自身の娘を――",
          DialogueId = 80170131,
          GUID = "C8B2901E",
          NextDialogue = 80170132,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2901E"
        },
        [80170132] = {
          ContentJP = "彼女の親友は勇敢な戦士でしたが、戦場で致命傷を負ってしまいました。彼女の娘は名高い学者で、生涯を全うしてその寿命の終わりを迎えていました。",
          DialogueId = 80170132,
          GUID = "C8B29048",
          NextDialogue = 80170133,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29048"
        },
        [80170133] = {
          ContentJP = "状況が異なるとはいえ、二人とも彼女の血で命を延ばすことを頑なに拒んだのです。「そんな方法で長生きしたくない」――それが二人の最期の言葉でした。",
          DialogueId = 80170133,
          GUID = "C8B29072",
          NextDialogue = 80170134,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29072"
        },
        [80170134] = {
          ContentJP = "少女の悲しみと悔しさに満ちた表情に、女性はかつての自分を思い出しました。閉じ込めていたはずの記憶が、疑問と後悔が、ふと蘇ったのです――",
          DialogueId = 80170134,
          GUID = "C8B2909C",
          NextDialogue = 80170135,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2909C"
        },
        [80170135] = {
          ContentJP = "もしも、親友と娘を助けていたら――自分が選ばなかった道の先には、どんな結末が待っていたのだろう？",
          DialogueId = 80170135,
          GUID = "C8B290C6",
          NextDialogue = 80170136,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B290C6"
        },
        [80170136] = {
          ContentJP = "彼女はその答えを知りたかった。そして、腕の皮膚を裂き、血をその姉妹に分け与えることにしたのです。",
          DialogueId = 80170136,
          GUID = "C8B290F0",
          NextDialogue = 80170137,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B290F0"
        },
        [80170137] = {
          ContentJP = "虫の息だった妹は、「黄金の血」を飲んですぐに意識を取り戻しました。",
          DialogueId = 80170137,
          GUID = "C8B2911A",
          NextOptions = {
            [1] = 801701371,
            [2] = 801701372
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2911A"
        },
        [80170138] = {
          ContentJP = "あなたは優しい子ですね……でも、「黄金の血」の奇跡など、所詮は人々の勝手な幻想に過ぎないのですよ。",
          DialogueId = 80170138,
          GUID = "C8B29144",
          NextDialogue = 80170140,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29144"
        },
        [80170139] = {
          ContentJP = "ええ。「黄金の血」の奇跡など、所詮は人々の勝手な幻想に過ぎないのですよ。",
          DialogueId = 80170139,
          GUID = "C8B2916E",
          NextDialogue = 80170140,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2916E"
        },
        [80170140] = {
          ContentJP = "彼女の血液には確かに特別な力がありましたが、病を癒したり、肉体の時間を止めることはできません。生命を「繋ぎ止める」ことはできても、本当の意味で救われることはなかったのです。",
          DialogueId = 80170140,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B29198",
          NextDialogue = 80170141,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29198"
        },
        [80170141] = {
          ContentJP = "それはまるで琥珀に閉じ込められた虫のように――朽ち果てることはありませんが、果たしてそれは「生きている」と言えるのでしょうか？",
          DialogueId = 80170141,
          GUID = "C8B291C2",
          NextDialogue = 80170142,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B291C2"
        },
        [80170142] = {
          ContentJP = "血を飲んだことで、少女は命を取り留めましたが、その身体は相変わらず病に蝕まれたまま……",
          DialogueId = 80170142,
          GUID = "C8B291EC",
          NextDialogue = 80170143,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B291EC"
        },
        [80170143] = {
          ContentJP = "日が経つにつれ、床に臥す時間が増え、水を飲む力さえないほど衰弱していました。味覚を失い、視力も低下し、更には姉の声も次第に聞こえなくなっていきました。",
          DialogueId = 80170143,
          GUID = "C8B29216",
          NextDialogue = 80170144,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29216"
        },
        [80170144] = {
          ContentJP = "少女は妹を看病するため、時間の融通が利く日雇いの仕事を選びました。しかし、二人分の生活費を稼ぐには、誰もやりたがらない、過酷で辛い仕事をする他ありませんでした。",
          DialogueId = 80170144,
          GUID = "C8B29240",
          NextDialogue = 80170145,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29240"
        },
        [80170145] = {
          ContentJP = "彼女の意志は強く、掴み取った「奇跡」必死に守り続けました。しかし、そのか細い身体にとって、過酷な労働は苦でしかなく――毎日、倒れないよう踏ん張るので精一杯でした。",
          DialogueId = 80170145,
          GUID = "C8B2926A",
          NextOptions = {
            [1] = 801701451
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2926A"
        },
        [80170146] = {
          ContentJP = "少女の妹は、自ら命を絶ちました。最後の力をふり絞り、姉が血のにじむような努力の末に手に入れた「奇跡」の小瓶を地面に叩きつけたのです。",
          DialogueId = 80170146,
          GUID = "C8B29294",
          NextDialogue = 80170147,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29294"
        },
        [80170147] = {
          ContentJP = "彼女は気付いたのでしょう。この「奇跡」は、姉妹にとって重い枷でしかないことに。",
          DialogueId = 80170147,
          GUID = "C8B292BE",
          NextDialogue = 80170148,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B292BE"
        },
        [80170148] = {
          ContentJP = "私は彼女の魂をニヴルヘイムへと送り届けました。その時、彼女なんて言ったと思う？",
          DialogueId = 80170148,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B292E8",
          NextDialogue = 80170149,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B292E8"
        },
        [80170149] = {
          ContentJP = "その表情からして、きっと優しい言葉なんでしょ。「ありがとう」とか？",
          DialogueId = 80170149,
          GUID = "C8B29312",
          NextDialogue = 80170150,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29312"
        },
        [80170150] = {
          ContentJP = "……何度も言い当てられると、問題を出すこちらが恥ずかしくなってしまいますね。その通りです。",
          DialogueId = 80170150,
          GUID = "C8B2933C",
          NextDialogue = 80170151,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2933C"
        },
        [80170151] = {
          ContentJP = "彼女は、姉にも、あの女性にも感謝していました。苦しい最期を迎えたにも関わらず、自分の死を穏やかに受け入れたのです。",
          DialogueId = 80170151,
          GUID = "C8B29366",
          NextDialogue = 80170152,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29366"
        },
        [80170152] = {
          ContentJP = "それを聞いて、少女は涙を流しながら何度も謝りました。そして、川の流れに乗って小さくなる骨箱に向かって、静かに「ありがとう」と呟いたのです。",
          DialogueId = 80170152,
          GUID = "C8B29390",
          NextDialogue = 80170153,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29390"
        },
        [80170153] = {
          ContentJP = "その後、少女はイーザーに定住し、優れた医者になりました。新しい家庭を築いた後、彼女は再び女性を尋ね、幸せな生活を送っていると伝えました。",
          DialogueId = 80170153,
          GUID = "C8B293BA",
          NextDialogue = 80170154,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B293BA"
        },
        [80170154] = {
          ContentJP = "その瞬間、女性はようやく理解しました。なぜ親友と娘が「奇跡」を拒んだのかを――",
          DialogueId = 80170154,
          GUID = "C8B293E4",
          NextDialogue = 80170155,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B293E4"
        },
        [80170155] = {
          ContentJP = "死は決して生命の敵ではありません。時にそれは優しさとなり、静かな解放をもたらすのです。まるで花が実を結ぶために、静かにその花びらを落とすように――終わりとは、新たな始まりでもあるのですから。",
          DialogueId = 80170155,
          GUID = "C8B2940E",
          NextDialogue = 80170156,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2940E"
        },
        [80170156] = {
          ContentJP = "頑なに死に抗うことは、逆に人の歩みを留めさせ、命を美しさを見逃すことになるでしょう。",
          DialogueId = 80170156,
          GUID = "C8B29438",
          NextOptions = {
            [1] = 801701561,
            [2] = 801701562
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29438"
        },
        [80170157] = {
          ContentJP = "とても心強い答えですね。",
          DialogueId = 80170157,
          GUID = "C8B29462",
          NextDialogue = 80170159,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B29462"
        },
        [80170158] = {
          ContentJP = "とても勇敢な答えですね。",
          DialogueId = 80170158,
          GUID = "C8B2948C",
          NextDialogue = 80170159,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B2948C"
        },
        [80170159] = {
          ContentJP = "とはいえ、この物語で語られているのはあの女性の考えに過ぎません。あまり深く考えず、あなた自身の答えを探して見てください。",
          DialogueId = 80170159,
          GUID = "C8B294B6",
          NextDialogue = 80170160,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B294B6"
        },
        [80170160] = {
          ContentJP = "あなたならどんな選択をしても、自我を保ち、幻想に囚われず、正しい道を見つけ出せると信じています。",
          DialogueId = 80170160,
          GUID = "C8B294E0",
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/001/C8B294E0"
        },
        [80170201] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentJP = "あら、{性别:坊や|お嬢さん}。ずいぶんお疲れのようね？",
          DialogueId = 80170201,
          GUID = "C8B29B9A",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801702011,
            [2] = 801702012
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29B9A"
        },
        [80170202] = {
          ContentJP = "故郷を離れてから、いろんなことを経験してきた。もちろん、後悔したことも多い。時々すごく無力感に襲われるんだ……どれほど頑張っても無駄な気がして……",
          DialogueId = 80170202,
          GUID = "C8B29BC4",
          NextDialogue = 80170203,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29BC4"
        },
        [80170203] = {
          ContentJP = "先輩として、何かアドバイスとかありますか？",
          DialogueId = 80170203,
          GUID = "C8B29BEE",
          NextDialogue = 80170204,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29BEE"
        },
        [80170204] = {
          ContentJP = "そうね……それじゃあ、もう一つ物語を聞かせてあげましょうか。",
          DialogueId = 80170204,
          GUID = "C8B29C18",
          NextDialogue = 80170205,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C18"
        },
        [80170205] = {
          ContentJP = "これは、とある青年と少女のお話――希望と勇気、そして未来に関する物語です。",
          DialogueId = 80170205,
          GUID = "C8B29C42",
          NextDialogue = 80170206,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C42"
        },
        [80170206] = {
          ContentJP = "千年前、この大陸にエリュシオンという国しか存在しなかった時代――平民の青年と貴族の少女がいました。",
          DialogueId = 80170206,
          GUID = "C8B29C6C",
          NextDialogue = 80170207,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C6C"
        },
        [80170207] = {
          ContentJP = "平民出身の青年は幼い頃から読書が大好きで、とりわけ歴史や神話の研究に夢中でした。彼は若くして豊かな知識を身につけ、周りからは優れた学者になることを期待されていました。",
          DialogueId = 80170207,
          GUID = "C8B29C96",
          NextDialogue = 80170208,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29C96"
        },
        [80170208] = {
          ContentJP = "しかし、本を読み、知識を深めるほど、自分がいる土地には数多くの間違いが存在することに気づいたのです。人々が当たり前だと思い込んでいたことは、決して正しいものではないと、彼は次第に考えるようになりました。",
          DialogueId = 80170208,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B29CC0",
          NextDialogue = 80170209,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29CC0"
        },
        [80170209] = {
          ContentJP = "平民は懸命に働いても生活は苦しいまま。一方で修道士の食卓には、いつだって食べきれないほどの美酒やご馳走が並べられていました。祝福の賛美歌には、いつも異端者として処刑台へと押しやられる無実の民の悲鳴が交わっていました――",
          DialogueId = 80170209,
          GUID = "C8B29CEA",
          NextDialogue = 80170210,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29CEA"
        },
        [80170210] = {
          ContentJP = "その悲鳴の中には、当然「黄金の血」を持つ少女の声も含まれていました。",
          DialogueId = 80170210,
          GUID = "C8B29D14",
          NextDialogue = 80170211,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D14"
        },
        [80170211] = {
          ContentJP = "昼間、彼女は震える手で自らの皮膚を裂き、訪れる人々に血を分け与えました。そして夜になると、牢獄で身を縮め、痛みに涙を流しながら、ひたすら神に祈りを捧げていました。",
          DialogueId = 80170211,
          GUID = "C8B29D3E",
          NextDialogue = 80170212,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D3E"
        },
        [80170212] = {
          ContentJP = "ある日、若き学者は聖堂に命がけで踏み入り、「黄金の血」を求めて集まる人々に向かって、熱意ある演説を行いました。しかし、返ってきたのは、衛兵たちの矛先だけでした。",
          DialogueId = 80170212,
          GUID = "C8B29D68",
          NextDialogue = 80170213,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D68"
        },
        [80170213] = {
          ContentJP = "彼は冷たく薄暗い牢獄に閉じ込められ、そこで偶然、この物語のもう一人の主人公――父親の付き添いとして視察に訪れていた貴族の少女に出会いました。",
          DialogueId = 80170213,
          GUID = "C8B29D92",
          NextDialogue = 80170214,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29D92"
        },
        [80170214] = {
          ContentJP = "少女は乗馬や武術を好み、凛々しくも優しい心の持ち主でした。少女は自分と同い年でありながら道を違えた青年を哀れに思い、罪を認めれば処罰が軽くなると伝え、密かに彼を説得することにしました。",
          DialogueId = 80170214,
          GUID = "C8B29DBC",
          NextDialogue = 80170215,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29DBC"
        },
        [80170215] = {
          ContentJP = "しかし、青年は自分の無実を主張するばかりか、逆に少女に向かって、「早く目を覚ませ」と説得し始めたのです。",
          DialogueId = 80170215,
          GUID = "C8B29DE6",
          NextDialogue = 80170216,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29DE6"
        },
        [80170216] = {
          ContentJP = "彼は少女にこう告げました。人々が崇めている「黄金の血」を持つ子は、貴族の少女の父親に金稼ぎの道具として利用されている哀れな娘だと。",
          DialogueId = 80170216,
          GUID = "C8B29E10",
          NextDialogue = 80170217,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E10"
        },
        [80170217] = {
          ContentJP = "青年の話を聞いた少女は、初めはまったく信じられず、馬鹿げているとさえ感じていました。しかし、必死に語る青年の熱意のこもった瞳を、少女は忘れることができませんでした。",
          DialogueId = 80170217,
          GUID = "C8B29E3A",
          NextDialogue = 80170218,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E3A"
        },
        [80170218] = {
          ContentJP = "その瞳には、嘘が一切ありませんでした。そうして、貴族の少女は真実を求めて最初の一歩を踏み出しました。彼女は父の部屋から鍵を盗み、聖堂の奥深くにある部屋を開けました。そこには、青白く痩せこけた少女が鎖に繋がれていました。",
          DialogueId = 80170218,
          GUID = "C8B29E64",
          NextDialogue = 80170219,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E64"
        },
        [80170219] = {
          ContentJP = "真実を目の当たりにした少女は牢へ戻り、青年の前に立ちました。少女の先ほどとはまるで別人のような表情に、青年は彼女が覚悟を決めたと悟りました。そして、彼は貴族たちの罪状を一つ一つ語り始めたのです。",
          DialogueId = 80170219,
          GUID = "C8B29E8E",
          NextDialogue = 80170220,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29E8E"
        },
        [80170220] = {
          ContentJP = "青年の言葉が鋭い刃のように、少女を取り囲んでいた美しい光景を切り裂き、その裏に隠された血まみれの真実を露わにしました。それからというもの、少女はこれまで気に留めなかった片隅の闇に、ようやく目を向け始めたのです。",
          DialogueId = 80170220,
          GUID = "C8B29EB8",
          NextDialogue = 80170221,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29EB8"
        },
        [80170221] = {
          ContentJP = "彼女は自分が目にした真実を父親に伝え、青年を解放してほしいと懇願しました。しかし、彼女を待ち受けていたのは父による軟禁と監視でした。彼女はようやく、自分の父親こそが、すべての苦痛の共犯者だったことを知ったのです。",
          DialogueId = 80170221,
          GUID = "C8B29EE2",
          NextOptions = {
            [1] = 801702211,
            [2] = 801702212
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29EE2"
        },
        [80170222] = {
          ContentJP = "ええ――彼らも己の無力さを嘆き、あなたのように疲れ果て、抗うことの意味を疑ったことがあったでしょう。それでも、諦めずに前へと進む道を選んだのです。",
          DialogueId = 80170222,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B29F0C",
          NextDialogue = 80170223,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F0C"
        },
        [80170223] = {
          ContentJP = "囚われの身となっても、青年は昼夜を問わず自らの学説を練り上げ、正義と自由に満ちた新しい世界を思い描いていました。",
          DialogueId = 80170223,
          GUID = "C8B29F36",
          NextDialogue = 80170224,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F36"
        },
        [80170224] = {
          ContentJP = "たとえ孤立無援であっても、少女は贅沢や娯楽の誘惑を拒み、貧民の支援をし続けました。同時に、志を同じくする仲間を探し出そうとしていたのです。",
          DialogueId = 80170224,
          GUID = "C8B29F60",
          NextDialogue = 80170225,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F60"
        },
        [80170225] = {
          ContentJP = "初め、彼らの努力は蝶の羽ばたきのように微々たるものでした。でも、それはやがて大きな嵐を巻き起こし、エリュシオンの強固な殻に亀裂を作ったのです。",
          DialogueId = 80170225,
          GUID = "C8B29F8A",
          NextDialogue = 80170226,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29F8A"
        },
        [80170226] = {
          ContentJP = "彼らこそ、歴史に名を刻んだ『大移住』事件の指導者です。彼らは反乱軍を結成し、抑圧されていた貧民を率いてエリュシオンを離れる道を切り開いたのです。",
          DialogueId = 80170226,
          GUID = "C8B29FB4",
          NextDialogue = 80170227,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29FB4"
        },
        [80170227] = {
          ContentJP = "エリュシオンの反乱軍……『大移住』事件……",
          DialogueId = 80170227,
          GUID = "C8B29FDE",
          NextDialogue = 80170228,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B29FDE"
        },
        [80170228] = {
          ContentJP = "本で読んだことがある。でも結局、本当に平等な世の中を実現することはできなかったんだよね？",
          DialogueId = 80170228,
          GUID = "C8B2A008",
          NextDialogue = 80170229,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A008"
        },
        [80170229] = {
          ContentJP = "……ええ。運命というものは本当に残酷なものです。静寂の中に嵐を巻き起こすこともあれば、大波を操って炎を消し去ることだってできる。あなたが言った通り、努力はほとんどの場合、報われないものです。",
          DialogueId = 80170229,
          GUID = "C8B2A032",
          NextDialogue = 80170230,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A032"
        },
        [80170230] = {
          ContentJP = "けれども、あの一瞬の輝きは確かに存在します。そして、それは「記憶」に永遠に刻まれるでしょう。",
          DialogueId = 80170230,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2A05C",
          NextDialogue = 80170231,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A05C"
        },
        [80170231] = {
          ContentJP = "あの大移住は、勇気と自由の光をアトラシア大陸に撒き散らし、偽りの神を暴いた。更には、人々が初めて自分の感情や願望と向き合うようになったきっかけを作ったのです。",
          DialogueId = 80170231,
          GUID = "C8B2A086",
          NextDialogue = 80170232,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A086"
        },
        [80170232] = {
          ContentJP = "何百年経っても、数多くの人が分厚い歴史書からその光を見つけ出し、あの青年と少女が夢見た理想郷を実現するために努力を続けているのです。",
          DialogueId = 80170232,
          GUID = "C8B2A0B0",
          NextDialogue = 80170233,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A0B0"
        },
        [80170233] = {
          ContentJP = "うん……",
          DialogueId = 80170233,
          GUID = "C8B2A0DA",
          NextDialogue = 80170234,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A0DA"
        },
        [80170234] = {
          ContentJP = "先ほど、私にアドバイスを求めていましたが、残念ながら、長い間俗離れした私には具体的な指摘はできません。",
          DialogueId = 80170234,
          GUID = "C8B2A104",
          NextDialogue = 80170235,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A104"
        },
        [80170235] = {
          ContentJP = "ですが、これだけは伝えておきましょう。年が経つほど、永遠に近づくほど、本当に大切なのは「今この瞬間」だと気付くんです。結果がどうであれ、不条理に抗ったという事実は決して変わりませんから。",
          DialogueId = 80170235,
          GUID = "C8B2A12E",
          NextDialogue = 80170236,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A12E"
        },
        [80170236] = {
          ContentJP = "{nickname}、恐れることも迷うこともないわ――あなたには並外れた力があります。きっと、あなたの光を歳月に刻み付けることができるでしょう。",
          DialogueId = 80170236,
          GUID = "C8B2A158",
          NextOptions = {
            [1] = 801702361,
            [2] = 801702362
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A158"
        },
        [80170237] = {
          ContentJP = "ええ、信じていますよ。",
          DialogueId = 80170237,
          FacialId = {
            [1] = "91502:Satisfy01"
          },
          GUID = "C8B2A182",
          NextDialogue = 80170238,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A182"
        },
        [80170238] = {
          ContentJP = "さて……重い話はこれくらいにして。お茶を飲みながら、このかけがえのない安らぎをゆっくり堪能しましょう。",
          DialogueId = 80170238,
          GUID = "C8B2A1AC",
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/002/C8B2A1AC"
        },
        [80170301] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentJP = "こんにちは。以前お会いした時より、ずいぶん顔色が良くなりましたね。",
          DialogueId = 80170301,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2AC02",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801703011,
            [2] = 801703012
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC02"
        },
        [80170302] = {
          ContentJP = "役に立てたようで嬉しいわ。それで、今回は何のお話を聞きたいのです？",
          DialogueId = 80170302,
          FacialId = {
            [1] = "91502:Happy01"
          },
          GUID = "C8B2AC2C",
          NextDialogue = 80170303,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC2C"
        },
        [80170303] = {
          ContentJP = "ニフル夫人は「過ち」についてどう思う？",
          DialogueId = 80170303,
          GUID = "C8B2AC56",
          NextDialogue = 80170304,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC56"
        },
        [80170304] = {
          ContentJP = "{性别:僕|私}は……様々なことを経験し、多くを失った。だから、{性别:僕|私}のせいなんじゃないかって考える時があるんだ。もしも別の選択をしていたら、いい結果を得られたんじゃないかってね。",
          DialogueId = 80170304,
          GUID = "C8B2AC80",
          NextDialogue = 80170305,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AC80"
        },
        [80170305] = {
          ContentJP = "でも、過去に戻ることはできない。だから、その答えが分かる日は来ない。",
          DialogueId = 80170305,
          GUID = "C8B2ACAA",
          NextDialogue = 80170306,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACAA"
        },
        [80170306] = {
          ContentJP = "あなたの迷いはよくわかるわ。では、今日は「過ち」に関する夫婦の物語をお話しましょう。",
          DialogueId = 80170306,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2ACD4",
          NextDialogue = 80170307,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACD4"
        },
        [80170307] = {
          ContentJP = "夫婦はエリュシオンの郊外に住んでいました。夫は猟師で、妻は街で女中として働いていました。二人はずっと子どもを望んでいましたが、長年の間、その願いは叶いませんでした。",
          DialogueId = 80170307,
          GUID = "C8B2ACFE",
          NextDialogue = 80170308,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ACFE"
        },
        [80170308] = {
          ContentJP = "ある日、猟師が森で狩りをしていると、迷子の子どもに出会いました。その子は全身血だらけで、震えながら泣いていた。そのあまりにも哀れな姿を見て、猟師は迷わず彼女を自分の家に連れて帰ることにしました。",
          DialogueId = 80170308,
          GUID = "C8B2AD28",
          NextDialogue = 80170309,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD28"
        },
        [80170309] = {
          ContentJP = "女中は少女をお風呂に入れました。彼女の身体に傷はなく、ただひどいショックを受けたようでした。何を言っても、彼女はただぼんやりと目を開いているだけで、何も答えようとはしませんでした。",
          DialogueId = 80170309,
          GUID = "C8B2AD52",
          NextDialogue = 80170310,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD52"
        },
        [80170310] = {
          ContentJP = "夫婦はその少女を一時的に家に引き取ることにしました。毎日、心を込めて世話をしていくうちに、少女は徐々に意識を取り戻し、周りに反応をするようになりました。そして、ようやく彼女は口を開いたのです。",
          DialogueId = 80170310,
          GUID = "C8B2AD7C",
          NextDialogue = 80170311,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AD7C"
        },
        [80170311] = {
          ContentJP = "少女は、両親を失ったことを夫婦に話しました。話し合った結果、夫婦は彼女を養子として迎えることを決めました。二人は養女を自分の子どものように大切に育て、少女もまた、非常に素直で優しい子でした。こうして、家族は幸せに暮らしていきました。",
          DialogueId = 80170311,
          GUID = "C8B2ADA6",
          NextOptions = {
            [1] = 801703111
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADA6"
        },
        [80170312] = {
          ContentJP = "表向きはそうでしょう。しかし、少女には恐ろしい秘密が隠されていたのです。",
          DialogueId = 80170312,
          FacialId = {
            [1] = "91502:Unhappy01"
          },
          GUID = "C8B2ADD0",
          NextDialogue = 80170313,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADD0"
        },
        [80170313] = {
          ContentJP = "彼女は異端者の家系に生まれ、家族全員がカロン族の古い神話を信仰していました。そのせいで、彼女の両親は処刑されましたが、彼女だけは特殊な自己治癒力で命拾いしたのです。",
          DialogueId = 80170313,
          GUID = "C8B2ADFA",
          NextDialogue = 80170314,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2ADFA"
        },
        [80170314] = {
          ContentJP = "彼女は指を血まみれにしながら、墓から地上へと逃れ、荒野を駆け抜けて森へと逃げ込んだのです。",
          DialogueId = 80170314,
          GUID = "C8B2AE24",
          NextDialogue = 80170315,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE24"
        },
        [80170315] = {
          ContentJP = "エリュシオンでは、異教の信仰は非常に最も重い罪でした。養父母にこの秘密が知られれば、役人に引き渡さずとも、間違いなく彼女を追い出すでしょう。",
          DialogueId = 80170315,
          GUID = "C8B2AE4E",
          NextDialogue = 80170316,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE4E"
        },
        [80170316] = {
          ContentJP = "やっと取り戻した「家」の温もりを、少女はどうしても失いたくありませんでした。そこで、彼女はこの小さな希望に縋りつきながら、自分の素性を隠すことにしたのです。",
          DialogueId = 80170316,
          GUID = "C8B2AE78",
          NextDialogue = 80170317,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AE78"
        },
        [80170317] = {
          ContentJP = "時が経つにつれて、少女は養父母の愛情に包まれながら健やかに成長していきました。彼女の秘密を知る者はおらず、次第に彼女自身もそのことを忘れていきました。次第に、彼女はこのまま幸せに暮らしていけると心から信じるようになっていました。",
          DialogueId = 80170317,
          GUID = "C8B2AEA2",
          NextDialogue = 80170318,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AEA2"
        },
        [80170318] = {
          ContentJP = "そのため、養母に「街で一緒に働きましょう」と提案された時、彼女は特に深く考えることなく同意しました。せいぜい貴族の屋敷での掃除や洗濯などの下働きで、目立つことはないと彼女は考えていました。",
          DialogueId = 80170318,
          GUID = "C8B2AECC",
          NextDialogue = 80170319,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AECC"
        },
        [80170319] = {
          ContentJP = "けれどある日、養母が掃除中に誤って屋敷のコレクションを壊してしまったのです。屋敷の規則に基づき、養母は鞭打ちの刑を言い渡されました。しかし、母の苦しむ姿を見たくなかった少女は、代わりに罪を被ったのです。",
          DialogueId = 80170319,
          GUID = "C8B2AEF6",
          NextDialogue = 80170320,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AEF6"
        },
        [80170320] = {
          ContentJP = "少女の肌には、見るも無惨な傷痕が残されました。しかし、その傷はほんの数分で尋常ではない速さで塞がったのです。",
          DialogueId = 80170320,
          GUID = "C8B2AF20",
          NextDialogue = 80170321,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF20"
        },
        [80170321] = {
          ContentJP = "この「神跡」はすぐに屋敷の主――『チャリティー』の耳に届きました。彼はすぐさま現場に駆けつけ、少女の心臓めがけて刃を突き立てたました。少女は激しく苦しみ死に絶えたかに思われましたが、数十分後に再び呼吸を取り戻したのです。",
          DialogueId = 80170321,
          GUID = "C8B2AF4A",
          NextDialogue = 80170322,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF4A"
        },
        [80170322] = {
          ContentJP = "『チャリティー』はその少女を屋敷から連れ出し、その素性を調査しました。こうして、彼女が処刑されたはずの異端者の娘だったことが暴かれてしまったのです。",
          DialogueId = 80170322,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2AF74",
          NextDialogue = 80170323,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF74"
        }
      }
    end
  },
  {
    MinKey = 80170323,
    MaxKey = 80180335,
    Loader = function()
      return {
        [80170323] = {
          ContentJP = "殺しても死なない少女を目の当たりにし、彼は最初こそ怒りを覚えたものの、ふと素晴らしい考えが浮かびました。エリュシオンで初めて目にする異能を「神跡」と偽って利用すれば、名声と財産を一気に手に入れられると考えたのです。",
          DialogueId = 80170323,
          GUID = "C8B2AF9E",
          NextDialogue = 80170324,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AF9E"
        },
        [80170324] = {
          ContentJP = "しかし、それを実現するには、少女の正体を隠す必要がありました。そこで彼は少女を監禁し、彼女に新しい身分を与えました。彼女の養母も、密かに処刑されてしまいました。",
          DialogueId = 80170324,
          GUID = "C8B2AFC8",
          NextOptions = {
            [1] = 801703241
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AFC8"
        },
        [80170325] = {
          ContentJP = "少女は酷い罪悪感に苛まれました。家族の温もりを求めるために正体を隠したせいで、優しい養父母をこんな悲劇に巻き込んでしまった――少女は自分を責めました。",
          DialogueId = 80170325,
          GUID = "C8B2AFF2",
          NextDialogue = 80170326,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2AFF2"
        },
        [80170326] = {
          ContentJP = "だからこそ、『大移住』が起こった際に反乱軍によって救出された後も、少女は養父の元へは帰りませんでした。この出会い自体が過ちだったと思っていた上、これ以上養父に迷惑をかけたくなかったのです。",
          DialogueId = 80170326,
          GUID = "C8B2B01C",
          NextDialogue = 80170327,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B01C"
        },
        [80170327] = {
          ContentJP = "それから数十年もの間、彼女は過去への後悔と養父への罪悪感で心を蝕まれていました。ある時、私がエリュシオンを訪れた際に、彼女の代わりに養父を訪ねることにしました。",
          DialogueId = 80170327,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2B046",
          NextDialogue = 80170328,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B046"
        },
        [80170328] = {
          ContentJP = "その時、彼はすでに白髪混じりの年寄りになっていました。長い間、名前を隠してひっそりと暮らしていた彼は、私がその本名を知っていたことにとても驚いた様子でした。",
          DialogueId = 80170328,
          GUID = "C8B2B070",
          NextDialogue = 80170329,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B070"
        },
        [80170329] = {
          ContentJP = "彼女の意向に従い、私は自分の本当の目的を明かさずに、ただ導き手として彼と話をしました。当時の出来事を話題に、昔の記憶を少しずつたどるようにね。",
          DialogueId = 80170329,
          GUID = "C8B2B09A",
          NextDialogue = 80170330,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B09A"
        },
        [80170330] = {
          ContentJP = "老人は当時の出来事をはっきり覚えていました。一晩のうちに妻と娘を失い、自分も指名手配犯となってしまったこと、そして数年間にわたる逃亡生活の苦しみも、何もかも話してくれました。",
          DialogueId = 80170330,
          GUID = "C8B2B0C4",
          NextDialogue = 80170331,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B0C4"
        },
        [80170331] = {
          ContentJP = "けれども意外なことに、彼は養女に迎えたことに後悔はないと言ったのです。",
          DialogueId = 80170331,
          FacialId = {
            [1] = "91502:Shock01"
          },
          GUID = "C8B2B0EE",
          NextDialogue = 80170332,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B0EE"
        },
        [80170332] = {
          ContentJP = "そして、彼は私に小さな箱を手渡しました。中に入っていたは彼の妻の遺灰でした。「導き手の訪れを待っていた。ようやく妻の魂を安らかに旅立たせられるよ」――彼はこう言っていました。",
          DialogueId = 80170332,
          GUID = "C8B2B118",
          NextDialogue = 80170333,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B118"
        },
        [80170333] = {
          ContentJP = "驚きながらも、私は数十年遅れた葬別の儀式を執り行いました。その時、その魂から小さな呟きが聞こえたのです――",
          DialogueId = 80170333,
          GUID = "C8B2B142",
          NextDialogue = 80170334,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B142"
        },
        [80170334] = {
          ContentJP = "それは老人と同じ言葉でした。「私たちの娘になってくれてありがとう」と。",
          DialogueId = 80170334,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2B16C",
          NextDialogue = 80170335,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B16C"
        },
        [80170335] = {
          ContentJP = "老人は私にすべてを教えてくれました。彼らは最初から少女の正体に気付いていたのです。少女の両親が殺害されたあの日、彼らは火を掲げた処刑人たちが密林に踏み込むのをその目で見ていましたから。",
          DialogueId = 80170335,
          GUID = "C8B2B196",
          NextDialogue = 80170336,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B196"
        },
        [80170336] = {
          ContentJP = "翌日、血だらけの少女を見て、彼はすぐにその正体を悟りました。夫婦は事実を知った上で、少女を養女として迎え入れていたのです。",
          DialogueId = 80170336,
          GUID = "C8B2B1C0",
          NextDialogue = 80170337,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B1C0"
        },
        [80170337] = {
          ContentJP = "彼らにとって、少女との出会いは、少女を守り育てることはかけがえのない幸せだったのです。たとえ、危険を伴うとわかっていても――",
          DialogueId = 80170337,
          GUID = "C8B2B1EA",
          NextDialogue = 80170338,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B1EA"
        },
        [80170338] = {
          ContentJP = "老人は更にこう続けました。彼が唯一後悔しているのは、自分に勇気が足りなかったことだと。もしもっと早く妻と娘を連れてエリュシオンを離れていたら、今も家族みんなで幸せに暮らしていられたかもしれない、と。",
          DialogueId = 80170338,
          GUID = "C8B2B214",
          NextDialogue = 80170339,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B214"
        },
        [80170339] = {
          ContentJP = "だから、その後彼は、捏造された罪状を背負うただの猟師から、本物の「異端者」へと変わりました。何十年もの間、彼は密かにエリュシオンの平民たちが国境を越えて逃れる手助けをし続けていたのです。",
          DialogueId = 80170339,
          GUID = "C8B2B23E",
          NextOptions = {
            [1] = 801703391
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B23E"
        },
        [80170340] = {
          ContentJP = "……はっきりとは言わなかったけれど、彼の安らかな表情を見る限り、きっと気付いていたのでしょう。",
          DialogueId = 80170340,
          GUID = "C8B2B268",
          NextDialogue = 80170341,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B268"
        },
        [80170341] = {
          ContentJP = "もう会えないとしても、お互いが元気だってわかっただけで、十分慰めになるんだろうね。",
          DialogueId = 80170341,
          GUID = "C8B2B292",
          NextDialogue = 80170342,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B292"
        },
        [80170342] = {
          ContentJP = "この結末も悪くないと思う。",
          DialogueId = 80170342,
          GUID = "C8B2B2BC",
          NextDialogue = 80170343,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B2BC"
        },
        [80170343] = {
          ContentJP = "そうね。彼の話を聞いているうちに、私もこう思うようになったの――",
          DialogueId = 80170343,
          GUID = "C8B2B2E6",
          NextDialogue = 80170344,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B2E6"
        },
        [80170344] = {
          ContentJP = "人間というのは、生きている限りどうしても過ちを犯してしまうもの。目先のことにとらわれたり、小さな希望に縋りついたり……過ちだとわかってても突き進んでしまうことだってある。",
          DialogueId = 80170344,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2B310",
          NextDialogue = 80170345,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B310"
        },
        [80170345] = {
          ContentJP = "けれども、間違った選択が必ずしも間違った結果をもたらすとは限らないでしょう。その中にある喜怒哀楽は、当事者にしかわからないのですから。",
          DialogueId = 80170345,
          GUID = "C8B2B33A",
          NextDialogue = 80170346,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B33A"
        },
        [80170346] = {
          ContentJP = "過ちそのものよりも大切なのは、私たちにはまだ未来があるということ。",
          DialogueId = 80170346,
          GUID = "C8B2B364",
          NextDialogue = 80170347,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B364"
        },
        [80170347] = {
          ContentJP = "私たちには、それを埋め合わせることも、変えることも、更に大きな意味を与えることもできる。",
          DialogueId = 80170347,
          GUID = "C8B2B38E",
          NextDialogue = 80170348,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B38E"
        },
        [80170348] = {
          ContentJP = "少なくとも、あの老人が昔話をしていた時、その表情は後悔と苦痛ではなく、平穏と幸せに満ちていましたから。",
          DialogueId = 80170348,
          GUID = "C8B2B3B8",
          NextOptions = {
            [1] = 801703481
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B3B8"
        },
        [80170349] = {
          ContentJP = "ありがとう。今日の話もすごくためになったよ。",
          DialogueId = 80170349,
          GUID = "C8B2B3E2",
          NextDialogue = 80170350,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B3E2"
        },
        [80170350] = {
          ContentJP = "ふふ、お礼を言うのはこちらですよ。",
          DialogueId = 80170350,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2B40C",
          NextDialogue = 80170351,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B40C"
        },
        [80170351] = {
          ContentJP = "年のせいか、話が長くなってしまいましたね。こんな年寄りの昔話に付き合ってくれて、ありがとう。",
          DialogueId = 80170351,
          GUID = "C8B2B436",
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/003/C8B2B436"
        },
        [80170401] = {
          Camera = "135.91098,22.045166,124.542297,0.000012,1.800007,-136.994522,35.0,158.845352,false,Manual,3.0",
          ContentJP = "あら、いらっしゃい。今日はどんな話をしましょうか？",
          DialogueId = 80170401,
          FacialId = {
            [1] = "91502:Smile01"
          },
          GUID = "C8B2BC6A",
          LookAt = {
            [1] = "91502:p(18000P1)"
          },
          NextOptions = {
            [1] = 801704011
          },
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BC6A"
        },
        [80170402] = {
          ContentJP = "今日はニフル夫人の昔話が聞きたいな。",
          DialogueId = 80170402,
          GUID = "C8B2BC94",
          NextDialogue = 80170403,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BC94"
        },
        [80170403] = {
          ContentJP = "私の、ですか……あなたほど賢い子なら、もう大方予想がついているんじゃないかしら？",
          DialogueId = 80170403,
          GUID = "C8B2BCBE",
          NextOptions = {
            [1] = 801704031,
            [2] = 801704032
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BCBE"
        },
        [80170404] = {
          ContentJP = "今までの物語は、全部あなた自身の話だよね？",
          DialogueId = 80170404,
          GUID = "C8B2BCE8",
          NextDialogue = 80170405,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BCE8"
        },
        [80170405] = {
          ContentJP = "ええ。",
          DialogueId = 80170405,
          GUID = "C8B2BD12",
          NextDialogue = 80170407,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD12"
        },
        [80170406] = {
          ContentJP = "私の昔話は、すべてこれまでに話した物語に交えていましたのよ。",
          DialogueId = 80170406,
          GUID = "C8B2BD3C",
          NextDialogue = 80170407,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD3C"
        },
        [80170407] = {
          ContentJP = "それらは他人の物語であったと同時に、私の物語でもあったのです。",
          DialogueId = 80170407,
          GUID = "C8B2BD66",
          NextDialogue = 80170408,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD66"
        },
        [80170408] = {
          ContentJP = "私は、異能を持ちながらも他人の苦痛を癒せなかった女性であり、聖堂に囚われ抗う力すらなかった少女であり、そして養父母を地獄へと追い込んだ子ども。",
          DialogueId = 80170408,
          GUID = "C8B2BD90",
          NextDialogue = 80170409,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BD90"
        },
        [80170409] = {
          ContentJP = "うん……でも、ちゃんとすべて話してほしい。今までみたいな傍観者としての視点ではなく、「あなた自身」の、ニフルの物語の主人公としてね。",
          DialogueId = 80170409,
          GUID = "C8B2BDBA",
          NextDialogue = 80170410,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BDBA"
        },
        [80170410] = {
          ContentJP = "……わかりました。そこまで興味があるのなら、私も久しぶりに過去を振返ってみましょう。",
          DialogueId = 80170410,
          GUID = "C8B2BDE4",
          NextDialogue = 80170411,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_AgreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BDE4"
        },
        [80170411] = {
          ContentJP = "私はエリュシオンの出身で、カロンの神話を信奉する家庭に生まれました。",
          DialogueId = 80170411,
          GUID = "C8B2BE0E",
          NextDialogue = 80170412,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE0E"
        },
        [80170412] = {
          ContentJP = "十歳のとき、両親は異端者の罪で処刑され、私も彼らと一緒に死ぬはずでした。しかしその時、私は思いがけず「骸」として覚醒し、不老不死の力を得て、生き延びることができたのです。",
          DialogueId = 80170412,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2BE38",
          NextDialogue = 80170413,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE38"
        },
        [80170413] = {
          ContentJP = "両親を失った私は、ひとり森をさまよい続けました。そんな私を、通りかかった猟師が助けてくれ、そこから私は第二の家を得ることとなりました。",
          DialogueId = 80170413,
          GUID = "C8B2BE62",
          NextDialogue = 80170414,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE62"
        },
        [80170414] = {
          ContentJP = "十八歳の時、私はうっかり自分の正体を暴露してしまい、「チャリティー」に知られ、それ以来「祝福された者」として、棘の冠をかぶることとなりました。",
          DialogueId = 80170414,
          GUID = "C8B2BE8C",
          NextDialogue = 80170415,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BE8C"
        },
        [80170415] = {
          ContentJP = "その後の数年間、私の世界は小さな聖堂だけになりました。「チャリティー」は私の血液を売りさばいて、数えきれないほどの富を手に入れました。",
          DialogueId = 80170415,
          GUID = "C8B2BEB6",
          NextDialogue = 80170416,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BEB6"
        },
        [80170416] = {
          ContentJP = "しかし、二人の勇敢な反逆者が私をその悪夢から救い出してくれました――二つ目の物語の青年と少女は、私の恩人であり、一番の親友であり、私に進むべき道を示してくれる人たちでした。",
          DialogueId = 80170416,
          FacialId = {
            [1] = "91502:Confident01"
          },
          GUID = "C8B2BEE0",
          NextDialogue = 80170417,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BEE0"
        },
        [80170417] = {
          ContentJP = "その後、エリカは北方へ向かう途中の戦闘で命を落とし、レクシスは無事に逃げ延びたものの、理想郷の答えを見つけることなく、最終的に積み重なる書類の中で命を閉ざしました。",
          DialogueId = 80170417,
          GUID = "C8B2BF0A",
          NextDialogue = 80170418,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk02R_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF0A"
        },
        [80170418] = {
          ContentJP = "イーザーでの生活の中で、私は一人の子どもを養子として迎えました。私は初めて育てる立場に立ち、一人としての人生を見届けることができました。",
          DialogueId = 80170418,
          GUID = "C8B2BF34",
          NextDialogue = 80170419,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF34"
        },
        [80170419] = {
          ContentJP = "私は彼女が、懐の中の小さな赤子から、美しく魅力的な少女へ、そして物静かで賢い女性へと成長していく様子を見守りました。彼女の泣き声、初めて話した言葉、初めて暗唱した詩文――どれも忘れたことはありません。",
          DialogueId = 80170419,
          GUID = "C8B2BF5E",
          NextDialogue = 80170420,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF5E"
        },
        [80170420] = {
          ContentJP = "彼女がレクシスと熱心に議論を交わし、また、レクシスの病床で悲しみに涙を流しながら彼の図書館の鍵を受け取った場面もすべて記憶に残っています。",
          DialogueId = 80170420,
          GUID = "C8B2BF88",
          NextDialogue = 80170421,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BF88"
        },
        [80170421] = {
          ContentJP = "彼女の一つ一つの変化に驚き、そして安堵すると同時に、私は気付きました。彼女もまた、限りある命を持つ存在だということを。エリカやレクシスと同じように、永遠に私と共にいることはできないのだと。",
          DialogueId = 80170421,
          GUID = "C8B2BFB2",
          NextDialogue = 80170422,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BFB2"
        },
        [80170422] = {
          ContentJP = "最終的に、彼らは私の元を去りました。最初はその別れに深い悲しみを感じましたが、血を求める姉妹に出会い、また数え切れないほどの生死を見届けるうち、私はようやくこの無常な世界を受け入れることができるようになりました。",
          DialogueId = 80170422,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2BFDC",
          NextDialogue = 80170423,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2BFDC"
        },
        [80170423] = {
          ContentJP = "私は悲しみも喜びも手放し、欲望を捨て去った。この世の苦しみに嘆いたり、憤ったりすることもなくなりました。そして、その後の九百年、私はアトラシア各地を巡り、亡者たちの導き手となったのです。",
          DialogueId = 80170423,
          GUID = "C8B2C006",
          NextDialogue = 80170424,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C006"
        },
        [80170424] = {
          ContentJP = "今、私は一時的にヒュペリアに留まっています。そこには、どこか見覚えのある子どもがいるのです。しかし、争いに加わるつもりも、何かを変えようとも思っていません。ただ、彼女の物語を見守るためだけにここにいます。",
          DialogueId = 80170424,
          GUID = "C8B2C030",
          NextDialogue = 80170425,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C030"
        },
        [80170425] = {
          ContentJP = "きっと、またすぐに旅路に出るわ……「死」が私を迎え入れてくれるその瞬間まで、私はこの世界を彷徨い続けることになるでしょう。",
          DialogueId = 80170425,
          GUID = "C8B2C05A",
          NextDialogue = 80170426,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C05A"
        },
        [80170426] = {
          ContentJP = "――私の物語は以上です。ご満足いただけたかしら？",
          DialogueId = 80170426,
          GUID = "C8B2C084",
          NextOptions = {
            [1] = 801704261
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C084"
        },
        [80170427] = {
          ContentJP = "長寿の力を得る前、それらの「役割」を担う前の「ニフル」は、どんな人だったの？",
          DialogueId = 80170427,
          GUID = "C8B2C0AE",
          NextDialogue = 80170428,
          SpeakNpcId = 790008,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C0AE"
        },
        [80170428] = {
          ContentJP = "……",
          DialogueId = 80170428,
          FacialId = {
            [1] = "91502:Shock01"
          },
          GUID = "C8B2C0D8",
          NextDialogue = 80170429,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C0D8"
        },
        [80170429] = {
          ContentJP = "私の過去に興味を持つ者は多いけれど、幼少期について尋ねられたのは初めてです。だけど、後の人生と比べると、その時の記憶はあまりにも平凡で、振り返る意味もあまり感じません。",
          DialogueId = 80170429,
          GUID = "C8B2C102",
          NextDialogue = 80170430,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C102"
        },
        [80170430] = {
          ContentJP = "そうですね……",
          DialogueId = 80170430,
          FacialId = {
            [1] = "91502:Think01"
          },
          GUID = "C8B2C12C",
          NextDialogue = 80170431,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C12C"
        },
        [80170431] = {
          ContentJP = "私の家――最初の家は、エリュシオンの北方、緑豊かな森の中にありました。そこには伝説も貴族もなく、可愛らしい野ウサギや美味しいベリーに囲まれた土地でした。",
          DialogueId = 80170431,
          GUID = "C8B2C156",
          NextDialogue = 80170432,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C156"
        },
        [80170432] = {
          ContentJP = "私が覚えている子どもの頃の記憶は、地面にこぼれ落ちた木漏れ日の模様や、小川のせせらぎが奏でる心地よい音くらいでしょうか。",
          DialogueId = 80170432,
          GUID = "C8B2C180",
          NextDialogue = 80170433,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C180"
        },
        [80170433] = {
          ContentJP = "あの頃の私も、普通の少女のように、父に森へ遊びに連れて行って欲しいと駄々をこねたり、母の注意を無視して小川で水遊びをしたりしていました。",
          DialogueId = 80170433,
          GUID = "C8B2C1AA",
          NextDialogue = 80170434,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1AA"
        },
        [80170434] = {
          ContentJP = "母もまた、導き手でした。よく見知らぬ人たちが森を越えてきて、小さな箱を母に渡すのを見ました。母は月明かりの下で踊り、その箱を水流に乗せて流していきました。",
          DialogueId = 80170434,
          GUID = "C8B2C1D4",
          NextDialogue = 80170435,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1D4"
        },
        [80170435] = {
          ContentJP = "「その箱の中には何が入っているの？」と、私は母に尋ねました。「人の思いよ」と、母は答えました。",
          DialogueId = 80170435,
          GUID = "C8B2C1FE",
          NextDialogue = 80170436,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C1FE"
        },
        [80170436] = {
          ContentJP = "「どうしてその思いを水に流すの？」と問い返すと、「人は、前に進んでいかなくてはならないから」と、母は答えました。",
          DialogueId = 80170436,
          GUID = "C8B2C228",
          NextDialogue = 80170437,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C228"
        },
        [80170437] = {
          ContentJP = "私は全く理解できませんでした。私の困惑した顔を見た父は、優しく私の頭を撫でて言いました。「大きくなったら、きっとわかるよ」と。",
          DialogueId = 80170437,
          GUID = "C8B2C252",
          NextDialogue = 80170438,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C252"
        },
        [80170438] = {
          ContentJP = "残念ながら、彼らは私が成長した姿を見ることはありませんでした。彼らが処刑人に命を奪われたその瞬間、無邪気で平穏なニフルの人生も終わりを迎えました。",
          DialogueId = 80170438,
          FacialId = {
            [1] = "91502:Sad01"
          },
          GUID = "C8B2C27C",
          NextOptions = {
            [1] = 801704381
          },
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Think_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C27C"
        },
        [80170439] = {
          ContentJP = "時折、昔を思い出すことがありますが、他の方のように、懐かしさや追憶の気持ちでその記憶をなぞることはありません。ただ、それらの思い出がふっと浮かんで、過ぎ去っていくのを感じるだけです。",
          DialogueId = 80170439,
          FacialId = {
            [1] = "91502:None"
          },
          GUID = "C8B2C2A6",
          NextDialogue = 80170440,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_Start"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2A6"
        },
        [80170440] = {
          ContentJP = "私にとって、過去の出来事は、他の記憶と同じように、ただ人生の一部であり、特別な意味はありません。",
          DialogueId = 80170440,
          GUID = "C8B2C2D0",
          NextDialogue = 80170441,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2D0"
        },
        [80170441] = {
          ContentJP = "ただ、今日はあなたという聞き手がいるからか、こうして過去を語っていると、心の中に少し波が立ったような気がします……",
          DialogueId = 80170441,
          GUID = "C8B2C2FA",
          NextDialogue = 80170442,
          SpeakNpcId = 91502,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C2FA"
        },
        [80170442] = {
          ContentJP = "……少し疲れました。しばし休ませてください。",
          DialogueId = 80170442,
          FacialId = {
            [1] = "91502:Close"
          },
          GUID = "C8B2C324",
          NextDialogue = 80170443,
          SpeakNpcId = 91502,
          TalkActionId = {
            [1] = "91502:Sit_Talk03_End"
          },
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C324"
        },
        [80170443] = {
          ContentJP = "そう言うと、ニフル夫人は静かに目を閉じ、そっとあなたの肩に頭を預けた。",
          DialogueId = 80170443,
          GUID = "C8B2C34E",
          IsBlack = 1,
          NextDialogue = 80170444,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C34E"
        },
        [80170444] = {
          ContentJP = "彼女の穏やかな呼吸と、少し微笑んだ表情からして、きっと良い夢を見ているのだろう。",
          DialogueId = 80170444,
          GUID = "C8B2C378",
          IsBlack = 1,
          NextDialogue = 80170445,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C378"
        },
        [80170445] = {
          ContentJP = "ベリーの香りと陽光の温もりに満ちた場所で、いたずら好きな野ウサギと駆けっこするような――そんな素敵な夢を。",
          DialogueId = 80170445,
          GUID = "C8B2C3A2",
          IsBlack = 1,
          VoiceName = "voice/$Locale$/inv/Nifu/004/C8B2C3A2"
        },
        [80180001] = {
          DialogueId = 80180001,
          GUID = "C8B8E36A",
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8E36A"
        },
        [80180101] = {
          Camera = "452.71582,-120.713928,293.808594,0.000068,-25.999489,160.803513,30.000002,125.0,false,DoNotOverride,2.8",
          ContentJP = "（それは半年前のことでした。南方戦線での礼賛会との戦争中に負傷した退役軍人、ロジェ・ジャストン氏を病院に見舞ったときのことです。）",
          DialogueId = 80180101,
          FacialId = {
            [1] = "790045:Unhappy01"
          },
          FinalCamera = "452.71582,-120.713928,293.808594,0.000071,-23.999413,157.603546,30.000002,125.0,false,DoNotOverride,2.8",
          GUID = "C8B8F3D2",
          NextDialogue = 80180102,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F3D2"
        },
        [80180102] = {
          Camera = "-17.312012,189.65033,156.878906,0.000039,-12.39904,-60.39682,30.000002,247.327988,false,Manual,3.162369",
          ContentJP = "アメリア……来てくれたのか……",
          DialogueId = 80180102,
          FinalCamera = "-15.135742,190.885254,156.878906,0.00004,-12.399033,-61.39677,30.000002,247.327988,false,Manual,3.162369",
          GUID = "C8B8F3FC",
          NextDialogue = 80180103,
          SpeakNpcId = 790059,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F3FC"
        },
        [80180103] = {
          Camera = "93.808105,84.920227,124.542969,0.000044,9.600609,157.202698,30.000008,107.300728,false,Manual,3.162369",
          ContentJP = "…………",
          DialogueId = 80180103,
          GUID = "C8B8F426",
          NextDialogue = 80180104,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F426"
        },
        [80180104] = {
          ContentJP = "……はい、お父さん。会いに来ました。",
          DialogueId = 80180104,
          GUID = "C8B8F450",
          NextDialogue = 80180105,
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F450"
        },
        [80180105] = {
          Camera = "233.50293,-42.842896,169.013672,0.000073,-14.598969,150.198013,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentJP = "焼き菓子と蜂蜜を少し持ってきたんです。ディズマニアで一番人気のあるお店のものです。……お口に合うかどうか、試してみてください。",
          DialogueId = 80180105,
          FinalCamera = "233.50293,-42.842896,169.013672,0.000074,-10.998831,146.797302,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F47A",
          NextDialogue = 80180106,
          SpeakNpcId = 790045,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F47A"
        },
        [80180106] = {
          Camera = "-0.36084,492.293091,78.546875,0.000105,4.201092,-82.801735,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentJP = "アメリア、もっと近くに……顔を見せてくれ……",
          DialogueId = 80180106,
          FinalCamera = "-15.919922,490.611572,78.546875,0.000109,4.201092,-79.201218,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F4A4",
          NextDialogue = 80180107,
          SpeakNpcId = 790059,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F4A4"
        },
        [80180107] = {
          ContentJP = "随分背が伸びたな……痩せたし……錬金院での仕事、やっぱり大変なんだろう……",
          DialogueId = 80180107,
          GUID = "C8B8F4CE",
          NextDialogue = 80180108,
          SpeakNpcId = 790059,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F4CE"
        },
        [80180108] = {
          Camera = "124.885254,73.358887,114.648438,0.000111,8.801046,154.798798,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentJP = "ご心配なく。私は元気です。研究員の皆さんもとても親切で、いつも助けてくださっています。",
          DialogueId = 80180108,
          FinalCamera = "129.206543,80.562866,114.648438,0.000111,8.801046,157.199387,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F4F8",
          NextDialogue = 80180109,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Talk02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F4F8"
        },
        [80180109] = {
          Camera = "-22.415527,411.51062,217.269531,0.000075,-19.597588,-75.394966,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentJP = "……いや……",
          DialogueId = 80180109,
          FinalCamera = "-37.787109,408.08606,217.269531,0.000077,-19.597588,-72.99453,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F522",
          NextDialogue = 80180110,
          SpeakNpcId = 790059,
          TalkActionId = {
            [1] = "790045:Talk02_End"
          },
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F522"
        },
        [80180110] = {
          ContentJP = "錬金院の話になるといつも泣いていた。行ったことを後悔してるって言ってた……",
          DialogueId = 80180110,
          GUID = "C8B8F54C",
          NextDialogue = 80180111,
          SpeakNpcId = 790059,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F54C"
        },
        [80180111] = {
          Camera = "114.473145,81.809021,158.171875,0.000098,-23.197474,-77.990166,30.000002,247.327988,false,DoNotOverride,3.162369",
          ContentJP = "君は……アメリアじゃないな？……一体、誰なんだ？",
          DialogueId = 80180111,
          FinalCamera = "110.792969,99.114258,165.755859,0.000092,-22.997458,-77.989754,30.000002,247.327988,false,DoNotOverride,3.162369",
          GUID = "C8B8F576",
          NextDialogue = 80180112,
          SpeakNpcId = 790059,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F576"
        },
        [80180112] = {
          Camera = "211.481445,-34.879761,148.429688,0.000081,-6.797363,148.809708,30.000002,268.824341,false,Manual,3.162369",
          ContentJP = "申し訳ありません……ジャストンさん。ダフネ・セオドールと申します。……アメリアの友人です。代わりに、お見舞いに伺いました。",
          DialogueId = 80180112,
          FinalCamera = "214.442383,-29.989197,148.429688,0.000082,-6.797363,151.209473,30.000002,268.824341,false,Manual,3.162369",
          GUID = "C8B8F5A0",
          NextDialogue = 80180113,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain02_Start"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F5A0"
        },
        [80180113] = {
          Camera = "389.942871,-15.916992,216.761719,0.000082,-16.596901,170.208176,30.000002,379.770111,false,Manual,3.162369",
          ContentJP = "……ああ……すみません、セオドールさん。立ってご挨拶もできず、どうかお許しを……",
          DialogueId = 80180113,
          FacialId = {
            [1] = "790059:CM_Sad01"
          },
          FinalCamera = "391.346191,-7.785767,216.761719,0.000082,-16.596901,170.208176,30.000002,379.770111,false,Manual,3.162369",
          GUID = "C8B8F5CA",
          NextDialogue = 80180114,
          SpeakNpcId = 790059,
          ToFinalCameraBlendTime = 8,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F5CA"
        },
        [80180114] = {
          ContentJP = "記憶がよく抜け落ちるんです。夢なのか現実なのか、わからなくなることもあって……ここ数日、アメリアがまだ生きている気がして……",
          DialogueId = 80180114,
          GUID = "C8B8F5F4",
          NextDialogue = 80180115,
          SpeakNpcId = 790059,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F5F4"
        },
        [80180115] = {
          Camera = "-14.48877,190.756897,161.263672,0.000049,-12.396656,-61.593624,30.000008,244.623566,false,Manual,3.301471",
          ContentJP = "小さな頃の彼女が、八段の階段を跳び下りて、私の胸に飛び込んでくるんです。「パパ！」って叫びながら……",
          DialogueId = 80180115,
          FinalCamera = "-7.308105,195.172363,161.263672,0.000047,-12.396656,-65.793968,30.000008,244.623566,false,Manual,3.301471",
          GUID = "C8B8F61E",
          NextDialogue = 80180116,
          SpeakNpcId = 790059,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F61E"
        },
        [80180116] = {
          Camera = "116.074707,70.821228,122.748047,0.000048,6.402981,152.803696,30.000008,131.13031,false,Manual,3.301471",
          ContentJP = "ジャストンさん……その……",
          DialogueId = 80180116,
          FinalCamera = "120.910645,79.414978,122.748047,0.000047,6.402981,155.80397,30.000008,131.026245,false,Manual,3.301471",
          GUID = "C8B8F648",
          NextDialogue = 80180117,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Explain02_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F648"
        },
        [80180117] = {
          ContentJP = "いいんだ、慰めなくていい……思い出しました、アメリアは一ヶ月前に埋葬されたんだ。優しい看護師が私を車椅子で連れて行ってくれて……私は彼女がいつも遊んでいたゴムのアヒルを墓前に置いてやったよ……",
          DialogueId = 80180117,
          GUID = "C8B8F672",
          NextDialogue = 80180118,
          SpeakNpcId = 790059,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F672"
        },
        [80180118] = {
          Camera = "437.276855,-80.072693,281.332031,0.000106,-25.192556,163.998383,30.000008,507.135406,false,Manual,2.479588",
          ContentJP = "セオドールさん、君は彼女の一番の友達だった。アメリアが生きていたとき、君のことを何度も話していたよ。……あの錬金院という場所、気をつけてくれ……",
          DialogueId = 80180118,
          FinalCamera = "437.276855,-80.072693,281.332031,0.000103,-22.392521,159.3983,30.000008,507.135406,false,Manual,2.479588",
          GUID = "C8B8F69C",
          NextDialogue = 80180119,
          SpeakNpcId = 790059,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F69C"
        },
        [80180119] = {
          Camera = "437.276855,-80.072693,281.332031,0.000103,-22.392521,159.3983,30.000008,507.135406,false,Manual,2.479588",
          ContentJP = "（私は、ジャストンさんが言っていることの意味を理解していました。私の大切な同級生――アメリア・ジャストンは、サーベル錬金院での事故によって命を落としたのです。）",
          DialogueId = 80180119,
          GUID = "C8B8F6C6",
          IsBlack = 1,
          NextDialogue = 80180120,
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/001/C8B8F6C6"
        },
        [80180120] = {
