          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/002/C8B90950"
        },
        [80180233] = {
          Camera = "24.695312,-121.806152,171.394531,-10.819184,-18.998465,-112.377495,30.000002,368.927856,false,DoNotOverride,1.2",
          ContentJP = "カロンなんて、冷血で、自己中心的で、ずる賢い蛇だらけ。背を向けた瞬間、平気で足首に牙を突き立ててくるわ。",
          DialogueId = 80180233,
          FinalCamera = "18.752441,-119.948242,170.269531,-10.820675,-18.398371,-107.777733,30.000002,368.927856,false,DoNotOverride,1.2",
