        },
        [80180349] = {
          Camera = "1023.142578,-512.480469,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          ContentJP = "どこへ？",
          DialogueId = 80180349,
          FinalCamera = "1013.601562,-529.96875,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          GUID = "C8B91C82",
          NextDialogue = 80180350,
          SpeakNpcId = 110025,
          SpeakNpcName = "UI_Npc_Name_Shibing4",
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91C82"
        },
        [80180350] = {
          Camera = "1013.601562,-529.96875,-28.856567,0.000109,7.203766,151.359207,45.0,1202.78186,false,Manual,2.168443",
          ContentJP = "応急物資を探しに。あと……",
          DialogueId = 80180350,
          GUID = "C8B91CAC",
          NextDialogue = 80180351,
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91CAC"
        },
        [80180351] = {
          Camera = "-128.251953,-146.082031,134.427856,0.000144,-1.196642,52.959221,45.0,317.18219,false,Manual,6.360716",
          ContentJP = "{nickname2}隊長の安否を、確認しに行きます。",
          DialogueId = 80180351,
          FinalCamera = "-126.076172,-147.757812,134.427856,0.000144,-1.196642,53.559261,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91CD6",
          SpeakNpcId = 790045,
          TalkActionId = {
            [1] = "790045:Talk01_End"
          },
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91CD6"
        },
        [80180352] = {
          Camera = "-14.550781,-91.125,107.247437,0.000139,8.803205,58.55764,45.0,317.18219,false,Manual,6.360716",
          ContentJP = "（遺体の転がる道を越えながら、私は自分の息遣いと鼓動だけを感じていました。\n自分が小さな存在だったと、初めて思い知ったのです。）",
          DialogueId = 80180352,
          FinalCamera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D00",
          IsBlack = 1,
          NextDialogue = 80180353,
          SpeakNpcId = 790045,
          ToFinalCameraBlendTime = 6,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D00"
        },
        [80180353] = {
          Camera = "-9.892578,-94.234375,107.247437,0.000138,8.803205,60.757439,45.0,317.18219,false,Manual,6.360716",
          ContentJP = "（私は、友を打ち負かし、実験に勝ち、痛みに打ち勝ってきた。\nなんでも乗り越えられると、そう思っていた。\nでも今はわかる。私に勝てないもののほうが、ずっとずっと多いのだと。）",
          DialogueId = 80180353,
          GUID = "C8B91D2A",
          IsBlack = 1,
          NextDialogue = 80180354,
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D2A"
        },
        [80180354] = {
          Camera = "47.957031,-1250.3125,16.771729,0.000155,3.202962,92.956001,45.0,317.18219,false,Manual,6.360716",
          ContentJP = "（それでも、この先に何が待っていても。\nこの戦いが終わったあと、たとえ生き延びた私であっても、あるいは、魂だけになった私であっても――\nこの言葉だけは、シビル・メイソンに伝えたい。）",
          DialogueId = 80180354,
          FinalCamera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          GUID = "C8B91D54",
          IsBlack = 1,
          SpeakNpcId = 790045,
          ToFinalCameraBlendTime = 10,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D54"
        },
        [80180355] = {
          Camera = "76.232422,-1248.960938,16.771729,0.000158,3.202962,93.755997,45.0,317.18219,false,Manual,6.360716",
          ContentJP = "（<H>ダフネ・セオドールは、今なお理想を捨ててはいない。</>）",
          DialogueId = 80180355,
          GUID = "C8B91D7E",
          IsBlack = 1,
          SpeakNpcId = 790045,
          VoiceName = "voice/$Locale$/inv/Dafu/003/C8B91D7E"
        },
        [80190001] = {
          ContentJP = "タダ酒を断るやつなんていると思うか？",
          DialogueId = 80190001,
          GUID = "C8BF4C0A"
        },
        [80190101] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          DialogueId = 80190101,
          Duration = 3,
          GUID = "C8BF5C72",
          NextDialogue = 80190102,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190102] = {
          ContentJP = "お前、一人でこんなデカい屋敷に住んでんのかよ？見た目ちゃんとしてるし、バーカウンターまであんのな。",
          DialogueId = 80190102,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF5C9C",
          NextDialogue = 80190103,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190103] = {
          ContentJP = "いいねぇ、もっと友達呼べって。そうすりゃお前もアイスレイク城で人脈ってやつができるかもだろ？",
          DialogueId = 80190103,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5CC6",
          NextDialogue = 80190104,
          SpeakNpcId = 95102
        },
        [80190104] = {
          ContentJP = "で、何か用？どうせまた頼み事だろ？面倒なやつなら断るぞ、今けっこうデカい仕事抱えてるからな。",
          DialogueId = 80190104,
          GUID = "C8BF5CF0",
          NextOptions = {
            [1] = 801901041,
            [2] = 801901042
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190105] = {
          ContentJP = "うわっ……鳥肌立ったんだけど。ま、俺だからまだしも、他のやつにもそんなセリフで酒誘ったらドン引きされっぞ？",
          DialogueId = 80190105,
          GUID = "C8BF5D1A",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190106] = {
          ContentJP = "おっ、そんじゃ遠慮なく。お前の腕前、味見させてもらおうか。",
          DialogueId = 80190106,
          GUID = "C8BF5D44",
          NextDialogue = 80190107,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190107] = {
          ContentJP = "{空格}",
          DialogueId = 80190107,
          Duration = 3,
          GUID = "C8BF5D6E",
          NextDialogue = 80190108,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190108] = {
          ContentJP = "ぷはぁ、ん、甘みの中に酸味があるし、そのうえ暖め酒ときた。アスフォデロスで飲んだやつに似てるが、どこかお前らしい味わいを感じるぜ。",
          DialogueId = 80190108,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF5D98",
          NextDialogue = 80190109,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190109] = {
          ContentJP = "これ、けっこう手間かかったろ？正直、期待以上だった。俺なんて熱湯でさえテンションが上がるやつだから、そこまで気合入れんでもよかったのによ。",
          DialogueId = 80190109,
          GUID = "C8BF5DC2",
          NextDialogue = 80190110,
          SpeakNpcId = 95102
        },
        [80190110] = {
          ContentJP = "ま、でもお前がノリノリだったのは分かったわ。あーなるほどな、ちょっと金入ったからパーッと使いたくなったんだろ？ご馳走して、新しいモン買ってさ。最近よくあるじゃん「金で気分を買う」みたいなやつ。",
          DialogueId = 80190110,
          GUID = "C8BF5DEC",
          NextOptions = {
            [1] = 801901101,
            [2] = 801901102
          },
          SpeakNpcId = 95102
        },
        [80190111] = {
          ContentJP = "だろ？一杯やるってことは、話したいってことだ。つまり俺が、他のやつらよりお前の気持ち分かってるってわけ。ありがたく思えよ？",
          DialogueId = 80190111,
          GUID = "C8BF5E16",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190112] = {
          ContentJP = "わーったわーった、俺が悪かった！金出してんのお前様だもんな？一発殴って気が済むなら、好きにやれ。",
          DialogueId = 80190112,
          GUID = "C8BF5E40",
          NextDialogue = 80190113,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190113] = {
          ContentJP = "……っと冗談はさておき、先輩からひとつ忠告な。「全員が友達」って思うな。酒おごる相手は選べ。",
          DialogueId = 80190113,
          GUID = "C8BF5E6A",
          NextDialogue = 80190114,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190114] = {
          ContentJP = "特にこのアイスレイク城じゃ、ロクでもねえ奴らが、お前の持ちもん狙ってすり寄ってくるからな。最初はいい顔して、やたら持ち上げてくる。",
          DialogueId = 80190114,
          GUID = "C8BF5E94",
          NextDialogue = 80190115,
          SpeakNpcId = 95102
        },
        [80190115] = {
          ContentJP = "表向きはへつらっていやがるが、いざってときには、なんの役にも立たねぇ。そいつらに比べたら、道端の野良犬のがマシだ。",
          DialogueId = 80190115,
          GUID = "C8BF5EBE",
          NextOptions = {
            [1] = 801901151
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190116] = {
          ContentJP = "はいはい、そうでーす。俺こそ最高にいい例ってやつだ。得さえあれば、どこだろうが、鼻利かせて飛んでくっつーの。",
          DialogueId = 80190116,
          GUID = "C8BF5EE8",
          NextDialogue = 80190117,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190117] = {
          ContentJP = "他のやつらがそのポジション欲しがったら、まずは自分の格をわきまえろってこったな。俺が腹いっぱいになるまで、他の誰かにうまい思いはさせないぜ？",
          DialogueId = 80190117,
          GUID = "C8BF5F12",
          NextOptions = {
            [1] = 801901171,
            [2] = 801901172
          },
          SpeakNpcId = 95102
        },
        [80190118] = {
          ContentJP = "えぇ！？ ちょっと待てよ、まだ帰りたくねぇんだけど！",
          DialogueId = 80190118,
          GUID = "C8BF5F3C",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190119] = {
          ContentJP = "ん？……さあ？何の話だか、さっぱり分かんねぇな〜？",
          DialogueId = 80190119,
          GUID = "C8BF5F66",
          NextDialogue = 80190120,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190120] = {
          ContentJP = "……酒、うまかった。もう一杯くれ。それ飲んだら、ちゃんと仕事戻るからさ。",
          DialogueId = 80190120,
          GUID = "C8BF5F90",
          SpeakNpcId = 95102
        },
        [80190201] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentJP = "おーっと、30分遅刻しちまったな。お詫びに、たとえ今日の酒がニシン缶みてぇな味でも、きっちり飲み干してやるよ！",
          DialogueId = 80190201,
          FacialId = {
            [1] = "95102:Ahaha01"
          },
          GUID = "C8BF6CDA",
          NextOptions = {
            [1] = 801902011,
            [2] = 801902012
          },
          SpeakNpcId = 95102
        },
        [80190202] = {
          ContentJP = "ハハ、バレたか。",
          DialogueId = 80190202,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF6D04",
          NextDialogue = 80190203,
          SpeakNpcId = 95102
        },
        [80190203] = {
          ContentJP = "この前言ってたでかい仕事、覚えてるか？今日ようやくウェルズと片付けたんだわ。思ったより時間食っちまってさ。",
          DialogueId = 80190203,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF6D2E",
          NextDialogue = 80190204,
          SpeakNpcId = 95102
        },
        [80190204] = {
          ContentJP = "依頼自体は単純なんだけどな、関わってるヤツがとにかく厄介だった。",
          DialogueId = 80190204,
          GUID = "C8BF6D58",
          NextOptions = {
            [1] = 801902041
          },
          SpeakNpcId = 95102
        },
        [80190205] = {
          ContentJP = "いやいや、あいつらのがまだマシだ。ルール守って、空気読んで、帝国に逆らわなきゃ基本スルーしてくれる。",
          DialogueId = 80190205,
          GUID = "C8BF6D82",
          NextDialogue = 80190206,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190206] = {
          ContentJP = "言ってみりゃ剣みたいなもんだな。危ねぇけど、動きは読める。",
          DialogueId = 80190206,
          GUID = "C8BF6DAC",
          NextDialogue = 80190207,
          SpeakNpcId = 95102
        },
        [80190207] = {
          ContentJP = "でもな、もっとヤベぇのがいる。タチ悪くて、横暴で、何考えてるかまったく分かんねぇ連中。まるで地雷みたいなやつらだ。",
          DialogueId = 80190207,
          GUID = "C8BF6DD6",
          NextDialogue = 80190208,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190208] = {
          ContentJP = "――フォーセイクン同盟だよ。あいつらに関わると、まったく厄介事だらけだ。",
          DialogueId = 80190208,
          GUID = "C8BF6E00",
          NextDialogue = 80190209,
          SpeakNpcId = 95102
        },
        [80190209] = {
          ContentJP = "今回もな、本来はただの配送だったんだよ。でもウェルズが「荷物の重さおかしくね？」って言い出して、中身こっそり確認したら……違法武器の山ときた。",
          DialogueId = 80190209,
          GUID = "C8BF6E2A",
          NextDialogue = 80190210,
          SpeakNpcId = 95102
        },
        [80190210] = {
          ContentJP = "もし正門から入ってたら、門前で衛兵に撃ち殺されて終わってたな。",
          DialogueId = 80190210,
          GUID = "C8BF6E54",
          NextDialogue = 80190211,
          SpeakNpcId = 95102
        },
        [80190211] = {
          ContentJP = "たぶん、それがヤツらの狙いだったんだろうな。月狩り人の死体が欲しかったのか、騒ぎを起こして城に潜り込みたかったのか……",
          DialogueId = 80190211,
          GUID = "C8BF6E7E",
          NextDialogue = 80190212,
          SpeakNpcId = 95102
        },
        [80190212] = {
          ContentJP = "もしくは、ソラがカロンをどう虐げてるかってのを、信者に見せたかったのかもしれねぇ。",
          DialogueId = 80190212,
          GUID = "C8BF6EA8",
          NextDialogue = 80190213,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190213] = {
          ContentJP = "もう意味わかんねぇだろ？常人の考え方じゃねぇよ。",
          DialogueId = 80190213,
          FacialId = {
            [1] = "95102:Angry01"
          },
          GUID = "C8BF6ED2",
          NextDialogue = 80190214,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190214] = {
          ContentJP = "結局、荷物を下水道に流して、排水口からこっそり運び込んで、外面だけは納品完了ってことにしたんだ。",
          DialogueId = 80190214,
          GUID = "C8BF6EFC",
          NextDialogue = 80190215,
          SpeakNpcId = 95102
        },
        [80190215] = {
          ContentJP = "簡単に聞こえるかもしんねぇけど、実際は何日も徹夜だぞ。俺もウェルズも、クッタクタだぜ。",
          DialogueId = 80190215,
          GUID = "C8BF6F26",
          NextOptions = {
            [1] = 801902151,
            [2] = 801902152
          },
          SpeakNpcId = 95102
        },
        [80190216] = {
          ContentJP = "いやいや、それとこれとは別だろ。ウェルズ側で何があろうと、お前との約束に遅刻したのは確かだからな。",
          DialogueId = 80190216,
          GUID = "C8BF6F50",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190217] = {
          ContentJP = "いやいや、それとこれは別だ！飲み仲間ってのはな、酒があれば棺からだって這い出してくるもんだぞ。",
          DialogueId = 80190217,
          GUID = "C8BF6F7A",
          NextDialogue = 80190218,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190218] = {
          ContentJP = "{空格}",
          DialogueId = 80190218,
          Duration = 3,
          GUID = "C8BF6FA4",
          NextDialogue = 80190219,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190219] = {
          ContentJP = "……でもまぁ、そろそろマジで寝るべきかもな。ただ、その前にひとつだけ言っときたい。お前や、お前を大事に思ってる仲間のためにも――最近のフォーセイクン同盟には、できるだけ関わらない方がいい。",
          DialogueId = 80190219,
          GUID = "C8BF6FCE",
          NextOptions = {
            [1] = 801902191
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190220] = {
          ContentJP = "……そりゃまあ。好きなやつなんてほとんどいないだろ。危ないもんには近づくな。それだけだ。",
          DialogueId = 80190220,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF6FF8",
          NextDialogue = 80190221,
          SpeakNpcId = 95102
        },
        [80190221] = {
          ContentJP = "長年このクソみてぇな暴力の世界で生き延びてきた俺が言える、たった一つの大事な教訓だ。フォーセイクン同盟には――絶対に、絶対に近づくな。",
          DialogueId = 80190221,
          GUID = "C8BF7022",
          NextDialogue = 80190222,
          SpeakNpcId = 95102
        },
        [80190222] = {
          ContentJP = "これは酔っ払いの戯言じゃねぇ。命に関わる警告だ。",
          DialogueId = 80190222,
          GUID = "C8BF704C",
          SpeakNpcId = 95102
        },
        [80190301] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentJP = "アウトサイダーは約束どおり現れた。だが、一口酒を飲んだきり、押し黙ってしまった。",
          DialogueId = 80190301,
          Duration = 3,
          FacialId = {
            [1] = "95102:Unhappy02"
          },
          GUID = "C8BF7D42",
          NextDialogue = 80190302,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190302] = {
          ContentJP = "……",
          DialogueId = 80190302,
          GUID = "C8BF7D6C",
          NextDialogue = 80190303,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190303] = {
          ContentJP = "…………",
          DialogueId = 80190303,
          GUID = "C8BF7D96",
          NextOptions = {
            [1] = 801903031,
            [2] = 801903032
          },
          SpeakNpcId = 95102
        },
        [80190304] = {
          ContentJP = "……",
          DialogueId = 80190304,
          GUID = "C8BF7DC0",
          NextDialogue = 80190305,
          SpeakNpcId = 95102
        },
        [80190305] = {
          ContentJP = "……ああ、大丈夫大丈夫。美味い酒だな。相変わらずいい出来だ。",
          DialogueId = 80190305,
          GUID = "C8BF7DEA",
          NextDialogue = 80190306,
          SpeakNpcId = 95102
        },
        [80190306] = {
          ContentJP = "……",
          DialogueId = 80190306,
          GUID = "C8BF7E14",
          NextOptions = {
            [1] = 801903061,
            [2] = 801903062
          },
          SpeakNpcId = 95102
        },
        [80190307] = {
          ContentJP = "は？勘違いすんなよ。俺が人前で泣くわけねーだろ。憂いた「飲み仲間」ってキャラじゃねーんだわ。",
          DialogueId = 80190307,
          FacialId = {
            [1] = "95102:Shock01"
          },
          GUID = "C8BF7E3E",
          NextDialogue = 80190308,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190308] = {
          ContentJP = "まあな、最近ちょくちょく昔のこと思い出すんだよ……年かね。",
          DialogueId = 80190308,
          FacialId = {
            [1] = "95102:Sad01"
          },
          GUID = "C8BF7E68",
          NextDialogue = 80190309,
          SpeakNpcId = 95102
        },
        [80190309] = {
          ContentJP = "そんな深刻そうな顔すんなって。別に昔話するつもりなんかねぇよ。まさか数杯か奢っただけで、俺の昔話を全部聞き出せると思ってんのか？",
          DialogueId = 80190309,
          GUID = "C8BF7E92",
          NextDialogue = 80190310,
          SpeakNpcId = 95102
        },
        [80190310] = {
          ContentJP = "誰にだって、墓まで持ってく秘密のひとつやふたつはあるんだよ。心の底に沈んでる副葬品ってやつがな。",
          DialogueId = 80190310,
          GUID = "C8BF7EBC",
          NextDialogue = 80190311,
          SpeakNpcId = 95102
        },
        [80190311] = {
          ContentJP = "それが取るに足らないことでもいいんだ。たとえばイコル液の匂いが好きだとか、固ぇジンジャークッキーかじって前歯折ったとか、あるいは――誰にも言えねぇような過去とか、な。",
          DialogueId = 80190311,
          GUID = "C8BF7EE6",
          NextDialogue = 80190312,
          SpeakNpcId = 95102
        },
        [80190312] = {
          ContentJP = "でもな、そういう目に見えねぇ秘密こそが、その人間の生き方を決めたりすんだ。……ま、言いすぎかもしんねーけど、言いたいことは伝わるだろ？",
          DialogueId = 80190312,
          GUID = "C8BF7F10",
          NextDialogue = 80190313,
          SpeakNpcId = 95102
        },
        [80190313] = {
          ContentJP = "自分の秘密をペラペラしゃべるやつってのは、大体二通りだ。ひとつは、そもそもその過去に重みがねぇやつ。",
          DialogueId = 80190313,
          GUID = "C8BF7F3A",
          NextDialogue = 80190314,
          SpeakNpcId = 95102
        },
        [80190314] = {
          ContentJP = "もうひとつは、誰かに慰めてもらいたくて、テキトーな作り話こさえてるやつだ。",
          DialogueId = 80190314,
          GUID = "C8BF7F64",
          NextDialogue = 80190315,
          SpeakNpcId = 95102
        },
        [80190315] = {
          ContentJP = "とにかくだ、自分の秘密や弱みを簡単にさらけ出すのは軽率な行為だ。相手に軽いヤツだと思われかねねぇしな。",
          DialogueId = 80190315,
          GUID = "C8BF7F8E",
          NextOptions = {
            [1] = 801903151,
            [2] = 801903152
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190316] = {
          ContentJP = "まあまあ、分かってるって。俺だってアスフォデロスじゃたまに「またデカい依頼引き受けちゃってさ〜」とかポロッと言ったりするし？",
          DialogueId = 80190316,
          GUID = "C8BF7FB8",
          NextDialogue = 80190317,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_AgreeHead"
          }
        },
        [80190317] = {
          ContentJP = "でも、それと「本当のこと」ってのはやっぱ違ぇんだよな。",
          DialogueId = 80190317,
          GUID = "C8BF7FE2",
          NextOptions = {
            [1] = 801903171
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190318] = {
          ContentJP = "おい！でたらめ言うなよ！",
          DialogueId = 80190318,
          GUID = "C8BF800C",
          NextDialogue = 80190319,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190319] = {
          ContentJP = "……お前だからこそ、俺は昔のこと、軽々しく話せねぇのよ。焦らしてるわけじゃねぇ。ただこれだけは分かってほしい。",
          DialogueId = 80190319,
          GUID = "C8BF8036",
          NextDialogue = 80190320,
          SpeakNpcId = 95102
        },
        [80190320] = {
          ContentJP = "墓を掘り返しても、宝が出てくるとは限らねぇ。むしろ呪いに引っかかる方が多い。だから俺は、秘密を墓まで持っていくんだ。",
          DialogueId = 80190320,
          GUID = "C8BF8060",
          NextDialogue = 80190321,
          SpeakNpcId = 95102
        },
        [80190321] = {
          ContentJP = "心配すんなって。ちゃんと過去は振り切ってきたさ。仮にそれが追いついてきたとしても、俺が何とかする。いずれ訪れる不安より、今の一杯の方が大事だろ？",
          DialogueId = 80190321,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF808A",
          NextDialogue = 80190322,
          SpeakNpcId = 95102
        },
        [80190322] = {
          ContentJP = "――よし、もう一杯だ！さっきのは一気にいっちまったから、味わうヒマもなかったんだわ。",
          DialogueId = 80190322,
          GUID = "C8BF80B4",
          NextOptions = {
            [1] = 801903221,
            [2] = 801903222
          },
          SpeakNpcId = 95102
        },
        [80190323] = {
          ContentJP = "ハハハッ、うまい酒といい仲間がいりゃ、ダラダラしゃべってるだけでも、最高の一日ってやつよ。",
          DialogueId = 80190323,
          FacialId = {
            [1] = "95102:Smile02"
          },
          GUID = "C8BF80DE",
          NextOptions = {
            [1] = 801903231
          },
          SpeakNpcId = 95102
        },
        [80190324] = {
          ContentJP = "……って今の、俺のことバカにしてない？",
          DialogueId = 80190324,
          GUID = "C8BF8108",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190401] = {
          Camera = "184.82782,72.338623,127.99707,0.000026,1.199654,-136.185898,35.0,125.0,false,Disable,2.8",
          ContentJP = "{空格}",
          DialogueId = 80190401,
          GUID = "C8BF8DAA",
          NextDialogue = 80190402,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190402] = {
          ContentJP = "ん？今、お前俺の名前呼んだか？",
          DialogueId = 80190402,
          FacialId = {
            [1] = "95102:Doubt01"
          },
          GUID = "C8BF8DD4",
          NextOptions = {
            [1] = 801904021
          },
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102
        },
        [80190403] = {
          ContentJP = "……あー、そっか。最近な、ちょっと被害妄想ぎみなんだよ。悪ぃな。",
          DialogueId = 80190403,
          FacialId = {
            [1] = "95102:Unhappy01"
          },
          GUID = "C8BF8DFE",
          NextDialogue = 80190404,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190404] = {
          ContentJP = "実はな、だいぶ前から幻聴ってやつがあってさ。時折誰かに本名を呼ばれた気になるんだ。その声は時に優しく、時に凛としててな。",
          DialogueId = 80190404,
          GUID = "C8BF8E28",
          NextDialogue = 80190405,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_Start"
          }
        },
        [80190405] = {
          ContentJP = "ま、耳鳴りみたいなモンよ。聞き慣れちまえば平気だ。暇なときはノリで返事して遊んでんだわ、どうせ幻聴だしな。",
          DialogueId = 80190405,
          GUID = "C8BF8E52",
          NextDialogue = 80190406,
          SpeakNpcId = 95102
        },
        [80190406] = {
          ContentJP = "でもな、昨日ヤベぇことが起きたんだよ。いつも通り適当に「おう」って返したらよ、本当に返事が返ってきたんだ。",
          DialogueId = 80190406,
          GUID = "C8BF8E7C",
          NextDialogue = 80190407,
          SpeakNpcId = 95102
        },
        [80190407] = {
          ContentJP = "路地のゴミ箱がガターン！って倒れてな、真っ黒な人影が出てきて、俺に声かけてきたんだよ。",
          DialogueId = 80190407,
          GUID = "C8BF8EA6",
          NextDialogue = 80190408,
          SpeakNpcId = 95102
        },
        [80190408] = {
          ContentJP = "ガキのイタズラだったらどれだけ良かったか……けどな、あいつが呼んだのは「アウトサイダー」じゃなくて、フォーセイクン同盟の連中しか知らねぇ名前だったんだ。",
          DialogueId = 80190408,
          GUID = "C8BF8ED0",
          NextDialogue = 80190409,
          SpeakNpcId = 95102
        },
        [80190409] = {
          ContentJP = "とっさに聞き間違ったふりをしたが……バレてないかは正直わかんねぇ。あ〜あ、あの依頼、全部ウェルズに押しつけときゃよかったわ。",
          DialogueId = 80190409,
          GUID = "C8BF8EFA",
          NextOptions = {
            [1] = 801904091
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk02_End"
          }
        },
        [80190410] = {
          ContentJP = "……",
          DialogueId = 80190410,
          GUID = "C8BF8F24",
          NextDialogue = 80190411,
          SpeakNpcId = 95102
        },
        [80190411] = {
          ContentJP = "{空格}",
          DialogueId = 80190411,
          GUID = "C8BF8F4E",
          NextDialogue = 80190412,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190412] = {
          ContentJP = "……まあいいか、正直に話すよ。そうじゃねぇと、油断したお前が道端でフォーセイクン同盟のキ●ガイに刺されでもしたら、心苦しいからな。",
          DialogueId = 80190412,
          GUID = "C8BF8F78",
          NextDialogue = 80190413,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_Start"
          }
        },
        [80190413] = {
          ContentJP = "昔ちょっとフォーセイクンとトラブったことあってよ、それ以来ずっと俺のこと探してんの。で、この前の依頼で……まあ、居場所がバレた<H>可能性</>があるってワケ。",
          DialogueId = 80190413,
          GUID = "C8BF8FA2",
          NextDialogue = 80190414,
          SpeakNpcId = 95102
        },
        [80190414] = {
          ContentJP = "だから今、アイスレイク城で俺の痕跡を全部消す作業してんのさ。厄介だからな。",
          DialogueId = 80190414,
          GUID = "C8BF8FCC",
          NextDialogue = 80190415,
          SpeakNpcId = 95102
        },
        [80190415] = {
          ContentJP = "もし見つかったら、俺の友達は全員巻き添えだ。片っ端から拷問されて、俺の居場所聞き出されんの。お前も例外じゃねぇ。",
          DialogueId = 80190415,
          GUID = "C8BF8FF6",
          NextDialogue = 80190416,
          SpeakNpcId = 95102
        },
        [80190416] = {
          ContentJP = "……まあでも、お前は「アイツはただの飲み友だし、何も知らねぇ」って言い切ってくれていいぜ？",
          DialogueId = 80190416,
          GUID = "C8BF9020",
          NextOptions = {
            [1] = 801904161,
            [2] = 801904162
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk01_End"
          }
        },
        [80190417] = {
          ContentJP = "そう焦って否定するなって……だが、もしも、本当にその日が来たら――",
          DialogueId = 80190417,
          GUID = "C8BF904A",
          NextDialogue = 80190418,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_Start"
          }
        },
        [80190418] = {
          ContentJP = "俺はお前らの前から姿を消す。もちろん、街からもな。そうなったら、フィーナのことは頼むぜ。",
          DialogueId = 80190418,
          GUID = "C8BF9074",
          NextDialogue = 80190419,
          SpeakNpcId = 95102
        },
        [80190419] = {
          ContentJP = "もしあいつが俺のこと尋ねたら、適当にはぐらかしてくれ。でっかい依頼が入ったとかな。そんで、俺の書いた手紙を月イチで渡してくれりゃあ、しばらくは誤魔化せると思う。",
          DialogueId = 80190419,
          GUID = "C8BF909E",
          NextDialogue = 80190420,
          SpeakNpcId = 95102
        },
        [80190420] = {
          ContentJP = "あ、そうだ。ウチの暖炉な、右側の三枚目のレンガの裏にちょっとだけ金を隠してるんだ。好きに使ってくれ。えーと、あと何かあったか……",
          DialogueId = 80190420,
          GUID = "C8BF90C8",
          NextDialogue = 80190421,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Think_End"
          }
        },
        [80190421] = {
          ContentJP = "アウトサイダー、とりあえず落ち着いて。",
          DialogueId = 80190421,
          GUID = "C8BF90F2",
          NextDialogue = 80190422,
          SpeakNpcId = 790008
        },
        [80190422] = {
          ContentJP = "……俺はいたって冷静だ。さっき俺が言ったこと、復唱してくれ。俺がいなくなったときに頼れるのは、お前しかいねぇんだからな。",
          DialogueId = 80190422,
          GUID = "C8BF911C",
          NextDialogue = 80190423,
          SpeakNpcId = 95102
        },
        [80190423] = {
          ContentJP = "なんだかアウトサイダーらしくないね。フォーセイクン同盟にビビってるの？",
          DialogueId = 80190423,
          GUID = "C8BF9146",
          NextDialogue = 80190424,
          SpeakNpcId = 790008
        },
        [80190424] = {
          ContentJP = "いつものノリじゃ、あのイカれた連中を相手にできねぇからな。",
          DialogueId = 80190424,
          FacialId = {
            [1] = "95102:Unacceptable01"
          },
          GUID = "C8BF9170",
          NextDialogue = 80190425,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_Start"
          }
        },
        [80190425] = {
          ContentJP = "あいつらはな、たったひとつの情報のために、指の爪を一本ずつ剥がすような奴らだぜ。",
          DialogueId = 80190425,
          GUID = "C8BF919A",
          NextDialogue = 80190426,
          SpeakNpcId = 95102
        },
        [80190426] = {
          ContentJP = "何が怖いかって、それが拷問の「始まり」にすぎねぇってんだ……友人を……そんな目に遭わせたくねぇ……",
          DialogueId = 80190426,
          GUID = "C8BF91C4",
          NextDialogue = 80190427,
          SpeakNpcId = 95102
        },
        [80190427] = {
          ContentJP = "……けど、まだ何も起きてないじゃん？居場所ばバレたってのもあくまで<H>可能性</>の話でしょ？",
          DialogueId = 80190427,
          GUID = "C8BF91EE",
          NextDialogue = 80190428,
          SpeakNpcId = 790008
        },
        [80190428] = {
          ContentJP = "1%でも可能性があるのなら、備えておくに越したことはない。",
          DialogueId = 80190428,
          GUID = "C8BF9218",
          NextDialogue = 80190429,
          SpeakNpcId = 95102
        },
        [80190429] = {
          ContentJP = "以前にもこんなことなかったの？その時よりも危険だってこと？",
          DialogueId = 80190429,
          GUID = "C8BF9242",
          NextDialogue = 80190430,
          SpeakNpcId = 790008
        },
        [80190430] = {
          ContentJP = "まあ……確かに今よりずっと危険な時はあったな……",
          DialogueId = 80190430,
          FacialId = {
            [1] = "95102:Think01"
          },
          GUID = "C8BF926C",
          NextDialogue = 80190431,
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Talk03_End"
          }
        },
        [80190431] = {
          ContentJP = "でしょ？その時はどうしてたの？",
          DialogueId = 80190431,
          GUID = "C8BF9296",
          NextDialogue = 80190432,
          SpeakNpcId = 790008
        },
        [80190432] = {
          ContentJP = "……まぁ、ただの空騒ぎだったこともある。そうでない場合は、脅しかけたり、ハッタリかましたり、軍団呼び込んだり、別の街でわざと目立ってごまかしたり――そういう小細工で乗り切ったことも、あるにはあるな。",
          DialogueId = 80190432,
          GUID = "C8BF92C0",
          NextOptions = {
            [1] = 801904321,
            [2] = 801904322
          },
          SpeakNpcId = 95102
        },
        [80190433] = {
          ContentJP = "{空格}",
          DialogueId = 80190433,
          GUID = "C8BF92EA",
          NextDialogue = 80190434,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190434] = {
          ContentJP = "ああ……お前の言うとおりだな。さっきは……どうかしてたぜ。もっとヤバい状況だって乗り越えてきたってのに、ガラにもなく「遺言」みてぇなこと言っちまったな。",
          DialogueId = 80190434,
          FacialId = {
            [1] = "95102:None"
          },
          GUID = "C8BF9314",
          NextDialogue = 80190435,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190435] = {
          ContentJP = "最近お前としゃべりすぎたせいか、それとも無意識に隊長のあんたに甘えたくなったのか、気が弱くなっちまったか……",
          DialogueId = 80190435,
          GUID = "C8BF933E",
          NextDialogue = 80190436,
          SpeakNpcId = 95102
        },
        [80190436] = {
          ContentJP = "……って、そんなわけねぇ！さては、今日の酒に何か仕込んだな！俺、今ものすごくキモいこと言ってなかった？言ってねぇよな、な！？",
          DialogueId = 80190436,
          GUID = "C8BF9368",
          NextOptions = {
            [1] = 801904361,
            [2] = 801904362
          },
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_DisagreeHead"
          }
        },
        [80190437] = {
          ContentJP = "ま、とにかく。不確かな「いつか」に怯えるより、起きた時に真っ先に頼ってほしい。もしかしたら、その時にはもっといい解決策があるかもしれないし。",
          DialogueId = 80190437,
          GUID = "C8BF9392",
          NextDialogue = 80190438,
          SpeakNpcId = 790008
        },
        [80190438] = {
          ContentJP = "ゴホッゴホッ……言うじゃねぇか。頼んだぜ、未来の俺！さあさあ、飲もうぜ！未来の俺たちに、乾杯！",
          DialogueId = 80190438,
          FacialId = {
            [1] = "95102:Smile01"
          },
          GUID = "C8BF93BC",
          NextDialogue = 80190439,
          SpeakNpcId = 95102
        },
        [80190439] = {
          ContentJP = "{空格}",
          DialogueId = 80190439,
          GUID = "C8BF93E6",
          NextDialogue = 80190440,
          Scripts = "PlayNormalSound{_delay{3},EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          TalkActionId = {
            [1] = "95102:Aote_Story_Drink"
          }
        },
        [80190440] = {
          ContentJP = "おっと、でもひとつ謝っとくわ。未来の不安はまぁ落ち着いたけど――俺の過去のことは、やっぱ全部は話せねぇんだ。",
          DialogueId = 80190440,
          GUID = "C8BF9410",
          NextDialogue = 80190441,
          Scripts = "StopNormalSound{EventPath{\"event:/sfx/common/story/ex01/yaoyue_drunk\"},PlayAs2D{true}}",
          SpeakNpcId = 95102,
          TalkActionId = {
            [1] = "95102:Sit_Idle_Loop"
          }
        },
        [80190441] = {
          ContentJP = "でもな、これだけは約束する。いつか必ず、お前に見せるよ――俺がアイスレイク城に来るまで、どんな道を通ってきたのかを。たぶん、俺にとってはキツい話になるし、お前の俺に対する信用を下げるかもしれねぇがな。",
          DialogueId = 80190441,
          GUID = "C8BF943A",
          NextDialogue = 80190442,
          SpeakNpcId = 95102
        },
        [80190442] = {
          ContentJP = "だが、その時が来ても、お前は今日と同じように、黙って俺に一杯ふるまってくれるって信じてるぜ――相棒。",
          DialogueId = 80190442,
          GUID = "C8BF9464",
          SpeakNpcId = 95102
        },
        [80200001] = {
          Camera = "371.189178,358.122345,166.996094,0.000053,-4.198886,-152.598816,30.0,1011.382263,false,Manual,2.8",
          ContentJP = "春には薇を摘み、夏には莧を育て、秋には枳を結び、冬には芝を訪う……",
          DialogueId = 80200001,
          FinalCamera = "255.737183,256.213654,144.412109,0.000053,-4.398778,-152.798981,30.000002,1011.382263,false,Manual,2.8",
