}]],
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          },
          ToFinalCameraBlendTime = 8
        },
        [80200004] = {
          ContentJP = "おっしゃるとおりです。今申し上げたものはすべて薬草で、中には食用にもなるものもございます。",
          DialogueId = 80200004,
          GUID = "C8C5B528",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200006] = {
          ContentJP = "ふふ……そこまで見抜かれるとは。まさしく『草木精要』からの一節です。",
          DialogueId = 80200006,
          GUID = "C8C5B57C",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200008] = {
          ContentJP = "いえ、あなたと私の間に遠慮は無用です。こうしてお越しいただけたこと、嬉しく思います。",
          DialogueId = 80200008,
          GUID = "C8C5B5D0",
          NextDialogue = 80200009,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Talk02_Start"
          }
        },
        [80200009] = {
          Camera = "-299.287354,935.059692,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          ContentJP = "さて、書物も随分と読みましたし、少し休憩いたしましょう。",
          DialogueId = 80200009,
          FinalCamera = "-309.453308,979.785645,645.397461,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
