            [1] = 802000101,
            [2] = 802000102,
            [3] = 802000103
          },
          Scripts = "LookAt{_delay{5.1},LookAtDescription{\"790053:n(790008)\"}}",
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790008:Talk03_End",
            [2] = "790053:Explain02_Start"
          },
          ToFinalCameraBlendTime = 8
        },
        [80200012] = {
          ContentJP = "最初のうちは不慣れでしたが……やはり、私はこの地が好きなのです。不便にも、いずれ慣れました。",
          DialogueId = 80200012,
          GUID = "C8C5B678",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200014] = {
          ContentJP = "ご寛容に感謝いたします。それこそが「君子の交わり、水の如し」でしょうか。",
          DialogueId = 80200014,
          GUID = "C8C5B6CC",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200016] = {
          ContentJP = "お腹が空きましたか？けれど、まだ食事の時刻には早いので。今しばらくお待ちを。",
          DialogueId = 80200016,
          GUID = "C8C5B720",
          NextDialogue = 80200017,
          SpeakNpcId = 790053,
          TalkActionId = {
            [1] = "790053:Explain02_End"
          }
        },
        [80200017] = {
          Camera = "8.049835,364.447235,138.173828,0.000069,-1.798737,-95.393364,35.0,1011.382263,false,DoNotOverride,1.2",
          ContentJP = "……ちょうどいい機会ですし、ひとつ、お願いがあります。",
          DialogueId = 80200017,
          FinalCamera = "6.295837,345.858063,137.587891,0.000069,-1.798737,-96.993561,35.0,1011.382263,false,DoNotOverride,1.2",
