        },
        [80200027] = {
          Camera = "-371.388824,918.673523,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          ContentJP = "無理にとは言いません。お体のことですから、気が進まなければ断っていただいて構いません。",
          DialogueId = 80200027,
          FinalCamera = "-298.00293,935.355347,618.705078,0.000024,-30.199797,-77.19545,30.0,1011.382263,false,Manual,1.2",
          GUID = "C8C5B8EE",
          NextOptions = {
            [1] = 802000271,
            [2] = 802000272,
            [3] = 802000273
          },
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 20
        },
        [80200029] = {
          ContentJP = "……ありがとう。あなたにとっては些細なことでも、私にとっては、胸に刻んでおきたいほどの恩です。",
          DialogueId = 80200029,
          GUID = "C8C5B942",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200031] = {
          ContentJP = "えっ……そ、そこまで信頼してくださるのですか？ちょ、ちょっと……そんなに慌てて上着を脱がなくても……",
          DialogueId = 80200031,
          GUID = "C8C5B996",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200033] = {
          ContentJP = "まさか、そんな無茶は言いませんよ。けれど……それはつまり、承諾してくれるということですね？",
          DialogueId = 80200033,
          GUID = "C8C5B9EA",
          NextDialogue = 80200034,
          SpeakNpcId = 790053
        },
        [80200034] = {
          Camera = "-12.930632,116.6409,137.194336,0.000094,6.600558,-127.588852,45.000011,194.999756,false,DoNotOverride,7.870067",
          ContentJP = "……ありがとうございます。では、全力で診させていただきます。",
          DialogueId = 80200034,
          GUID = "C8C5BA14",
          NextDialogue = 80200035,
          SpeakNpcId = 790053
        },
        [80200035] = {
          ContentJP = "フーシュが丁寧にあなたを診察する",
          DialogueId = 80200035,
          GUID = "C8C5BA3E",
          IsBlack = 1
        },
        [80200036] = {
          Camera = "-40.848995,85.709183,149.865234,0.000094,1.200781,-124.785934,45.000011,194.999756,false,DoNotOverride,7.870067",
          ContentJP = "……ふむ。体の調子自体は、問題なさそうですね。少なくとも、大きな異常は見当たりませんでした。ただ……",
          DialogueId = 80200036,
          FinalCamera = "-27.404249,104.783081,149.896484,0.000094,0.000697,-124.58551,45.000023,194.999756,false,DoNotOverride,7.870067",
          GUID = "C8C5BA68",
          NextDialogue = 80200037,
          SpeakNpcId = 790053,
          ToFinalCameraBlendTime = 4
        },
        [80200037] = {
          Camera = "-77.972321,4.005304,157.167969,0.000114,-5.999071,62.412296,45.000011,194.999756,false,Manual,7.870067",
          ContentJP = "顔色ではわかりにくいのですが…もしかして、かなり長いこと、眠れていないのではありませんか？",
          DialogueId = 80200037,
          GUID = "C8C5BA92",
          NextOptions = {
            [1] = 802000371,
            [2] = 802000372,
            [3] = 802000373
          },
          SpeakNpcId = 790053
        },
        [80200039] = {
          Camera = "86.032745,191.327408,140.46875,0.000115,0.600701,-140.191589,45.000011,194.999756,false,Manual,7.870067",
          ContentJP = "このままでは、後々に影響が出るかもしれません。もし眠る場所がないようなら、この枯栄閣を使っても構いませんよ。一時の寝床くらいにはなりますから。",
          DialogueId = 80200039,
          GUID = "C8C5BAE6",
