        },
        [80200215] = {
          ContentJP = "幻覚：枯栄閣の中、フーフォン登場",
          DialogueId = 80200215,
          GUID = "C8C5D18A"
        },
        [80200216] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "……頭が……ここって……枯栄閣？",
