          NextDialogue = 80200217,
          SpeakNpcId = 790008
        },
        [80200217] = {
          ContentJP = "あれは……フーシュ……？",
          DialogueId = 80200217,
          GUID = "C8C5D1DE",
          NextDialogue = 80200218,
          SpeakNpcId = 790008
        },
        [80200218] = {
          ContentJP = "めんどくさい、めんどくさい、めんどくさいっ！",
          DialogueId = 80200218,
          GUID = "C8C5D208",
          NextDialogue = 80200219,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200219] = {
          ContentJP = "朝起きたとき、今日は絶対に妹にキレないって決めたのに！なんで朝ごはんすら終わってないのに破ってんのよ、私！",
          DialogueId = 80200219,
          GUID = "C8C5D232",
          NextDialogue = 80200220,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200220] = {
          ContentJP = "ったく……どれだけせっかちなんだよ私！どんなに無愛想でも、結局あの子は私の妹だから。放っておくわけにはいかないし……いつも彼女を怒らせてどうする気なのよ。",
          DialogueId = 80200220,
          GUID = "C8C5D25C",
          NextDialogue = 80200221,
          SpeakNpcId = 790054,
          SpeakNpcName = "？？？"
        },
        [80200221] = {
          ContentJP = "だけど、フーシュのあの生真面目な姿、あまりにもばかばかしくてしようがなくなるよね……あの子の笑顔、こっちで預かっとけよ。",
          DialogueId = 80200221,
          GUID = "C8C5D286",
          NextDialogue = 80200222,
          SpeakNpcId = 790054
        },
        [80200222] = {
          ContentJP = "まぁまぁ、人間として当然のこと……",
          DialogueId = 80200222,
          GUID = "C8C5D2B0",
          NextDialogue = 80200223,
          SpeakNpcId = 790054
        },
        [80200223] = {
          ContentJP = "……フーシュ？",
          DialogueId = 80200223,
          GUID = "C8C5D2DA",
          NextDialogue = 80200224,
          SpeakNpcId = 790008
        },
        [80200224] = {
          ContentJP = "違うわ！私はフーシュの双子の姉、フーフォンよ。妹と間違える人、けっこういるの。",
          DialogueId = 80200224,
          GUID = "C8C5D304",
          NextDialogue = 80200225,
          SpeakNpcId = 790054
        },
        [80200225] = {
          ContentJP = "それにしても、あの子に知り合いがいるなんてね。あんな陰気なキノコ女に……びっくりだわ。",
          DialogueId = 80200225,
          GUID = "C8C5D32E",
          NextOptions = {
            [1] = 802002251,
            [2] = 802002252,
            [3] = 802002253
          },
          SpeakNpcId = 790054
        },
        [80200226] = {
          ContentJP = "へぇ……あんた、いいセンスしてるじゃない。フーシュの友だちは私の友だちよ！",
          DialogueId = 80200226,
          GUID = "C8C5D382",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200227] = {
          ContentJP = "はあ！？まさかここにまで取り立てに来たの！？あの子、銭勘定なんてできないし、小銭の音にすらびっくりするレベルよ？騙そうったってそうはいかないんだからね！",
          DialogueId = 80200227,
          GUID = "C8C5D3D6",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200228] = {
          ContentJP = "うへぇ、軽い……あんた、もし病気じゃないなら、帰って寝な！",
          DialogueId = 80200228,
          GUID = "C8C5D42A",
          NextDialogue = 80200229,
          SpeakNpcId = 790054
        },
        [80200229] = {
          ContentJP = "で、本題。あんたがここに来た理由、聞かせてくれる？",
          DialogueId = 80200229,
          GUID = "C8C5D454",
          NextDialogue = 80200230,
          SpeakNpcId = 790054
        },
        [80200230] = {
          ContentJP = "音容草をうっかり食べちゃって……頭がふわふわするし、変な幻も見えてる。たぶんフーシュなら治せると思って、助けを求めに来たんだ。",
          DialogueId = 80200230,
          GUID = "C8C5D47E",
          NextDialogue = 80200231,
          SpeakNpcId = 790008
        },
        [80200231] = {
          ContentJP = "タイミングが悪いわね。フーシュ、今ちょっとご機嫌斜めでさ。でも、私も一応医師だし、代わりに診てあげる。",
          DialogueId = 80200231,
          GUID = "C8C5D4A8",
          NextDialogue = 80200232,
          SpeakNpcId = 790054
        },
        [80200232] = {
          ContentJP = "うん……",
          DialogueId = 80200232,
          GUID = "C8C5D4D2",
          NextDialogue = 80200233,
          SpeakNpcId = 790054
        },
        [80200233] = {
          ContentJP = "足取りもまあまあ、目の焦点も合ってるし、ろれつも回ってる。あの葉っぱ、半分くらいしか食べてないでしょ？",
          DialogueId = 80200233,
          GUID = "C8C5D4FC",
          NextDialogue = 80200234,
          SpeakNpcId = 790054
        },
        [80200234] = {
          ContentJP = "症状は軽めだね。もうちょっとで薬草の解毒が終わるから、安心してな。",
          DialogueId = 80200234,
          GUID = "C8C5D526",
          NextDialogue = 80200235,
          SpeakNpcId = 790054
        },
        [80200235] = {
          ContentJP = "我慢できなかったら、橘と枳の丸薬があるから言って。",
          DialogueId = 80200235,
          GUID = "C8C5D550",
          NextDialogue = 80200236,
          SpeakNpcId = 790054
        },
        [80200236] = {
          ContentJP = "……で、推測だけど。あんた、寝つき悪いとか、夢見がちとか、あるでしょ？それで憶夢草を探してたんじゃないの？でも、間違って音容草を食べたってわけ。",
          DialogueId = 80200236,
          GUID = "C8C5D57A",
          NextDialogue = 80200237,
          SpeakNpcId = 790054
        },
        [80200237] = {
          ContentJP = "でも、その症状は、地伏せ枝と隙間で咲く花の方がいいと思うな。憶夢草はたしかに眠れるけど、夢の中に忘れたい記憶が出てくるのよ。むしろ心の傷をえぐりかねない。",
          DialogueId = 80200237,
          GUID = "C8C5D5A4",
          NextDialogue = 80200238,
          SpeakNpcId = 790054
        },
        [80200238] = {
          ContentJP = "……見た目のことは置いといて、あなたとフーシュ、たしかに似てるね。",
          DialogueId = 80200238,
          GUID = "C8C5D5CE",
          NextDialogue = 80200239,
          SpeakNpcId = 790008
        },
        [80200239] = {
          ContentJP = "ふふっ、そんなこと言われたの、初めてかも。双子だけど、みんな私のことは「出来損ない」って言うからさ。ほら、大風九章の第九条とも相性悪いし。",
          DialogueId = 80200239,
          GUID = "C8C5D5F8",
          NextDialogue = 80200240,
          SpeakNpcId = 790054
        },
        [80200240] = {
          ContentJP = "フーシュは静かでどこか疎遠な感じ。あなたは明るくてちょっとガサツだけど、診察のときの真面目さと優しさ、あれは本当に似てる。",
          DialogueId = 80200240,
          GUID = "C8C5D622",
          NextDialogue = 80200241,
          SpeakNpcId = 790008
        },
        [80200241] = {
          ContentJP = "……そっか。あんた、ほんとにあの子と仲いいのね。",
          DialogueId = 80200241,
          GUID = "C8C5D64C",
          NextDialogue = 80200242,
          SpeakNpcId = 790054
        },
        [80200242] = {
          ContentJP = "あの子、不器用で、思ってることなかなか言えない子だから。言っても全然的外れだったりしてさ。",
          DialogueId = 80200242,
          GUID = "C8C5D676",
          NextDialogue = 80200243,
          SpeakNpcId = 790054
        },
        [80200243] = {
          ContentJP = "でも、あんたみたいに分かってくれる人がいるなら、あの子もきっと救われる。",
          DialogueId = 80200243,
          GUID = "C8C5D6A0",
          NextDialogue = 80200244,
          SpeakNpcId = 790054
        },
        [80200244] = {
          ContentJP = "まったく、姉のくせに口ばっかりの私が先に謝っとくよ。ごめんね。",
          DialogueId = 80200244,
          GUID = "C8C5D6CA",
          NextDialogue = 80200245,
          SpeakNpcId = 790054
        },
        [80200245] = {
          ContentJP = "さて、フーシュの友だちさん。ちょっとお願いがあるんだけど、聞いてくれるよね？",
          DialogueId = 80200245,
          GUID = "C8C5D6F4",
          NextDialogue = 80200246,
          SpeakNpcId = 790054
        },
        [80200246] = {
          ContentJP = "うん、話してみて。",
          DialogueId = 80200246,
          GUID = "C8C5D71E",
          NextDialogue = 80200247,
          SpeakNpcId = 790008
        },
        [80200247] = {
          ContentJP = "フーシュに、謝りたいことがあるの。そのための贈り物を、代わりに取ってきてもらえない？",
          DialogueId = 80200247,
          GUID = "C8C5D748",
          NextDialogue = 80200248,
          SpeakNpcId = 790054
        },
        [80200248] = {
          ContentJP = "ここからそう遠くない水辺に、「コトブキイカ」がよく出るの。釣ってきてくれるかな、あんたなら楽勝でしょ？",
          DialogueId = 80200248,
          GUID = "C8C5D772",
          SpeakNpcId = 790054
        },
        [80200301] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "わっ、マジで釣れた！？すごいじゃん。この万能な私でも、一日粘って一匹も釣れないのにさ〜！",
          DialogueId = 80200301,
          GUID = "C8C5E5E2",
          NextDialogue = 80200302,
          SpeakNpcId = 790054
        },
        [80200302] = {
          ContentJP = "万能……？",
          DialogueId = 80200302,
          GUID = "C8C5E60C",
          NextDialogue = 80200303,
          SpeakNpcId = 790008
        },
        [80200303] = {
          ContentJP = "そういえば、フーシュにあなたの絵、見せてもらったよ。……なんていうか、すごく……抽象的だね。",
          DialogueId = 80200303,
          GUID = "C8C5E636",
          NextDialogue = 80200304,
          SpeakNpcId = 790008
        },
        [80200304] = {
          ContentJP = "……ちょっと待って、それ見せる？あの子は……まったく！！",
          DialogueId = 80200304,
          GUID = "C8C5E660",
          NextDialogue = 80200305,
          SpeakNpcId = 790054
        },
        [80200305] = {
          ContentJP = "ゴホン……でも、彼女がコトブキイカ好きってのは初耳だったな。",
          DialogueId = 80200305,
          GUID = "C8C5E68A",
          NextDialogue = 80200306,
          SpeakNpcId = 790008
        },
        [80200306] = {
          ContentJP = "別に好きじゃないよ〜",
          DialogueId = 80200306,
          GUID = "C8C5E6B4",
          NextDialogue = 80200307,
          SpeakNpcId = 790054
        },
        [80200307] = {
          ContentJP = "あれのせいで、子どもの頃、泣いたんだから。トラウマ級だね。",
          DialogueId = 80200307,
          GUID = "C8C5E6DE",
          NextOptions = {
            [1] = 802003071,
            [2] = 802003072,
            [3] = 802003073
          },
          SpeakNpcId = 790054
        },
        [80200311] = {
          ContentJP = "……ぶっちゃけ最近も、何回か言い合いしたの。あんたもなんとなく分かるでしょ？",
          DialogueId = 80200311,
          GUID = "C8C5E786",
          NextDialogue = 80200312,
          SpeakNpcId = 790054
        },
        [80200312] = {
          ContentJP = "私は、新しい治療法を試したくて。でも、あの子は枯栄の術を守るべきって言うの。",
          DialogueId = 80200312,
          GUID = "C8C5E7B0",
          NextDialogue = 80200313,
          SpeakNpcId = 790054
        },
        [80200313] = {
          ContentJP = "正直、どっちにも言い分はあるんだけどさ。私の方法は、成果も分かんないし、大風九章に背いてる……",
          DialogueId = 80200313,
          GUID = "C8C5E7DA",
          NextDialogue = 80200314,
          SpeakNpcId = 790054
        },
        [80200314] = {
          ContentJP = "この先どうなるかなんて、自分でも分かんない。",
          DialogueId = 80200314,
          GUID = "C8C5E804",
          NextDialogue = 80200315,
          SpeakNpcId = 790054
        },
        [80200315] = {
          ContentJP = "でもね、一つだけ確かなことがある。——今のまま術を使い続けたら、あの子は……きっと、死んでしまう。",
          DialogueId = 80200315,
          GUID = "C8C5E82E",
          NextDialogue = 80200316,
          SpeakNpcId = 790054
        },
        [80200316] = {
          ContentJP = "だから、絶対譲れないの。ケンカになったって、止まれないんだよ。",
          DialogueId = 80200316,
          GUID = "C8C5E858",
          NextDialogue = 80200317,
          SpeakNpcId = 790054
        },
        [80200317] = {
          ContentJP = "はあ……姉の苦労も知らないでさ。謝るのはこっちの役目でも、楽はさせたくないっての！",
          DialogueId = 80200317,
          GUID = "C8C5E882",
          NextDialogue = 80200318,
          SpeakNpcId = 790054
        },
        [80200318] = {
          ContentJP = "でも、もう近づくのは禁止されてるからさ。この子たち——おともだちイカちゃんは、あんたから渡して。あの子、あんたにはガード甘いし、もしかしたらまた泣いてくれるかも……ふふっ。",
          DialogueId = 80200318,
          GUID = "C8C5E8AC",
          NextOptions = {
            [1] = 80200319
          },
          SpeakNpcId = 790054
        },
        [80200319] = {
          ContentJP = "コトブキイカ……",
          DialogueId = 80200319,
          GUID = "C8C5E8D6",
          NextDialogue = 80200320
        },
        [80200320] = {
          ContentJP = "……つまりさ。彼女に「長生きしてほしい」って、遠回しに伝えたいんでしょ？",
          DialogueId = 80200320,
          GUID = "C8C5E900",
          NextDialogue = 80200321,
          SpeakNpcId = 790008
        },
        [80200321] = {
          ContentJP = "うっ……そ、そういうのは……言っちゃダメなの！バレてても、黙っててくれないと、台無しでしょ！？私は、あの子がムッとする顔、見たいだけなんだから〜！",
          DialogueId = 80200321,
          GUID = "C8C5E92A",
          NextDialogue = 80200322,
          SpeakNpcId = 790054
        },
        [80200322] = {
          ContentJP = "さっさと行って、ほらほら！",
          DialogueId = 80200322,
          GUID = "C8C5E954",
          SpeakNpcId = 790054
        },
        [80200323] = {
          ContentJP = "幻境終了。採薬クエストポイント1に戻る。",
          DialogueId = 80200323,
          GUID = "C8C5E97E"
        },
        [80200324] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "——目が覚めたのですね！",
          DialogueId = 80200324,
          GUID = "C8C5E9A8",
          NextDialogue = 80200325,
          SpeakNpcId = 790053
        },
        [80200325] = {
          ContentJP = "ほんの三、四分のはずだったのに、どうにも心配で……本の記述を見間違えたのかと思ったわ。毒性、もっと強かったかもって。",
          DialogueId = 80200325,
          GUID = "C8C5E9D2",
          NextDialogue = 80200326,
          SpeakNpcId = 790053
        },
        [80200326] = {
          ContentJP = "枯栄の術を試そうとしたの。でも、術が終わる前に、あなたのほうが先に目覚めるんじゃないかって……",
          DialogueId = 80200326,
          GUID = "C8C5E9FC",
          NextDialogue = 80200327,
          SpeakNpcId = 790053
        },
        [80200327] = {
          ContentJP = "あなたとフーフォン、やっぱり似てるね。",
          DialogueId = 80200327,
          GUID = "C8C5EA26",
          NextDialogue = 80200328,
          SpeakNpcId = 790008
        },
        [80200328] = {
          ContentJP = "……まさか、姉に会ったのですか？",
          DialogueId = 80200328,
          GUID = "C8C5EA50",
          NextDialogue = 80200329,
          SpeakNpcId = 790053
        },
        [80200329] = {
          ContentJP = "うん。昔の話、覚えてる？喧嘩して、謝るために、あなたの一番嫌いなコトブキイカをプレゼントしたって。",
          DialogueId = 80200329,
          GUID = "C8C5EA7A",
          NextDialogue = 80200330,
          SpeakNpcId = 790008
        },
        [80200330] = {
          ContentJP = "……そんなことも、あったかもしれませんね。もう、すっかり忘れていました。もうずいぶん前のことでしたし。",
          DialogueId = 80200330,
          GUID = "C8C5EAA4",
          NextDialogue = 80200331,
          SpeakNpcId = 790053
        },
        [80200331] = {
          ContentJP = "で、許してあげたの？",
          DialogueId = 80200331,
          GUID = "C8C5EACE",
          NextDialogue = 80200332,
          SpeakNpcId = 790008
        },
        [80200332] = {
          ContentJP = "ふふ……いいえ。またひと悶着しました。あのときは、後悔してなかったのですが——",
          DialogueId = 80200332,
          GUID = "C8C5EAF8",
          NextDialogue = 80200333,
          SpeakNpcId = 790053
        },
        [80200333] = {
          ContentJP = "今の私なら、もしかしたら、あのイカを受け取ったかもしれません。",
          DialogueId = 80200333,
          GUID = "C8C5EB22",
          NextDialogue = 80200334,
          SpeakNpcId = 790053
        },
        [80200334] = {
          ContentJP = "……「もしかしたら」ですけどね。多足類は、今も本当に苦手なんです。",
          DialogueId = 80200334,
          GUID = "C8C5EB4C",
          NextDialogue = 80200335,
          SpeakNpcId = 790053
        },
        [80200335] = {
          ContentJP = "でも、本当は……こんな過去、あなたに見せるべきじゃなかったのかもしれません。もう還らない人のことなんて、思い出しても切なくなるだけですもの。",
          DialogueId = 80200335,
          GUID = "C8C5EB76",
          NextDialogue = 80200336,
          SpeakNpcId = 790053
        },
        [80200336] = {
          ContentJP = "だけど、ここは……私たちが育った場所。枯栄閣にある音容草のすべてに、きっと私たちの記憶が眠っているんです。",
          DialogueId = 80200336,
          GUID = "C8C5EBA0",
          NextDialogue = 80200337,
          SpeakNpcId = 790053
        },
        [80200337] = {
          ContentJP = "だから、次は……私が、自分で確かめたいんです。よろしいですか？",
          DialogueId = 80200337,
          GUID = "C8C5EBCA",
          NextOptions = {
            [1] = 802003371,
            [2] = 802003372
          },
          SpeakNpcId = 790053
        },
        [80200339] = {
          ContentJP = "ありがとうございます。",
          DialogueId = 80200339,
          GUID = "C8C5EC1E",
          NextDialogue = 80200342,
          SpeakNpcId = 790054
        },
        [80200341] = {
          ContentJP = "ふふっ、また今度会ったときに話してあげますね。",
          DialogueId = 80200341,
          GUID = "C8C5EC72",
          NextDialogue = 80200342,
          SpeakNpcId = 790054
        },
        [80200342] = {
          ContentJP = "さあ、次の場所へ行きましょう。",
          DialogueId = 80200342,
          GUID = "C8C5EC9C",
          SpeakNpcId = 790053
        },
        [80200343] = {
          ContentJP = "場面転換：枯栄閣・野外",
          DialogueId = 80200343,
          GUID = "C8C5ECC6"
        },
        [80200344] = {
          Camera = "106.860352,-6.606262,131.715088,0.0,-0.799959,-137.395889,30.0,125.0,false,Manual,2.8",
          ContentJP = "見つけました。",
          DialogueId = 80200344,
          GUID = "C8C5ECF0",
          NextDialogue = 80200345,
          SpeakNpcId = 790053
        },
        [80200345] = {
          ContentJP = "さて、これは音容草でしょうか、それとも憶夢草……？",
          DialogueId = 80200345,
          GUID = "C8C5ED1A",
          NextOptions = {
            [1] = 802003451,
            [2] = 802003452
          },
          SpeakNpcId = 790053
        },
        [80200348] = {
          ContentJP = "見た目には大差ありませんが、手で触れると、ほんのわずかに違いを感じます。……恐らく、これは憶夢草でしょう。",
          DialogueId = 80200348,
          GUID = "C8C5ED98",
          NextDialogue = 80200349,
          SpeakNpcId = 790053
        },
        [80200349] = {
          ContentJP = "もし、あのとき二度も失敗していなければ、この違いには気づけなかったかもしれません。",
          DialogueId = 80200349,
          GUID = "C8C5EDC2",
          NextDialogue = 80200350,
          SpeakNpcId = 790053
        },
        [80200350] = {
          ContentJP = "最初にこれを見分けた人って、どうやって判断したんだろ？もしかして、{性别:僕|私}たちみたいに手探りで試したのかな。",
          DialogueId = 80200350,
          GUID = "C8C5EDEC",
          NextDialogue = 80200351,
          SpeakNpcId = 790008
        },
        [80200351] = {
          ContentJP = "ふふ……そうかもしれませんね。",
          DialogueId = 80200351,
          GUID = "C8C5EE16",
          NextDialogue = 80200352,
          SpeakNpcId = 790053
        },
        [80200352] = {
          ContentJP = "おそらく、数えきれないほどの危険を乗り越え、眠れぬ夜を過ごし、理解されず、傷つくこともあったでしょう。それでも決して諦めなかった。",
          DialogueId = 80200352,
          GUID = "C8C5EE40",
          NextDialogue = 80200353,
          SpeakNpcId = 790053
        },
        [80200353] = {
          ContentJP = "すべては——何百年も受け継がれてきた、「人を癒す」という、たった一つの理想のために。",
          DialogueId = 80200353,
          GUID = "C8C5EE6A",
          NextDialogue = 80200354,
          SpeakNpcId = 790053
        },
        [80200354] = {
          ContentJP = "そういえば、フーフォンが言ってたよ。地伏せ枝と隙間で咲く花の方が、不眠には合ってるって。",
          DialogueId = 80200354,
          GUID = "C8C5EE94",
          NextDialogue = 80200355,
          SpeakNpcId = 790008
        },
        [80200355] = {
          ContentJP = "憶夢草は眠れるけど、忘れたくない夢を見てしまうってさ。",
          DialogueId = 80200355,
          GUID = "C8C5EEBE",
          NextDialogue = 80200356,
          SpeakNpcId = 790008
        },
        [80200356] = {
          ContentJP = "つまり、僕には憶夢草はもう必要ないわけだけど。……それでも、試すの？",
          DialogueId = 80200356,
          GUID = "C8C5EEE8",
          NextDialogue = 80200357,
          SpeakNpcId = 790008
        },
        [80200357] = {
          ContentJP = "フーシュは答えず、静かにその葉の先を口に含んだ。そこにあったのは、不安でも、迷いでもなく——穏やかな呼吸と、優しい寝言だった。",
          DialogueId = 80200357,
          GUID = "C8C5EF12",
          IsBlack = 1,
          NextDialogue = 80200358
        },
        [80200358] = {
          ContentJP = "……はあ……次はもう少し、まともなお詫びの品にしてほしいですね。",
          DialogueId = 80200358,
          GUID = "C8C5EF3C",
          SpeakNpcId = 790053
        },
        [88888801] = {
          DialogueId = 88888801,
          DialoguePanelType = "None",
          Duration = 5,
          GUID = "DE8616EA",
          Scripts = "SEQ{SetRotation{SetRotationDescription{\"888888:n(0)\"}},PlayAnimation{ActorId{0},AnimationId{\"Cat_Interactive01\"}}}",
          SpeakNpcId = 888888,
