          RandomOptionNum = 3,
          SpeakNpcId = 83101,
          VoiceName = "voice/$Locale$/char/Linen/vo_welcome",
          bForbidSkipOptions = true
        },
        [90130002] = {
          ContentJP = "別の話にしようか。",
          DialogueId = 90130002,
          GUID = "90130002.0",
          NextDialogue = 90130001
        },
        [90130003] = {
          ContentJP = "それじゃあ、また。",
