            [3] = 901400013,
            [4] = 901400014,
            [5] = 901400015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_welcome",
          bForbidSkipOptions = true
        },
        [90140002] = {
          ContentJP = "別の話にしようか。",
          DialogueId = 90140002,
          GUID = "90140002.0",
          NextDialogue = 90140001
        },
        [90140003] = {
          ContentJP = "それじゃあ、また。",
          DialogueId = 90140003,
          GUID = "90140003.0"
        },
        [90140101] = {
          ContentJP = "ご明察です。霧がかかる日が多くて、洗濯物が乾かないうえに、ホコリで汚れてしまいます。",
          DialogueId = 90140101,
          GUID = "E1A80252",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140103,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Talk01_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_01_1"
        },
        [90140103] = {
          ContentJP = "しかも、よからぬことを企み、霧に紛れてフローラ様に近づく「汚れ」も増えますので。",
          DialogueId = 90140103,
          GUID = "E1A802A6",
          NextDialogue = 90140104,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_01_2"
        },
        [90140104] = {
          ContentJP = "じゃあ晴れの日が好きってこと？",
          DialogueId = 90140104,
          GUID = "E1A802D0",
          NextDialogue = 90140105,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83102:Talk01_End"
          }
        },
        [90140105] = {
          ContentJP = "洗濯日和と考えれば、晴天は好ましいのですが。フローラ様と私の行動が人目につきやすいとも論じられます——結局どのような天気であれど、私にとっては悪天なのです。悪しき日かそれ以上に悪しき日かの違いだけです。",
          DialogueId = 90140105,
          GUID = "E1A802FA",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90140201] = {
          ContentJP = "そんな当たり前のことが気になりますので？一介のメイドとして戦いを嗜むのは至極当然でございます。",
          DialogueId = 90140201,
          GUID = "E1A812BA",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140203,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_02_1"
        },
        [90140203] = {
          ContentJP = "{性别:僕の知ってるメイドと違う。普通は大きなお屋敷を掃除するとかじゃない？|私の知ってるメイドと違う。普通は大きなお屋敷を掃除するとかじゃない？}",
          DialogueId = 90140203,
          GUID = "E1A8130E",
          NextDialogue = 90140204,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83102:Confident_End"
          }
        },
        [90140204] = {
          ContentJP = "私の目には、目障りに飛びまわるハエも<Default note=\"text:エジュウ\">穢獣</>も、掃いて捨てるべき汚れにしか映りません。戦闘は、私にとって掃除という愉快な作業にすぎないのです。",
          DialogueId = 90140204,
          GUID = "E1A81338",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90140301] = {
          ContentJP = "物騒？と申されましても何が何やら……曖昧な示唆ではなく、具体的な名称で仰ってくだされば。",
          DialogueId = 90140301,
          GUID = "E1A82322",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140303,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_03_1"
        },
        [90140303] = {
          ContentJP = "銃だよ、銃！とんでもない数の銃を買ってるよね！？",
          DialogueId = 90140303,
          GUID = "E1A82376",
          NextDialogue = 90140304,
          SpeakNpcId = 100001
        },
        [90140304] = {
          ContentJP = "……えぇ、認めます。私は銃が好きですよ。日常的に使うメイドの掃除道具の中でも、一番手にしっくりきますし、最も効率よく「汚れ」を排除することができますからね。",
          DialogueId = 90140304,
          GUID = "E1A823A0",
          NextDialogue = 90140305,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_03_2"
        },
        [90140305] = {
          ContentJP = "ストレスが溜まっているのであれば、何丁かお貸ししても構いません。ダダダダダッと嗜めば気も晴れますかと。",
          DialogueId = 90140305,
          GUID = "E1A823CA",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90140401] = {
          ContentJP = "ああ、そのような噂が流布されても不思議ではございませんね。どうでもいい方々と無駄な雑談をする趣味は持ちあわせておりませんので。",
          DialogueId = 90140401,
          GUID = "E1A8338A",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140403,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_04_1"
        },
        [90140403] = {
          ContentJP = "{性别:ん？でも僕たちけっこう長いことおしゃべりしてるよね。|ん？でも私たちけっこう長いことおしゃべりしてるよね。}",
          DialogueId = 90140403,
          GUID = "E1A833DE",
          NextDialogue = 90140404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83102:Think_End"
          }
        },
        [90140404] = {
          ContentJP = "誤解なきよう。相応の報酬をお支払いいただいているからこその態度でございます。いつかあなたが一文無しになれば、見捨てるかもしれませんね。",
          DialogueId = 90140404,
          GUID = "E1A83408",
          NextDialogue = 90140405,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_04_2"
        },
        [90140405] = {
          ContentJP = "あの、それは、悲しい……",
          DialogueId = 90140405,
          GUID = "E1A83432",
          NextDialogue = 90140406,
          SpeakNpcId = 100001
        },
        [90140406] = {
          ContentJP = "ご心配には及びません。そのような窮地には私がさせませんから。信じてくださいませ。",
          DialogueId = 90140406,
          GUID = "E1A8345C",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90140501] = {
          ContentJP = "え？ど……どちらに？本日のご予定では、こちらにはいらっしゃらないはず……",
          DialogueId = 90140501,
          GUID = "E1A843F2",
          LookAt = {
            [1] = "83102:n(0)",
            [2] = "0:n(83102)"
          },
          NextDialogue = 90140503,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_1"
        },
        [90140503] = {
          ContentJP = "騙しやがりましたね。",
          DialogueId = 90140503,
          GUID = "E1A84446",
          NextDialogue = 90140504,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_2"
        },
        [90140504] = {
          ContentJP = "ちょっと慌てすぎじゃない？",
          DialogueId = 90140504,
          GUID = "E1A84470",
          NextDialogue = 90140505,
          SpeakNpcId = 100001
        },
        [90140505] = {
          ContentJP = "いいえ、お嬢様は最優先事項なのです。もったいないことですが、私にとってフローラ様はご主人様というだけでなく、別の絆で結ばれた方でもいらっしゃいます。ですので……",
          DialogueId = 90140505,
          GUID = "E1A8449A",
          NextDialogue = 90140506,
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_3"
        },
        [90140506] = {
          ContentJP = "残念ながら私は吟遊詩人ではありませんので、友人と家族の意味を兼ねそなえた言葉を寡聞にして存じませんが……",
          DialogueId = 90140506,
          GUID = "E1A844C4",
          NextDialogue = 90140507,
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_4"
        },
        [90140507] = {
          ContentJP = "そういう気持ちは、言葉がなくても伝わると思うな。",
          DialogueId = 90140507,
          GUID = "E1A844EE",
          NextDialogue = 90140508,
          SpeakNpcId = 100001
        },
        [90140508] = {
          ContentJP = "フローラ様に知っていたただくつもりはありません——ご主人様の進む道を掃除するのがメイドの務めでございますから。お嬢様のために働けるだけで極めて光栄なことです。",
          DialogueId = 90140508,
          GUID = "E1A84518",
          NextOptions = {
            [1] = 90140002,
            [2] = 90140003
          },
          SpeakNpcId = 83102,
          TalkActionId = {
            [1] = "83102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Xier/vo_topic_05_5",
          bForbidSkipOptions = true
        },
        [90140601] = {
          Content = "我最喜欢的花，生长在恒温的穹顶下。只需一片花瓣就可以制成安神的晚茶，而十片花瓣，又可以萃出一滴让人长眠的毒液。偶尔在梦里我还会修剪那片花圃，而醒来后，我会庆幸不用再照料它们。",
          DialogueId = 90140601,
          GUID = "E1A8545A",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_01"
        },
        [90140701] = {
          ContentJP = "まぁ、すごい！心の底から尊敬いたしますわ！常日頃から果てなき大志を抱き、思索に耽っていらっしゃるのですね！私のような、目の前の些事をこなすことで精いっぱいのメイドにはとてもとても！",
          DialogueId = 90140701,
          GUID = "E1A864C2",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_02"
        },
        [90140801] = {
          ContentJP = "不要品の処分は、予てから悩みの種でした。引き取ってくださるのであれば、とても喜ばしいことでございます。ただしお部屋に入られる前に、入浴サービスを提供させていただきますので。拒否権はございません。抵抗も許しません。",
          DialogueId = 90140801,
          GUID = "E1A8752A",
          SpeakNpcId = 83102,
          VoiceName = "voice/$Locale$/char/Xier/vo_companio_03"
        },
        [90150000] = {
          ContentJP = "～～♪ ちいちゃなちいさな私の家、金の小川のそば。暖炉はぱちぱち暖かで、パパが作ったブリキの人形、ママが歌う子守歌。さあみんなでおやすみ。",
          DialogueId = 90150000,
          GUID = "E1AE5A8B",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_idle"
        },
        [90150001] = {
          ContentJP = "……あっ……あなたは。こんにちは、どうも。",
          DialogueId = 90150001,
          GUID = "E1AE5A8A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextOptions = {
            [1] = 901500011,
            [2] = 901500012,
            [3] = 901500013,
            [4] = 901500014,
            [5] = 901500015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_welcome",
          bForbidSkipOptions = true
        },
        [90150002] = {
          ContentJP = "別の話にしようか。",
          DialogueId = 90150002,
          GUID = "90150002.0",
          NextDialogue = 90150001
        },
        [90150003] = {
          ContentJP = "それじゃあ、また。",
          DialogueId = 90150003,
          GUID = "90150003.0"
        },
        [90150101] = {
          ContentJP = "えっとね、背が伸びるキャンディーがあったらなって考えてたの。もしあるなら食べてみたいなあって……",
          DialogueId = 90150101,
          GUID = "E1AE6AF2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150103,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_1"
        },
        [90150103] = {
          ContentJP = "そしたら雲よりも背が高くなって、お空に浮かぶお星さまを、なでてあげられるでしょう？",
          DialogueId = 90150103,
          GUID = "E1AE6B46",
          NextDialogue = 90150104,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_2"
        },
        [90150104] = {
          ContentJP = "{性别:うっかり僕のことを踏み潰して、ぺっちゃんこに……？|うっかり私のことを踏み潰して、ぺっちゃんこに……？}",
          DialogueId = 90150104,
          GUID = "E1AE6B70",
          NextDialogue = 90150105,
          SpeakNpcId = 100001
        },
        [90150105] = {
          ContentJP = "そ、そんなことしないわ！気をつけるもの！でも……本当に心配なら、私の手の平に座るのはどうかしら？そうやって一緒にお散歩するの、素敵じゃないかな？",
          DialogueId = 90150105,
          GUID = "E1AE6B9A",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_01_3",
          bForbidSkipOptions = true
        },
        [90150201] = {
          ContentJP = "フィーナね、とっても大きなガラスの箱を持っているの。なかにはフワフワな白い雪……雪みたいに白いマシュマロが入っているわ。マシュマロみたいにフカフカな雲と、雲みたいに暖かい風をそこに入れたいの……",
          DialogueId = 90150201,
          GUID = "E1AE7B5A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150203,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_1"
        },
        [90150203] = {
          ContentJP = "みんなの笑顔も一緒に、ぜ～んぶ、箱の中に入れたいな。",
          DialogueId = 90150203,
          GUID = "E1AE7BAE",
          NextDialogue = 90150204,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_2"
        },
        [90150204] = {
          ContentJP = "いいね、入ってみたい。",
          DialogueId = 90150204,
          GUID = "E1AE7BD8",
          NextDialogue = 90150205,
          SpeakNpcId = 100001
        },
        [90150205] = {
          ContentJP = "うん、小さくなれるキャンディーを食べれば、なかに入って遊べるわ。でも……箱の中はどっちを向いても真っ白だから、迷子にならないように気をつけないと。",
          DialogueId = 90150205,
          GUID = "E1AE7C02",
          NextDialogue = 90150206,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_3"
        },
        [90150206] = {
          ContentJP = "もし迷子になったら、フィーナは助けに来てくれる？",
          DialogueId = 90150206,
          GUID = "E1AE7C2C",
          NextDialogue = 90150207,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81801:Think_Start"
          }
        },
        [90150207] = {
          ContentJP = "{性别:えっと、お兄さんが迷子になってしまったら……そしたらフィーナが、パンを小さくちぎって落としながら探しにいくわ！パンの欠片が道になって、たどっていけば出口が見つけられるはず！|えっと、お姉さんが迷子になってしまったら……そしたらフィーナが、パンを小さくちぎって落としながら探しにいくわ！パンの欠片が道になって、たどっていけば出口が見つけられるはず！}",
          DialogueId = 90150207,
          GUID = "E1AE7C56",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90150301] = {
          ContentJP = "うん……！夢の中で真っ白なナイチンゲールを見たわ。私のね、手に止まったり、部屋のなかでかくれんぼもしたの……うーん……でも夢を見ていたのはフィーナ？それとも、ナイチンゲールがフィーナの夢を見ていたのかしら……？",
          DialogueId = 90150301,
          GUID = "E1AE8BC2",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150303,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_1"
        },
        [90150303] = {
          ContentJP = "フィーナもナイチンゲールも、同じ夢を見たのかな？",
          DialogueId = 90150303,
          GUID = "E1AE8C16",
          NextDialogue = 90150304,
          SpeakNpcId = 100001
        },
        [90150304] = {
          ContentJP = "きっとそうだわ！あそこはワンダーランドだったのよ！眠っている子供、小さな動物のお友達、みんなで一緒に遊べる素敵な場所。ああ……次の夢では誰に出会えるのかしら？フクロウのおじいさん？カナリアのお嬢さん？それとも白ウサギさん？",
          DialogueId = 90150304,
          GUID = "E1AE8C40",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Agree"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90150401] = {
          ContentJP = "フィーナにはお母さんと、ふたりのお父さんがいたの。でもみんな、もういなくなっちゃった……",
          DialogueId = 90150401,
          GUID = "E1AE9C2A",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150402,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_1"
        },
        [90150402] = {
          ContentJP = "最初のお父さんは、お母さんと一緒に遠い遠い国へと行ったわ。2番目のお父さんも、遠い遠い国に行っちゃった……フィーナが連れていったのだけど。",
          DialogueId = 90150402,
          GUID = "E1AE9C54",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90150501] = {
          ContentJP = "アウトサイダーはね、世界で一番偉大な魔法使い。一番心地よい言葉を話す、世界で一番優しい人……",
          DialogueId = 90150501,
          GUID = "E1AEAC92",
          LookAt = {
            [1] = "81801:n(0)",
            [2] = "0:n(81801)"
          },
          NextDialogue = 90150503,
          SpeakNpcId = 81801,
          TalkActionId = {
            [1] = "81801:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_1"
        },
        [90150503] = {
          ContentJP = "……？",
          DialogueId = 90150503,
          GUID = "E1AEACE6",
          NextDialogue = 90150504,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "81801:Explain02_End"
          }
        },
        [90150504] = {
          ContentJP = "あれ、ハテナが頭に浮かんでいるみたいだけど、フィーナ、何か間違っているの？",
          DialogueId = 90150504,
          GUID = "E1AEAD10",
          NextDialogue = 90150505,
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_2"
        },
        [90150505] = {
          ContentJP = "{性别:少なくとも僕の知っているアウトサイダーとは別人だ。|少なくとも私の知っているアウトサイダーとは別人ね。}",
          DialogueId = 90150505,
          GUID = "E1AEAD3A",
          NextDialogue = 90150506,
          SpeakNpcId = 100001
        },
        [90150506] = {
          ContentJP = "{性别:え……じゃあアウトサイダーってお兄さんに優しくないの？本当にごめんなさい、私がデコピンして、態度を改めてもらうわ！|じゃあアウトサイダーってお姉さんに優しくないの？本当にごめんなさい、私がデコピンして、態度を改めてもらうわ！}",
          DialogueId = 90150506,
          GUID = "E1AEAD64",
          NextOptions = {
            [1] = 90150002,
            [2] = 90150003
          },
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90150601] = {
          ContentJP = "約束して。もう絶対に、絶対に絶対に……悪い呪い師がたくさんいる危険な場所には行かないで。いい？",
          DialogueId = 90150601,
          GUID = "E1AEBCFA",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_01"
        },
        [90150701] = {
          ContentJP = "それは……何？ハムスターのお姉さんが飼っている妖精？不思議……きっとお姉さんを乗せて、どんなお城の壁でも飛び越えてしまうのね？",
          DialogueId = 90150701,
          GUID = "E1AECD62",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_02"
        },
        [90150801] = {
          ContentJP = "ライオンのお姉さんは大剣の中に眠っている女神様を呼び覚ましたいのね？多分だけど、呪文をいっぱい唱えないといけないのかも。例えばーー「この聖剣サマエルを覚醒させし者は、エリュシオンの王となるであろう！」とか！",
          DialogueId = 90150801,
          GUID = "E1AEDDCA",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_03"
        },
        [90150901] = {
          ContentJP = "南の国から来たタツノオトシゴのお兄さん。どこかで会ったことある気が……あっ、思い出した！ずっとずっと昔、お父さんがお家にあなたの肖像画を飾っていたわ！",
          DialogueId = 90150901,
          GUID = "E1AEEE32",
          SpeakNpcId = 81801,
          VoiceName = "voice/$Locale$/char/Feina/vo_companio_04"
        },
        [90160000] = {
          ContentJP = "今のこの安心感も悪くない。何年も経ってやっと、ここに少しだけ居場所を感じられた。",
          DialogueId = 90160000,
          GUID = "E1B4C329",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_idle"
        },
        [90160001] = {
          ContentJP = "やっと来たか、残ってた用事は片付けといた。たいした稼ぎにもならないってのに、疲れて死にそうだ。あーあ、この家のために俺、必死だな。",
          DialogueId = 90160001,
          GUID = "E1B4C32A",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextOptions = {
            [1] = 901600011,
            [2] = 901600012,
            [3] = 901600013,
            [4] = 901600014,
            [5] = 901600015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_welcome",
          bForbidSkipOptions = true
        },
        [90160002] = {
          ContentJP = "別の話にしようか。",
          DialogueId = 90160002,
          GUID = "90160002.0",
          NextDialogue = 90160001
        },
        [90160003] = {
          ContentJP = "それじゃあ、また。",
          DialogueId = 90160003,
          GUID = "90160003.0"
        },
        [90160101] = {
          ContentJP = "マニュアルだぁ？あるわけないだろ？こんな仕事してる連中に本を読む根気があると思ってんのか？\nといっても、格言はいろいろあるがね。たとえば「体に2発入れた後に頭をぶん殴れ。そしたらどんな相手だってイチコロだ」、ってオレが考えた喧嘩のコツだけどな。",
          DialogueId = 90160101,
          GUID = "E1B4D392",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160103,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_1"
        },
        [90160103] = {
          ContentJP = "{性别:なんだかおもしろそう。他にはどんなのがあるんだ？|なんだかおもしろそう。他にはどんなのがあるの？}",
          DialogueId = 90160103,
          GUID = "E1B4D3E6",
          NextDialogue = 90160104,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Confident_Start"
          }
        },
        [90160104] = {
          ContentJP = "おーおーがっつくなって、美味いもんは一口ずつ噛みしめろよ。強欲がこの仕事の天敵なんだぜ？欲深さってやつは、他人からもらうより、たいがいは自分の心から生まれるもんだ。",
          DialogueId = 90160104,
          GUID = "E1B4D410",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_01_2",
          bForbidSkipOptions = true
        },
        [90160201] = {
          ContentJP = "あいつらは消えない野焼きの火さ。油断してると山ごと燃やされちまう。お前のために言っとくが、あんまりヤツらと関わるなよ……",
          DialogueId = 90160201,
          GUID = "E1B4E3FA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160203,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Talk03_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_1"
        },
        [90160203] = {
          ContentJP = "いつになく真剣だね……どうして？",
          DialogueId = 90160203,
          GUID = "E1B4E44E",
          NextDialogue = 90160204,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Talk03_End"
          }
        },
        [90160204] = {
          ContentJP = "そりゃあれだ……何度かトラブったことがあるからな。この先あいつらと関わることがあったとしても、絶対に俺の名前は出すんじゃないぞ。",
          DialogueId = 90160204,
          GUID = "E1B4E478",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_02_2",
          bForbidSkipOptions = true
        },
        [90160301] = {
          ContentJP = "まあちょいとな。そっちのガーゼを取ってくれないか？フィーナにバレたら、また口酸っぱく言われちまうからよ。",
          DialogueId = 90160301,
          GUID = "E1B4F462",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160303,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_1"
        },
        [90160303] = {
          ContentJP = "{性别:/フィーナはアウトサイダーのことが心配なんだよ。|フィーナはアウトサイダーのことが心配なのよ。}",
          DialogueId = 90160303,
          GUID = "E1B4F4B6",
          NextDialogue = 90160304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Explain02_End"
          }
        },
        [90160304] = {
          ContentJP = "わかっちゃいるんだけどさ、怪我なんざ仕事柄日常茶飯事だろ？あまり心配かけたくないんだよ。フィーナに聞かれたら誤魔化してくれって、な、今度、飯でも奢るから。",
          DialogueId = 90160304,
          GUID = "E1B4F4E0",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90160401] = {
          ContentJP = "お、食ってみないか？見た目はアレだけど、頭さえとっちまえば、クッキーみたいにサクサクだぞ。なんかちょっとだけ肉っぽい味もするし……",
          DialogueId = 90160401,
          GUID = "E1B504CA",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160403,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Give"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_1"
        },
        [90160403] = {
          ContentJP = "（身を翻して逃げ出す）",
          DialogueId = 90160403,
          GUID = "E1B5051E",
          NextDialogue = 90160404,
          SpeakNpcId = 100001
        },
        [90160404] = {
          ContentJP = "逃げるなって。役立つサバイバルの知恵だってのに……荒野で迷って食料がなくなったら、こいつらは大切なエネルギー源だぞ。",
          DialogueId = 90160404,
          GUID = "E1B50548",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_04_2",
          bForbidSkipOptions = true
        },
        [90160501] = {
          ContentJP = "だな……っておい、どうしてこれっぽっちしか持ってないんだ。まさかまた自分の報酬を他人にやったのか？",
          DialogueId = 90160501,
          GUID = "E1B51532",
          LookAt = {
            [1] = "85102:n(0)",
            [2] = "0:n(85102)"
          },
          NextDialogue = 90160503,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_1"
        },
        [90160503] = {
          ContentJP = "{性别:あの人たちの方が僕よりおカネが必要みたいだったから。|あの人たちの方が私よりおカネが必要みたいだったから。}",
          DialogueId = 90160503,
          GUID = "E1B51586",
          NextDialogue = 90160504,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "85102:Confident_End"
          }
        },
        [90160504] = {
          ContentJP = "お前ってやつは……はぁ……まあいい、これもお前の長所だろうしな。カネに困ったら俺に言えよ。",
          DialogueId = 90160504,
          GUID = "E1B515B0",
          NextDialogue = 90160505,
          SpeakNpcId = 85102,
          TalkActionId = {
            [1] = "85102:Agree"
          },
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_2"
        },
        [90160505] = {
          ContentJP = "じゃあ、いま、おカネに困ってます！",
          DialogueId = 90160505,
          GUID = "E1B515DA",
          NextDialogue = 90160506,
          SpeakNpcId = 100001
        },
        [90160506] = {
          ContentJP = "……友人としてお前のことを心配してんだぞ！何を図々しく調子に乗ってんだ",
          DialogueId = 90160506,
          GUID = "E1B51604",
          NextOptions = {
            [1] = 90160002,
            [2] = 90160003
          },
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90160601] = {
          Content = "你怎么也在这儿？身体不要紧吗，病没问题吗，饭吃过了吗？哎……有什么想要的给我说就好，没事还是不要瞎跑了。",
          DialogueId = 90160601,
          GUID = "E1B5259A",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_01"
        },
        [90160701] = {
          ContentJP = "おっ、あいつと仲のいい嬢ちゃんじゃないか……体がそんなに強くないって聞いたぜ？座って楽にしてくれよ。",
          DialogueId = 90160701,
          GUID = "E1B53602",
          NextDialogue = 90160702,
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_1"
        },
        [90160702] = {
          ContentJP = "遠慮なんてすんなよ。病弱な妹と暮らしてるからな、世話焼きには慣れてんのさ……もし腹が減ったり喉が渇いたりしたらなんでも言ってくれ。あいつの友達ってことは、俺の友達でもあるんだぞ？",
          DialogueId = 90160702,
          GUID = "E1B5362C",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_02_2"
        },
        [90160801] = {
          ContentJP = "よぉ女将さんじゃないか。なんであんたがここに……なんか緊急の依頼か？あいつはこの間の疲れが残ってんだ、少しは休ませてくれよ……",
          DialogueId = 90160801,
          GUID = "E1B5466A",
          NextDialogue = 90160802,
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_03_1"
        },
        [90160802] = {
          ContentJP = "あ、だが報酬の割がいいってんなら話は別だ。まずは話を聞かせてくれ",
          DialogueId = 90160802,
          GUID = "E1B54694",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_03_2"
        },
        [90160901] = {
          ContentJP = "俺の小さい頃、覚えてるか？あんたは俺にとって優しい姉貴であり、厳しい親父でもあった……ああいや、老けてて暴力的だなんて言ってないぜ。ただ……あの頃の俺に居場所を与えてくれたこと、礼を言いたいだけだ。",
          DialogueId = 90160901,
          GUID = "E1B556D2",
          SpeakNpcId = 85102,
          VoiceName = "voice/$Locale$/char/Aote/vo_companio_04"
        },
        [90170000] = {
          ContentJP = "んん～天気いいねぇ。花を摘んだりするのにはピッタリな日和！体もいい香りになるしね！ねえねえ、{nickname}、一緒にお出かけでもしない？",
          DialogueId = 90170000,
          GUID = "E1BB2BC9",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_idle"
        },
        [90170001] = {
          ContentJP = "ここに来たついでに君ん家の前を雪かきしといてあげたよ！これにはもう、スーパー感謝でしょ？私にあったかココアをご馳走したくなったりした？",
          DialogueId = 90170001,
          GUID = "E1BB2BCA",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextOptions = {
            [1] = 901700011,
            [2] = 901700012,
            [3] = 901700013,
            [4] = 901700014,
            [5] = 901700015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90170002] = {
          ContentJP = "別の話にしようか。",
          DialogueId = 90170002,
          GUID = "90170002.0",
          NextDialogue = 90170001
        },
        [90170003] = {
          ContentJP = "それじゃあ、また。",
          DialogueId = 90170003,
          GUID = "90170003.0"
        },
        [90170101] = {
          ContentJP = "んーっとね……ポイされた子たちに次のご主人様を見つけてあげる仕事かな。あと物資不足で困ってる人たちの生活を、少しはマシにしてあげられるよ。",
          DialogueId = 90170101,
          GUID = "E1BB3C32",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170103,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_1"
        },
        [90170103] = {
          ContentJP = "具体的にどんなことをしているの？",
          DialogueId = 90170103,
          GUID = "E1BB3C86",
          NextDialogue = 90170104,
          SpeakNpcId = 100001
        },
        [90170104] = {
          ContentJP = "例えば、貴族のおじさまが手放したベルベットのカーテンを冬服に仕立てれば、お年寄りが暖かく過ごせるし。捨てられちゃった人形は、石とかでしか遊べない子供たちに渡すとハッピーにできるね。",
          DialogueId = 90170104,
          GUID = "E1BB3CB0",
          NextDialogue = 90170105,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_2"
        },
        [90170105] = {
          ContentJP = "誰が捨てたかもわかんないボロい本棚を運んでさ、へばって休んでたんだ。そしたらさ、猫のお母さんが子猫を連れてきてね？その子たち本棚に飛び乗ったり、飛び降りたり、月が沈んで太陽が昇るまでずーっと遊んでたよ。",
          DialogueId = 90170105,
          GUID = "E1BB3CDA",
          NextDialogue = 90170106,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_3"
        },
        [90170106] = {
          ContentJP = "ゴミ拾いの仕事ってそんな感じ！こまごました仕事ばかりだけどさ、絶対に退屈はしない！どうよどうよ？君も私たちのフォロワーになっちゃう？",
          DialogueId = 90170106,
          GUID = "E1BB3D04",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Agree"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90170201] = {
          ContentJP = "おぉぉう、声が大きい！これはゴミ拾いにとってのトップシークレットでありますから……泥棒を捕まえてくれた君にだけ、特別に教えてあげる。",
          DialogueId = 90170201,
          GUID = "E1BB4C9A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170203,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_1"
        },
        [90170203] = {
          ContentJP = "ま、よーするにアイスレイク城のゴミ箱マップなんだけど。上物が拾える場所にマーク付けといたから。それに、そこのゴミ箱を大きいサイズに変えたりとか、「入荷」はいつになるかとかも計算してあるのだーー！",
          DialogueId = 90170203,
          GUID = "E1BB4CEE",
          NextDialogue = 90170204,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Give"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_2"
        },
        [90170204] = {
          ContentJP = "まあこの業界は大豊作が毎回起きるわけじゃないから。どれぐらいゲットできるかは、結局運任せになっちゃうんだけどね……",
          DialogueId = 90170204,
          GUID = "E1BB4D18",
          NextDialogue = 90170205,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_3"
        },
        [90170205] = {
          ContentJP = "ゴミ拾いも大変なんだね……",
          DialogueId = 90170205,
          GUID = "E1BB4D42",
          NextDialogue = 90170206,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Sigh_End"
          }
        },
        [90170206] = {
          ContentJP = "ザッツライト！その通り！いやぁ、やっぱ君は分かってくれる人だね！",
          DialogueId = 90170206,
          GUID = "E1BB4D6C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_02_4",
          bForbidSkipOptions = true
        },
        [90170301] = {
          ContentJP = "ノーノー、私はアイスレイク城が大好きだよ！雪原を見て思い出してるだけ。お父さんと一緒にさまよい歩いた日々とかさ、雪原で子供時代を過ごしてたから。",
          DialogueId = 90170301,
          GUID = "E1BB5D02",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170303,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_1"
        },
        [90170303] = {
          ContentJP = "そんな風に過ごした時間をどう思う？",
          DialogueId = 90170303,
          GUID = "E1BB5D56",
          NextDialogue = 90170304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Agree"
          }
        },
        [90170304] = {
          ContentJP = "ここから眺める雪原は、メルヘンストーリーに出てくる雪の国みたいにきれいだよね。でもさ……一歩、また一歩と踏み込むと、ほんと自分がちっぽけに感じるんだよ。膝まで積もった雪の中を歩けど歩けど景色はずっと変わらないまま。",
          DialogueId = 90170304,
          GUID = "E1BB5D80",
          NextDialogue = 90170305,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_2"
        },
        [90170305] = {
          ContentJP = "あの頃も嫌いじゃないけど、でもやっぱり私は、賑やかでいい感じに栄えてるアイスレイク城が大好きなんだ！",
          DialogueId = 90170305,
          GUID = "E1BB5DAA",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_03_3",
          bForbidSkipOptions = true
        },
        [90170401] = {
          ContentJP = "子供の頃、一緒に雪原をさまよい歩いてくれた猫ちゃんだよ。名前は「まんまるニャーゴ」！干し肉をあげないとなでさせてくれないんだけど。あの手触りったら——んぬふふふふぅ、頭がオーバーロードしちゃうね！",
          DialogueId = 90170401,
          GUID = "E1BB6D6A",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170403,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_1"
        },
        [90170403] = {
          ContentJP = "雪原の猫ってどんな風に鳴くのかな？虎っぽいかんじ？",
          DialogueId = 90170403,
          GUID = "E1BB6DBE",
          NextDialogue = 90170404,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Explain02_End"
          }
        },
        [90170404] = {
          ContentJP = "うーんと……ニャーニャーじゃないね。……ガォ、ガゥ、ガォオン！って感じ！",
          DialogueId = 90170404,
          GUID = "E1BB6DE8",
          NextDialogue = 90170405,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_2"
        },
        [90170405] = {
          ContentJP = "いまでも会ったりしてるの？",
          DialogueId = 90170405,
          GUID = "E1BB6E12",
          NextDialogue = 90170406,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83301:Think_End"
          }
        },
        [90170406] = {
          ContentJP = "まんまるニャーゴは雪原に生きる獣だから、街には近づきたがらない。だからお別れするしかなかったけど……あの子はずっと私の記憶のなかにいるんだ。あの雪原の景色と一緒にさ。",
          DialogueId = 90170406,
          GUID = "E1BB6E3C",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_04_3",
          bForbidSkipOptions = true
        },
        [90170501] = {
          ContentJP = "違うし、私じゃないし、そんなんじゃないし、姫様なんて子供が喜ぶような呼び方されるわけないし！ギブです、ギブするので、もうその話はなしで……！",
          DialogueId = 90170501,
          GUID = "E1BB7DD2",
          LookAt = {
            [1] = "83301:n(0)",
            [2] = "0:n(83301)"
          },
          NextDialogue = 90170503,
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_1"
        },
        [90170503] = {
          ContentJP = "ならマギーはみんなにどう呼ばれたいの？",
          DialogueId = 90170503,
          GUID = "E1BB7E26",
          NextDialogue = 90170504,
          SpeakNpcId = 100001
        },
        [90170504] = {
          ContentJP = "そりゃもちろん——ゴホン、街の闇に潜み、独り暗躍する、人呼んで物言わぬ探偵…… それこそがLadyマギー！今日もアイスレイク城の知られざるシークレットを、彼女は丸っと解き明かしていく！",
          DialogueId = 90170504,
          GUID = "E1BB7E50",
          NextDialogue = 90170505,
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Confident_Start"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_2"
        },
        [90170505] = {
          ContentJP = "ふぁふぁふぁ、これこそ私にふさわしい通り名だもんね！",
          DialogueId = 90170505,
          GUID = "E1BB7E7A",
          NextOptions = {
            [1] = 90170002,
            [2] = 90170003
          },
          SpeakNpcId = 83301,
          TalkActionId = {
            [1] = "83301:Confident_End"
          },
          VoiceName = "voice/$Locale$/char/Maer/vo_topic_05_3",
          bForbidSkipOptions = true
        },
        [90170601] = {
          ContentJP = "この生地、この紋章、この革！ヒルダお姉さま、もしやあなたはマジの神様なのでしょうか！？このような「イケナイモノ」を「適切に処理」するご用向きの際は、ぜひとも私をお呼びくださいませ！安心安全きれいさっぱり処理することをお約束しますので！",
          DialogueId = 90170601,
          GUID = "E1BB8E3A",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_01"
        },
        [90170701] = {
          ContentJP = "フィーナちゃん、おひさ～！んっ？『雪ネコ冒険者と茶トラ探偵』の続きを聞きたいって？オーケー、椅子を持ってくるから待ってて！座ってゆっくりとお話して進ぜよう！",
          DialogueId = 90170701,
          GUID = "E1BB9EA2",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_02"
        },
        [90170801] = {
          ContentJP = "典獄様、私は根っからの善良な市民でございます！空腹を満たすべくゴミ箱から少～しばかし食べ残しなどをちょうだいしているだけで、盗んだり奪ったりはしておりません！いくら仕事熱心な典獄様でも、ゴミ箱は管轄外だと思いますです、はい。",
          DialogueId = 90170801,
          GUID = "E1BBAF0A",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_03"
        },
        [90170901] = {
          ContentJP = "リーンさんの暮らしぶりってすごく……大変そう。私と一緒にゴミ拾いしよっか？少しは生活に余裕が出るかもだよ？",
          DialogueId = 90170901,
          GUID = "E1BBBF72",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_04"
        },
        [90171001] = {
          ContentJP = "超絶、アルティメット、ベストにトップで優しくお美しいカミラお姉さま。実は少しばかりトラブルが発生しちゃって、ちょびっと助けて欲しいんだけど――今回で絶対に最後！えっと「今月は」最後ね！でもきっと助けてくれるよね！信じてます！そうだよね？",
          DialogueId = 90171001,
          GUID = "E1BBCFDA",
          SpeakNpcId = 83301,
          VoiceName = "voice/$Locale$/char/Maer/vo_companio_05"
        },
        [90180000] = {
          ContentJP = "イェール：ぬ、ぬき、にき、くい、釘、引きにき、引きぬきにき、釘、釘にきで、くきで……",
          DialogueId = 90180000,
          GUID = "E1C19467",
          NextDialogue = 90180002,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_1"
        },
        [90180001] = {
          ContentJP = "イェール：いらっしゃい……お天気、いいですね…… はい、爆発実験に向いてる……本当に、いいお天気です。",
          DialogueId = 90180001,
          GUID = "E1C1946A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextOptions = {
            [1] = 901800011,
            [2] = 901800012,
            [3] = 901800013,
            [4] = 901800014
          },
          RandomOptionNum = 3,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Agree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_welcome",
          bForbidSkipOptions = true
        },
        [90180002] = {
          ContentJP = "オリバー：「ぬきにくい釘、引きぬきにくい釘、釘ぬきでぬく釘」だ！おら俺に続いて言ってみろ、バカイェール！",
          DialogueId = 90180002,
          GUID = "E1C19468",
          NextDialogue = 90180003,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_2"
        },
        [90180003] = {
          ContentJP = "イェール：は、はいぃ！ぬ、抜き、にき……",
          DialogueId = 90180003,
          GUID = "E1C19469",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_idle_3"
        },
        [90180004] = {
          ContentJP = "別の話にしようか。",
          DialogueId = 90180004,
          GUID = "90180004.0",
          NextDialogue = 90180001
        },
        [90180005] = {
          ContentJP = "それじゃあ、また。",
          DialogueId = 90180005,
          GUID = "90180005.0"
        },
        [90180101] = {
          ContentJP = "イェール：オリバーは、しゃべる爆弾ではないです……信じられないかもですが……彼は、実は……",
          DialogueId = 90180101,
          GUID = "E1C1A4D2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180103,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_1"
        },
        [90180103] = {
          ContentJP = "オリバー：黙れっつーのイラつかせんじゃねぇ！俺はイェールでイェールは俺ってだけだ。わかったか？まぁわかんなくても別にどーでもいいがな。けし粒みてぇなおめぇの脳ミソの理解力になんざ期待しちゃいねぇし。",
          DialogueId = 90180103,
          GUID = "E1C1A526",
          NextDialogue = 90180104,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Angry01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_2"
        },
        [90180104] = {
          ContentJP = "生意気な爆弾は、さっさと捨ててしまおう。",
          DialogueId = 90180104,
          GUID = "E1C1A550",
          NextDialogue = 90180105,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83103:Angry01_End"
          }
        },
        [90180105] = {
          ContentJP = "イェール：か、彼は、オリバーは、い、い、いい子なんですよ！ぶっきらぼうで、話し方も、まあ、キツい感じで……いきなり現れる時も、ありますが……でも……",
          DialogueId = 90180105,
          GUID = "E1C1A57A",
          NextDialogue = 90180106,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_3"
        },
        [90180106] = {
          ContentJP = "オリバー：おい、おめぇそれ褒めてんのか？",
          DialogueId = 90180106,
          GUID = "E1C1A5A4",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_01_4",
          bForbidSkipOptions = true
        },
        [90180201] = {
          ContentJP = "イェール：僕は……お役には、立てないかもです。唯一の特技は、この……「キュートちゃん」を作ることだけかも……？",
          DialogueId = 90180201,
          GUID = "E1C1B53A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180203,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_1"
        },
        [90180203] = {
          ContentJP = "えーと、「キュートちゃん」って？",
          DialogueId = 90180203,
          GUID = "E1C1B58E",
          NextDialogue = 90180204,
          SpeakNpcId = 100001
        },
        [90180204] = {
          ContentJP = "イェール：「キュートちゃん」は……オモチャ屋「ドンパチ」の……一番の人気商品です。作るのには、すごく時間がかかります。",
          DialogueId = 90180204,
          GUID = "E1C1B5B8",
          NextDialogue = 90180205,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_2"
        },
        [90180205] = {
          ContentJP = "イェール：でも、僕の技術力が優れてるとかじゃなくて……オリバーがただ、慣れてるだけなんです。",
          DialogueId = 90180205,
          GUID = "E1C1B5E2",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_02_3",
          bForbidSkipOptions = true
        },
        [90180301] = {
          ContentJP = "イェール：あ、あ、すみません！で、でも、速くしゃべろうとすると、舌が、回らなくなってしまって。",
          DialogueId = 90180301,
          GUID = "E1C1C5A2",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180303,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Sigh_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_1"
        },
        [90180303] = {
          ContentJP = "それでも頑張ってほかの人と話しているんだね。",
          DialogueId = 90180303,
          GUID = "E1C1C5F6",
          NextDialogue = 90180304,
          SpeakNpcId = 100001,
          TalkActionId = {
            [1] = "83103:Sigh_End"
          }
        },
        [90180304] = {
          ContentJP = "イェール：ま、まあ、はい。時々オリバーが、代わりに話してくれます……僕の言いたいことは、隣に誰もいない時、オリバーが全部聞いてくれます。",
          DialogueId = 90180304,
          GUID = "E1C1C620",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_03_2",
          bForbidSkipOptions = true
        },
        [90180401] = {
          ContentJP = "イェール：僕には「子供の頃」が、ありません……気がついたら、この身体の中にいたので。オリバーなら、「子供の頃」が、あるかもです。",
          DialogueId = 90180401,
          GUID = "E1C1D60A",
          LookAt = {
            [1] = "83103:n(0)",
            [2] = "0:n(83103)"
          },
          NextDialogue = 90180403,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_1"
        },
        [90180403] = {
          ContentJP = "思い出が少ないのは悲しいね。",
          DialogueId = 90180403,
          GUID = "E1C1D65E",
          NextDialogue = 90180404,
          SpeakNpcId = 100001
        },
        [90180404] = {
          ContentJP = "イェール：考えたことはあります。もし「子供の頃」があれば……どんな感じかなって。ジョーンズ先生が、普通のお父さんのように……毎晩寝る前に、ベッドの横に座って……物語を、聞かせてくれたら……",
          DialogueId = 90180404,
          GUID = "E1C1D688",
          NextDialogue = 90180405,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_2"
        },
        [90180405] = {
          ContentJP = "オリバー：あのジョーンズの野郎から物語を聞くだって？おめぇん頭んなかは花畑かよ？",
          DialogueId = 90180405,
          GUID = "E1C1D6B2",
          NextDialogue = 90180406,
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_3"
        },
        [90180406] = {
          ContentJP = "イェール：ご、ごご、ごめん、なさい！わ、わかってるから！彼の興味があるのは実験だけで、物語なんて、聞かせる気ないってことは……",
          DialogueId = 90180406,
          GUID = "E1C1D6DC",
          NextOptions = {
            [1] = 90180004,
            [2] = 90180005
          },
          SpeakNpcId = 83103,
          TalkActionId = {
            [1] = "83103:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Yeer/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90180501] = {
          ContentJP = "イェール：こ、こんにちは……君の歌声、本当にと、とても、とても美しいです。",
          DialogueId = 90180501,
          GUID = "E1C1E672",
          NextDialogue = 90180502,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_1"
        },
        [90180502] = {
          ContentJP = "オリバー：ふん、哀れな虫のもう1匹か。",
          DialogueId = 90180502,
          GUID = "E1C1E69C",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_01_2"
        },
        [90180601] = {
          ContentJP = "イェール：ヘーゼルナッツは……君の、友達ですか？僕にも、友達がいます、仲のいい。彼はヘ、ヘーゼルナッツのように、信頼できます。",
          DialogueId = 90180601,
          GUID = "E1C1F6DA",
          NextDialogue = 90180602,
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_1"
        },
        [90180602] = {
          ContentJP = "オリバー：俺のことブタと同じって言いたいのか？",
          DialogueId = 90180602,
          GUID = "E1C1F704",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_02_2"
        },
        [90180701] = {
          ContentJP = "イェール：あぅ……お、お、怒らないで。僕の、爆弾の実験は、せせ、セキュリティ基準を、ぜんぶ、み、満たしてますから……",
          DialogueId = 90180701,
          GUID = "E1C20742",
          SpeakNpcId = 83103,
          VoiceName = "voice/$Locale$/char/Yeer/vo_companio_03"
        },
        [90190000] = {
          ContentJP = "怪我人のうめき声も、急な戦況報告もない、これほど安らかなひと時はいつぶりか……コーヒーを淹れて、あの小説を最後まで読んでしまいましょう。お姫様は結局、誰と結ばれたのかしら……",
          DialogueId = 90190000,
          GUID = "E1C7FD09",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_idle"
        },
        [90190001] = {
          ContentJP = "今日もお元気そうでホッとしました。お体にはくれぐれも気をつけてください……いずれ訪れる平和のためにも。",
          DialogueId = 90190001,
          GUID = "E1C7FD0A",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextOptions = {
            [1] = 901900011,
            [2] = 901900012,
            [3] = 901900013,
            [4] = 901900014,
            [5] = 901900015
          },
          RandomOptionNum = 3,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_welcome",
          bForbidSkipOptions = true
        },
        [90190002] = {
          ContentJP = "別の話にしようか。",
          DialogueId = 90190002,
          GUID = "90190002.0",
          NextDialogue = 90190001
        },
        [90190003] = {
          ContentJP = "それじゃあ、また。",
          DialogueId = 90190003,
          GUID = "90190003.0"
        },
        [90190101] = {
          ContentJP = "そうですね……特に趣味と呼べるようなものはありません。強いて言えば、読書でしょうか。",
          DialogueId = 90190101,
          GUID = "E1C80D72",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190102,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_1"
        },
        [90190102] = {
          ContentJP = "舞踏会や社交の席にほとんど参加せず、家に閉じこもってばかりだったので……お偉いさまに取り入る機会を無駄にしたと、母に口うるさく言われたものです……",
          DialogueId = 90190102,
          GUID = "E1C80D9C",
          NextDialogue = 90190103,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_2"
        },
        [90190103] = {
          ContentJP = "ですが、私は今の生活に十分満足しています。",
          DialogueId = 90190103,
          GUID = "E1C80DC6",
          NextDialogue = 90190104,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_3"
        },
        [90190104] = {
          ContentJP = "最近はどんな本を読んでいるの？",
          DialogueId = 90190104,
          GUID = "E1C80DF0",
          NextDialogue = 90190105,
          SpeakNpcId = 100001
        },
        [90190105] = {
          ContentJP = "ほとんど戦場での応急処置に関するものですね。例えば、『戦場救援マニュアル』、『一般的な外傷の手当て』、『野戦臨時病院の構造』ってところでしょうか……",
          DialogueId = 90190105,
          GUID = "E1C80E1A",
          NextDialogue = 90190106,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_4"
        },
        [90190106] = {
          ContentJP = "ご存知のように、私がこれまで学んできた内容は人の救助とは全く無関係の知識でした。医務官の資格を取得した今でも、時々プレッシャーと不安を感じてしまうんです。",
          DialogueId = 90190106,
          GUID = "E1C80E44",
          NextDialogue = 90190107,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_5"
        },
        [90190107] = {
          ContentJP = "そんなに緊張しないで、リラックスした方がいいよ。",
          DialogueId = 90190107,
          GUID = "E1C80E6E",
          NextDialogue = 90190108,
          SpeakNpcId = 100001
        },
        [90190108] = {
          ContentJP = "ええ、最近『ガラスの靴』という本を読んだんです。ええと……その、お姫様と騎士の……物語です。べ、べつに恋愛小説が好きなわけではありません！ただ、少し……内容が気になっただけで……",
          DialogueId = 90190108,
          GUID = "E1C80E98",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_01_6",
          bForbidSkipOptions = true
        },
        [90190201] = {
          ContentJP = "もちろんです！錬金術とは、ヒュペリアの土台であり、学者たちの間では「始まりの奇跡」と呼ばれています！",
          DialogueId = 90190201,
          GUID = "E1C81DDA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190202,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_1"
        },
        [90190202] = {
          ContentJP = "当初、人々は月ノ石から金を分離しようとしていました。しかし、のちにこの小さな石に潜む無数の可能性を発見したのです――それは機械の歯車を回し、電気の火花を散らす……ソラ族でいう「魔法」です。",
          DialogueId = 90190202,
          GUID = "E1C81E04",
          NextDialogue = 90190203,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain01_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_2"
        },
        [90190203] = {
          ContentJP = "……ただその後、錬金院は……",
          DialogueId = 90190203,
          GUID = "E1C81E2E",
          NextDialogue = 90190204,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain01_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_3"
        },
        [90190204] = {
          ContentJP = "確か、錬金院にいたよね？",
          DialogueId = 90190204,
          GUID = "E1C81E58",
          NextDialogue = 90190205,
          SpeakNpcId = 100001
        },
        [90190205] = {
          ContentJP = "……ええ。ですが、もう昔のことです。",
          DialogueId = 90190205,
          GUID = "E1C81E82",
          NextDialogue = 90190206,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_4"
        },
        [90190206] = {
          ContentJP = "なぜ錬金院を離れたの？",
          DialogueId = 90190206,
          GUID = "E1C81EAC",
          NextDialogue = 90190207,
          SpeakNpcId = 100001
        },
        [90190207] = {
          ContentJP = "サーベル錬金院が本来の軌道から外れ、人の道を誤ったからです。錬金院はヒュペリアという戦車におけるエンジンでした。ですが、その燃料は人々の苦しみと不幸から搾られたものだったんです。",
          DialogueId = 90190207,
          GUID = "E1C81ED6",
          NextDialogue = 90190208,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Talk02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_5"
        },
        [90190208] = {
          ContentJP = "私は自分が思っていたより弱い人だったんだと思います。それを受け入れる覚悟も、止める勇気や力もなく、ただ逃げるという選択しかできませんでした。",
          DialogueId = 90190208,
          GUID = "E1C81F00",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Talk02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_02_6",
          bForbidSkipOptions = true
        },
        [90190301] = {
          ContentJP = "緊急用の機械と薬品です。包帯、消毒液、麻酔剤、そして外傷を処理するメスと縫い糸を常に持ち歩くようにしているんです。",
          DialogueId = 90190301,
          GUID = "E1C82E42",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190302,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_1"
        },
        [90190302] = {
          ContentJP = "あとは、ハンカチとくしですかね。",
          DialogueId = 90190302,
          GUID = "E1C82E6C",
          NextDialogue = 90190303,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Think_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_2"
        },
        [90190303] = {
          ContentJP = "戦場でも身だしなみに気をつかってるんだね。",
          DialogueId = 90190303,
          GUID = "E1C82E96",
          NextDialogue = 90190304,
          SpeakNpcId = 100001
        },
        [90190304] = {
          ContentJP = "あ、いえ……これは私が使うのではありません。負傷者さんが不運にも命を落とした時、簡単に身だしなみを整えるために使うものなんです。",
          DialogueId = 90190304,
          GUID = "E1C82EC0",
          NextDialogue = 90190305,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_3"
        },
        [90190305] = {
          ContentJP = "痛みとは残酷なものです。それは命だけでなく、人間としての尊厳をすべて奪われてしまうのですから。",
          DialogueId = 90190305,
          GUID = "E1C82EEA",
          NextDialogue = 90190306,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_4"
        },
        [90190306] = {
          ContentJP = "なので……せめて遺族の方たちには、よりキレイで穏やかな姿にして送り返したいんです……痛みで歪んだ無残な姿ではなく、安らかに眠る我が子の顔を見せることが、せめてもの慰めだと思いまして……",
          DialogueId = 90190306,
          GUID = "E1C82F14",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_03_5",
          bForbidSkipOptions = true
        },
        [90190401] = {
          ContentJP = "いえ、全然平気です！……ええと、実は少しだけ……応急処置と看護の知識はバッチリなのですが、体力テストは着いていくので精一杯で……",
          DialogueId = 90190401,
          GUID = "E1C83EAA",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190402,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Disagree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_1"
        },
        [90190402] = {
          ContentJP = "毎日早起きして、自主練をしているのですが、それでもギリギリ合格点しか取れなくて……うっ、笑わないでください！勉強よりも運動のほうがよっぽど大変なんですから。",
          DialogueId = 90190402,
          GUID = "E1C83ED4",
          NextDialogue = 90190403,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_2"
        },
        [90190403] = {
          ContentJP = "早起きして自主練なんて、聞いただけで大変そうだね。",
          DialogueId = 90190403,
          GUID = "E1C83EFE",
          NextDialogue = 90190404,
          SpeakNpcId = 100001
        },
        [90190404] = {
          ContentJP = "はい、確かにとても疲れます。でも、注意力を足元から逸らし、郊外の麦畑や地平線の果てにある小屋を眺めたり、風車の音や牛飼いの笛の音に耳を傾けたりしていると、不思議と気持ちが落ち着くんです。",
          DialogueId = 90190404,
          GUID = "E1C83F28",
          NextDialogue = 90190405,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_3"
        },
        [90190405] = {
          ContentJP = "……私がこうして走っているのは、このありふれた日常を守るためなんだって思えるから。",
          DialogueId = 90190405,
          GUID = "E1C83F52",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_04_4",
          bForbidSkipOptions = true
        },
        [90190501] = {
          ContentJP = "……父との最後の会話は、トランシーバー越しだったんです。その時、父はロンザ要塞にある危険な戦場にいたのに、「心配するな 」って慰めてくれました。",
          DialogueId = 90190501,
          GUID = "E1C84F12",
          LookAt = {
            [1] = "85401:n(0)",
            [2] = "0:n(85401)"
          },
          NextDialogue = 90190502,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_Start"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_1"
        },
        [90190502] = {
          ContentJP = "その後、ときどき深夜にトランシーバーの電源を入れて、父の周波数に合わせていました。トランシーバーの向こうから父の声が聞こえてくるのに期待して――",
          DialogueId = 90190502,
          GUID = "E1C84F3C",
          NextDialogue = 90190503,
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Explain02_End"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_2"
        },
        [90190503] = {
          ContentJP = "ある日の夜、いつものように電源を入れて十数分待った時、急に気付いたんです。彼はもう二度と帰って来ないんだと……",
          DialogueId = 90190503,
          GUID = "E1C84F66",
          NextDialogue = 90190504,
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_3"
        },
        [90190504] = {
          ContentJP = "その、元気出して……",
          DialogueId = 90190504,
          GUID = "E1C84F90",
          NextDialogue = 90190505,
          SpeakNpcId = 100001
        },
        [90190505] = {
          ContentJP = "ええ、心配しないでください。父の分までしっかり生きるって決めたので。ロンザの戦いの犠牲者たちの無念を晴らすまで、歩みを止めるつもりはありません。",
          DialogueId = 90190505,
          GUID = "E1C84FBA",
          NextOptions = {
            [1] = 90190002,
            [2] = 90190003
          },
          SpeakNpcId = 85401,
          TalkActionId = {
            [1] = "85401:Agree"
          },
          VoiceName = "voice/$Locale$/char/Dafu/vo_topic_05_4",
          bForbidSkipOptions = true
        },
        [90190601] = {
          ContentJP = "帝都の図書館で華胥の医学書を読んだことがあります。ヒュペリアの医学論とは少し違いますが、応急処置に応用するには最適な内容でした。ただ、いくつかわからないことがありまして、お聞きしてもいいですか？",
          DialogueId = 90190601,
          GUID = "E1C85F7A",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_01"
        },
        [90190701] = {
          ContentJP = "典獄さん、遅れてやってきた正義は本当に正義と呼べるのでしょうか？",
          DialogueId = 90190701,
          GUID = "E1C86FE2",
          SpeakNpcId = 85401,
          VoiceName = "voice/$Locale$/char/Dafu/vo_companio_02"
        }
      }
    end
  },
  {
