          ImprPlusId = 1003,
          NextDialogue = 51000304
        },
        [510003023] = {
          ContentJP = "（彼女がとても悲しんでいることに気づく）",
          DialogueId = 510003023,
          GUID = "510003023.0",
          ImprPlusId = 1004,
          NextDialogue = 51000305
        },
        [510003051] = {
          ContentJP = "（何か助けられるかもしれない）",
          DialogueId = 510003051,
          GUID = "510003051.0",
          NextDialogue = 510003052
        },
        [510003052] = {
          ContentJP = "（何か助けられるかもしれない）",
          DialogueId = 510003052,
