          GUID = "510073153",
          ImprPlusId = 1004,
          NextDialogue = 51007316
        },
        [510073154] = {
          ContentJP = "報酬をくれるならそれでいい。",
          DialogueId = 510073154,
          GUID = "510073154",
          ImprPlusId = 1001,
          NextDialogue = 51007316
        },
        [510073155] = {
          ContentJP = "よくわかったな。知性にあふれたこのわたしが手伝うよ。研究経費を分けてくれ。",
          DialogueId = 510073155,
          GUID = "510073155",
          ImprPlusId = 1005,
          NextDialogue = 51007316
        },
        [510073156] = {
          ContentJP = "ねえ、あなたが案内してくれない？ひらめきを得るために少し付き合って。酒場の常連の中じゃ、あなたがいちばん飲まないし、いちばん本を読んでそうだもの。",
