          GUID = "7FB1039F",
          NextOptions = {
            [1] = 510073153,
            [2] = 510073154,
            [3] = 510073155
          },
          SpeakNpcId = 700077
        },
        [510073231] = {
          ContentJP = "工法も施設も違うわ。古い区画は石と煉瓦、新しい区画は機械的な仕組みが目立つ…",
          DialogueId = 510073231,
          GUID = "7FB104C5",
          NextDialogue = 510073232,
          SpeakNpcId = 700172
        },
        [510073232] = {
