        [800202021] = {
          ContentJP = "じゃあ、先に休んでくる？",
          DialogueId = 800202021,
          GUID = "800202021.0",
          NextDialogue = 80020203
        },
        [800202022] = {
          ContentJP = "ずいぶん大袈裟だね。",
          DialogueId = 800202022,
          GUID = "800202022.0",
          NextDialogue = 80020204
        },
        [800202091] = {
          ContentJP = "ヒルダって本当にただのメイドなのかな？",
          DialogueId = 800202091,
          GUID = "800202091.0",
          NextDialogue = 80020210
        },
        [800202092] = {
          ContentJP = "危険すぎるよ。",
          DialogueId = 800202092,
          GUID = "800202092.0",
          NextDialogue = 80020211
        },
        [800202161] = {
          ContentJP = "なんだか格好よく聞こえるね。",
          DialogueId = 800202161,
          GUID = "800202161.0",
          NextDialogue = 80020217
        },
        [800202162] = {
          ContentJP = "大変そうだね。",
          DialogueId = 800202162,
          GUID = "800202162.0",
          NextDialogue = 80020218
        },
        [800203021] = {
          ContentJP = "一緒に行ってもいい？",
          DialogueId = 800203021,
          GUID = "800203021.0",
          NextDialogue = 80020303
        },
        [800203022] = {
          ContentJP = "ヒルダでも街をぶらついたりするんだ？",
          DialogueId = 800203022,
          GUID = "800203022.0",
          NextDialogue = 80020304
        },
        [800203121] = {
          ContentJP = "え？本当にそんな効果あるかな？",
          DialogueId = 800203121,
          GUID = "800203121.0",
          NextDialogue = 80020313
        },
        [800203122] = {
          ContentJP = "確かに見栄えがよくなりそう。",
          DialogueId = 800203122,
          GUID = "800203122.0",
          NextDialogue = 80020314
        },
        [800203161] = {
          ContentJP = "王子様？",
          DialogueId = 800203161,
          GUID = "800203161.0",
          NextDialogue = 80020317
        },
        [800204021] = {
          ContentJP = "機嫌が悪そうだけど、花の剪定が嫌いだったり？",
          DialogueId = 800204021,
          GUID = "800204021.0",
          NextDialogue = 80020403
        },
        [800204022] = {
          ContentJP = "メイドらしい仕事だね。",
          DialogueId = 800204022,
          GUID = "800204022.0",
          NextDialogue = 80020404
        },
        [800204091] = {
          ContentJP = "今は何に悩んでいるのかな？",
          DialogueId = 800204091,
          GUID = "800204091.0",
          NextDialogue = 80020410
        },
        [800204092] = {
          ContentJP = "前の同僚について詳しく聞いていい？",
          DialogueId = 800204092,
          GUID = "800204092.0",
          NextDialogue = 80020411
        },
        [800204171] = {
          ContentJP = "気になるなら、直接会いに行ってみたら？",
          DialogueId = 800204171,
          GUID = "800204171.0",
          NextDialogue = 80020418
        },
        [800205011] = {
          ContentJP = "え？ただの偶然だけど。",
          DialogueId = 800205011,
          GUID = "800205011.0",
          NextDialogue = 80020503
        },
        [800205012] = {
          ContentJP = "目立つ髪の色だし、気づかない方が難しいよ。",
          DialogueId = 800205012,
          GUID = "800205012.0",
          NextDialogue = 80020503
        },
        [800205071] = {
          ContentJP = "わだかまりが解けたみたいだね？",
          DialogueId = 800205071,
          GUID = "800205071.0",
          NextDialogue = 80020508
        },
        [800205072] = {
          ContentJP = "心残りとかはない？",
          DialogueId = 800205072,
          GUID = "800205072.0",
          NextDialogue = 80020509
        },
        [800205121] = {
          ContentJP = "私が苦悩している間にも彼女はためらいなく計画を進めていきました。必要ならば私すら排除する冷徹さをもって。",
          DialogueId = 800205121,
          GUID = "C852AD41",
          NextDialogue = 80020513,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_Talk02_Start"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD41"
        },
        [800205141] = {
          ContentJP = "まだ彼女を憎んでいるの？",
          DialogueId = 800205141,
          GUID = "C852AD6C",
          NextDialogue = 800205143
        },
        [800205142] = {
          ContentJP = "まだ彼女を愛しているの？",
          DialogueId = 800205142,
          GUID = "C852AD6D",
          NextDialogue = 800205143
        },
        [800205143] = {
          ContentJP = "率直に申し上げますと、わかり兼ねております。少しの怒り、少しの悔しさ、なのに恋しいとも想う気持ちも混ざっているのです。あなたが仰るような愛や憎しみなど、ふたりの諜報員にとっては贅沢である……といったところでしょうか。",
          DialogueId = 800205143,
          FacialId = {
            [1] = "93102:Unhappy01"
          },
          GUID = "C852AD94",
          NextDialogue = 80020515,
          SpeakNpcId = 93102,
          TalkActionId = {
            [1] = "93102:Sit_DisagreeHead"
          },
          VoiceName = "voice/$Locale$/inv/Xier/005/C852AD94"
        },
        [800205181] = {
          ContentJP = "え？今「感謝する」って言った？",
          DialogueId = 800205181,
          GUID = "800205181.0",
          NextDialogue = 80020522
        },
        [800205182] = {
          ContentJP = "よく聞こえなかったから、もう一度。",
          DialogueId = 800205182,
          GUID = "800205182.0",
          NextDialogue = 80020522
        },
        [800301051] = {
          ContentJP = "こういう時のランディーって本当にブレないね。",
          DialogueId = 800301051,
          GUID = "800301051.0",
          NextDialogue = 80030106
        },
        [800301052] = {
          ContentJP = "いつもサボっている{性别:じゃないか|でしょ}。",
          DialogueId = 800301052,
          GUID = "800301052.0",
          NextDialogue = 80030107
        },
        [800302051] = {
          ContentJP = "休暇のために嘘をつく紳士なんているの？",
          DialogueId = 800302051,
          GUID = "800302051.0",
          NextDialogue = 80030206
        },
        [800302052] = {
          ContentJP = "えーと、うん、素敵{性别:だ|ね}、とても紳士的。",
          DialogueId = 800302052,
          GUID = "800302052.0",
          NextDialogue = 80030207
        },
        [800302091] = {
          ContentJP = "姉たち？きっと上品なレディなんだろうね。",
          DialogueId = 800302091,
          GUID = "800302091.0",
          NextDialogue = 80030210
        },
        [800302092] = {
          ContentJP = "子供の頃のランディーってなんだか想像できない{性别:な|ね}。",
          DialogueId = 800302092,
          GUID = "800302092.0",
          NextDialogue = 80030211
        },
        [800302131] = {
          ContentJP = "「愛」っていいことだよね？",
          DialogueId = 800302131,
          GUID = "800302131.0",
          NextDialogue = 80030214
        },
        [800302132] = {
          ContentJP = "「紳士」と似た皮肉な意味合いの「愛」かな……ご苦労様。",
          DialogueId = 800302132,
          GUID = "800302132.0",
          NextDialogue = 80030215
        },
        [800304031] = {
          ContentJP = "何かトラブルが？いつものランディーらしくない{性别:けど|ね}。",
          DialogueId = 800304031,
          GUID = "800304031.0",
          NextDialogue = 80030404
        },
        [800304032] = {
          ContentJP = "急いでいる様子だけど、ダンスにでも誘われたの？",
          DialogueId = 800304032,
          GUID = "800304032.0",
          NextDialogue = 80030406
        },
        [800304071] = {
          ContentJP = "悪夢？",
          DialogueId = 800304071,
          GUID = "800304071.0",
          NextDialogue = 80030408
        },
        [800304081] = {
          ContentJP = "お父さん……ランディーの口から初めて聞いた。",
          DialogueId = 800304081,
          GUID = "800304081.0",
          NextDialogue = 80030409
        },
        [800304321] = {
          ContentJP = "本当にそう{性别:かな|なの}？",
          DialogueId = 800304321,
          GUID = "800304321.0",
          NextDialogue = 80030433
        },
        [800304351] = {
          ContentJP = "お父さんが目覚めたら、きっと今のランディーを誇りに思ってくれる。",
          DialogueId = 800304351,
          GUID = "800304351.0",
          NextDialogue = 80030436
        },
        [800304352] = {
          ContentJP = "もう一杯入れようか？",
          DialogueId = 800304352,
          GUID = "800304352.0",
          NextDialogue = 80030437
        },
        [800305011] = {
          ContentJP = "ありがとう。機嫌がいい{性别:な|ね}。",
          DialogueId = 800305011,
          GUID = "C8790EF4",
          NextDialogue = 80030502
        },
        [800305012] = {
          ContentJP = "なにか企んで{性别:ない|いるの}？",
          DialogueId = 800305012,
          GUID = "C8790F48",
          NextDialogue = 80030503
        },
        [800305081] = {
          ContentJP = "女性？なら僕に何の用が？",
          DialogueId = 800305081,
          GUID = "C879106E",
          NextDialogue = 80030509,
          TriggerCondition = {
            IsBoy = {}
          }
        },
        [800305082] = {
          ContentJP = "そのために私を誘ったのね……",
          DialogueId = 800305082,
          GUID = "800305082.0",
          NextDialogue = 80030526,
          TriggerCondition = {
            IsGirl = {}
          }
        },
        [800305091] = {
          ContentJP = "そっちが、変装したらいい話じゃない？",
          DialogueId = 800305091,
          GUID = "800305091.0",
          NextDialogue = 80030510
        },
        [800305092] = {
          ContentJP = "？",
          DialogueId = 800305092,
          GUID = "800305092.0",
          NextDialogue = 80030511
        },
        [800305141] = {
          ContentJP = "……兄弟って……えっと兄さん？それってどういう状況で？",
          DialogueId = 800305141,
          GUID = "800305141.0",
          NextDialogue = 80030515
        },
        [800305142] = {
          ContentJP = "もしや自分が着たいだけ？",
          DialogueId = 800305142,
          GUID = "800305142.0",
          NextDialogue = 80030515
        },
        [800305161] = {
          ContentJP = "最後ふたつは普通じゃない気が……",
          DialogueId = 800305161,
          GUID = "800305161.0",
          NextDialogue = 80030517
        },
        [800305171] = {
          ContentJP = "いいよ、仕方ないし。",
          DialogueId = 800305171,
          GUID = "80030571",
          NextDialogue = 80030518
        },
        [800305172] = {
          ContentJP = "ちょっと考えさせて。",
          DialogueId = 800305172,
          GUID = "800305172",
          NextDialogue = 80030523
        },
        [800305261] = {
          ContentJP = "パーティーで私を生け捕りにはしないよね？",
          DialogueId = 800305261,
          GUID = "C87910C2",
          NextDialogue = 80030527
        },
        [800305311] = {
          ContentJP = "もちろん冗談。",
          DialogueId = 800305311,
          GUID = "C87911BE",
          NextDialogue = 80030532
        },
        [800305312] = {
          ContentJP = "その通りじゃない？",
          DialogueId = 800305312,
          GUID = "C8791212",
          NextDialogue = 80030533
        },
        [800305351] = {
          ContentJP = "ごめんなさい。あなたの慌てる様子が面白いだろうなってつい……",
          DialogueId = 800305351,
          GUID = "C87912BA",
          NextDialogue = 80030536
        },
        [800305352] = {
          ContentJP = "いいえ、本当に捕まえるつもりじゃないか心配よ！",
          DialogueId = 800305352,
          GUID = "C8791362",
          NextDialogue = 80030539
        },
        [800305431] = {
          ContentJP = "なら、わかった、いいよ。",
          DialogueId = 800305431,
          GUID = "C879145E",
          NextDialogue = 80030544
        },
        [800701271] = {
          DialogueId = 800701271,
